/**
 * Count KB entries, respecting scope isolation.
 * Falls back to project_id match or total when scoped count is 0.
 * @param projectId - Optional project scope
 * @param userId - Optional user scope
 */
export async function getKbEntryCount(
  projectId?: string,
  userId?: string,
): Promise<number> {
  try {
    if (!(await tableExists())) return 0;
    const adapter = getIndexAdapter();
    const filter = buildAdminScopeFilter(projectId, userId);

    if (filter) {
      const row = await adapter.getAsync<{ cnt: number }>(
        `SELECT COUNT(*) as cnt FROM knowledge_entries WHERE ${filter.clause}`,
        filter.params as unknown[],
      );
      const scopedCount = row?.cnt ?? 0;
      // SA4E-49: Fall back to project_id match when scoped count is 0
      if (scopedCount === 0) return getUnfilteredKbEntryCount(projectId);
      return scopedCount;
    }

    const row = await adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM knowledge_entries',
    );
    return row?.cnt ?? 0;
  } catch (err) {
    logger.error({ err }, 'Error in getKbEntryCount');
    return 0;
  }
}

/**
 * SA4E-49: Fallback count when scope-based filter returns 0.
 * Tries project_id match first, then total count as last resort.
 * Admin views need accurate counts even if scope metadata is incomplete.
 */
async function getUnfilteredKbEntryCount(projectId?: string): Promise<number> {
  const adapter = getIndexAdapter();
  if (projectId) {
    const row = await adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM knowledge_entries WHERE project_id = ? OR project_id IS NULL',
      [projectId],
    );
    if ((row?.cnt ?? 0) > 0) return row!.cnt;
  }
  const row = await adapter.getAsync<{ cnt: number }>(
    'SELECT COUNT(*) as cnt FROM knowledge_entries',
  );
  return row?.cnt ?? 0;
}

/**
 * List KB entries with pagination and sorting.
 * @returns Paginated items array and total count
 */
export async function getKbEntries(
  page = 1,
  pageSize = 20,
  sortBy = 'created_at',
  sortDir: 'asc' | 'desc' = 'desc',
  projectId?: string,
  userId?: string,
): Promise<{ items: any[]; total: number }> {
  try {
    if (!(await tableExists())) return { items: [], total: 0 };
    const adapter = getIndexAdapter();

    // Validate sort column to prevent SQL injection
    const validColumns = ['id', 'created_at', 'updated_at', 'source', 'type',
      'tier', 'quality_score', 'tags', 'summary', 'content'];
    const safeSort = validColumns.includes(sortBy) ? sortBy : 'created_at';
    const safeDir = sortDir === 'asc' ? 'ASC' : 'DESC';

    const filter = buildAdminScopeFilter(projectId, userId);
    return filter
      ? fetchWithFilter(adapter, filter, safeSort, safeDir, page, pageSize)
      : fetchWithoutFilter(adapter, safeSort, safeDir, page, pageSize);
  } catch (err) {
    logger.error({ err }, 'Error in getKbEntries');
    return { items: [], total: 0 };
  }
}

/** Fetch with scope isolation WHERE clause. */
async function fetchWithFilter(
  adapter: DatabaseAdapter,
  filter: { clause: string; params: unknown[] },
  safeSort: string,
  safeDir: string,
  page: number,
  pageSize: number,
): Promise<{ items: any[]; total: number }> {
  const where = `WHERE ${filter.clause}`;
  const countRow = await adapter.getAsync<{ cnt: number }>(
    `SELECT COUNT(*) as cnt FROM knowledge_entries ${where}`,
    filter.params as unknown[],
  );
  const total = countRow?.cnt ?? 0;
  const rows = await adapter.allAsync<Record<string, unknown>>(
    `SELECT * FROM knowledge_entries ${where} ORDER BY ${safeSort} ${safeDir} LIMIT ? OFFSET ?`,
    [...(filter.params as unknown[]), pageSize, (page - 1) * pageSize],
  );
  return { items: rows, total };
}

/** Fetch without scope filter (unscoped admin view). */
async function fetchWithoutFilter(
  adapter: DatabaseAdapter,
  safeSort: string,
  safeDir: string,
  page: number,
  pageSize: number,
): Promise<{ items: any[]; total: number }> {
  const countRow = await adapter.getAsync<{ cnt: number }>(
    'SELECT COUNT(*) as cnt FROM knowledge_entries',
  );
  const total = countRow?.cnt ?? 0;
  const rows = await adapter.allAsync<Record<string, unknown>>(
    `SELECT * FROM knowledge_entries ORDER BY ${safeSort} ${safeDir} LIMIT ? OFFSET ?`,
    [pageSize, (page - 1) * pageSize],
  );
  return { items: rows, total };
}

/**
 * admin/db/kb-search.ts — KB full-text search via DatabaseAdapter.
 * SA4E-50: Uses getIndexAdapter() async methods for PostgreSQL/SQLite support.
 * TF-IDF scoring runs in-memory after DB fetch; compatible with all engines.
 */

import { getIndexAdapter, getActiveEngine, logger } from './core.js';
import { buildAdminScopeFilter } from './kb-scope-filter.js';

/** Check if knowledge_entries table exists (SQLite only guard). */
async function tableExists(): Promise<boolean> {
  const adapter = getIndexAdapter();
  if (!adapter.isConnected()) return false; // PG not yet connected — skip gracefully
  if (getActiveEngine() !== 'sqlite') return true;
  const row = await adapter.getAsync<{ cnt: number }>(
    "SELECT COUNT(*) as cnt FROM sqlite_master WHERE type='table' AND name='knowledge_entries'",
  );
  return (row?.cnt ?? 0) > 0;
}

/** Score fields by LIKE match for each search term. */
function buildLikeClauses(
  queryTerms: string[],
  searchCols: string[],
): { likeClauses: string[]; likeParams: unknown[] } {
  const likeClauses: string[] = [];
  const likeParams: unknown[] = [];
  for (const term of queryTerms) {
    for (const col of searchCols) {
      likeClauses.push(`${col} LIKE ?`);
      likeParams.push(`%${term}%`);
    }
  }
  return { likeClauses, likeParams };
}

/** Compute TF-IDF + bonus score for a single row. */
function scoreRow(
  row: any,
  queryTerms: string[],
  termDocFreq: Record<string, number>,
  totalDocs: number,
  now: number,
): any {
  const fields = {
    content: (row.content || '').toLowerCase(),
    source: (row.source || '').toLowerCase(),
    summary: (row.summary || '').toLowerCase(),
    tags: (row.tags || '').toLowerCase(),
  };
  const fullText = `${fields.content} ${fields.source} ${fields.summary} ${fields.tags}`;
  const totalWords = fullText.split(/\s+/).length || 1;

  let tfidfScore = 0;
  for (const term of queryTerms) {
    const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const occurrences = (fullText.match(new RegExp(escaped, 'gi')) || []).length;
    const tf = occurrences / totalWords;
    const idf = Math.log((totalDocs + 1) / ((termDocFreq[term] || 1) + 1)) + 1;
    tfidfScore += tf * idf;
  }
  const normalizedTfidf = Math.min(tfidfScore * 100, 1.0);

  let keywordBonus = 0;
  for (const term of queryTerms) {
    if (fields.source.includes(term)) keywordBonus += 0.15;
    if (fields.summary.includes(term)) keywordBonus += 0.1;
    if (fields.tags.includes(term)) keywordBonus += 0.05;
  }
  keywordBonus = Math.min(keywordBonus, 0.3);

  const createdAt = row.created_at ? new Date(row.created_at).getTime() : 0;
  const ageDays = (now - createdAt) / (1000 * 60 * 60 * 24);
  const recencyBonus = ageDays <= 7 ? 0.2 : ageDays <= 30 ? 0.1 : 0;

  const qualityRaw = row.quality_score != null ? row.quality_score / 100 : (row.confidence || 0);
  const qualityBonus = qualityRaw * 0.1;

  return {
    ...row,
    score: +Math.min(normalizedTfidf + keywordBonus + recencyBonus + qualityBonus, 1.0).toFixed(3),
    scores: {
      similarity: +normalizedTfidf.toFixed(3),
      keyword: +keywordBonus.toFixed(3),
      recency: +recencyBonus.toFixed(3),
      quality: +qualityBonus.toFixed(3),
    },
  };
}

/**
 * Full-text search KB entries using LIKE + in-memory TF-IDF scoring.
 * @returns Top 50 scored results and total candidate count
 */
export async function searchKbEntries(
  query: string,
  projectId?: string,
  userId?: string,
): Promise<{ items: any[]; total: number }> {
  try {
    if (!(await tableExists())) return { items: [], total: 0 };
    const adapter = getIndexAdapter();

    const queryTerms = query.toLowerCase().split(/\s+/).filter(t => t.length > 1);
    if (queryTerms.length === 0) return { items: [], total: 0 };

    const totalRow = await adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM knowledge_entries',
    );
    const totalDocs = totalRow?.cnt ?? 0;

    const searchCols = ['content', 'source', 'summary', 'tags'];
    const { likeClauses, likeParams } = buildLikeClauses(queryTerms, searchCols);
    const filter = buildAdminScopeFilter(projectId, userId);
    const projectFilter = filter ? ` AND (${filter.clause})` : '';
    const projectParams = filter ? (filter.params as unknown[]) : [];

    const rows = await adapter.allAsync<Record<string, unknown>>(
      `SELECT * FROM knowledge_entries WHERE (${likeClauses.join(' OR ')})${projectFilter} LIMIT 200`,
      [...likeParams, ...projectParams],
    );

    // Compute document frequency per term for IDF calculation
    const termDocFreq: Record<string, number> = {};
    for (const term of queryTerms) {
      termDocFreq[term] = rows.filter(row => {
        const text = `${row.content || ''} ${row.source || ''} ${row.summary || ''} ${row.tags || ''}`.toLowerCase();
        return text.includes(term);
      }).length;
    }

    const now = Date.now();
    const scoredRows = rows.map(row => scoreRow(row, queryTerms, termDocFreq, totalDocs, now));
    scoredRows.sort((a: any, b: any) => b.score - a.score);
    return { items: scoredRows.slice(0, 50), total: scoredRows.length };
  } catch (err) {
    logger.error({ err }, 'Error in searchKbEntries');
    return { items: [], total: 0 };
  }
}

/**
 * admin/db/kb-tags.ts — KB tag management via DatabaseAdapter.
 * SA4E-50: All functions are async; use getIndexAdapter() for multi-DB support.
 */

import { getIndexAdapter, getActiveEngine, logger } from './core.js';
import { buildAdminScopeFilter } from './kb-scope-filter.js';

/** Check if knowledge_entries table exists (SQLite only guard). */
async function tableExists(): Promise<boolean> {
  const adapter = getIndexAdapter();
  if (!adapter.isConnected()) return false; // PG not yet connected — skip gracefully
  if (getActiveEngine() !== 'sqlite') return true;
  const row = await adapter.getAsync<{ cnt: number }>(
    "SELECT COUNT(*) as cnt FROM sqlite_master WHERE type='table' AND name='knowledge_entries'",
  );
  return (row?.cnt ?? 0) > 0;
}

/** Parse comma-separated tags string into a trimmed, non-empty array. */
function parseTags(raw: string): string[] {
  return raw.split(',').map(t => t.trim()).filter(t => t.length > 0);
}

/**
 * Get all tags with usage counts across KB entries.
 * @returns Map of tag name → { count, lastUsed }
 */
export async function getAllKbTags(
  projectId?: string,
  userId?: string,
): Promise<Record<string, { count: number; lastUsed: string }>> {
  const tagCounts: Record<string, { count: number; lastUsed: string }> = {};
  try {
    if (!(await tableExists())) return tagCounts;
    const adapter = getIndexAdapter();
    const filter = buildAdminScopeFilter(projectId, userId);
    let rows: { tags: string; created_at: string }[];

    if (filter) {
      rows = await adapter.allAsync<{ tags: string; created_at: string }>(
        `SELECT tags, created_at FROM knowledge_entries WHERE tags IS NOT NULL AND tags != '' AND (${filter.clause})`,
        filter.params as unknown[],
      );
    } else {
      rows = await adapter.allAsync<{ tags: string; created_at: string }>(
        "SELECT tags, created_at FROM knowledge_entries WHERE tags IS NOT NULL AND tags != ''",
      );
    }

    for (const row of rows) {
      if (!row.tags) continue;
      for (const tag of parseTags(row.tags)) {
        if (!tagCounts[tag]) tagCounts[tag] = { count: 0, lastUsed: row.created_at || new Date().toISOString() };
        tagCounts[tag].count++;
        if (row.created_at && new Date(row.created_at) > new Date(tagCounts[tag].lastUsed)) {
          tagCounts[tag].lastUsed = row.created_at;
        }
      }
    }
  } catch (e) {
    logger.error({ err: e }, 'Error in getAllKbTags');
  }
  return tagCounts;
}

/**
 * Replace all tags on a KB entry.
 * @param entryId - ID of the entry to update
 * @param tags - New tag list
 */
export async function updateKbEntryTags(entryId: string, tags: string[]): Promise<void> {
  try {
    if (!(await tableExists())) return;
    const adapter = getIndexAdapter();
    await adapter.runAsync(
      'UPDATE knowledge_entries SET tags = ? WHERE id = ?',
      [tags.join(','), entryId],
    );
  } catch (e) {
    logger.error({ err: e }, 'Error in updateKbEntryTags');
  }
}

/**
 * Rename a tag across all entries.
 * @returns Number of entries updated
 */
export async function renameKbTag(oldName: string, newName: string): Promise<number> {
  let renamed = 0;
  try {
    if (!(await tableExists())) return 0;
    const adapter = getIndexAdapter();
    const rows = await adapter.allAsync<{ id: string; tags: string }>(
      'SELECT id, tags FROM knowledge_entries WHERE tags LIKE ?',
      [`%${oldName}%`],
    );
    for (const row of rows) {
      if (!row.tags) continue;
      const tagArr = parseTags(row.tags);
      const idx = tagArr.indexOf(oldName);
      if (idx !== -1) {
        tagArr[idx] = newName.trim();
        await adapter.runAsync('UPDATE knowledge_entries SET tags = ? WHERE id = ?', [tagArr.join(','), row.id]);
        renamed++;
      }
    }
  } catch (e) {
    logger.error({ err: e }, 'Error in renameKbTag');
  }
  return renamed;
}

/**
 * Remove a tag from all entries.
 * @returns Number of entries updated
 */
export async function deleteKbTag(tagName: string): Promise<number> {
  let removed = 0;
  try {
    if (!(await tableExists())) return 0;
    const adapter = getIndexAdapter();
    const rows = await adapter.allAsync<{ id: string; tags: string }>(
      'SELECT id, tags FROM knowledge_entries WHERE tags LIKE ?',
      [`%${tagName}%`],
    );
    for (const row of rows) {
      if (!row.tags) continue;
      const tagArr = parseTags(row.tags);
      const idx = tagArr.indexOf(tagName);
      if (idx !== -1) {
        tagArr.splice(idx, 1);
        await adapter.runAsync('UPDATE knowledge_entries SET tags = ? WHERE id = ?', [tagArr.join(','), row.id]);
        removed++;
      }
    }
  } catch (e) {
    logger.error({ err: e }, 'Error in deleteKbTag');
  }
  return removed;
}

/**
 * Merge sourceTag into targetTag across all entries.
 * @returns Number of entries updated
 */
export async function mergeKbTags(sourceTag: string, targetTag: string): Promise<number> {
  let merged = 0;
  try {
    if (!(await tableExists())) return 0;
    const adapter = getIndexAdapter();
    const rows = await adapter.allAsync<{ id: string; tags: string }>(
      'SELECT id, tags FROM knowledge_entries WHERE tags LIKE ?',
      [`%${sourceTag}%`],
    );
    for (const row of rows) {
      if (!row.tags) continue;
      const tagArr = parseTags(row.tags);
      const idx = tagArr.indexOf(sourceTag);
      if (idx !== -1) {
        tagArr.splice(idx, 1);
        if (!tagArr.includes(targetTag)) tagArr.push(targetTag);
        await adapter.runAsync('UPDATE knowledge_entries SET tags = ? WHERE id = ?', [tagArr.join(','), row.id]);
        merged++;
      }
    }
  } catch (e) {
    logger.error({ err: e }, 'Error in mergeKbTags');
  }
  return merged;
}

/**
 * Get all entries with a specific tag.
 * @returns Array of raw entry rows
 */
export async function getKbEntriesByTag(
  tagName: string,
  projectId?: string,
  userId?: string,
): Promise<any[]> {
  try {
    if (!(await tableExists())) return [];
    const adapter = getIndexAdapter();
    const filter = buildAdminScopeFilter(projectId, userId);
    let rows: Record<string, unknown>[];

    if (filter) {
      rows = await adapter.allAsync<Record<string, unknown>>(
        `SELECT * FROM knowledge_entries WHERE tags LIKE ? AND (${filter.clause})`,
        [`%${tagName}%`, ...(filter.params as unknown[])],
      );
    } else {
      rows = await adapter.allAsync<Record<string, unknown>>(
        'SELECT * FROM knowledge_entries WHERE tags LIKE ?',
        [`%${tagName}%`],
      );
    }

    // Filter to exact tag matches (LIKE may include superset tags)
    return rows.filter(row => {
      if (!row.tags) return false;
      return parseTags(row.tags as string).includes(tagName);
    });
  } catch (e) {
    logger.error({ err: e }, 'Error in getKbEntriesByTag');
    return [];
  }
}

/**
 * admin/db/schema.ts — Admin schema initialization and seed data.
 * SA4E-53: Accepts DatabaseAdapter (sync interface) instead of raw better-sqlite3.
