/**
 * admin/db/users.ts — User CRUD operations via DatabaseAdapter async methods.
 * SA4E-50: All functions are async and use getAdminAdapter() so they work with
 * both SQLite (sync-under-the-hood) and PostgreSQL.
 */

import * as crypto from 'crypto';
import type { User, UserStatus } from '../types/rbac.types.js';
import { getAdminAdapter } from './core.js';
import { hashPassword } from './password.js';
import { invalidateUserSessions } from './sessions.js';

/** Build user object from raw DB row. */
function rowToUser(r: Record<string, unknown>): User {
  return {
    userId: r.user_id as string,
    username: r.username as string,
    email: r.email as string,
    status: r.status as UserStatus,
    accessGroupId: r.access_group_id as string,
    forcePasswordChange: !!(r.force_password_change as number),
    createdAt: r.created_at as string,
    lastLogin: (r.last_login as string) || undefined,
  };
}

/**
 * List users with optional filters and pagination.
 * @param filters - Optional status/search/group filters
 * @param page - 1-based page number
 * @param pageSize - Records per page
 */
export async function getUsers(
  filters?: { status?: string; search?: string; accessGroupId?: string },
  page = 1,
  pageSize = 50,
): Promise<{ items: any[]; total: number }> {
  const adapter = getAdminAdapter();
  let where = 'WHERE 1=1';
  const params: unknown[] = [];

  if (filters?.status) { where += ' AND u.status = ?'; params.push(filters.status); }
  if (filters?.accessGroupId) { where += ' AND u.access_group_id = ?'; params.push(filters.accessGroupId); }
  if (filters?.search) {
    where += ' AND (u.username LIKE ? OR u.email LIKE ?)';
    params.push(`%${filters.search}%`, `%${filters.search}%`);
  }

  const countRow = await adapter.getAsync<{ cnt: number }>(
    `SELECT COUNT(*) as cnt FROM users u ${where}`, params,
  );
  const total = countRow?.cnt ?? 0;

  const rows = await adapter.allAsync<Record<string, unknown>>(
    `SELECT u.*, g.access_group_name FROM users u
     LEFT JOIN access_groups g ON u.access_group_id = g.access_group_id
     ${where} ORDER BY u.created_at DESC LIMIT ? OFFSET ?`,
    [...params, pageSize, (page - 1) * pageSize],
  );

  return {
    total,
    items: rows.map(r => ({
      ...rowToUser(r),
      accessGroupName: (r.access_group_name as string) || '',
    })),
  };
}

/**
 * Fetch a single user by ID.
 * @returns User or null if not found
 */
export async function getUserById(userId: string): Promise<User | null> {
  const adapter = getAdminAdapter();
  const r = await adapter.getAsync<Record<string, unknown>>(
    'SELECT * FROM users WHERE user_id = ?', [userId],
  );
  return r ? rowToUser(r) : null;
}

/**
 * Fetch a user with password hash for authentication.
 * @returns User + passwordHash or null
 */
export async function getUserByUsername(
  username: string,
): Promise<(User & { passwordHash: string }) | null> {
  const adapter = getAdminAdapter();
  const r = await adapter.getAsync<Record<string, unknown>>(
    'SELECT * FROM users WHERE username = ?', [username],
  );
  if (!r) return null;
  return { ...rowToUser(r), passwordHash: r.password_hash as string };
}

/**
 * Create a new user with a hashed password.
 * @returns Newly created User object
 */
export async function createUser(
  username: string,
  email: string,
  password: string,
  accessGroupId: string,
): Promise<User> {
  const adapter = getAdminAdapter();
  const userId = 'user-' + crypto.randomUUID().slice(0, 8);
  const now = new Date().toISOString();
  const hash = hashPassword(password);

  await adapter.runAsync(
    `INSERT INTO users (user_id, username, email, password_hash, status, access_group_id, force_password_change, created_at)
     VALUES (?, ?, ?, ?, 'ACTIVE', ?, 1, ?)`,
    [userId, username, email, hash, accessGroupId, now],
  );

  return { userId, username, email, status: 'ACTIVE', accessGroupId, forcePasswordChange: true, createdAt: now };
}

/**
 * Update user status. Invalidates sessions on DISABLED.
 * @returns Number of sessions terminated
 */
export async function updateUserStatus(userId: string, status: UserStatus): Promise<number> {
  const adapter = getAdminAdapter();
  await adapter.runAsync('UPDATE users SET status = ? WHERE user_id = ?', [status, userId]);
  if (status === 'DISABLED') {
    return invalidateUserSessions(userId);
  }
  return 0;
}

/**
 * Delete a user. Cannot delete the system admin.
 * @throws Error if user is admin or not found
 */
export async function deleteUser(userId: string): Promise<void> {
  const adapter = getAdminAdapter();
  const user = await adapter.getAsync<{ username: string }>(
    'SELECT username FROM users WHERE user_id = ?', [userId],
  );
  if (user?.username === 'admin') throw new Error('Cannot delete system admin');
  await invalidateUserSessions(userId);
  await adapter.runAsync('DELETE FROM users WHERE user_id = ?', [userId]);
}

/**
 * Generate a temporary password and force password change on next login.
 * @returns Plain-text temporary password
 */
export async function resetUserPassword(userId: string): Promise<string> {
  const adapter = getAdminAdapter();
  const tempPwd = crypto.randomBytes(6).toString('base64url');
  const hash = hashPassword(tempPwd);
  await adapter.runAsync(
    'UPDATE users SET password_hash = ?, force_password_change = 1 WHERE user_id = ?',
    [hash, userId],
  );
  return tempPwd;
}

/**
 * Change a user's password and clear the force_password_change flag.
 */
export async function changePassword(userId: string, newPassword: string): Promise<void> {
  const adapter = getAdminAdapter();
  const hash = hashPassword(newPassword);
  await adapter.runAsync(
    'UPDATE users SET password_hash = ?, force_password_change = 0 WHERE user_id = ?',
    [hash, userId],
  );
}

/** Record the current timestamp as last_login for a user. */
export async function updateLastLogin(userId: string): Promise<void> {
  const adapter = getAdminAdapter();
  await adapter.runAsync(
    'UPDATE users SET last_login = ? WHERE user_id = ?',
    [new Date().toISOString(), userId],
  );
}

/** Update user email address. */
export async function updateUserEmail(userId: string, email: string): Promise<void> {
  const adapter = getAdminAdapter();
  await adapter.runAsync('UPDATE users SET email = ? WHERE user_id = ?', [email, userId]);
}

/**
 * Update user details (username, email, access_group_id).
 * @throws Error if username conflicts or group doesn't exist
 */
export async function updateUser(
  userId: string,
  updates: { username?: string; email?: string; accessGroupId?: string }
): Promise<User> {
  const adapter = getAdminAdapter();

  // Validate username uniqueness if changing
  if (updates.username) {
    const existing = await adapter.getAsync<{ user_id: string }>(
      'SELECT user_id FROM users WHERE username = ? AND user_id != ?',
      [updates.username, userId],
    );
    if (existing) throw new Error('Username already exists');
  }

  // Validate group exists if changing
  if (updates.accessGroupId) {
    const group = await adapter.getAsync<{ access_group_id: string }>(
      'SELECT access_group_id FROM access_groups WHERE access_group_id = ?',
      [updates.accessGroupId],
    );
    if (!group) throw new Error('Access group not found');
  }

  const fields: string[] = [];
  const params: unknown[] = [];

  if (updates.username) { fields.push('username = ?'); params.push(updates.username); }
  if (updates.email !== undefined) { fields.push('email = ?'); params.push(updates.email); }
  if (updates.accessGroupId) { fields.push('access_group_id = ?'); params.push(updates.accessGroupId); }

  if (fields.length === 0) throw new Error('No updates provided');

  params.push(userId);
  await adapter.runAsync(`UPDATE users SET ${fields.join(', ')} WHERE user_id = ?`, params);

  const updated = await getUserById(userId);
  if (!updated) throw new Error('User not found after update');
  return updated;
}

/** Count total active users (used by dashboard stats). */
export async function getUserCount(): Promise<number> {
  const adapter = getAdminAdapter();
  const row = await adapter.getAsync<{ cnt: number }>(
    "SELECT COUNT(*) as cnt FROM users WHERE status = 'ACTIVE'",
  );
  return row?.cnt ?? 0;
}

/** Count users belonging to a specific access group. */
export async function getUserCountByGroup(groupId: string): Promise<number> {
  const adapter = getAdminAdapter();
  const row = await adapter.getAsync<{ cnt: number }>(
    'SELECT COUNT(*) as cnt FROM users WHERE access_group_id = ?', [groupId],
  );
  return row?.cnt ?? 0;
}

// KSA-286: Admin Portal Module Entry Point

import { Express, Router, json } from 'express';
import path from 'path';
import { createRBACMiddleware } from './middleware/rbac.middleware.js';
import { createAuditMiddleware } from './middleware/audit.middleware.js';
import { rateLimitMiddleware } from './middleware/rate-limit.middleware.js';
import { dashboardRouter } from './routes/dashboard.router.js';
import { kbAdminRouter } from './routes/kb-admin.router.js';
import { mcpAdminRouter } from './routes/mcp-admin.router.js';
import { userRouter } from './routes/user.router.js';
import { rbacRouter } from './routes/rbac.router.js';
import { configRouter } from './routes/config.router.js';
import { auditRouter } from './routes/audit.router.js';

export interface AdminModuleDependencies {
  db: any;
  jwtService: { validate(token: string): { sub: string; username: string } | null };
  kbEngine: any;
  mcpOrchestrator: any;
}

export function registerAdminModule(app: Express, deps: AdminModuleDependencies): void {
  const adminRouter = Router();
  adminRouter.use(json({ limit: '50mb' }));

  // JWT extraction
  adminRouter.use((req, _res, next) => {
    const auth = req.headers.authorization;
    if (auth?.startsWith('Bearer ')) {
      const claims = deps.jwtService.validate(auth.slice(7));
      if (claims) { (req as unknown as { userId: string; username: string }).userId = claims.sub; (req as unknown as { userId: string; username: string }).username = claims.username; }
    }
    next();
  });

  // RBAC
  adminRouter.use(createRBACMiddleware({
    getUserPermissions: async (userId: string) => {
      const rows = deps.db.prepare(
        'SELECT gp.permission_id, gp.role_data FROM users u JOIN group_permissions gp ON gp.access_group_id = u.access_group_id WHERE u.user_id = ?'
      ).all(userId);
      return rows?.length ? rows.map((r: any) => ({ permissionId: r.permission_id, roleData: JSON.parse(r.role_data || '{}') })) : null;
    },
    getUserStatus: async (userId: string) => deps.db.prepare('SELECT status FROM users WHERE user_id = ?').get(userId)?.status || null,
  }));

  adminRouter.use(rateLimitMiddleware);
  adminRouter.use(createAuditMiddleware({
    recordAudit: async (entry) => {
      deps.db.prepare(
        'INSERT INTO audit_entries (audit_id, user_id, username, action, resource, resource_id, changes, ip_address) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
      ).run(crypto.randomUUID(), entry.userId, entry.username, entry.action, entry.resource, entry.resourceId || null, entry.changes ? JSON.stringify(entry.changes) : null, entry.ipAddress || null);
    },
  }));

  // /api/admin/me
  adminRouter.get('/me', (req, res) => {
    const userId = (req as unknown as { userId: string }).userId;
    if (!userId) { res.status(401).json({ success: false, error: { code: 'UNAUTHORIZED', message: 'Not authenticated' } }); return; }
    const user = deps.db.prepare('SELECT u.*, ag.access_group_name FROM users u JOIN access_groups ag ON ag.access_group_id = u.access_group_id WHERE u.user_id = ?').get(userId);
    if (!user) { res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'User not found' } }); return; }
    const perms = deps.db.prepare('SELECT permission_id, role_data FROM group_permissions WHERE access_group_id = ?').all(user.access_group_id);
    res.json({ success: true, data: { userId: user.user_id, username: user.username, email: user.email, accessGroup: { id: user.access_group_id, name: user.access_group_name }, permissions: perms.map((p: any) => ({ permissionId: p.permission_id, roleData: JSON.parse(p.role_data || '{}') })) } });
  });

  // Feature routers
  adminRouter.use('/dashboard', dashboardRouter(deps));
  adminRouter.use('/kb', kbAdminRouter(deps));
  adminRouter.use('/mcp', mcpAdminRouter(deps));
  adminRouter.use('/users', userRouter(deps));
  adminRouter.use('/rbac', rbacRouter(deps));
  adminRouter.use('/config', configRouter(deps));
  adminRouter.use('/audit', auditRouter(deps));

  app.use('/api/admin', adminRouter);

  // SPA static files
  const spaPath = path.join(__dirname, '../../viewer/admin');
  app.get('/admin/*', (_req, res) => { res.sendFile(path.join(spaPath, 'index.html'), (err) => { if (err) res.status(404).send('Admin Portal not built yet'); }); });

  console.log('[KSA-286] Admin Portal registered: /api/admin/* + /admin/*');
}

// KSA-286: Audit Middleware — Records every admin action after handler completes

import { Request, Response, NextFunction } from 'express';

export interface AuditDeps {
  recordAudit: (entry: {
    userId: string;
    username: string;
    action: string;
    resource: string;
    resourceId?: string;
    changes?: any;
    ipAddress?: string;
  }) => Promise<void>;
}

function deriveAction(method: string, path: string): string {
  if (path.includes('force-logout')) return 'USER_FORCE_LOGOUT';
  if (path.includes('reset-password')) return 'USER_UPDATED';
  if (path.includes('status') && method === 'PATCH') return 'USER_DISABLED';
  if (path.includes('promotion/review')) return 'KB_ENTRY_PROMOTED';
  if (path.includes('/links') && method === 'POST') return 'KB_LINKED';
  if (path.includes('/links') && method === 'DELETE') return 'KB_UNLINKED';
  if (path.includes('/tags')) return 'KB_TAGS_UPDATED';
  if (path.includes('/restart')) return 'SERVER_RESTARTED';
  if (path.includes('/tools/') && method === 'PATCH') return 'TOOL_DISABLED';
  if (path.includes('/import')) return 'KB_IMPORTED';
  if (path.includes('/config') && method === 'PATCH') return 'CONFIG_UPDATED';

  const resource = path.split('/').filter(Boolean)[2] || 'unknown';
  const map: Record<string, Record<string, string>> = {
    users: { POST: 'USER_CREATED', PATCH: 'USER_UPDATED', DELETE: 'USER_DELETED' },
    rbac: { POST: 'GROUP_CREATED', PUT: 'GROUP_UPDATED', DELETE: 'GROUP_DELETED' },
  };
  return map[resource]?.[method] || `${method}_${resource.toUpperCase()}`;
}

export function createAuditMiddleware(deps: AuditDeps) {
  return (req: Request, res: Response, next: NextFunction): void => {
    if (req.method === 'GET') { next(); return; }

    const originalJson = res.json.bind(res);
    res.json = function (body: any) {
      const userId = (req as unknown as { userId: string }).userId;
      const username = (req as unknown as { username: string }).username || 'unknown';
      if (userId && res.statusCode < 500) {
        deps.recordAudit({
          userId, username,
          action: deriveAction(req.method, req.baseUrl + req.path),
          resource: (req.baseUrl + req.path).split('/').filter(Boolean)[2] || 'unknown',
          resourceId: (req.params.id || req.params.userId) as string | undefined,
          changes: req.body ? { after: req.body } : undefined,
          ipAddress: (Array.isArray(req.ip) ? req.ip[0] : req.ip) || req.socket.remoteAddress,
        }).catch(() => {});
      }
      return originalJson(body);
    };
    next();
  };
}

// KSA-286: RBAC Middleware — Permission enforcement on every /api/admin/* request

import { Request, Response, NextFunction } from 'express';
import { PermissionId, AdminErrorCode, GroupPermission } from '../types/admin.types.js';

// Route → Permission mapping
const ROUTE_PERMISSIONS: Record<string, PermissionId> = {
