// KSA-286: Audit Service
import { AuditEntry, PaginatedResult, PaginationParams } from '../types/admin.types.js';

export class AuditService {
  constructor(private db: any) {}

  record(entry: Omit<AuditEntry, 'auditId' | 'timestamp'>): void {
    this.db.prepare('INSERT INTO audit_entries (audit_id, user_id, username, action, resource, resource_id, changes, ip_address) VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(crypto.randomUUID(), entry.userId, entry.username, entry.action, entry.resource, entry.resourceId || null, entry.changes ? JSON.stringify(entry.changes) : null, entry.ipAddress || null);
  }

  list(filters: { userId?: string; action?: string; dateFrom?: string; dateTo?: string }, pagination: PaginationParams): PaginatedResult<AuditEntry> {
    let where = '1=1'; const params: any[] = [];
    if (filters.userId) { where += ' AND user_id = ?'; params.push(filters.userId); }
    if (filters.action) { where += ' AND action = ?'; params.push(filters.action); }
    if (filters.dateFrom) { where += ' AND timestamp >= ?'; params.push(filters.dateFrom); }
    if (filters.dateTo) { where += ' AND timestamp <= ?'; params.push(filters.dateTo); }
    const total = this.db.prepare(`SELECT COUNT(*) as cnt FROM audit_entries WHERE ${where}`).get(...params)?.cnt || 0;
    const offset = (pagination.page - 1) * pagination.size;
    const rows = this.db.prepare(`SELECT * FROM audit_entries WHERE ${where} ORDER BY timestamp DESC LIMIT ? OFFSET ?`).all(...params, pagination.size, offset);
    return { items: rows.map((r: any) => ({ auditId: r.audit_id, userId: r.user_id, username: r.username, action: r.action, resource: r.resource, resourceId: r.resource_id, changes: r.changes ? JSON.parse(r.changes) : undefined, timestamp: r.timestamp, ipAddress: r.ip_address })), pagination: { page: pagination.page, size: pagination.size, total, totalPages: Math.ceil(total / pagination.size), hasNext: offset + pagination.size < total, hasPrev: pagination.page > 1 } };
  }

  export(format: 'csv' | 'json', dateFrom: string, dateTo: string): string {
    const rows = this.db.prepare('SELECT * FROM audit_entries WHERE timestamp >= ? AND timestamp <= ? ORDER BY timestamp DESC').all(dateFrom, dateTo);
    if (format === 'json') return JSON.stringify(rows, null, 2);
    return 'audit_id,user_id,username,action,resource,resource_id,timestamp,ip_address\n' + rows.map((r: any) => `${r.audit_id},${r.user_id},${r.username},${r.action},${r.resource},${r.resource_id||''},${r.timestamp},${r.ip_address||''}`).join('\n');
  }
}

// KSA-286: Config Service
import { ConfigEntry, ConfigHistoryEntry, ConfigUpdateResult } from '../types/admin.types.js';

export class ConfigService {
  private runtime = new Map<string, any>();
  constructor(private db: any) { for (const e of this.db.prepare('SELECT * FROM config_entries').all()) { this.runtime.set(`${e.section}:${e.key}`, JSON.parse(e.value)); } }

  getAll(sections?: string[]): ConfigEntry[] {
    const rows = sections?.length ? this.db.prepare(`SELECT * FROM config_entries WHERE section IN (${sections.map(()=>'?').join(',')}) ORDER BY section,key`).all(...sections) : this.db.prepare('SELECT * FROM config_entries ORDER BY section,key').all();
    return rows.map((r: any) => ({ section: r.section, key: r.key, value: r.value, type: r.type, defaultValue: r.default_value, requiresRestart: !!r.requires_restart, lastModified: r.last_modified, modifiedBy: r.modified_by }));
  }

  update(section: string, key: string, newValue: any, userId: string): ConfigUpdateResult {
    const entry = this.db.prepare('SELECT * FROM config_entries WHERE section = ? AND key = ?').get(section, key);
    if (!entry) throw { code: 'ENTRY_NOT_FOUND' };
    const val = JSON.stringify(newValue);
    this.db.transaction(() => { this.db.prepare('UPDATE config_entries SET value=?, last_modified=datetime("now"), modified_by=? WHERE section=? AND key=?').run(val, userId, section, key); this.db.prepare('INSERT INTO config_history (history_id,section,key,old_value,new_value,changed_by) VALUES (?,?,?,?,?,?)').run(crypto.randomUUID(), section, key, entry.value, val, userId); })();
    if (!entry.requires_restart) { this.runtime.set(`${section}:${key}`, newValue); return { applied: true, requiresRestart: false }; }
    return { applied: false, requiresRestart: true };
  }

  getHistory(limit = 10): ConfigHistoryEntry[] {
    return this.db.prepare('SELECT * FROM config_history ORDER BY changed_at DESC LIMIT ?').all(limit).map((r: any) => ({ historyId: r.history_id, section: r.section, key: r.key, oldValue: r.old_value, newValue: r.new_value, changedAt: r.changed_at, changedBy: r.changed_by }));
  }

  get(section: string, key: string): any { return this.runtime.get(`${section}:${key}`); }
}

/**
 * dashboard.service.ts — Dashboard health data service.
 * SA4E-50: getKbEntryCount is now async; getHealth is async.
 * NOTE: This service uses legacy raw db for activeSessions (schema init path).
 * KSA-286: Dashboard Service
 */
import pino from 'pino';
import type { DashboardHealth } from '../types/admin.types.js';
import * as os from 'os';
import * as fs from 'fs';
import { getKbEntryCount } from '../admin-db.js';

const logger = pino({ name: 'dashboard-service' });

export class DashboardService {
  private startTime = Date.now();
  constructor(private db: any, private mcpOrchestrator: any) {}

  async getHealth(): Promise<DashboardHealth> {
    const memUsage = process.memoryUsage();
    const cpus = os.cpus();
    const cpuPercent = cpus.reduce((acc, cpu) => {
      const total = Object.values(cpu.times).reduce((a, b) => a + b, 0);
      return acc + ((total - cpu.times.idle) / total) * 100;
    }, 0) / cpus.length;

    let sqliteSize = 0;
    try {
      const stat = fs.statSync(this.db.name);
      sqliteSize = stat.size / (1024 * 1024);
    } catch { logger.debug({ context: 'dashboard-health' }, 'Could not stat SQLite db file for size'); }

    const activeSessions = this.db.prepare('SELECT COUNT(*) as cnt FROM sessions WHERE is_active = 1').get()?.cnt || 0;
    const alerts: DashboardHealth['alerts'] = [];
    if (memUsage.heapUsed / (1024 * 1024) > 80 * 0.01 * os.totalmem() / (1024 * 1024)) {
      alerts.push({ severity: 'warning', message: 'Memory usage > 80%', since: new Date().toISOString() });
    }

    const servers = this.mcpOrchestrator?.getServers?.() || [];
    const onlineCount = servers.filter((s: any) => s.status === 'RUNNING').length;
    
    // Count ALL KB entries across all projects when no specific filter is active
    let kbTotal = 0;
    try {
      const adapter = (this.db as any);
      const row = this.db.prepare("SELECT COUNT(*) as cnt FROM knowledge_entries").get() as { cnt?: number } | undefined;
      kbTotal = row?.cnt || 0;
    } catch {
      kbTotal = await getKbEntryCount();
    }

    return {
      uptime: Math.floor((Date.now() - this.startTime) / 1000),
      memoryUsageMB: Math.round(memUsage.heapUsed / (1024 * 1024)),
      cpuPercent: Math.round(cpuPercent * 10) / 10,
      sqliteFileSizeMB: Math.round(sqliteSize * 10) / 10,
      mcpServers: { online: onlineCount, total: servers.length },
      kbEntryCount: { user: 0, project: 0, shared: kbTotal },
      activeUsers: activeSessions,
      alerts,
    };
  }

  getActivity(limit = 20): any[] {
    return this.db.prepare(
      'SELECT audit_id, user_id, username, action, resource, timestamp FROM audit_entries ORDER BY timestamp DESC LIMIT ?',
    ).all(limit);
  }
}

