export class KBAdminService {
  constructor(private db: any, private kbEngine: any) {}

  listEntries(filters: { tier?: string; tags?: string; search?: string }, pagination: PaginationParams): PaginatedResult<any> {
    // Delegate to KB engine with pagination
    const result = this.kbEngine?.listEntries?.({ ...filters, page: pagination.page, size: pagination.size });
    if (result) return result;
    return { items: [], pagination: { page: pagination.page, size: pagination.size, total: 0, totalPages: 0, hasNext: false, hasPrev: false } };
  }

  createLink(sourceId: string, targetId: string, linkType = 'related'): void {
    // BR-10: Circular link detection (BFS)
    if (this.hasCircularLink(sourceId, targetId)) throw { code: AdminErrorCode.CIRCULAR_LINK };
    this.kbEngine?.createLink?.(sourceId, targetId, linkType);
  }

  removeLink(sourceId: string, targetId: string): void { this.kbEngine?.removeLink?.(sourceId, targetId); }

  updateTags(entryId: string, tags: string[]): void {
    // BR-06: validate tag format, BR-07: max 20
    for (const tag of tags) { if (!/^[a-z0-9-]{1,50}$/.test(tag)) throw { code: AdminErrorCode.VALIDATION_ERROR, message: `Invalid tag: ${tag}` }; }
    if (tags.length > 20) throw { code: AdminErrorCode.VALIDATION_ERROR, message: 'Max 20 tags' };
    this.kbEngine?.updateTags?.(entryId, tags);
  }

  reviewPromotion(data: { entryId: string; decision: 'APPROVE' | 'REJECT'; comment: string; targetTier?: string }, reviewerId: string): void {
    if (data.comment.length < 10) throw { code: AdminErrorCode.COMMENT_TOO_SHORT };
    const promo = this.db.prepare('SELECT * FROM kb_promotion_queue WHERE entry_id = ? AND status = ?').get(data.entryId, 'PENDING');
    if (!promo) throw { code: AdminErrorCode.PROMOTION_NOT_PENDING };

    if (data.decision === 'APPROVE') {
      this.db.prepare('UPDATE kb_promotion_queue SET status = ?, review_comment = ?, reviewed_by = ?, reviewed_at = datetime("now") WHERE promotion_id = ?').run('APPROVED', data.comment, reviewerId, promo.promotion_id);
      this.kbEngine?.promoteEntry?.(data.entryId, data.targetTier || promo.target_tier);
    } else {
      const cooldown = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
      this.db.prepare('UPDATE kb_promotion_queue SET status = ?, review_comment = ?, reviewed_by = ?, reviewed_at = datetime("now"), cooldown_until = ? WHERE promotion_id = ?').run('REJECTED', data.comment, reviewerId, cooldown, promo.promotion_id);
    }
  }

  listPromotions(): KBPromotionEntry[] {
    return this.db.prepare('SELECT * FROM kb_promotion_queue WHERE status = ? ORDER BY created_at DESC').all('PENDING').map((r: any) => ({ promotionId: r.promotion_id, entryId: r.entry_id, sourceTier: r.source_tier, targetTier: r.target_tier, reason: r.reason, status: r.status, createdAt: r.created_at }));
  }

  getGraphData(filters: { tier?: string; minQuality?: number; limit?: number; projectId?: string }): any {
    return this.kbEngine?.getGraphData?.(filters) || { nodes: [], edges: [], clusters: [], totalCount: 0 };
  }

  private hasCircularLink(sourceId: string, targetId: string): boolean {
    const visited = new Set<string>();
    const queue = [targetId];
    while (queue.length > 0) {
      const current = queue.shift()!;
      if (current === sourceId) return true;
      if (visited.has(current)) continue;
      visited.add(current);
      const linked = this.kbEngine?.getLinkedEntries?.(current) || [];
      for (const entry of linked) { if (!visited.has(entry.id)) queue.push(entry.id); }
    }
    return false;
  }
}

// KSA-286: MCP Admin Service
import { MCPServerInfo, AdminErrorCode } from '../types/admin.types.js';

export class MCPAdminService {
  constructor(private mcpOrchestrator: any) {}

  listServers(): MCPServerInfo[] {
    const servers = this.mcpOrchestrator?.getServers?.() || [];
    return servers.map((s: any) => ({
      serverId: s.id || s.serverId,
      serverName: s.name || s.serverName || s.id,
      status: s.status || 'STOPPED',
      tools: (s.tools || []).map((t: any) => ({ name: t.name, enabled: t.enabled !== false, lastCall: t.lastCall })),
      lastHeartbeat: s.lastHeartbeat,
      uptimeSeconds: s.uptimeSeconds || 0,
      restartCount: s.restartCount || 0,
    }));
  }

  getServer(serverId: string): MCPServerInfo | null {
    const servers = this.listServers();
    return servers.find(s => s.serverId === serverId) || null;
  }

  async restart(serverId: string): Promise<{ success: boolean; message: string }> {
    try {
      await this.mcpOrchestrator?.restartServer?.(serverId);
      return { success: true, message: `Server ${serverId} restarted` };
    } catch (e: any) {
      throw { code: AdminErrorCode.RESTART_FAILED, message: e.message || 'Restart failed' };
    }
  }

  toggleTool(serverId: string, toolName: string, enabled: boolean): void {
    this.mcpOrchestrator?.toggleTool?.(serverId, toolName, enabled);
  }

  getLogs(serverId: string, lines = 200): string[] {
    return this.mcpOrchestrator?.getServerLogs?.(serverId, lines) || [];
  }
}

// KSA-286: RBAC Service — SQLite-only path (uses raw better-sqlite3 directly)
import { AccessGroupWithPermissions, GroupPermission, AdminErrorCode } from '../types/admin.types.js';
import { invalidateRBACCache } from '../middleware/rbac.middleware.js';

export class RBACService {
  constructor(private db: any) {}

  private rolesTableExists: boolean | null = null;

  // SQLite-only path: uses raw better-sqlite3 Database.prepare() directly
  private hasRolesTable(): boolean {
    if (this.rolesTableExists === null) {
      const result = this.db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='roles'").get();
      this.rolesTableExists = !!result;
    }
    return this.rolesTableExists;
  }

  listGroups(): AccessGroupWithPermissions[] {
    const groups = this.db.prepare('SELECT * FROM access_groups ORDER BY access_group_name').all();
    const hasRoles = this.hasRolesTable();
    return groups.map((g: any) => {
      const perms = this.db.prepare('SELECT permission_id, role_data FROM group_permissions WHERE access_group_id = ?').all(g.access_group_id);
      const userCount = this.db.prepare('SELECT COUNT(*) as cnt FROM users WHERE access_group_id = ?').get(g.access_group_id)?.cnt || 0;
      const permissionsWithRoles = perms.map((p: any) => {
        let roles: any[] = [];
        if (hasRoles) {
          try { roles = this.db.prepare('SELECT role_id, role_name, role_data FROM roles WHERE access_group_id = ? AND permission_id = ?').all(g.access_group_id, p.permission_id); } catch (err) { /* roles table query failed — table may not exist */ }
        }
        return { permissionId: p.permission_id, roleData: JSON.parse(p.role_data || '{}'), roles: roles.map((r: any) => ({ roleId: r.role_id, roleName: r.role_name, roleData: JSON.parse(r.role_data || '{}') })) };
      });
      return { accessGroupId: g.access_group_id, accessGroupName: g.access_group_name, isSystemGroup: !!g.is_system_group, createdAt: g.created_at, updatedAt: g.updated_at, permissions: permissionsWithRoles, userCount };
    });
  }

  createGroup(name: string, permissions: GroupPermission[]): AccessGroupWithPermissions {
    if (this.db.prepare('SELECT 1 FROM access_groups WHERE access_group_name = ?').get(name)) throw { code: AdminErrorCode.VALIDATION_ERROR, message: 'Group name exists' };
    const id = 'grp-' + crypto.randomUUID().slice(0, 8);
    this.db.transaction(() => {
      this.db.prepare('INSERT INTO access_groups (access_group_id, access_group_name) VALUES (?, ?)').run(id, name);
      for (const p of permissions) { this.db.prepare('INSERT INTO group_permissions (access_group_id, permission_id, role_data) VALUES (?, ?, ?)').run(id, p.permissionId, JSON.stringify(p.roleData || {})); }
    })();
    invalidateRBACCache();
    return { accessGroupId: id, accessGroupName: name, isSystemGroup: false, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), permissions };
  }

  updateGroup(groupId: string, name: string, permissions: GroupPermission[]): void {
    const group = this.db.prepare('SELECT * FROM access_groups WHERE access_group_id = ?').get(groupId);
    if (!group) throw { code: AdminErrorCode.ENTRY_NOT_FOUND };
    this.db.transaction(() => {
      // SQLite-only path: rbac uses raw better-sqlite3
      const nowExpr = "datetime('now')";
      this.db.prepare(`UPDATE access_groups SET access_group_name = ?, updated_at = ${nowExpr} WHERE access_group_id = ?`).run(name, groupId);
      this.db.prepare('DELETE FROM group_permissions WHERE access_group_id = ?').run(groupId);
      for (const p of permissions) { this.db.prepare('INSERT INTO group_permissions (access_group_id, permission_id, role_data) VALUES (?, ?, ?)').run(groupId, p.permissionId, JSON.stringify(p.roleData || {})); }
    })();
    invalidateRBACCache();
  }

  deleteGroup(groupId: string): void {
    const group = this.db.prepare('SELECT * FROM access_groups WHERE access_group_id = ?').get(groupId);
    if (!group) throw { code: AdminErrorCode.ENTRY_NOT_FOUND };
    if (group.is_system_group) throw { code: AdminErrorCode.LAST_SYSTEM_OWNER, message: 'Cannot delete System Owner group' };
    const users = this.db.prepare('SELECT COUNT(*) as cnt FROM users WHERE access_group_id = ?').get(groupId)?.cnt || 0;
    if (users > 0) throw { code: AdminErrorCode.GROUP_HAS_USERS, message: `Group has ${users} users` };
    this.db.prepare('DELETE FROM access_groups WHERE access_group_id = ?').run(groupId);
    invalidateRBACCache();
  }

  listPermissions(): any[] { return this.db.prepare('SELECT * FROM permissions ORDER BY permission_id').all(); }

  // --- Role CRUD ---

  listRoles(groupId: string, permissionId: string): any[] {
    return this.db.prepare('SELECT role_id, role_name, role_data, created_at FROM roles WHERE access_group_id = ? AND permission_id = ?').all(groupId, permissionId)
      .map((r: any) => ({ roleId: r.role_id, roleName: r.role_name, roleData: JSON.parse(r.role_data || '{}'), createdAt: r.created_at }));
  }

  createRole(groupId: string, permissionId: string, roleName: string, roleData: any): any {
    const gp = this.db.prepare('SELECT 1 FROM group_permissions WHERE access_group_id = ? AND permission_id = ?').get(groupId, permissionId);
    if (!gp) throw { code: AdminErrorCode.ENTRY_NOT_FOUND, message: 'Group does not have this permission' };
    const roleId = 'role-' + crypto.randomUUID().slice(0, 8);
    this.db.prepare('INSERT INTO roles (role_id, access_group_id, permission_id, role_name, role_data) VALUES (?, ?, ?, ?, ?)').run(roleId, groupId, permissionId, roleName, JSON.stringify(roleData || {}));
    invalidateRBACCache();
    return { roleId, roleName, roleData: roleData || {}, createdAt: new Date().toISOString() };
  }

  updateRole(roleId: string, roleName: string, roleData: any): void {
    const role = this.db.prepare('SELECT 1 FROM roles WHERE role_id = ?').get(roleId);
    if (!role) throw { code: AdminErrorCode.ENTRY_NOT_FOUND, message: 'Role not found' };
    this.db.prepare('UPDATE roles SET role_name = ?, role_data = ? WHERE role_id = ?').run(roleName, JSON.stringify(roleData || {}), roleId);
    invalidateRBACCache();
  }

  deleteRole(roleId: string): void {
    const role = this.db.prepare('SELECT 1 FROM roles WHERE role_id = ?').get(roleId);
    if (!role) throw { code: AdminErrorCode.ENTRY_NOT_FOUND, message: 'Role not found' };
    this.db.prepare('DELETE FROM roles WHERE role_id = ?').run(roleId);
    invalidateRBACCache();
  }
}

// KSA-286: Search Service — Execute search with score breakdown

import { AdminModuleDependencies } from '../index.js';

export interface SearchRequest {
  query: string;
  tier?: string;
  tags?: string[];
  limit?: number;
  includeScoreBreakdown?: boolean;
}

export function createSearchService(deps: AdminModuleDependencies) {
  const { kbEngine } = deps;

  return {
    search(request: SearchRequest) {
      try {
        const results = kbEngine?.search?.({
          query: request.query,
          tier: request.tier,
          tags: request.tags,
          limit: request.limit || 20,
          includeScoreBreakdown: request.includeScoreBreakdown !== false,
        }) || [];

        return {
          query: request.query,
          results: results.map((r: any) => ({
            entryId: r.entryId || r.id,
            title: r.title,
            content: r.content?.substring(0, 500),
            tier: r.tier,
            tags: r.tags || [],
            score: r.score || 0,
            scoreBreakdown: r.scoreBreakdown || undefined,
            createdAt: r.createdAt,
          })),
          total: results.length,
          searchTimeMs: 0,
        };
      } catch (e: any) {
        return { query: request.query, results: [], total: 0, searchTimeMs: 0, error: e?.message };
      }
    },
  };
}

// KSA-286: SSE (Server-Sent Events) Manager
import pino from 'pino';
import { Response } from 'express';

const logger = pino({ name: 'sse-manager' });

interface SSEClient { userId: string; res: Response; connectedAt: number; }

export class SSEManager {
  private clients = new Map<string, SSEClient>();
  private heartbeatInterval: NodeJS.Timeout;

  constructor() { this.heartbeatInterval = setInterval(() => this.heartbeat(), 15000); }

  addClient(userId: string, res: Response): void {
    // Close existing connection for this user (1 per user limit)
    const existing = this.clients.get(userId);
    if (existing) { try { existing.res.end(); } catch { logger.trace({ context: 'sse-add' }, 'Failed to close existing SSE connection (already disconnected)'); } }

    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no' });
    res.write('retry: 30000\n\n');
    this.clients.set(userId, { userId, res, connectedAt: Date.now() });

    res.on('close', () => { this.clients.delete(userId); });
  }

  broadcast(event: string, data: any): void {
    const msg = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
    for (const client of this.clients.values()) { try { client.res.write(msg); } catch { logger.trace({ context: 'sse-broadcast' }, 'Failed to write to SSE client (likely disconnected)'); } }
  }

  sendToUser(userId: string, event: string, data: any): void {
    const client = this.clients.get(userId);
    if (client) { try { client.res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); } catch { logger.trace({ context: 'sse-send', userId }, 'Failed to send event to SSE client (likely disconnected)'); } }
  }

  private heartbeat(): void {
    for (const client of this.clients.values()) { try { client.res.write(': keepalive\n\n'); } catch { this.clients.delete(client.userId); } }
  }

  getClientCount(): number { return this.clients.size; }

  destroy(): void { clearInterval(this.heartbeatInterval); for (const c of this.clients.values()) { try { c.res.end(); } catch { logger.trace({ context: 'sse-destroy' }, 'Failed to end SSE response during destroy'); } } this.clients.clear(); }
}

// KSA-286: User Service
import { AdminUser, AdminErrorCode, PaginatedResult, PaginationParams } from '../types/admin.types.js';

export class UserService {
  constructor(private db: any) {}

  list(filters: { status?: string; search?: string }, pagination: PaginationParams): PaginatedResult<AdminUser> {
    let where = '1=1'; const params: any[] = [];
    if (filters.status) { where += ' AND status = ?'; params.push(filters.status); }
    if (filters.search) { where += ' AND (username LIKE ? OR email LIKE ?)'; params.push('%'+filters.search+'%', '%'+filters.search+'%'); }
    const total = this.db.prepare(`SELECT COUNT(*) as cnt FROM users WHERE ${where}`).get(...params)?.cnt || 0;
    const offset = (pagination.page - 1) * pagination.size;
    const rows = this.db.prepare(`SELECT * FROM users WHERE ${where} ORDER BY created_at DESC LIMIT ? OFFSET ?`).all(...params, pagination.size, offset);
    return { items: rows.map((r: any) => ({ userId: r.user_id, username: r.username, email: r.email, status: r.status, accessGroupId: r.access_group_id, forcePasswordChange: !!r.force_password_change, createdAt: r.created_at, lastLogin: r.last_login })), pagination: { page: pagination.page, size: pagination.size, total, totalPages: Math.ceil(total / pagination.size), hasNext: offset + pagination.size < total, hasPrev: pagination.page > 1 } };
  }

  async create(data: { username: string; email: string; password: string; accessGroupId: string }): Promise<AdminUser> {
    if (this.db.prepare('SELECT 1 FROM users WHERE username = ?').get(data.username)) throw { code: AdminErrorCode.DUPLICATE_USERNAME };
    if (this.db.prepare('SELECT 1 FROM users WHERE email = ?').get(data.email)) throw { code: AdminErrorCode.DUPLICATE_EMAIL };
    if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(data.password)) throw { code: AdminErrorCode.WEAK_PASSWORD };
    const bcrypt = require('bcrypt');
    const userId = crypto.randomUUID();
    const hash = await bcrypt.hash(data.password, 10);
    this.db.prepare('INSERT INTO users (user_id, username, email, password_hash, access_group_id) VALUES (?, ?, ?, ?, ?)').run(userId, data.username, data.email, hash, data.accessGroupId);
    return { userId, username: data.username, email: data.email, status: 'ACTIVE', accessGroupId: data.accessGroupId, forcePasswordChange: false, createdAt: new Date().toISOString() };
  }

  updateStatus(userId: string, status: 'ACTIVE' | 'DISABLED'): { sessionsTerminated: number } {
    this.db.prepare('UPDATE users SET status = ? WHERE user_id = ?').run(status, userId);
    if (status === 'DISABLED') { const r = this.db.prepare('UPDATE sessions SET is_active = 0 WHERE user_id = ? AND is_active = 1').run(userId); return { sessionsTerminated: r.changes }; }
    return { sessionsTerminated: 0 };
  }

  delete(userId: string): void {
    const user = this.db.prepare('SELECT access_group_id FROM users WHERE user_id = ?').get(userId);
    if (!user) throw { code: AdminErrorCode.ENTRY_NOT_FOUND };
    const group = this.db.prepare('SELECT is_system_group FROM access_groups WHERE access_group_id = ?').get(user.access_group_id);
    if (group?.is_system_group) { const cnt = this.db.prepare('SELECT COUNT(*) as c FROM users WHERE access_group_id = ?').get(user.access_group_id)?.c; if (cnt <= 1) throw { code: AdminErrorCode.LAST_SYSTEM_OWNER }; }
    this.db.prepare('DELETE FROM users WHERE user_id = ?').run(userId);
  }

  forceLogout(userId: string, sessionId?: string): { terminated: number } {
    const r = sessionId ? this.db.prepare('UPDATE sessions SET is_active = 0 WHERE session_id = ? AND user_id = ?').run(sessionId, userId) : this.db.prepare('UPDATE sessions SET is_active = 0 WHERE user_id = ? AND is_active = 1').run(userId);
    return { terminated: r.changes };
  }

  async resetPassword(userId: string): Promise<{ temporaryPassword: string }> {
    const bcrypt = require('bcrypt');
    const temp = crypto.randomUUID().replace(/-/g, '').slice(0, 16);
    const hash = await bcrypt.hash(temp, 10);
    this.db.prepare('UPDATE users SET password_hash = ?, force_password_change = 1 WHERE user_id = ?').run(hash, userId);
    return { temporaryPassword: temp };
  }
}

// KSA-286: Admin Portal Type Definitions

export type PermissionId =
  | 'DASHBOARD_VIEW' | 'KB_READ' | 'KB_WRITE' | 'KB_PROMOTE'
  | 'KB_IMPORT_EXPORT' | 'MCP_ACCESS' | 'MCP_MANAGE' | 'USER_MANAGE'
  | 'RBAC_MANAGE' | 'CONFIG_EDIT' | 'SEARCH_EXPLORE' | 'AUDIT_VIEW'
  | 'GRAPH_VIEW' | 'ANALYTICS_VIEW';

export type UserStatus = 'ACTIVE' | 'DISABLED' | 'PENDING';
export type KBTier = 'USER' | 'PROJECT' | 'SHARED';
export type PromotionStatus = 'PENDING' | 'APPROVED' | 'REJECTED';
export type MCPServerStatus = 'RUNNING' | 'STOPPED' | 'ERROR' | 'STARTING';
export type ConfigValueType = 'string' | 'number' | 'boolean' | 'select';

export interface AdminUser {
  userId: string;
  username: string;
  email: string;
  status: UserStatus;
  accessGroupId: string;
  forcePasswordChange: boolean;
  createdAt: string;
  lastLogin?: string;
}

export interface AdminUserWithPassword extends AdminUser {
  passwordHash: string;
}

export interface Session {
  sessionId: string;
  userId: string;
  device?: string;
  ipAddress?: string;
  loginAt: string;
  expiresAt: string;
  isActive: boolean;
}

export interface AccessGroup {
  accessGroupId: string;
  accessGroupName: string;
  isSystemGroup: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface AccessGroupWithPermissions extends AccessGroup {
  permissions: GroupPermission[];
  userCount?: number;
}

export interface Permission {
  permissionId: PermissionId;
  permissionName: string;
  description?: string;
  roleDataSchema: Record<string, any>;
}

export interface GroupPermission {
  permissionId: PermissionId;
  roleData: Record<string, any>;
}

export type AuditAction =
  | 'USER_CREATED' | 'USER_UPDATED' | 'USER_DISABLED' | 'USER_DELETED' | 'USER_FORCE_LOGOUT'
  | 'GROUP_CREATED' | 'GROUP_UPDATED' | 'GROUP_DELETED'
  | 'PERMISSION_ASSIGNED' | 'PERMISSION_REVOKED'
  | 'KB_ENTRY_PROMOTED' | 'KB_ENTRY_REJECTED' | 'KB_BULK_DELETE' | 'KB_IMPORTED' | 'KB_EXPORTED'
  | 'KB_LINKED' | 'KB_UNLINKED' | 'KB_TAGS_UPDATED'
  | 'SERVER_RESTARTED' | 'TOOL_ENABLED' | 'TOOL_DISABLED'
  | 'CONFIG_UPDATED' | 'CONFIG_RESET'
  | 'LOGIN_SUCCESS' | 'LOGIN_FAILED' | 'TOKEN_REVOKED';

export interface AuditEntry {
  auditId: string;
  userId: string;
  username: string;
  action: AuditAction;
  resource: string;
  resourceId?: string;
  changes?: { before?: Record<string, any>; after?: Record<string, any> };
  timestamp: string;
  ipAddress?: string;
}

export interface ConfigEntry {
  section: string;
  key: string;
  value: string;
  type: ConfigValueType;
  defaultValue: string;
  requiresRestart: boolean;
  lastModified?: string;
  modifiedBy?: string;
}

export interface ConfigHistoryEntry {
  historyId: string;
  section: string;
  key: string;
  oldValue: string;
  newValue: string;
  changedAt: string;
  changedBy: string;
}

export interface KBPromotionEntry {
  promotionId: string;
  entryId: string;
  sourceTier: KBTier;
  targetTier: KBTier;
  reason: string;
  status: PromotionStatus;
  reviewComment?: string;
  reviewedBy?: string;
  reviewedAt?: string;
  createdAt: string;
  cooldownUntil?: string;
}

export interface MCPServerInfo {
  serverId: string;
  serverName: string;
  status: MCPServerStatus;
  tools: Array<{ name: string; enabled: boolean; lastCall?: string }>;
  lastHeartbeat?: string;
  uptimeSeconds: number;
  restartCount: number;
}

export interface DashboardHealth {
  uptime: number;
  memoryUsageMB: number;
  cpuPercent: number;
  sqliteFileSizeMB: number;
  mcpServers: { online: number; total: number };
  kbEntryCount: { user: number; project: number; shared: number };
  activeUsers: number;
  alerts: Array<{ severity: 'info' | 'warning' | 'critical'; message: string; since: string }>;
}

export interface PaginationParams { page: number; size: number; }

export interface PaginatedResult<T> {
  items: T[];
  pagination: { page: number; size: number; total: number; totalPages: number; hasNext: boolean; hasPrev: boolean };
}

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: { code: string; message: string; details?: Record<string, any> };
  meta: { requestId: string; timestamp: string };
}

export enum AdminErrorCode {
  UNAUTHORIZED = 'UNAUTHORIZED',
  TOKEN_EXPIRED = 'TOKEN_EXPIRED',
  PERMISSION_DENIED = 'PERMISSION_DENIED',
  ROLE_DATA_DENIED = 'ROLE_DATA_DENIED',
  USER_DISABLED = 'USER_DISABLED',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  DUPLICATE_USERNAME = 'DUPLICATE_USERNAME',
  DUPLICATE_EMAIL = 'DUPLICATE_EMAIL',
  WEAK_PASSWORD = 'WEAK_PASSWORD',
  INVALID_ROLE_DATA = 'INVALID_ROLE_DATA',
  LAST_SYSTEM_OWNER = 'LAST_SYSTEM_OWNER',
  CIRCULAR_LINK = 'CIRCULAR_LINK',
  ENTRY_NOT_FOUND = 'ENTRY_NOT_FOUND',
  GROUP_HAS_USERS = 'GROUP_HAS_USERS',
  PERMISSION_IN_USE = 'PERMISSION_IN_USE',
  IMPORT_TOO_LARGE = 'IMPORT_TOO_LARGE',
  CONCURRENT_EDIT = 'CONCURRENT_EDIT',
  PROMOTION_NOT_PENDING = 'PROMOTION_NOT_PENDING',
  COMMENT_TOO_SHORT = 'COMMENT_TOO_SHORT',
  SERVER_UNRESPONSIVE = 'SERVER_UNRESPONSIVE',
  RESTART_FAILED = 'RESTART_FAILED',
  RATE_LIMIT_EXCEEDED = 'RATE_LIMIT_EXCEEDED',
  INTERNAL_ERROR = 'INTERNAL_ERROR',
}


export interface ConfigUpdateResult { applied: boolean; requiresRestart: boolean; }

import { z } from 'zod';
import * as path from 'path';
import * as fs from 'fs';
import * as crypto from 'crypto';
import { execSync } from 'child_process';
import * as os from 'os';

export function getWorkspacePath(): string {
  // Check CLI arg --workspace first
  const args = process.argv.slice(2);
  const idx = args.indexOf('--workspace');
  if (idx >= 0 && args[idx + 1]) return path.resolve(args[idx + 1]);

  // Check env variable
  const envWs = process.env.CODE_INTEL_WORKSPACE;
  if (envWs) return path.resolve(envWs);

  return process.cwd();
}

const BackendConfigSchema = z.object({
  port: z.number().min(1024).max(65535).default(48721),
  host: z.string().default('0.0.0.0'),
  dataDir: z.string().default('.code-intel'),
  onnxModelPath: z.string().default('models/model.onnx'),
  sqliteDbPath: z.string().default('index.db'),
  orchestrationConfigPath: z.string().default('orchestration.json'),
  logLevel: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
  projectId: z.string().default('default'),
});

export type BackendConfig = z.infer<typeof BackendConfigSchema> & {
  workspace: string;
};

/**
 * Derive projectId with 3-step resolution:
 * 1. Explicit: .code-intel/project.json → projectId field
 * 2. Git remote: sha256(git remote get-url origin).slice(0, 12)
 * 3. Fallback: sha256(userId + folderName).slice(0, 12) — prevents data leak across users
 */
function deriveProjectId(workspace: string, overrides?: Partial<BackendConfig>): string {
  // Priority 0: Explicit override (e.g., from test or CLI)
  if (overrides?.projectId && overrides.projectId !== 'default') return overrides.projectId;
  const envId = process.env.CODE_INTEL_PROJECT_ID;
  if (envId) return envId;

  // Priority 1: .code-intel/project.json
  try {
    const projectJsonPath = path.resolve(workspace, '.code-intel', 'project.json');
    if (fs.existsSync(projectJsonPath)) {
      const content = JSON.parse(fs.readFileSync(projectJsonPath, 'utf-8'));
      if (content.projectId && typeof content.projectId === 'string') {
        return content.projectId;
      }
    }
  } catch (err) { console.debug('[BackendConfig] ignore parse errors :', (err as Error).message); }

  // Priority 2: Git remote origin URL hash
  try {
    const remoteUrl = execSync('git remote get-url origin', { cwd: workspace, encoding: 'utf-8', timeout: 3000 }).trim();
    if (remoteUrl) {
      return crypto.createHash('sha256').update(remoteUrl).digest('hex').slice(0, 12);
    }
  } catch (err) { console.debug('[BackendConfig] no git or no remote :', (err as Error).message); }

  // Priority 3: Hash of userId + folder name (prevents cross-user data leak)
  const userId = os.userInfo().username || 'unknown';
  const folderName = path.basename(workspace) || 'default';
  return crypto.createHash('sha256').update(`${userId}:${folderName}`).digest('hex').slice(0, 12);
}

export function loadConfig(overrides?: Partial<BackendConfig>): BackendConfig {
  const workspace = overrides?.workspace ?? getWorkspacePath();
  const raw = {
    port: parseInt(process.env.CODE_INTEL_PORT || '48721', 10),
    host: process.env.CODE_INTEL_HOST || '0.0.0.0',
    dataDir: process.env.CODE_INTEL_DATA_DIR || '.code-intel',
    onnxModelPath: process.env.CODE_INTEL_ONNX_MODEL || 'models/model.onnx',
    sqliteDbPath: process.env.CODE_INTEL_DB || 'index.db',
    orchestrationConfigPath: process.env.CODE_INTEL_ORCHESTRATION || 'orchestration.json',
    logLevel: process.env.CODE_INTEL_LOG_LEVEL || 'info',
    projectId: deriveProjectId(workspace, overrides),
    workspace,
    ...overrides,
  };

  return {
    ...BackendConfigSchema.parse(raw),
    workspace: raw.workspace,
  };
}

/**
 * PBT-01..03 — CoreTools.resolveCoreToolNames property tests (SA4E-18).
 * fast-check is NOT a project dependency, so properties are exercised with a
 * deterministic-seed random-input loop (1000 runs) mutating CORE_TOOLS contents.
 */

import { describe, it, expect, afterEach } from 'vitest';
import { CORE_TOOLS, META_TOOLS, resolveCoreToolNames } from '../CoreTools.js';

const META = [...META_TOOLS];
const original = [...CORE_TOOLS];
const RUNS = 1000;

function setCore(entries: string[]): void {
  (CORE_TOOLS as string[]).length = 0;
  (CORE_TOOLS as string[]).push(...(entries as any[]));
}

// Small deterministic PRNG (mulberry32) for reproducible random inputs.
function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const POOL = ['mem_search', 'code_search', 'find_tools', '', '   ', 'x', 'weird tool', 'a', 'b'];

function randomArray(rand: () => number): any[] {
  const len = Math.floor(rand() * 12);
  const out: any[] = [];
  for (let i = 0; i < len; i++) {
    const pick = rand();
    if (pick < 0.15) out.push('');
    else if (pick < 0.3) out.push('   ');
    else out.push(POOL[Math.floor(rand() * POOL.length)]);
  }
  return out;
}

afterEach(() => setCore(original));

describe('CoreTools property invariants', () => {
  it('PBT-01: always includes all META_TOOLS for any input', () => {
    const rand = rng(12345);
    for (let i = 0; i < RUNS; i++) {
      setCore(randomArray(rand));
      const set = resolveCoreToolNames();
      for (const m of META) expect(set.has(m)).toBe(true);
    }
  });

  it('PBT-02: output is always duplicate-free', () => {
    const rand = rng(67890);
    for (let i = 0; i < RUNS; i++) {
      setCore(randomArray(rand));
      const set = resolveCoreToolNames();
      const arr = [...set];
      expect(arr.length).toBe(new Set(arr).size);
    }
  });

  it('PBT-03: never throws; invalid entries dropped, result non-empty', () => {
    const rand = rng(24680);
    for (let i = 0; i < RUNS; i++) {
      setCore(randomArray(rand));
      let set: Set<string> | undefined;
      expect(() => { set = resolveCoreToolNames(); }).not.toThrow();
      expect(set!.size).toBeGreaterThanOrEqual(META.length);
      expect(set!.has('')).toBe(false);
      expect(set!.has('   ')).toBe(false);
    }
  });
});

