/**
 * KSA-168: Git Miner — Semantic search over git commit history.
 * Parses git log, stores commit metadata, enables text-based search.
 * SA4E-41: commits are stamped with project_id and search is tenant-scoped (fail-closed).
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import { DialectHelper } from '../../../database/dialect/DialectHelper.js';
import type { GitCommit, GitCommitResult, GitIndexSummary } from './types.js';
import { parseGitLog, getLastIndexedHash } from './GitLogParser.js';
import { buildCodeScopeFilter, requireProjectId } from '../../query/code-intel-isolation.js';

export class GitMiner {
  private adapter: DatabaseAdapter;
  private dialect: DialectHelper;
  private repoPath: string;
  private maxCommits: number;
  private projectId: string | undefined;
  private initialized: Promise<void>;

  /**
   * @param projectId  SA4E-41 tenant scope. indexHistory requires it (write);
   *   search/getSummary are fail-closed when it is missing.
   */
  constructor(adapter: DatabaseAdapter, repoPath: string, maxCommits: number = 10000, projectId?: string) {
    this.adapter = adapter;
    this.dialect = new DialectHelper(adapter.getEngine());
    this.repoPath = repoPath;
    this.maxCommits = maxCommits;
    this.projectId = projectId;
    this.initialized = this.ensureSchema();
  }

  async indexHistory(force: boolean = false): Promise<GitIndexSummary> {
    await this.initialized;
    // Writes must fail loudly when there is no tenant context.
    const pid = requireProjectId(this.projectId);
    const lastHash = force ? null : await getLastIndexedHash(this.adapter, pid);
    const commits = parseGitLog(lastHash, this.repoPath, this.maxCommits);
    if (commits.length === 0) return this.getSummary();
    const insertSql = this.dialect.insertIgnore(
      'git_commits',
      ['project_id', 'hash', 'author', 'date', 'message', 'files_changed', 'insertions', 'deletions'],
      'project_id, hash',
    );
    await this.adapter.transactionAsync(async () => {
      for (const commit of commits) {
        await this.adapter.runAsync(insertSql, [
          pid, commit.hash, commit.author, commit.date, commit.message,
          JSON.stringify(commit.filesChanged), commit.insertions, commit.deletions,
        ]);
      }
    });
    await this.recordIndexMeta(pid, commits[0].hash);
    return this.getSummary();
  }

  private async recordIndexMeta(pid: string, lastHash: string): Promise<void> {
    const metaColumns = ['project_id', 'key', 'value'];
    const metaUpsert = this.dialect.upsert('git_index_meta', metaColumns, 'project_id, key', ['value']);
    await this.adapter.runAsync(metaUpsert, [pid, 'last_indexed_hash', lastHash]);
    // For last_indexed_at, use engine-appropriate NOW() expression
    const nowSql = this.adapter.getEngine() === 'sqlite'
      ? `INSERT OR REPLACE INTO git_index_meta (project_id, key, value) VALUES (?, 'last_indexed_at', datetime('now'))`
      : `INSERT INTO git_index_meta (project_id, key, value) VALUES (?, 'last_indexed_at', NOW()) ON CONFLICT (project_id, key) DO UPDATE SET value = EXCLUDED.value`;
    await this.adapter.runAsync(nowSql, [pid]);
  }

  async search(query: string, options: { author?: string; file?: string; limit?: number; since?: string } = {}): Promise<GitCommitResult[]> {
    await this.initialized;
    const limit = options.limit ?? 10;
    const scope = buildCodeScopeFilter(this.projectId, 'git_commits'); // fail-closed
    let sql = `SELECT hash, author, date, message, files_changed, insertions, deletions FROM git_commits WHERE ${scope.clause}`;
    const params: unknown[] = [...scope.params];
    if (query) {
      sql += ` AND (message LIKE ? OR files_changed LIKE ?)`;
      params.push(`%${query}%`, `%${query}%`);
    }
    if (options.author) { sql += ` AND author LIKE ?`; params.push(`%${options.author}%`); }
    if (options.file) { sql += ` AND files_changed LIKE ?`; params.push(`%${options.file}%`); }
    if (options.since) { sql += ` AND date >= ?`; params.push(options.since); }
    sql += ` ORDER BY date DESC LIMIT ?`;
    params.push(limit);
    const rows = await this.adapter.allAsync<{
      hash: string; author: string; date: string; message: string;
      files_changed: string; insertions: number; deletions: number;
    }>(sql, params);
    return rows.map((row, idx) => ({
      hash: row.hash, author: row.author, date: row.date, message: row.message,
      filesChanged: JSON.parse(row.files_changed), insertions: row.insertions,
      deletions: row.deletions, score: 1.0 - (idx * 0.05),
    }));
  }

  async getSummary(): Promise<GitIndexSummary> {
    await this.initialized;
    if (!this.projectId) {
      return { totalCommits: 0, indexed: 0, lastHash: null, lastIndexedAt: null };
    }
    const countRow = await this.adapter.getAsync<{ count: number }>(
      `SELECT COUNT(*) as count FROM git_commits WHERE project_id = ?`,
      [this.projectId],
    );
    const meta = async (key: string) => {
      const row = await this.adapter.getAsync<{ value: string }>(
        `SELECT value FROM git_index_meta WHERE key = ? AND project_id = ?`,
        [key, this.projectId],
      );
      return row?.value ?? null;
    };
    return {
      totalCommits: countRow?.count ?? 0, indexed: countRow?.count ?? 0,
      lastHash: await meta('last_indexed_hash'), lastIndexedAt: await meta('last_indexed_at'),
    };
  }

  /** Create git tables if they don't exist (async, cross-engine). */
  private async ensureSchema(): Promise<void> {
    await this.adapter.execAsync(`
      CREATE TABLE IF NOT EXISTS git_commits (
        project_id TEXT NOT NULL DEFAULT '',
        hash TEXT NOT NULL,
        author TEXT NOT NULL,
        date TEXT NOT NULL,
        message TEXT NOT NULL,
        files_changed TEXT NOT NULL DEFAULT '[]',
        insertions INTEGER DEFAULT 0,
        deletions INTEGER DEFAULT 0,
        PRIMARY KEY (project_id, hash)
      );
      CREATE INDEX IF NOT EXISTS idx_git_date ON git_commits(date);
      CREATE INDEX IF NOT EXISTS idx_git_author ON git_commits(author);
      CREATE INDEX IF NOT EXISTS idx_git_project ON git_commits(project_id);
      CREATE TABLE IF NOT EXISTS git_index_meta (
        project_id TEXT NOT NULL DEFAULT '',
        key TEXT NOT NULL,
        value TEXT NOT NULL,
        PRIMARY KEY (project_id, key)
      );
    `);
    await this.migrateLegacyGitSchema();
  }

  /** Add project_id to pre-SA4E-41 git tables when missing (idempotent, async). */
  private async migrateLegacyGitSchema(): Promise<void> {
    const colQuery = this.dialect.columnExistsQuery('git_commits');
    const cols = await this.adapter.allAsync<{ name: string }>(colQuery);
    if (!cols.some(c => c.name === 'project_id')) {
      await this.adapter.execAsync(`ALTER TABLE git_commits ADD COLUMN project_id TEXT NOT NULL DEFAULT ''`);
    }
    const metaColQuery = this.dialect.columnExistsQuery('git_index_meta');
    const metaCols = await this.adapter.allAsync<{ name: string }>(metaColQuery);
    if (!metaCols.some(c => c.name === 'project_id')) {
      await this.adapter.execAsync(`ALTER TABLE git_index_meta ADD COLUMN project_id TEXT NOT NULL DEFAULT ''`);
    }
  }
}

/**
 * KSA-168: MCP Tool registrations for similarity & mining tools.
 * SA4E-45: Refactored to accept DatabaseAdapter.
 */

import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import { DuplicateDetector } from './DuplicateDetector.js';
import { DeadCodeDetector } from './DeadCodeDetector.js';
import { GitMiner } from './GitMiner.js';

export const SIMILARITY_TOOL_DEFINITIONS = [
  { name: 'find_duplicates', description: 'Find near-duplicate functions using embedding similarity. Groups similar code into clusters with refactoring suggestions.', inputSchema: { type: 'object', properties: { file_path: { type: 'string', description: 'Filter by file path' }, module: { type: 'string', description: 'Filter by module name' }, min_similarity: { type: 'number', description: 'Minimum similarity threshold (default: 0.85)' }, limit: { type: 'number', description: 'Max clusters to return (default: 20)' } } } },
  { name: 'find_dead_code', description: 'Find potentially dead/unreachable code using call graph reachability analysis from entry points.', inputSchema: { type: 'object', properties: { file_path: { type: 'string', description: 'Filter by file path' }, module: { type: 'string', description: 'Filter by module name' }, min_confidence: { type: 'number', description: 'Minimum confidence threshold 0-100 (default: 60)' }, limit: { type: 'number', description: 'Max results (default: 50)' } } } },
  { name: 'git_search', description: 'Search git commit history by message, author, or file. Returns matching commits with metadata.', inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'Search query (matches message and file names)' }, author: { type: 'string', description: 'Filter by author name' }, file: { type: 'string', description: 'Filter by file path' }, since: { type: 'string', description: 'Only commits after this date (ISO format)' }, limit: { type: 'number', description: 'Max results (default: 10)' } }, required: ['query'] } },
  { name: 'git_index', description: 'Index git commit history for searching. Incremental by default.', inputSchema: { type: 'object', properties: { force: { type: 'boolean', description: 'Force full re-index (default: false)' } } } },
];

/** Dispatch a similarity/mining tool call (SA4E-41: tenant-scoped, fail-closed). */
export async function handleSimilarityTool(
  name: string, args: Record<string, unknown>, adapter: DatabaseAdapter, workspacePath: string, projectId?: string
): Promise<string | null> {
  switch (name) {
    case 'find_duplicates': return handleFindDuplicates(args, adapter, projectId);
    case 'find_dead_code': return handleFindDeadCode(args, adapter, projectId);
    case 'git_search': return handleGitSearch(args, adapter, workspacePath, projectId);
    case 'git_index': return handleGitIndex(args, adapter, workspacePath, projectId);
    default: return null;
  }
}

async function handleFindDuplicates(args: Record<string, unknown>, adapter: DatabaseAdapter, projectId?: string): Promise<string> {
  const minSimilarity = (args.min_similarity as number) ?? 0.85;
  const detector = new DuplicateDetector(adapter, minSimilarity, 5, projectId);
  const report = await detector.detect({ filePath: args.file_path as string | undefined, module: args.module as string | undefined, limit: args.limit as number | undefined });
  if (report.clusters.length === 0) return `No duplicate code found (scanned ${report.totalPairsScanned} pairs in ${report.scanDurationMs}ms).`;
  const lines = [`Found ${report.clusters.length} duplicate clusters (${report.totalDuplicates} functions) in ${report.scanDurationMs}ms:\n`];
  for (const cluster of report.clusters) {
    lines.push(`🔄 ${cluster.id} (avg similarity: ${(cluster.avgSimilarity * 100).toFixed(1)}%)`);
    lines.push(`   💡 ${cluster.suggestion}`);
    for (const member of cluster.members) { lines.push(`   - ${member.name} — ${member.filePath}:${member.startLine}`); }
    lines.push('');
  }
  return lines.join('\n');
}

async function handleFindDeadCode(args: Record<string, unknown>, adapter: DatabaseAdapter, projectId?: string): Promise<string> {
  const minConfidence = (args.min_confidence as number) ?? 60;
  const detector = new DeadCodeDetector(adapter, minConfidence, projectId);
  const report = await detector.detect({ filePath: args.file_path as string | undefined, module: args.module as string | undefined, limit: args.limit as number | undefined });
  if (report.candidates.length === 0) return `No dead code found (${report.totalFunctions} functions, ${report.reachableCount} reachable).`;
  const lines = [`Found ${report.candidates.length} potentially dead functions (${report.unreachableCount}/${report.totalFunctions} unreachable, ${report.scanDurationMs}ms):\n`];
  for (const candidate of report.candidates) {
    const conf = candidate.confidence >= 80 ? '🔴' : candidate.confidence >= 60 ? '🟡' : '⚪';
    lines.push(`${conf} ${candidate.name} (${candidate.kind}) — confidence: ${candidate.confidence}%`);
    lines.push(`   ${candidate.filePath}:${candidate.startLine}`);
    lines.push(`   Reasons: ${candidate.reasons.join(', ')}`);
  }
  return lines.join('\n');
}

async function handleGitSearch(args: Record<string, unknown>, adapter: DatabaseAdapter, workspacePath: string, projectId?: string): Promise<string> {
  const query = args.query as string;
  if (!query) return 'Parameter "query" is required.';
  const miner = new GitMiner(adapter, workspacePath, 10000, projectId);
  const results = await miner.search(query, { author: args.author as string | undefined, file: args.file as string | undefined, since: args.since as string | undefined, limit: args.limit as number | undefined });
  if (results.length === 0) return `No commits found matching "${query}".`;
  const lines = [`Found ${results.length} commits matching "${query}":\n`];
  for (const commit of results) {
    lines.push(`${commit.hash.slice(0, 8)} | ${commit.date.slice(0, 10)} | ${commit.author}`);
    lines.push(`  ${commit.message}`);
    lines.push(`  Files: ${commit.filesChanged.slice(0, 5).join(', ')}${commit.filesChanged.length > 5 ? ` (+${commit.filesChanged.length - 5} more)` : ''}`);
    lines.push(`  +${commit.insertions} -${commit.deletions}`);
    lines.push('');
  }
  return lines.join('\n');
}

async function handleGitIndex(args: Record<string, unknown>, adapter: DatabaseAdapter, workspacePath: string, projectId?: string): Promise<string> {
  const force = (args.force as boolean) ?? false;
  const miner = new GitMiner(adapter, workspacePath, 10000, projectId);
  try {
    const summary = await miner.indexHistory(force);
    return [`Git history indexed:`, `  Total commits: ${summary.totalCommits}`, `  Last hash: ${summary.lastHash?.slice(0, 8) ?? 'none'}`, `  Last indexed: ${summary.lastIndexedAt ?? 'never'}`].join('\n');
  } catch (err: any) {
    if (String(err?.message).startsWith('PROJECT_REQUIRED')) return JSON.stringify({ error: 'X-Project-Id required to index git history' });
    throw err;
  }
}

/**
 * AIContextService unit tests — orchestration, budget enforcement, not-found path.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import * as os from 'os';
import * as path from 'path';
import { AIContextService } from '../ai-context-service.js';
import type { AIContextParams } from '../types.js';

type RowGetter = (sql: string, args: unknown[]) => unknown;
type RowAller = (sql: string, args: unknown[]) => unknown[];

function makeAdapter(get?: RowGetter, all?: RowAller) {
  return {
    prepare: (sql: string) => ({
      get: (...args: unknown[]) => (get ? get(sql, args) : undefined),
      all: (...args: unknown[]) => (all ? all(sql, args) : []),
    }),
  };
}

const SYMBOL = {
  id: 1,
  name: 'fetchUser',
  kind: 'function',
  filePath: 'src/fetch-user.ts',
  line: 10,
  parentSymbolId: null,
};

let workspace: string;

beforeEach(() => {
  workspace = path.join(os.tmpdir(), `sa4e-ai-context-${Date.now()}-${Math.random()}`);
});

function buildService(db: any, resolver: any, callGraph: any) {
  return new AIContextService(db, resolver, callGraph, workspace);
}

describe('AIContextService.getContext', () => {
  it('returns a not-found response with suggestions when resolution fails', async () => {
    const resolver = { resolve: vi.fn(async () => []), suggest: vi.fn(async () => ['nearMatch']) };
    const callGraph = { findCallers: vi.fn(), findCallees: vi.fn() };
    const service = buildService(makeAdapter(), resolver, callGraph);

    const res = await service.getContext({ symbol: 'missing', intent: 'explain', token_budget: 1000 });
    expect(res.symbol).toBe('missing');
    expect(res.kind).toBe('unknown');
    expect(res.context.error).toContain('missing');
    expect(res.context.suggestions).toEqual(['nearMatch']);
    expect(res.metadata.budget_used).toBe(0);
    expect(res.metadata.budget_total).toBe(1000);
    expect(resolver.suggest).toHaveBeenCalled();
  });

  it('assembles db-backed and graph-backed sections for the explain intent', async () => {
    const db = makeAdapter(
      (sql) => (sql.includes('doc_comment') ? { doc_comment: 'Loads a user by id.' } : undefined),
      (sql) => {
        if (sql.includes('parent_symbol_id')) return [{ name: 'siblingFn', kind: 'function', signature: 'siblingFn()', line: 20 }];
        if (sql.includes('r.kind = \'imports\'')) return [{ name: 'lodash', file_path: 'node_modules/lodash' }];
        if (sql.includes('type_alias')) return [{ name: 'UserDTO', kind: 'interface', signature: 'UserDTO', file: 'src/types.ts' }];
        return [];
      },
    );
    const resolver = { resolve: vi.fn(async () => [SYMBOL]), suggest: vi.fn(async () => []) };
    const callGraph = {
      findCallers: vi.fn(async () => ({ results: [] })),
      findCallees: vi.fn(async () => ({ results: [] })),
    };
    const service = buildService(db, resolver, callGraph);

    const res = await service.getContext({ symbol: 'fetchUser', intent: 'explain', token_budget: 4000 });
    expect(res.symbol).toBe('fetchUser');
    expect(res.file_path).toBe('src/fetch-user.ts');
    expect(res.kind).toBe('function');
    expect(res.intent).toBe('explain');
    expect(res.context.doc_comment).toBe('Loads a user by id.');
    expect(res.context.siblings).toEqual([{ name: 'siblingFn', kind: 'function', signature: 'siblingFn()', line: 20 }]);
    expect(res.context.imports).toEqual(['lodash']);
    expect(res.context.type_definitions).toEqual([{ name: 'UserDTO', kind: 'interface', signature: 'UserDTO', file: 'src/types.ts' }]);
    expect(res.metadata.sections_included).toEqual(expect.arrayContaining(['doc_comment', 'siblings', 'imports', 'type_definitions']));
    expect(res.metadata.sections_included[0]).toBe('doc_comment');
    expect(res.metadata.sections_omitted).toEqual([]);
    expect(res.metadata.budget_used).toBeGreaterThan(0);
    expect(res.metadata.budget_total).toBe(4000);
  });

  it('omits remaining sections once the budget is exhausted', async () => {
    const db = makeAdapter(
      (sql) => (sql.includes('doc_comment') ? { doc_comment: 'x'.repeat(10000) } : undefined),
      () => [{ name: 'siblingFn' }],
    );
    const resolver = { resolve: vi.fn(async () => [SYMBOL]), suggest: vi.fn(async () => []) };
    const callGraph = {
      findCallers: vi.fn(async () => ({ results: [] })),
      findCallees: vi.fn(async () => ({ results: [] })),
    };
    const service = buildService(db, resolver, callGraph);

    const res = await service.getContext({ symbol: 'fetchUser', intent: 'explain', token_budget: 800 });
    expect(res.context.doc_comment).toContain('(truncated)');
    expect(res.context.doc_comment_truncated).toBe(true);
    expect(res.metadata.sections_included).toEqual(['doc_comment']);
    expect(res.metadata.sections_omitted).toEqual(['siblings', 'imports', 'callers', 'callees', 'type_definitions']);
    expect(res.metadata.budget_used).toBe(800);
  });

  it('defaults intent and budget when parameters are omitted', async () => {
    const db = makeAdapter(
      (sql) => (sql.includes('doc_comment') ? { doc_comment: 'short' } : undefined),
      () => [],
    );
    const resolver = { resolve: vi.fn(async () => [SYMBOL]), suggest: vi.fn(async () => []) };
    const callGraph = {
      findCallers: vi.fn(async () => ({ results: [] })),
      findCallees: vi.fn(async () => ({ results: [] })),
    };
    const service = buildService(db, resolver, callGraph);

    const res = await service.getContext({ symbol: 'fetchUser' } as AIContextParams);
    expect(res.intent).toBe('explain');
    expect(res.metadata.budget_total).toBe(4000);
  });
});

/**
 * RRFMerger unit tests — Reciprocal Rank Fusion across code/memory/graph sources.
 */

import { describe, it, expect } from 'vitest';
import { RRFMerger } from '../rrf-merger.js';
import type { SourceWeights } from '../types.js';

const merger = new RRFMerger();
const K = 60;

function source(name: string, results: any[]) {
  return { source: name, results };
}

describe('RRFMerger.merge', () => {
  it('returns results sorted by descending score', () => {
    const out = merger.merge({
      code: source('code', [{ id: 1, name: 'a' }, { id: 2, name: 'b' }]),
      memory: source('memory', []),
      graph: source('graph', []),
    });
    expect(out.length).toBe(2);
    expect(out[0].relevance_score).toBeGreaterThanOrEqual(out[1].relevance_score);
    expect(out[0].sources).toEqual(['code']);
    expect(out[1].sources).toEqual(['code']);
  });

  it('fuses the same item appearing in multiple sources', () => {
    const out = merger.merge({
      code: source('code', [{ id: 7, name: 'shared' }]),
      memory: source('memory', [{ id: 7, name: 'shared' }]),
      graph: source('graph', []),
    });
    expect(out.length).toBe(1);
    expect(out[0].relevance_score).toBeCloseTo(0.5 / K + 0.3 / K);
    expect(out[0].sources).toEqual(['code', 'memory']);
  });

  it('ranks earlier results higher within a single source', () => {
    const out = merger.merge({
      code: source('code', [{ id: 1, name: 'top' }, { id: 2, name: 'second' }]),
      memory: source('memory', []),
      graph: source('graph', []),
    });
    expect(out[0].relevance_score).toBeCloseTo(0.5 / K);
    expect(out[1].relevance_score).toBeCloseTo(0.5 / (K + 1));
  });

  it('applies custom weights', () => {
    const weights: SourceWeights = { code: 1.0, memory: 0, graph: 0 };
    const out = merger.merge({
      code: source('code', [{ id: 1, name: 'only-code' }]),
      memory: source('memory', [{ id: 1, name: 'only-code' }]),
      graph: source('graph', [{ id: 1, name: 'only-code' }]),
    }, weights);
    expect(out[0].relevance_score).toBeCloseTo(1 / K);
  });

  it('dedupes items keyed by name+file when no id exists', () => {
    const out = merger.merge({
      code: source('code', [{ name: 'fn', file: 'src/a.ts' }]),
      memory: source('memory', [{ name: 'fn', file: 'src/a.ts' }]),
      graph: source('graph', []),
    });
    expect(out.length).toBe(1);
    expect(out[0].sources).toEqual(['code', 'memory']);
  });

  it('keys by name alone when file is missing', () => {
    const out = merger.merge({
      code: source('code', [{ name: 'lone' }]),
      memory: source('memory', [{ name: 'lone' }]),
      graph: source('graph', []),
    });
    expect(out.length).toBe(1);
    expect(out[0].sources).toEqual(['code', 'memory']);
  });

  it('falls back to serialized content for nameless items', () => {
    const out = merger.merge({
      code: source('code', [{ kind: 'expr', x: 1 }]),
      memory: source('memory', [{ kind: 'expr', x: 1 }]),
      graph: source('graph', []),
    });
    expect(out.length).toBe(1);
    expect(out[0].sources).toEqual(['code', 'memory']);
  });

  it('spreads item fields and stamps relevance_score and sources', () => {
    const out = merger.merge({
      code: source('code', [{ id: 3, name: 'thing', kind: 'class', line: 12 }]),
      memory: source('memory', []),
      graph: source('graph', []),
    });
    expect(out[0]).toMatchObject({ id: 3, name: 'thing', kind: 'class', line: 12 });
    expect(out[0].sources).toEqual(['code']);
    expect(typeof out[0].relevance_score).toBe('number');
  });

  it('returns an empty list when all sources are empty', () => {
    expect(merger.merge({ code: source('code', []), memory: source('memory', []), graph: source('graph', []) })).toEqual([]);
  });
});

/**
 * KSA-158: AI Context Service — intent-aware context assembly with token budgeting.
 * Orchestrates symbol resolution, section fetching, and budget management.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver } from '../graph/symbol-resolver.js';
import { CallGraphService } from '../graph/call-graph-service.js';
import { TokenBudgetManager } from './token-budget-manager.js';
import { getStrategy } from './intent-strategies.js';
import { GitService } from './git-service.js';
import { AIContextParams, AIContextResponse } from './types.js';
import { fetchSection, notFoundResponse } from './context-sections.js';

export class AIContextService {
  private adapter: DatabaseAdapter;
  private resolver: SymbolResolver;
  private callGraph: CallGraphService;
  private gitService: GitService;
  private workspace: string;

  constructor(
    adapter: DatabaseAdapter,
    resolver: SymbolResolver,
    callGraph: CallGraphService,
    workspace: string
  ) {
    this.adapter = adapter;
    this.resolver = resolver;
    this.callGraph = callGraph;
    this.gitService = new GitService(workspace);
    this.workspace = workspace;
  }

  /** Get intent-aware context for a symbol within token budget. */
  async getContext(params: AIContextParams): Promise<AIContextResponse> {
    const startTime = Date.now();
    const { symbol, intent = 'explain', token_budget = 4000, caller_depth = 1 } = params;

    const resolved = await this.resolver.resolve(symbol);
    if (resolved.length === 0) {
      return notFoundResponse(symbol, intent, token_budget, startTime, this.resolver);
    }

    const targetSymbol = resolved[0];
    const strategy = getStrategy(intent);

    const budgetManager = new TokenBudgetManager(token_budget);
    const context: Record<string, any> = {};
    const sectionsIncluded: string[] = [];
    const sectionsOmitted: string[] = [];

    for (const section of strategy.sections) {
      if (budgetManager.isExhausted()) {
        sectionsOmitted.push(section.name);
        continue;
      }

      const content = fetchSection(section, targetSymbol, caller_depth, this.adapter, this.callGraph, this.resolver, this.gitService, this.workspace);
      if (content == null) {
        continue;
      }

      const tokens = budgetManager.estimateTokens(content);

      if (budgetManager.canFit(tokens)) {
        context[section.name] = content;
        budgetManager.consume(tokens);
        sectionsIncluded.push(section.name);
      } else if (budgetManager.remaining() > 100) {
        const truncated = budgetManager.truncateToFit(content);
        context[section.name] = truncated;
        context[`${section.name}_truncated`] = true;
        budgetManager.consumeAll();
        sectionsIncluded.push(section.name);
      } else {
        sectionsOmitted.push(section.name);
      }
    }

    return {
      symbol: targetSymbol.name,
      file_path: targetSymbol.filePath,
      kind: targetSymbol.kind,
      intent,
      context,
      metadata: {
        budget_used: budgetManager.used(),
        budget_total: token_budget,
        sections_included: sectionsIncluded,
        sections_omitted: sectionsOmitted,
        query_time_ms: Date.now() - startTime
      }
    };
  }
}

/**
 * KSA-160: Budget Allocator — allocates token budget across ranked results.
 * Top results get full source, middle get signatures, bottom get references.
 */

import { MergedResult, ContextItem } from './types.js';

export interface AllocatedResult extends MergedResult {
  detail: 'full' | 'signature' | 'reference';
  content: string;
  tokens: number;
}

export class BudgetAllocator {
  private CHARS_PER_TOKEN = 4;

  /** Allocate token budget across merged results with progressive detail levels. */
  allocate(results: MergedResult[], maxTokens: number): AllocatedResult[] {
    const allocated: AllocatedResult[] = [];
    let tokensUsed = 100; // Response overhead

    const highThreshold = Math.max(1, Math.ceil(results.length * 0.2));
    const medThreshold = Math.ceil(results.length * 0.6);

    for (let i = 0; i < results.length; i++) {
      if (tokensUsed >= maxTokens) break;

      const result = results[i];
      let detail: 'full' | 'signature' | 'reference';
      let content: string;
      let tokens: number;

      if (i < highThreshold) {
        detail = 'full';
        content = result.source_code || result.content || result.signature || result.name;
        tokens = this.estimateTokens(content);
      } else if (i < medThreshold) {
        detail = 'signature';
        content = result.signature || result.name;
        tokens = this.estimateTokens(content);
      } else {
        detail = 'reference';
        content = `${result.name} (${result.file || 'unknown'}:${result.line || 0})`;
        tokens = 15;
      }

      // Downgrade if exceeds budget
      if (tokensUsed + tokens > maxTokens && detail === 'full') {
        detail = 'signature';
        content = result.signature || result.name;
        tokens = this.estimateTokens(content);
      }

      if (tokensUsed + tokens <= maxTokens) {
        allocated.push({ ...result, detail, content, tokens });
        tokensUsed += tokens;
      }
    }

    return allocated;
  }

  private estimateTokens(text: string): number {
    return Math.ceil(text.length / this.CHARS_PER_TOKEN);
  }
}

import * as fs from 'fs';
import * as path from 'path';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver, ResolvedSymbol } from '../graph/symbol-resolver.js';
import { CallGraphService } from '../graph/call-graph-service.js';
import { GitService } from './git-service.js';
import { SectionDef } from './intent-strategies.js';
import { AIContextResponse } from './types.js';

export function fetchSection(
  section: SectionDef,
  symbol: ResolvedSymbol,
  callerDepth: number,
  db: DatabaseAdapter,
  callGraph: CallGraphService,
  resolver: SymbolResolver,
  gitService: GitService,
  workspace: string
): any {
  try {
    switch (section.name) {
      case 'source': return fetchSource(symbol, workspace, db);
      case 'callers': return fetchCallers(symbol, callerDepth, section.format, callGraph);
      case 'callees': return fetchCallees(symbol, callerDepth, callGraph);
      case 'siblings': return fetchSiblings(symbol, db);
      case 'imports': return fetchImports(symbol, db);
      case 'tests': return fetchRelatedTests(symbol, db);
      case 'type_definitions': return fetchTypeDefinitions(symbol, db);
      case 'doc_comment': return fetchDocComment(symbol, db);
      case 'error_patterns': return fetchErrorPatterns(symbol, db, workspace);
      case 'recent_changes': return fetchRecentChanges(symbol, gitService);
      case 'test_patterns': return fetchTestPatterns(symbol, db);
      case 'mocks_needed': return fetchMocksNeeded(symbol, callGraph);
      default: return null;
    }
  } catch {
    return null;
  }
}

export function getSymbolEndLine(symbol: ResolvedSymbol, db: DatabaseAdapter): number | null {
  const row = db.prepare(`SELECT end_line FROM symbols WHERE id = ?`).get(symbol.id) as { end_line: number } | undefined;
  return row?.end_line || null;
}

export function fetchSource(symbol: ResolvedSymbol, workspace: string, db: DatabaseAdapter): string | null {
  try {
    const fullPath = path.resolve(workspace, symbol.filePath);
    if (!fs.existsSync(fullPath)) return null;
    const content = fs.readFileSync(fullPath, 'utf-8');
    const lines = content.split('\n');
    const startLine = symbol.line - 1;
    const endLine = getSymbolEndLine(symbol, db) || startLine + 50;
    return lines.slice(startLine, endLine).join('\n');
  } catch {
    return null;
  }
}

export async function fetchCallers(symbol: ResolvedSymbol, depth: number, format: string, callGraph: CallGraphService): Promise<any> {
  const result = await callGraph.findCallers(symbol.name, depth, 10);
  if (result.results.length === 0) return null;
  if (format === 'summary') {
    return result.results.map(r => `${r.symbol} (${r.filePath}:${r.callSiteLine})`);
  }
  return result.results.map(r => ({
    symbol: r.symbol, file: r.filePath, line: r.callSiteLine, kind: r.kind
  }));
}

export async function fetchCallees(symbol: ResolvedSymbol, depth: number, callGraph: CallGraphService): Promise<any> {
  const result = await callGraph.findCallees(symbol.name, depth, 10);
  if (result.results.length === 0) return null;
  return result.results.map(r => ({
    symbol: r.symbol, file: r.filePath, line: r.callSiteLine, kind: r.kind
  }));
}

export function fetchSiblings(symbol: ResolvedSymbol, db: DatabaseAdapter): any {
  const query = symbol.parentSymbolId
    ? `SELECT name, kind, signature, start_line as line FROM symbols WHERE parent_symbol_id = ? AND id != ? ORDER BY start_line`
    : `SELECT s.name, s.kind, s.signature, s.start_line as line FROM symbols s JOIN files f ON s.file_id = f.id WHERE f.relative_path = ? AND s.parent_symbol_id IS NULL AND s.id != ? ORDER BY s.start_line`;

  const params = symbol.parentSymbolId
    ? [symbol.parentSymbolId, symbol.id]
    : [symbol.filePath, symbol.id];

  const rows = db.prepare(query).all(...params) as any[];
  if (rows.length === 0) return null;
  return rows.map(r => ({ name: r.name, kind: r.kind, signature: r.signature, line: r.line }));
}

export function fetchImports(symbol: ResolvedSymbol, db: DatabaseAdapter): any {
  const rows = db.prepare(`
    SELECT DISTINCT r.target_symbol as name, r.file_path
    FROM relationships r
    WHERE r.source_symbol_id = ? AND r.kind = 'imports'
  `).all(symbol.id) as any[];
  if (rows.length === 0) return null;
  return rows.map(r => r.name);
}

export function fetchRelatedTests(symbol: ResolvedSymbol, db: DatabaseAdapter): any {
  const rows = db.prepare(`
    SELECT DISTINCT f.relative_path as file_path
    FROM relationships r
    JOIN files f ON r.file_path = f.relative_path
    WHERE r.target_symbol LIKE ?
    AND (f.relative_path LIKE '%test%' OR f.relative_path LIKE '%spec%')
    LIMIT 5
  `).all(`%${symbol.name}%`) as any[];
  if (rows.length === 0) return null;
  return rows.map(r => r.file_path);
}

export function fetchTypeDefinitions(symbol: ResolvedSymbol, db: DatabaseAdapter): any {
  const rows = db.prepare(`
    SELECT DISTINCT s.name, s.kind, s.signature, f.relative_path as file
    FROM relationships r
    JOIN symbols s ON s.id = r.target_symbol_id
    JOIN files f ON s.file_id = f.id
    WHERE r.source_symbol_id = ? AND s.kind IN ('interface', 'type_alias', 'enum', 'class')
    LIMIT 10
  `).all(symbol.id) as any[];
  if (rows.length === 0) return null;
  return rows;
}

export function fetchDocComment(symbol: ResolvedSymbol, db: DatabaseAdapter): string | null {
  const row = db.prepare(`SELECT doc_comment FROM symbols WHERE id = ?`).get(symbol.id) as { doc_comment: string | null } | undefined;
  return row?.doc_comment || null;
}

export function fetchErrorPatterns(symbol: ResolvedSymbol, db: DatabaseAdapter, workspace: string): any {
  const source = fetchSource(symbol, workspace, db);
  if (!source) return null;
  const patterns: any[] = [];
  const lines = source.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.startsWith('throw ')) patterns.push({ type: 'throw', line: i + 1, text: line });
    if (line.startsWith('catch')) patterns.push({ type: 'catch', line: i + 1, text: line });
    if (line.includes('.catch(')) patterns.push({ type: 'promise-catch', line: i + 1, text: line });
  }
  return patterns.length > 0 ? patterns : null;
}

export function fetchRecentChanges(symbol: ResolvedSymbol, gitService: GitService): any {
  const commits = gitService.getFileHistory(symbol.filePath, 5);
  return commits.length > 0 ? commits : null;
}

export function fetchTestPatterns(symbol: ResolvedSymbol, db: DatabaseAdapter): any {
  const rows = db.prepare(`
    SELECT DISTINCT s.name, s.signature
    FROM symbols s
    JOIN files f ON s.file_id = f.id
    WHERE (f.relative_path LIKE '%test%' OR f.relative_path LIKE '%spec%')
    AND s.kind = 'function'
    AND f.module = (SELECT module FROM files WHERE relative_path = ?)
    LIMIT 10
  `).all(symbol.filePath) as any[];
  if (rows.length === 0) return null;
  return rows.map(r => r.name);
}

export async function fetchMocksNeeded(symbol: ResolvedSymbol, callGraph: CallGraphService): Promise<any> {
  const result = await callGraph.findCallees(symbol.name, 1, 20);
  if (result.results.length === 0) return null;
  const externalDeps = result.results
    .filter(r => r.filePath !== symbol.filePath && r.filePath !== '(external)')
    .map(r => ({ symbol: r.symbol, file: r.filePath }));
  return externalDeps.length > 0 ? externalDeps : null;
}

export async function notFoundResponse(
  symbol: string,
  intent: string,
  budget: number,
  startTime: number,
  resolver: SymbolResolver
): Promise<AIContextResponse> {
  const suggestions = await resolver.suggest(symbol);
  return {
    symbol,
    file_path: '',
    kind: 'unknown',
    intent,
    context: { error: `Symbol "${symbol}" not found`, suggestions },
    metadata: {
      budget_used: 0,
      budget_total: budget,
      sections_included: [],
      sections_omitted: [],
      query_time_ms: Date.now() - startTime
    }
  };
}

/**
 * KSA-160: Curated Context Service — NL query → parallel search → RRF merge → budget allocation.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { QueryAnalyzer } from './query-analyzer.js';
import { RRFMerger } from './rrf-merger.js';
import { BudgetAllocator } from './budget-allocator.js';
import { SymbolResolver } from '../graph/symbol-resolver.js';
import { GraphTraverser } from '../graph/traverser.js';
import { QueryLayer } from '../query/query-layer.js';
import { CuratedContextParams, CuratedContextResponse } from './types.js';
import { searchCode, searchMemory, expandGraph, formatSections } from './curated-helpers.js';

export class CuratedContextService {
  private analyzer: QueryAnalyzer;
  private merger: RRFMerger;
  private allocator: BudgetAllocator;
  private adapter: DatabaseAdapter;
  private queryLayer: QueryLayer;
  private traverser: GraphTraverser;
  private resolver: SymbolResolver;

  constructor(
    adapter: DatabaseAdapter,
    queryLayer: QueryLayer,
    traverser: GraphTraverser,
    resolver: SymbolResolver
  ) {
    this.analyzer = new QueryAnalyzer();
    this.merger = new RRFMerger();
    this.allocator = new BudgetAllocator();
    this.adapter = adapter;
    this.queryLayer = queryLayer;
    this.traverser = traverser;
    this.resolver = resolver;
  }

  /** Execute curated context search with NL query. */
  async getContext(params: CuratedContextParams): Promise<CuratedContextResponse> {
    const startTime = Date.now();
    const {
      query,
      max_tokens = 4000,
      include_source = true,
      include_memory = true,
      include_graph = true,
      source_weights,
      projectId
    } = params;

    const analysis = this.analyzer.analyze(query);

    const [codeResults, memoryResults] = await Promise.all([
      include_source ? searchCode(analysis, this.queryLayer, this.resolver, projectId) : Promise.resolve({ source: 'code', results: [] }),
      include_memory ? searchMemory(analysis, this.adapter, projectId) : Promise.resolve({ source: 'memory', results: [] })
    ]);

    let graphResults = { source: 'graph', results: [] as any[] };
    if (include_graph && codeResults.results.length > 0) {
      graphResults = await expandGraph(codeResults.results.slice(0, 5), this.traverser);
    }

    const merged = this.merger.merge(
      { code: codeResults, memory: memoryResults, graph: graphResults },
      source_weights
    );

    const allocated = this.allocator.allocate(merged, max_tokens);

    const sections = formatSections(allocated);
    const tokensUsed = allocated.reduce((sum, r) => sum + r.tokens, 0) + 100;

    return {
      query,
      sections,
      metadata: {
        tokens_used: tokensUsed,
        tokens_budget: max_tokens,
        sources_queried: [
          ...(include_source ? ['code'] : []),
          ...(include_memory ? ['memory'] : []),
          ...(include_graph ? ['graph'] : [])
        ],
        total_candidates: codeResults.results.length + memoryResults.results.length + graphResults.results.length,
        results_returned: allocated.length,
        execution_time_ms: Date.now() - startTime
      }
    };
  }
}

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver } from '../graph/symbol-resolver.js';
import { GraphTraverser } from '../graph/traverser.js';
import { QueryLayer } from '../query/query-layer.js';
import { QueryAnalysis } from './types.js';
import { BudgetAllocator, AllocatedResult } from './budget-allocator.js';
import { ContextSection, ContextItem } from './types.js';

export async function searchCode(
  analysis: { ftsQuery: string; symbolCandidates: string[] },
  queryLayer: QueryLayer,
  resolver: SymbolResolver,
  projectId?: string
): Promise<{ source: string; results: any[] }> {
  try {
    const ftsResults = await queryLayer.searchCode(projectId, analysis.ftsQuery, 30);

    const symbolResults: any[] = [];
    for (const candidate of analysis.symbolCandidates.slice(0, 5)) {
      const resolved = await resolver.resolve(candidate);
      for (const sym of resolved.slice(0, 3)) {
        symbolResults.push({
          id: sym.id, name: sym.name, kind: sym.kind,
          file: sym.filePath, line: sym.line, signature: null
        });
      }
    }

    const combined = miniRRF(
      ftsResults.map(r => ({
        id: undefined, name: r.name, kind: r.kind, file: r.filePath,
        line: r.startLine, signature: r.signature, source_code: null
      })),
      symbolResults
    );

    return { source: 'code', results: combined.slice(0, 20) };
  } catch (err) {
    return { source: 'code', results: [] };
  }
}

export async function searchMemory(
  analysis: { ftsQuery: string; keywords: string[] },
  db: DatabaseAdapter,
  projectId?: string
): Promise<{ source: string; results: any[] }> {
  try {
    // SA4E-41 §6.4: fail-closed — never search the shared KB without a tenant scope.
    if (!projectId) return { source: 'memory', results: [] };
    const query = analysis.keywords.slice(0, 5).join(' ');
    // Scope KB results to the tenant's project_id (mirrors the memory IsolationLayer).
    const rows = await db.allAsync<any>(`
      SELECT id, content, summary, type, tags, created_at
      FROM knowledge_entries
      WHERE project_id = ?
        AND id IN (
          SELECT rowid FROM knowledge_fts WHERE knowledge_fts MATCH ?
        )
      ORDER BY created_at DESC
      LIMIT 10
    `, [projectId, query]);

    return {
      source: 'memory',
      results: rows.map(r => ({
        id: r.id,
        name: r.summary || r.content?.substring(0, 50) || 'entry',
        kind: r.type || 'memory',
        content: r.summary || r.content?.substring(0, 200),
        file: undefined, line: undefined
      }))
    };
  } catch (err) {
    return { source: 'memory', results: [] };
  }
}

export async function expandGraph(topSymbols: any[], traverser: GraphTraverser): Promise<{ source: string; results: any[] }> {
  const expanded: any[] = [];
  const seen = new Set<string>();

  for (const symbol of topSymbols) {
    try {
      const startNode = await traverser.resolveNode(symbol.name);
      if (!startNode) continue;

      const results = await traverser.traverse(startNode, {
        edgeTypes: ['calls', 'imports', 'inherits'],
        nodeTypes: [],
        direction: 'both',
        maxDepth: 1,
        maxResults: 5
      });

      for (const r of results) {
        const key = `${r.node.name}:${r.node.filePath}`;
        if (seen.has(key)) continue;
        seen.add(key);

        expanded.push({
          id: r.node.id, name: r.node.name, kind: r.node.kind,
          file: r.node.filePath, line: r.node.startLine,
          relationship: `${r.edgeType} ${symbol.name}`
        });
      }
    } catch (err) { console.debug('[curated-helpers] skip :', (err as Error).message); }
  }

  return { source: 'graph', results: expanded };
}

export function miniRRF(listA: any[], listB: any[]): any[] {
  const k = 60;
  const scores = new Map<string, { score: number; item: any }>();

  for (let i = 0; i < listA.length; i++) {
    const key = listA[i].name + ':' + (listA[i].file || '');
    scores.set(key, { score: 1 / (k + i), item: listA[i] });
  }

  for (let i = 0; i < listB.length; i++) {
    const key = listB[i].name + ':' + (listB[i].file || '');
    if (scores.has(key)) {
      scores.get(key)!.score += 1 / (k + i);
    } else {
      scores.set(key, { score: 1 / (k + i), item: listB[i] });
    }
  }

  return Array.from(scores.values())
    .sort((a, b) => b.score - a.score)
    .map(e => e.item);
}

export function formatSections(allocated: AllocatedResult[]): ContextSection[] {
  const bySource = new Map<string, ContextItem[]>();

  for (const item of allocated) {
    const source = (item.sources?.[0] || 'code') as 'code' | 'memory' | 'graph';
    if (!bySource.has(source)) bySource.set(source, []);

    bySource.get(source)!.push({
      name: item.name, kind: item.kind, file: item.file, line: item.line,
      relevance: item.relevance_score, detail: item.detail,
      content: item.content, relationship: item.relationship
    });
  }

  const sections: ContextSection[] = [];
  const titleMap: Record<string, string> = {
    code: 'Code Symbols', memory: 'Knowledge Base', graph: 'Related (Graph)'
  };

  for (const [source, items] of bySource) {
    sections.push({
      title: titleMap[source] || source,
      source: source as 'code' | 'memory' | 'graph',
      items
    });
  }

  return sections;
}

/**
 * KSA-159: Edit Context Service — source + callers + tests + git for editing.
 * Gathers everything needed before modifying a symbol.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver } from '../graph/symbol-resolver.js';
import { CallGraphService } from '../graph/call-graph-service.js';
import { TestDetector } from '../graph/test-detector.js';
import { TokenBudgetManager } from './token-budget-manager.js';
import { GitService } from './git-service.js';
import { EditContextParams, EditContextResult } from './types.js';
import {
  ResolvedSymbolFull,
  resolveSymbolInput,
  readSymbolSource,
  getSignature,
  getCallerContext,
  getTestContext,
  getGitContext,
  getSiblingContext,
  symbolNotFoundResponse
} from './edit-helpers.js';

export class EditContextService {
  private adapter: DatabaseAdapter;
  private resolver: SymbolResolver;
  private callGraph: CallGraphService;
  private testDetector: TestDetector;
  private gitService: GitService;
  private budgetManager: TokenBudgetManager;
  private workspace: string;

  constructor(
    adapter: DatabaseAdapter,
    resolver: SymbolResolver,
    callGraph: CallGraphService,
    testDetector: TestDetector,
    workspace: string
  ) {
    this.adapter = adapter;
    this.resolver = resolver;
    this.callGraph = callGraph;
    this.testDetector = testDetector;
    this.gitService = new GitService(workspace);
    this.budgetManager = new TokenBudgetManager(4000);
    this.workspace = workspace;
  }

  /** Get full edit context for a symbol. */
  async getContext(params: EditContextParams): Promise<EditContextResult> {
    const startTime = Date.now();
    const {
      symbol: symbolInput,
      include_callers = true,
      include_tests = true,
      include_memories = false,
      include_git = true,
      token_budget = 4000,
      caller_depth = 1
    } = params;

    const symbol = await resolveSymbolInput(symbolInput, this.adapter, this.resolver);
    if (!symbol) {
      return symbolNotFoundResponse(symbolInput, token_budget, startTime);
    }

    const source = readSymbolSource(symbol, this.workspace);
    const signature = getSignature(symbol, this.adapter);

    const [callers, tests, gitHistory, siblings] = await Promise.all([
      include_callers ? getCallerContext(symbol, caller_depth, this.callGraph, this.workspace) : Promise.resolve(null),
      include_tests ? getTestContext(symbol, this.testDetector, this.workspace) : Promise.resolve(null),
      include_git ? getGitContext(symbol, this.gitService) : Promise.resolve(null),
      getSiblingContext(symbol, this.adapter)
    ]);

    const sections: Record<string, { content: any; priority: number }> = {
      source: { content: source, priority: 1 },
    };
    if (callers && callers.length > 0) sections.callers = { content: callers, priority: 2 };
    if (tests && tests.length > 0) sections.tests = { content: tests, priority: 3 };
    if (gitHistory && gitHistory.length > 0) sections.git_history = { content: gitHistory, priority: 5 };
    if (siblings && siblings.length > 0) sections.siblings = { content: siblings, priority: 6 };

    const assembled = this.budgetManager.assemble(sections, token_budget);

    const result: EditContextResult = {
      symbol: symbol.name,
      file: symbol.filePath,
      line: symbol.line,
      kind: symbol.kind,
      source: assembled.result.source || source,
      signature,
      metadata: {
        tokenCount: assembled.tokenCount,
        tokenBudget: token_budget,
        sectionsIncluded: assembled.included,
        sectionsExcluded: assembled.excluded,
        queryTimeMs: Date.now() - startTime
      }
    };

    if (assembled.result.callers) result.callers = assembled.result.callers;
    if (assembled.result.tests) result.tests = assembled.result.tests;
    if (assembled.result.git_history) result.git_history = assembled.result.git_history;
    if (assembled.result.siblings) result.siblings = assembled.result.siblings;

    return result;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver, ResolvedSymbol } from '../graph/symbol-resolver.js';
import { CallGraphService } from '../graph/call-graph-service.js';
import { TestDetector } from '../graph/test-detector.js';
import { GitService } from './git-service.js';
import {
  EditContextResult, CallerContext, TestContext, GitCommit, SiblingContext
} from './types.js';

export interface ResolvedSymbolFull extends ResolvedSymbol {
  endLine?: number;
  signature?: string;
}

export async function resolveSymbolInput(input: string, db: DatabaseAdapter, resolver: SymbolResolver): Promise<ResolvedSymbolFull | null> {
  if (input.includes(':') && /:\d+$/.test(input)) {
    const colonIdx = input.lastIndexOf(':');
    const file = input.substring(0, colonIdx);
    const line = parseInt(input.substring(colonIdx + 1));
    return findSymbolAtLine(file, line, db);
  }

  const resolved = await resolver.resolve(input);
  if (resolved.length === 0) return null;

  const sym = resolved[0];
  const extra = await db.getAsync<{ endLine: number; signature: string }>(
    `SELECT end_line as endLine, signature FROM symbols WHERE id = ?`,
    [sym.id],
  );

  return {
    ...sym,
    endLine: extra?.endLine,
    signature: extra?.signature || undefined
  };
}

export function findSymbolAtLine(file: string, line: number, db: DatabaseAdapter): ResolvedSymbolFull | null {
  const row = db.prepare(`
    SELECT s.id, s.name, s.kind, f.relative_path as filePath, s.start_line as line,
           s.end_line as endLine, s.signature, s.parent_symbol_id as parentSymbolId
    FROM symbols s
    JOIN files f ON s.file_id = f.id
    WHERE f.relative_path LIKE ? AND s.start_line <= ? AND s.end_line >= ?
    ORDER BY (s.end_line - s.start_line) ASC
    LIMIT 1
  `).get(`%${file}`, line, line) as ResolvedSymbolFull | undefined;
  return row || null;
}

export function readSymbolSource(symbol: ResolvedSymbolFull, workspace: string): string {
  try {
    const fullPath = path.resolve(workspace, symbol.filePath);
    const content = fs.readFileSync(fullPath, 'utf-8');
    const lines = content.split('\n');
    const start = symbol.line - 1;
    const end = symbol.endLine || start + 50;
    return lines.slice(start, end).join('\n');
  } catch (err) {
    return '';
  }
}

export function getSignature(symbol: ResolvedSymbolFull, db: DatabaseAdapter): string | null {
  if (symbol.signature) return symbol.signature;
  const row = db.prepare(`SELECT signature FROM symbols WHERE id = ?`).get(symbol.id) as { signature: string | null } | undefined;
  return row?.signature || null;
}

export async function getCallerContext(symbol: ResolvedSymbolFull, depth: number, callGraph: CallGraphService, workspace: string): Promise<CallerContext[]> {
  const result = await callGraph.findCallers(symbol.name, depth, 10);
  return result.results.map(caller => {
    const context = getLineContext(caller.filePath, caller.callSiteLine, 2, workspace);
    return {
      symbol: caller.qualifiedName || caller.symbol,
      file: caller.filePath,
      line: caller.callSiteLine,
      context
    };
  });
}

export function getLineContext(file: string, line: number, surroundingLines: number, workspace: string): string {
  try {
    const fullPath = path.resolve(workspace, file);
    const content = fs.readFileSync(fullPath, 'utf-8');
    const lines = content.split('\n');
    const start = Math.max(0, line - 1 - surroundingLines);
    const end = Math.min(lines.length, line + surroundingLines);
    return lines.slice(start, end).join('\n');
  } catch (err) {
    return '';
  }
}

export async function getTestContext(symbol: ResolvedSymbolFull, testDetector: TestDetector, workspace: string): Promise<TestContext[]> {
  const testFiles = testDetector.findRelatedTests([symbol], []);
  const results: TestContext[] = [];

  for (const tf of testFiles.slice(0, 3)) {
    try {
      const fullPath = path.resolve(workspace, tf.file);
      const content = fs.readFileSync(fullPath, 'utf-8');
      const testBlocks = extractTestBlocks(content, symbol.name);
      for (const block of testBlocks.slice(0, 2)) {
        results.push({
          file: tf.file,
          testName: block.name,
          source: block.source
        });
      }
    } catch (err) { console.debug('[edit-helpers] skip unreadable files :', (err as Error).message); }
  }

  return results;
}

export function extractTestBlocks(content: string, symbolName: string): Array<{ name: string; source: string }> {
  const blocks: Array<{ name: string; source: string }> = [];
  const lines = content.split('\n');
  const testPattern = /(?:it|test|describe)\s*\(\s*['"`]([^'"`]*?)['"`]/;

  for (let i = 0; i < lines.length; i++) {
    const match = lines[i].match(testPattern);
    if (match && (lines[i].includes(symbolName) || (i + 10 < lines.length && lines.slice(i, i + 10).join('\n').includes(symbolName)))) {
      const name = match[1];
      const end = Math.min(i + 15, lines.length);
      const source = lines.slice(i, end).join('\n');
      blocks.push({ name, source });
    }
  }

  return blocks;
}

export async function getGitContext(symbol: ResolvedSymbolFull, gitService: GitService): Promise<GitCommit[]> {
  return gitService.getFileHistory(symbol.filePath, 5);
}

export async function getSiblingContext(symbol: ResolvedSymbolFull, db: DatabaseAdapter): Promise<SiblingContext[]> {
  const query = symbol.parentSymbolId
    ? `SELECT name, kind, signature, start_line as line FROM symbols WHERE parent_symbol_id = ? AND id != ? ORDER BY start_line`
    : `SELECT s.name, s.kind, s.signature, s.start_line as line FROM symbols s JOIN files f ON s.file_id = f.id WHERE f.relative_path = ? AND s.parent_symbol_id IS NULL AND s.id != ? ORDER BY s.start_line`;

  const params = symbol.parentSymbolId
    ? [symbol.parentSymbolId, symbol.id]
    : [symbol.filePath, symbol.id];

  return (db.prepare(query).all(...params) as any[]).map(r => ({
    name: r.name,
    kind: r.kind,
    signature: r.signature,
    line: r.line
  }));
}

export function symbolNotFoundResponse(symbol: string, budget: number, startTime: number): EditContextResult {
  return {
    symbol,
    file: '',
    line: 0,
    kind: 'unknown',
    source: '',
    signature: null,
    metadata: {
      tokenCount: 0,
      tokenBudget: budget,
      sectionsIncluded: [],
      sectionsExcluded: ['error: symbol not found'],
      queryTimeMs: Date.now() - startTime
    }
  };
}

/**
 * KSA-160: RRF Merger — Reciprocal Rank Fusion for merging multi-source results.
 */

import { SourceWeights, MergedResult } from './types.js';

interface SourceResults {
  source: string;
  results: any[];
}

export class RRFMerger {
  private k = 60; // RRF constant

  /** Merge results from multiple sources using Reciprocal Rank Fusion. */
  merge(
    sources: { code: SourceResults; memory: SourceResults; graph: SourceResults },
    weights?: SourceWeights
  ): MergedResult[] {
    const w = weights || { code: 0.5, memory: 0.3, graph: 0.2 };
    const scores = new Map<string, { score: number; item: any; sources: string[] }>();

    this.addScores(scores, sources.code.results, w.code, 'code');
    this.addScores(scores, sources.memory.results, w.memory, 'memory');
    this.addScores(scores, sources.graph.results, w.graph, 'graph');

    return Array.from(scores.values())
      .sort((a, b) => b.score - a.score)
      .map(entry => ({
        ...entry.item,
        relevance_score: entry.score,
        sources: entry.sources
      }));
  }

  private addScores(
    scores: Map<string, { score: number; item: any; sources: string[] }>,
    results: any[],
    weight: number,
    source: string
  ): void {
    for (let rank = 0; rank < results.length; rank++) {
      const item = results[rank];
      const key = this.getKey(item);
      const rrfScore = weight * (1 / (this.k + rank));

      if (scores.has(key)) {
        const existing = scores.get(key)!;
        existing.score += rrfScore;
        existing.sources.push(source);
      } else {
        scores.set(key, { score: rrfScore, item, sources: [source] });
      }
    }
  }

  private getKey(item: any): string {
    if (item.id) return String(item.id);
    if (item.name && item.file) return `${item.name}:${item.file}`;
    if (item.name) return item.name;
    return JSON.stringify(item).substring(0, 100);
  }
}

/**
 * KSA-158/159: Token Budget Manager — estimates tokens and assembles context within budget.
 */

export class TokenBudgetManager {
  private budget: number;
  private consumed: number = 0;

  constructor(budget: number) {
    this.budget = Math.max(budget, 500); // Minimum 500 tokens
  }

  /** Estimate token count for content (~4 chars per token). */
  estimateTokens(content: any): number {
    const text = typeof content === 'string' ? content : JSON.stringify(content);
    return Math.ceil(text.length / 4);
  }

  /** Check if tokens can fit within remaining budget. */
  canFit(tokens: number): boolean {
    return this.consumed + tokens <= this.budget;
  }

  /** Consume tokens from budget. */
  consume(tokens: number): void {
    this.consumed += tokens;
  }

  /** Mark budget as fully consumed. */
  consumeAll(): void {
    this.consumed = this.budget;
  }

  /** Get remaining token budget. */
  remaining(): number {
    return Math.max(0, this.budget - this.consumed);
  }

  /** Get total tokens consumed. */
  used(): number {
    return this.consumed;
  }

  /** Check if budget is effectively exhausted (<50 tokens remaining). */
  isExhausted(): boolean {
    return this.remaining() < 50;
  }

  /** Truncate content to fit remaining budget. */
  truncateToFit(content: any): any {
    const maxChars = this.remaining() * 4;

    if (typeof content === 'string') {
      if (content.length <= maxChars) return content;
      return content.substring(0, maxChars) + '\n... (truncated)';
    }

    if (Array.isArray(content)) {
      let chars = 0;
      const result: any[] = [];
      for (const item of content) {
        const itemStr = JSON.stringify(item);
        if (chars + itemStr.length > maxChars) break;
        result.push(item);
        chars += itemStr.length;
      }
      return result;
    }

    const text = JSON.stringify(content);
    if (text.length <= maxChars) return content;
    return text.substring(0, maxChars);
  }

  /**
   * Assemble multiple sections into a result within token budget.
   * Sections are sorted by priority (lower = higher priority).
   */
  assemble(
    sections: Record<string, { content: any; priority: number }>,
    budget: number
  ): { result: Record<string, any>; tokenCount: number; included: string[]; excluded: string[] } {
    const sorted = Object.entries(sections)
      .filter(([_, v]) => v.content != null)
      .sort(([_, a], [__, b]) => a.priority - b.priority);

    const result: Record<string, any> = {};
    let usedTokens = 0;
    const included: string[] = [];
    const excluded: string[] = [];

    for (const [key, { content }] of sorted) {
      const tokens = this.estimateTokens(content);

      if (usedTokens + tokens <= budget) {
        result[key] = content;
        usedTokens += tokens;
        included.push(key);
      } else if (Array.isArray(content) && content.length > 0) {
        // Try truncation for arrays
        const remaining = budget - usedTokens;
        const truncated = this.truncateArray(content, remaining);
        if (truncated.length > 0) {
          result[key] = truncated;
          usedTokens += this.estimateTokens(truncated);
          included.push(`${key} (truncated: ${truncated.length}/${content.length})`);
          continue;
        }
        excluded.push(key);
      } else {
        excluded.push(key);
      }
    }

    return { result, tokenCount: usedTokens, included, excluded };
  }

  private truncateArray(arr: any[], tokenBudget: number): any[] {
    const result: any[] = [];
    let used = 0;
    for (const item of arr) {
      const tokens = this.estimateTokens(item);
      if (used + tokens > tokenBudget) break;
      result.push(item);
      used += tokens;
    }
    return result;
  }
}

