/**
 * Download and verification utilities for native bindings.
 */

import * as fs from 'fs';
import * as path from 'path';
import * as https from 'https';
import * as http from 'http';
import * as crypto from 'crypto';
import pino from 'pino';
import { MANIFEST, BinaryEntry } from './manifest.js';

const logger = pino({ name: 'native-addon-resolver' });

async function downloadBinary(cacheKey: string, cachePath: string, bindingFile: string): Promise<void> {
  const entry = MANIFEST.binaries[cacheKey];
  if (!entry) throw new Error(`No binary available for ${cacheKey}`);

  fs.mkdirSync(cachePath, { recursive: true });
  logger.error(`[native-addon] Downloading: ${entry.url}`);
  logger.error(`[native-addon] Expected size: ${(entry.size / 1024 / 1024).toFixed(1)} MB`);

  await downloadWithRetry(entry, bindingFile);
}

async function downloadWithRetry(entry: BinaryEntry, bindingFile: string): Promise<void> {
  const maxAttempts = 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      if (attempt > 1) {
        logger.error(`[native-addon] Retry ${attempt}/${maxAttempts}...`);
        await sleep(2000 * (attempt - 1));
      }
      await downloadAndVerify(entry, bindingFile);
      return;
    } catch (err: any) {
      cleanupFile(bindingFile);
      if (attempt === maxAttempts) throw err;
    }
  }
}

async function downloadAndVerify(entry: BinaryEntry, bindingFile: string): Promise<void> {
  await downloadFile(entry.url, bindingFile);

  const hash = computeSha256Sync(bindingFile);
  if (hash !== entry.sha256) {
    cleanupFile(bindingFile);
    throw new Error(
      `Checksum mismatch: expected ${entry.sha256.substring(0, 16)}..., got ${hash.substring(0, 16)}...`
    );
  }
}

function downloadFile(url: string, target: string, maxRedirects = 10): Promise<void> {
  return new Promise((resolve, reject) => {
    if (maxRedirects <= 0) { reject(new Error('Too many redirects')); return; }
    const parsedUrl = new URL(url);
    const client = parsedUrl.protocol === 'https:' ? https : http;
    const req = client.get(buildRequestOptions(parsedUrl), (res) => {
      handleDownloadResponse(res, target, maxRedirects, parsedUrl, resolve, reject);
    });
    req.on('timeout', () => { req.destroy(); reject(new Error('Download timed out (60s)')); });
    req.on('error', (_err) => { cleanupFile(target); reject(_err); });
  });
}

function buildRequestOptions(parsedUrl: URL): https.RequestOptions {
  return {
    hostname: parsedUrl.hostname,
    port: parsedUrl.port,
    path: parsedUrl.pathname + parsedUrl.search,
    timeout: 60000,
    headers: {
      'User-Agent': 'mcp-code-intelligence/1.0',
    },
  };
}

function handleDownloadResponse(
  res: http.IncomingMessage,
  target: string,
  maxRedirects: number,
  parsedUrl: URL,
  resolve: (value: void | PromiseLike<void>) => void,
  reject: (reason?: any) => void,
): void {
  const status = res.statusCode ?? 0;
  if (status >= 300 && status < 400 && res.headers.location) {
    return handleRedirect(res, target, maxRedirects, resolve, reject);
  }
  if (status !== 200) {
    res.resume();
    reject(new Error(`HTTP ${status} from ${parsedUrl.hostname}`));
    return;
  }

  pipeToFile(res, target, resolve, reject);
}

function handleRedirect(
  res: http.IncomingMessage,
  target: string,
  maxRedirects: number,
  resolve: (value: void | PromiseLike<void>) => void,
  reject: (reason?: any) => void,
): void {
  res.resume();
  downloadFile(res.headers.location!, target, maxRedirects - 1)
    .then(resolve)
    .catch(reject);
}

function pipeToFile(
  res: http.IncomingMessage,
  target: string,
  resolve: (value: void | PromiseLike<void>) => void,
  reject: (reason?: any) => void,
): void {
  const file = fs.createWriteStream(target);
  res.pipe(file);

  file.on('finish', () => {
    file.close();
    resolve();
  });

  file.on('error', (err) => {
    file.close();
    cleanupFile(target);
    reject(err);
  });
}

function computeSha256Sync(filePath: string): string {
  const content = fs.readFileSync(filePath);
  return crypto.createHash('sha256').update(content).digest('hex');
}

function cleanupFile(filePath: string): void {
  try {
    if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  } catch (err) { logger.debug({ err }, '[download] ignore '); }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export { downloadBinary, downloadFile, computeSha256Sync, cleanupFile, sleep };

/**
 * NativeAddonResolver — Resolves better-sqlite3 native binding for standalone MCP server.
 *
 * Modes:
 * 1. Extension mode: BETTER_SQLITE3_BINDING env var set → use that path directly
 * 2. Standalone mode: auto-detect platform, check cache, download if needed
 * 3. Fallback: if download fails → try require("better-sqlite3") (npm-installed)
 *
 * Cache: ~/.code-intel/native-addons/better-sqlite3/v{version}/node-v{major}-{platform}-{arch}/better_sqlite3.node
 */

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import pino from 'pino';
import { validateBinding } from './validation.js';
import { downloadBinary } from './download.js';
import { MANIFEST } from './manifest.js';

const logger = pino({ name: 'native-addon-resolver' });

async function tryExtensionBinding(): Promise<string | undefined> {
  const envBinding = process.env.BETTER_SQLITE3_BINDING;
  if (!envBinding) return undefined;

  logger.error(`[native-addon] Extension mode: using ${envBinding}`);
  if (await validateBinding(envBinding)) {
    return envBinding;
  }

  logger.error(`[native-addon] ⚠️ Extension-provided binding failed to load (MODULE_VERSION mismatch?)`);
  logger.error(`[native-addon] Falling back to self-resolve for runtime Node v${getNodeMajorVersion()}`);
  return undefined;
}

async function checkCacheBinding(bindingFile: string): Promise<boolean> {
  if (!fs.existsSync(bindingFile) || fs.statSync(bindingFile).size === 0) return false;
  if (await validateBinding(bindingFile)) return true;
  logger.error(`[native-addon] ⚠️ Cached binary MODULE_VERSION mismatch. Deleting: ${bindingFile}`);
  try { fs.unlinkSync(bindingFile); } catch (err) { logger.debug({ err }, '[index] ignore '); }
  return false;
}

async function downloadWithFallback(
  cacheKey: string,
  cachePath: string,
  bindingFile: string,
): Promise<string | undefined> {
  try {
    await downloadBinary(cacheKey, cachePath, bindingFile);
    logger.error(`[native-addon] Downloaded and verified: ${bindingFile}`);
    return bindingFile;
  } catch (err: any) {
    logger.error({ err }, `[native-addon] Download failed:`);
    logger.error('[native-addon] Falling back to npm-installed better-sqlite3');
    return undefined;
  }
}

async function resolveFromCacheOrDownload(
  cacheKey: string,
  cachePath: string,
  bindingFile: string,
): Promise<string | undefined> {
  if (await checkCacheBinding(bindingFile)) {
    logger.error(`[native-addon] Cache hit (validated): ${bindingFile}`);
    return bindingFile;
  }
  return downloadWithFallback(cacheKey, cachePath, bindingFile);
}

/**
 * Resolve the native binding path. Must be called (and awaited) before creating Database instances.
 * Returns the path to better_sqlite3.node, or undefined if fallback to npm-installed should be used.
 *
 * KSA-112: If cached binary has wrong NODE_MODULE_VERSION, auto-delete and re-download.
 */
export async function resolveNativeBinding(): Promise<string | undefined> {
  const extResult = await tryExtensionBinding();
  if (extResult !== undefined) return extResult;

  logger.error('[native-addon] Standalone mode: resolving prebuilt binary...');
  const cacheKey = getCacheKey();
  if (!cacheKey) {
    logger.error('[native-addon] Unsupported platform, falling back to npm-installed');
    return undefined;
  }

  const cachePath = getCachePath(cacheKey);
  const bindingFile = path.join(cachePath, 'better_sqlite3.node');
  return resolveFromCacheOrDownload(cacheKey, cachePath, bindingFile);
}

/**
 * Synchronous resolve — returns cached path or undefined.
 * Use after resolveNativeBinding() has been called at startup.
 */
export function resolveNativeBindingSync(): string | undefined {
  const envBinding = process.env.BETTER_SQLITE3_BINDING;
  if (envBinding) return envBinding;

  const cacheKey = getCacheKey();
  if (!cacheKey) return undefined;

  const bindingFile = path.join(getCachePath(cacheKey), 'better_sqlite3.node');
  if (fs.existsSync(bindingFile) && fs.statSync(bindingFile).size > 0) {
    return bindingFile;
  }
  return undefined;
}

function getNodeMajorVersion(): string {
  return process.versions.node.split('.')[0];
}

function getCacheKey(): string | null {
  const platform = process.platform;
  const arch = process.arch;
  const major = getNodeMajorVersion();
  const exactKey = `node-v${major}-${platform}-${arch}`;
  if (exactKey in MANIFEST.binaries) return exactKey;

  const runtimeMajor = parseInt(major, 10);
  const candidates = Object.keys(MANIFEST.binaries)
    .filter(k => k.startsWith('node-v') && k.endsWith(`-${platform}-${arch}`))
    .map(k => ({ key: k, major: parseInt(k.match(/node-v(\d+)/)?.[1] || '0', 10) }))
    .filter(c => c.major <= runtimeMajor)
    .sort((a, b) => b.major - a.major);

  if (candidates.length > 0) {
    logger.error(`[native-addon] Node v${major}, using compatible binary: ${candidates[0].key}`);
    return candidates[0].key;
  }
  return null;
}

function getCachePath(cacheKey: string): string {
  const homeDir = os.homedir();
  return path.join(
    homeDir,
    '.code-intel',
    'native-addons',
    'better-sqlite3',
    `v${MANIFEST.version}`,
    cacheKey
  );
}

export { getCacheKey, getCachePath, getNodeMajorVersion };

/**
 * KSA-112: Validate that a .node binding file can be loaded by the current runtime.
 * Uses process.dlopen() test to catch MODULE_VERSION mismatch before actual use.
 * Returns true if loadable, false if mismatch or other error.
 */

import * as fs from 'fs';
import pino from 'pino';

const logger = pino({ name: 'native-addon-resolver' });

async function validateBinding(bindingPath: string): Promise<boolean> {
  try {
    if (!fs.existsSync(bindingPath) || fs.statSync(bindingPath).size === 0) return false;
    const testModule = { exports: {} } as any;
    process.dlopen(testModule, bindingPath);
    logger.error(`[native-addon] ✅ Binding validated: ${bindingPath}`);
    return true;
  } catch (err: any) {
    const msg = err.message || '';
    if (msg.includes('ERR_DLOPEN_FAILED') || msg.includes('NODE_MODULE_VERSION') || msg.includes('was compiled against')) {
      logger.error(`[native-addon] ❌ MODULE_VERSION mismatch: ${msg.substring(0, 200)}`);
    } else {
      logger.error(`[native-addon] ❌ Binding validation failed: ${msg.substring(0, 200)}`);
    }
    return false;
  }
}

export { validateBinding };

/**
 * SA4E-107: Code Enrichment Handler.
 * Main handler: loads symbol context, calls LLM, parses response, stores results.
 * Strategy pattern selects enrichment approach per symbol kind.
 */

import type { Logger } from 'pino';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import type { LLMService } from '../../modules/memory/llm/LLMService.js';
import type { PendingTask } from '../../modules/memory/task-queue/models.js';
import { CodeEnrichmentPromptBuilder } from './CodeEnrichmentPromptBuilder.js';
import { CodeEnrichmentPayloadSchema } from './types.js';
import type { CodeEnrichmentPayload, EnrichmentStrategy, SymbolContext, CodeEnrichmentLLMResponse } from './types.js';
import { validateTags } from './tag-validator.js';
import { isPegaKind } from '../../modules/pega/pega-mapping.js';

/** LLM call timeout in milliseconds (BR-02). */
const LLM_TIMEOUT_MS = 30_000;
/** Max pseudo code length (BR-05). */
const MAX_PSEUDO_CODE_LENGTH = 2000;

// Strategy selection: which symbol kinds map to which enrichment strategy
const CLASS_KINDS = new Set(['class', 'interface', 'enum']);
const FUNCTION_KINDS = new Set(['function', 'method', 'arrow_function', 'generator']);

/**
 * Orchestrates LLM enrichment for a single code symbol.
 * Injected into TaskWorker via setCodeEnrichmentHandler().
 */
export class CodeEnrichmentHandler {
  private readonly promptBuilder: CodeEnrichmentPromptBuilder;

  constructor(
    private readonly adapter: DatabaseAdapter,
    private readonly llmService: LLMService,
    private readonly logger: Logger,
  ) {
    this.promptBuilder = new CodeEnrichmentPromptBuilder();
  }

  /**
   * Enrich a single symbol from a CODE_ENRICHMENT task.
   * @param task - The pending task with payload
   */
  async enrichSymbol(task: PendingTask): Promise<void> {
    const parsed = CodeEnrichmentPayloadSchema.safeParse(JSON.parse(task.payload));
    if (!parsed.success) {
      throw new Error(`invalid_payload: ${parsed.error.message}`);
    }
    const payload = parsed.data;
    const context = await this.loadContext(payload);
    const strategy = this.selectStrategy(payload.symbolKind, payload.workspaceType);
    const messages = this.promptBuilder.build(strategy, context);
    const raw = await this.callLLMWithTimeout(messages);
    const response = this.parseResponse(raw, strategy);
    await this.storeResults(payload.symbolId, response, strategy);
  }

  private selectStrategy(kind: string, workspaceType: string): EnrichmentStrategy {
    // SA4E-171: use isPegaKind() for all 16+ pega kinds (replaces static set)
    if (workspaceType === 'pega' && isPegaKind(kind)) return 'PEGA_SUMMARY';
    if (FUNCTION_KINDS.has(kind)) return 'FUNCTION_SUMMARY';
    if (CLASS_KINDS.has(kind)) return 'CLASS_SUMMARY';
    return 'CLASS_SUMMARY'; // Fallback
  }

  private async loadContext(payload: CodeEnrichmentPayload): Promise<SymbolContext> {
    const sym = await this.adapter.getAsync<{
      name: string; kind: string; signature: string | null;
      doc_comment: string | null; parent_symbol: string | null;
    }>(
      'SELECT name, kind, signature, doc_comment, parent_symbol FROM symbols WHERE id = ?',
      [payload.symbolId],
    );
    if (!sym) throw new Error(`symbol_not_found: ${payload.symbolId}`);

    const bodyText = await this.loadBodyText(payload.symbolId);
    const childMembers = await this.loadChildMembers(payload.symbolId);
    const existingPseudoCode = await this.loadExistingPseudoCode(payload.symbolId);

    return {
      name: sym.name,
      kind: sym.kind,
      signature: sym.signature,
      docComment: sym.doc_comment,
      bodyText,
      childMembers,
      existingPseudoCode,
      // SA4E-106: Pega class from payload or parent_symbol; ruleset from payload
      pegaClass: payload.pegaClass || sym.parent_symbol || undefined,
      pegaRuleset: payload.pegaRuleset || undefined,
    };
  }

  private async loadBodyText(symbolId: number): Promise<string | null> {
    const row = await this.adapter.getAsync<{ embedding: Buffer }>(
      'SELECT embedding FROM body_embeddings WHERE symbol_id = ? AND chunk_index = 0',
      [symbolId],
    );
    if (!row?.embedding) return null;
    return Buffer.from(row.embedding).toString('utf-8');
  }

  private async loadChildMembers(symbolId: number): Promise<string[] | null> {
    const rows = await this.adapter.allAsync<{ name: string; kind: string }>(
      'SELECT name, kind FROM symbols WHERE parent_symbol_id = ? LIMIT 30',
      [symbolId],
    );
    if (rows.length === 0) return null;
    return rows.map(r => `${r.kind}:${r.name}`);
  }

  private async loadExistingPseudoCode(symbolId: number): Promise<string | null> {
    const row = await this.adapter.getAsync<{ pseudo_code: string | null }>(
      'SELECT pseudo_code FROM symbols WHERE id = ?', [symbolId],
    );
    return row?.pseudo_code ?? null;
  }

  /** Call LLM with 30s timeout via Promise.race (BR-02). */
  private async callLLMWithTimeout(messages: { role: string; content: string }[]): Promise<string> {
    const timeout = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error('llm_timeout')), LLM_TIMEOUT_MS),
    );
    const result = await Promise.race([
      this.llmService.complete(messages as any),
      timeout,
    ]);
    return result.content;
  }

  /** Parse LLM response with regex fallback on JSON parse failure. */
  private parseResponse(raw: string, strategy: EnrichmentStrategy): CodeEnrichmentLLMResponse {
    // Attempt 1: direct JSON parse
    try {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed.summary === 'string') return parsed;
    } catch { /* fallback below */ }

    // Attempt 2: extract from markdown code fence
    const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (fenceMatch) {
      try {
        const parsed = JSON.parse(fenceMatch[1].trim());
        if (parsed && typeof parsed.summary === 'string') return parsed;
      } catch { /* fallback below */ }
    }

    // Attempt 3: regex extraction of individual fields
    return this.regexFallbackParse(raw, strategy);
  }

  private regexFallbackParse(raw: string, strategy: EnrichmentStrategy): CodeEnrichmentLLMResponse {
    const summaryMatch = raw.match(/"summary"\s*:\s*"([^"]+)"/);
    const pseudoMatch = raw.match(/"pseudo_code"\s*:\s*"([^"]+)"/);
    const tagsMatch = raw.match(/"tags"\s*:\s*\[([^\]]*)\]/);

    const summary = summaryMatch?.[1] ?? raw.slice(0, 200).replace(/["\n]/g, ' ').trim();
    const result: CodeEnrichmentLLMResponse = { summary };

    if ((strategy === 'FUNCTION_SUMMARY' || strategy === 'PEGA_SUMMARY') && pseudoMatch) {
      result.pseudo_code = pseudoMatch[1];
    }
    if (tagsMatch) {
      const tagStrs = tagsMatch[1].match(/"([^"]+)"/g)?.map(s => s.replace(/"/g, ''));
      result.tags = tagStrs ?? [];
    }
    return result;
  }

  /** Persist enrichment results to symbols table (last-write-wins, BR-07). */
  private async storeResults(
    symbolId: number, response: CodeEnrichmentLLMResponse, strategy: EnrichmentStrategy,
  ): Promise<void> {
    const tags = validateTags(response.tags);
    const tagsJson = tags.length > 0 ? JSON.stringify(tags) : null;

    // SA4E-171: store pseudo_code for both FUNCTION and PEGA strategies
    let pseudoCode: string | null = null;
    if ((strategy === 'FUNCTION_SUMMARY' || strategy === 'PEGA_SUMMARY') && response.pseudo_code) {
      pseudoCode = response.pseudo_code.length > MAX_PSEUDO_CODE_LENGTH
        ? response.pseudo_code.slice(0, MAX_PSEUDO_CODE_LENGTH) + '...'
        : response.pseudo_code;
    }

    const now = new Date().toISOString();
    await this.adapter.runAsync(
      `UPDATE symbols SET summary = ?, pseudo_code = COALESCE(?, pseudo_code),
       llm_tags = ?, enrichment_status = 'COMPLETED', enriched_at = ? WHERE id = ?`,
      [response.summary, pseudoCode, tagsJson, now, symbolId],
    );
  }
}

/**
 * SA4E-106: CodeEnrichmentTaskCreator — cross-scope enrichment copy.
