/**
 * SA4E-91 — Tests for CodeEdgeExtractor strategies.
 * Verifies IMPORTS, CALLS, and EXTENDS edges are extracted from code_dependencies,
 * code_call_graph, and symbols tables, then inserted into graph_edges.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import Database from 'better-sqlite3';
import pino from 'pino';
import { SqliteDbAdapter } from '../../../modules/memory/task-queue/SqliteDbAdapter.js';
import {
  ImportsEdgeStrategy,
  CallsEdgeStrategy,
  ExtendsEdgeStrategy,
  extractAndInsertCodeEdges,
} from '../code-edge-extractor.js';

const PID = 'proj_test';
const log = pino({ level: 'silent' });

const INDEX_SCHEMA = `
CREATE TABLE files (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL DEFAULT '',
  path TEXT, relative_path TEXT, language TEXT, module TEXT, content_hash TEXT, size_bytes INTEGER, line_count INTEGER);
CREATE TABLE symbols (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL DEFAULT '',
  file_id INTEGER, name TEXT, kind TEXT, signature TEXT, start_line INTEGER, end_line INTEGER,
  parent_symbol TEXT, parent_symbol_id INTEGER, visibility TEXT, doc_comment TEXT, complexity INTEGER, is_exported INTEGER DEFAULT 0);
CREATE TABLE code_dependencies (id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_file_id INTEGER NOT NULL, target_file_id INTEGER, target_path TEXT NOT NULL DEFAULT '',
  dependency_type TEXT NOT NULL DEFAULT 'import');
CREATE TABLE code_call_graph (id INTEGER PRIMARY KEY AUTOINCREMENT,
  caller_symbol_id INTEGER NOT NULL, callee_symbol_id INTEGER NOT NULL, call_site_line INTEGER);
`;

const ADMIN_SCHEMA = `
CREATE TABLE graph_nodes (entry_id TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL DEFAULT 'DOCUMENT', tier TEXT NOT NULL DEFAULT 'SHARED', project_id TEXT NOT NULL DEFAULT '',
  x REAL DEFAULT 0, y REAL DEFAULT 0, z REAL DEFAULT 0, level INTEGER DEFAULT 2, cluster_id TEXT,
  created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE graph_edges (id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL, target TEXT NOT NULL,
  weight REAL NOT NULL DEFAULT 0.5, rel_type TEXT NOT NULL DEFAULT 'RELATED_TO',
  UNIQUE(source, target));
`;

describe('SA4E-91 CodeEdgeExtractor', () => {
  let indexDb: Database.Database;
  let adminDb: Database.Database;

  beforeEach(() => {
    indexDb = new Database(':memory:');
    indexDb.exec(INDEX_SCHEMA);
    adminDb = new Database(':memory:');
    adminDb.exec(ADMIN_SCHEMA);
  });

  afterEach(() => { indexDb.close(); adminDb.close(); });

  describe('ImportsEdgeStrategy', () => {
    it('extracts IMPORTS edges from code_dependencies', async () => {
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/a.ts', 'a.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/b.ts', 'b.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO code_dependencies (source_file_id, target_file_id, target_path) VALUES (1, 2, './b')`).run();

      const strategy = new ImportsEdgeStrategy();
      const edges = await strategy.extract(new SqliteDbAdapter(indexDb), PID);

      expect(edges).toHaveLength(1);
      expect(edges[0]).toEqual({ source: 'code:1', target: 'code:2', label: 'IMPORTS', weight: 0.8 });
    });

    it('skips dependencies with null target_file_id', async () => {
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/a.ts', 'a.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO code_dependencies (source_file_id, target_file_id, target_path) VALUES (1, NULL, 'lodash')`).run();

      const strategy = new ImportsEdgeStrategy();
      const edges = await strategy.extract(new SqliteDbAdapter(indexDb), PID);

      expect(edges).toHaveLength(0);
    });
  });

  describe('CallsEdgeStrategy', () => {
    it('extracts CALLS edges from code_call_graph', async () => {
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/x.ts', 'x.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind) VALUES (?, 1, 'foo', 'function')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind) VALUES (?, 1, 'bar', 'function')`).run(PID);
      indexDb.prepare(`INSERT INTO code_call_graph (caller_symbol_id, callee_symbol_id, call_site_line) VALUES (1, 2, 10)`).run();

      const strategy = new CallsEdgeStrategy();
      const edges = await strategy.extract(new SqliteDbAdapter(indexDb), PID);

      expect(edges).toHaveLength(1);
      expect(edges[0]).toEqual({ source: 'code:1', target: 'code:2', label: 'CALLS', weight: 0.7 });
    });
  });

  describe('ExtendsEdgeStrategy', () => {
    it('extracts EXTENDS edges from parent_symbol_id', async () => {
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/c.ts', 'c.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind, parent_symbol_id) VALUES (?, 1, 'Base', 'class', NULL)`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind, parent_symbol_id) VALUES (?, 1, 'Child', 'class', 1)`).run(PID);

      const strategy = new ExtendsEdgeStrategy();
      const edges = await strategy.extract(new SqliteDbAdapter(indexDb), PID);

      expect(edges).toHaveLength(1);
      expect(edges[0]).toEqual({ source: 'code:2', target: 'code:1', label: 'EXTENDS', weight: 0.9 });
    });
  });

  describe('extractAndInsertCodeEdges (integration)', () => {
    it('inserts all edge types into graph_edges', async () => {
      // File A=1 imports File B=2, but Symbol X=3 (in file A) calls Symbol Y=4 (in file B)
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/a.ts', 'a.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/b.ts', 'b.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind) VALUES (?, 1, 'fn1', 'function')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind) VALUES (?, 1, 'fn2', 'function')`).run(PID);
      indexDb.prepare(`INSERT INTO symbols (project_id, file_id, name, kind) VALUES (?, 2, 'fn3', 'function')`).run(PID);
      // File 1 → File 2 (IMPORTS edge: code:1 → code:2)
      indexDb.prepare(`INSERT INTO code_dependencies (source_file_id, target_file_id, target_path) VALUES (1, 2, './b')`).run();
      // Symbol 2 → Symbol 3 (CALLS edge: code:2 → code:3)
      indexDb.prepare(`INSERT INTO code_call_graph (caller_symbol_id, callee_symbol_id, call_site_line) VALUES (2, 3, 10)`).run();

      const count = await extractAndInsertCodeEdges(
        new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), PID, log,
      );

      expect(count).toBe(2);
      const edges = adminDb.prepare('SELECT * FROM graph_edges ORDER BY rel_type').all() as any[];
      expect(edges).toHaveLength(2);
      expect(edges.some((e: any) => e.rel_type === 'IMPORTS')).toBe(true);
      expect(edges.some((e: any) => e.rel_type === 'CALLS')).toBe(true);
    });

    it('is idempotent — duplicate inserts ignored', async () => {
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/a.ts', 'a.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO files (project_id, path, relative_path) VALUES (?, '/b.ts', 'b.ts')`).run(PID);
      indexDb.prepare(`INSERT INTO code_dependencies (source_file_id, target_file_id, target_path) VALUES (1, 2, './b')`).run();

      await extractAndInsertCodeEdges(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), PID, log);
      await extractAndInsertCodeEdges(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), PID, log);

      const edges = adminDb.prepare('SELECT * FROM graph_edges').all() as any[];
      expect(edges.length).toBe(1);
    });
  });
});

/**
 * SA4E-41 Graph sync test — GraphSyncService projects only the target tenant's
 * code symbols into admin.db graph_nodes; other tenants and KB nodes untouched.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import Database from 'better-sqlite3';
import pino from 'pino';
import { SqliteDbAdapter } from '../../../modules/memory/task-queue/SqliteDbAdapter.js';
import { GraphSyncService } from '../graph-sync-service.js';

const PID_A = 'proj_aaaa';
const PID_B = 'proj_bbbb';
const log = pino({ level: 'silent' });

const INDEX_SCHEMA = `
CREATE TABLE files (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL DEFAULT '',
  path TEXT, relative_path TEXT, language TEXT, module TEXT, content_hash TEXT, size_bytes INTEGER, line_count INTEGER);
CREATE TABLE symbols (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL DEFAULT '',
  file_id INTEGER, name TEXT, kind TEXT, signature TEXT, start_line INTEGER, end_line INTEGER,
  parent_symbol TEXT, visibility TEXT, doc_comment TEXT, complexity INTEGER, is_exported INTEGER DEFAULT 0);
`;

const ADMIN_SCHEMA = `
CREATE TABLE graph_nodes (entry_id TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL DEFAULT 'DOCUMENT', tier TEXT NOT NULL DEFAULT 'SHARED', project_id TEXT NOT NULL DEFAULT '',
  x REAL DEFAULT 0, y REAL DEFAULT 0, z REAL DEFAULT 0, level INTEGER DEFAULT 2, cluster_id TEXT,
  created_at TEXT DEFAULT (datetime('now')));
`;

function seedSymbols(db: Database.Database, pid: string, names: string[]): void {
  const fInfo = db.prepare(`INSERT INTO files (project_id, path, relative_path, language) VALUES (?, ?, 'src/x.ts', 'typescript')`).run(pid, `/${pid}/x.ts`);
  const fileId = fInfo.lastInsertRowid as number;
  const ins = db.prepare(`INSERT INTO symbols (project_id, file_id, name, kind, start_line, end_line, is_exported, complexity) VALUES (?, ?, ?, 'function', 1, 5, 1, 2)`);
  for (const n of names) ins.run(pid, fileId, n);
}

describe('SA4E-41 GraphSyncService', () => {
  let indexDb: Database.Database;
  let adminDb: Database.Database;

  beforeEach(() => {
    indexDb = new Database(':memory:'); indexDb.exec(INDEX_SCHEMA);
    adminDb = new Database(':memory:'); adminDb.exec(ADMIN_SCHEMA);
    seedSymbols(indexDb, PID_A, ['alphaOne', 'alphaTwo']);
    seedSymbols(indexDb, PID_B, ['bravoOne']);
    // A pre-existing KB node for A must never be touched by code sync.
    adminDb.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id) VALUES ('doc-1', 'KB', 'CONTEXT', 'SEMANTIC', ?)`).run(PID_A);
  });

  afterEach(() => { indexDb.close(); adminDb.close(); });

  it('projects only the target tenant code nodes', async () => {
    await new GraphSyncService(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), log).syncProjectSymbols(PID_B);
    const codeNodes = adminDb.prepare("SELECT project_id FROM graph_nodes WHERE entry_id LIKE 'code:%'").all() as { project_id: string }[];
    expect(codeNodes.length).toBe(1);
    expect(codeNodes.every(n => n.project_id === PID_B)).toBe(true);
  });

  it('does not create code nodes for other tenants', async () => {
    await new GraphSyncService(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), log).syncProjectSymbols(PID_B);
    const aCode = adminDb.prepare("SELECT COUNT(*) c FROM graph_nodes WHERE entry_id LIKE 'code:%' AND project_id = ?").get(PID_A) as any;
    expect(aCode.c).toBe(0);
  });

  it('leaves KB (non-code) nodes untouched', async () => {
    await new GraphSyncService(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), log).syncProjectSymbols(PID_B);
    const kb = adminDb.prepare("SELECT COUNT(*) c FROM graph_nodes WHERE entry_id = 'doc-1'").get() as any;
    expect(kb.c).toBe(1);
  });

  it('is idempotent (re-sync replaces, does not duplicate)', async () => {
    const svc = new GraphSyncService(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), log);
    await svc.syncProjectSymbols(PID_B);
    await svc.syncProjectSymbols(PID_B);
    const count = adminDb.prepare("SELECT COUNT(*) c FROM graph_nodes WHERE entry_id LIKE 'code:%' AND project_id = ?").get(PID_B) as any;
    expect(count.c).toBe(1);
  });

  it('fail-closed: empty projectId is a no-op', async () => {
    await new GraphSyncService(new SqliteDbAdapter(indexDb), new SqliteDbAdapter(adminDb), log).syncProjectSymbols('');
    const count = adminDb.prepare("SELECT COUNT(*) c FROM graph_nodes WHERE entry_id LIKE 'code:%'").get() as any;
    expect(count.c).toBe(0);
  });
});

/**
 * KSA-154: Call Graph Service - BFS traversal for callers/callees.
 * Provides transitive call graph analysis with depth control.
 */

import { GraphRepository, CallerResult, CalleeResult } from './graph-repository.js';
import { SymbolResolver, ResolvedSymbol } from './symbol-resolver.js';

export interface CallGraphItem {
  symbol: string;
  qualifiedName: string;
  kind: string;
  filePath: string;
  definitionLine: number;
  callSiteLine: number;
  depthLevel: number;
  parameters?: string | null;
  isAsync?: boolean;
}

export interface CallGraphResponse {
  symbol: string;
  resolvedTo: Array<{ id: number; file: string; line: number; kind: string }>;
  results: CallGraphItem[];
  metadata: {
    totalCount: number;
    depthSearched: number;
    truncated: boolean;
    queryTimeMs: number;
  };
}

export class CallGraphService {
  private graphRepo: GraphRepository;
  private symbolResolver: SymbolResolver;

  constructor(graphRepo: GraphRepository, symbolResolver: SymbolResolver) {
    this.graphRepo = graphRepo;
    this.symbolResolver = symbolResolver;
  }

  /** Find all callers of a symbol with transitive depth. */
  async findCallers(
    symbolName: string,
    depth: number = 1,
    limit: number = 20,
    fileFilter?: string,
    kindFilter: string | string[] = 'calls'
  ): Promise<CallGraphResponse> {
    const startTime = Date.now();
    const clampedDepth = Math.min(Math.max(depth, 1), 5);

    const resolved = await this.symbolResolver.resolve(symbolName);
    if (resolved.length === 0) {
      return await this.symbolNotFoundResponse(symbolName);
    }

    // KSA-191: Support multiple kind filters (SF call types: flow-action, wire, apex-import)
    const kinds = Array.isArray(kindFilter) ? kindFilter : [kindFilter];

    const results: CallGraphItem[] = [];
    const visited = new Set<number>();
    const queue: Array<{ symbolName: string; depth: number }> = [];

    for (const sym of resolved) {
      queue.push({ symbolName: sym.name, depth: 0 });
    }

    while (queue.length > 0 && results.length < limit) {
      const { symbolName: current, depth: currentDepth } = queue.shift()!;
      if (currentDepth >= clampedDepth) continue;

      // Query for each kind
      for (const kind of kinds) {
        const callers = await this.graphRepo.findCallers(current, kind, limit - results.length);

        for (const caller of callers) {
          if (visited.has(caller.id)) continue;
          visited.add(caller.id);

          const item: CallGraphItem = {
            symbol: caller.name,
            qualifiedName: caller.parameters ? `${caller.parameters}.${caller.name}` : caller.name,
            kind: caller.kind,
            filePath: caller.file_path,
            definitionLine: caller.def_line,
            callSiteLine: caller.call_line,
            depthLevel: currentDepth + 1,
            parameters: caller.parameters,
            isAsync: caller.is_async === 1,
          };

          if (fileFilter && !this.matchFilter(item.filePath, fileFilter)) continue;

          results.push(item);

          if (currentDepth + 1 < clampedDepth) {
            queue.push({ symbolName: caller.name, depth: currentDepth + 1 });
          }
        }
      }
    }

    return {
      symbol: symbolName,
      resolvedTo: resolved.map(s => ({ id: s.id, file: s.filePath, line: s.line, kind: s.kind })),
      results,
      metadata: {
        totalCount: results.length,
        depthSearched: clampedDepth,
        truncated: results.length >= limit,
        queryTimeMs: Date.now() - startTime,
      },
    };
  }

  /** Find all callees of a symbol with transitive depth. */
  async findCallees(
    symbolName: string,
    depth: number = 1,
    limit: number = 20,
    fileFilter?: string,
    includeExternal: boolean = true,
    kindFilter: string | string[] = 'calls'
  ): Promise<CallGraphResponse> {
    const startTime = Date.now();
    const clampedDepth = Math.min(Math.max(depth, 1), 5);

    const resolved = await this.symbolResolver.resolve(symbolName);
    if (resolved.length === 0) {
      return await this.symbolNotFoundResponse(symbolName);
    }

    // KSA-191: Support multiple kind filters (SF: dml, soql, trigger-on)
    const kinds = Array.isArray(kindFilter) ? kindFilter : [kindFilter];

    const results: CallGraphItem[] = [];
    const visited = new Set<string>();
    const queue: Array<{ symbolId: number; depth: number }> = [];

    for (const sym of resolved) {
      queue.push({ symbolId: sym.id, depth: 0 });
    }

    while (queue.length > 0 && results.length < limit) {
      const { symbolId, depth: currentDepth } = queue.shift()!;
      if (currentDepth >= clampedDepth) continue;

      for (const kind of kinds) {
        const callees = await this.graphRepo.findCallees(symbolId, kind, limit - results.length);

        for (const callee of callees) {
          const key = `${callee.name}:${callee.call_line}`;
          if (visited.has(key)) continue;
          visited.add(key);

          if (!includeExternal && !callee.file_path) continue;

          const item: CallGraphItem = {
            symbol: callee.name,
            qualifiedName: callee.name,
            kind: callee.kind || 'unknown',
            filePath: callee.file_path || '(external)',
            definitionLine: callee.def_line || 0,
            callSiteLine: callee.call_line,
            depthLevel: currentDepth + 1,
          };

          if (fileFilter && item.filePath !== '(external)' && !this.matchFilter(item.filePath, fileFilter)) continue;

          results.push(item);

          if (callee.file_path && currentDepth + 1 < clampedDepth) {
            const calleeResolved = await this.symbolResolver.resolve(callee.name);
            for (const cr of calleeResolved) {
              if (cr.filePath === callee.file_path) {
                queue.push({ symbolId: cr.id, depth: currentDepth + 1 });
                break;
              }
            }
          }
        }
      }
    }

    return {
      symbol: symbolName,
      resolvedTo: resolved.map(s => ({ id: s.id, file: s.filePath, line: s.line, kind: s.kind })),
      results,
      metadata: {
        totalCount: results.length,
        depthSearched: clampedDepth,
        truncated: results.length >= limit,
        queryTimeMs: Date.now() - startTime,
      },
    };
  }

  private async symbolNotFoundResponse(symbolName: string): Promise<CallGraphResponse> {
    const suggestions = await this.symbolResolver.suggest(symbolName);
    return {
      symbol: symbolName,
      resolvedTo: [],
      results: [],
      metadata: { totalCount: 0, depthSearched: 0, truncated: false, queryTimeMs: 0 },
    };
  }

  private matchFilter(filePath: string, filter: string): boolean {
    if (filter.includes('*')) {
      const regex = new RegExp('^' + filter.replace(/\*/g, '.*') + '$');
      return regex.test(filePath);
    }
    return filePath.includes(filter);
  }
}

/**
 * KSA-156: Impact Analysis helpers - extracted from ImpactAnalysisService.
 * Pure functions for severity classification, recommendation generation, etc.
 * SA4E-45: Refactored to use DatabaseAdapter abstraction.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { ResolvedSymbol } from './symbol-resolver.js';
import { TestDetector, RelatedTest } from './test-detector.js';

export type Severity = 'critical' | 'high' | 'medium' | 'low';
export type ImpactAction = 'modify' | 'delete' | 'rename';

export interface ImpactItem {
  symbol: string;
  qualifiedName?: string;
  file: string;
  line: number;
  severity: Severity;
  reason: string;
  chain?: string[];
}

export interface ImpactResult {
  symbol: string;
  action: ImpactAction;
  blastRadius: {
    summary: Record<Severity, number>;
    totalAffected: number;
    affectedFiles: number;
    affectedTests: number;
  };
  impacts: ImpactItem[];
  affectedTests: RelatedTest[];
  recommendations: string[];
  metadata: {
    queryTimeMs: number;
    depthSearched: number;
    truncated: boolean;
  };
}

export function classifySeverity(depth: number, action: ImpactAction, type: string): Severity {
  if (action === 'delete') {
    if (depth <= 1) return 'critical';
    if (depth <= 2) return 'high';
    return 'medium';
  }
  if (action === 'rename' && depth <= 1) return 'high';
  if (depth === 1) return 'critical';
  if (depth === 2) return 'high';
  if (depth === 3) return 'medium';
  return 'low';
}

/** Find implementors of an interface method that would be impacted. */
export function findImplementorImpacts(resolved: ResolvedSymbol[], symbolName: string, adapter: DatabaseAdapter): ImpactItem[] {
  const impacts: ImpactItem[] = [];
  for (const sym of resolved) {
    if (sym.kind !== 'method') continue;
    if (!sym.parentSymbolId) continue;
    const parent = adapter.get<{ kind: string; name: string }>(
      'SELECT kind, name FROM symbols WHERE id = ?', [sym.parentSymbolId]);
    if (!parent || parent.kind !== 'interface') continue;
    const implementors = adapter.all<{ name: string; file_path: string; line: number }>(`
      SELECT DISTINCT s.name, f.relative_path as file_path, s.start_line as line
      FROM relationships r
      JOIN symbols s ON s.id = r.source_symbol_id
      JOIN files f ON s.file_id = f.id
      WHERE r.target_symbol = ? AND r.kind = 'implements'
    `, [parent.name]);
    for (const impl of implementors) {
      impacts.push({
        symbol: `${impl.name}.${sym.name}`,
        file: impl.file_path,
        line: impl.line,
        severity: 'critical',
        reason: `Implements ${parent.name}.${sym.name}`,
      });
    }
  }
  return impacts;
}

export function generateRecommendations(impacts: ImpactItem[], action: ImpactAction, symbol: string, testDetector: TestDetector): string[] {
  const recs: string[] = [];
  const critical = impacts.filter(i => i.severity === 'critical');
  const testImpacts = impacts.filter(i => testDetector.isTestFile(i.file));
  if (action === 'delete' && impacts.length === 0) {
    recs.push(`Safe to delete "${symbol}" - no references found`);
  } else if (action === 'delete' && impacts.length > 0) {
    recs.push(`Remove all ${impacts.length} references before deleting "${symbol}"`);
  }
  if (action === 'modify' && critical.length > 0) {
    recs.push(`Update ${critical.length} direct callers if signature changes`);
  }
  if (action === 'rename') {
    const files = new Set(impacts.map(i => i.file)).size;
    recs.push(`Update references in ${files} files with new name`);
  }
  if (testImpacts.length > 0) {
    const testFiles = testImpacts.map(t => t.file).slice(0, 5);
    recs.push(`Run affected tests: ${testFiles.join(', ')}`);
  }
  if (impacts.length > 20) {
    recs.push('Consider incremental refactoring to reduce blast radius');
  }
  return recs;
}

export function filterBySeverity(impacts: ImpactItem[], threshold: Severity): ImpactItem[] {
  const order: Record<Severity, number> = { critical: 0, high: 1, medium: 2, low: 3 };
  const thresholdOrder = order[threshold];
  return impacts.filter(i => order[i.severity] <= thresholdOrder);
}

export function deduplicate(impacts: ImpactItem[]): ImpactItem[] {
  const seen = new Set<string>();
  return impacts.filter(i => {
    const key = `${i.file}:${i.symbol}:${i.line}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function severityOrder(severity: Severity): number {
  const order: Record<Severity, number> = { critical: 0, high: 1, medium: 2, low: 3 };
  return order[severity];
}

export function buildSummary(impacts: ImpactItem[]): Record<Severity, number> {
  const summary: Record<Severity, number> = { critical: 0, high: 0, medium: 0, low: 0 };
  for (const i of impacts) { summary[i.severity]++; }
  return summary;
}

export function emptyResult(symbolName: string, action: ImpactAction): ImpactResult {
  return {
    symbol: symbolName,
    action,
    blastRadius: { summary: { critical: 0, high: 0, medium: 0, low: 0 }, totalAffected: 0, affectedFiles: 0, affectedTests: 0 },
    impacts: [],
    affectedTests: [],
    recommendations: [`Symbol "${symbolName}" not found in index`],
    metadata: { queryTimeMs: 0, depthSearched: 0, truncated: false },
  };
}

/**
 * KSA-153: Schema Migrator — Applies graph schema migrations.
 * SA4E-53: async + cross-engine (PostgreSQL + SQLite) compatible.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import pino from 'pino';

const logger = pino({ name: 'graph-migrator' });

/** Enhanced symbol columns added for tree-sitter (KSA-145/153). */
const ENHANCED_SYMBOL_COLUMNS = [
  { name: 'parameters', type: 'TEXT' },
  { name: 'return_type', type: 'TEXT' },
  { name: 'parent_symbol_id', type: 'INTEGER' },
  { name: 'decorators', type: 'TEXT' },
  { name: 'complexity', type: 'INTEGER' },
  { name: 'is_async', type: 'INTEGER DEFAULT 0' },
  { name: 'is_exported', type: 'INTEGER DEFAULT 0' },
  { name: 'doc_comment_full', type: 'TEXT' },
  { name: 'modifiers', type: 'TEXT' },
] as const;

/** SA4E-107: Enrichment columns for LLM-generated metadata. */
const ENRICHMENT_COLUMNS = [
  { name: 'summary', type: 'TEXT' },
  { name: 'pseudo_code', type: 'TEXT' },
  { name: 'llm_tags', type: 'TEXT' },
  { name: 'enrichment_status', type: 'TEXT' },
  { name: 'enriched_at', type: 'TEXT' },
] as const;

/** Build cross-engine DDL for the relationships table. */
function buildGraphSchema(engine: string): string {
  const serial = engine === 'sqlite' ? 'INTEGER PRIMARY KEY' : 'SERIAL PRIMARY KEY';
  return `
CREATE TABLE IF NOT EXISTS relationships (
    id ${serial},
    source_symbol_id INTEGER NOT NULL,
    target_symbol TEXT NOT NULL,
    target_symbol_id INTEGER,
    kind TEXT NOT NULL CHECK(kind IN ('calls','imports','inherits','implements','uses','decorates')),
    file_path TEXT NOT NULL,
    line INTEGER NOT NULL,
    metadata TEXT,
    FOREIGN KEY (source_symbol_id) REFERENCES symbols(id) ON DELETE CASCADE,
    FOREIGN KEY (target_symbol_id) REFERENCES symbols(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_rel_source_kind ON relationships(source_symbol_id, kind);
CREATE INDEX IF NOT EXISTS idx_rel_target_kind ON relationships(target_symbol, kind);
CREATE INDEX IF NOT EXISTS idx_rel_file ON relationships(file_path);
`;
}

function buildFileIndexSchema(engine: string): string {
  const ts = engine === 'sqlite' ? `(datetime('now'))` : 'current_timestamp';
  return `
CREATE TABLE IF NOT EXISTS file_index (
    path TEXT PRIMARY KEY,
    mtime INTEGER NOT NULL,
    content_hash TEXT NOT NULL,
    size_bytes INTEGER NOT NULL,
    last_indexed TEXT NOT NULL DEFAULT ${ts},
    symbol_count INTEGER DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_file_index_hash ON file_index(content_hash);
`;
}

function buildGraphMetaSchema(engine: string): string {
  const conflict = engine === 'sqlite' ? 'INSERT OR IGNORE' : 'INSERT';
  const onConflict = engine === 'sqlite' ? '' : ' ON CONFLICT (key) DO NOTHING';
  return `
CREATE TABLE IF NOT EXISTS graph_meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
${conflict} INTO graph_meta (key, value) VALUES ('schema_version', '3')${onConflict};
${conflict} INTO graph_meta (key, value) VALUES ('last_checkpoint', '')${onConflict};
${conflict} INTO graph_meta (key, value) VALUES ('total_nodes', '0')${onConflict};
${conflict} INTO graph_meta (key, value) VALUES ('total_edges', '0')${onConflict};
`;
}

function buildBodyEmbeddingsSchema(engine: string): string {
  const serial = engine === 'sqlite' ? 'INTEGER PRIMARY KEY AUTOINCREMENT' : 'SERIAL PRIMARY KEY';
  const ts = engine === 'sqlite' ? `(datetime('now'))` : 'current_timestamp';
  return `
CREATE TABLE IF NOT EXISTS body_embeddings (
    id ${serial},
    symbol_id INTEGER NOT NULL,
    chunk_index INTEGER NOT NULL DEFAULT 0,
    embedding BYTEA NOT NULL,
    token_count INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT ${ts},
    UNIQUE(symbol_id, chunk_index),
    FOREIGN KEY (symbol_id) REFERENCES symbols(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_body_embeddings_symbol ON body_embeddings(symbol_id);
`;
}

/**
 * Run graph-related migrations (KSA-153 + KSA-169).
 * Safe to call multiple times — all operations are idempotent.
 */
export async function runGraphMigrations(adapter: DatabaseAdapter): Promise<void> {
  const engine = adapter.getEngine();
  logger.error(`[graph-migrator] Running graph schema migrations (engine: ${engine})...`);

  await addEnhancedSymbolColumns(adapter);

  // SA4E-107: Add enrichment columns
  await addEnrichmentColumns(adapter);

  await execIdempotent(adapter, buildGraphSchema(engine));
  logger.error('[graph-migrator] Relationships table ready');

  await execIdempotent(adapter, buildFileIndexSchema(engine));
  logger.error('[graph-migrator] File index table ready');

  await execIdempotent(adapter, buildGraphMetaSchema(engine));
  logger.error('[graph-migrator] Graph metadata table ready');

  await execIdempotent(adapter, buildBodyEmbeddingsSchema(engine));
  logger.error('[graph-migrator] Body embeddings table ready');

  // Update schema version
  if (engine === 'sqlite') {
    await adapter.runAsync('INSERT OR REPLACE INTO schema_version (version) VALUES (?)', [3]);
  } else {
    await adapter.runAsync(
      'INSERT INTO schema_version (version) VALUES ($1) ON CONFLICT (version) DO NOTHING',
      [3],
    );
  }
  logger.error('[graph-migrator] Schema version set to 3');
}

/** Execute DDL, ignoring "already exists" errors (idempotent). */
async function execIdempotent(adapter: DatabaseAdapter, sql: string): Promise<void> {
  // Split on semicolons and execute each statement individually
  const stmts = sql.split(';').map(s => s.trim()).filter(s => s.length > 0);
  for (const stmt of stmts) {
    try {
      await adapter.execAsync(stmt);
    } catch (err: unknown) {
      const msg = (err as Error).message ?? '';
      if (msg.includes('already exists') || msg.includes('duplicate column')) continue;
      throw err;
    }
  }
}

async function addEnhancedSymbolColumns(adapter: DatabaseAdapter): Promise<void> {
  const existing = await getExistingColumns(adapter, 'symbols');
  let added = 0;

  for (const col of ENHANCED_SYMBOL_COLUMNS) {
    if (!existing.has(col.name)) {
      try {
        await adapter.execAsync(`ALTER TABLE symbols ADD COLUMN ${col.name} ${col.type}`);
        added++;
      } catch (err) {
        // Column may already exist
      }
    }
  }

  if (added > 0) {
    logger.error(`[graph-migrator] Added ${added} enhanced symbol columns`);
    try {
      await adapter.execAsync('CREATE INDEX IF NOT EXISTS idx_sym_parent ON symbols(parent_symbol_id)');
      await adapter.execAsync('CREATE INDEX IF NOT EXISTS idx_sym_exported ON symbols(is_exported)');
      await adapter.execAsync('CREATE INDEX IF NOT EXISTS idx_sym_file_kind ON symbols(file_id, kind)');
    } catch (err) {
      // Indexes may already exist
    }
  }
}

/** SA4E-107: Add enrichment columns to symbols table (idempotent). */
async function addEnrichmentColumns(adapter: DatabaseAdapter): Promise<void> {
  const existing = await getExistingColumns(adapter, 'symbols');
  let added = 0;

  for (const col of ENRICHMENT_COLUMNS) {
    if (!existing.has(col.name)) {
      try {
        await adapter.execAsync(`ALTER TABLE symbols ADD COLUMN ${col.name} ${col.type}`);
        added++;
      } catch (err) {
        // Column may already exist — idempotent
      }
    }
  }

  if (added > 0) {
    logger.error(`[graph-migrator] Added ${added} enrichment columns`);
  }

  // Create indexes for enrichment queries (idempotent)
  try {
    await adapter.execAsync('CREATE INDEX IF NOT EXISTS idx_symbols_enrichment_status ON symbols(enrichment_status)');
    await adapter.execAsync('CREATE INDEX IF NOT EXISTS idx_symbols_project_enrichment ON symbols(project_id, enrichment_status)');
  } catch (err) {
    // Indexes may already exist
  }
}

async function getExistingColumns(adapter: DatabaseAdapter, table: string): Promise<Set<string>> {
  try {
    // PostgreSQL: information_schema
    const pg = await adapter.allAsync<{ column_name: string }>(
      `SELECT column_name FROM information_schema.columns WHERE table_name = $1`,
      [table],
    );
    if (pg.length > 0) return new Set(pg.map(r => r.column_name));
  } catch (err) { logger.debug({ err }, '[migrator] SQLite fallback '); }
  try {
    const sqlite = await adapter.allAsync<{ name: string }>(
      `SELECT name FROM pragma_table_info('${table}')`,
    );
    return new Set(sqlite.map(r => r.name));
  } catch (err) { return new Set(); }
}

/** Check if graph migrations have been applied. */
export async function isGraphSchemaReady(adapter: DatabaseAdapter): Promise<boolean> {
  try {
    // PostgreSQL
    const pg = await adapter.allAsync<{ table_name: string }>(
      `SELECT table_name FROM information_schema.tables WHERE table_name = 'relationships'`,
    );
    if (pg.length > 0) return true;
  } catch (err) { logger.debug({ err }, '[migrator] Operation failed (non-fatal)'); }
  try {
    // SQLite
    const lite = await adapter.getAsync<{ name: string }>(
      "SELECT name FROM sqlite_master WHERE type='table' AND name='relationships'",
    );
    return !!lite;
  } catch (err) { return false; }
}

/**
 * KSA-157: Traverse helpers - extracted from GraphTraverser.
 * Pure functions for neighbor resolution and source snippet extraction.
 * SA4E-45: Refactored to use DatabaseAdapter abstraction.
 * SA4E-53: Async API for PostgreSQL compatibility.
 */

import * as fs from 'fs';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { GraphNode, TraverseConfig } from './traverser.js';
import { resolveWithinWorkspace } from '../../shared/path-safety.js';
import { buildCodeScopeFilter } from '../query/code-intel-isolation.js';

/** Allowed edge types for traversal queries (SEC-01: allowlist prevents SQL injection). */
const ALLOWED_EDGE_TYPES = new Set([
  'calls', 'imports', 'inherits', 'implements', 'uses',
  'decorates', 'overrides', 'extends', 'references', 'type_of',
]);

/** Retrieve neighbor nodes from the graph within a tenant scope. */
export async function getNeighbors(nodeId: number, config: TraverseConfig, adapter: DatabaseAdapter, projectId?: string): Promise<GraphNode[]> {
  // SEC-01 fix: validate edgeTypes against allowlist, use parameterized placeholders
  const validEdgeTypes = config.edgeTypes.filter(e => ALLOWED_EDGE_TYPES.has(e));
  const edgeFilter = validEdgeTypes.length > 0
    ? `AND r.kind IN (${validEdgeTypes.map(() => '?').join(',')})`
    : '';
  const edgeParams = validEdgeTypes;
  const scope = buildCodeScopeFilter(projectId, 's');
  let rows: any[] = [];
  switch (config.direction) {
    case 'outgoing':
      rows = await adapter.allAsync(`
        SELECT s.id, s.name, s.kind, f.relative_path as filePath, s.start_line as startLine, r.kind as _incomingEdgeType
        FROM relationships r
        JOIN symbols s ON s.id = r.target_symbol_id
        JOIN files f ON s.file_id = f.id
        WHERE r.source_symbol_id = ? AND ${scope.clause} ${edgeFilter}
        LIMIT 100
      `, [nodeId, ...scope.params, ...edgeParams]);
      break;
    case 'incoming':
      rows = await adapter.allAsync(`
        SELECT s.id, s.name, s.kind, f.relative_path as filePath, s.start_line as startLine, r.kind as _incomingEdgeType
        FROM relationships r
        JOIN symbols s ON s.id = r.source_symbol_id
        JOIN files f ON s.file_id = f.id
        WHERE r.target_symbol_id = ? AND ${scope.clause} ${edgeFilter}
        LIMIT 100
      `, [nodeId, ...scope.params, ...edgeParams]);
      break;
    case 'both': {
      const outgoing = await adapter.allAsync(`
        SELECT s.id, s.name, s.kind, f.relative_path as filePath, s.start_line as startLine, r.kind as _incomingEdgeType
        FROM relationships r
        JOIN symbols s ON s.id = r.target_symbol_id
        JOIN files f ON s.file_id = f.id
        WHERE r.source_symbol_id = ? AND ${scope.clause} ${edgeFilter}
        LIMIT 50
      `, [nodeId, ...scope.params, ...edgeParams]);
      const incoming = await adapter.allAsync(`
        SELECT s.id, s.name, s.kind, f.relative_path as filePath, s.start_line as startLine, r.kind as _incomingEdgeType
        FROM relationships r
        JOIN symbols s ON s.id = r.source_symbol_id
        JOIN files f ON s.file_id = f.id
        WHERE r.target_symbol_id = ? AND ${scope.clause} ${edgeFilter}
        LIMIT 50
      `, [nodeId, ...scope.params, ...edgeParams]);
      rows = [...outgoing, ...incoming];
      break;
    }
  }
  return rows as GraphNode[];
}

/** Extract source snippet from a file for display in traversal results. */
export function getSourceSnippet(filePath: string, startLine: number, contextLines: number, workspace: string): string | null {
  try {
    const fullPath = resolveWithinWorkspace(workspace, filePath);
    if (!fullPath || !fs.existsSync(fullPath)) return null;
    const content = fs.readFileSync(fullPath, 'utf-8');
    const lines = content.split('\n');
    const start = Math.max(0, startLine - 1);
    const end = Math.min(lines.length, start + contextLines);
    return lines.slice(start, end).join('\n');
  } catch {
    return null;
  }
}

/**
 * KSA-157: Graph Traverser - generic BFS/DFS engine with edge/node type filtering.
 * Provides the core traversal logic for the code_traverse MCP tool.
 * SA4E-45: Refactored to use DatabaseAdapter abstraction.
 */

import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { SymbolResolver } from './symbol-resolver.js';
import { getNeighbors, getSourceSnippet } from './traverse-helpers.js';

export interface GraphNode {
  id: number;
  name: string;
  kind: string;
  filePath: string;
  startLine: number;
  _incomingEdgeType?: string;
}

export interface TraverseConfig {
  edgeTypes: string[];
  nodeTypes: string[];
  direction: 'outgoing' | 'incoming' | 'both';
  maxDepth: number;
  maxResults: number;
}

export interface TraverseResultItem {
  node: GraphNode;
  depth: number;
  path: string[];
  edgeType: string;
}

export interface TraverseResponse {
  start: { name: string; kind: string; file: string; line: number };
  results: Array<{
    name: string;
    kind: string;
    file: string;
    line: number;
    depth: number;
    edge_type: string;
    source?: string;
  }>;
  metadata: {
    total_traversed: number;
    total_results: number;
    max_depth_reached: number;
    truncated: boolean;
    execution_time_ms: number;
  };
}

export class GraphTraverser {
  private adapter: DatabaseAdapter;
  private resolver: SymbolResolver;
  private workspace: string;
  private projectId: string | undefined;

  /**
   * @param projectId  SA4E-41 tenant scope. Undefined => fail-closed (no neighbors).
   */
  constructor(adapter: DatabaseAdapter, resolver: SymbolResolver, workspace: string, projectId?: string) {
    this.adapter = adapter;
    this.resolver = resolver;
    this.workspace = workspace;
    this.projectId = projectId;
  }

  async resolveNode(identifier: string): Promise<GraphNode | null> {
    const resolved = await this.resolver.resolve(identifier);
    if (resolved.length === 0) return null;
    return {
      id: resolved[0].id,
      name: resolved[0].name,
      kind: resolved[0].kind,
      filePath: resolved[0].filePath,
      startLine: resolved[0].line,
    };
  }

  async traverse(startNode: GraphNode, config: TraverseConfig): Promise<TraverseResultItem[]> {
    const visited = new Set<number>();
    const queue: Array<{ node: GraphNode; depth: number; path: string[] }> = [
      { node: startNode, depth: 0, path: [startNode.name] },
    ];
    const results: TraverseResultItem[] = [];
    while (queue.length > 0 && results.length < config.maxResults) {
      const { node, depth, path: currentPath } = queue.shift()!;
      if (visited.has(node.id)) continue;
      visited.add(node.id);
      if (depth > 0) {
        if (config.nodeTypes.length === 0 || config.nodeTypes.includes(node.kind)) {
          results.push({ node, depth, path: currentPath, edgeType: node._incomingEdgeType || 'unknown' });
        }
      }
      if (depth < config.maxDepth) {
        const neighbors = await getNeighbors(node.id, config, this.adapter, this.projectId);
        for (const neighbor of neighbors) {
          if (!visited.has(neighbor.id)) {
            queue.push({ node: neighbor, depth: depth + 1, path: [...currentPath, neighbor.name] });
          }
        }
      }
    }
    return results.sort((a, b) => a.depth - b.depth);
  }

  formatResponse(
    startNode: GraphNode,
    results: TraverseResultItem[],
    includeSource: boolean,
    sourceLines: number,
    executionTimeMs: number
  ): TraverseResponse {
    const formattedResults = results.map(r => {
      const formatted: any = {
        name: r.node.name,
        kind: r.node.kind,
        file: r.node.filePath,
        line: r.node.startLine,
        depth: r.depth,
        edge_type: r.edgeType,
      };
      if (includeSource) {
        formatted.source = getSourceSnippet(r.node.filePath, r.node.startLine, sourceLines, this.workspace);
      }
      return formatted;
    });
    return {
      start: { name: startNode.name, kind: startNode.kind, file: startNode.filePath, line: startNode.startLine },
      results: formattedResults,
      metadata: {
        total_traversed: results.length,
        total_results: formattedResults.length,
        max_depth_reached: Math.max(...results.map(r => r.depth), 0),
        truncated: results.length >= 50,
        execution_time_ms: executionTimeMs,
      },
    };
  }
}

