/**
 * Async File Scanner — SA4E-44
 * Non-blocking workspace traversal with chunked yield.
 * Replaces synchronous scanWorkspace() to avoid event loop blocking.
 */

import * as fsp from 'fs/promises';
import * as path from 'path';
import * as crypto from 'crypto';
import type { AppConfig } from '../config.js';
import type { ScannedFile } from './file-scanner.js';
import { detectLanguage, loadFileMetadata } from './file-scanner.js';
import { createIgnoreParser } from '../parsers/ignore/index.js';

const CHUNK_SIZE = 50;

export async function scanWorkspaceAsync(
  config: AppConfig,
): Promise<ScannedFile[]> {
  const results: ScannedFile[] = [];
  const ignoreParser = createIgnoreParser(config.workspace);
  const metadata = loadFileMetadata(config.workspace);
  const queue: string[] = [config.workspace];
  let processed = 0;

  while (queue.length > 0) {
    const dir = queue.shift()!;
    let entries: any[];
    try {
      entries = await fsp.readdir(dir, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      const relPath = path.relative(config.workspace, fullPath)
        .replace(/\\/g, '/');

      if (shouldSkip(entry.name, relPath, config, ignoreParser)) continue;

      if (entry.isDirectory()) {
        queue.push(fullPath);
      } else if (entry.isFile()) {
        const file = await processFile(fullPath, relPath, config, metadata);
        if (file) results.push(file);
      }

      if (++processed % CHUNK_SIZE === 0) {
        await new Promise<void>(r => setImmediate(r));
      }
    }
  }

  return results;
}

function shouldSkip(
  name: string, relPath: string, config: AppConfig,
  ignoreParser: { shouldIgnore(p: string): boolean },
): boolean {
  if (name.startsWith('.') && name !== '.') return true;
  if (config.excludePatterns.some(p => relPath.includes(p) || name === p)) {
    return true;
  }
  return ignoreParser.shouldIgnore(relPath);
}

async function processFile(
  fullPath: string, relPath: string, config: AppConfig,
  metadata: Record<string, { fileCreatedAt?: string; fileAuthor?: string; fileVersion?: string }>,
): Promise<ScannedFile | null> {
  const language = detectLanguage(fullPath);
  if (!language) return null;

  const ext = path.extname(fullPath).toLowerCase();
  const validExt = config.includeExtensions.includes(ext)
    || ext === '.kts' || language === 'salesforce-meta';
  if (!validExt) return null;

  try {
    const stat = await fsp.stat(fullPath);
    if (stat.size > config.maxFileSize) return null;

    const content = await fsp.readFile(fullPath, 'utf-8');
    if (isBinary(content)) return null;

    const meta = metadata[relPath] || {};
    return {
      absolutePath: fullPath,
      relativePath: relPath,
      language,
      contentHash: crypto.createHash('sha256')
        .update(content).digest('hex').slice(0, 16),
      sizeBytes: stat.size,
      lineCount: content.split('\n').length,
      fileCreatedAt: meta.fileCreatedAt || stat.birthtime?.toISOString(),
      fileAuthor: meta.fileAuthor,
      fileVersion: meta.fileVersion,
    };
  } catch {
    return null;
  }
}

function isBinary(content: string): boolean {
  const sample = content.slice(0, 1024);
  return (sample.match(/\0/g) || []).length > 2;
}

/**
 * @deprecated SA4E-78: File watching moved to Extension side (VS Code FileSystemWatcher).
 * This class is retained for backward compatibility with co-located deployments.
 * For decoupled deployments, use POST /api/index/file-events instead.
 *
 * File Watcher — chokidar-based file system watcher with debounce.
 * Gracefully degrades if chokidar is not installed.
 */

import pino from 'pino';
import { AppConfig } from '../config.js';
import { detectLanguage } from './file-scanner.js';

const logger = pino({ name: 'file-watcher' });

type WatchEvent = 'add' | 'change' | 'unlink';
type WatchCallback = (filePath: string, event: WatchEvent) => void;

export class FileWatcher {
  private config: AppConfig;
  private callback: WatchCallback;
  private watcher: any = null;
  private debounceTimers = new Map<string, NodeJS.Timeout>();

  constructor(config: AppConfig, callback: WatchCallback) {
    this.config = config;
    this.callback = callback;
  }

  /** Start watching the workspace for file changes. */
  start(): void {
    this.initChokidar().catch(err => {
      logger.error({ err }, '[watcher] chokidar not available, file watching disabled:');
    });
  }

  /** Stop the file watcher. */
  stop(): void {
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
    }
    for (const timer of this.debounceTimers.values()) {
      clearTimeout(timer);
    }
    this.debounceTimers.clear();
    logger.error('[watcher] Stopped');
  }

  private async initChokidar(): Promise<void> {
    const chokidar = await import('chokidar');
    const ignored = this.config.excludePatterns.map(p => `**/${p}/**`);

    this.watcher = chokidar.watch(this.config.workspace, {
      ignored: [...ignored, /(^|[\/\\])\./],
      persistent: true,
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 200, pollInterval: 50 },
    });

    this.watcher.on('add', (p: string) => this.handleEvent(p, 'add'));
    this.watcher.on('change', (p: string) => this.handleEvent(p, 'change'));
    this.watcher.on('unlink', (p: string) => this.handleEvent(p, 'unlink'));

    logger.error('[watcher] Watching for file changes');
  }

  private handleEvent(filePath: string, event: WatchEvent): void {
    if (event !== 'unlink' && !detectLanguage(filePath)) return;
    this.debounce(filePath, () => this.callback(filePath, event));
  }

  private debounce(key: string, fn: () => void): void {
    const existing = this.debounceTimers.get(key);
    if (existing) clearTimeout(existing);

    const timer = setTimeout(() => {
      this.debounceTimers.delete(key);
      fn();
    }, this.config.watchDebounceMs);

    this.debounceTimers.set(key, timer);
  }
}

/**
 * Index Helper — Standalone file indexing and DB operations.
 * SA4E-41: all reads/writes are scoped by project_id (multi-tenant isolation).
 * SA4E-53: converted to async API for PostgreSQL compatibility.
 */

import type { DatabaseAdapter, PreparedStatement } from '../../database/adapters/DatabaseAdapter.js';
import { DialectHelper } from '../../database/dialect/DialectHelper.js';
import * as fs from 'fs';
import type { Logger } from 'pino';
import type { ScannedFile } from './file-scanner.js';
import { extractSymbols } from '../parsers/signature-extractor.js';
import { detectModule } from './module-helper.js';

/**
 * Check if file content hash matches the database (unchanged) within a tenant.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function isFileUnchanged(adapter: DatabaseAdapter, file: ScannedFile, projectId: string): Promise<boolean> {
  const row = await adapter.getAsync<{ content_hash: string }>(
    'SELECT content_hash FROM files WHERE relative_path = ? AND project_id = ?',
    [file.relativePath, projectId],
  );
  return row?.content_hash === file.contentHash;
}

/** Legacy regex-based symbol extraction (used when tree-sitter unavailable). */
export async function indexFileSymbolsRegex(
  file: ScannedFile, fileId: number, projectId: string, adapter: DatabaseAdapter, logger: Logger
): Promise<void> {
  try {
    const content = fs.readFileSync(file.absolutePath, 'utf-8');
    const symbols = extractSymbols(content, file.language);
    const sql = `INSERT INTO symbols (project_id, file_id, name, kind, signature, start_line, end_line, parent_symbol, visibility, doc_comment)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    for (const sym of symbols) {
      await adapter.runAsync(sql, [
        projectId, fileId, sym.name, sym.kind, sym.signature,
        sym.startLine, sym.endLine, sym.parentSymbol,
        sym.visibility, sym.docComment,
      ]);
    }
  } catch (err) {
    logger.error({ err }, `[indexer] Error indexing ${file.relativePath}:`);
  }
}

/**
 * Upsert a file record in the database, stamped with the tenant scope.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function upsertFileInDb(adapter: DatabaseAdapter, file: ScannedFile, projectId: string): Promise<void> {
  const module = detectModule(file.relativePath);
  const dialect = new DialectHelper(adapter.getEngine());
  const columns = ['project_id', 'path', 'relative_path', 'language', 'module', 'content_hash', 'size_bytes', 'line_count', 'last_indexed'];
  const updateCols = ['content_hash', 'size_bytes', 'line_count', 'last_indexed'];
  // Build upsert with engine-appropriate NOW() expression for last_indexed
  const sql = adapter.getEngine() === 'sqlite'
    ? `INSERT OR REPLACE INTO files (${columns.join(', ')}) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))`
    : `INSERT INTO files (${columns.join(', ')}) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW()) ON CONFLICT (project_id, relative_path) DO UPDATE SET ${updateCols.map(c => `${c} = EXCLUDED.${c}`).join(', ')}`;
  await adapter.runAsync(sql,
    [projectId, file.absolutePath, file.relativePath, file.language, module, file.contentHash, file.sizeBytes, file.lineCount],
  );
}

/**
 * Regex fallback for file upsert (delete + re-insert symbols), scoped by tenant.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function upsertFileRegexFallback(adapter: DatabaseAdapter, file: ScannedFile, projectId: string, logger: Logger): Promise<void> {
  const fileRow = await adapter.getAsync<{ id: number }>(
    'SELECT id FROM files WHERE relative_path = ? AND project_id = ?',
    [file.relativePath, projectId],
  );
  if (!fileRow) return;

  await adapter.runAsync('DELETE FROM symbols WHERE file_id = ?', [fileRow.id]);
  await indexFileSymbolsRegex(file, fileRow.id, projectId, adapter, logger);
}

