import { CodeEnrichmentTaskCreator } from '../enrichment/CodeEnrichmentTaskCreator.js';


const logger = pino({ name: 'indexing-engine' });
const __dirname = path.dirname(fileURLToPath(import.meta.url));

export class IndexingEngine {
  private adapter: DatabaseAdapter;
  private dialect: DialectHelper;
  private config: AppConfig;
  private watcher: FileWatcher | null = null;
  private running = false;
  private indexing = new Set<string>(); // SA4E-41: per-project index guard
  private treeSitterIndexer: TreeSitterIndexer | null = null;
  private grammarRegistry: GrammarRegistry | null = null;
  private graphRepo: GraphRepository | null = null;
  private treeSitterReady = false;
  /** SA4E-78: Progress event emitter for Observer pattern. */
  private readonly progressEmitter = new EventEmitter();
  /** SA4E-78: Cached instance avoids repeated instantiation (AD-6). */
  private readonly graphSyncService: GraphSyncService;
  /** SA4E-107: Creates enrichment tasks after indexing. */
  private readonly enrichmentTaskCreator: CodeEnrichmentTaskCreator;

  constructor(adapter: DatabaseAdapter, config: AppConfig) {
    this.adapter = adapter;
    this.dialect = new DialectHelper(adapter.getEngine());
    this.config = config;
    this.graphSyncService = new GraphSyncService(this.adapter, this.adapter, logger);
    this.enrichmentTaskCreator = new CodeEnrichmentTaskCreator(this.adapter, logger);
    this.initTreeSitter();
  }

  /**
   * Subscribe to progress events emitted during index operations.
   * @param event - Event name ('progress')
   * @param handler - Callback receiving phase, current, total
   */
  on(event: string, handler: (...args: unknown[]) => void): void {
    this.progressEmitter.on(event, handler);
  }

  private initTreeSitter(): void {
    // SA4E-53: schema check is async — run migrations lazily, non-blocking
    this.ensureGraphSchema().catch(err => {
      logger.error({ err }, '[indexer] Graph schema init failed');
    });
    try {
      this.graphRepo = new GraphRepository(this.adapter);
      const configPath = [path.resolve(__dirname, '../parsers/grammar-config.json'), path.resolve(__dirname, '../../src/parsers/grammar-config.json')].find(fs.existsSync);
      if (configPath) {
        const grammarConfig = loadGrammarConfig(configPath);
        this.grammarRegistry = new GrammarRegistry(grammarConfig);
        this.treeSitterIndexer = new TreeSitterIndexer(this.grammarRegistry, this.adapter, this.config.maxFileSize, this.config.workspace);
        this.treeSitterReady = true;
        logger.error(`[indexer] Tree-sitter initialized (${grammarConfig.languages.length} langs)` + (detectSfdxProject(this.config.workspace) ? ' [SFDX]' : ''));
      } else {
        logger.error(`[indexer] Grammar config not found, using regex fallback`);
      }
    } catch (err) {
      logger.error({ err }, '[indexer] Tree-sitter init failed, using regex fallback:');
      this.treeSitterReady = false;
    }
  }

  /** SA4E-53: Ensure graph schema is ready (async migration). */
  private async ensureGraphSchema(): Promise<void> {
    const ready = await isGraphSchemaReady(this.adapter);
    if (!ready) await runGraphMigrations(this.adapter);
  }

  async startBackgroundIndexing(): Promise<void> {
    // DISABLED: scanWorkspace blocks event loop on Windows with 1000+ files
    return;
  }

  async runFullIndex(scope?: Partial<IndexScope>, signal?: AbortSignal): Promise<void> {
    const { projectId, workspace } = resolveScope(scope, {
      projectId: this.config.projectId,
      workspace: this.config.workspace,
    });
    if (this.indexing.has(projectId)) return; // per-project guard
    this.indexing.add(projectId);
    logger.error(`[indexer] Starting full index (project=${projectId})...`);
    await new Promise<void>(resolve => setImmediate(resolve));
    try {
      // Phase: scanning (SA4E-78: async scan, non-blocking)
      this.emitProgress(projectId, 'scanning', 0, 0);
      const files = await scanWorkspaceAsync({ ...this.config, workspace });
      if (signal?.aborted) { this.emitProgress(projectId, 'cancelled', 0, 0); return; }

      logger.error(`[indexer] Found ${files.length} files to index`);
      // Phase: indexing
      this.emitProgress(projectId, 'indexing', 0, files.length);
      await this.indexFiles(files, projectId, signal);
      if (signal?.aborted) { this.emitProgress(projectId, 'cancelled', 0, 0); return; }

      // Phase: resolving
      this.emitProgress(projectId, 'resolving', 0, 0);
      await new Promise<void>(resolve => setImmediate(resolve));
      await updateModules(this.adapter, projectId);
      await new Promise<void>(resolve => setImmediate(resolve));
      await detectAndStorePatterns(this.adapter, new Map(), logger, projectId);
      if (this.graphRepo) {
        await new Promise<void>(resolve => setImmediate(resolve));
        const resolved = await this.graphRepo.resolveTargets(5000, projectId);
        if (resolved > 0) logger.error(`[indexer] Resolved ${resolved} cross-file symbol references`);
      }
      await new Promise<void>(resolve => setImmediate(resolve));
      await this.syncGraphNodes(projectId);
      await new Promise<void>(resolve => setImmediate(resolve));
      // SA4E-107: Create enrichment tasks (non-blocking — failures don't affect indexing)
      await this.createEnrichmentTasks(projectId);
      await new Promise<void>(resolve => setImmediate(resolve));
      logSfdxStats(this.adapter, this.config, logger);
      this.registerWorkspace(projectId, workspace);

      this.emitProgress(projectId, 'complete', files.length, files.length);
      logger.error('[indexer] Full index complete');
    } finally {
      this.indexing.delete(projectId);
    }
  }

  /** SA4E-78: Emit progress event via EventEmitter (Observer pattern). */
  private emitProgress(projectId: string, phase: ProgressPhase, current: number, total: number): void {
    this.progressEmitter.emit('progress', { projectId, phase, current, total });
  }

  /** Project this tenant's code symbols into graph_nodes in index DB (non-fatal). SA4E-53: async. SA4E-78: cached. */
  private async syncGraphNodes(projectId: string): Promise<void> {
    try {
      await this.graphSyncService.syncProjectSymbols(projectId);
    } catch (err) {
      logger.error({ err }, '[indexer] Graph node sync skipped');
    }
  }

  /** SA4E-107: Create enrichment tasks for unenriched symbols (non-fatal, BR-01). */
  private async createEnrichmentTasks(projectId: string): Promise<void> {
    try {
      await this.enrichmentTaskCreator.createTasksForProject(projectId);
    } catch (err) {
      logger.warn({ err }, '[indexer] Enrichment task creation skipped (non-fatal)');
    }
  }

  /** Register workspace in project_registry so admin dropdown shows it (non-fatal). */
  private registerWorkspace(projectId: string, workspace: string): void {
    try {
      const repo = new AdminGraphRepository(getAdminAdapter());
      repo.registerProject(projectId, path.basename(workspace), workspace);
    } catch (err) {
      logger.warn({ err }, '[indexer] project_registry upsert skipped (non-fatal)');
    }
  }

  /**
   * SA4E-41 SEC-06: incremental watcher events are scoped to the BOOT tenant only.
   * The FileWatcher only watches `config.workspace` (a single tenant's tree), so the
   * boot `config.projectId` is the correct owner for these events. Other tenants are
   * indexed push-only via POST /api/index/source (which passes the request projectId
   * to runFullIndex). Do NOT reuse this path for multi-tenant workspaces.
   */
  private bootProjectId(): string {
    return this.config.projectId;
  }

  async indexSingleFile(filePath: string, projectId?: string): Promise<IndexResult | null> {
    const pid = projectId || this.bootProjectId();
    const file = scanSingleFile(filePath, this.config.workspace);
    if (!file) return null;
    return this.upsertFile(file, pid);
  }

  public getAdapter(): DatabaseAdapter { return this.adapter; }

  removeFile(filePath: string): void {
    const relativePath = filePath.replace(/\\/g, '/');
    const projectId = this.bootProjectId(); // SEC-06: boot-tenant scope only
    // SA4E-53: fire-and-forget async (non-fatal for watcher events)
    this.adapter.runAsync('DELETE FROM files WHERE relative_path = ? AND project_id = ?', [relativePath, projectId])
      .catch(err => logger.error({ err }, '[indexer] removeFile run failed'));
    this.graphRepo?.deleteFileRelationships(relativePath, projectId)
      .catch(err => logger.error({ err }, '[indexer] removeFile deleteFileRelationships failed'));
  }

  isRunning(projectId?: string): boolean {
    return projectId ? this.indexing.has(projectId) : this.indexing.size > 0;
  }
  stop(): void {
    this.running = false;
    this.watcher?.stop();
    this.watcher = null;
  }

  getTreeSitterStats() {
    if (!this.treeSitterReady || !this.grammarRegistry) return { ready: false, languages: [], unavailableGrammars: [] };
    const allLangs = this.grammarRegistry.listLanguages();
    return { ready: true, languages: allLangs.filter(l => l.available).map(l => l.id), unavailableGrammars: allLangs.filter(l => !l.available).map(l => l.id) };
  }

  /** KSA-191: Get SFDX project stats from database. */
  getSfdxStats() { return getSfdxStatsImpl(this.adapter, this.config); }

  /**
   * SA4E-53: replaced prepare() calls with inline runAsync/allAsync.
   * SA4E-78: added signal for cooperative cancellation at batch boundaries.
   */
  private async indexFiles(files: ScannedFile[], projectId: string, signal?: AbortSignal): Promise<void> {
    const { filesToIndex, skippedCount } = await this.registerFilesForIndex(files, projectId, signal);
    if (signal?.aborted) return;
    const counts = this.treeSitterReady && this.treeSitterIndexer
      ? await this.indexFileSymbolsTreeSitter(filesToIndex, projectId, signal)
      : await this.indexFileSymbolsRegexFallback(filesToIndex, projectId, signal);
    logger.error(`[indexer] Indexed ${counts.treeSitterCount} files via tree-sitter, ${counts.regexCount} via regex fallback, ${skippedCount} unchanged`);
  }

  /**
   * Register files into DB and collect those needing symbol indexing.
   * SA4E-53: replaces prepare()+transaction() with runAsync()+transactionAsync().
   * SA4E-78: abort check at batch boundaries.
   */
  private async registerFilesForIndex(files: ScannedFile[], projectId: string, signal?: AbortSignal) {
    const filesToIndex: ScannedFile[] = [];
    let skippedCount = 0;
    const BATCH = 200;
    const insertSql = this.adapter.getEngine() === 'sqlite'
      ? `INSERT OR REPLACE INTO files (project_id,path,relative_path,language,module,content_hash,size_bytes,line_count,last_indexed,file_created_at,file_author,file_version) VALUES (?,?,?,?,?,?,?,?,${this.dialect.now()},?,?,?)`
      : `INSERT INTO files (project_id,path,relative_path,language,module,content_hash,size_bytes,line_count,last_indexed,file_created_at,file_author,file_version) VALUES (?,?,?,?,?,?,?,?,${this.dialect.now()},?,?,?) ON CONFLICT (project_id, path) DO UPDATE SET content_hash=EXCLUDED.content_hash, size_bytes=EXCLUDED.size_bytes, line_count=EXCLUDED.line_count, last_indexed=EXCLUDED.last_indexed, file_created_at=EXCLUDED.file_created_at, file_author=EXCLUDED.file_author, file_version=EXCLUDED.file_version`;
    for (let i = 0; i < files.length; i += BATCH) {
      if (signal?.aborted) break; // SA4E-78: cooperative cancellation
      const batch = files.slice(i, i + BATCH);
      await this.adapter.transactionAsync(async () => {
        for (const file of batch) {
          if (await isFileUnchanged(this.adapter, file, projectId)) { skippedCount++; continue; }
          filesToIndex.push(file);
          await this.adapter.runAsync(insertSql, [
            projectId, file.absolutePath, file.relativePath, file.language,
            detectModule(file.relativePath), file.contentHash, file.sizeBytes, file.lineCount,
            file.fileCreatedAt ?? null, file.fileAuthor ?? null, file.fileVersion ?? null,
          ]);
        }
      });
      this.emitProgress(projectId, 'indexing', Math.min(i + BATCH, files.length), files.length);
      await new Promise<void>(resolve => setImmediate(resolve));
    }
    return { filesToIndex, skippedCount };
  }

  private async indexFileSymbolsTreeSitter(filesToIndex: ScannedFile[], projectId: string, signal?: AbortSignal) {
    let treeSitterCount = 0;
    let regexCount = 0;
    for (let i = 0; i < filesToIndex.length; i += 50) {
      if (signal?.aborted) break; // SA4E-78: cooperative cancellation
      const batch = filesToIndex.slice(i, i + 50).map(f => ({ absolutePath: f.absolutePath, relativePath: f.relativePath }));
      for (const result of await this.treeSitterIndexer!.indexFiles(batch, projectId)) {
        if (result.method === 'tree-sitter') treeSitterCount++; else regexCount++;
      }
    }
    return { treeSitterCount, regexCount };
  }

  /**
   * SA4E-53: replaced prepare()+transaction() with transactionAsync()+runAsync().
   * SA4E-78: abort check at batch boundaries.
   */
  private async indexFileSymbolsRegexFallback(filesToIndex: ScannedFile[], projectId: string, signal?: AbortSignal) {
    logger.error('[indexer] Tree-sitter not available, using regex extraction');
    let regexCount = 0;
    const BATCH = 25;
    for (let i = 0; i < filesToIndex.length; i += BATCH) {
      if (signal?.aborted) break; // SA4E-78: cooperative cancellation
      const batch = filesToIndex.slice(i, i + BATCH);
      await this.adapter.transactionAsync(async () => {
        for (const file of batch) {
          const fileRow = await this.adapter.getAsync<{ id: number }>(
            'SELECT id FROM files WHERE relative_path = ? AND project_id = ?',
            [file.relativePath, projectId],
          );
          if (!fileRow) continue;
          await this.adapter.runAsync('DELETE FROM symbols WHERE file_id = ?', [fileRow.id]);
          await indexFileSymbolsRegex(file, fileRow.id, projectId, this.adapter, logger);
          regexCount++;
        }
      });
      await new Promise<void>(resolve => setImmediate(resolve));
    }
    return { treeSitterCount: 0, regexCount };
  }

  private async upsertFile(file: ScannedFile, projectId: string): Promise<IndexResult | null> {
    await upsertFileInDb(this.adapter, file, projectId);
    if (this.treeSitterReady && this.treeSitterIndexer) {
      return await this.treeSitterIndexer.indexFile(file.absolutePath, file.relativePath, projectId);
    }
    await upsertFileRegexFallback(this.adapter, file, projectId, logger);
    try {
      const source = fs.readFileSync(file.absolutePath, 'utf-8');
      const depResolver = new DependencyResolver();
      const dependencies = depResolver.resolve(source, file.relativePath, this.config.workspace);
      return {
        filePath: file.relativePath,
        symbolCount: 0,
        relationshipCount: 0,
        parseErrors: 0,
        duration: 0,
        method: 'regex-fallback',
        dependencies,
      };
    } catch {
      return null;
    }
  }

  private startWatcher(): void {
    if (!this.config.watchEnabled || !this.running) return;
    this.watcher = new FileWatcher(this.config, (filePath, event) => {
      if (event === 'unlink') this.removeFile(filePath);
      else this.indexSingleFile(filePath).catch(err => logger.error({ err }, `[indexer] Watch error ${filePath}:`));
    });
    this.watcher.start();
  }
}

/**
 * SA4E-108 — Unit tests for ProjectTypeDetector.
 * Covers: UT-01, UT-02, UT-09, UT-12
 */
import { describe, it, expect, vi } from 'vitest';
import { ProjectTypeDetector, type KBSearchFn } from '../detector.js';
import type { ProjectTypeConfig } from '../models.js';
import pino from 'pino';

const logger = pino({ level: 'silent' });

const JAVA_CONFIG: ProjectTypeConfig = {
  type_id: 'java-maven', display_name: 'Java (Maven)',
  signals: [{ file: 'pom.xml', confidence: 0.9 }],
  source_roots: ['src/main/java/'], test_roots: ['src/test/java/'],
  exclude_patterns: ['target/'], extensions: ['.java'],
  mono_repo_signals: [],
  priority: 10, auto_discovered: false,
};

function mockCache() {
  return {
    get: vi.fn().mockResolvedValue(null),
    set: vi.fn().mockResolvedValue(undefined),
    invalidate: vi.fn().mockResolvedValue(undefined),
    canDiscover: vi.fn().mockResolvedValue(true),
    markDiscovered: vi.fn().mockResolvedValue(undefined),
  } as any;
}

function mockKB(configs: ProjectTypeConfig[]): KBSearchFn {
  return vi.fn().mockResolvedValue(configs.map(c => ({ content: JSON.stringify(c) })));
}

describe('ProjectTypeDetector', () => {
  it('UT-12: returns built-in defaults when KB empty', async () => {
    const detector = new ProjectTypeDetector(mockKB([]), mockCache(), logger, [JAVA_CONFIG]);
    const configs = await detector.loadTypeDefinitions();
    expect(configs).toHaveLength(1);
    expect(configs[0].type_id).toBe('java-maven');
  });

  it('UT-09: invalidateConfigCache forces reload', async () => {
    const kb = mockKB([JAVA_CONFIG]);
    const detector = new ProjectTypeDetector(kb, mockCache(), logger);
    await detector.loadTypeDefinitions();
    detector.invalidateConfigCache();
    await detector.loadTypeDefinitions();
    expect(kb).toHaveBeenCalledTimes(2);
  });

  it('UT-02: returns fallback for non-existent path', async () => {
    const detector = new ProjectTypeDetector(mockKB([JAVA_CONFIG]), mockCache(), logger);
    const result = await detector.detect('/nonexistent/xyz');
    expect(result.project_type).toBe('fallback');
    expect(result.confidence).toBe(0);
  });

  it('loads configs sorted by priority', async () => {
    const low = { ...JAVA_CONFIG, type_id: 'low', priority: 1 };
    const high = { ...JAVA_CONFIG, type_id: 'high', priority: 99 };
    const detector = new ProjectTypeDetector(mockKB([low, high]), mockCache(), logger);
    const configs = await detector.loadTypeDefinitions();
    expect(configs[0].type_id).toBe('high');
  });
});

/**
 * SA4E-108 — ProjectTypeDetector.
 * Loads type definitions from KB, scans workspace for build files,
 * scores confidence, and returns DetectionResult.
 */
import { readdir } from 'fs/promises';
import { join, relative } from 'path';
import type { Logger } from 'pino';
import {
  type DetectionResult,
  FALLBACK_TYPE,
  type ProjectTypeConfig,
  ProjectTypeConfigSchema,
  type ScoredMatch,
  type Signal,
} from './models.js';
import type { ProjectTypeCache } from './cache.js';

/** Confidence threshold — below this, fallback activates (BR-01) */
const CONFIDENCE_THRESHOLD = 0.5;
/** Max directory depth for build file scanning */
const MAX_SCAN_DEPTH = 2;
/** Directories to skip during build file scan */
const SKIP_DIRS = ['.git', 'node_modules', 'target', 'build', 'dist', '__pycache__'];

/** KB search function signature */
export interface KBEntry { content: string; }
export type KBSearchFn = (query: string, opts: { type: string; limit: number }) => Promise<KBEntry[]>;

/**
 * Detects project type by matching workspace files against
 * KB-stored type definitions. Caches results for performance.
 */
export class ProjectTypeDetector {
  private configCache: ProjectTypeConfig[] | null = null;

  constructor(
    private readonly kbSearch: KBSearchFn,
    private readonly cache: ProjectTypeCache,
    private readonly logger: Logger,
    private readonly builtInDefaults: ProjectTypeConfig[] = [],
  ) {}

  /** Load type definitions from KB (cached in-memory) */
  async loadTypeDefinitions(): Promise<ProjectTypeConfig[]> {
    if (this.configCache) return this.configCache;
    try {
      const results = await this.kbSearch('project-type-config', { type: 'ARCHITECTURE', limit: 50 });
      const configs = this.parseConfigs(results);
      if (configs.length === 0) return this.loadBuiltInDefaults();
      this.configCache = configs.sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0));
      return this.configCache;
    } catch (err) {
      this.logger.warn({ err }, 'KB unavailable, using built-in defaults');
      return this.loadBuiltInDefaults();
    }
  }

  /** Detect project type for workspace */
  async detect(workspacePath: string): Promise<DetectionResult> {
    const cached = await this.cache.get(workspacePath);
    if (cached) return cached;
    const configs = await this.loadTypeDefinitions();
    const buildFiles = await this.scanBuildFiles(workspacePath);
    const matches = this.scoreAll(configs, buildFiles);
    if (matches.length === 0) return this.buildFallback(workspacePath);
    const best = matches[0];
    const result = this.buildResult(best);
    await this.cache.set(workspacePath, result);
    return result;
  }

  /** Force re-detection bypassing cache (BR-06) */
  async redetect(workspacePath: string): Promise<DetectionResult> {
    await this.cache.invalidate(workspacePath);
    return this.detect(workspacePath);
  }

  /** Clear in-memory config cache */
  invalidateConfigCache(): void { this.configCache = null; }

  // --- Private ---

  private parseConfigs(results: KBEntry[]): ProjectTypeConfig[] {
    return results
      .map(r => { try { return ProjectTypeConfigSchema.safeParse(JSON.parse(r.content)); } catch { return { success: false as const, error: null, data: undefined }; } })
      .filter(r => r.success)
      .map(r => r.data) as ProjectTypeConfig[];
  }

  private loadBuiltInDefaults(): ProjectTypeConfig[] {
    this.configCache = this.builtInDefaults;
    return this.builtInDefaults;
  }

  private async scanBuildFiles(dir: string, depth = 0): Promise<string[]> {
    if (depth > MAX_SCAN_DEPTH) return [];
    const files: string[] = [];
    try {
      const entries = await readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile()) {
          files.push(entry.name);
        } else if (entry.isDirectory() && depth < MAX_SCAN_DEPTH && !SKIP_DIRS.includes(entry.name)) {
          const sub = await this.scanBuildFiles(join(dir, entry.name), depth + 1);
          files.push(...sub.map(f => join(entry.name, f)));
        }
      }
    } catch { /* permission error */ }
    return files;
  }

  private scoreAll(configs: ProjectTypeConfig[], files: string[]): ScoredMatch[] {
    return configs
      .map(config => ({ config, ...this.matchSignals(config.signals, files) }))
      .filter(m => m.score >= CONFIDENCE_THRESHOLD)
      .sort((a, b) => b.score - a.score);
  }

  /** Match signals against files — return highest confidence (PBT-01: always 0-1) */
  private matchSignals(signals: Signal[], files: string[]): { score: number; matchedFiles: string[] } {
    let maxScore = 0;
    const matched: string[] = [];
    for (const signal of signals) {
      const found = files.filter(f => this.fileMatches(f, signal.file));
      if (found.length > 0) {
        maxScore = Math.max(maxScore, signal.confidence);
        matched.push(...found);
      }
    }
    return { score: maxScore, matchedFiles: [...new Set(matched)] };
  }

  private fileMatches(filePath: string, pattern: string): boolean {
    const name = filePath.split(/[/\\]/).pop() ?? '';
    if (pattern.includes('*')) {
      const re = new RegExp('^' + pattern.replace(/\./g, '\\.').replace(/\*/g, '.*') + '$');
      return re.test(name);
    }
    return name === pattern;
  }

  private buildResult(match: ScoredMatch): DetectionResult {
    return {
      project_type: match.config.type_id,
      build_tool: match.config.type_id.split('-').pop() ?? 'unknown',
      confidence: match.score,
      detected_files: match.matchedFiles,
      source_roots: match.config.source_roots,
      test_roots: match.config.test_roots ?? [],
      exclude_patterns: match.config.exclude_patterns,
      extensions: match.config.extensions,
      is_mono_repo: false,
    };
  }

  private buildFallback(workspacePath: string): DetectionResult {
    this.logger.info({ workspacePath }, 'No project type detected, using fallback');
    return {
      project_type: FALLBACK_TYPE, build_tool: 'none', confidence: 0,
      detected_files: [], source_roots: [], test_roots: [],
      exclude_patterns: [], extensions: [], is_mono_repo: false,
    };
  }
}

/**
 * SFDX Helper — Standalone functions for Salesforce DX project detection and stats.
 */

import * as fs from 'fs';
import * as path from 'path';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import type { AppConfig } from '../config.js';
import type { Logger } from 'pino';

/** Detect whether the workspace is an SFDX project. */
export function detectSfdxProject(workspace: string): boolean {
  return fs.existsSync(path.join(workspace, 'sfdx-project.json'))
    || fs.existsSync(path.join(workspace, 'force-app'));
}

function readPackageDirectories(workspace: string): string[] {
  const sfdxConfigPath = path.join(workspace, 'sfdx-project.json');
  if (!fs.existsSync(sfdxConfigPath)) return ['force-app'];
  try {
    const config = JSON.parse(fs.readFileSync(sfdxConfigPath, 'utf-8'));
    if (Array.isArray(config.packageDirectories)) {
      return config.packageDirectories
        .map((pd: any) => pd.path ?? pd)
        .filter(Boolean);
    }
  } catch (err) { console.debug('[sfdx-helper] Failed to parse sfdx-project.json (non-fatal):', (err as Error).message); }
  return ['force-app'];
}

function queryModuleStats(adapter: DatabaseAdapter): { apex_classes: number; apex_triggers: number; flows: number; objects: number; lwc_components: number; } {
  const moduleCounts = adapter.all<{ module: string; count: number }>(
    `SELECT module, COUNT(*) as count FROM files
     WHERE module IN ('apex-classes', 'apex-triggers', 'sf-flows', 'sf-objects', 'lwc-components')
     GROUP BY module`,
  );

  const stats = { apex_classes: 0, apex_triggers: 0, flows: 0, objects: 0, lwc_components: 0 };
  for (const row of moduleCounts) {
    switch (row.module) {
      case 'apex-classes': stats.apex_classes = row.count; break;
      case 'apex-triggers': stats.apex_triggers = row.count; break;
      case 'sf-flows': stats.flows = row.count; break;
      case 'sf-objects': stats.objects = row.count; break;
      case 'lwc-components': stats.lwc_components = row.count; break;
    }
  }
  return stats;
}

function querySfRelationships(adapter: DatabaseAdapter): Record<string, number> {
  const sfKinds = ['trigger-on', 'soql', 'dml', 'wire', 'flow-action', 'flow-object', 'apex-import', 'inherits', 'implements'];
  const relCounts = adapter.all<{ kind: string; count: number }>(
    `SELECT kind, COUNT(*) as count FROM relationships
     WHERE kind IN (${sfKinds.map(() => '?').join(',')})
     GROUP BY kind`,
    sfKinds,
  );

  const relationships: Record<string, number> = {};
  for (const row of relCounts) relationships[row.kind] = row.count;
  return relationships;
}

function queryLastIndexed(adapter: DatabaseAdapter): string | null {
  const lastRow = adapter.get<{ t: string | null }>(
    `SELECT MAX(last_indexed) as t FROM files WHERE language IN ('apex', 'salesforce-meta')`,
  );
  return lastRow?.t ?? null;
}

/** Get SFDX project stats from database. */
export function getSfdxStats(
  adapter: DatabaseAdapter, config: AppConfig
): {
  detected: boolean;
  projectRoot: string | null;
  packageDirectories: string[];
  stats: { apex_classes: number; apex_triggers: number; flows: number; objects: number; lwc_components: number };
  lastIndexed: string | null;
  relationships: Record<string, number>;
} | null {
  if (!detectSfdxProject(config.workspace)) return null;
  return {
    detected: true,
    projectRoot: config.workspace,
    packageDirectories: readPackageDirectories(config.workspace),
    stats: queryModuleStats(adapter),
    lastIndexed: queryLastIndexed(adapter),
    relationships: querySfRelationships(adapter),
  };
}

/** Log SFDX-specific stats after indexing. */
export function logSfdxStats(adapter: DatabaseAdapter, config: AppConfig, logger: Logger): void {
  const sfdxStats = getSfdxStats(adapter, config);
  if (!sfdxStats) return;

  const { stats, relationships } = sfdxStats;
  const totalSf = stats.apex_classes + stats.apex_triggers + stats.flows + stats.objects + stats.lwc_components;
  if (totalSf === 0) return;

  const relCount = Object.values(relationships).reduce((a, b) => a + b, 0);
  logger.error(
    `[indexer] SF stats: ${stats.apex_classes} apex classes, ${stats.apex_triggers} triggers, ` +
    `${stats.flows} flows, ${stats.objects} objects, ${stats.lwc_components} LWC — ${relCount} relationships`
  );
}

/**
 * SA4E-78 — DependencyResolver (static-only, no filesystem access).
 * Resolves import/require statements to candidate file paths.
 * Hash verification is deferred to when content is available via the indexer.
 */

import type { FileDependency } from './types.js';
import * as path from 'path';
import { PegaRuleAstParser } from '../../modules/pega/PegaRuleAstParser.js';

const AST_PARSER = new PegaRuleAstParser();

export class DependencyResolver {
  resolve(source: string, filePath: string, workspace: string): FileDependency[] {
    const ext = path.extname(filePath).toLowerCase();
    if (ext === '.ts' || ext === '.tsx' || ext === '.js' || ext === '.jsx' || ext === '.mjs' || ext === '.cjs') {
      return this.resolveTsJs(source, filePath, workspace);
    }
    if (ext === '.java') {
      return this.resolveJava(source, filePath, workspace);
    }
    if (ext === '.py') {
      return this.resolvePython(source, filePath, workspace);
    }
    if (ext === '.pega') {
      return this.resolvePega(source, filePath, workspace);
    }
    return [];
  }

  /**
   * Static TS/JS import resolution — compute candidate path without reading files.
   * Hash verification deferred to indexer (SA4E-78: AD-7).
   */
  private resolveTsJs(source: string, filePath: string, _workspace: string): FileDependency[] {
    const deps: FileDependency[] = [];
    const dir = path.posix.dirname(filePath);
    const importRe = /from\s+['"]([^'"]+)['"]|require\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
    const seen = new Set<string>();
    let match: RegExpExecArray | null;
    while ((match = importRe.exec(source)) !== null) {
      const modulePath = match[1] || match[2];
      if (!modulePath || seen.has(modulePath)) continue;
      seen.add(modulePath);
      if (modulePath.startsWith('.')) {
        // Static resolution: compute candidate path, no file read
        const candidate = path.posix.resolve(dir, modulePath);
        deps.push({ path: candidate, expectedHash: '', sourceType: 'local' });
      }
    }
    return deps;
  }

  private resolveJava(source: string, filePath: string, workspace: string): FileDependency[] {
    const deps: FileDependency[] = [];
    const importRe = /^import\s+(?:static\s+)?([a-zA-Z0-9_.*]+)\s*;/gm;
    const seen = new Set<string>();
    let match: RegExpExecArray | null;
    while ((match = importRe.exec(source)) !== null) {
      const importPath = match[1];
      if (!importPath || importPath.includes('*') || seen.has(importPath)) continue;
      seen.add(importPath);
      const fileRelPath = importPath.replace(/\./g, '/') + '.java';
      if (fileRelPath.startsWith('java/') || fileRelPath.startsWith('javax/') || fileRelPath.startsWith('org/springframework/') || fileRelPath.startsWith('com/fasterxml/') || fileRelPath.startsWith('org/apache/') || fileRelPath.startsWith('org/slf4j/') || fileRelPath.startsWith('org/junit/') || fileRelPath.startsWith('org/mockito/') || fileRelPath.startsWith('lombok/')) continue;
      deps.push({
        path: fileRelPath,
        expectedHash: '',
        sourceType: 'local',
      });
    }
    return deps;
  }

  private resolvePython(source: string, filePath: string, workspace: string): FileDependency[] {
    const deps: FileDependency[] = [];
    const importRe = /^(?:from\s+([a-zA-Z0-9_.]+)\s+)?import\s+([a-zA-Z0-9_* ,]+)/gm;
    const seen = new Set<string>();
    let match: RegExpExecArray | null;
    while ((match = importRe.exec(source)) !== null) {
      const fromModule = match[1];
      const modulePath = fromModule || match[2].split(',')[0].trim();
      if (!modulePath || seen.has(modulePath)) continue;
      seen.add(modulePath);
      if (modulePath.startsWith('.')) {
        const parts = filePath.split('/');
        const base = parts.slice(0, -1);
        const levels = modulePath.split('.');
        let rel: string;
        if (levels[0] === '') {
          rel = path.posix.join(...base, ...levels.slice(1).filter(Boolean));
        } else {
          rel = path.posix.join(...base, ...levels.filter(Boolean));
        }
        deps.push({
          path: rel + '.py',
          expectedHash: '',
          sourceType: 'local',
        });
      }
    }
    return deps;
  }

  /**
   * Static Pega reference resolution — parse AST references without file reads.
   * SA4E-78: hash deferred, no filesystem coupling.
   */
  private resolvePega(source: string, _filePath: string, _workspace: string): FileDependency[] {
    const deps: FileDependency[] = [];
    try {
      const json = JSON.parse(source);
      const ast = AST_PARSER.parse(json);
      for (const ref of ast.references) {
        const targetFile = this.pegaRefToFilePath(ref);
        deps.push({ path: targetFile, expectedHash: '', sourceType: 'local' });
      }
    } catch {
      // JSON parse failed — skip
    }
    return deps;
  }

  private pegaRefToFilePath(ref: { ruleType: string; className: string; ruleName: string }): string {
    const typePart = ref.ruleType.replace(/-/g, '-');
    const cls = ref.className.replace(/^@/, '');
    return cls ? `${cls}.${ref.ruleName}.${typePart}.pega` : `${ref.ruleName}.${typePart}.pega`;
  }
}

import { pipeline, env, FeatureExtractionPipeline } from '@xenova/transformers';

// Suppress local file warnings, force downloading from HF Hub if not available locally
(env as any).allowLocalModels = false;

export class EmbeddingService {
  private static instance: EmbeddingService;
  private extractorPromise: Promise<FeatureExtractionPipeline> | null = null;
  private readonly modelName = 'Xenova/paraphrase-multilingual-MiniLM-L12-v2';

  private constructor() {}

  public static getInstance(): EmbeddingService {
    if (!EmbeddingService.instance) {
      EmbeddingService.instance = new EmbeddingService();
    }
    return EmbeddingService.instance;
  }

  /**
   * Initialize the pipeline. This downloads the model on first run.
   */
  private async getExtractor(): Promise<FeatureExtractionPipeline> {
    if (!this.extractorPromise) {
      this.extractorPromise = pipeline('feature-extraction', this.modelName, {
        quantized: true, // Use quantized model for performance
      }) as Promise<FeatureExtractionPipeline>;
    }
    return this.extractorPromise;
  }

  /**
   * Generates a dense vector embedding for the given text.
   */
  public async generateEmbedding(text: string): Promise<number[]> {
    const extractor = await this.getExtractor();
    const output = await extractor(text, { pooling: 'mean', normalize: true });
    
    // Output tensor data is Float32Array
    const data = output.data;
    const array = new Array(data.length);
    for (let i = 0; i < data.length; i++) {
      array[i] = data[i];
    }
    return array;
  }

  /**
   * Calculates cosine similarity between two vectors.
   */
  public cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length) throw new Error('Vector dimension mismatch');
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }
    if (normA === 0 || normB === 0) return 0;
    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }
}

/**
 * KSA-169: Body Extractor — Extract function bodies from tree-sitter AST.
 * Provides full body text for embedding generation.
 */

import type { Parser, Tree, Node } from 'web-tree-sitter';
import type { SyntaxNode } from '../types.js';
import { getNodeText, getNodeRange } from '../ast-utils.js';

export interface FunctionBody {
  symbolId: string;
  name: string;
  bodyText: string;
  tokenCount: number;
  startLine: number;
  endLine: number;
}

export class BodyExtractor {
  private minBodyLines: number;
  private maxBodyTokens: number;

  constructor(minBodyLines: number = 3, maxBodyTokens: number = 10_000) {
    this.minBodyLines = minBodyLines;
    this.maxBodyTokens = maxBodyTokens;
  }

  extractBody(node: SyntaxNode, source: string): string | null {
    const bodyNode = this.findBodyNode(node);
    if (!bodyNode) return null;

    const bodyText = getNodeText(bodyNode, source);
    const lineCount = bodyText.split('\n').length;
    if (lineCount < this.minBodyLines) return null;

    const tokenCount = this.estimateTokens(bodyText);
    if (tokenCount > this.maxBodyTokens) {
      return this.truncateToTokens(bodyText, this.maxBodyTokens);
    }

    return bodyText;
  }

  extractAllBodies(tree: Tree, source: string, filePath: string): FunctionBody[] {
    const bodies: FunctionBody[] = [];
    const functionTypes = new Set([
      'function_declaration', 'method_definition',
      'arrow_function', 'function_expression',
      'generator_function_declaration',
      'function_definition', 'method_declaration',
    ]);

    const stack: SyntaxNode[] = [tree.rootNode];
    while (stack.length > 0) {
      const node = stack.pop()!;

      if (functionTypes.has(node.type)) {
        const body = this.extractBody(node, source);
        if (body) {
          const name = this.extractFunctionName(node, source);
          const range = getNodeRange(node);
          const tokenCount = this.estimateTokens(body);

          bodies.push({
            symbolId: `${filePath}:${name}:${range.startLine}`,
            name,
            bodyText: body,
            tokenCount,
            startLine: range.startLine,
            endLine: range.endLine,
          });
        }
      }

      for (let i = node.childCount - 1; i >= 0; i--) {
        const child = node.child(i);
        if (child) stack.push(child);
      }
    }

    return bodies;
  }

  private findBodyNode(node: SyntaxNode): SyntaxNode | null {
    const bodyTypes = ['statement_block', 'block', 'function_body', 'class_body'];
    for (let i = 0; i < node.namedChildCount; i++) {
      const child = node.namedChild(i);
      if (child && bodyTypes.includes(child.type)) return child;
    }
    return null;
  }

  private extractFunctionName(node: SyntaxNode, source: string): string {
    const nameTypes = ['identifier', 'property_identifier', 'type_identifier'];
    for (let i = 0; i < node.namedChildCount; i++) {
      const child = node.namedChild(i);
      if (child && nameTypes.includes(child.type)) {
        return getNodeText(child, source);
      }
    }

    if (node.parent?.type === 'variable_declarator') {
      for (let i = 0; i < node.parent.namedChildCount; i++) {
        const child = node.parent.namedChild(i);
        if (child && child.type === 'identifier') {
          return getNodeText(child, source);
        }
      }
    }

    return '<anonymous>';
  }

  private estimateTokens(text: string): number {
    return text.split(/[\s\n\r\t]+/).filter(Boolean).length;
  }

  private truncateToTokens(text: string, maxTokens: number): string {
    const words = text.split(/[\s\n\r\t]+/);
    if (words.length <= maxTokens) return text;
    return words.slice(0, maxTokens).join(' ');
  }
}

/**
 * KSA-145: Grammar Registry — Manages tree-sitter WASM grammar loading and caching.
 * Maps file extensions to language parsers, lazy-loads grammars on first use.
 * KSA-191: Added null wasmPath support + compound extension matching.
 */

import { Parser, Language } from 'web-tree-sitter';
import type { Node } from 'web-tree-sitter';
import * as path from 'path';
import * as fs from 'fs';
import pino from 'pino';
import type { ILanguageParser } from './types.js';

const logger = pino({ name: 'grammar-registry' });

export interface LanguageConfig {
  id: string;
  extensions: string[];
  wasmPath: string | null;
  parserModule: string;
}

export interface GrammarRegistryConfig {
  languages: LanguageConfig[];
  grammarDir: string;
}

export class GrammarRegistry {
  private config: GrammarRegistryConfig;
  private parsers: Map<string, any> = new Map();
  private languageParsers: Map<string, ILanguageParser> = new Map();
  private extensionMap: Map<string, string> = new Map();
  private unavailable: Set<string> = new Set();
  private initialized = false;
  private ParserClass: typeof Parser | null = null;

  constructor(config: GrammarRegistryConfig) {
    this.config = config;
    this.buildExtensionMap();
  }

  /** Initialize web-tree-sitter WASM runtime. Must be called before parsing. */
  async initialize(): Promise<void> {
    if (this.initialized) return;
    await Parser.init();
    this.ParserClass = Parser;
    this.initialized = true;
    logger.error('[grammar-registry] Tree-sitter WASM runtime initialized');
  }

  /** Get a parser for a file path based on extension. Returns null if unsupported. */
  async getParser(filePath: string): Promise<ILanguageParser | null> {
    if (!this.initialized) await this.initialize();

    const langId = this.getLanguageId(filePath);
    if (!langId || this.unavailable.has(langId)) return null;

    if (this.languageParsers.has(langId)) {
      return this.languageParsers.get(langId)!;
    }

    return this.loadParser(langId);
  }

  /** Get language ID for a file — supports compound extensions (longest match wins). */
  getLanguageId(filePath: string): string | null {
    const lowerPath = filePath.toLowerCase().replace(/\\/g, '/');

    // Try compound extensions first (longest match wins)
    for (const [ext, langId] of this.extensionMap.entries()) {
      // Compound extensions have multiple dots (e.g., .flow-meta.xml)
      if (ext.split('.').length > 2 && lowerPath.endsWith(ext)) {
        return langId;
      }
    }

    // Fall back to simple extension
    const ext = path.extname(lowerPath);
    return this.extensionMap.get(ext) ?? null;
  }

  /** List all registered languages. */
  listLanguages(): { id: string; extensions: string[]; available: boolean }[] {
    return this.config.languages.map(lang => ({
      id: lang.id,
      extensions: lang.extensions,
      available: !this.unavailable.has(lang.id),
    }));
  }

  /** Check if a language grammar is available. */
  isAvailable(langId: string): boolean {
    return !this.unavailable.has(langId) &&
      this.config.languages.some(l => l.id === langId);
  }

  private async loadParser(langId: string): Promise<ILanguageParser | null> {
    const langConfig = this.config.languages.find(c => c.id === langId);
    if (!langConfig) return null;

    try {
      let parser: any = null;

      if (langConfig.wasmPath) {
        // Standard tree-sitter path (existing behavior)
        const wasmPath = path.resolve(this.config.grammarDir, langConfig.wasmPath);

        if (!fs.existsSync(wasmPath)) {
          logger.error(`[grammar-registry] WASM not found: ${wasmPath}`);
          this.unavailable.add(langId);
          return null;
        }

        parser = new Parser();
        const language = await Language.load(wasmPath);
        parser.setLanguage(language);
        this.parsers.set(langId, parser);
      }
      // If wasmPath is null, parser stays null — passed to constructor as-is

      // Dynamically import the language parser module
      const modulePath = langConfig.parserModule;
      const imported = await import(modulePath);
      // Handle both ESM default export and CJS module.exports.default
      const LangParserClass = imported.default?.default ?? imported.default ?? imported;
      if (typeof LangParserClass !== 'function') {
        throw new TypeError(`LangParserClass is not a constructor (got ${typeof LangParserClass})`);
      }
      const langParser: ILanguageParser = new LangParserClass(parser, langId);
      this.languageParsers.set(langId, langParser);

      logger.error(`[grammar-registry] Loaded grammar: ${langId}`);
      return langParser;
    } catch (error) {
      logger.error({ error }, `[grammar-registry] Failed to load ${langId}:`);
      this.unavailable.add(langId);
      return null;
    }
  }

  private buildExtensionMap(): void {
    // Sort languages so compound extensions (longer) are registered first
    const sorted = [...this.config.languages].sort((a, b) => {
      const maxA = Math.max(...a.extensions.map(e => e.length));
      const maxB = Math.max(...b.extensions.map(e => e.length));
      return maxB - maxA; // Longer extensions first
    });

    for (const lang of sorted) {
      for (const ext of lang.extensions) {
        this.extensionMap.set(ext, lang.id);
      }
    }
  }
}

/** Load grammar registry config from JSON file. */
export function loadGrammarConfig(configPath: string): GrammarRegistryConfig {
  const raw = fs.readFileSync(configPath, 'utf-8');
  const data = JSON.parse(raw);
  return {
    languages: data.languages ?? [],
    grammarDir: path.dirname(configPath),
  };
}

/**
 * KSA-152: Grammar Configuration Loader.
 * Loads per-language JSON grammar configs and provides a LanguageRegistry.
 */

import * as fs from 'fs';
import * as path from 'path';
import pino from 'pino';

const logger = pino({ name: 'grammar-config-loader' });

export interface EntityConfig {
  nodeTypes: string[];
  nameField: string;
  bodyField?: string;
  kind: string;
  extractParams?: boolean;
  extractReturnType?: boolean;
  extractModifiers?: boolean;
}

export interface RelationshipConfig {
  nodeTypes: string[];
  kind: string;
  sourceField?: string;
  targetField?: string;
}

export interface ScopingConfig {
  classContainers: string[];
  namespaceContainers: string[];
}

export interface ParserConfig {
  includePrivate: boolean;
  includeTests: boolean;
  parseDocs: boolean;
  maxFileSize: number;
  maxFunctionSize: number;
  timeoutPerFile: number;
}

export interface GrammarConfig {
  schemaVersion: string;
  language: string;
  displayName: string;
  extensions: string[];
  grammarWasm: string;
  parserConfig: ParserConfig;
  entities: Record<string, EntityConfig>;
  relationships: Record<string, RelationshipConfig>;
  scoping: ScopingConfig;
}

const DEFAULT_PARSER_CONFIG: ParserConfig = {
  includePrivate: false,
  includeTests: false,
  parseDocs: true,
  maxFileSize: 1_048_576,
  maxFunctionSize: 10_000,
  timeoutPerFile: 5000,
};

export class LanguageRegistry {
  private extMap: Map<string, GrammarConfig> = new Map();
  private languages: Map<string, GrammarConfig> = new Map();

  register(config: GrammarConfig): void {
    this.languages.set(config.language, config);
    for (const ext of config.extensions) {
      this.extMap.set(ext, config);
    }
  }

  getByExtension(ext: string): GrammarConfig | null {
    return this.extMap.get(ext) ?? null;
  }

  getByName(name: string): GrammarConfig | null {
    return this.languages.get(name) ?? null;
  }

  listLanguages(): { language: string; displayName: string; extensions: string[] }[] {
    return Array.from(this.languages.values()).map(c => ({
      language: c.language,
      displayName: c.displayName,
      extensions: c.extensions,
    }));
  }

  get size(): number {
    return this.languages.size;
  }
}

export function loadGrammarConfigs(configDir: string): LanguageRegistry {
  const registry = new LanguageRegistry();

  if (!fs.existsSync(configDir)) {
    logger.error(`[grammar-config] Config directory not found: ${configDir}`);
    return registry;
  }

  const files = fs.readdirSync(configDir).filter(
    f => f.endsWith('.grammar.json')
  );

  for (const file of files) {
    try {
      const filePath = path.join(configDir, file);
      const raw = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      const config = parseGrammarConfig(raw);
      if (config) {
        registry.register(config);
        logger.error(`[grammar-config] Loaded: ${config.language} (${config.extensions.join(', ')})`);
      }
    } catch (err) {
      logger.error({ err }, `[grammar-config] Failed to load ${file}:`);
    }
  }

  return registry;
}

function parseGrammarConfig(raw: Record<string, unknown>): GrammarConfig | null {
  if (!raw.language || !raw.extensions || !raw.grammar_wasm || !raw.entities) {
    return null;
  }

  const entities: Record<string, EntityConfig> = {};
  if (typeof raw.entities === 'object' && raw.entities) {
    for (const [key, val] of Object.entries(raw.entities as Record<string, any>)) {
      entities[key] = {
        nodeTypes: val.node_types ?? [],
        nameField: val.name_field ?? 'identifier',
        bodyField: val.body_field,
        kind: val.kind ?? key,
        extractParams: val.extract_params ?? false,
        extractReturnType: val.extract_return_type ?? false,
        extractModifiers: val.extract_modifiers ?? false,
      };
    }
  }

  const relationships: Record<string, RelationshipConfig> = {};
  if (typeof raw.relationships === 'object' && raw.relationships) {
    for (const [key, val] of Object.entries(raw.relationships as Record<string, any>)) {
      relationships[key] = {
        nodeTypes: val.node_types ?? [],
        kind: val.kind ?? key,
        sourceField: val.source_field,
        targetField: val.target_field,
      };
    }
  }

  const scopingRaw = raw.scoping as Record<string, any> | undefined;
  const scoping: ScopingConfig = {
    classContainers: scopingRaw?.class_containers ?? ['class_declaration'],
    namespaceContainers: scopingRaw?.namespace_containers ?? ['module', 'namespace_declaration'],
  };

  const parserRaw = raw.parser_config as Record<string, any> | undefined;
  const parserConfig: ParserConfig = {
    ...DEFAULT_PARSER_CONFIG,
    ...(parserRaw ? {
      includePrivate: parserRaw.include_private ?? DEFAULT_PARSER_CONFIG.includePrivate,
      includeTests: parserRaw.include_tests ?? DEFAULT_PARSER_CONFIG.includeTests,
      parseDocs: parserRaw.parse_docs ?? DEFAULT_PARSER_CONFIG.parseDocs,
      maxFileSize: parserRaw.max_file_size ?? DEFAULT_PARSER_CONFIG.maxFileSize,
      maxFunctionSize: parserRaw.max_function_size ?? DEFAULT_PARSER_CONFIG.maxFunctionSize,
      timeoutPerFile: parserRaw.timeout_per_file ?? DEFAULT_PARSER_CONFIG.timeoutPerFile,
    } : {}),
  };

  return {
    schemaVersion: String(raw.schema_version ?? '1.0'),
    language: String(raw.language),
    displayName: String(raw.display_name ?? raw.language),
    extensions: raw.extensions as string[],
    grammarWasm: String(raw.grammar_wasm),
    parserConfig,
    entities,
    relationships,
    scoping,
  };
}

export function resolveParserConfig(
  globalConfig: ParserConfig,
  languageConfig?: Partial<ParserConfig>
): ParserConfig {
  if (!languageConfig) return globalConfig;
  return { ...globalConfig, ...languageConfig };
}

/**
 * SA4E-169 — Unit tests for the gitignore-style ignore parser.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { IgnoreParser, createIgnoreParser, DEFAULT_IGNORE_PATTERNS } from '../ignore-parser.js';

let dir: string;

describe('IgnoreParser', () => {
  let parser: IgnoreParser;

  it('loads default patterns on construction', () => {
    parser = new IgnoreParser();
    const patterns = parser.getPatterns();
    expect(patterns.length).toBeGreaterThanOrEqual(DEFAULT_IGNORE_PATTERNS.length);
    expect(parser.shouldIgnore('node_modules/lodash/index.js')).toBe(true);
    expect(parser.shouldIgnore('dist/bundle.js')).toBe(true);
    expect(parser.shouldIgnore('src/app.ts')).toBe(false);
  });

  it('ignores git directory and dot-prefixed paths from defaults', () => {
    parser = new IgnoreParser();
    expect(parser.shouldIgnore('.git/config')).toBe(true);
    expect(parser.shouldIgnore('.git/HEAD')).toBe(true);
  });

  it('respects directory patterns anywhere in the path', () => {
    parser = new IgnoreParser();
    expect(parser.shouldIgnore('a/b/node_modules/x/y.js')).toBe(true);
  });

  it('adds custom patterns via addPatterns', () => {
    parser = new IgnoreParser();
    parser.addPatterns(['*.min.js'], 'custom');
    expect(parser.shouldIgnore('vendor/lib.min.js')).toBe(true);
    expect(parser.shouldIgnore('vendor/lib.js')).toBe(false);
  });

  it('supports negation to re-include ignored files', () => {
    const ignore = new IgnoreParser();
    ignore.addPatterns(['*.log', '!keep.log', 'vendor/'], 'custom');
    expect(ignore.shouldIgnore('temp.log')).toBe(true);
    expect(ignore.shouldIgnore('keep.log')).toBe(false);
    expect(ignore.shouldIgnore('vendor/files.js')).toBe(true);
  });

  it('ignores comment lines and empty patterns', () => {
    parser = new IgnoreParser();
    parser.addPatterns(['# a comment', '', '   ', 'build/'], 'custom');
    expect(parser.getPatterns().filter(p => p.sourceFile === 'custom')).toHaveLength(1);
  });

  it('handles ** globstar patterns across nested segments', () => {
    parser = new IgnoreParser();
    parser.addPatterns(['src/**/generated.ts'], 'custom');
    expect(parser.shouldIgnore('src/a/b/generated.ts')).toBe(true);
    expect(parser.shouldIgnore('src/nested/generated.ts')).toBe(true);
    expect(parser.shouldIgnore('other/generated.ts')).toBe(false);
  });

  it('normalizes Windows-style separators', () => {
    parser = new IgnoreParser();
    parser.addPatterns(['dist/'], 'custom');
    expect(parser.shouldIgnore('dist\\bundle.js')).toBe(true);
  });

  it('parseFile tolerates missing files', () => {
    parser = new IgnoreParser();
    expect(() => parser.parseFile(path.join(os.tmpdir(), 'missing-ignore-file-' + Date.now()))).not.toThrow();
  });
});

describe('createIgnoreParser', () => {
  let ws: string;

  beforeAll(() => {
    ws = fs.mkdtempSync(path.join(os.tmpdir(), 'code-intel-ignore-'));
  });

  afterAll(() => {
    fs.rmSync(ws, { recursive: true, force: true });
  });

  it('reads patterns from .gitignore', () => {
    fs.writeFileSync(path.join(ws, '.gitignore'), '*.tmp\n');
    const parser = createIgnoreParser(ws);
    expect(parser.shouldIgnore('scratch.tmp')).toBe(true);
    expect(parser.shouldIgnore('scratch.ts')).toBe(false);
  });

  it('reads patterns from .codeintelignore', () => {
    fs.writeFileSync(path.join(ws, '.codeintelignore'), 'generated/\n');
    const parser = createIgnoreParser(ws);
    expect(parser.shouldIgnore('generated/x.ts')).toBe(true);
  });

  it('returns a parser with only defaults when no files exist', () => {
    const empty = fs.mkdtempSync(path.join(os.tmpdir(), 'code-intel-ignore-empty-'));
    try {
      const parser = createIgnoreParser(empty);
      expect(parser.getPatterns().length).toBeGreaterThanOrEqual(DEFAULT_IGNORE_PATTERNS.length);
    } finally {
      fs.rmSync(empty, { recursive: true, force: true });
    }
  });
});

