import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship, SymbolKind } from '../../types.js';
import { getNodeText, getNodeRange, getNamedChild, extractDocComment } from '../../ast-utils.js';
import { buildMethodSignature } from '../common.js';
import { extractApexModifiers, extractApexAnnotations, calculateApexComplexity } from './helpers.js';
import { extractMethod, extractConstructor, extractFields } from './members.js';
import { extractApexInheritance } from './relationships.js';

export function extractDeclarations(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[], depth: number = 0,
): void {
  if (depth > 10) return;
  for (let i = 0; i < node.namedChildCount; i++) {
    const child = node.namedChild(i);
    if (!child) continue;
    switch (child.type) {
      case 'class_declaration':
        extractType(child, source, filePath, parentName, 'class', symbols, relationships, depth); break;
      case 'interface_declaration':
        extractType(child, source, filePath, parentName, 'interface', symbols, relationships, depth); break;
      case 'enum_declaration':
        extractType(child, source, filePath, parentName, 'enum', symbols, relationships, depth); break;
    }
  }
}

export function extractType(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, defaultKind: SymbolKind,
  symbols: ExtractedSymbol[], relationships: ExtractedRelationship[],
  depth: number,
): void {
  const nameNode = getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const docComment = extractDocComment(node, source);
  const modifiers = extractApexModifiers(node, source);
  const isExported = modifiers.includes('public') || modifiers.includes('global');
  const annotations = extractApexAnnotations(node, source);
  extractApexInheritance(node, source, filePath, name, relationships);
  const modStr = modifiers.join(' ');
  symbols.push({
    name, kind: defaultKind, filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: `${modStr} ${defaultKind} ${name}`.trim().slice(0, 500),
    modifiers, decorators: annotations, parentName, isExported, docComment,
  });
  const body = getNamedChild(node, 'class_body')
    ?? getNamedChild(node, 'interface_body')
    ?? getNamedChild(node, 'enum_body');
  if (body) extractMembers(body, source, filePath, name, symbols, relationships, depth);
  for (const ann of annotations) {
    relationships.push({ sourceSymbol: name, targetSymbol: ann, kind: 'decorates', filePath, line: range.startLine });
  }
}

export function extractMembers(
  body: SyntaxNode, source: string, filePath: string,
  className: string, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[], depth: number,
): void {
  for (let i = 0; i < body.namedChildCount; i++) {
    const member = body.namedChild(i);
    if (!member) continue;
    switch (member.type) {
      case 'method_declaration':
        extractMethod(member, source, filePath, className, symbols, relationships); break;
      case 'constructor_declaration':
        extractConstructor(member, source, filePath, className, symbols, relationships); break;
      case 'field_declaration':
        extractFields(member, source, filePath, className, symbols); break;
      case 'class_declaration':
        extractType(member, source, filePath, className, 'class', symbols, relationships, depth + 1); break;
      case 'interface_declaration':
        extractType(member, source, filePath, className, 'interface', symbols, relationships, depth + 1); break;
      case 'enum_declaration':
        extractType(member, source, filePath, className, 'enum', symbols, relationships, depth + 1); break;
    }
  }
}

import type { SyntaxNode, ExtractedRelationship } from '../../types.js';
import { getNodeText, getNamedChild, findNodes, walkTree } from '../../ast-utils.js';

const APEX_MODIFIERS = ['public', 'private', 'protected', 'global', 'virtual', 'abstract',
  'static', 'final', 'transient', 'webservice',
  'with sharing', 'without sharing', 'inherited sharing'];

export function extractApexModifiers(node: SyntaxNode, source: string): string[] {
  const modifiers: string[] = [];
  const modifierNode = getNamedChild(node, 'modifiers');
  if (!modifierNode) return modifiers;
  for (let i = 0; i < modifierNode.childCount; i++) {
    const child = modifierNode.child(i);
    if (!child) continue;
    if (child.type === 'marker_annotation' || child.type === 'annotation') continue;
    const text = getNodeText(child, source).toLowerCase();
    if (APEX_MODIFIERS.includes(text)) modifiers.push(text);
  }
  return modifiers;
}

export function extractApexAnnotations(node: SyntaxNode, source: string): string[] {
  const annotations: string[] = [];
  const modifierNode = getNamedChild(node, 'modifiers');
  if (!modifierNode) return annotations;
  for (let i = 0; i < modifierNode.childCount; i++) {
    const child = modifierNode.child(i);
    if (!child) continue;
    if (child.type === 'marker_annotation' || child.type === 'annotation') {
      const text = getNodeText(child, source).replace(/^@/, '').split('(')[0].trim();
      annotations.push(text);
    }
  }
  return annotations;
}

export function extractTriggerEvents(triggerNode: SyntaxNode, source: string): string[] {
  const events: string[] = [];
  const text = getNodeText(triggerNode, source);
  const eventMatch = text.match(/\(([^)]+)\)/);
  if (eventMatch) {
    const eventStr = eventMatch[1];
    const eventParts = eventStr.split(',').map(e => e.trim().toLowerCase());
    events.push(...eventParts);
  }
  return events;
}

export function inferSObjectFromDML(targetText: string): string | null {
  const cleaned = targetText.replace(/^(new|old|updated|inserted)/, '');
  const singular = cleaned.replace(/s$/, '');
  if (singular.length > 0) {
    return singular.charAt(0).toUpperCase() + singular.slice(1);
  }
  return null;
}

export function calculateApexComplexity(node: SyntaxNode): number {
  let complexity = 1;
  const branchTypes = new Set([
    'if_statement', 'for_statement', 'enhanced_for_statement',
    'while_statement', 'do_statement', 'switch_expression',
    'catch_clause', 'ternary_expression',
  ]);
  walkTree(node, {
    enter(n) {
      if (branchTypes.has(n.type)) complexity++;
      if (n.type === '&&' || n.type === '||') complexity++;
    }
  });
  return complexity;
}

export function extractApexMethodReturnType(node: SyntaxNode, source: string): string | undefined {
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (!child) continue;
    if (['type_identifier', 'void_type', 'integral_type', 'floating_point_type',
         'boolean_type', 'generic_type', 'scoped_type_identifier', 'array_type'].includes(child.type)) {
      return getNodeText(child, source);
    }
  }
  return undefined;
}

export function getApexFieldType(node: SyntaxNode, source: string): string {
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (!child) continue;
    if (['type_identifier', 'void_type', 'integral_type', 'floating_point_type',
         'boolean_type', 'generic_type', 'scoped_type_identifier', 'array_type'].includes(child.type)) {
      return getNodeText(child, source);
    }
  }
  return '';
}

import type { Parser as ParserType } from 'web-tree-sitter';
import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../../types.js';
import { findNodes } from '../../ast-utils.js';
import { extractDeclarations } from './declarations.js';
import { extractTrigger } from './triggers.js';

export default class ApexParser implements ILanguageParser {
  readonly languageId: string;
  private parser: any;

  constructor(parser: any, languageId: string) {
    this.parser = parser;
    this.languageId = languageId;
  }

  getSupportedExtensions(): string[] {
    return ['.cls', '.trigger'];
  }

  parse(source: string, filePath: string): ParseResult {
    const tree = this.parser.parse(source);
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    if (tree.rootNode.hasError) {
      const errorNodes = findNodes(tree.rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({ message: 'Parse error', line: node.startPosition.row + 1, column: node.startPosition.column });
      }
    }

    if (filePath.endsWith('.trigger')) {
      extractTrigger(tree.rootNode, source, filePath, symbols, relationships);
    } else {
      extractDeclarations(tree.rootNode, source, filePath, null, symbols, relationships);
    }

    return { symbols, relationships, errors };
  }
}

import type { SyntaxNode, ExtractedRelationship } from '../../types.js';
import { getNodeText, getNamedChild, findNodes } from '../../ast-utils.js';
import { getBaseTypeName, resolveCallTarget } from '../common.js';
import { inferSObjectFromDML } from './helpers.js';

export function extractApexDML(
  body: SyntaxNode, source: string, filePath: string,
  callerName: string, relationships: ExtractedRelationship[],
): void {
  const dmlNodes = findNodes(body, 'dml_expression');
  for (const dml of dmlNodes) {
    const dmlType = dml.child(0);
    if (!dmlType) continue;
    const operation = getNodeText(dmlType, source).toUpperCase();
    const targetExpr = dml.child(1);
    if (!targetExpr) continue;
    const targetText = getNodeText(targetExpr, source);
    const sobject = inferSObjectFromDML(targetText);
    relationships.push({
      sourceSymbol: callerName, targetSymbol: sobject || targetText,
      kind: 'dml' as any, filePath, line: dml.startPosition.row + 1,
      metadata: { operation },
    });
  }
}

export function extractApexSOQL(
  body: SyntaxNode, source: string, filePath: string,
  callerName: string, relationships: ExtractedRelationship[],
): void {
  const soqlNodes = findNodes(body, 'soql_expression');
  for (const soql of soqlNodes) {
    const soqlText = getNodeText(soql, source);
    const fromMatch = soqlText.match(/FROM\s+(\w+)/i);
    if (!fromMatch) continue;
    const sobject = fromMatch[1];
    const fieldsMatch = soqlText.match(/SELECT\s+(.+?)\s+FROM/i);
    const fields = fieldsMatch ? fieldsMatch[1].split(',').map(f => f.trim()) : [];
    relationships.push({
      sourceSymbol: callerName, targetSymbol: sobject,
      kind: 'soql' as any, filePath, line: soql.startPosition.row + 1,
      metadata: { fields },
    });
  }
}

export function extractApexCalls(
  body: SyntaxNode, source: string, filePath: string,
  callerName: string, relationships: ExtractedRelationship[],
): void {
  const seen = new Set<string>();
  const methodCalls = findNodes(body, 'method_invocation');
  for (const call of methodCalls) {
    const target = resolveCallTarget(call, source);
    if (!target) continue;
    const key = `${callerName}->${target}`;
    if (seen.has(key)) continue;
    seen.add(key);
    relationships.push({
      sourceSymbol: callerName, targetSymbol: target,
      kind: 'calls', filePath, line: call.startPosition.row + 1,
    });
  }
  const creations = findNodes(body, 'object_creation_expression');
  for (const creation of creations) {
    const typeNode = getNamedChild(creation, 'type_identifier')
      ?? getNamedChild(creation, 'scoped_type_identifier')
      ?? getNamedChild(creation, 'generic_type');
    if (!typeNode) continue;
    const typeName = getBaseTypeName(typeNode, source);
    const target = `${typeName}.constructor`;
    const key = `${callerName}->${target}`;
    if (seen.has(key)) continue;
    seen.add(key);
    relationships.push({
      sourceSymbol: callerName, targetSymbol: target,
      kind: 'calls', filePath, line: creation.startPosition.row + 1,
      metadata: { constructor: true },
    });
  }
}

export function extractApexInheritance(
  node: SyntaxNode, source: string, filePath: string,
  className: string, relationships: ExtractedRelationship[],
): void {
  const superclass = getNamedChild(node, 'superclass');
  if (superclass) {
    const typeId = getNamedChild(superclass, 'type_identifier')
      ?? getNamedChild(superclass, 'scoped_type_identifier')
      ?? getNamedChild(superclass, 'generic_type');
    if (typeId) {
      relationships.push({
        sourceSymbol: className, targetSymbol: getBaseTypeName(typeId, source),
        kind: 'inherits', filePath, line: typeId.startPosition.row + 1,
      });
    }
  }
  const interfaces = getNamedChild(node, 'super_interfaces');
  if (interfaces) {
    const typeList = getNamedChild(interfaces, 'type_list');
    if (typeList) {
      for (let i = 0; i < typeList.namedChildCount; i++) {
        const typeNode = typeList.namedChild(i);
        if (!typeNode) continue;
        relationships.push({
          sourceSymbol: className, targetSymbol: getBaseTypeName(typeNode, source),
          kind: 'implements', filePath, line: typeNode.startPosition.row + 1,
        });
      }
    }
  }
}

import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship } from '../../types.js';
import { getNodeText, getNodeRange, getNamedChild, findNodes } from '../../ast-utils.js';
import { extractTriggerEvents } from './helpers.js';
import { extractApexCalls, extractApexDML, extractApexSOQL } from './relationships.js';
import { extractDeclarations } from './declarations.js';

export function extractTrigger(
  root: SyntaxNode, source: string, filePath: string,
  symbols: ExtractedSymbol[], relationships: ExtractedRelationship[],
): void {
  const triggerNodes = findNodes(root, 'trigger_declaration');
  if (triggerNodes.length === 0) {
    extractDeclarations(root, source, filePath, null, symbols, relationships);
    return;
  }
  const triggerNode = triggerNodes[0];
  const nameNode = getNamedChild(triggerNode, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(triggerNode);
  const objectNode = triggerNode.namedChild(1);
  const sobject = objectNode ? getNodeText(objectNode, source) : 'Unknown';
  const events = extractTriggerEvents(triggerNode, source);
  symbols.push({
    name, kind: 'class', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: `trigger ${name} on ${sobject} (${events.join(', ')})`,
    modifiers: ['trigger'], isExported: true,
  });
  relationships.push({
    sourceSymbol: name, targetSymbol: sobject,
    kind: 'trigger-on' as any, filePath, line: range.startLine,
    metadata: { events },
  });
  const body = getNamedChild(triggerNode, 'trigger_body') ?? getNamedChild(triggerNode, 'block');
  if (body) {
    extractApexCalls(body, source, filePath, name, relationships);
    extractApexDML(body, source, filePath, name, relationships);
    extractApexSOQL(body, source, filePath, name, relationships);
  }
}

import type { SyntaxNode } from '../../types.js';
import { getNodeText, getNamedChild } from '../../ast-utils.js';

export interface ReceiverInfo {
  text: string;
  typeName: string;
  isPointer: boolean;
}

export function isExported(name: string): boolean {
  if (!name || name.length === 0) return false;
  return name[0] === name[0].toUpperCase() && name[0] !== name[0].toLowerCase();
}

export function extractReceiver(node: SyntaxNode | null, source: string): ReceiverInfo {
  if (!node) return { text: '', typeName: '', isPointer: false };
  const paramList = node.namedChildren;
  if (paramList.length === 0) return { text: '', typeName: '', isPointer: false };
  const paramDecl = paramList[0];
  const typeNode = paramDecl.childForFieldName('type');
  if (!typeNode) {
    const lastChild = paramDecl.namedChildren[paramDecl.namedChildren.length - 1];
    if (lastChild) {
      const isPointer = lastChild.type === 'pointer_type';
      const typeName = isPointer
        ? getNodeText(lastChild.namedChildren[0], source)
        : getNodeText(lastChild, source);
      return { text: getNodeText(paramDecl, source), typeName, isPointer };
    }
    return { text: getNodeText(paramDecl, source), typeName: '', isPointer: false };
  }
  const isPointer = typeNode.type === 'pointer_type';
  const typeName = isPointer
    ? getNodeText(typeNode.namedChildren[0], source)
    : getNodeText(typeNode, source);
  return { text: getNodeText(paramDecl, source), typeName, isPointer };
}

export function extractParams(node: SyntaxNode | null, source: string): string {
  if (!node) return '';
  return getNodeText(node, source);
}

export function extractResult(node: SyntaxNode | null, source: string): string {
  if (!node) return '';
  return getNodeText(node, source).trim();
}

export function buildFuncSignature(name: string, params: string, returnType: string): string {
  const ret = returnType ? ` ${returnType}` : '';
  return `func ${name}${params}${ret}`.slice(0, 500);
}

export function buildMethodSignature(receiver: ReceiverInfo, name: string, params: string, returnType: string): string {
  const ret = returnType ? ` ${returnType}` : '';
  const recv = receiver.text ? `(${receiver.text}) ` : '';
  return `func ${recv}${name}${params}${ret}`.slice(0, 500);
}

import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship, SymbolKind } from '../../types.js';
import { getNodeText, getNodeRange, findNodes, walkTree, calculateComplexity, extractDocComment } from '../../ast-utils.js';
import { isExported, extractReceiver, extractParams, extractResult, buildFuncSignature, buildMethodSignature } from './helpers.js';

export function extractDeclarations(
  root: SyntaxNode, source: string, filePath: string,
  symbols: ExtractedSymbol[], relationships: ExtractedRelationship[],
): void {
  for (let i = 0; i < root.namedChildCount; i++) {
    const child = root.namedChild(i);
    if (!child) continue;
    switch (child.type) {
      case 'function_declaration':
        extractFunction(child, source, filePath, symbols, relationships); break;
      case 'method_declaration':
        extractMethod(child, source, filePath, symbols, relationships); break;
      case 'type_declaration':
        extractTypeDeclaration(child, source, filePath, symbols); break;
      case 'const_declaration':
      case 'var_declaration':
        extractVarConst(child, source, filePath, symbols); break;
    }
  }
}

export function extractFunction(
  node: SyntaxNode, source: string, filePath: string,
  symbols: ExtractedSymbol[], relationships: ExtractedRelationship[],
): void {
  const nameNode = node.childForFieldName('name');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const params = extractParams(node.childForFieldName('parameters'), source);
  const returnType = extractResult(node.childForFieldName('result'), source);
  const docComment = extractDocComment(node, source);
  const exported = isExported(name);
  symbols.push({
    name, kind: 'function', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: buildFuncSignature(name, params, returnType),
    parameters: params || null, returnType: returnType || null,
    isExported: exported, docComment, complexity: calculateComplexity(node),
  });
  const body = node.childForFieldName('body');
  if (body) extractGoCalls(body, source, filePath, name, relationships);
}

export function extractMethod(
  node: SyntaxNode, source: string, filePath: string,
  symbols: ExtractedSymbol[], relationships: ExtractedRelationship[],
): void {
  const nameNode = node.childForFieldName('name');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const receiver = extractReceiver(node.childForFieldName('receiver'), source);
  const params = extractParams(node.childForFieldName('parameters'), source);
  const returnType = extractResult(node.childForFieldName('result'), source);
  const docComment = extractDocComment(node, source);
  const exported = isExported(name);
  symbols.push({
    name, kind: 'method', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: buildMethodSignature(receiver, name, params, returnType),
    parameters: params || null, returnType: returnType || null,
    parentName: receiver.typeName, isExported: exported, docComment,
    modifiers: receiver.isPointer ? ['pointer_receiver'] : ['value_receiver'],
    complexity: calculateComplexity(node),
  });
  relationships.push({
    sourceSymbol: receiver.typeName, targetSymbol: name,
    kind: 'uses', filePath, line: range.startLine,
    metadata: { relationship: 'has_method', pointer_receiver: receiver.isPointer },
  });
  const body = node.childForFieldName('body');
  if (body) extractGoCalls(body, source, filePath, `${receiver.typeName}.${name}`, relationships);
}

export function extractTypeDeclaration(node: SyntaxNode, source: string, filePath: string, symbols: ExtractedSymbol[]): void {
  const typeSpecs = findNodes(node, 'type_spec');
  for (const spec of typeSpecs) extractTypeSpec(spec, source, filePath, symbols);
}

export function extractTypeSpec(node: SyntaxNode, source: string, filePath: string, symbols: ExtractedSymbol[]): void {
  const nameNode = node.childForFieldName('name');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const typeNode = node.childForFieldName('type');
  if (!typeNode) return;
  const range = getNodeRange(node);
  const exported = isExported(name);
  const docComment = extractDocComment(node, source);
  let kind: SymbolKind;
  let signature: string;
  switch (typeNode.type) {
    case 'struct_type': kind = 'struct'; signature = `type ${name} struct`; break;
    case 'interface_type': kind = 'interface'; signature = `type ${name} interface`; break;
    default: kind = 'type'; signature = `type ${name} ${getNodeText(typeNode, source).split('\n')[0].slice(0, 100)}`; break;
  }
  symbols.push({ name, kind, filePath, startLine: range.startLine, endLine: range.endLine, signature, isExported: exported, docComment });
}

export function extractVarConst(node: SyntaxNode, source: string, filePath: string, symbols: ExtractedSymbol[]): void {
  const specType = node.type === 'const_declaration' ? 'const_spec' : 'var_spec';
  const specs = findNodes(node, specType);
  for (const spec of specs) {
    const nameNode = spec.childForFieldName('name');
    if (!nameNode) continue;
    const name = getNodeText(nameNode, source);
    const range = getNodeRange(spec);
    const exported = isExported(name);
    symbols.push({
      name, kind: node.type === 'const_declaration' ? 'constant' as SymbolKind : 'variable', filePath,
      startLine: range.startLine, endLine: range.endLine,
      signature: getNodeText(spec, source).split('\n')[0].trim().slice(0, 200),
      isExported: exported,
    });
  }
}

export function extractGoCalls(
  body: SyntaxNode, source: string, filePath: string,
  callerName: string, relationships: ExtractedRelationship[],
): void {
  const seen = new Set<string>();
  const callExprs = findNodes(body, 'call_expression');
  for (const call of callExprs) {
    const funcNode = call.childForFieldName('function');
    if (!funcNode) continue;
    const target = getNodeText(funcNode, source).trim();
    const key = `${callerName}->${target}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const isGoroutine = isInsideNodeType(call, 'go_statement');
    const isDeferred = isInsideNodeType(call, 'defer_statement');
    const metadata: Record<string, unknown> = {};
    if (isGoroutine) metadata.async = true;
    if (isDeferred) metadata.deferred = true;
    relationships.push({
      sourceSymbol: callerName, targetSymbol: target, kind: 'calls', filePath,
      line: call.startPosition.row + 1,
      metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
    });
  }
}

function isInsideNodeType(node: SyntaxNode, type: string): boolean {
  let current = node.parent;
  while (current) {
    if (current.type === type) return true;
    if (current.type === 'function_declaration' || current.type === 'method_declaration') break;
    current = current.parent;
  }
  return false;
}

import type { Parser as ParserType } from 'web-tree-sitter';
import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../../types.js';
import { findNodes } from '../../ast-utils.js';
import { extractDeclarations, extractGoCalls } from './members.js';

function isGeneratedFile(source: string, filePath: string): boolean {
  if (filePath.endsWith('_generated.go')) return true;
  const firstLines = source.split('\n').slice(0, 3).join('\n');
  return firstLines.includes('// Code generated');
}

function extractImports(root: SyntaxNode, source: string, filePath: string, relationships: ExtractedRelationship[]): void {
  const importDecls = findNodes(root, 'import_declaration');
  for (const decl of importDecls) {
    const importSpecs = findNodes(decl, 'import_spec');
    for (const spec of importSpecs) {
      const pathNode = spec.childForFieldName('path');
      if (!pathNode) continue;
      const importPath = getNodeText(pathNode, source).replace(/"/g, '');
      const aliasNode = spec.childForFieldName('name');
      const alias = aliasNode ? getNodeText(aliasNode, source) : null;
      relationships.push({ sourceSymbol: filePath, targetSymbol: importPath, kind: 'imports', filePath, line: spec.startPosition.row + 1, metadata: { alias, module: importPath } });
    }
  }
}

import { getNodeText } from '../../ast-utils.js';

function detectInterfaceImplementations(symbols: ExtractedSymbol[]): ExtractedRelationship[] {
  const interfaces = symbols.filter(s => s.kind === 'interface');
  const structs = symbols.filter(s => s.kind === 'struct');
  const implRelationships: ExtractedRelationship[] = [];
  if (interfaces.length === 0 || structs.length === 0) return implRelationships;
  return implRelationships;
}

export default class GoParser implements ILanguageParser {
  readonly languageId: string;
  private parser: any;

  constructor(parser: any, languageId: string) {
    this.parser = parser;
    this.languageId = languageId;
  }

  getSupportedExtensions(): string[] {
    return ['.go'];
  }

  parse(source: string, filePath: string): ParseResult {
    if (isGeneratedFile(source, filePath)) {
      return { symbols: [], relationships: [], errors: [] };
    }
    const tree = this.parser.parse(source);
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    if (tree.rootNode.hasError) {
      const errorNodes = findNodes(tree.rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({ message: 'Parse error', line: node.startPosition.row + 1, column: node.startPosition.column });
      }
    }

    extractDeclarations(tree.rootNode, source, filePath, symbols, relationships);
    extractImports(tree.rootNode, source, filePath, relationships);
    const implRelationships = detectInterfaceImplementations(symbols);
    relationships.push(...implRelationships);

    return { symbols, relationships, errors };
  }
}

import type { Parser as ParserType } from 'web-tree-sitter';
import type {
  ILanguageParser, ParseResult, ExtractedSymbol,
  ExtractedRelationship, ParseError,
} from '../../types.js';
import { findNodes } from '../../ast-utils.js';
import { extractPackage, extractDeclarations } from './extractor.js';
import { extractJavaImports } from './relationships.js';

export default class JavaParser implements ILanguageParser {
