import type { Parser as ParserType } from 'web-tree-sitter';
import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../../types.js';
import { findNodes, findFirst, getNodeText, getNodeRange } from '../../ast-utils.js';
import { extractDeclarationsInNode } from './dispatchable.js';

function extractPackage(root: SyntaxNode, source: string, filePath: string, symbols: ExtractedSymbol[]): void {
  const pkgNode = findFirst(root, 'package_header');
  if (!pkgNode) return;
  const identifier = findFirst(pkgNode, 'identifier');
  if (!identifier) return;
  symbols.push({
    name: getNodeText(identifier, source), kind: 'namespace', filePath,
    ...getNodeRange(pkgNode), signature: getNodeText(pkgNode, source).trim(),
  });
}

function extractImports(root: SyntaxNode, source: string, filePath: string, relationships: ExtractedRelationship[]): void {
  const imports = findNodes(root, 'import_header');
  for (const imp of imports) {
    const identifier = findFirst(imp, 'identifier');
    if (!identifier) continue;
    const target = getNodeText(identifier, source);
    const impText = getNodeText(imp, source);
    const isWildcard = impText.includes('.*') || impText.endsWith('*');
    let alias: string | undefined;
    const aliasNode = findFirst(imp, 'import_alias');
    if (aliasNode) {
      const aliasId = findFirst(aliasNode, 'simple_identifier');
      if (aliasId) alias = getNodeText(aliasId, source);
    }
    relationships.push({
      sourceSymbol: '__file__', targetSymbol: isWildcard ? target + '.*' : target,
      kind: 'imports', filePath, line: imp.startPosition.row + 1,
      metadata: { ...(isWildcard && { wildcard: true }), ...(alias && { alias }) },
    });
  }
}

export default class KotlinParser implements ILanguageParser {
  readonly languageId = 'kotlin';
  private parser: any;

  constructor(parser: any, _languageId?: string) {
    this.parser = parser;
  }

  getSupportedExtensions(): string[] {
    return ['.kt', '.kts'];
  }

  parse(source: string, filePath: string): ParseResult {
    const tree = this.parser.parse(source);
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    if (tree.rootNode.hasError) {
      const errorNodes = findNodes(tree.rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({ message: 'Parse error', line: node.startPosition.row + 1, column: node.startPosition.column });
      }
    }

    extractPackage(tree.rootNode, source, filePath, symbols);
    extractImports(tree.rootNode, source, filePath, relationships);
    extractDeclarationsInNode(tree.rootNode, source, filePath, symbols, relationships, undefined);

    return { symbols, relationships, errors };
  }
}

import type { SyntaxNode } from '../../types.js';
import { getNodeText, getNamedChild, findNodes, walkTree } from '../../ast-utils.js';

export function getDecorators(node: SyntaxNode, source: string): string[] {
  const decorators: string[] = [];
  for (let i = 0; i < node.namedChildCount; i++) {
    const child = node.namedChild(i);
    if (!child || child.type !== 'decorator') continue;
    const text = getNodeText(child, source).replace(/^@/, '').split('(')[0].trim();
    decorators.push(text);
  }
  return decorators;
}

export function extractPythonReturnType(node: SyntaxNode, source: string): string | undefined {
  const typeNode = getNamedChild(node, 'type');
  if (typeNode) return getNodeText(typeNode, source);
  return undefined;
}

export function extractDocstring(body: SyntaxNode, source: string): string | null {
  const firstChild = body.namedChild(0);
  if (!firstChild || firstChild.type !== 'expression_statement') return null;
  const expr = firstChild.namedChild(0);
  if (!expr || expr.type !== 'string') return null;
  const text = getNodeText(expr, source);
  return text.replace(/^("""|''')\s*/, '').replace(/\s*("""|''')$/, '').trim().slice(0, 500) || null;
}

export function calculatePythonComplexity(node: SyntaxNode): number {
  let complexity = 1;
  const branchTypes = new Set([
    'if_statement', 'elif_clause', 'for_statement', 'while_statement',
    'except_clause', 'with_statement', 'case_clause', 'assert_statement',
  ]);
  walkTree(node, {
    enter(n) {
      if (branchTypes.has(n.type)) complexity++;
      if (n.type === 'boolean_operator') complexity++;
      if (n.type === 'conditional_expression') complexity++;
      if (['list_comprehension', 'set_comprehension', 'dictionary_comprehension', 'generator_expression'].includes(n.type)) complexity++;
    }
  });
  return complexity;
}

export function buildPythonFunctionSignature(isAsync: boolean, name: string, params: string, returnType: string | undefined): string {
  const prefix = isAsync ? 'async ' : '';
  const ret = returnType ? ` -> ${returnType}` : '';
  return `${prefix}def ${name}${params}${ret}`.slice(0, 500);
}

export function extractModuleName(stmt: SyntaxNode, source: string): string {
  for (let i = 0; i < stmt.childCount; i++) {
    const child = stmt.child(i);
    if (!child) continue;
    if (child.type === 'dotted_name' || child.type === 'relative_import') return getNodeText(child, source);
  }
  return '';
}

export function getImportedIdentifiers(stmt: SyntaxNode, source: string): string[] {
  const names: string[] = [];
  let afterImport = false;
  for (let i = 0; i < stmt.childCount; i++) {
    const child = stmt.child(i);
    if (!child) continue;
    if (child.type === 'import') { afterImport = true; continue; }
    if (afterImport && (child.type === 'dotted_name' || child.type === 'identifier')) names.push(getNodeText(child, source));
  }
  return names;
}

import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship, SymbolKind, RelationshipKind } from '../../types.js';
import { getNodeText, getNodeRange, getNamedChild, findNodes, extractDocComment } from '../../ast-utils.js';
import { getDecorators, extractPythonReturnType, extractDocstring, calculatePythonComplexity, buildPythonFunctionSignature } from './helpers.js';

export function extractFunction(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[], decoratedNode?: SyntaxNode,
): void {
  const nameNode = getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(decoratedNode || node);
  const precedingText = source.substring(Math.max(0, node.startIndex - 6), node.startIndex);
  const isAsync = precedingText.includes('async');
  const decorators = getDecorators(decoratedNode || node, source);
  let kind: SymbolKind = parentName ? 'method' : 'function';
  if (decorators.includes('property')) kind = 'property';
  if (name === '__init__') kind = 'constructor';
  const paramsNode = getNamedChild(node, 'parameters');
  const params = paramsNode ? getNodeText(paramsNode, source) : '()';
  const returnType = extractPythonReturnType(node, source);
  const modifiers: string[] = [];
  if (isAsync) modifiers.push('async');
  if (decorators.includes('staticmethod')) modifiers.push('static');
  if (decorators.includes('classmethod')) modifiers.push('classmethod');
  if (decorators.includes('abstractmethod')) modifiers.push('abstract');
  const isExported = !name.startsWith('_');
  const body = getNamedChild(node, 'block');
  const complexity = body ? calculatePythonComplexity(body) : 1;
  const docComment = body ? extractDocstring(body, source) : null;
  symbols.push({
    name, kind, filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: buildPythonFunctionSignature(isAsync, name, params, returnType),
    parameters: params, returnType, modifiers, decorators, parentName,
    isAsync, isExported, docComment, complexity,
  });
  if (body) {
    extractPythonCalls(body, source, filePath, parentName ? `${parentName}.${name}` : name, relationships);
    extractDeclarationsNode(body, source, filePath, name, symbols, relationships);
  }
  for (const dec of decorators) {
    relationships.push({
      sourceSymbol: parentName ? `${parentName}.${name}` : name,
      targetSymbol: dec, kind: 'decorates', filePath, line: range.startLine,
    });
  }
}

export function extractClass(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[], decoratedNode?: SyntaxNode,
): void {
  const nameNode = getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(decoratedNode || node);
  const decorators = getDecorators(decoratedNode || node, source);
  const argList = getNamedChild(node, 'argument_list');
  const bases: string[] = [];
  let isProtocol = false;
  let isABC = false;
  if (argList) {
    for (let i = 0; i < argList.namedChildCount; i++) {
      const arg = argList.namedChild(i);
      if (!arg) continue;
      if (arg.type === 'identifier' || arg.type === 'attribute') {
        const baseName = getNodeText(arg, source);
        bases.push(baseName);
        if (baseName === 'Protocol') isProtocol = true;
        if (baseName === 'ABC' || baseName === 'ABCMeta') isABC = true;
        const relKind: RelationshipKind = isProtocol ? 'implements' : 'inherits';
        relationships.push({ sourceSymbol: name, targetSymbol: baseName, kind: relKind, filePath, line: arg.startPosition.row + 1 });
      }
    }
  }
  const kind: SymbolKind = isProtocol ? 'interface' : 'class';
  const modifiers: string[] = [];
  if (isABC) modifiers.push('abstract');
  if (decorators.includes('dataclass')) modifiers.push('dataclass');
  const isExported = !name.startsWith('_');
  const body = getNamedChild(node, 'block');
  const docComment = body ? extractDocstring(body, source) : null;
  symbols.push({
    name, kind, filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: `class ${name}${bases.length ? `(${bases.join(', ')})` : ''}`,
    modifiers, decorators, parentName, isExported, docComment,
  });
  if (body) extractDeclarationsNode(body, source, filePath, name, symbols, relationships);
  for (const dec of decorators) {
    relationships.push({ sourceSymbol: name, targetSymbol: dec, kind: 'decorates', filePath, line: range.startLine });
  }
}

function extractModuleVariable(
  node: SyntaxNode, source: string, filePath: string, symbols: ExtractedSymbol[],
): void {
  const assignment = getNamedChild(node, 'assignment');
  if (!assignment) return;
  const left = assignment.child(0);
  if (!left || left.type !== 'identifier') return;
  const name = getNodeText(left, source);
  const range = getNodeRange(node);
  const isConstant = /^[A-Z_][A-Z0-9_]*$/.test(name);
  symbols.push({
    name, kind: isConstant ? 'constant' as SymbolKind : 'variable', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: getNodeText(node, source).split('\n')[0].trim().slice(0, 200),
    isExported: !name.startsWith('_'),
  });
}

export function extractDeclarationsNode(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  for (let i = 0; i < node.namedChildCount; i++) {
    const child = node.namedChild(i);
    if (!child) continue;
    switch (child.type) {
      case 'function_definition':
        extractFunction(child, source, filePath, parentName, symbols, relationships); break;
      case 'class_definition':
        extractClass(child, source, filePath, parentName, symbols, relationships); break;
      case 'decorated_definition':
        extractDecorated(child, source, filePath, parentName, symbols, relationships); break;
      case 'expression_statement':
        if (!parentName) extractModuleVariable(child, source, filePath, symbols); break;
    }
  }
}

function extractDecorated(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  for (let i = 0; i < node.namedChildCount; i++) {
    const child = node.namedChild(i);
    if (!child) continue;
    if (child.type === 'function_definition') {
      extractFunction(child, source, filePath, parentName, symbols, relationships, node);
    } else if (child.type === 'class_definition') {
      extractClass(child, source, filePath, parentName, symbols, relationships, node);
    }
  }
}

export function extractPythonCalls(
  body: SyntaxNode, source: string, filePath: string,
  callerName: string, relationships: ExtractedRelationship[],
): void {
  const callNodes = findNodes(body, 'call');
  const seen = new Set<string>();
  const builtins = new Set(['print', 'len', 'range', 'str', 'int', 'float', 'list', 'dict', 'set', 'tuple', 'type', 'isinstance', 'issubclass', 'super', 'hasattr', 'getattr', 'setattr', 'repr', 'bool', 'enumerate', 'zip', 'map', 'filter', 'sorted', 'reversed', 'any', 'all', 'min', 'max', 'abs', 'round', 'open', 'id', 'hex', 'oct', 'bin', 'ord', 'chr', 'format', 'vars', 'dir', 'help', 'input', 'iter', 'next', 'slice', 'object', 'property', 'staticmethod', 'classmethod']);
  for (const call of callNodes) {
    const funcNode = call.child(0);
    if (!funcNode) continue;
    const funcName = getNodeText(funcNode, source);
    if (builtins.has(funcName)) continue;
    const key = `${callerName}->${funcName}`;
    if (seen.has(key)) continue;
    seen.add(key);
    relationships.push({ sourceSymbol: callerName, targetSymbol: funcName, kind: 'calls', filePath, line: call.startPosition.row + 1 });
  }
}

import type { Parser as ParserType } from 'web-tree-sitter';
import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../../types.js';
import { getNodeText, getNodeRange, findNodes, getNamedChild } from '../../ast-utils.js';
import { extractDeclarationsNode } from './members.js';
import { extractModuleName, getImportedIdentifiers } from './helpers.js';

function extractImports(root: SyntaxNode, source: string, filePath: string, relationships: ExtractedRelationship[]): void {
  const importStmts = findNodes(root, 'import_statement');
  for (const stmt of importStmts) {
    const names = findNodes(stmt, 'dotted_name');
    for (const name of names) {
      relationships.push({ sourceSymbol: '__file__', targetSymbol: getNodeText(name, source), kind: 'imports', filePath, line: stmt.startPosition.row + 1 });
    }
  }
  const fromStmts = findNodes(root, 'import_from_statement');
  for (const stmt of fromStmts) {
    const moduleName = extractModuleName(stmt, source);
    const isRelative = moduleName.startsWith('.');
    if (findNodes(stmt, 'wildcard_import').length > 0) {
      relationships.push({ sourceSymbol: '__file__', targetSymbol: `${moduleName}.*`, kind: 'imports', filePath, line: stmt.startPosition.row + 1, metadata: { wildcard: true, ...(isRelative && { relative: true }) } });
      continue;
    }
    const importedNames = findNodes(stmt, 'aliased_import');
    if (importedNames.length > 0) {
      for (const imported of importedNames) {
        const nameNode = imported.child(0);
        if (!nameNode) continue;
        const name = getNodeText(nameNode, source);
        const aliasNode = imported.childCount > 2 ? imported.child(2) : null;
        const alias = aliasNode ? getNodeText(aliasNode, source) : undefined;
        relationships.push({ sourceSymbol: '__file__', targetSymbol: moduleName ? `${moduleName}.${name}` : name, kind: 'imports', filePath, line: stmt.startPosition.row + 1, metadata: { from: moduleName, name, ...(alias && { alias }), ...(isRelative && { relative: true }) } });
      }
    } else {
      const identifiers = getImportedIdentifiers(stmt, source);
      for (const name of identifiers) {
        relationships.push({ sourceSymbol: '__file__', targetSymbol: moduleName ? `${moduleName}.${name}` : name, kind: 'imports', filePath, line: stmt.startPosition.row + 1, metadata: { from: moduleName, name } });
      }
    }
  }
}

export default class PythonParser implements ILanguageParser {
  readonly languageId: string;
  private parser: any;

  constructor(parser: any, languageId: string) {
    this.parser = parser;
    this.languageId = languageId;
  }

  getSupportedExtensions(): string[] {
    return ['.py', '.pyi'];
  }

  parse(source: string, filePath: string): ParseResult {
    const tree = this.parser.parse(source);
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    if (tree.rootNode.hasError) {
      const errorNodes = findNodes(tree.rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({ message: 'Parse error', line: node.startPosition.row + 1, column: node.startPosition.column });
      }
    }

    extractImports(tree.rootNode, source, filePath, relationships);
    extractDeclarationsNode(tree.rootNode, source, filePath, null, symbols, relationships);

    return { symbols, relationships, errors };
  }
}

import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship, SymbolKind } from '../../types.js';
import { getNodeText, getNodeRange, findNodes, calculateComplexity, extractDocComment } from '../../ast-utils.js';
import { extractVisibility, extractFunctionModifiers, extractParams, extractReturnType, buildFuncSignature } from './helpers.js';
import { extractRustCalls } from './calls.js';

export function extractFunction(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  const nameNode = node.childForFieldName('name');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const visibility = extractVisibility(node, source);
  const modifiers = extractFunctionModifiers(node, source);
  const params = extractParams(node.childForFieldName('parameters'), source);
  const returnType = extractReturnType(node, source);
  const typeParams = node.childForFieldName('type_parameters');
  const generics = typeParams ? getNodeText(typeParams, source) : '';
  const docComment = extractDocComment(node, source);
  const isExported = visibility === 'pub' || visibility === 'pub_crate';
  symbols.push({
    name, kind: parentName ? 'method' : 'function', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: buildFuncSignature(name, generics, params, returnType, modifiers),
    parameters: params || null, returnType: returnType || null,
    modifiers, isAsync: modifiers.includes('async'), isExported, parentName,
    docComment, complexity: calculateComplexity(node),
  });
  const body = node.childForFieldName('body');
  if (body) {
    const callerName = parentName ? `${parentName}.${name}` : name;
    extractRustCalls(body, source, filePath, callerName, relationships);
  }
}

export function extractStruct(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  const nameNode = node.childForFieldName('name');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const visibility = extractVisibility(node, source);
  const isExported = visibility === 'pub' || visibility === 'pub_crate';
  const docComment = extractDocComment(node, source);
  const typeParams = node.childForFieldName('type_parameters');
  const generics = typeParams ? getNodeText(typeParams, source) : '';
  symbols.push({
    name, kind: 'struct', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: `struct ${name}${generics}`, isExported, parentName, docComment,
  });
  let prev = node.previousNamedSibling;
  while (prev && prev.type === 'attribute_item') {
    const attrText = getNodeText(prev, source);
    const deriveMatch = attrText.match(/derive\(([^)]+)\)/);
    if (deriveMatch) {
      const traits = deriveMatch[1].split(',').map(t => t.trim());
      for (const trait of traits) {
        if (trait) {
          relationships.push({
            sourceSymbol: name, targetSymbol: trait,
            kind: 'implements', filePath, line: range.startLine,
            metadata: { derived: true },
          });
        }
      }
    }
    prev = prev.previousNamedSibling;
  }
}

