import type { Parser as ParserType } from 'web-tree-sitter';
import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../../types.js';
import { findNodes } from '../../ast-utils.js';
import {
  extractFunction, extractStruct, extractEnum,
  extractTypeAlias, extractConstStatic, extractMacroDefinition,
} from './members.js';
import { extractTrait, extractImpl, extractModule } from './dispatchable.js';
import { extractUseDeclarations } from './uses.js';

export type DispatchFn = (
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
) => void;

function extractFromNode(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  for (let i = 0; i < node.namedChildCount; i++) {
    const child = node.namedChild(i);
    if (!child) continue;
    switch (child.type) {
      case 'function_item':
        extractFunction(child, source, filePath, parentName, symbols, relationships); break;
      case 'struct_item':
        extractStruct(child, source, filePath, parentName, symbols, relationships); break;
      case 'enum_item':
        extractEnum(child, source, filePath, parentName, symbols, relationships); break;
      case 'trait_item':
        extractTrait(child, source, filePath, parentName, symbols, relationships, extractFromNode); break;
      case 'impl_item':
        extractImpl(child, source, filePath, symbols, relationships, extractFromNode); break;
      case 'mod_item':
        extractModule(child, source, filePath, parentName, symbols, relationships, extractFromNode); break;
      case 'type_item':
        extractTypeAlias(child, source, filePath, parentName, symbols); break;
      case 'const_item':
      case 'static_item':
        extractConstStatic(child, source, filePath, parentName, symbols); break;
      case 'macro_definition':
        extractMacroDefinition(child, source, filePath, symbols); break;
    }
  }
}

export default class RustParser implements ILanguageParser {
  readonly languageId: string;
  private parser: any;

  constructor(parser: any, languageId: string) {
    this.parser = parser;
    this.languageId = languageId;
  }

  getSupportedExtensions(): string[] {
    return ['.rs'];
  }

  parse(source: string, filePath: string): ParseResult {
    const tree = this.parser.parse(source);
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    if (tree.rootNode.hasError) {
      const errorNodes = findNodes(tree.rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({ message: 'Parse error', line: node.startPosition.row + 1, column: node.startPosition.column });
      }
    }

    extractFromNode(tree.rootNode, source, filePath, null, symbols, relationships);
    extractUseDeclarations(tree.rootNode, source, filePath, relationships);

    return { symbols, relationships, errors };
  }
}

import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError } from '../../types.js';
import { parseFlow, parseObject, parseField, parseLWCMeta, parseAuraMeta } from './parsers.js';

function detectMetaType(filePath: string): string | null {
  const normalized = filePath.replace(/\\/g, '/').toLowerCase();
  if (normalized.endsWith('.flow-meta.xml')) return 'flow';
  if (normalized.endsWith('.object-meta.xml')) return 'object';
  if (normalized.endsWith('.field-meta.xml')) return 'field';
  if (normalized.endsWith('.js-meta.xml')) return 'lwc-meta';
  if (normalized.endsWith('.component-meta.xml')) return 'aura-meta';
  return null;
}

export default class SalesforceMetaParser implements ILanguageParser {
  readonly languageId: string;

  constructor(_parser: any, languageId: string) {
    this.languageId = languageId;
  }

  getSupportedExtensions(): string[] {
    return ['.flow-meta.xml', '.object-meta.xml', '.field-meta.xml', '.js-meta.xml', '.component-meta.xml'];
  }

  parse(source: string, filePath: string): ParseResult {
    const symbols: ExtractedSymbol[] = [];
    const relationships: ExtractedRelationship[] = [];
    const errors: ParseError[] = [];

    try {
      const metaType = detectMetaType(filePath);
      switch (metaType) {
        case 'flow': parseFlow(source, filePath, symbols, relationships); break;
        case 'object': parseObject(source, filePath, symbols, relationships); break;
        case 'field': parseField(source, filePath, symbols, relationships); break;
        case 'lwc-meta': parseLWCMeta(source, filePath, symbols, relationships); break;
        case 'aura-meta': parseAuraMeta(source, filePath, symbols); break;
      }
    } catch (err) {
      errors.push({ message: `XML parse error: ${err instanceof Error ? err.message : String(err)}`, line: 1, column: 0 });
    }

    return { symbols, relationships, errors };
  }
}

import type { SyntaxNode, ExtractedSymbol, ExtractedRelationship, SymbolKind } from '../../types.js';
import { getNodeText, getNodeRange, getNamedChild, calculateComplexity, extractDocComment } from '../../ast-utils.js';
import { isExported, hasModifier, extractParameters, extractReturnType, buildFunctionSignature, extractDecorators, extractModifiers } from '../ts-utils.js';

export function extractFunction(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
): void {
  const nameNode = getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const params = extractParameters(node, source);
  const returnType = extractReturnType(node, source);
  const exported = isExported(node);
  const isAsync = hasModifier(node, source, 'async');
  const docComment = extractDocComment(node, source);
  const decorators = extractDecorators(node, source);
  symbols.push({
    name, kind: parentName ? 'method' : 'function', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: buildFunctionSignature(name, params, returnType, isAsync),
    parameters: params, returnType, isAsync, isExported: exported,
    parentName, docComment, complexity: calculateComplexity(node),
    decorators: decorators.length > 0 ? decorators : undefined,
  });
}

export function extractClass(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
  relationships: ExtractedRelationship[],
): void {
  const nameNode = getNamedChild(node, 'type_identifier') ?? getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const exported = isExported(node);
  const docComment = extractDocComment(node, source);
  const decorators = extractDecorators(node, source);
  const modifiers = extractModifiers(node, source);
  const isAbstract = modifiers.includes('abstract');
  symbols.push({
    name, kind: 'class', filePath,
    startLine: range.startLine, endLine: range.endLine,
    signature: `${isAbstract ? 'abstract ' : ''}class ${name}`,
    isExported: exported, parentName, docComment,
    modifiers: modifiers.length > 0 ? modifiers : undefined,
    decorators: decorators.length > 0 ? decorators : undefined,
  });
  const body = getNamedChild(node, 'class_body');
  if (body) extractClassMembers(body, source, filePath, name, symbols);
}

export function extractClassMembers(
  body: SyntaxNode, source: string, filePath: string,
  className: string, symbols: ExtractedSymbol[],
): void {
  for (let i = 0; i < body.namedChildCount; i++) {
    const member = body.namedChild(i);
    if (!member) continue;
    switch (member.type) {
      case 'method_definition':
        extractMethod(member, source, filePath, className, symbols); break;
      case 'public_field_definition':
      case 'property_definition':
        extractProperty(member, source, filePath, className, symbols); break;
    }
  }
}

export function extractMethod(
  node: SyntaxNode, source: string, filePath: string,
  className: string, symbols: ExtractedSymbol[],
): void {
