export function extractTypeAlias(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
): void {
  const nameNode = getNamedChild(node, 'type_identifier') ?? getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const exported = isExported(node);
  symbols.push({ name, kind: 'type', filePath, startLine: range.startLine, endLine: range.endLine, signature: getNodeText(node, source).split('\n')[0].trim().slice(0, 200), isExported: exported, parentName });
}

export function extractEnum(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
): void {
  const nameNode = getNamedChild(node, 'identifier');
  if (!nameNode) return;
  const name = getNodeText(nameNode, source);
  const range = getNodeRange(node);
  const exported = isExported(node);
  symbols.push({ name, kind: 'enum', filePath, startLine: range.startLine, endLine: range.endLine, signature: `enum ${name}`, isExported: exported, parentName });
}

export function extractVariableDeclaration(
  node: SyntaxNode, source: string, filePath: string,
  parentName: string | null, symbols: ExtractedSymbol[],
): void {
  for (let i = 0; i < node.namedChildCount; i++) {
    const declarator = node.namedChild(i);
    if (!declarator || declarator.type !== 'variable_declarator') continue;
    const nameNode = getNamedChild(declarator, 'identifier');
    if (!nameNode) continue;
    const name = getNodeText(nameNode, source);
    const value = getNamedChild(declarator, 'arrow_function') ?? getNamedChild(declarator, 'function_expression') ?? getNamedChild(declarator, 'function');
    if (value) {
      const range = getNodeRange(node);
      const params = extractParameters(value, source);
      const returnType = extractReturnType(value, source);
      const exported = isExported(node);
      const isAsync = hasModifier(value, source, 'async');
      const docComment = extractDocComment(node, source);
      symbols.push({ name, kind: 'function', filePath, startLine: range.startLine, endLine: range.endLine, signature: buildFunctionSignature(name, params, returnType, isAsync), parameters: params, returnType, isAsync, isExported: exported, parentName, docComment, complexity: calculateComplexity(value) });
    }
  }
}

/**
 * KSA-146: TypeScript/JavaScript Language Parser (Modular Architecture).
 * Delegates extraction to specialized sub-extractors for maintainability.
 * Supports both TypeScript (.ts/.tsx) and JavaScript (.js/.jsx/.mjs/.cjs).
 */

import type { ILanguageParser, ParseResult, ExtractedSymbol, ExtractedRelationship, ParseError, SyntaxNode } from '../types.js';
import { findNodes } from '../ast-utils.js';
import { TSSymbolExtractor } from './ts-symbol-extractor.js';
import { TSCallExtractor } from './ts-call-extractor.js';
import { TSImportExtractor } from './ts-import-extractor.js';
import { TSInheritanceExtractor } from './ts-inheritance-extractor.js';

export default class TypeScriptParser implements ILanguageParser {
  readonly languageId: string;
  private parser: any; // web-tree-sitter Parser instance
  private symbolExtractor: TSSymbolExtractor;
  private callExtractor: TSCallExtractor;
  private importExtractor: TSImportExtractor;
  private inheritanceExtractor: TSInheritanceExtractor;

  constructor(parser: any, languageId: string) {
    this.parser = parser;
    this.languageId = languageId;
    this.symbolExtractor = new TSSymbolExtractor();
    this.callExtractor = new TSCallExtractor();
    this.importExtractor = new TSImportExtractor();
    this.inheritanceExtractor = new TSInheritanceExtractor();
  }

  getSupportedExtensions(): string[] {
    return this.languageId === 'typescript'
      ? ['.ts', '.tsx']
      : ['.js', '.jsx', '.mjs', '.cjs'];
  }

  parse(source: string, filePath: string): ParseResult {
    const tree = this.parser.parse(source);
    const rootNode = tree.rootNode;

    // Collect parse errors
    const errors: ParseError[] = [];
    if (rootNode.hasError) {
      const errorNodes = findNodes(rootNode, 'ERROR');
      for (const node of errorNodes.slice(0, 10)) {
        errors.push({
          message: 'Parse error',
          line: node.startPosition.row + 1,
          column: node.startPosition.column,
        });
      }
    }

    // Extract symbols (functions, classes, interfaces, etc.)
    const relationships: ExtractedRelationship[] = [];
    const symbols = this.symbolExtractor.extract(rootNode, source, filePath, relationships);

    // Extract call relationships
    const calls = this.callExtractor.extract(rootNode, source, filePath, symbols);

    // Extract import relationships
    const imports = this.importExtractor.extract(rootNode, source, filePath);

    // Extract inheritance relationships
    const inheritance = this.inheritanceExtractor.extract(rootNode, source, filePath, symbols);

    // Merge all relationships
    const allRelationships = [...relationships, ...calls, ...imports, ...inheritance];

    return { symbols, relationships: allRelationships, errors };
  }
}

/**
 * Signature Extractor — Multi-language regex-based symbol extraction.
 * Extracts functions, classes, interfaces, and other symbols from source files.
 */

export interface ExtractedSymbol {
  name: string;
  kind: SymbolKind;
  signature: string;
  startLine: number;
  endLine: number;
  parentSymbol: string | null;
  visibility: string | null;
  docComment: string | null;
}

export type SymbolKind =
  | 'function' | 'class' | 'interface' | 'method'
  | 'enum' | 'type' | 'constant' | 'variable'
  | 'module' | 'namespace' | 'trait' | 'struct';

interface PatternDef {
  regex: RegExp;
  kind: SymbolKind;
  nameGroup: number;
  signatureGroup?: number;
}

/** Extract symbols from source content based on language. */
export function extractSymbols(content: string, language: string): ExtractedSymbol[] {
  const patterns = getPatterns(language);
  if (!patterns.length) return [];

  const lines = content.split('\n');
  const symbols: ExtractedSymbol[] = [];

  for (const pattern of patterns) {
    extractWithPattern(lines, content, pattern, symbols);
  }

  return deduplicateSymbols(symbols);
}

function extractWithPattern(
  lines: string[], content: string, pattern: PatternDef, symbols: ExtractedSymbol[]
): void {
  const matches = content.matchAll(new RegExp(pattern.regex, 'gm'));
  for (const match of matches) {
    if (!match.index && match.index !== 0) continue;
    const startLine = content.slice(0, match.index).split('\n').length;
    const name = match[pattern.nameGroup];
    if (!name || name.length > 100) continue;

    symbols.push({
      name,
      kind: pattern.kind,
      signature: (match[pattern.signatureGroup ?? 0] ?? match[0]).trim().slice(0, 500),
      startLine,
      endLine: estimateEndLine(lines, startLine),
      parentSymbol: null,
      visibility: extractVisibility(match[0]),
      docComment: extractDocComment(lines, startLine - 1),
    });
  }
}

function estimateEndLine(lines: string[], startLine: number): number {
  let depth = 0;
  let foundOpen = false;
  for (let i = startLine - 1; i < lines.length && i < startLine + 200; i++) {
    const line = lines[i];
    for (const ch of line) {
      if (ch === '{') { depth++; foundOpen = true; }
      if (ch === '}') depth--;
    }
    if (foundOpen && depth <= 0) return i + 1;
  }
  return Math.min(startLine + 1, lines.length);
}

function extractVisibility(text: string): string | null {
  if (/\bpublic\b/.test(text)) return 'public';
  if (/\bprivate\b/.test(text)) return 'private';
  if (/\bprotected\b/.test(text)) return 'protected';
  if (/\binternal\b/.test(text)) return 'internal';
  if (/\bexport\b/.test(text)) return 'export';
  return null;
}

function extractDocComment(lines: string[], lineIdx: number): string | null {
  const comments: string[] = [];
  for (let i = lineIdx - 1; i >= Math.max(0, lineIdx - 15); i--) {
    const line = lines[i].trim();
    if (line.startsWith('*') || line.startsWith('/**') || line.startsWith('///') || line.startsWith('#')) {
      comments.unshift(line.replace(/^\/\*\*|\*\/|\*|\/\/\/|#\s?/g, '').trim());
    } else if (line === '') {
      continue;
    } else {
      break;
    }
  }
  return comments.length > 0 ? comments.join(' ').slice(0, 500) : null;
}

function deduplicateSymbols(symbols: ExtractedSymbol[]): ExtractedSymbol[] {
  const seen = new Set<string>();
  return symbols.filter(s => {
    const key = `${s.name}:${s.startLine}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function getPatterns(language: string): PatternDef[] {
  switch (language) {
    case 'typescript': case 'javascript': return TS_PATTERNS;
    case 'kotlin': return KOTLIN_PATTERNS;
    case 'python': return PYTHON_PATTERNS;
    case 'java': return JAVA_PATTERNS;
    case 'go': return GO_PATTERNS;
    case 'rust': return RUST_PATTERNS;
    default: return GENERIC_PATTERNS;
  }
}

const TS_PATTERNS: PatternDef[] = [
  { regex: /^(?:export\s+)?(?:async\s+)?function\s+(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^(?:export\s+)?class\s+(\w+)/m, kind: 'class', nameGroup: 1 },
  { regex: /^(?:export\s+)?interface\s+(\w+)/m, kind: 'interface', nameGroup: 1 },
  { regex: /^(?:export\s+)?type\s+(\w+)/m, kind: 'type', nameGroup: 1 },
  { regex: /^(?:export\s+)?enum\s+(\w+)/m, kind: 'enum', nameGroup: 1 },
  { regex: /^(?:export\s+)?const\s+(\w+)\s*=\s*(?:async\s*)?\(/m, kind: 'function', nameGroup: 1 },
];

const KOTLIN_PATTERNS: PatternDef[] = [
  { regex: /^\s*(?:(?:public|private|internal|protected)\s+)?(?:suspend\s+)?fun\s+(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|internal|protected)\s+)?(?:data\s+|sealed\s+|abstract\s+|open\s+)?class\s+(\w+)/m, kind: 'class', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|internal|protected)\s+)?interface\s+(\w+)/m, kind: 'interface', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|internal|protected)\s+)?object\s+(\w+)/m, kind: 'module', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|internal|protected)\s+)?enum\s+class\s+(\w+)/m, kind: 'enum', nameGroup: 1 },
];

const PYTHON_PATTERNS: PatternDef[] = [
  { regex: /^(?:async\s+)?def\s+(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^class\s+(\w+)/m, kind: 'class', nameGroup: 1 },
];

const JAVA_PATTERNS: PatternDef[] = [
  { regex: /^\s*(?:(?:public|private|protected)\s+)?(?:static\s+)?(?:[\w<>\[\]]+\s+)(\w+)\s*\(/m, kind: 'function', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|protected)\s+)?(?:abstract\s+)?class\s+(\w+)/m, kind: 'class', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|protected)\s+)?interface\s+(\w+)/m, kind: 'interface', nameGroup: 1 },
  { regex: /^\s*(?:(?:public|private|protected)\s+)?enum\s+(\w+)/m, kind: 'enum', nameGroup: 1 },
];

const GO_PATTERNS: PatternDef[] = [
  { regex: /^func\s+(?:\(\w+\s+\*?\w+\)\s+)?(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^type\s+(\w+)\s+struct/m, kind: 'struct', nameGroup: 1 },
  { regex: /^type\s+(\w+)\s+interface/m, kind: 'interface', nameGroup: 1 },
];

const RUST_PATTERNS: PatternDef[] = [
  { regex: /^\s*(?:pub\s+)?(?:async\s+)?fn\s+(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^\s*(?:pub\s+)?struct\s+(\w+)/m, kind: 'struct', nameGroup: 1 },
  { regex: /^\s*(?:pub\s+)?trait\s+(\w+)/m, kind: 'trait', nameGroup: 1 },
  { regex: /^\s*(?:pub\s+)?enum\s+(\w+)/m, kind: 'enum', nameGroup: 1 },
  { regex: /^\s*(?:pub\s+)?mod\s+(\w+)/m, kind: 'module', nameGroup: 1 },
];

const GENERIC_PATTERNS: PatternDef[] = [
  { regex: /^(?:function|def|func|fn|sub)\s+(\w+)/m, kind: 'function', nameGroup: 1 },
  { regex: /^(?:class|struct|type)\s+(\w+)/m, kind: 'class', nameGroup: 1 },
];

import * as fs from 'fs';
import * as path from 'path';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { GrammarRegistry } from './grammar-registry.js';
import { extractSymbols } from './signature-extractor.js';
import type { ParseResult, IndexResult, FileDependency } from './types.js';
import { storeResults, storeRegexResults, extractAndStoreBodies } from './indexer/storage.js';
import { DependencyResolver } from './dependency-resolver.js';

export class TreeSitterIndexer {
  private registry: GrammarRegistry;
  private adapter: DatabaseAdapter;
  private maxFileSize: number;
  private depResolver: DependencyResolver;
  private workspace: string;

  constructor(registry: GrammarRegistry, adapter: DatabaseAdapter, maxFileSize: number = 1_048_576, workspace: string = '') {
    this.registry = registry;
    this.adapter = adapter;
    this.maxFileSize = maxFileSize;
    this.depResolver = new DependencyResolver();
    this.workspace = workspace;
  }

  async indexFile(filePath: string, relativePath: string, projectId: string): Promise<IndexResult> {
    const startTime = Date.now();
    let source: string;
    try {
      const stat = fs.statSync(filePath);
      if (stat.size > this.maxFileSize) return await this.regexFallback(filePath, relativePath, projectId, startTime);
      source = fs.readFileSync(filePath, 'utf-8');
    } catch {
      return { filePath: relativePath, symbolCount: 0, relationshipCount: 0, parseErrors: 1, duration: Date.now() - startTime, method: 'regex-fallback', dependencies: [] };
    }
    const parser = await this.registry.getParser(filePath);
    let result: ParseResult;
    let method: 'tree-sitter' | 'regex-fallback';
    if (parser) {
      result = parser.parse(source, relativePath);
      method = 'tree-sitter';
    } else {
      return await this.regexFallback(filePath, relativePath, projectId, startTime);
    }
    const symbolIds = await storeResults(this.adapter, relativePath, result, projectId);
    await extractAndStoreBodies(this.adapter, relativePath, source, result, symbolIds, projectId);
    const dependencies = this.depResolver.resolve(source, relativePath, this.workspace);
    return { filePath: relativePath, symbolCount: result.symbols.length, relationshipCount: result.relationships.length, parseErrors: result.errors.length, duration: Date.now() - startTime, method, dependencies };
  }

  async indexFiles(files: { absolutePath: string; relativePath: string }[], projectId: string): Promise<IndexResult[]> {
    const results: IndexResult[] = [];
    for (const file of files) {
      results.push(await this.indexFile(file.absolutePath, file.relativePath, projectId));
    }
    return results;
  }

  private async regexFallback(filePath: string, relativePath: string, projectId: string, startTime: number): Promise<IndexResult> {
    try {
      const source = fs.readFileSync(filePath, 'utf-8');
      const ext = path.extname(filePath).toLowerCase();
      const language = this.extToLanguage(ext);
      const symbols = extractSymbols(source, language);
      if (symbols.length > 0) await storeRegexResults(this.adapter, relativePath, symbols, projectId);
      const dependencies = this.depResolver.resolve(source, relativePath, this.workspace);
      return { filePath: relativePath, symbolCount: symbols.length, relationshipCount: 0, parseErrors: 0, duration: Date.now() - startTime, method: 'regex-fallback', dependencies };
    } catch {
      return { filePath: relativePath, symbolCount: 0, relationshipCount: 0, parseErrors: 1, duration: Date.now() - startTime, method: 'regex-fallback', dependencies: [] };
    }
  }

  private extToLanguage(ext: string): string {
    const map: Record<string, string> = {
      '.ts': 'typescript', '.tsx': 'typescript', '.js': 'javascript', '.jsx': 'javascript',
      '.py': 'python', '.kt': 'kotlin', '.kts': 'kotlin', '.java': 'java', '.go': 'go', '.rs': 'rust',
      '.cls': 'apex', '.trigger': 'apex',
    };
    return map[ext] ?? 'generic';
  }
}

