﻿/**
 * code_symbols tool — Lookup symbols by name, kind, or file path.
 */

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { z } from 'zod';
import { QueryLayer } from '../query/query-layer.js';

export function registerCodeSymbols(server: McpServer, queryLayer: QueryLayer): void {
  server.tool(
    'code_symbols',
    'Find code symbols by name prefix or list symbols in a file. Filter by kind (function, class, interface, etc).',
    {
      name: z.string().optional().describe('Symbol name or prefix to search'),
      file: z.string().optional().describe('File path to list symbols from'),
      kind: z.string().optional().describe('Filter by kind: function, class, interface, enum, type, method'),
      limit: z.number().optional().default(50).describe('Max results'),
      __projectId: z.string().optional().describe('SA4E-41 tenant scope (injected)'),
    },
    async ({ name, file, kind, limit, __projectId }) => {
      let text: string;
      if (file) {
        const symbols = await queryLayer.getFileSymbols(__projectId, file);
        text = formatFileSymbols(file, symbols);
      } else if (name) {
        const symbols = await queryLayer.findSymbols(__projectId, name, kind, limit);
        text = formatSymbolList(symbols, name);
      } else {
        text = 'Provide either "name" or "file" parameter';
      }
      return { content: [{ type: 'text', text }] };
    }
  );
}

function formatFileSymbols(file: string, symbols: any[]): string {
  if (symbols.length === 0) return `No symbols found in ${file}`;
  const lines = [`Symbols in ${file} (${symbols.length}):\n`];
  for (const s of symbols) {
    const vis = s.visibility ? `[${s.visibility}] ` : '';
    lines.push(`  L${s.startLine} ${vis}${s.kind} ${s.name}`);
  }
  return lines.join('\n');
}

function formatSymbolList(symbols: any[], query: string): string {
  if (symbols.length === 0) return `No symbols matching "${query}"`;
  const lines = [`Found ${symbols.length} symbols matching "${query}":\n`];
  for (const s of symbols) {
    lines.push(`[${s.kind}] ${s.name} — ${s.filePath}:${s.startLine}`);
    if (s.signature) lines.push(`  ${s.signature.slice(0, 120)}`);
  }
  return lines.join('\n');
}

/**
 * SA4E-84 — Apply orchestrator for ELK auto-layout fix mode.
 * Coordinates: normalize args → build ELK graph → run layout → write XML → validate.
 * Writes fixed XML directly to file. Returns metadata only (no content_base64).
 */

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import type { DiagramGraph } from './drawio-parser.js';
import { parseDrawio } from './drawio-parser.js';
import type { NormalizedArgs } from './drawio-layout-models.js';
import { buildElkGraph, runElkLayout } from './elk-layout.js';
import { applyLayoutToXml } from './drawio-writer.js';

/**
 * Parse an integer from environment variable with bounds validation (SEC-02).
 * Returns defaultVal if env var is missing, NaN, out of bounds, or non-finite.
 * @param envVar - Environment variable name
 * @param defaultVal - Fallback value
 * @param min - Minimum allowed value (inclusive)
 * @param max - Maximum allowed value (inclusive)
 */
function parseEnvInt(envVar: string, defaultVal: number, min: number, max: number): number {
  const raw = process.env[envVar];
  if (raw === undefined) return defaultVal;
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed < min || parsed > max) return defaultVal;
  return Math.floor(parsed);
}

// BR-7: configurable limits via env (NFR-P5) — with bounds validation (SEC-02)
const MAX_NODES = parseEnvInt('SA4E_ELK_MAX_NODES', 500, 1, 5000);
const TIMEOUT_MS = parseEnvInt('SA4E_ELK_TIMEOUT_MS', 10_000, 1000, 60_000);

/** Maximum spacing in pixels to prevent resource exhaustion (SEC-03). */
const MAX_SPACING = 500;

/**
 * Orchestrate ELK layout fix: build graph → run ELK → write to file → return metadata.
 * @param rawXml - Original XML content
 * @param graph - Parsed diagram graph
 * @param issues - Detected issues (before fix)
 * @param nodeCount - Total node count
 * @param args - Tool arguments for algorithm/spacing/direction
 * @param filePath - Absolute path to write fixed XML
 * @returns JSON string with status, repositioned_nodes (no content_base64)
 */
export async function handleApply(
  rawXml: string, graph: DiagramGraph, issues: object[], nodeCount: number,
  args: Record<string, unknown>, filePath: string,
): Promise<string> {
  if (nodeCount > MAX_NODES) return error(`Diagram too large (${nodeCount} nodes, max ${MAX_NODES})`);
  const normalized = normalizeLayoutArgs(args);
  // Container detected → edge-only fix (keep node positions, only distribute ports)
  if (graph.containers.length > 0) {
    return handleEdgeOnlyFix(rawXml, graph, issues, filePath);
  }
  // Flat diagram → full ELK repositioning
  try {
    const elkGraph = buildElkGraph(graph, normalized);
    const laidOut = await runElkLayout(elkGraph, TIMEOUT_MS);
    const { xml, repositionedNodes } = applyLayoutToXml(rawXml, laidOut);
    if (repositionedNodes.length === 0) return error('ELK layout produced no position changes');
    validateReparse(xml);
    fs.writeFileSync(filePath, xml, 'utf-8');
    return JSON.stringify({
      status: 'fixed',
      message: `Fixed ${issues.length} issues with ELK ${normalized.algorithm} layout. ${repositionedNodes.length} nodes repositioned.`,
    });
  } catch (e: any) {
    console.error('[drawio-apply] ELK layout error:', e);
    return error('Layout engine failed. Please check input diagram and retry.');
  }
}

/** Normalize layout args with safe defaults and upper bounds (SEC-03). */
export function normalizeLayoutArgs(args: Record<string, unknown>): NormalizedArgs {
  const VALID_ALG = ['layered', 'force', 'mrtree', 'radial'];
  const VALID_DIR = ['DOWN', 'RIGHT', 'LEFT', 'UP'];
  const algorithm = typeof args.algorithm === 'string' && VALID_ALG.includes(args.algorithm)
    ? args.algorithm : 'layered';
  // SEC-03: Cap spacing to MAX_SPACING to prevent resource exhaustion
  const rawSpacing = typeof args.spacing === 'number' && args.spacing > 0 ? args.spacing : 80;
  const spacing = Math.min(rawSpacing, MAX_SPACING);
  const direction = typeof args.direction === 'string' && VALID_DIR.includes(args.direction.toUpperCase())
    ? args.direction.toUpperCase() : 'DOWN';
  return { algorithm, spacing, direction };
}

/**
 * Edge-only fix for container diagrams: distribute edge ports to prevent stacking.
 * Keeps all node positions unchanged. Only modifies edge style attributes.
 */
function handleEdgeOnlyFix(
  rawXml: string, graph: DiagramGraph, issues: object[], filePath: string,
): string {
  try {
    let xml = rawXml;
    const nodeMap = new Map([...graph.nodes, ...graph.containers].map(n => [n.id, n]));
    const edgesBySource = new Map<string, typeof graph.edges>();
    const edgesByTarget = new Map<string, typeof graph.edges>();
    for (const e of graph.edges) {
      if (!edgesBySource.has(e.sourceId)) edgesBySource.set(e.sourceId, []);
      edgesBySource.get(e.sourceId)!.push(e);
      if (!edgesByTarget.has(e.targetId)) edgesByTarget.set(e.targetId, []);
      edgesByTarget.get(e.targetId)!.push(e);
    }
    for (const [nodeId, edges] of edgesBySource) {
      if (edges.length <= 1 || !nodeMap.has(nodeId)) continue;
      for (let i = 0; i < edges.length; i++) {
        const exitX = (i + 1) / (edges.length + 1);
        xml = addPortToEdge(xml, edges[i].id, 'exit', exitX, 1);
      }
    }
    for (const [nodeId, edges] of edgesByTarget) {
      if (edges.length <= 1 || !nodeMap.has(nodeId)) continue;
      for (let i = 0; i < edges.length; i++) {
        const entryX = (i + 1) / (edges.length + 1);
        xml = addPortToEdge(xml, edges[i].id, 'entry', entryX, 0);
      }
    }
    if (xml === rawXml) {
      return JSON.stringify({ status: 'already_good', message: 'Container diagram — no edge routing improvements needed.' });
    }
    validateReparse(xml);
    fs.writeFileSync(filePath, xml, 'utf-8');
    return JSON.stringify({
      status: 'fixed',
      message: `Fixed edge routing for container diagram. ${issues.length} issues detected, ports distributed.`,
    });
  } catch (e: any) {
    console.error('[drawio-apply] Edge-only fix error:', e);
    return error('Edge routing fix failed. Please check diagram structure.');
  }
}

/** Add exit/entry port coordinates to an edge style attribute. */
function addPortToEdge(xml: string, edgeId: string, type: 'exit' | 'entry', x: number, y: number): string {
  const escaped = edgeId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`(<mxCell\\b[^>]*\\bid="${escaped}"[^>]*style=")([^"]*)("`);
  return xml.replace(regex, (_match, pre: string, style: string, post: string) => {
    let clean = style.replace(new RegExp(`${type}X=[^;]*;?`, 'g'), '');
    clean = clean.replace(new RegExp(`${type}Y=[^;]*;?`, 'g'), '');
    clean = clean.replace(new RegExp(`${type}Dx=[^;]*;?`, 'g'), '');
    clean = clean.replace(new RegExp(`${type}Dy=[^;]*;?`, 'g'), '');
    const port = `${type}X=${x.toFixed(2)};${type}Y=${y};${type}Dx=0;${type}Dy=0;`;
    return `${pre}${clean}${port}${post}`;
  });
}

/** BR-7: Re-parse fixed XML to ensure it's valid before writing to file. */
function validateReparse(xml: string): void {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'drawio-fix-'));
  try {
    const tmpFile = path.join(tmpDir, 'fixed.drawio');
    fs.writeFileSync(tmpFile, xml, 'utf-8');
    parseDrawio(tmpFile); // Throws if XML is broken
  } finally {
    try {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    } catch (cleanupErr) {
      console.error('[drawio-apply] Temp cleanup failed:', cleanupErr);
    }
  }
}

function error(msg: string): string {
  return JSON.stringify({ error: msg });
}

/**
 * drawio_export_png — Export .drawio XML (base64) to PNG (base64).
 * Backend receives content_base64, renders PNG, returns output_base64.
 * Priority: 1) draw.io CLI, 2) chrome-devtools-mcp, 3) puppeteer-mcp
 */
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import pino from 'pino';
import { setCachedDrawioCliPath, exportWithCli, exportWithChrome, exportWithPuppeteer, findDrawioCli, hasUpstreamServer } from './drawio-renderers.js';

const logger = pino({ name: 'drawio-export-png' });

export const DRAWIO_EXPORT_PNG_DEFINITION = {
  name: 'drawio_export_png',
  description: 'Export .drawio XML content (base64) to PNG. Returns output_base64 (PNG bytes).',
  inputSchema: {
    type: 'object',
    properties: {
      content_base64: { type: 'string', description: 'Base64-encoded .drawio XML content' },
      file_path: { type: 'string', description: 'Original file path (reference only)' },
    },
    required: ['content_base64'],
  },
};

type RendererType = 'drawio-cli' | 'chrome-devtools-mcp' | 'puppeteer-mcp' | 'none';

let cachedRenderer: RendererType | null = null;

export function detectRenderer(orchestrationEngine?: any): RendererType {
  if (cachedRenderer !== null) return cachedRenderer;
  const cliPath = findDrawioCli();
  if (cliPath) { setCachedDrawioCliPath(cliPath); cachedRenderer = 'drawio-cli'; return cachedRenderer; }
  if (orchestrationEngine && hasUpstreamServer(orchestrationEngine, 'chrome-devtools-mcp')) {
    cachedRenderer = 'chrome-devtools-mcp'; return cachedRenderer;
  }
  if (orchestrationEngine && hasUpstreamServer(orchestrationEngine, 'puppeteer')) {
    cachedRenderer = 'puppeteer-mcp'; return cachedRenderer;
  }
  cachedRenderer = 'none';
  return cachedRenderer;
}

export function isExportPngAvailable(orchestrationEngine?: any): boolean {
  return detectRenderer(orchestrationEngine) !== 'none';
}

export function resetRendererCache(): void {
  cachedRenderer = null;
  setCachedDrawioCliPath(null);
}

export async function handleDrawioExportPng(
  args: Record<string, unknown>,
  workspace: string,
  orchestrationEngine?: any
): Promise<string> {
  const b64 = args.content_base64 as string | undefined;
  if (!b64) return jsonError('content_base64 is required');

  const content = decodeBase64Content(b64);
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'drawio-'));
  const tmpDrawio = path.join(tmpDir, 'input.drawio');
  const tmpPng = path.join(tmpDir, 'input.png');

  try {
    const xml = wrapXmlIfNeeded(content);
    fs.writeFileSync(tmpDrawio, xml, 'utf-8');
    const renderer = detectRenderer(orchestrationEngine);
    await renderWithEngine(renderer, tmpDrawio, tmpPng, workspace, orchestrationEngine);
    if (!fs.existsSync(tmpPng)) return jsonError('Export failed — PNG not created');
    const pngBuf = fs.readFileSync(tmpPng);
    const outputBase64 = pngBuf.toString('base64');
    return JSON.stringify({ success: true, output_base64: outputBase64, size_bytes: pngBuf.length, renderer });
  } catch (e: any) {
    return jsonError(`Export failed: ${e.message ?? e}`);
  } finally {
    cleanupTmpDir(tmpDir);
  }
}

function decodeBase64Content(b64: string): string {
  return Buffer.from(b64, 'base64').toString('utf-8');
}

function wrapXmlIfNeeded(content: string): string {
  const trimmed = content.trim();
  if (trimmed.startsWith('<mxfile') || trimmed.startsWith('<?xml') || trimmed.startsWith('<mxGraphModel')) return content;
  return `<?xml version="1.0" encoding="UTF-8"?>\n<mxfile host="app.diagrams.net">\n<diagram name="Page-1">\n${content}\n</diagram>\n</mxfile>`;
}

async function renderWithEngine(
  renderer: RendererType, inputPath: string, outputPath: string,
  workspace: string, orchestrationEngine?: any
): Promise<void> {
  switch (renderer) {
    case 'drawio-cli': await exportWithCli(inputPath, outputPath); break;
    case 'chrome-devtools-mcp': await exportWithChrome(inputPath, outputPath, workspace, orchestrationEngine); break;
    case 'puppeteer-mcp': await exportWithPuppeteer(inputPath, outputPath, workspace, orchestrationEngine); break;
    default: throw new Error('No renderer available. Install draw.io desktop or configure chrome-devtools-mcp.');
  }
}

function cleanupTmpDir(dir: string): void {
  try { fs.rmSync(dir, { recursive: true, force: true }); } catch (err) { logger.debug({ err }, '[drawio-export-png] best-effort '); }
}

function jsonError(msg: string): string {
  return JSON.stringify({ success: false, error: msg });
}

/**
 * Parses draw.io XML into graph nodes and edges for layout processing.
 * Uses regex-based parsing (no external XML deps needed for draw.io format).
 */

import * as fs from 'fs';

export interface DiagramNode {
  id: string;
  parentId: string;
  x: number;
  y: number;
  width: number;
  height: number;
  style: string;
  isContainer: boolean;
}

export interface DiagramEdge {
  id: string;
  sourceId: string;
  targetId: string;
  style: string;
}

export interface DiagramGraph {
  nodes: DiagramNode[];
  edges: DiagramEdge[];
  containers: DiagramNode[];
}

/** Parse .drawio XML file into DiagramGraph. */
export function parseDrawio(filePath: string): { raw: string; graph: DiagramGraph } {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const graph = extractGraph(raw);
  return { raw, graph };
}

function extractGraph(xml: string): DiagramGraph {
  const nodes: DiagramNode[] = [];
  const edges: DiagramEdge[] = [];
  const containers: DiagramNode[] = [];

  // Match all mxCell elements (self-closing or with children)
  const cellRegex = /<mxCell\s([^>]*?)(?:\/>|>([\s\S]*?)<\/mxCell>)/g;
  const cells: Array<{ attrs: Record<string, string>; body: string }> = [];
  let match: RegExpExecArray | null;

  while ((match = cellRegex.exec(xml)) !== null) {
    const attrs = parseAttrs(match[1]);
    const body = match[2] ?? '';
    cells.push({ attrs, body });
  }

  const cellIds = new Set(cells.map(c => c.attrs['id'] ?? ''));

  for (const cell of cells) {
    const id = cell.attrs['id'] ?? '';
    const style = cell.attrs['style'] ?? '';
    const parent = cell.attrs['parent'] ?? '1';

    if (cell.attrs['edge'] === '1') {
      const src = cell.attrs['source'];
      const tgt = cell.attrs['target'];
      if (src && tgt) edges.push({ id, sourceId: src, targetId: tgt, style });
    } else if (id !== '0' && id !== '1') {
      const geom = parseGeometry(cell.body, cell.attrs);
      if (!geom) continue;
      const isCont = hasChildren(id, cells) || isContainerStyle(style, geom.w, geom.h);
      const node: DiagramNode = {
        id, parentId: parent,
        x: geom.x, y: geom.y, width: geom.w, height: geom.h,
        style, isContainer: isCont,
      };
      if (isCont) containers.push(node); else nodes.push(node);
    }
  }
  return { nodes, edges, containers };
}

function parseGeometry(body: string, cellAttrs: Record<string, string>): { x: number; y: number; w: number; h: number } | null {
  // Look for mxGeometry in body or as sibling in raw XML
  const geomRegex = /<mxGeometry\s([^>]*?)(?:\/>|>)/;
  const geomMatch = body.match(geomRegex);
  if (!geomMatch) return null;
  const attrs = parseAttrs(geomMatch[1]);
  if (attrs['as'] !== 'geometry') return null;
  return {
    x: parseFloat(attrs['x'] ?? '0'),
    y: parseFloat(attrs['y'] ?? '0'),
    w: parseFloat(attrs['width'] ?? '80'),
    h: parseFloat(attrs['height'] ?? '40'),
  };
}

function parseAttrs(attrStr: string): Record<string, string> {
  const result: Record<string, string> = {};
  const regex = /(\w+)="([^"]*)"/g;
  let m: RegExpExecArray | null;
  while ((m = regex.exec(attrStr)) !== null) {
    result[m[1]] = m[2];
  }
  return result;
}

function hasChildren(nodeId: string, cells: Array<{ attrs: Record<string, string>; body: string }>): boolean {
  return cells.some(c =>
    c.attrs['parent'] === nodeId && c.attrs['edge'] !== '1' && c.body.includes('mxGeometry')
  );
}

function isContainerStyle(style: string, width: number, height: number): boolean {
  const s = style.toLowerCase();
  if (s.includes('swimlane')) return true;
  if (s.includes('fillcolor=none') && s.includes('dashed=1')) return true;
  if (s.includes('shape=rectangle') && s.includes('dashed=1') && width > 300 && height > 300) return true;
  return false;
}

import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

let _cachedDrawioCliPath: string | null = null;

export function setCachedDrawioCliPath(path: string | null): void {
  _cachedDrawioCliPath = path;
}

export function getCachedDrawioCliPath(): string | null {
  return _cachedDrawioCliPath;
}

export function findDrawioCli(): string | null {
  if (_cachedDrawioCliPath) return _cachedDrawioCliPath;
  const candidates: string[] = [];
  if (process.platform === 'win32') {
    candidates.push(
      'C:\\Program Files\\draw.io\\draw.io.exe',
      `${process.env.LOCALAPPDATA || ''}\\Programs\\draw.io\\draw.io.exe`,
      `${process.env.PROGRAMFILES || ''}\\draw.io\\draw.io.exe`,
    );
  } else if (process.platform === 'darwin') {
    candidates.push(
      '/Applications/draw.io.app/Contents/MacOS/draw.io',
      '/usr/local/bin/drawio',
      `${process.env.HOME || ''}/Applications/draw.io.app/Contents/MacOS/draw.io`,
    );
  } else {
    candidates.push(
      '/usr/bin/drawio',
      '/usr/local/bin/drawio',
      '/snap/bin/drawio',
      `${process.env.HOME || ''}/.local/bin/drawio`,
    );
  }
  for (const candidate of candidates) {
    if (candidate && fs.existsSync(candidate)) return candidate;
  }
  try {
    const which = process.platform === 'win32' ? 'where drawio 2>nul' : 'which drawio';
    const result = execSync(which, { timeout: 5000, stdio: 'pipe' }).toString().trim();
    if (result && fs.existsSync(result.split('\n')[0])) return result.split('\n')[0];
  } catch (err) { console.debug('[drawio-renderers] not in PATH :', (err as Error).message); }
  return null;
}

export async function exportWithCli(inputPath: string, outputPath: string): Promise<void> {
  if (!_cachedDrawioCliPath) throw new Error('draw.io CLI path not cached');
  const cmd = `"${_cachedDrawioCliPath}" --export --format png --border 10 --output "${outputPath}" "${inputPath}"`;
  execSync(cmd, { timeout: 30000, stdio: 'pipe' });
}

