/** Context bag injected into every code-intel tool handler. */
interface CodeIntelContext {
  queryLayer: QueryLayer;
  adapter: DatabaseAdapter;
  dbManager: DatabaseManager | null;
  indexer: IndexingEngine;
  workspace: string;
  projectId?: string;
}

/** All handlers return Promise<string> — sync handlers are wrapped with resolve(). */
type CodeIntelHandlerFn = (args: Record<string, unknown>, ctx: CodeIntelContext) => Promise<string>;

/** Helper: normalise sync-or-async result to Promise<string>. */
function p(v: string | Promise<string> | Promise<string | null> | null | undefined, fallback = 'Unknown tool'): Promise<string> {
  if (v == null) return Promise.resolve(fallback);
  if (typeof v === 'string') return Promise.resolve(v);
  return v.then(r => r ?? fallback);
}

/**
 * OCP registry: tool name -> handler function.
 * To add a new code-intel tool: import its handler and add one line here.
 * dispatchCodeIntelTool() requires NO changes.
 */
const TOOL_HANDLER_REGISTRY: Record<string, CodeIntelHandlerFn> = {
  code_search:        (a, ctx) => p(handleCodeSearch(a, ctx.queryLayer, ctx.projectId)),
  code_symbols:       (a, ctx) => p(handleCodeSymbols(a, ctx.queryLayer, ctx.projectId)),
  code_context:       (a, ctx) => p(handleCodeContext(a, ctx.queryLayer, ctx.workspace, ctx.projectId)),
  code_modules:       (a, ctx) => p(handleCodeModules(a, ctx.queryLayer, ctx.projectId)),
  code_index_status:  (a, ctx) => p(handleCodeIndexStatus(a, ctx.queryLayer, ctx.indexer, ctx.workspace, ctx.projectId)),
  stream_write_file:  (a, ctx) => p(handleStreamWriteFile(a, ctx.workspace, ctx.projectId)),
  code_kb_export:     (a, ctx) => p(handleCodeKbExport(a, ctx.queryLayer, ctx.workspace)),
  drawio_auto_layout: (a, ctx) => p(handleDrawioLayout(a, ctx.workspace)),
  drawio_export_png:  (a, ctx) => p(handleDrawioExportPng(a, ctx.workspace, null as any)),
  code_callers:       (a, ctx) => p(handleCodeCallers(a, ctx.adapter, ctx.projectId)),
  code_callees:       (a, ctx) => p(handleCodeCallees(a, ctx.adapter, ctx.projectId)),
  code_dependencies:  (a, ctx) => p(handleCodeDependencies(a, ctx.adapter, ctx.workspace, ctx.projectId)),
  code_impact:        (a, ctx) => p(handleCodeImpact(a, ctx.adapter, ctx.workspace, ctx.projectId)),
  code_traverse:      (a, ctx) => p(handleCodeTraverse(a, ctx.adapter, ctx.workspace, ctx.projectId)),
  complexity_analysis:(a, ctx) => p(handleComplexityTool(a, ctx.adapter, ctx.projectId)),
  find_entry_points:  (a, ctx) => p(handleEntryPointTool(a, ctx.adapter, ctx.projectId)),
  find_circular_deps: (a, ctx) => p(handleGraphAnalysisTool('find_circular_deps', a, ctx.adapter, ctx.projectId), 'Unknown tool: find_circular_deps'),
  find_related_tests: (a, ctx) => p(handleGraphAnalysisTool('find_related_tests', a, ctx.adapter, ctx.projectId), 'Unknown tool: find_related_tests'),
  find_hot_paths:     (a, ctx) => p(handleGraphAnalysisTool('find_hot_paths', a, ctx.adapter, ctx.projectId), 'Unknown tool: find_hot_paths'),
  find_dead_imports:  (a, ctx) => p(handleGraphAnalysisTool('find_dead_imports', a, ctx.adapter, ctx.projectId), 'Unknown tool: find_dead_imports'),
  module_summary:     (a, ctx) => p(handleGraphAnalysisTool('module_summary', a, ctx.adapter, ctx.projectId), 'Unknown tool: module_summary'),
  get_ai_context:     (a, ctx) => p(handleGetAIContext(a, ctx.adapter, ctx.workspace, ctx.projectId)),
  get_edit_context:   (a, ctx) => p(handleGetEditContext(a, ctx.adapter, ctx.workspace, ctx.projectId)),
  get_curated_context:(a, ctx) => p(handleGetCuratedContext(a, ctx.adapter, ctx.workspace, ctx.dbManager, ctx.projectId)),
  find_duplicates:    (a, ctx) => p(handleSimilarityTool('find_duplicates', a, ctx.adapter, ctx.workspace, ctx.projectId), 'Unknown tool: find_duplicates'),
  find_dead_code:     (a, ctx) => p(handleSimilarityTool('find_dead_code', a, ctx.adapter, ctx.workspace, ctx.projectId), 'Unknown tool: find_dead_code'),
  git_search:         (a, ctx) => p(handleSimilarityTool('git_search', a, ctx.adapter, ctx.workspace, ctx.projectId), 'Unknown tool: git_search'),
  git_index:          (a, ctx) => p(handleSimilarityTool('git_index', a, ctx.adapter, ctx.workspace, ctx.projectId), 'Unknown tool: git_index'),
  analyze_artifact:    (a, _ctx) => handleAnalyzeArtifact(a, _ctx),
  code_search_by_tag:  (a, ctx) => p(handleCodeSearchByTag(ctx.adapter, a.tag as string, (a.limit as number) ?? 20, ctx.projectId)),
  code_enrichment_stats: (a, ctx) => p(handleCodeEnrichmentStats(ctx.adapter, ctx.projectId)),
};

/**
 * Dispatch a code-intelligence tool call via the handler registry.
 * OCP: adding a new tool requires only adding to TOOL_HANDLER_REGISTRY above.
 * DIP: QueryLayer and DatabaseAdapter are injected (created once at module init).
 */
export async function dispatchCodeIntelTool(
  name: string,
  args: Record<string, unknown>,
  queryLayer: QueryLayer,
  adapter: DatabaseAdapter,
  dbManager: DatabaseManager | null,
  indexer: IndexingEngine,
  workspace: string,
  projectId?: string,
): Promise<string> {
  const handler = TOOL_HANDLER_REGISTRY[name];
  if (!handler) return `Unknown tool: ${name}`;
  const ctx: CodeIntelContext = { queryLayer, adapter, dbManager, indexer, workspace, projectId };
  return handler(args, ctx);
}

/**
 * SA4E-85 — Knowledge persistence layer (database-agnostic).
 * Internal storage behind KnowledgeService. Uses DatabaseAdapter abstraction
 * to support both SQLite and PostgreSQL. DB perms hardened (Finding #22).
 */

import * as crypto from 'crypto';
import Database from 'better-sqlite3';
import type { QueryDatabaseAdapter } from '../database/adapters/DatabaseAdapter.js';
import { KNOWLEDGE_SCHEMA } from './schema.js';
import type {
  Thread, Message, Checkpoint, ToolExecution, Artifact,
  KnowledgeEvent, Agent, PendingWrite, SaveCheckpointInput, MessageInput,
} from './models.js';

/** Parse JSON safely with fallback. */
function parse<T>(raw: string | null | undefined, fallback: T): T {
  if (!raw) return fallback;
  try { return JSON.parse(raw) as T; } catch { return fallback; }
}

/**
 * KnowledgeDb — adapter-based persistence for LangGraph thread state.
 * All methods are async to support both SQLite and PostgreSQL engines.
 */
export class KnowledgeDb {
  constructor(private readonly adapter: QueryDatabaseAdapter) {}

  /**
   * Create an in-memory KnowledgeDb for testing.
   * Uses better-sqlite3 :memory: with sync-to-async wrapper.
   */
  static createInMemory(): KnowledgeDb {
    const raw = new Database(':memory:');
    raw.pragma('journal_mode = WAL');
    const adapter: QueryDatabaseAdapter = {
      async runAsync(sql, params?) { const s = raw.prepare(sql); const r = params ? s.run(...params) : s.run(); return { changes: r.changes, lastInsertRowid: r.lastInsertRowid }; },
      async getAsync<T>(sql: string, params?: unknown[]) { const s = raw.prepare(sql); return (params ? s.get(...params) : s.get()) as T | undefined; },
      async allAsync<T>(sql: string, params?: unknown[]) { const s = raw.prepare(sql); return (params ? s.all(...params) : s.all()) as T[]; },
      async execAsync(sql) { raw.exec(sql); },
      async transactionAsync<T>(fn: () => Promise<T>) { return fn(); },
    };
    raw.exec(KNOWLEDGE_SCHEMA);
    return new KnowledgeDb(adapter);
  }

  /** Detect PostgreSQL via runtime duck-typing (composed adapters expose getEngine). */
  private isPostgres(): boolean {
    const withEngine = (this.adapter as unknown as { getEngine?: () => string });
    return typeof withEngine.getEngine === 'function'
      && (withEngine.getEngine as () => string)() === 'postgresql';
  }

  /** Run schema migration (CREATE IF NOT EXISTS). */
  async migrate(): Promise<void> {
    await this.adapter.execAsync(KNOWLEDGE_SCHEMA);
    // PostgreSQL: events.id has no auto-increment default in the shared DDL
    // (INTEGER PRIMARY KEY auto-increments only in SQLite). Ensure a sequence
    // so concurrent LangGraph put/putWrites compute ids atomically (no MAX() race).
    if (this.isPostgres()) {
      await this.adapter.execAsync(`
        CREATE SEQUENCE IF NOT EXISTS knowledge_events_id_seq;
        SELECT setval('knowledge_events_id_seq', COALESCE((SELECT MAX(id) FROM events), 1));
        ALTER TABLE events ALTER COLUMN id SET DEFAULT nextval('knowledge_events_id_seq');
      `);
    }
  }

  /** No-op for adapter-based lifecycle (adapter manages its own connection). */
  close(): void { /* adapter lifecycle managed externally */ }

  // --- threads ---
  async createThread(t: Thread): Promise<void> {
    await this.adapter.runAsync(
      'INSERT INTO threads (thread_id, workspace_id, title, agent_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
      [t.thread_id, t.workspace_id, t.title, t.agent_id, t.status, t.created_at, t.updated_at],
    );
  }

  /**
   * Concurrency-safe thread creation for the checkpointer path. LangGraph fires
   * put/putWrites concurrently for the SAME thread_id — both may observe the
   * thread absent and both attempt creation. ON CONFLICT DO NOTHING lets one win;
   * the loser re-reads the winning row. `created` tells the caller whether to
   * append the THREAD_CREATED event (exactly once).
   */
  async ensureThread(t: Thread): Promise<{ created: boolean; thread: Thread }> {
    const now = new Date().toISOString();
    const candidate: Thread = {
      thread_id: t.thread_id,
      workspace_id: t.workspace_id,
      title: t.title ?? 'New thread',
      agent_id: t.agent_id ?? null,
      status: 'active',
      created_at: t.created_at ?? now,
      updated_at: now,
    };
    const result = await this.adapter.runAsync(
      `INSERT INTO threads (thread_id, workspace_id, title, agent_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT (thread_id) DO NOTHING`,
      [candidate.thread_id, candidate.workspace_id, candidate.title, candidate.agent_id, candidate.status, candidate.created_at, candidate.updated_at],
    );
    const row = await this.adapter.getAsync<Thread>(
      'SELECT * FROM threads WHERE thread_id = ?', [candidate.thread_id],
    );
    return { created: (result.changes ?? 0) > 0, thread: row as Thread };
  }

  async listThreads(workspaceId: string): Promise<Thread[]> {
    return this.adapter.allAsync<Thread>(
      'SELECT * FROM threads WHERE workspace_id = ? ORDER BY updated_at DESC', [workspaceId],
    );
  }

  async getThread(threadId: string): Promise<Thread | null> {
    const row = await this.adapter.getAsync<Thread>(
      'SELECT * FROM threads WHERE thread_id = ?', [threadId],
    );
    return row ?? null;
  }

  async deleteThread(threadId: string): Promise<void> {
    await this.adapter.transactionAsync(async () => {
      for (const table of ['threads', 'messages', 'checkpoints', 'tool_executions', 'artifacts', 'events']) {
        await this.adapter.runAsync(`DELETE FROM ${table} WHERE thread_id = ?`, [threadId]);
      }
    });
  }

  // --- messages ---
  async appendMessage(workspaceId: string, threadId: string, m: MessageInput, seq: number): Promise<void> {
    const id = m.id ?? crypto.randomUUID();
    const timestamp = m.timestamp ?? new Date().toISOString();
    await this.adapter.runAsync(
      `INSERT INTO messages (id, thread_id, workspace_id, role, content, agent_id, timestamp, seq) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT (id) DO NOTHING`,
      [id, threadId, workspaceId, m.role, m.content, m.agent_id ?? null, timestamp, seq],
    );
  }

  async listMessages(threadId: string): Promise<Message[]> {
    return this.adapter.allAsync<Message>(
      'SELECT * FROM messages WHERE thread_id = ? ORDER BY seq ASC', [threadId],
    );
  }

  async countMessages(threadId: string): Promise<number> {
    const row = await this.adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM messages WHERE thread_id = ?', [threadId],
    );
    return row?.cnt ?? 0;
  }

  // --- checkpoints ---
  async getCheckpoint(threadId: string): Promise<Checkpoint | null> {
    const row = await this.adapter.getAsync<Record<string, any>>(
      'SELECT * FROM checkpoints WHERE thread_id = ?', [threadId],
    );
    if (!row) return null;
    return {
      thread_id: row.thread_id,
      workspace_id: row.workspace_id,
      checkpoint: parse(row.checkpoint, null),
      metadata: parse(row.metadata, {}),
      channel_versions: parse(row.channel_versions, {}),
      pending_writes: parse<PendingWrite[]>(row.pending_writes, []),
      version: row.version,
      updated_at: row.updated_at,
    };
  }

  async upsertCheckpoint(workspaceId: string, threadId: string, input: SaveCheckpointInput): Promise<Checkpoint> {
    const existing = await this.getCheckpoint(threadId);
    const version = (existing?.version ?? 0) + 1;
    const writes = [...(existing?.pending_writes ?? []), ...(input.writes ?? input.pendingWrites ?? [])];
    const checkpoint = input.checkpoint ?? existing?.checkpoint ?? null;
    const metadata = input.metadata ?? existing?.metadata ?? {};
    const channelVersions = input.newVersions ?? existing?.channel_versions ?? {};
    const updatedAt = new Date().toISOString();
    await this.adapter.runAsync(
      `INSERT INTO checkpoints (thread_id, workspace_id, checkpoint, metadata, channel_versions, pending_writes, version, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT (thread_id) DO UPDATE SET
         checkpoint = excluded.checkpoint, metadata = excluded.metadata,
         channel_versions = excluded.channel_versions, pending_writes = excluded.pending_writes,
         version = excluded.version, updated_at = excluded.updated_at`,
      [threadId, workspaceId, JSON.stringify(checkpoint), JSON.stringify(metadata),
       JSON.stringify(channelVersions), JSON.stringify(writes), version, updatedAt],
    );
    return { thread_id: threadId, workspace_id: workspaceId, checkpoint, metadata, channel_versions: channelVersions, pending_writes: writes, version, updated_at: updatedAt };
  }

  // --- tool executions ---
  async addToolExecution(exec: ToolExecution): Promise<void> {
    await this.adapter.runAsync(
      'INSERT INTO tool_executions (id, thread_id, workspace_id, tool_id, name, status, input, output, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [exec.id, exec.thread_id, exec.workspace_id, exec.tool_id, exec.name, exec.status, JSON.stringify(exec.input ?? null), JSON.stringify(exec.output ?? null), exec.created_at],
    );
  }

  // --- artifacts ---
  async addArtifact(a: Artifact): Promise<void> {
    await this.adapter.runAsync(
      'INSERT INTO artifacts (id, thread_id, workspace_id, type, name, content, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
      [a.id, a.thread_id, a.workspace_id, a.type, a.name, JSON.stringify(a.content ?? null), a.created_at],
    );
  }

  async listArtifacts(threadId: string): Promise<Artifact[]> {
    const rows = await this.adapter.allAsync<Record<string, any>>(
      'SELECT * FROM artifacts WHERE thread_id = ? ORDER BY created_at ASC', [threadId],
    );
    return rows.map((row) => ({ ...row, content: parse(row.content, null) })) as unknown as Artifact[];
  }

  // --- events (append-only log) ---
  async appendEvent(workspaceId: string, threadId: string, type: string, payload: unknown): Promise<void> {
    // id auto-increments on both engines: SQLite rowid for INTEGER PRIMARY KEY,
    // PostgreSQL via knowledge_events_id_seq default (see migrate()).
    await this.adapter.runAsync(
      'INSERT INTO events (thread_id, workspace_id, type, payload, created_at) VALUES (?, ?, ?, ?, ?)',
      [threadId, workspaceId, type, JSON.stringify(payload ?? {}), new Date().toISOString()],
    );
  }

  async listEvents(threadId: string): Promise<KnowledgeEvent[]> {
    const rows = await this.adapter.allAsync<Record<string, any>>(
      'SELECT * FROM events WHERE thread_id = ? ORDER BY id ASC', [threadId],
    );
    return rows.map((row) => ({ ...row, payload: parse(row.payload, null) })) as unknown as KnowledgeEvent[];
  }

  // --- agents (registry) ---
  async upsertAgent(a: Agent): Promise<Agent> {
    await this.adapter.runAsync(
      `INSERT INTO agents (agent_id, name, description, tools, mcp_servers, auto_approve, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT (agent_id) DO UPDATE SET
         name = excluded.name, description = excluded.description, tools = excluded.tools,
         mcp_servers = excluded.mcp_servers, auto_approve = excluded.auto_approve, updated_at = excluded.updated_at`,
      [a.agent_id, a.name, a.description, JSON.stringify(a.tools), JSON.stringify(a.mcp_servers), JSON.stringify(a.auto_approve), a.created_at, a.updated_at],
    );
    return a;
  }

  async listAgents(): Promise<Agent[]> {
    const rows = await this.adapter.allAsync<Record<string, any>>(
      'SELECT * FROM agents ORDER BY name ASC', [],
    );
    return rows.map((row) => ({
      agent_id: row.agent_id,
      name: row.name,
      description: row.description,
      tools: parse<string[]>(row.tools, []),
      mcp_servers: parse<string[]>(row.mcp_servers, []),
      auto_approve: parse<string[]>(row.auto_approve, []),
      created_at: row.created_at,
      updated_at: row.updated_at,
    })) as unknown as Agent[];
  }
}

/**
 * SA4E-85 — KnowledgeService: async business logic + workspace binding.
 * Event Sourcing: every mutation appends to the append-only event log;
 * threads / messages / checkpoints are projections on top of it.
 *
 * Workspace isolation (SECURITY-REVIEW Finding #18): every thread access verifies
 * the caller's workspace_id matches the stored one. On mismatch all accessor
 * methods return null (routes map to 404 — never 403, preventing enumeration).
 */

import type { Logger } from 'pino';
import * as crypto from 'crypto';
import type { KnowledgeDb } from './KnowledgeDb.js';
import type { ProjectContext } from '../modules/memory/ProjectContext.js';
import type {
  Thread,
  Message,
  Checkpoint,
  KnowledgeEvent,
  Artifact,
  ToolExecution,
  Agent,
  CreateThreadInput,
  SaveCheckpointInput,
} from './models.js';
import { isUuidV4 } from './models.js';

export interface KnowledgeServiceOptions {
  defaultWorkspace?: string;
}

export class KnowledgeService {
  private readonly defaultWorkspace: string;

  constructor(
    private readonly db: KnowledgeDb,
    private readonly logger: Logger,
    options: KnowledgeServiceOptions = {},
  ) {
    this.defaultWorkspace = options.defaultWorkspace ?? 'default';
  }

  /** Caller workspace: X-Project-Id > JWT wid claim > default. */
  resolveWorkspaceId(ctx: ProjectContext): string {
    return ctx.projectId || ctx.workspaceId || this.defaultWorkspace;
  }

  /** Return the thread only if it belongs to the caller's workspace. */
  private async ownedThread(ctx: ProjectContext, threadId: string): Promise<Thread | null> {
    if (!isUuidV4(threadId)) return null;
    const thread = await this.db.getThread(threadId);
    if (!thread || thread.workspace_id !== this.resolveWorkspaceId(ctx)) return null;
    return thread;
  }

  async createThread(ctx: ProjectContext, input: CreateThreadInput): Promise<Thread> {
    const now = new Date().toISOString();
    const thread: Thread = {
      thread_id: crypto.randomUUID(),
      workspace_id: this.resolveWorkspaceId(ctx),
      title: input.title?.trim() || 'New thread',
      agent_id: input.agent_id || null,
      status: 'active',
      created_at: now,
      updated_at: now,
    };
    await this.db.createThread(thread);
    await this.db.appendEvent(thread.workspace_id, thread.thread_id, 'THREAD_CREATED', {
      title: thread.title,
      agent_id: thread.agent_id,
    });
    this.logger.info({ thread_id: thread.thread_id, workspace_id: thread.workspace_id }, 'Thread created');
    return thread;
  }

  async listThreads(ctx: ProjectContext): Promise<Thread[]> {
    return this.db.listThreads(this.resolveWorkspaceId(ctx));
  }

  async getThread(ctx: ProjectContext, threadId: string): Promise<Thread | null> {
    return this.ownedThread(ctx, threadId);
  }

  async getMessages(ctx: ProjectContext, threadId: string): Promise<Message[] | null> {
    if (!await this.ownedThread(ctx, threadId)) return null;
    return this.db.listMessages(threadId);
  }

  async getCheckpoint(ctx: ProjectContext, threadId: string): Promise<Checkpoint | null> {
    if (!await this.ownedThread(ctx, threadId)) return null;
    return this.db.getCheckpoint(threadId);
  }

  /** Save checkpoint (+ optional writes / messages) — projection updated. */
  async saveCheckpoint(ctx: ProjectContext, threadId: string, input: SaveCheckpointInput): Promise<Checkpoint | null> {
    const workspaceId = this.resolveWorkspaceId(ctx);
    let thread = await this.ownedThread(ctx, threadId);
    if (!thread) {
      // LangGraph fires put/putWrites concurrently for the SAME thread_id — two
      // requests may both observe the thread absent and both attempt creation.
      // ensureThread upserts (ON CONFLICT DO NOTHING) so exactly one wins; the
      // loser reads the winner's row and re-uses it (SAME workspace → re-verify
      // below succeeds, no 404). A thread owned by ANOTHER workspace is never
      // inserted or overwritten by ensureThread, and the re-verify below rejects
      // it with 404 (SECURITY-REVIEW #18). No pre-check: a same-workspace thread
      // that appeared between ownedThread and here is NOT an error.
      if (!isUuidV4(threadId)) return null;
      const { created, thread: ensured } = await this.db.ensureThread({
        thread_id: threadId,
        workspace_id: workspaceId,
        title: 'Auto thread',
        agent_id: null,
        status: 'active',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      });
      // Re-verify ownership AFTER the upsert: the loser of the race reads the
      // winner's row. If a concurrent request from another workspace won first,
      // the thread is not ours → 404 (no write, no enumeration).
      thread = await this.ownedThread(ctx, threadId);
      if (!thread) return null;
      if (created) {
        await this.db.appendEvent(workspaceId, threadId, 'THREAD_CREATED', { title: thread.title, agent_id: null });
      }
    }
    const checkpoint = await this.db.upsertCheckpoint(thread.workspace_id, threadId, input);
    const messages = input.messages ?? [];
    const seqBase = await this.db.countMessages(threadId);
    for (let i = 0; i < messages.length; i++) {
      await this.db.appendMessage(thread.workspace_id, threadId, messages[i], seqBase + i);
    }
    await this.db.appendEvent(thread.workspace_id, threadId, 'CHECKPOINT_SAVED', {
      version: checkpoint.version,
      writes: (input.writes ?? input.pendingWrites ?? []).length,
      messages: messages.length,
    });
    this.logger.info({ thread_id: threadId, version: checkpoint.version }, 'Checkpoint saved');
    return checkpoint;
  }

  async getEvents(ctx: ProjectContext, threadId: string): Promise<KnowledgeEvent[] | null> {
    if (!await this.ownedThread(ctx, threadId)) return null;
    return this.db.listEvents(threadId);
  }

  async getArtifacts(ctx: ProjectContext, threadId: string): Promise<Artifact[] | null> {
    if (!await this.ownedThread(ctx, threadId)) return null;
    return this.db.listArtifacts(threadId);
  }

  async addArtifact(ctx: ProjectContext, threadId: string, input: { type: string; name: string; content?: unknown }): Promise<Artifact | null> {
    const thread = await this.ownedThread(ctx, threadId);
    if (!thread) return null;
    const artifact: Artifact = {
      id: crypto.randomUUID(),
      thread_id: threadId,
      workspace_id: thread.workspace_id,
      type: input.type,
      name: input.name,
      content: input.content ?? null,
      created_at: new Date().toISOString(),
    };
    await this.db.addArtifact(artifact);
    await this.db.appendEvent(thread.workspace_id, threadId, 'ARTIFACT_ADDED', { type: input.type, name: input.name });
    return artifact;
  }

  async addToolExecution(ctx: ProjectContext, threadId: string, input: { tool_id: string; name: string; status: ToolExecution['status']; input?: unknown; output?: unknown }): Promise<ToolExecution | null> {
    const thread = await this.ownedThread(ctx, threadId);
    if (!thread) return null;
    const exec: ToolExecution = {
      id: crypto.randomUUID(),
      thread_id: threadId,
      workspace_id: thread.workspace_id,
      tool_id: input.tool_id,
      name: input.name,
      status: input.status,
      input: input.input ?? null,
      output: input.output ?? null,
      created_at: new Date().toISOString(),
    };
    await this.db.addToolExecution(exec);
    await this.db.appendEvent(thread.workspace_id, threadId, 'TOOL_EXECUTION', { tool_id: input.tool_id, status: input.status });
    return exec;
  }

  async getAgents(): Promise<Agent[]> {
    return this.db.listAgents();
  }

  async upsertAgent(input: Omit<Agent, 'created_at' | 'updated_at'>): Promise<Agent> {
    const now = new Date().toISOString();
    const agent: Agent = { ...input, created_at: now, updated_at: now };
    return this.db.upsertAgent(agent);
  }

  async deleteThread(ctx: ProjectContext, threadId: string): Promise<boolean> {
    const thread = await this.ownedThread(ctx, threadId);
    if (!thread) return false;
    await this.db.appendEvent(thread.workspace_id, threadId, 'THREAD_DELETED', {});
    await this.db.deleteThread(threadId);
    this.logger.info({ thread_id: threadId }, 'Thread deleted');
    return true;
  }
}

/**
 * SA4E-85 — Knowledge REST API route tests (Hono).
 * Exercises real KnowledgeService + in-memory SQLite through the Hono app.
 * STC: PBT-HYD-01 (create→UUID), IT-HYD-03 (checkpoint roundtrip), #18 (404),
 *      #19 (jwtAuth wired), #23 (rate limit + body cap).
 */

import { describe, it, expect } from 'vitest';
import pino from 'pino';
import { Hono } from 'hono';
import { KnowledgeDb } from '../KnowledgeDb.js';
import { KnowledgeService } from '../KnowledgeService.js';
import { createKnowledgeApiRoutes } from '../routes.js';
import { UUID_V4_REGEX } from '../models.js';
import { createProjectContext } from '../../modules/memory/ProjectContext.js';

const logger = pino({ level: 'silent' });

function makeApp(checkpointLimit = 10 * 1024 * 1024) {
  const db = KnowledgeDb.createInMemory();
  const service = new KnowledgeService(db, logger);
  const app = new Hono();
  app.route('/api/v1', createKnowledgeApiRoutes(service, logger, { checkpointBodyLimitBytes: checkpointLimit }));
  return { app, db, service };
}

function wsHeaders(projectId: string): Record<string, string> {
  return { 'Content-Type': 'application/json', 'X-Project-Id': projectId };
}

async function createThread(app: Hono, projectId = 'ws-A') {
  const res = await app.request('/api/v1/threads', {
    method: 'POST',
    headers: wsHeaders(projectId),
    body: JSON.stringify({ title: 'route-test' }),
  });
  const body = (await res.json()) as any;
  return { status: res.status, thread_id: body.data?.thread_id };
}

describe('Knowledge REST API — /api/v1', () => {
  it('POST /threads returns 201 with UUID v4 thread_id (PBT-HYD-01)', async () => {
    const { app } = makeApp();
    const { status, thread_id } = await createThread(app, 'ws-A');
    expect(status).toBe(201);
    expect(thread_id).toMatch(UUID_V4_REGEX);
  });

  it('POST /threads with non-object body returns 400', async () => {
    const { app } = makeApp();
    const res = await app.request('/api/v1/threads', {
      method: 'POST',
      headers: wsHeaders('ws-A'),
      body: JSON.stringify([1, 2, 3]),
    });
    expect(res.status).toBe(400);
    const body = (await res.json()) as any;
    expect(body.error.code).toBe('INVALID_REQUEST');
  });

  it('GET /threads lists only caller workspace threads', async () => {
    const { app } = makeApp();
    await createThread(app, 'ws-A');
    await createThread(app, 'ws-B');
    const res = await app.request('/api/v1/threads', { headers: wsHeaders('ws-A') });
    expect(res.status).toBe(200);
    const body = (await res.json()) as any;
    expect(body.data).toHaveLength(1);
    expect(body.data[0].workspace_id).toBe('ws-A');
  });

  it('GET /threads/:id from another workspace returns 404, not 403 (#18)', async () => {
    const { app } = makeApp();
    const { thread_id } = await createThread(app, 'ws-A');
    const res = await app.request(`/api/v1/threads/${thread_id}`, { headers: wsHeaders('ws-B') });
    expect(res.status).toBe(404);
    const body = (await res.json()) as any;
    expect(body.error.code).toBe('THREAD_NOT_FOUND');
  });

  it('GET /threads/:id/messages from another workspace returns 404 (#18)', async () => {
    const { app } = makeApp();
    const { thread_id } = await createThread(app, 'ws-A');
    const res = await app.request(`/api/v1/threads/${thread_id}/messages`, { headers: wsHeaders('ws-B') });
    expect(res.status).toBe(404);
  });

  it('PUT then GET checkpoint roundtrip (IT-HYD-03)', async () => {
    const { app } = makeApp();
    const { thread_id } = await createThread(app, 'ws-A');
    const payload = {
      checkpoint: { v: 3, channel_values: { messages: [{ role: 'user', content: 'persisted' }] } },
      metadata: { source: 'remote-checkpointer' },
      pendingWrites: [{ task_id: 't1', channel: 'state', value: 'ok' }],
      messages: [{ id: 'm1', role: 'user', content: 'persisted message' }],
    };
    const putRes = await app.request(`/api/v1/threads/${thread_id}/checkpoint`, {
      method: 'PUT',
      headers: wsHeaders('ws-A'),
      body: JSON.stringify(payload),
    });
    expect(putRes.status).toBe(200);
    const putBody = (await putRes.json()) as any;
    expect(putBody.data.checkpoint).toEqual(payload.checkpoint);
    expect(putBody.data.metadata).toEqual(payload.metadata);

    const getRes = await app.request(`/api/v1/threads/${thread_id}/checkpoint`, { headers: wsHeaders('ws-A') });
    expect(getRes.status).toBe(200);
    const getBody = (await getRes.json()) as any;
    expect(getBody.data.checkpoint).toEqual(payload.checkpoint);
    expect(getBody.data.pending_writes).toEqual(payload.pendingWrites);

    const msgRes = await app.request(`/api/v1/threads/${thread_id}/messages`, { headers: wsHeaders('ws-A') });
    const msgBody = (await msgRes.json()) as any;
    expect(msgBody.data).toHaveLength(1);
    expect(msgBody.data[0].content).toBe('persisted message');
