/**
 * ModuleFactory — creates and registers all modules with their dependencies.
 * Factory pattern: centralizes module instantiation, eliminates wiring from index.ts.
 * Each module is created with the right deps based on its constructor signature.
 */

import type { Logger } from 'pino';
import type { ModuleRegistry } from './ModuleRegistry.js';
import type { Container } from '../di/Container.js';
import { MemoryModule } from './memory/MemoryModule.js';
import { CodeIntelModule } from './code-intel/CodeIntelModule.js';
import { OrchestrationModule } from './orchestration/OrchestrationModule.js';
import { AnalyticsModule } from './analytics/AnalyticsModule.js';
import { KBGraphModule } from './kb-graph/KBGraphModule.js';
import { UtilityModule } from './utility/UtilityModule.js';
import { WebModule } from './web/WebModule.js';
import { SecurityModule } from './security/SecurityModule.js';
import { KnowledgeModule } from '../knowledge/KnowledgeModule.js';
import { HttpServer } from '../server/HttpServer.js';
import { MemoryToolSearchService } from './orchestration/MemoryToolSearchService.js';
import { ToolRouter } from '../tool-router/ToolRouter.js';
import { McpConfigService } from './orchestration/McpConfigService.js';

export interface ModuleFactoryConfig {
  port: number;
  host: string;
  workspace: string;
  dataDir: string;
  version: string;
}

export class ModuleFactory {
  constructor(
    private readonly registry: ModuleRegistry,
    private readonly logger: Logger,
    private readonly config: ModuleFactoryConfig,
    private readonly container?: Container,
  ) {}

  createAndRegisterAll(): void {
    this.registry.register(new MemoryModule(this.logger, undefined, this.registry));
    this.registry.register(new CodeIntelModule(this.logger));
    this.registry.register(new OrchestrationModule(this.logger, this.registry));
    this.registry.register(new AnalyticsModule(this.logger));
    this.registry.register(new KBGraphModule(this.logger));
    this.registry.register(new UtilityModule(this.logger));
    // SA4E-85 Phase 0: Backend-Driven Knowledge — SSOT for threads/checkpoints/events
    this.registry.register(new KnowledgeModule(this.logger));
    // SA4E-167: GateGuard — programmatic destructive command prevention
    this.registry.register(new SecurityModule(this.logger, this.registry));
  }

  createToolRouter(): ToolRouter {
    return new ToolRouter(this.registry, this.logger);
  }

  createMcpConfigService(): McpConfigService {
    return new McpConfigService(this.config.workspace, this.config.dataDir, this.logger);
  }

  createToolSearchService(memoryModule: MemoryModule): MemoryToolSearchService | null {
    try {
      const adapter = memoryModule.getEngine()?.getAdapter();
      if (!adapter) return null;
      return new MemoryToolSearchService(adapter, this.logger);
    } catch {
      return null;
    }
  }

  createHttpServer(toolRouter: ToolRouter, mcpConfigService: McpConfigService): HttpServer {
    return new HttpServer({
      port: this.config.port,
      host: this.config.host,
      logger: this.logger,
      registry: this.registry,
      version: this.config.version,
      toolRouter,
      mcpConfigService,
    });
  }
}

/**
 * Module lifecycle registry.
 * Observer pattern: emits lifecycle events via EventBus.
 * Modules and wiring logic subscribe to events instead of post-init casting.
 */

import type { IModule, ModuleHealth, ModuleStatus } from '../types/module.js';
import type { ToolHandler, ToolDefinition } from '../types/tool.js';
import type { Logger } from 'pino';
import { bus, Events } from '../shared/EventBus.js';

export class ModuleRegistry {
  private modules: Map<string, IModule> = new Map();
  private logger: Logger;
  private eventBus: typeof bus;

  constructor(logger: Logger, eventBus?: typeof bus) {
    this.logger = logger;
    this.eventBus = eventBus || bus;
  }

  register(module: IModule): void {
    this.modules.set(module.name, module);
    this.logger.info({ module: module.name }, 'Module registered');
    this.eventBus.emit(Events.MODULE_REGISTERED, { name: module.name });
  }

  async initializeAll(): Promise<void> {
    const initPromises = Array.from(this.modules.entries()).map(
      async ([name, module]) => {
        try {
          this.logger.info({ module: name }, 'Initializing module');
          await module.initialize();
          this.logger.info({ module: name, status: module.status }, 'Module initialized');
          if (module.status === 'ready') {
            this.eventBus.emit(Events.MODULE_READY, { name });
          } else {
            this.eventBus.emit(Events.MODULE_ERROR, { name, status: module.status });
          }
        } catch (err) {
          this.logger.error({ module: name, err }, 'Module initialization failed');
          this.eventBus.emit(Events.MODULE_ERROR, { name, error: String(err) });
        }
      }
    );

    await Promise.allSettled(initPromises);
  }

  async shutdownAll(): Promise<void> {
    const shutdownPromises = Array.from(this.modules.entries()).map(
      async ([name, module]) => {
        try {
          await module.shutdown();
          this.logger.info({ module: name }, 'Module shutdown complete');
          this.eventBus.emit(Events.MODULE_STOPPED, { name });
        } catch (err) {
          this.logger.error({ module: name, err }, 'Module shutdown failed');
        }
      }
    );

    await Promise.allSettled(shutdownPromises);
  }

  /**
   * SA4E-45: Hot-swap a module — shutdown then reinitialize.
   * Used when database engine is switched on-the-fly via admin UI.
   */
  async reinitializeModule(name: string): Promise<void> {
    const module = this.modules.get(name);
    if (!module) {
      this.logger.warn({ module: name }, 'Cannot reinitialize: module not found');
      return;
    }
    try {
      this.logger.info({ module: name }, 'Reinitializing module (hot-swap)');
      await module.shutdown();
      this.eventBus.emit(Events.MODULE_STOPPED, { name });
      await module.initialize();
      if (module.status === 'ready') {
        this.eventBus.emit(Events.MODULE_READY, { name });
      }
      this.logger.info({ module: name, status: module.status }, 'Module reinitialized');
    } catch (err) {
      this.logger.error({ module: name, err }, 'Module reinitialization failed');
      this.eventBus.emit(Events.MODULE_ERROR, { name, error: String(err) });
    }
  }

  /**
   * SA4E-45: Reinitialize all engine modules after DB switch.
   * Shuts down memory + codeIntel, then reinitializes with new adapter.
   */
  async reinitializeEngineModules(): Promise<void> {
    const engineModules = ['memory', 'codeIntel'];
    for (const name of engineModules) {
      await this.reinitializeModule(name);
    }
  }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();
    for (const module of this.modules.values()) {
      if (module.status === 'ready') {
        for (const [name, handler] of module.getToolHandlers()) {
          handlers.set(name, handler);
        }
      }
    }
    return handlers;
  }

  getModule(name: string): IModule | undefined {
    return this.modules.get(name);
  }

  getAllToolDefinitions(): ToolDefinition[] {
    const definitions: ToolDefinition[] = [];
    for (const module of this.modules.values()) {
      if (module.status === 'ready') {
        definitions.push(...module.getToolDefinitions());
      }
    }
    return definitions;
  }

  getHealth(): Record<string, ModuleStatus> {
    const health: Record<string, ModuleStatus> = {};
    for (const [name, module] of this.modules) {
      health[name] = module.status;
    }
    return health;
  }

  getModuleHealth(): ModuleHealth[] {
    return Array.from(this.modules.entries()).map(([name, module]) => ({
      name,
      status: module.status,
    }));
  }

  getReadyCount(): number {
    return Array.from(this.modules.values()).filter(m => m.status === 'ready').length;
  }

  getTotalCount(): number {
    return this.modules.size;
  }

  isAllReady(): boolean {
    return Array.from(this.modules.values()).every(m => m.status === 'ready');
  }
}

/**
 * Analytics Module — real tool usage stats and KB quality scoring.
 * Reads from mcp_tools (call counts), knowledge_entries (KB stats),
 * and audit_log (recent activity) via admin DB adapter.
 */

import type { IModule, ModuleStatus } from '../../types/module.js';
import type { ToolHandler, ToolDefinition } from '../../types/tool.js';
import type { Logger } from 'pino';
import { getAdminAdapter } from '../../admin/db/core.js';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { withErrorHandling, withTextResult, compose } from '../../tool-router/ToolHandlerDecorators.js';

/** Summary row returned by analytics_summary tool. */
interface AnalyticsSummary {
  totalCalls: number;
  uniqueTools: number;
  topTools: Array<{ name: string; calls: number }>;
  kbEntries: number;
  kbScopeCounts: Record<string, number>;
  recentErrors: number;
}

/** Quality row returned by quality_score tool. */
interface QualityScore {
  entry_id: string;
  score: number;
  factors: {
    hasContent: boolean;
    contentLength: number;
    tagCount: number;
    hasSummary: boolean;
    ageScore: number;
  };
}

export class AnalyticsModule implements IModule {
  readonly name = 'analytics';
  private _status: ModuleStatus = 'initializing';
  private logger: Logger;
  private adapter!: DatabaseAdapter;

  constructor(logger: Logger) {
    this.logger = logger.child({ module: this.name });
  }

  get status(): ModuleStatus { return this._status; }

  async initialize(): Promise<void> {
    this.logger.info('Initializing analytics module');
    try {
      this.adapter = getAdminAdapter();
      this._status = 'ready';
      this.logger.info('Analytics module ready');
    } catch (err) {
      this.logger.error({ err }, 'Failed to initialize analytics module');
      this._status = 'error';
    }
  }

  async shutdown(): Promise<void> { this._status = 'stopped'; }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();

    handlers.set('analytics_summary', async (args) => {
      try {
        const topN = typeof args.top_n === 'number' ? args.top_n : 10;
        const summary = await this.buildSummary(topN);
        return { content: [{ type: 'text', text: JSON.stringify(summary, null, 2) }], isError: false };
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        this.logger.error({ err }, 'analytics_summary failed');
        return { content: [{ type: 'text', text: `Analytics unavailable: ${msg}` }], isError: true };
      }
    });

    handlers.set('quality_score', async (args) => {
      try {
        const entryId = String(args.entry_id || '');
        if (!entryId) {
          return { content: [{ type: 'text', text: 'Missing required argument: entry_id' }], isError: true };
        }
        const result = await this.computeQualityScore(entryId);
        if (!result) {
          return { content: [{ type: 'text', text: `Entry not found: ${entryId}` }], isError: true };
        }
        return { content: [{ type: 'text', text: JSON.stringify(result, null, 2) }], isError: false };
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        this.logger.error({ err, entry_id: args.entry_id }, 'quality_score failed');
        return { content: [{ type: 'text', text: `Quality score unavailable: ${msg}` }], isError: true };
      }
    });

    return handlers;
  }

  getToolDefinitions(): ToolDefinition[] {
    return [
      {
        name: 'analytics_summary',
        description: 'Get real analytics: total tool calls, top tools by usage, KB entry counts by scope, and recent error count.',
        inputSchema: {
          type: 'object',
          properties: { top_n: { type: 'number', description: 'Number of top tools to return (default 10)' } },
        },
        category: 'analytics',
      },
      {
        name: 'quality_score',
        description: 'Compute quality score (0–100) for a KB entry based on content length, tag count, summary presence, and recency.',
        inputSchema: {
          type: 'object',
          properties: { entry_id: { type: 'string', description: 'UUID of the knowledge entry' } },
          required: ['entry_id'],
        },
        category: 'analytics',
      },
    ];
  }

  // --- Private helpers ---

  /** Aggregate real usage data from mcp_tools and knowledge_entries tables. */
  private async buildSummary(topN: number): Promise<AnalyticsSummary> {
    const totalRow = await this.adapter.getAsync<{ total: number }>(
      'SELECT COALESCE(SUM(call_count), 0) as total FROM mcp_tools', [],
    );
    const totalCalls = totalRow?.total ?? 0;

    const uniqueRow = await this.adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM mcp_tools WHERE call_count > 0', [],
    );
    const uniqueTools = uniqueRow?.cnt ?? 0;

    const topRows = await this.adapter.allAsync<{ name: string; call_count: number }>(
      'SELECT name, call_count FROM mcp_tools ORDER BY call_count DESC LIMIT ?', [topN],
    );
    const topTools = topRows.map(r => ({ name: r.name, calls: r.call_count }));

    const kbRow = await this.adapter.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM knowledge_entries', [],
    );
    const kbEntries = kbRow?.cnt ?? 0;

    const scopeRows = await this.adapter.allAsync<{ scope: string; cnt: number }>(
      "SELECT COALESCE(scope, 'global') as scope, COUNT(*) as cnt FROM knowledge_entries GROUP BY scope", [],
    );
    const kbScopeCounts: Record<string, number> = {};
    for (const row of scopeRows) kbScopeCounts[row.scope] = row.cnt;

    const since = new Date(Date.now() - 86_400_000).toISOString();
    const errRow = await this.adapter.getAsync<{ cnt: number }>(
      "SELECT COUNT(*) as cnt FROM audit_log WHERE action LIKE '%error%' AND timestamp > ?", [since],
    );
    const recentErrors = errRow?.cnt ?? 0;

    return { totalCalls, uniqueTools, topTools, kbEntries, kbScopeCounts, recentErrors };
  }

  /** Compute a 0–100 quality score for a single KB entry. */
  private async computeQualityScore(entryId: string): Promise<QualityScore | null> {
    const row = await this.adapter.getAsync<{
      id: string; content: string; summary: string | null;
      tags: string | null; created_at: string | null;
    }>(
      'SELECT id, content, summary, tags, created_at FROM knowledge_entries WHERE id = ?',
      [entryId],
    );
    if (!row) return null;

    const contentLength = (row.content || '').length;
    const hasContent = contentLength > 50;
    const tagCount = row.tags ? row.tags.split(',').filter(Boolean).length : 0;
    const hasSummary = Boolean(row.summary && row.summary.length > 10);

    // Age score: full score within 30 days, decays to 0 at 365 days
    const ageMs = row.created_at ? Date.now() - new Date(row.created_at).getTime() : 0;
    const ageScore = Math.max(0, 1 - ageMs / (365 * 86_400_000));

    const score = Math.round(
      (hasContent ? 40 : 0) +
      Math.min(20, contentLength / 200) +
      Math.min(20, tagCount * 5) +
      (hasSummary ? 10 : 0) +
      ageScore * 10,
    );

    return {
      entry_id: entryId,
      score: Math.min(100, score),
      factors: {
        hasContent, contentLength, tagCount, hasSummary,
        ageScore: Math.round(ageScore * 100) / 100,
      },
    };
  }
}

/**
 * Code Intelligence Module — handles code_* tool operations.
 * SA4E-53: DatabaseManager only created for SQLite engine.
 * PostgreSQL uses resolveEngineAdapter directly — no SQLite file created.
 */

import type { IModule, ModuleStatus } from '../../types/module.js';
import type { ToolHandler, ToolDefinition } from '../../types/tool.js';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import type { Logger } from 'pino';
import { DatabaseManager } from '../../engine/db/database-manager.js';
import { IndexingEngine } from '../../engine/indexer/indexing-engine.js';
import { QueryLayer } from '../../engine/query/query-layer.js';
import { loadConfig } from '../../engine/config.js';
import { resolveEngineAdapter } from '../../database/factory/resolveEngineAdapter.js';
import { CODE_INTEL_TOOL_DEFINITIONS, dispatchCodeIntelTool } from '../../engine/tools/register-tools.js';
import { withErrorHandling, withTextResult } from '../../tool-router/ToolHandlerDecorators.js';
import { OnboardingService } from './onboarding/OnboardingService.js';
import { OnboardingToolHandler } from './onboarding/OnboardingToolHandler.js';
import { ONBOARDING_TOOL_DEFINITIONS } from './onboarding/definitions.js';

export class CodeIntelModule implements IModule {
  readonly name = 'codeIntel';
  private _status: ModuleStatus = 'initializing';
  private logger: Logger;
  /** Only set when engine is SQLite — null for PostgreSQL. */
  private dbManager: DatabaseManager | null = null;
  private indexer!: IndexingEngine;
  private workspace!: string;
  private queryLayer!: QueryLayer;
  private adapter!: DatabaseAdapter;
  private onboardingHandler!: OnboardingToolHandler;

  constructor(logger: Logger) {
    this.logger = logger.child({ module: this.name });
  }

  get status(): ModuleStatus { return this._status; }

  getIndexer(): IndexingEngine { return this.indexer; }

  async initialize(): Promise<void> {
    this.logger.info('Initializing code intelligence module');
    try {
      const config = loadConfig();
      this.workspace = config.workspace;

      // Resolve adapter — only opens SQLite file when engine is sqlite
      this.adapter = await resolveEngineAdapter(config.dataDir, config.dbPath);

      // For SQLite: also initialize DatabaseManager (runs schema migrations, WAL mode, etc.)
      // For PostgreSQL: schema is managed via scripts/run-migrations.ts
      if (this.adapter.getEngine() === 'sqlite') {
        this.dbManager = new DatabaseManager(config.dbPath, config.projectId);
        this.dbManager.initialize();
      }

      this.queryLayer = new QueryLayer(this.adapter);
      this.indexer = new IndexingEngine(this.adapter, config);
      this.indexer.startBackgroundIndexing();
      // SA4E-166: Initialize onboarding service
      const onboardingService = new OnboardingService(this.workspace, this.logger);
      this.onboardingHandler = new OnboardingToolHandler(onboardingService, this.logger);
      this._status = 'ready';
    } catch (error) {
      this.logger.error({ err: error }, 'Failed to initialize code intelligence module');
      this._status = 'error';
    }
  }

  async shutdown(): Promise<void> {
    this.logger.info('Shutting down code intelligence module');
    if (this.indexer) this.indexer.stop();
    if (this.dbManager) this.dbManager.close();
    this._status = 'stopped';
  }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();

    for (const def of CODE_INTEL_TOOL_DEFINITIONS) {
      const handler = withErrorHandling(this.logger, def.name)(
        withTextResult(
          async (args) => {
            const projectId = (args as Record<string, unknown>).__projectId as string | undefined;
            return dispatchCodeIntelTool(
              def.name, args,
              this.queryLayer, this.adapter, this.dbManager,
              this.indexer, this.workspace, projectId,
            );
          },
        ),
      );
      handlers.set(def.name, handler);
    }

    // SA4E-166: Register onboarding tool handlers
    for (const [name, handler] of this.onboardingHandler.getHandlers()) {
      handlers.set(name, withErrorHandling(this.logger, name)(handler));
    }

    return handlers;
  }

  getToolDefinitions(): ToolDefinition[] {
    const codeIntelDefs = CODE_INTEL_TOOL_DEFINITIONS.map(def => ({
      name: def.name,
      description: def.description,
      inputSchema: def.inputSchema as any,
      category: 'code' as const,
    }));
    return [...codeIntelDefs, ...ONBOARDING_TOOL_DEFINITIONS];
  }
}

/**
 * SA4E-51 — KB Graph Module.
 * Passes getAdminAdapter() to GraphService so graph_nodes/graph_edges
 * are stored in the active engine (SQLite or PostgreSQL), not hardcoded SQLite.
 */

import type { IModule, ModuleStatus } from '../../types/module.js';
import type { ToolHandler, ToolDefinition } from '../../types/tool.js';
import type { Logger } from 'pino';
import { getAdminAdapter } from '../../admin/db/core.js';
import { GraphService } from './service/index.js';

export class KBGraphModule implements IModule {
  readonly name = 'kbGraph';
  private _status: ModuleStatus = 'initializing';
  private readonly logger: Logger;
  private readonly graphService: GraphService;

  /**
   * @param logger - Pino logger; child logger scoped to module name is created internally
   */
  constructor(logger: Logger) {
    this.logger = logger.child({ module: this.name });
    // DIP: inject DatabaseAdapter so GraphService is engine-agnostic
    this.graphService = new GraphService(getAdminAdapter(), this.logger);
  }

  get status(): ModuleStatus { return this._status; }

  async initialize(): Promise<void> {
    this.logger.info('Initializing KB graph module');
    await this.graphService.initialize();
    // Expose globally for admin routes spatial endpoint
    (globalThis as any).__sqliteGraphService = this.graphService;
    this._status = 'ready';
  }

  async shutdown(): Promise<void> {
    this._status = 'stopped';
  }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();

    handlers.set('kb_graph_query', async (args) => {
      const query = args.query as string | undefined;
      const type = args.type as string | undefined;
      const tier = args.tier as string | undefined;
      const limit = (args.limit as number) || 20;
      const projectId = (args.project_id as string) || (args.__projectId as string) || undefined;

      try {
        const nodes = await this.graphService.searchNodes(query, type, tier, limit, projectId);
        const nodeIds = nodes.map(n => n.id);
        const edges = await this.graphService.getEdgesForNodeIds(nodeIds);
        return {
          content: [{ type: 'text', text: JSON.stringify({
            nodes, edges, query: query ?? null,
            stats: { nodeCount: nodes.length, edgeCount: edges.length },
          }) }],
          isError: false,
        };
      } catch (err: any) {
        this.logger.error({ err: err.message, query }, 'kb_graph_query failed');
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message, nodes: [], edges: [] }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_add_node', async (args) => {
      const label = args.label as string || args.title as string || '';
      const type = (args.type as string) || 'CONTEXT';
      const tier = (args.tier as string) || 'SHARED';
      const entryId = (args.entry_id as string) || `custom-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const projectId = (args.project_id as string) || '';

      try {
        const node = await this.graphService.addNode(entryId, label, type, tier, projectId);
        return {
          content: [{ type: 'text', text: JSON.stringify({ status: 'added', node }) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_add_edge', async (args) => {
      const source = args.source as string || args.from as string || '';
      const target = args.target as string || args.to as string || '';
      if (!source || !target) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: 'source and target are required' }) }],
          isError: true,
        };
      }
      const weight = (args.weight as number) ?? 0.5;
      const relType = (args.relation as string) || (args.rel_type as string) || 'RELATED_TO';

      try {
        await this.graphService.addEdge(source, target, weight, relType);
        return {
          content: [{ type: 'text', text: JSON.stringify({ status: 'added', source, target, relType }) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_community', async (args) => {
      const maxIterations = (args.max_iterations as number) || 20;
      const minClusterSize = (args.min_cluster_size as number) || 2;

      try {
        const communities = await this.graphService.detectCommunities(maxIterations, minClusterSize);
        return {
          content: [{ type: 'text', text: JSON.stringify({
            communities,
            totalClusters: communities.length,
            totalNodes: communities.reduce((s, c) => s + c.nodeCount, 0),
          }) }],
          isError: false,
        };
      } catch (err: any) {
        this.logger.error({ err: err.message }, 'kb_graph_community failed');
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message, communities: [] }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_pagerank', async (args) => {
      const topN = (args.top_n as number) || 20;
      const dampingFactor = (args.damping_factor as number) ?? 0.85;
      const maxIterations = (args.max_iterations as number) || 20;

      try {
        const ranked = await this.graphService.computePageRank(dampingFactor, maxIterations, 0.001, topN);
        return {
          content: [{ type: 'text', text: JSON.stringify({
            ranked,
            topN: ranked.length,
          }) }],
          isError: false,
        };
      } catch (err: any) {
        this.logger.error({ err: err.message }, 'kb_graph_pagerank failed');
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message, ranked: [] }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_merge', async (args) => {
      const projectIds = args.project_ids as string[] || [];
      try {
        const result = await this.graphService.mergeGraph(projectIds);
        return {
          content: [{ type: 'text', text: JSON.stringify(result) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_cross_sync', async (args) => {
      const source = args.source_project_id as string || '';
      const target = args.target_project_id as string || '';
      if (!source || !target) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: 'source_project_id and target_project_id are required' }) }],
          isError: true,
        };
      }
      try {
        const result = await this.graphService.crossSync(source, target);
        return {
          content: [{ type: 'text', text: JSON.stringify(result) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_remove_cross', async (args) => {
      const a = args.project_a as string || '';
      const b = args.project_b as string || '';
      if (!a || !b) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: 'project_a and project_b are required' }) }],
          isError: true,
        };
      }
      try {
        const result = await this.graphService.removeCrossEdges(a, b);
        return {
          content: [{ type: 'text', text: JSON.stringify(result) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    handlers.set('kb_graph_stats', async () => {
      try {
        const stats = await this.graphService.getGraphStats();
        return {
          content: [{ type: 'text', text: JSON.stringify(stats) }],
          isError: false,
        };
      } catch (err: any) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ error: err.message }) }],
          isError: true,
        };
      }
    });

    return handlers;
  }

  getToolDefinitions(): ToolDefinition[] {
    return [
      {
        name: 'kb_graph_query',
        description: 'Query the knowledge base graph — search by label, type, or tier',
        inputSchema: {
          type: 'object',
          properties: {
            query: { type: 'string', description: 'Fuzzy search label or entry_id' },
            type: { type: 'string', description: 'Filter by node type (FUNCTION, CLASS, DOCUMENT, etc.)' },
            tier: { type: 'string', description: 'Filter by tier (CODE, SHARED, etc.)' },
            limit: { type: 'number', description: 'Max results (default 20)' },
            project_id: { type: 'string' },
          },
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_add_node',
        description: 'Add a node to the KB graph — auto-creates position and type/tier edges',
        inputSchema: {
          type: 'object',
          properties: {
            label: { type: 'string', description: 'Display label (max 50 chars)' },
            type: { type: 'string', description: 'Node type (CLASS, FUNCTION, DOCUMENT, CONTEXT, etc.)' },
            tier: { type: 'string', description: 'Tier (SHARED, CODE, etc.)' },
            entry_id: { type: 'string', description: 'Unique ID (auto-generated if omitted)' },
            project_id: { type: 'string' },
          },
          required: ['label'],
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_add_edge',
        description: 'Add an edge between KB graph nodes',
        inputSchema: {
          type: 'object',
          properties: {
            source: { type: 'string', description: 'Source node entry_id' },
            target: { type: 'string', description: 'Target node entry_id' },
            relation: { type: 'string', description: 'Relationship label (default: RELATED_TO)' },
            weight: { type: 'number', description: 'Edge strength 0-1 (default 0.5)' },
          },
          required: ['source', 'target'],
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_community',
        description: 'Detect communities/clusters in the KB graph using label propagation. Returns groups of densely connected nodes.',
        inputSchema: {
          type: 'object',
          properties: {
            max_iterations: { type: 'number', description: 'Max label propagation passes (default 20)' },
            min_cluster_size: { type: 'number', description: 'Minimum nodes per cluster (default 2)' },
          },
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_pagerank',
        description: 'Compute PageRank scores for all graph nodes. Returns top-N nodes ranked by importance.',
        inputSchema: {
          type: 'object',
          properties: {
            top_n: { type: 'number', description: 'Return top N nodes (default 20, 0 = all)' },
            damping_factor: { type: 'number', description: 'Probability of following edges (default 0.85)' },
            max_iterations: { type: 'number', description: 'Max iterations (default 20)' },
          },
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_merge',
        description: 'Multi-agent graph merge — combine nodes/edges from multiple projects. Returns merged view with conflict detection.',
        inputSchema: {
          type: 'object',
          properties: {
            project_ids: { type: 'array', items: { type: 'string' }, description: 'Project IDs to merge' },
          },
          required: ['project_ids'],
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_cross_sync',
        description: 'Cross-tenant sync — create CROSS_TENANT edges between matching nodes across two projects.',
        inputSchema: {
          type: 'object',
          properties: {
            source_project_id: { type: 'string', description: 'Source project ID' },
            target_project_id: { type: 'string', description: 'Target project ID' },
          },
          required: ['source_project_id', 'target_project_id'],
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_remove_cross',
        description: 'Remove all CROSS_TENANT edges between two projects.',
        inputSchema: {
          type: 'object',
          properties: {
            project_a: { type: 'string', description: 'First project ID' },
            project_b: { type: 'string', description: 'Second project ID' },
          },
          required: ['project_a', 'project_b'],
        },
        category: 'kb-graph',
      },
      {
        name: 'kb_graph_stats',
        description: 'Get KB graph summary statistics: node/edge count, density, type distribution.',
        inputSchema: { type: 'object', properties: {} },
        category: 'kb-graph',
      },
    ];
  }
}

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import Database from 'better-sqlite3';
import { SqliteDbAdapter } from '../../memory/task-queue/SqliteDbAdapter.js';
import { GraphService } from '../service/index.js';
import { KBGraphModule } from '../KBGraphModule.js';
import pino from 'pino';

const GRAPH_SCHEMA = `
CREATE TABLE IF NOT EXISTS graph_nodes (
  entry_id TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL DEFAULT 'DOCUMENT', tier TEXT NOT NULL DEFAULT 'SHARED',
  project_id TEXT NOT NULL DEFAULT '',
  x REAL NOT NULL DEFAULT 0, y REAL NOT NULL DEFAULT 0, z REAL NOT NULL DEFAULT 0,
  level INTEGER NOT NULL DEFAULT 2, cluster_id TEXT DEFAULT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS graph_edges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL, target TEXT NOT NULL,
  weight REAL NOT NULL DEFAULT 0.5, rel_type TEXT NOT NULL DEFAULT 'RELATED_TO',
  UNIQUE(source, target)
);
`;

const log = pino({ level: 'silent' }) as any;

describe('KBGraphModule handlers', () => {
  let db: Database.Database;
  let adapter: SqliteDbAdapter;
  let module: KBGraphModule;

  beforeEach(() => {
    db = new Database(':memory:');
    db.exec(GRAPH_SCHEMA);
    adapter = new SqliteDbAdapter(db);
    // Override internal GraphService to use test adapter
    const svc = new GraphService(adapter as any, log);
    module = new (class extends KBGraphModule {
      constructor() {
        super(log);
        (this as any).graphService = svc;
      }
      async initialize() { (this as any)._status = 'ready'; }
    })();
  });

  afterEach(() => db.close());

  it('kb_graph_stats returns zeros on empty graph', async () => {
    const handlers = module.getToolHandlers();
    const handler = handlers.get('kb_graph_stats')!;
    const result = await handler({});
    expect(result.isError).toBe(false);
    const data = JSON.parse(result.content[0].text as string);
    expect(data.nodeCount).toBe(0);
    expect(data.edgeCount).toBe(0);
  });

  it('kb_graph_stats returns correct counts', async () => {
    db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
      VALUES ('n1', 'Node1', 'CLASS', 'CODE', '', 0, 0, 0, 0)`).run();
    db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
      VALUES ('n2', 'Node2', 'FUNCTION', 'CODE', '', 0, 0, 0, 0)`).run();
    db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('n1', 'n2', 0.5)`).run();

    const handlers = module.getToolHandlers();
    const result = await handlers.get('kb_graph_stats')!({});
    const data = JSON.parse(result.content[0].text as string);
    expect(data.nodeCount).toBe(2);
    expect(data.edgeCount).toBe(1);
    expect(data.typeDistribution).toEqual({ CLASS: 1, FUNCTION: 1 });
  });

  it('kb_graph_query finds nodes by query', async () => {
    db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
      VALUES ('n1', 'HelloWorld', 'FUNCTION', 'CODE', '', 0, 0, 0, 0)`).run();
    db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
