  it('detects label conflicts across projects', async () => {
    db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
      VALUES ('n1', 'SameLabel', 'CLASS', 'CODE', 'proj1', 0, 0, 0, 0)`).run();
