import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import Database from 'better-sqlite3';
import { SqliteDbAdapter } from '../../../memory/task-queue/SqliteDbAdapter.js';
import { GraphService } from '../index.js';
import pino from 'pino';

const GRAPH_SCHEMA = `
CREATE TABLE IF NOT EXISTS graph_nodes (
  entry_id TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL DEFAULT 'DOCUMENT', tier TEXT NOT NULL DEFAULT 'SHARED',
  project_id TEXT NOT NULL DEFAULT '',
  x REAL NOT NULL DEFAULT 0, y REAL NOT NULL DEFAULT 0, z REAL NOT NULL DEFAULT 0,
  level INTEGER NOT NULL DEFAULT 2, cluster_id TEXT DEFAULT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS graph_edges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL, target TEXT NOT NULL,
  weight REAL NOT NULL DEFAULT 0.5, rel_type TEXT NOT NULL DEFAULT 'RELATED_TO',
  UNIQUE(source, target)
);
`;

const log = pino({ level: 'silent' });

describe('GraphService', () => {
  let db: Database.Database;
  let adapter: SqliteDbAdapter;
  let svc: GraphService;

  beforeEach(() => {
    db = new Database(':memory:');
    db.exec(GRAPH_SCHEMA);
    adapter = new SqliteDbAdapter(db);
    svc = new GraphService(adapter as any, log);
  });

  afterEach(() => db.close());

  describe('searchNodes', () => {
    beforeEach(() => {
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('n1', 'Alpha', 'FUNCTION', 'CODE', 'p1', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('n2', 'Beta', 'CLASS', 'CODE', 'p1', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('n3', 'Gamma', 'DOCUMENT', 'SHARED', 'p2', 0, 0, 0, 0)`).run();
    });

    it('returns all nodes when no filters', async () => {
      const nodes = await svc.searchNodes();
      expect(nodes).toHaveLength(3);
    });

    it('filters by query (label LIKE)', async () => {
      const nodes = await svc.searchNodes('Alpha');
      expect(nodes).toHaveLength(1);
      expect(nodes[0].id).toBe('n1');
    });

    it('filters by type', async () => {
      const nodes = await svc.searchNodes(undefined, 'CLASS');
      expect(nodes).toHaveLength(1);
      expect(nodes[0].id).toBe('n2');
    });

    it('filters by tier', async () => {
      const nodes = await svc.searchNodes(undefined, undefined, 'SHARED');
      expect(nodes).toHaveLength(1);
      expect(nodes[0].id).toBe('n3');
    });

    it('respects limit', async () => {
      const nodes = await svc.searchNodes(undefined, undefined, undefined, 1);
      expect(nodes).toHaveLength(1);
    });
  });

  describe('getEdgesForNodeIds', () => {
    beforeEach(() => {
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('a', 'A', 'TYPE', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('b', 'B', 'TYPE', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('c', 'C', 'TYPE', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight, rel_type) VALUES ('a', 'b', 0.8, 'RELATED_TO')`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight, rel_type) VALUES ('b', 'c', 0.5, 'RELATED_TO')`).run();
    });

    it('returns edges where either endpoint matches', async () => {
      const edges = await svc.getEdgesForNodeIds(['a', 'b']);
      expect(edges).toHaveLength(2);
    });

    it('returns empty for unknown ids', async () => {
      const edges = await svc.getEdgesForNodeIds(['x']);
      expect(edges).toEqual([]);
    });
  });

  describe('detectCommunities', () => {
    it('returns empty when no edges', async () => {
      const communities = await svc.detectCommunities();
      expect(communities).toEqual([]);
    });

    it('detects a single community from connected nodes', async () => {
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('a', 'A', 'TYPE', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('b', 'B', 'TYPE', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('a', 'b', 1.0)`).run();
      const communities = await svc.detectCommunities(10, 2);
      expect(communities).toHaveLength(1);
      expect(communities[0].nodeCount).toBe(2);
    });
  });

  describe('computePageRank', () => {
    it('returns empty when no edges', async () => {
      const ranked = await svc.computePageRank();
      expect(ranked).toEqual([]);
    });

    it('ranks nodes by connectivity', async () => {
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('hub', 'Hub', 'CLASS', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('a', 'A', 'CLASS', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('b', 'B', 'CLASS', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('hub', 'a', 1.0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('hub', 'b', 1.0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('a', 'b', 0.5)`).run();

      const ranked = await svc.computePageRank(0.85, 20, 0.001, 3);
      expect(ranked).toHaveLength(3);
      // 'b' has 2 incoming edges (hub→b, a→b) vs hub has 0, so 'b' ranks highest
      expect(ranked[0].nodeId).toBe('b');
    });
  });

  describe('getGraphStats', () => {
    it('returns zero counts on empty graph', async () => {
      const stats = await svc.getGraphStats();
      expect(stats.nodeCount).toBe(0);
      expect(stats.edgeCount).toBe(0);
      expect(stats.density).toBe(0);
      expect(stats.typeDistribution).toEqual({});
    });

    it('returns correct counts and density', async () => {
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('a', 'A', 'FUNCTION', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level)
        VALUES ('b', 'B', 'CLASS', 'CODE', '', 0, 0, 0, 0)`).run();
      db.prepare(`INSERT INTO graph_edges (source, target, weight) VALUES ('a', 'b', 1.0)`).run();

      const stats = await svc.getGraphStats();
      expect(stats.nodeCount).toBe(2);
      expect(stats.edgeCount).toBe(1);
      expect(stats.density).toBeGreaterThan(0);
      expect(stats.typeDistribution.FUNCTION).toBe(1);
      expect(stats.typeDistribution.CLASS).toBe(1);
    });
  });
});

/**
 * SA4E-51 — GraphService: KB Graph operations backed by DatabaseAdapter.
 * SA4E-53: updated to async API for PostgreSQL compatibility.
 * Replaces the previous SqliteGraphService which used getAdminDb() directly.
 * Constructor accepts a DatabaseAdapter (injected by KBGraphModule) so the
 * correct engine is used at runtime.
 */

import type { Logger } from 'pino';
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import type { SpatialQueryParams, SpatialGraphResult, GraphNode } from './constants.js';
import { getKbEntryCount } from '../../../admin/admin-db.js';

export type { GraphNode, GraphEdge, SpatialQueryParams, SpatialGraphResult } from './constants.js';
export { LEVEL_MAP, KIND_TO_TYPE } from './constants.js';
export * from './nodes.js';
export * from './spatial.js';
export * from './sync.js';

import * as nodes from './nodes.js';
import * as sync from './sync.js';
import * as spatial from './spatial.js';

/**
 * Facade over KB Graph helpers — all writes go through the injected adapter.
 * Rename: GraphService (alias SqliteGraphService kept for backward compat).
 */
export class GraphService {
  private readonly db: DatabaseAdapter;
  private readonly logger: Logger;
  private _ready = false;

  /**
   * @param db - DatabaseAdapter for graph_nodes / graph_edges
   * @param logger - Pino logger
   */
  constructor(db: DatabaseAdapter, logger: Logger) {
    this.db = db;
    this.logger = logger.child({ service: 'graph-service' });
  }

  get ready(): boolean { return this._ready; }

  /** Initialise: count existing nodes and trigger full sync if empty. SA4E-53: async. */
  async initialize(): Promise<void> {
    const graphCount = await nodes.getNodeCount(this.db);
    this._ready = true;
    if (graphCount === 0) {
      const kbCount = await getKbEntryCount();
      if (kbCount > 0) {
        // KB has entries but graph is empty — sync immediately
        this.logger.info({ kbCount }, 'Graph empty but KB has entries — starting full sync');
        await this.fullSync();
      } else {
        // Both empty at startup — schedule a delayed sync to catch documents indexed after startup
        this.logger.info('Graph and KB both empty at startup — scheduling delayed sync in 60s');
        setTimeout(() => {
          this.fullSync().catch(err =>
            this.logger.warn({ err }, 'Delayed graph sync failed'),
          );
        }, 60_000);
      }
    } else {
      this.logger.info({ existingNodes: graphCount }, 'Graph service ready');
    }
  }

  /**
   * Full sync from KB entries + code symbols.
   * @returns Counts of nodes and edges created plus breakdown by source type
   */
  async fullSync(): Promise<{ nodesCreated: number; edgesCreated: number; sources: Record<string, number> }> {
    const result = await sync.fullSync(this.db, this.logger);
    this._ready = true;
    return result;
  }

  /** @returns Current node count, optionally scoped to a project. SA4E-53: async. */
  async getNodeCount(projectId?: string): Promise<number> {
    return nodes.getNodeCount(this.db, projectId);
  }

  /**
   * Add a node; no-op if entry already exists. SA4E-53: async.
   * @returns The inserted or existing node
   */
  async addNode(entryId: string, label: string, type: string, tier: string, projectId = ''): Promise<GraphNode> {
    return nodes.addNode(entryId, label, type, tier, this.db, this.logger, projectId);
  }

  /** Remove a node and all its incident edges. SA4E-53: async. */
  async removeNode(entryId: string): Promise<void> {
    return nodes.removeNode(entryId, this.db);
  }

  /** @returns Node by ID or null. SA4E-53: async. */
  async getNode(entryId: string): Promise<GraphNode | null> {
    return nodes.getNode(entryId, this.db, this.logger);
  }

  /**
   * Insert a direct graph edge between two nodes. SA4E-53: async.
   * @param weight - Edge strength [0,1]
   * @param relType - Relationship label
   */
  async addEdge(source: string, target: string, weight = 0.5, relType = 'RELATED_TO'): Promise<void> {
    await this.db.runAsync(
      'INSERT INTO graph_edges (source, target, weight, rel_type) VALUES (?, ?, ?, ?) ON CONFLICT (source, target) DO NOTHING',
      [source, target, weight, relType],
    );
  }

  /** @returns All node positions (lightweight for 3D viewport load). SA4E-53: async. */
  async getAllPositions(projectId?: string) {
    return spatial.getAllPositions(this.db, projectId);
  }

  /** @returns Nodes + edges for current camera frustum. SA4E-53: async. */
  async spatialQuery(params: SpatialQueryParams, projectId?: string): Promise<SpatialGraphResult> {
    return spatial.spatialQuery(params, this.db, this.logger, projectId);
  }

  /**
   * Sync a pre-prepared entry list into the graph.
   * @param entries - Node descriptors to upsert
   * @param projectId - Default project ID
   */
  async syncFromEntries(
    entries: Array<{ id: string; label: string; type: string; tier: string; groupId?: number; projectId?: string }>,
    projectId = '',
  ): Promise<{ nodesCreated: number; edgesCreated: number }> {
    return await sync.syncFromEntries(entries, this.db, this.logger, projectId);
  }

  /** Compute Fibonacci-sphere position for a node by current graph state. SA4E-53: async. */
  async computePosition(index: number, type: string) {
    return nodes.computePosition(index, type, this.db);
  }

  /** Compute position by explicit group/count parameters (no DB reads). */
  computePositionByIndex(i: number, total: number, type: string, groupId: number, groupCount: number) {
    return nodes.computePositionByIndex(i, total, type, groupId, groupCount);
  }

  /** Trigger neighbourhood edge creation for an existing node. SA4E-53: async. */
  async autoCreateEdges(entryId: string, type: string, tier: string, projectId = ''): Promise<void> {
    return nodes.autoCreateEdges(entryId, type, tier, this.db, projectId);
  }

  /** Map a raw DB row to a typed GraphNode. */
  rowToNode(row: any): GraphNode {
    return nodes.rowToNode(row);
  }

  /** Search graph_nodes by label, type, or tier. SA4E-53: async. */
  async searchNodes(
    query?: string, type?: string, tier?: string,
    limit = 20, projectId?: string,
  ): Promise<GraphNode[]> {
    const clauses: string[] = [];
    const params: unknown[] = [];

    if (query) {
      clauses.push('(label LIKE ? OR entry_id LIKE ?)');
      params.push(`%${query}%`, `%${query}%`);
    }
    if (type) {
      clauses.push('type = ?');
      params.push(type.toUpperCase());
    }
    if (tier) {
      clauses.push('tier = ?');
      params.push(tier);
    }
    if (projectId) {
      clauses.push('project_id = ?');
      params.push(projectId);
    }

    const where = clauses.length > 0 ? `WHERE ${clauses.join(' AND ')}` : '';
    const rows = await this.db.allAsync<any>(
      `SELECT * FROM graph_nodes ${where} ORDER BY label ASC LIMIT ?`,
      [...params, limit],
    );
    return rows.map(nodes.rowToNode);
  }

  /** Get edges where either endpoint is in the given node ID set. */
  async getEdgesForNodeIds(
    ids: string[], limit = 200,
  ): Promise<Array<{ source: string; target: string; weight: number; type: string }>> {
    if (ids.length === 0) return [];
    const placeholders = ids.map(() => '?').join(',');
    const rows = await this.db.allAsync<any>(
      `SELECT source, target, weight, rel_type FROM graph_edges
       WHERE source IN (${placeholders}) OR target IN (${placeholders}) LIMIT ?`,
      [...ids, ...ids, limit],
    );
    return rows.map(r => ({ source: r.source, target: r.target, weight: r.weight, type: r.rel_type }));
  }

  /** Load all edges from the graph into memory. */
  private async loadAllEdges(): Promise<Array<{ source: string; target: string; weight: number }>> {
    return this.db.allAsync<any>(
      'SELECT source, target, weight FROM graph_edges', [],
    ).then(rows => rows.map(r => ({ source: r.source, target: r.target, weight: r.weight })));
  }

  /**
   * Community detection via label propagation.
   * Returns clusters (community -> node IDs) sorted by size descending.
   * @param maxIterations - Max label propagation passes (default 20)
   * @param minClusterSize - Minimum nodes per cluster in output (default 2)
   */
  async detectCommunities(
    maxIterations = 20, minClusterSize = 2,
  ): Promise<Array<{ community: string; nodeCount: number; nodeIds: string[]; avgWeight: number }>> {
    const edges = await this.loadAllEdges();
    if (edges.length === 0) return [];

    const nodeSet = new Set<string>();
    const adjacency = new Map<string, Map<string, number>>();
    for (const e of edges) {
      nodeSet.add(e.source); nodeSet.add(e.target);
      if (!adjacency.has(e.source)) adjacency.set(e.source, new Map());
      if (!adjacency.has(e.target)) adjacency.set(e.target, new Map());
      adjacency.get(e.source)!.set(e.target, (adjacency.get(e.source)!.get(e.target) || 0) + e.weight);
      adjacency.get(e.target)!.set(e.source, (adjacency.get(e.target)!.get(e.source) || 0) + e.weight);
    }

    const nodes = Array.from(nodeSet);
    const labels = new Map<string, string>();
    for (const n of nodes) labels.set(n, n);

    for (let iter = 0; iter < maxIterations; iter++) {
      let changed = 0;
      for (const n of nodes) {
        const neighbors = adjacency.get(n);
        if (!neighbors || neighbors.size === 0) continue;
        const freq = new Map<string, number>();
        for (const [neighbor, w] of neighbors) {
          const lbl = labels.get(neighbor)!;
          freq.set(lbl, (freq.get(lbl) || 0) + w);
        }
        let bestLabel = labels.get(n)!;
        let bestCount = 0;
        for (const [lbl, count] of freq) {
          if (count > bestCount) { bestCount = count; bestLabel = lbl; }
        }
        if (bestLabel !== labels.get(n)) { labels.set(n, bestLabel); changed++; }
      }
      if (changed === 0) break;
    }

    const communities = new Map<string, { nodeIds: string[]; totalWeight: number; edgeCount: number }>();
    for (const n of nodes) {
      const lbl = labels.get(n)!;
      if (!communities.has(lbl)) communities.set(lbl, { nodeIds: [], totalWeight: 0, edgeCount: 0 });
      communities.get(lbl)!.nodeIds.push(n);
    }

    for (const e of edges) {
      const sl = labels.get(e.source);
      const tl = labels.get(e.target);
      if (sl && tl && sl === tl) {
        const c = communities.get(sl)!;
        c.totalWeight += e.weight;
        c.edgeCount++;
      }
    }

    return Array.from(communities.entries())
      .filter(([, c]) => c.nodeIds.length >= minClusterSize)
      .map(([community, c]) => ({
        community,
        nodeCount: c.nodeIds.length,
        nodeIds: c.nodeIds,
        avgWeight: c.edgeCount > 0 ? Math.round((c.totalWeight / c.edgeCount) * 100) / 100 : 0,
      }))
      .sort((a, b) => b.nodeCount - a.nodeCount);
  }

  /**
   * Simplified PageRank — iterative rank propagation over graph edges.
   * @param dampingFactor - Probability of following an edge vs teleporting (default 0.85)
   * @param maxIterations - Max iterations (default 20)
   * @param convergence - Stop when max rank change < this (default 0.001)
   * @param topN - Return only top-N nodes (default 20, 0 = all)
   */
  async computePageRank(
    dampingFactor = 0.85, maxIterations = 20, convergence = 0.001, topN = 20,
  ): Promise<Array<{ nodeId: string; rank: number; label: string; type: string }>> {
    const edges = await this.loadAllEdges();
    if (edges.length === 0) return [];

    const outDegree = new Map<string, number>();
    const inLinks = new Map<string, Map<string, number>>();
    const nodeSet = new Set<string>();

    for (const e of edges) {
      nodeSet.add(e.source); nodeSet.add(e.target);
      outDegree.set(e.source, (outDegree.get(e.source) || 0) + 1);
      if (!inLinks.has(e.target)) inLinks.set(e.target, new Map());
      inLinks.get(e.target)!.set(e.source, e.weight);
    }

    const nodes = Array.from(nodeSet);
    const N = nodes.length;
    const rank = new Map<string, number>();
    const teleport = (1 - dampingFactor) / N;

    for (const n of nodes) rank.set(n, 1 / N);

    for (let iter = 0; iter < maxIterations; iter++) {
      const newRank = new Map<string, number>();
      let maxDelta = 0;

      for (const n of nodes) {
        let sum = 0;
        const incoming = inLinks.get(n);
        if (incoming) {
          for (const [source, weight] of incoming) {
            const deg = outDegree.get(source) || 1;
            sum += (rank.get(source) || 0) * (weight / deg);
          }
        }
        const pr = teleport + dampingFactor * sum;
        newRank.set(n, pr);
        maxDelta = Math.max(maxDelta, Math.abs(pr - (rank.get(n) || 0)));
      }

      for (const [n, pr] of newRank) rank.set(n, pr);
      if (maxDelta < convergence) break;
    }

    const nodeRows = await this.db.allAsync<any>(
      'SELECT entry_id, label, type FROM graph_nodes', [],
    );
    const nodeMeta = new Map<string, { label: string; type: string }>();
    for (const r of nodeRows) nodeMeta.set(r.entry_id, { label: r.label, type: r.type });

    const ranked = Array.from(rank.entries())
      .map(([nodeId, pr]) => {
        const meta = nodeMeta.get(nodeId) || { label: nodeId, type: 'UNKNOWN' };
        return { nodeId, rank: Math.round(pr * 100000) / 100000, label: meta.label, type: meta.type };
      })
      .sort((a, b) => b.rank - a.rank);

    return topN > 0 ? ranked.slice(0, topN) : ranked;
  }

  /** Get graph summary statistics. */
  async getGraphStats(): Promise<{
    nodeCount: number; edgeCount: number; density: number;
    typeDistribution: Record<string, number>;
  }> {
    const nodeRow = await this.db.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM graph_nodes');
    const edgeRow = await this.db.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM graph_edges');
    const nodeCount = nodeRow?.cnt ?? 0;
    const edgeCount = edgeRow?.cnt ?? 0;
    const density = nodeCount > 1
      ? Math.round((edgeCount / (nodeCount * (nodeCount - 1) / 2)) * 100000) / 100000
      : 0;

    const typeRows = await this.db.allAsync<{ type: string; cnt: number }>(
      'SELECT type, COUNT(*) as cnt FROM graph_nodes GROUP BY type ORDER BY cnt DESC',
    );
    const typeDistribution: Record<string, number> = {};
    for (const r of typeRows) typeDistribution[r.type] = r.cnt;

    return { nodeCount, edgeCount, density, typeDistribution };
  }

  /**
   * Multi-agent graph merge — combine nodes/edges from multiple projects.
   * Returns a read-only merged graph view with conflict resolution notes.
   */
  async mergeGraph(
    projectIds: string[],
  ): Promise<{
    nodes: Array<any>;
    edges: Array<any>;
    stats: { totalNodes: number; totalEdges: number; projectCount: number; conflicts: number };
  }> {
    if (projectIds.length === 0) return { nodes: [], edges: [], stats: { totalNodes: 0, totalEdges: 0, projectCount: 0, conflicts: 0 } };

    const placeholders = projectIds.map(() => '?').join(',');
    const nodes = await this.db.allAsync<any>(
      `SELECT * FROM graph_nodes WHERE project_id IN (${placeholders}) ORDER BY label ASC`,
      projectIds,
    );

    const nodeIds = nodes.map((n: any) => n.entry_id);
    if (nodeIds.length === 0) {
      return { nodes: [], edges: [], stats: { totalNodes: 0, totalEdges: 0, projectCount: projectIds.length, conflicts: 0 } };
    }
    const edgePlaceholders = nodeIds.map(() => '?').join(',');
    const edges = await this.db.allAsync<any>(
      `SELECT * FROM graph_edges WHERE source IN (${edgePlaceholders}) OR target IN (${edgePlaceholders})`,
      [...nodeIds, ...nodeIds],
    );

    const labelProjects = new Map<string, Set<string>>();
    const conflicts = new Set<string>();
    for (const n of nodes) {
      if (!labelProjects.has(n.label)) labelProjects.set(n.label, new Set());
      labelProjects.get(n.label)!.add(n.project_id || '');
      if (labelProjects.get(n.label)!.size > 1) conflicts.add(n.label);
    }

    return {
      nodes: nodes.map((n: any) => this.rowToNode(n)),
      edges: edges.map((r: any) => ({ source: r.source, target: r.target, weight: r.weight, type: r.rel_type })),
      stats: {
        totalNodes: nodes.length,
        totalEdges: edges.length,
        projectCount: projectIds.length,
        conflicts: conflicts.size,
      },
    };
  }

  /**
   * Cross-tenant sync — create edges between matching nodes across two projects.
   */
  async crossSync(
    sourceProjectId: string,
    targetProjectId: string,
  ): Promise<{ edgesCreated: number; matches: number; sourceNodes: number; targetNodes: number }> {
    const sourceNodes = await this.db.allAsync<any>(
      'SELECT * FROM graph_nodes WHERE project_id = ?', [sourceProjectId],
    );
    const targetNodes = await this.db.allAsync<any>(
      'SELECT * FROM graph_nodes WHERE project_id = ?', [targetProjectId],
    );

    if (sourceNodes.length === 0 || targetNodes.length === 0) {
      return { edgesCreated: 0, matches: 0, sourceNodes: sourceNodes.length, targetNodes: targetNodes.length };
    }

    const targetByLabel = new Map<string, any[]>();
    for (const tn of targetNodes) {
      const key = tn.label.toLowerCase();
      if (!targetByLabel.has(key)) targetByLabel.set(key, []);
      targetByLabel.get(key)!.push(tn);
    }

    let edgesCreated = 0;
    let matches = 0;

    for (const sn of sourceNodes) {
      const key = sn.label.toLowerCase();
      const matches_target = targetByLabel.get(key);
      if (!matches_target) continue;
      for (const tn of matches_target) {
        if (sn.entry_id === tn.entry_id) continue;
        matches++;
        try {
          await this.db.runAsync(
            'INSERT INTO graph_edges (source, target, weight, rel_type) VALUES (?, ?, ?, ?) ON CONFLICT (source, target) DO NOTHING',
            [sn.entry_id, tn.entry_id, 0.8, 'CROSS_TENANT'],
          );
          edgesCreated++;
        } catch (err) { this.logger.debug({ err }, '[kb-graph] Cross-tenant edge insert failed (non-fatal)'); }
      }
    }

    return { edgesCreated, matches, sourceNodes: sourceNodes.length, targetNodes: targetNodes.length };
  }

  /**
   * Remove all cross-tenant edges between two projects.
   */
  async removeCrossEdges(projectIdA: string, projectIdB: string): Promise<{ removed: number }> {
    const aNodes = await this.db.allAsync<any>(
      'SELECT entry_id FROM graph_nodes WHERE project_id = ?', [projectIdA],
    );
    const bNodes = await this.db.allAsync<any>(
      'SELECT entry_id FROM graph_nodes WHERE project_id = ?', [projectIdB],
    );
    const aIds = aNodes.map((n: any) => n.entry_id);
    const bIds = bNodes.map((n: any) => n.entry_id);
    if (aIds.length === 0 || bIds.length === 0) return { removed: 0 };

    const aPH = aIds.map(() => '?').join(',');
    const bPH = bIds.map(() => '?').join(',');

    const result = await this.db.runAsync(
      `DELETE FROM graph_edges WHERE rel_type = 'CROSS_TENANT'
       AND ((source IN (${aPH}) AND target IN (${bPH})) OR (source IN (${bPH}) AND target IN (${aPH})))`,
      [...aIds, ...bIds, ...bIds, ...aIds],
    );
    return { removed: typeof result === 'object' && result !== null && 'changes' in result ? (result as any).changes : 0 };
  }
}

// Backward-compat alias — existing code that imports SqliteGraphService still compiles
export { GraphService as SqliteGraphService };

/**
 * SA4E-51 — Node CRUD operations and position math for KB Graph.
 * SA4E-53: converted to async API for PostgreSQL compatibility.
 * Uses DatabaseAdapter instead of raw Database.Database so graph_nodes/graph_edges
 * are written to whichever engine is active (SQLite or PostgreSQL).
 */

import type { Logger } from 'pino';
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import type { GraphNode } from './constants.js';
import { LEVEL_MAP } from './constants.js';

// Z-axis offset per node type — keeps layers visually separated in 3D space
const TYPE_Z_OFFSET: Record<string, number> = {
  REQUIREMENT: 0, ARCHITECTURE: 150, PROCEDURE: 300,
  CONTEXT: 50, DECISION: 200, DOCUMENT: 100,
  LESSON_LEARNED: -100, ERROR_PATTERN: -150,
  CLASS: 500, INTERFACE: 450, FUNCTION: 600, METHOD: 550,
  TYPE: 480, CONSTRUCTOR: 520, ENUM: 460, CONSTANT: 400, VARIABLE: 380,
  CODE_ENTITY: 470,
};

/**
 * Compute 3D position using Fibonacci sphere distribution.
 * Groups nodes by type into clusters on the sphere surface.
 * @param i - Index of this node within its group
 * @param total - Total node count (used for local spread radius)
 * @param type - Node type (determines Z offset layer)
 * @param groupId - Cluster index on the sphere
 * @param groupCount - Total number of clusters
 */
export function computePositionByIndex(
  i: number, total: number, type: string, groupId: number, groupCount: number,
) {
  const level = LEVEL_MAP[type.toUpperCase()] ?? 2;
  // Fibonacci sphere: distributes cluster centers evenly on sphere surface
  const golden = (1 + Math.sqrt(5)) / 2;
  const phi = Math.acos(1 - 2 * (groupId + 0.5) / Math.max(groupCount, 1));
  const theta_g = 2 * Math.PI * groupId / golden;
  const sphereRadius = 1200;
  const centerX = sphereRadius * Math.sin(phi) * Math.cos(theta_g);
  const centerY = sphereRadius * Math.sin(phi) * Math.sin(theta_g);
  const centerZ = sphereRadius * Math.cos(phi);
  const localSpread = 180;
  const theta_l = 2 * Math.PI * i / golden;
  const localR = Math.sqrt((i % 200) / 200) * localSpread;
  const zOffset = TYPE_Z_OFFSET[type.toUpperCase()] ?? level * 150;
  return {
    x: Math.round((centerX + localR * Math.cos(theta_l)) * 100) / 100,
    y: Math.round((centerY + localR * Math.sin(theta_l)) * 100) / 100,
    z: Math.round((centerZ + zOffset) * 100) / 100,
    level,
    clusterId: `cluster-${groupId}`,
  };
}

/**
 * Compute position for a new node by querying current graph state.
 * SA4E-53: async for PostgreSQL compatibility.
 * @param index - Insertion index (used for local spread)
 * @param type - Node type for Z-layer selection
 * @param db - DatabaseAdapter (reads graph_nodes)
 */
export async function computePosition(index: number, type: string, db: DatabaseAdapter) {
  const typeRows = await db.allAsync<{ type: string }>('SELECT DISTINCT type FROM graph_nodes', []);
  const groups = new Map<string, number>();
  let gc = 0;
  for (const r of typeRows) groups.set(r.type, gc++);
  if (!groups.has(type.toUpperCase())) groups.set(type.toUpperCase(), gc++);
  const countRow = await db.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM graph_nodes', []);
  const nodeCount = countRow?.cnt ?? 0;
  return computePositionByIndex(index, nodeCount + 1, type, groups.get(type.toUpperCase()) || 0, gc || 1);
}

/** Map a raw DB row to a typed GraphNode. */
export function rowToNode(row: any): GraphNode {
  return {
    id: row.entry_id, label: row.label, type: row.type, tier: row.tier,
    x: row.x, y: row.y, z: row.z, level: row.level, clusterId: row.cluster_id,
  };
}

/**
 * Fetch a single node by entry ID.
 * SA4E-53: async for PostgreSQL compatibility.
 * @returns GraphNode or null if not found
 */
export async function getNode(entryId: string, db: DatabaseAdapter, logger: Logger): Promise<GraphNode | null> {
  const row = await db.getAsync<any>('SELECT * FROM graph_nodes WHERE entry_id = ?', [entryId]);
  if (!row) return null;
  return rowToNode(row);
}

/**
 * Count nodes, optionally scoped to a project.
 * SA4E-53: async for PostgreSQL compatibility.
 * @param projectId - Optional project filter
 */
export async function getNodeCount(db: DatabaseAdapter, projectId?: string): Promise<number> {
  if (projectId) {
    const row = await db.getAsync<{ cnt: number }>(
      'SELECT COUNT(*) as cnt FROM graph_nodes WHERE project_id = ?', [projectId],
    );
    return row?.cnt ?? 0;
  }
  const row = await db.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM graph_nodes', []);
  return row?.cnt ?? 0;
}

/**
 * Insert a new node (or return existing) and auto-create type/tier edges.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function addNode(
  entryId: string, label: string, type: string, tier: string,
  db: DatabaseAdapter, logger: Logger, projectId = '',
): Promise<GraphNode> {
  const existing = await db.getAsync<{ entry_id: string }>(
    'SELECT entry_id FROM graph_nodes WHERE entry_id = ?', [entryId],
  );
  if (existing) return (await getNode(entryId, db, logger))!;
  const count = await getNodeCount(db);
  const pos = await computePosition(count, type, db);
  await db.runAsync(
    'INSERT INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level, cluster_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (entry_id) DO NOTHING',
    [entryId, label.substring(0, 50), type.toUpperCase(), tier, projectId, pos.x, pos.y, pos.z, pos.level, pos.clusterId],
  );
  await autoCreateEdges(entryId, type.toUpperCase(), tier, db, projectId);
  return { id: entryId, label, type: type.toUpperCase(), tier, ...pos };
}

/**
 * Remove a node and all its edges from the graph.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function removeNode(entryId: string, db: DatabaseAdapter): Promise<void> {
  await db.runAsync('DELETE FROM graph_edges WHERE source = ? OR target = ?', [entryId, entryId]);
  await db.runAsync('DELETE FROM graph_nodes WHERE entry_id = ?', [entryId]);
}

/**
 * Auto-create edges to similar-type and same-tier nodes (neighbourhood seeding).
 * Limits 3 TYPE_MATCH + 1 TIER_MATCH per new node to avoid edge explosion.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function autoCreateEdges(
  entryId: string, type: string, tier: string, db: DatabaseAdapter, projectId = '',
): Promise<void> {
  const projectFilter = projectId ? ' AND project_id = ?' : '';
  const projectArgs = projectId ? [projectId] : [];
  const typeNeighbours = await db.allAsync<{ entry_id: string }>(
    `SELECT entry_id FROM graph_nodes WHERE type = ? AND entry_id != ?${projectFilter} ORDER BY RANDOM() LIMIT 3`,
    [type, entryId, ...projectArgs],
  );
  for (const row of typeNeighbours) {
    await db.runAsync(
      'INSERT INTO graph_edges (source, target, weight, rel_type) VALUES (?, ?, ?, ?) ON CONFLICT (source, target) DO NOTHING',
      [entryId, row.entry_id, 0.6, 'TYPE_MATCH'],
    );
  }
  const tierNeighbours = await db.allAsync<{ entry_id: string }>(
    `SELECT entry_id FROM graph_nodes WHERE tier = ? AND type != ? AND entry_id != ?${projectFilter} ORDER BY RANDOM() LIMIT 1`,
    [tier, type, entryId, ...projectArgs],
  );
  for (const row of tierNeighbours) {
    await db.runAsync(
      'INSERT INTO graph_edges (source, target, weight, rel_type) VALUES (?, ?, ?, ?) ON CONFLICT (source, target) DO NOTHING',
      [entryId, row.entry_id, 0.4, 'TIER_MATCH'],
    );
  }
}

/**
 * SA4E-51 — Full sync and bulk node/edge creation for KB Graph.
 * SA4E-53: converted to async API for PostgreSQL compatibility.
 * Accepts DatabaseAdapter so writes go to the active engine (SQLite or PostgreSQL).
 * processCodeSymbols reads symbols via getIndexAdapter() — same engine as the indexer.
 */

import type { Logger } from 'pino';
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import { getKbEntries } from '../../../admin/admin-db.js';
import { getIndexAdapter } from '../../../admin/db/core.js';
import { loadConfig } from '../../../config/index.js';
import { KIND_TO_TYPE } from './constants.js';
import { computePositionByIndex } from './nodes.js';
import { buildSpatialEdges, buildCrossClusterEdges } from './spatial.js';

type EntryRow = { id: string; label: string; type: string; tier: string; groupId?: number; projectId?: string };

/**
 * Bulk-insert nodes into graph_nodes using position math.
 * SA4E-53: uses transactionAsync + runAsync for PostgreSQL compatibility.
 * @param entries - Flat list of nodes to upsert
 * @param db - DatabaseAdapter (write target)
 * @param projectId - Default project ID when entry has none
 * @returns Number of nodes inserted/replaced
 */
export async function insertAllNodes(entries: EntryRow[], db: DatabaseAdapter, projectId = ''): Promise<number> {
  const n = entries.length;
  const typeGroups = new Map<string, number>();
  let typeGroupCounter = 0;
  const totalGroups = Math.max(...entries.map(e => e.groupId ?? 0)) + 1 || 1;

  function resolveGroupId(e: EntryRow): number {
    if (e.groupId !== undefined) return e.groupId;
    const t = e.type.toUpperCase();
    if (!typeGroups.has(t)) typeGroups.set(t, typeGroupCounter++);
    return typeGroups.get(t)!;
  }

  let created = 0;
  const CHUNK = 5000; // Optimal batch for SQLite WAL throughput
  for (let start = 0; start < n; start += CHUNK) {
    const chunk = entries.slice(start, start + CHUNK);
    await db.transactionAsync(async () => {
      for (let ci = 0; ci < chunk.length; ci++) {
        const entry = chunk[ci];
        const type = entry.type.toUpperCase();
        const gId = resolveGroupId(entry);
        const pos = computePositionByIndex(start + ci, n, type, gId, totalGroups);
        await db.runAsync(
          'INSERT OR REPLACE INTO graph_nodes (entry_id, label, type, tier, project_id, x, y, z, level, cluster_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          [entry.id, entry.label.substring(0, 60), type, entry.tier, entry.projectId || projectId,
           pos.x, pos.y, pos.z, pos.level, pos.clusterId],
        );
        created++;
      }
    });
  }
  return created;
}

/**
 * Sync a prepared entry list into graph_nodes then rebuild spatial/cluster edges.
 * SA4E-53: async for PostgreSQL compatibility.
 * @param entries - Prepared node list
 * @param db - DatabaseAdapter (write target)
 * @param logger - Pino logger
 * @param projectId - Default project ID
 */
export async function syncFromEntries(
  entries: EntryRow[], db: DatabaseAdapter, logger: Logger, projectId = '',
): Promise<{ nodesCreated: number; edgesCreated: number }> {
  const nodesCreated = await insertAllNodes(entries, db, projectId);
  const spatialEdges = await buildSpatialEdges(db);
  const clusterEdges = await buildCrossClusterEdges(db);
  const edgesCreated = spatialEdges + clusterEdges;
  logger.info({ nodesCreated, edgesCreated }, 'syncFromEntries complete');
  return { nodesCreated, edgesCreated };
}

/** Collect KB document entries via the async getKbEntries API. */
async function processKbEntries(
  allEntries: EntryRow[], sources: Record<string, number>,
  ksaGroupMap: Map<string, number>, groupCounter: { value: number }, logger: Logger,
): Promise<void> {
  const serverProjectId = loadConfig().projectId;
  const docResult = await getKbEntries(1, 100000, 'created_at', 'desc', serverProjectId);

  function getKsaGroupId(source: string | null | undefined): number {
    if (!source) return 0;
    const m = source.match(/KSA-\d+/i);
    const key = m ? m[0].toUpperCase() : 'MISC';
    if (!ksaGroupMap.has(key)) ksaGroupMap.set(key, groupCounter.value++);
    return ksaGroupMap.get(key)!;
  }

  for (const entry of docResult.items) {
    const type = (entry.type || 'DOCUMENT').toUpperCase();
    const label = ((entry.summary || entry.tags || '').substring(0, 50)) ||
      (entry.source || '').split('/').pop() || `Doc ${entry.id}`;
    allEntries.push({
      id: `doc-${entry.id}`, label, type, tier: entry.tier || 'SHARED',
      groupId: getKsaGroupId(entry.source),
      projectId: entry.project_id || serverProjectId,
    });
    sources[type] = (sources[type] || 0) + 1;
  }
  logger.info({ count: docResult.items.length }, 'Collected knowledge entries');
}

/** Map one symbol row to an entry, grouping by source module. */
function processSymbolRow(
  sym: any, allEntries: EntryRow[], sources: Record<string, number>,
  ksaGroupMap: Map<string, number>, groupCounter: { value: number },
): void {
  const type = KIND_TO_TYPE[sym.kind] || 'CODE_ENTITY';
  const fileSuffix = sym.file_path ? sym.file_path.replace(/\\/g, '/').split('/').pop() || '' : '';
  const label = `${sym.name} (${fileSuffix})`.substring(0, 60);
  const fileParts = (sym.file_path || '').replace(/\\/g, '/').split('/');
  const srcIdx = fileParts.lastIndexOf('src');
  const module = srcIdx >= 0 && fileParts[srcIdx + 1] ? fileParts[srcIdx + 1] : 'code';
  const moduleKey = `MODULE-${module}`;
  if (!ksaGroupMap.has(moduleKey)) ksaGroupMap.set(moduleKey, groupCounter.value++);
  allEntries.push({
    id: `sym-${sym.id}`, label, type, tier: 'CODE',
    groupId: ksaGroupMap.get(moduleKey), projectId: loadConfig().projectId,
  });
  sources[type] = (sources[type] || 0) + 1;
}

/**
 * Read code symbols from the index adapter — same engine as the indexer.
/**
 * Read code symbols from the index adapter.
 * SA4E-53: converted to async for PostgreSQL compatibility.
 */
async function processCodeSymbols(
  allEntries: EntryRow[], sources: Record<string, number>,
  ksaGroupMap: Map<string, number>, groupCounter: { value: number }, logger: Logger,
): Promise<void> {
  try {
    const adapter = getIndexAdapter();
    const INCLUDE_KINDS = ['function', 'class', 'interface', 'method', 'type', 'enum', 'constructor'];
    const placeholders = INCLUDE_KINDS.map(() => '?').join(',');
    const rows = await adapter.allAsync<any>(
      `SELECT s.id, s.name, s.kind, f.path as file_path, f.language
       FROM symbols s LEFT JOIN files f ON f.id = s.file_id
       WHERE s.kind IN (${placeholders})`,
      INCLUDE_KINDS,
    );
    for (const sym of rows) processSymbolRow(sym, allEntries, sources, ksaGroupMap, groupCounter);
    logger.info({ symbolCount: rows.length }, 'Collected code symbols');
  } catch (err: any) {
    logger.warn({ error: err.message }, 'Failed to read code symbols — skipping');
  }
}

/**
 * Full graph sync: collect all KB entries + code symbols, then bulk-insert.
 * @param db - DatabaseAdapter to write graph_nodes/graph_edges
 * @param logger - Pino logger
 */
export async function fullSync(
  db: DatabaseAdapter, logger: Logger,
): Promise<{ nodesCreated: number; edgesCreated: number; sources: Record<string, number> }> {
  const startTime = Date.now();
  const allEntries: EntryRow[] = [];
  const ksaGroupMap = new Map<string, number>();
  const groupCounter = { value: 0 };
  const sources: Record<string, number> = {};

  await processKbEntries(allEntries, sources, ksaGroupMap, groupCounter, logger);
  await processCodeSymbols(allEntries, sources, ksaGroupMap, groupCounter, logger);

  const result = await syncFromEntries(allEntries, db, logger);
  const elapsed = Date.now() - startTime;
  logger.info({ ...result, sources, elapsed: `${elapsed}ms` }, 'Full graph sync complete');
  return { ...result, sources };
}

/**
 * Memory Module — handles mem_* tool operations.
 * Builder pattern: initialize() delegates to MemoryModuleBuilder.
 * DIP: core dependencies injectable via MemoryModuleDeps.
 * SRP: LLM initialization delegated to LLMInitializer.
 */

import type { IModule, ModuleStatus } from '../../types/module.js';
import type { ToolHandler, ToolDefinition } from '../../types/tool.js';
import type { Logger } from 'pino';
import { DatabaseManager } from '../../engine/db/database-manager.js';
import { MemoryEngine } from './engine/index.js';
import { MemoryToolDispatcher } from './dispatchers/index.js';
import type { ModuleRegistry } from '../ModuleRegistry.js';
import { MEMORY_TOOL_DEFINITIONS } from './definitions/index.js';
import { loadConfig } from '../../engine/config.js';
import { stopScheduler } from './evolution/Scheduler.js';
import type { SchedulerHandles } from './evolution/Scheduler.js';
import { TaskWorker } from './task-queue/TaskWorker.js';
import type { ScopeContext } from './models.js';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { ScopePromotionService } from './promotion/index.js';
import { MemoryModuleBuilder } from './MemoryModuleBuilder.js';
import { withErrorHandling, withScopeContext, withResultFormat } from '../../tool-router/ToolHandlerDecorators.js';
import { bus, Events } from '../../shared/EventBus.js';
import { initLLMInBackground } from './llm/LLMInitializer.js';

/**
 * Injectable dependencies for MemoryModule.
 * All fields are optional — production uses default factories via initialize().
 * Tests can inject mocks to avoid real DB/filesystem access.
 */
export interface MemoryModuleDeps {
  dbManager?: DatabaseManager;
  memAdapter?: DatabaseAdapter;
  engine?: MemoryEngine;
  taskWorker?: TaskWorker;
  promotionService?: ScopePromotionService;
}

export class MemoryModule implements IModule {
  readonly name = 'memory';
  private _status: ModuleStatus = 'initializing';
  private logger: Logger;
  dbManager!: DatabaseManager;
  engine!: MemoryEngine;
  dispatcher!: MemoryToolDispatcher;
  promotionInterval: ReturnType<typeof setInterval> | null = null;
  consolidationInterval: ReturnType<typeof setInterval> | null = null;
  readonly sessionName: string;
  schedulerHandles: SchedulerHandles | null = null;
  taskWorker: TaskWorker | null = null;
  private readonly registry?: ModuleRegistry;
  private readonly injectedDeps: MemoryModuleDeps;

  constructor(logger: Logger, sessionName?: string, registry?: ModuleRegistry, deps: MemoryModuleDeps = {}) {
    this.logger = logger.child({ module: this.name });
    this.sessionName = sessionName || `kiro-backend-${process.pid}`;
    this.registry = registry;
    this.injectedDeps = deps;
  }

  get status(): ModuleStatus { return this._status; }

  getInjectedDeps(): MemoryModuleDeps { return this.injectedDeps; }

  setDbManager(m: DatabaseManager): void { this.dbManager = m; }
  setEngine(e: MemoryEngine): void { this.engine = e; }
  setDispatcher(d: MemoryToolDispatcher): void { this.dispatcher = d; }
  setTaskWorker(w: TaskWorker): void { this.taskWorker = w; }
  setPromotionInterval(i: ReturnType<typeof setInterval> | null): void { this.promotionInterval = i; }
  setConsolidationInterval(i: ReturnType<typeof setInterval> | null): void { this.consolidationInterval = i; }
  setSchedulerHandles(h: SchedulerHandles | null): void { this.schedulerHandles = h; }
  setStatus(s: 'ready' | 'error'): void { this._status = s; }

  async initialize(): Promise<void> {
    this.logger.info('Initializing memory module');
    try {
      const config = loadConfig();
      const builder = new MemoryModuleBuilder(this as any, this.logger, {
        dbPath: config.dbPath,
        dataDir: config.dataDir,
        workspace: config.workspace,
        sessionName: this.sessionName,
      });

      await builder.withDatabase();
      await builder.withEngine();
      await builder.withFtsRebuild();
      builder.withDispatcher(this.registry);
      builder.withTaskWorker();
      builder.withPromotion();
      builder.withConsolidation();
      builder.withBackgroundLLM();
      builder.build();

      // Subscribe to LLM config changes — re-init services immediately without restart
      bus.on(Events.LLM_CONFIG_CHANGED, () => {
        this.logger.info('[MemoryModule] LLM config changed — re-initializing LLM services');
        this.reinitLLM();
      });

      // Subscribe to TaskWorker config changes — apply concurrency/intervals without restart
      bus.on(Events.TASK_WORKER_CONFIG_CHANGED, (payload: any) => {
        if (!this.taskWorker) return;
        const key = payload?.key as string;
        const raw = payload?.value;
        if (key === 'concurrency') this.taskWorker.updateConfig({ concurrency: parseInt(String(raw), 10) });
        else if (key === 'baseInterval') this.taskWorker.updateConfig({ baseInterval: parseInt(String(raw), 10) });
        else if (key === 'maxInterval') this.taskWorker.updateConfig({ maxInterval: parseInt(String(raw), 10) });
      });
    } catch (error) {
      this.logger.error({ err: error }, 'Failed to initialize memory module');
      this._status = 'error';
    }
  }

  /**
   * Re-initialize LLM services (TagAnalyzer + ClassifyService) using latest config from DB.
   * Called automatically when admin saves LLM config via UI — no restart needed.
   * Safe to call while running — fire-and-forget, replaces existing service references.
   */
  reinitLLM(): void {
    if (!this.dispatcher || !this.taskWorker) {
      this.logger.warn('[MemoryModule] Cannot reinit LLM — dispatcher or taskWorker not ready');
      return;
    }
    initLLMInBackground(this.dispatcher, this.taskWorker, this.logger);
  }

  async shutdown(): Promise<void> {
    this.logger.info('Shutting down memory module');
    if (this.schedulerHandles) { stopScheduler(this.schedulerHandles); this.schedulerHandles = null; }
    if (this.promotionInterval) { clearInterval(this.promotionInterval); this.promotionInterval = null; }
    if (this.consolidationInterval) { clearInterval(this.consolidationInterval); this.consolidationInterval = null; }
    if (this.engine) this.engine.endSession();
    if (this.dbManager) this.dbManager.close();
    this._status = 'stopped';
  }

  getEngine(): MemoryEngine { return this.engine; }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();
    for (const def of MEMORY_TOOL_DEFINITIONS) {
      const handler = withErrorHandling(this.logger, def.name)(
        withScopeContext(this.dispatcher)(
          withResultFormat(
            async (args) => this.dispatcher.dispatch(def.name, args as Record<string, unknown>),
          ),
        ),
      );
      handlers.set(def.name, handler);
    }
    return handlers;
  }

  getToolDefinitions(): ToolDefinition[] {
    return MEMORY_TOOL_DEFINITIONS.map(def => ({ ...def, category: 'memory' })) as ToolDefinition[];
  }
}

﻿/**
 * MemoryModuleBuilder — fluent builder for MemoryModule initialization.
 * Builder pattern: decomposes the 69-line initialize() into focused steps.
 * Each with*() method handles one sub-step, improving testability and SRP.
 *
 * Usage:
 *   const mod = new MemoryModule(logger);
 *   await new MemoryModuleBuilder(mod)
 *     .withDatabase(config)
 *     .withEngine(config)
 *     .withDispatcher(config, registry)
 *     .withTaskWorker(config)
 *     .withPromotion(config)
 *     .withBackgroundLLM()
 *     .build();
 */

import type { Logger } from 'pino';
import type { ModuleRegistry } from '../ModuleRegistry.js';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { DatabaseManager } from '../../engine/db/database-manager.js';
import { MemoryEngine } from './engine/index.js';
import { MemoryToolDispatcher } from './dispatchers/index.js';
import { ConvertToolResolver } from './ingest/ConvertToolResolver.js';
import { RegistryOrchestrationGateway } from './ingest/OrchestrationGateway.js';
import { QueryLayer } from '../../engine/query/query-layer.js';
import { migrate001AddScopeColumns } from './migrations/001-add-scope-columns.js';
import { migrate002AddEvolutionColumns } from './migrations/002-add-evolution-columns.js';
import { migrate003PendingTasks } from './migrations/003-pending-tasks.js';
import { migrate004ResetSequences } from './migrations/004-reset-sequences.js';
import { migrate005UniqueSourceProject } from './migrations/005-unique-source-project.js';
import { migrate006PendingTasksProjectId } from './migrations/006-pending-tasks-project-id.js';
import { ScopePromotionService } from './promotion/index.js';
import { TierConsolidationService } from './consolidation/service.js';
import { startScheduler, stopScheduler } from './evolution/Scheduler.js';
import type { SchedulerHandles } from './evolution/Scheduler.js';
import { TaskWorker } from './task-queue/TaskWorker.js';
import type { TaskWorkerConfig } from './task-queue/TaskWorkerConfig.js';
import { resolveEngineAdapter } from '../../database/factory/resolveEngineAdapter.js';
import { initLLMInBackground } from './llm/LLMInitializer.js';
import type { MemoryModule, MemoryModuleDeps } from './MemoryModule.js';

const PROMOTION_SCAN_INTERVAL_MS = 60 * 60 * 1000;
const CONSOLIDATION_INTERVAL_MS = 30 * 60 * 1000;

export interface BuilderConfig {
  dataDir: string;
  dbPath?: string;
  workspace?: string;
  sessionName?: string;
  taskWorkerConfig?: Partial<TaskWorkerConfig>;
}

/**
 * MemoryModuleBuilder — constructs a MemoryModule step-by-step.
 * SA4E-53: updated ScopePromotionService constructor to use DatabaseAdapter.
 */
export class MemoryModuleBuilder {
  private memAdapter: DatabaseAdapter | null = null;

  constructor(
    private readonly mod: MemoryModule,
    private readonly logger: Logger,
    private readonly config: BuilderConfig,
  ) {}

  /** Step 1: Open SQLite/PG connection and run schema migrations. */
  /** Step 1: Open connection and run schema migrations.
   *  SA4E-53: DatabaseManager only created for SQLite — Postgres skips SQLite file.
   */
  async withDatabase(): Promise<this> {
    const dbPath = this.config.dbPath ?? `${this.config.dataDir}/memory.db`;
    const injectd = this.mod.getInjectedDeps();

    // Resolve adapter — only opens SQLite when engine is sqlite
    const injectAdapter = injectd.memAdapter;
    if (injectAdapter) {
      this.memAdapter = injectAdapter;
    } else {
      this.memAdapter = await resolveEngineAdapter(this.config.dataDir, dbPath);
    }

    // For SQLite: also initialize DatabaseManager (schema migrations, WAL, etc.)
    if (this.memAdapter.getEngine() === 'sqlite') {
      let dbManager: DatabaseManager;
      if (injectd.dbManager) {
        dbManager = injectd.dbManager;
      } else {
        dbManager = new DatabaseManager(dbPath);
        dbManager.initialize();
      }
      this.mod.setDbManager(dbManager);
    }

    // Run versioned migrations via DatabaseAdapter
    await migrate001AddScopeColumns(this.memAdapter);
    await migrate002AddEvolutionColumns(this.memAdapter);
    await migrate003PendingTasks(this.memAdapter);
    await migrate004ResetSequences(this.memAdapter);
    await migrate005UniqueSourceProject(this.memAdapter);
    await migrate006PendingTasksProjectId(this.memAdapter);

    // SA4E-79: Add enrichment_status tracking columns
    const { migrate007Up } = await import('./schema/migrations/007_enrichment_status.js');
    await migrate007Up(this.memAdapter).catch(err => {
      // Column already exists — safe to ignore
      if (!String(err).includes('duplicate column') && !String(err).includes('already exists')) {
        this.logger.warn({ err }, '[MemoryModuleBuilder] Migration 007 issue (non-fatal)');
      }
    });

    // SA4E-45: Ensure PostgreSQL FTS infrastructure exists (tsvector_content + GIN index)
    if (this.memAdapter.getEngine() === 'postgresql') {
      const { recreateFtsInfrastructure } = await import('../../database/migration/fts-recreation.js');
      await recreateFtsInfrastructure(this.memAdapter).catch(err => {
        this.logger.warn({ err }, '[MemoryModuleBuilder] FTS recreation failed (non-fatal)');
      });
    }

    return this;
  }

  /** Step 2: Construct MemoryEngine and start a named session. */
  async withEngine(): Promise<this> {
    const injectd = this.mod.getInjectedDeps();
    const engine = injectd.engine ?? new MemoryEngine(this.memAdapter!);
    await engine.startSession(this.config.sessionName);
    this.mod.setEngine(engine);
    // Backfill existing knowledge_entries into graph_nodes (non-blocking)
    engine.syncExistingEntriesToGraph().then(n => {
      this.logger.info({ count: n }, '[MemoryModuleBuilder] Backfilled KB entries into graph_nodes');
    }).catch((err: unknown) => {
      this.logger.warn({ err }, '[MemoryModuleBuilder] Backfill KB → graph skipped');
    });
    return this;
  }

  /** Step 2b: Rebuild FTS index if empty (SA4E-79 FTS bug fix). */
  async withFtsRebuild(): Promise<this> {
    if (!this.memAdapter || this.memAdapter.getEngine() !== 'sqlite') return this;
    try {
      const count = await this.memAdapter.getAsync<{ cnt: number }>(
        'SELECT COUNT(*) as cnt FROM knowledge_fts',
      );
      if (count && count.cnt > 0) return this;
      this.logger.info('[FTS] knowledge_fts is empty — triggering rebuild from knowledge_entries');
      await this.memAdapter.runAsync(
        "INSERT INTO knowledge_fts(knowledge_fts) VALUES('rebuild')",
      );
      const rebuilt = await this.memAdapter.getAsync<{ cnt: number }>(
        'SELECT COUNT(*) as cnt FROM knowledge_fts',
      );
      this.logger.info({ rebuilt: rebuilt?.cnt ?? 0 }, '[FTS] Rebuild complete');
    } catch (err) {
      this.logger.warn({ err }, '[FTS] Rebuild failed (non-fatal)');
    }
    return this;
  }

  /** Step 3: Wire MemoryToolDispatcher with all services. */
  withDispatcher(registry?: ModuleRegistry): this {
    const { workspace = '' } = this.config;
    const queryLayer = this.memAdapter
      ? new QueryLayer(this.memAdapter!)
      : undefined;
    const dispatcher = new MemoryToolDispatcher(this.mod.engine, workspace, queryLayer);
    if (registry) {
      const gateway = new RegistryOrchestrationGateway(registry);
      const resolver = new ConvertToolResolver(gateway);
      dispatcher.setConvertResolver(resolver);
    }
    if (this.memAdapter) dispatcher.setDbAdapter(this.memAdapter);
    this.mod.setDispatcher(dispatcher);
    return this;
  }

  /** Step 4: Set up task worker for background enrichment. */
  withTaskWorker(): this {
    const injectd = this.mod.getInjectedDeps();
    const worker = injectd.taskWorker
      ? injectd.taskWorker
      : new TaskWorker(this.memAdapter!, this.mod.engine, this.logger, this.config.taskWorkerConfig);
    worker.start();
    this.mod.setTaskWorker(worker);

    // SA4E-107: Load persisted TaskWorker config from DB (Admin UI values survive restart)
    this.loadPersistedTaskWorkerConfig(worker).catch(err => {
      this.logger.debug({ err }, '[MemoryModuleBuilder] Failed to load persisted TaskWorker config (using defaults)');
    });

    return this;
  }

  /** Load TaskWorker config overrides from config_changes DB table (non-blocking). */
  private async loadPersistedTaskWorkerConfig(worker: TaskWorker): Promise<void> {
    try {
      const { getAdminAdapter } = await import('../../admin/db/core.js');
      const adapter = getAdminAdapter();
      const rows = await adapter.allAsync<{ key: string; new_value: string }>(
        "SELECT key, new_value FROM config_changes WHERE section = 'taskWorker' ORDER BY changed_at DESC",
      );
      const patch: Record<string, number> = {};
      for (const row of rows) {
        if (!patch[row.key]) { patch[row.key] = parseInt(row.new_value, 10); }
      }
      if (Object.keys(patch).length > 0) {
        worker.updateConfig(patch as any);
        this.logger.info({ patch }, '[TaskWorker] Loaded persisted config from DB');
      }
    } catch { /* DB may not have config_changes table yet — use defaults */ }
  }

  /** Step 5: Start scope promotion service + background scheduler. */
  withPromotion(): this {
    const injectd = this.mod.getInjectedDeps();
    if (!injectd.promotionService && this.memAdapter) {
      // SA4E-53: ScopePromotionService now uses DatabaseAdapter
      const promotionService = new ScopePromotionService(this.memAdapter, this.logger);
      // Initialize table asynchronously (non-blocking)
      promotionService.ensurePromotionQueueTable().catch((err: unknown) => {
        this.logger.warn({ err }, '[MemoryModuleBuilder] promotion queue table init failed');
      });
      this.mod.dispatcher?.setPromotionService(promotionService);

      const interval = setInterval(() => {
        promotionService.runPromotionCycle().catch((err: unknown) => {
          this.logger.warn({ err }, 'Promotion cycle failed');
        });
      }, PROMOTION_SCAN_INTERVAL_MS);
      this.mod.setPromotionInterval(interval);
    } else if (injectd.promotionService) {
      this.mod.dispatcher?.setPromotionService(injectd.promotionService);
    }

    // Start decay/epoch scheduler — now uses adapter directly (all engines)
    if (this.mod.engine) {
      const handles = startScheduler(this.mod.engine.getAdapter(), this.logger);
      this.mod.setSchedulerHandles(handles);
    }
    return this;
  }

  /** Step 6: Start background tier consolidation (non-blocking). */
  withConsolidation(): this {
    if (this.memAdapter) {
      const service = new TierConsolidationService(this.memAdapter);
      const interval = setInterval(() => {
        service.runConsolidation().catch((err: unknown) => {
          this.logger.warn({ err }, '[MemoryModuleBuilder] Consolidation cycle failed');
        });
      }, CONSOLIDATION_INTERVAL_MS);
      this.mod.setConsolidationInterval(interval);
    }
    return this;
  }

  /** Step 7: Kick off LLM initialization in background (non-blocking). */
  withBackgroundLLM(): this {
    if (this.mod.taskWorker) {
      try {
        initLLMInBackground(this.mod.dispatcher!, this.mod.taskWorker, this.logger);
      } catch (err: unknown) {
        this.logger.warn({ err }, 'LLM init failed');
      }
    }
    return this;
  }

  /** Finalize: mark module as ready. */
  build(): void {
    this.mod.setStatus('ready');
    this.logger.info('Memory module ready');
  }
}

/**
 * MigrationRunner — versioned schema migration system.
 * Replaces fragile try/catch ALTER TABLE approach (SA4E-26).
 * Implements BR-10 through BR-15.
 * SA4E-53: Uses SyncDatabaseAdapter instead of raw better-sqlite3.
 */

import type { SyncDatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';

export interface Migration {
  version: number;
  name: string;
  up: string;
}

const REGISTERED_MIGRATIONS: Migration[] = [
  {
    version: 1,
    name: 'add_project_id_column',
    up: [
      'ALTER TABLE knowledge_entries ADD COLUMN project_id TEXT DEFAULT NULL',
      'CREATE INDEX IF NOT EXISTS idx_ke_project_id ON knowledge_entries(project_id)',
      'CREATE INDEX IF NOT EXISTS idx_ke_scope_project ON knowledge_entries(scope, project_id)',
    ].join(';\n'),
  },
  {
    version: 2,
    name: 'add_workspace_id_column',
    up: [
      'ALTER TABLE knowledge_entries ADD COLUMN workspace_id TEXT DEFAULT NULL',
      'CREATE INDEX IF NOT EXISTS idx_ke_workspace_id ON knowledge_entries(workspace_id)',
      'CREATE INDEX IF NOT EXISTS idx_ke_scope_isolation ON knowledge_entries(scope, user_id, workspace_id, project_id)',
    ].join(';\n'),
  },
];

export class MigrationRunner {
  private readonly db: SyncDatabaseAdapter;

  constructor(db: SyncDatabaseAdapter) {
    this.db = db;
  }

  run(): { applied: number; skipped: number; total: number } {
    this.ensureTrackingTable();
    const applied = this.getAppliedVersions();
    let appliedCount = 0;
    let skippedCount = 0;

    // Downgrade detection (TA Decision #5)
    const maxDb = applied.length > 0 ? Math.max(...applied) : 0;
    const maxCode = REGISTERED_MIGRATIONS.length > 0
      ? REGISTERED_MIGRATIONS[REGISTERED_MIGRATIONS.length - 1].version
      : 0;
    if (maxDb > maxCode) {
      console.warn(
        `[MigrationRunner] DB version (${maxDb}) ahead of code (${maxCode}). Forward-only — continuing.`,
      );
    }

    for (const m of REGISTERED_MIGRATIONS) {
      if (applied.includes(m.version)) {
        skippedCount++;
        continue;
      }

      try {
        for (const stmt of m.up.split(';\n').filter(s => s.trim())) {
          try {
            this.db.exec(stmt);
          } catch (stmtErr: unknown) {
            const stmtMsg = stmtErr instanceof Error ? stmtErr.message : String(stmtErr);
            if (stmtMsg.includes('duplicate column')) {
              // SA4E-26 leftover — column already exists, continue
              console.info(`[MigrationRunner] v${m.version} (${m.name}): column exists, recording as applied.`);
            } else {
              throw stmtErr;
            }
          }
        }
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : String(err);
        throw new Error(`Migration v${m.version} (${m.name}) failed: ${msg}`);
      }

      this.db.run(
        'INSERT INTO schema_migrations (version, name, applied_at, checksum) VALUES (?, ?, ?, ?)',
        [m.version, m.name, new Date().toISOString(), null],
      );
      appliedCount++;
    }

    if (appliedCount > 0) {
      console.info(`[MigrationRunner] Applied ${appliedCount} migration(s).`);
    }

    return { applied: appliedCount, skipped: skippedCount, total: REGISTERED_MIGRATIONS.length };
  }

  getAppliedVersions(): number[] {
    try {
      return (this.db.all<{ version: number }>('SELECT version FROM schema_migrations ORDER BY version'))
        .map(r => r.version);
    } catch {
      return []; // Table doesn't exist yet
    }
  }

  getCurrentVersion(): number {
    const versions = this.getAppliedVersions();
    return versions.length > 0 ? Math.max(...versions) : 0;
  }

  private ensureTrackingTable(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS schema_migrations (
        version INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        applied_at TEXT NOT NULL,
        checksum TEXT
      )
    `);
  }
}

