    it('throws on malformed JSON with braces', () => {
      const llm = createMockLLMService('{}');
      const svc = new ClassifyService(llm as any);

      expect(() => svc.parseResponse('{invalid json content}'))
        .toThrow('llm_parse_error');
    });
  });

  describe('classify', () => {
