import { describe, it, expect, vi } from 'vitest';
import { searchPegaSymbols, mergeDedupResults } from '../engine/pega-search.js';
import type { SearchResult } from '../models.js';

describe('pega-search', () => {
  describe('mergeDedupResults', () => {
    it('should prefer symbols over legacy when FQN matches', () => {
      const legacy: SearchResult[] = [
        { entry: { source: 'Rule-Obj-Activity:Work:Approve' } as any, score: 5, matchType: 'knowledge_fts' },
      ];
      const symbols: SearchResult[] = [
        { entry: { source: 'Rule-Obj-Activity:Work:Approve' } as any, score: 3, matchType: 'symbols_fts' },
      ];
      const result = mergeDedupResults(legacy, symbols, 10);
      // Only one result (deduped), from symbols
      expect(result).toHaveLength(1);
      expect(result[0].matchType).toBe('symbols_fts');
    });

    it('should include both when FQN does not match', () => {
      const legacy: SearchResult[] = [
        { entry: { source: 'legacy:Work:RuleA' } as any, score: 5, matchType: 'knowledge_fts' },
      ];
      const symbols: SearchResult[] = [
        { entry: { source: 'Rule-Obj-Activity:Work:RuleB' } as any, score: 3, matchType: 'symbols_fts' },
      ];
      const result = mergeDedupResults(legacy, symbols, 10);
      expect(result).toHaveLength(2);
    });

    it('should respect limit parameter', () => {
      const legacy: SearchResult[] = Array.from({ length: 5 }, (_, i) => ({
        entry: { source: `legacy${i}` } as any, score: i, matchType: 'knowledge_fts',
      }));
      const symbols: SearchResult[] = Array.from({ length: 5 }, (_, i) => ({
        entry: { source: `symbol${i}` } as any, score: i + 10, matchType: 'symbols_fts',
      }));
      const result = mergeDedupResults(legacy, symbols, 7);
      expect(result).toHaveLength(7);
    });

    it('should sort by score descending', () => {
      const legacy: SearchResult[] = [
        { entry: { source: 'a' } as any, score: 10, matchType: 'knowledge_fts' },
      ];
      const symbols: SearchResult[] = [
        { entry: { source: 'b' } as any, score: 20, matchType: 'symbols_fts' },
      ];
      const result = mergeDedupResults(legacy, symbols, 10);
      expect(result[0].score).toBeGreaterThan(result[1].score!);
    });

    it('should handle empty arrays', () => {
      expect(mergeDedupResults([], [], 10)).toHaveLength(0);
      const legacy: SearchResult[] = [
        { entry: { source: 'a' } as any, score: 1, matchType: 'knowledge_fts' },
      ];
      expect(mergeDedupResults(legacy, [], 10)).toHaveLength(1);
      expect(mergeDedupResults([], legacy, 10)).toHaveLength(1);
    });
  });

  describe('searchPegaSymbols', () => {
    it('should return empty array when no projectId', async () => {
      const mockAdapter = {} as any;
      const result = await searchPegaSymbols(mockAdapter, 'test', 10, undefined);
      expect(result).toHaveLength(0);
    });

    it('should return empty array when projectId is empty', async () => {
      const mockAdapter = {} as any;
      const result = await searchPegaSymbols(mockAdapter, 'test', 10, { projectId: '' } as any);
      expect(result).toHaveLength(0);
    });

    it('should return empty for unsupported engine', async () => {
      const mockAdapter = {
        getEngine: () => 'mysql',
      } as any;
      const result = await searchPegaSymbols(mockAdapter, 'test', 10, { projectId: 'proj1' } as any);
      expect(result).toHaveLength(0);
    });

    it('should call sqlite FTS when engine is sqlite', async () => {
      const mockRows = [
        { id: 1, name: 'TestRule', kind: 'pega_activity', signature: 'fqn1', doc_comment: 'doc', summary: 'sum', enrichment_status: null, score: -1.5 },
      ];
      const mockAdapter = {
        getEngine: () => 'sqlite',
        allAsync: vi.fn().mockResolvedValue(mockRows),
      } as any;
      const result = await searchPegaSymbols(mockAdapter, 'TestRule', 10, { projectId: 'proj1' } as any);
      expect(result).toHaveLength(1);
      expect(mockAdapter.allAsync).toHaveBeenCalledOnce();
      // Verify project_id is passed (SEC-04)
      const callArgs = mockAdapter.allAsync.mock.calls[0][1];
      expect(callArgs).toContain('proj1');
    });

    it('should sanitize FTS query — strip colons and quotes (SEC Finding #1)', async () => {
      const mockAdapter = {
        getEngine: () => 'sqlite',
        allAsync: vi.fn().mockResolvedValue([]),
      } as any;
      await searchPegaSymbols(mockAdapter, 'test:inject"quote', 10, { projectId: 'p1' } as any);
      const ftsArg = mockAdapter.allAsync.mock.calls[0][1][0];
      // Should not contain : or "
      expect(ftsArg).not.toContain(':');
      expect(ftsArg).not.toContain('"');
    });

    it('should limit query to 200 chars (SEC Finding #2)', async () => {
      const longQuery = 'a'.repeat(300);
      const mockAdapter = {
        getEngine: () => 'sqlite',
        allAsync: vi.fn().mockResolvedValue([]),
      } as any;
      await searchPegaSymbols(mockAdapter, longQuery, 10, { projectId: 'p1' } as any);
      const ftsArg = mockAdapter.allAsync.mock.calls[0][1][0];
      expect(ftsArg.length).toBeLessThanOrEqual(200);
    });
  });
});

import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import type { ConsolidationResult } from '../models.js';
import { DialectHelper } from '../../../database/dialect/DialectHelper.js';

const TIER_ORDER: Record<string, number> = { WORKING: 0, EPISODIC: 1, SEMANTIC: 2 };
const TIER_NAMES = ['WORKING', 'EPISODIC', 'SEMANTIC'];

export interface ConsolidationConfig {
  workingToEpisodicMinHours: number;
  workingToEpisodicMinAccess: number;
  workingToEpisodicMinQuality: number;
  episodicToSemanticMinDays: number;
  episodicToSemanticMinAccess: number;
  episodicToSemanticMinQuality: number;
  batchSize: number;
}

export const DEFAULT_CONSOLIDATION_CONFIG: ConsolidationConfig = {
  workingToEpisodicMinHours: 24,
  workingToEpisodicMinAccess: 3,
  workingToEpisodicMinQuality: 50,
  episodicToSemanticMinDays: 7,
  episodicToSemanticMinAccess: 10,
  episodicToSemanticMinQuality: 70,
  batchSize: 100,
};

export class TierConsolidationService {
  private adapter: DatabaseAdapter;
  private dialect: DialectHelper;

  constructor(
    adapter: DatabaseAdapter,
    private config: ConsolidationConfig = DEFAULT_CONSOLIDATION_CONFIG,
  ) {
    this.adapter = adapter;
    this.dialect = new DialectHelper(adapter.getEngine());
  }

  getConfig(): ConsolidationConfig { return this.config; }

  updateConfig(partial: Partial<ConsolidationConfig>): void {
    this.config = { ...this.config, ...partial };
  }

  async runConsolidation(dryRun = false, targetTier?: string): Promise<ConsolidationResult> {
    const result: ConsolidationResult = { promoted: 0, demoted: 0, expired: 0 };

    const tiersToProcess = targetTier
      ? TIER_NAMES.slice(0, TIER_ORDER[targetTier] ?? TIER_NAMES.length)
      : TIER_NAMES;

    for (let i = 0; i < tiersToProcess.length; i++) {
      const fromTier = tiersToProcess[i];
      const toTierIdx = TIER_ORDER[fromTier] + 1;
      if (toTierIdx >= TIER_NAMES.length) continue;
      const toTier = TIER_NAMES[toTierIdx];
      if (targetTier && TIER_ORDER[toTier] > TIER_ORDER[targetTier]) continue;
      const promoted = await this.promoteTier(fromTier, toTier, dryRun);
      result.promoted += promoted;
    }

    if (!targetTier) {
      const demoted = await this.demoteStale(dryRun);
      result.demoted += demoted;
      const expired = await this.archiveExpired(dryRun);
      result.expired += expired;
    }

    return result;
  }

  private async promoteTier(fromTier: string, toTier: string, dryRun: boolean): Promise<number> {
    let candidates: any[] = [];

    if (fromTier === 'WORKING' && toTier === 'EPISODIC') {
      candidates = await this.adapter.allAsync<any>(
        `SELECT id, tier, access_count, quality_score, created_at FROM knowledge_entries
         WHERE tier = ? AND archived = 0
           AND quality_score >= ?
           AND access_count >= ?
           AND ${this.dialect.dateColumnCompare('created_at', '<= now -', `-${this.config.workingToEpisodicMinHours} hours`)}
         LIMIT ?`,
        [fromTier, this.config.workingToEpisodicMinQuality, this.config.workingToEpisodicMinAccess,
         this.config.batchSize],
      );
    } else if (fromTier === 'EPISODIC' && toTier === 'SEMANTIC') {
      candidates = await this.adapter.allAsync<any>(
        `SELECT id, tier, access_count, quality_score, structured_map, created_at FROM knowledge_entries
         WHERE tier = ? AND archived = 0
           AND quality_score >= ?
           AND access_count >= ?
           AND structured_map != '{}'
           AND ${this.dialect.dateColumnCompare('created_at', '<= now -', `-${this.config.episodicToSemanticMinDays} days`)}
         LIMIT ?`,
        [fromTier, this.config.episodicToSemanticMinQuality, this.config.episodicToSemanticMinAccess,
         this.config.batchSize],
      );
    }

    if (candidates.length === 0) return 0;
    if (dryRun) return candidates.length;

    const ids = candidates.map((c: any) => c.id);
    const now = this.dialect.now();

    await this.adapter.runAsync(
      `UPDATE knowledge_entries SET tier = ?, updated_at = ${now} WHERE id IN (${ids.join(',')})`,
      [toTier],
    );

    for (const c of candidates) {
      await this.adapter.runAsync(
        `INSERT INTO consolidation_log (entry_id, from_tier, to_tier, reason) VALUES (?, ?, ?, ?)`,
        [c.id, fromTier, toTier, `auto-promote: meets ${fromTier}→${toTier} criteria`],
      );
    }

    return candidates.length;
  }

  private async demoteStale(dryRun: boolean): Promise<number> {
    const candidates = await this.adapter.allAsync<any>(
      `SELECT id, tier, access_count, last_accessed_at, created_at FROM knowledge_entries
       WHERE tier IN ('EPISODIC', 'SEMANTIC') AND archived = 0
         AND last_accessed_at IS NOT NULL
         AND ${this.dialect.dateColumnCompare('last_accessed_at', '<= now -', '-30 days')}
         AND access_count < 2
       LIMIT ?`,
      [this.config.batchSize],
    );

    if (candidates.length === 0) return 0;
    if (dryRun) return candidates.length;

    for (const c of candidates) {
      const currentTier = c.tier as string;
      const idx = TIER_ORDER[currentTier] ?? 1;
      const targetTier = TIER_NAMES[Math.max(0, idx - 1)];
      if (targetTier === currentTier) continue;

      await this.adapter.runAsync(
        `UPDATE knowledge_entries SET tier = ?, updated_at = ${this.dialect.now()} WHERE id = ?`,
        [targetTier, c.id],
      );
      await this.adapter.runAsync(
        `INSERT INTO consolidation_log (entry_id, from_tier, to_tier, reason) VALUES (?, ?, ?, ?)`,
        [c.id, currentTier, targetTier, 'auto-demote: stale (30d no access, <2 total)'],
      );
    }

    return candidates.length;
  }

  private async archiveExpired(dryRun: boolean): Promise<number> {
    const candidates = await this.adapter.allAsync<any>(
      `SELECT id FROM knowledge_entries
       WHERE archived = 0 AND expires_at IS NOT NULL
         AND ${this.dialect.dateColumnCompare('expires_at', '<= now')}
       LIMIT ?`,
      [this.config.batchSize],
    );

    if (candidates.length === 0) return 0;
    if (dryRun) return candidates.length;

    const ids = candidates.map((c: any) => c.id);
    await this.adapter.runAsync(
      `UPDATE knowledge_entries SET archived = 1, updated_at = ${this.dialect.now()} WHERE id IN (${ids.join(',')})`,
    );

    for (const c of candidates) {
      await this.adapter.runAsync(
        `INSERT INTO consolidation_log (entry_id, from_tier, to_tier, reason) VALUES (?, ?, ?, ?)`,
        [c.id, 'any', 'archived', 'auto-archive: expired'],
      );
    }

    return candidates.length;
  }
}

import type { MemoryEngine } from '../engine/core.js';
import type { ScopeContext } from '../models.js';
import type { ScopePromotionService } from '../promotion/service.js';
import type { QueryLayer } from '../../../engine/query/query-layer.js';
import { TierConsolidationService } from '../consolidation/service.js';
import { handleSyncCode } from './sync-code.js';

type Args = Record<string, unknown>;

export async function handleAdmin(engine: MemoryEngine, a: Args): Promise<string> {
  const action = (a.action as string) || 'status';
  switch (action) {
    case 'status': {
      const adapter = engine.getAdapter();
      const entryRow = await adapter.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM knowledge_entries');
      const edgeRow = await adapter.getAsync<{ cnt: number }>('SELECT COUNT(*) as cnt FROM knowledge_graph_edges');
      return `Entries: ${entryRow?.cnt ?? 0} | Edges: ${edgeRow?.cnt ?? 0}`;
    }
    case 'sync_code': return await handleSyncCode(engine, a._queryLayer as QueryLayer | undefined, a._workspace as string, a);
    case 'tool_usage': return JSON.stringify(await engine.getToolUsage(a.tool_name as string | undefined));
    case 'audit': return (await engine.listAudit((a.limit as number) ?? 20, a.operation as string)).map((e: any) => `[${e.operation}] ${e.created_at}`).join('\n') || 'Empty';
    case 'sessions': return (await engine.listSessions()).map((s: any) => `[${s.session_id}] ${s.status}`).join('\n') || 'None';
    case 'analytics': case 'popular': return '{}';
    case 'retry_all_failed': {
      const { PendingTaskRepository } = await import('../task-queue/PendingTaskRepository.js');
      const repo = new PendingTaskRepository(engine.getAdapter());
      const count = await repo.retryAllFailed();
      return `Reset ${count} FAILED tasks back to PENDING for retry.`;
    }
    case 'task_stats': {
      const { PendingTaskRepository } = await import('../task-queue/PendingTaskRepository.js');
      const repo = new PendingTaskRepository(engine.getAdapter());
      const stats = await repo.getStats();
      return JSON.stringify(stats);
    }
    case 'reset_enrichment': {
      // SA4E-171: Pega rules are enriched via symbols (CODE_ENRICHMENT).
      // Reset to NULL so CodeEnrichmentTaskCreator re-queues them.
      const projectId = a.project_id as string || '';
      const typeFilter = projectId
        ? `AND project_id = '${projectId}'`
        : '';
      const result = await engine.getAdapter().runAsync(
        `UPDATE symbols SET enrichment_status = NULL, enriched_at = NULL WHERE kind LIKE 'pega_%' AND enrichment_status = 'COMPLETED' ${typeFilter}`,
      );
      return `Reset ${result.changes} Pega symbols enrichment to re-eligible for CODE_ENRICHMENT.`;
    }
    case 'purge_orphan_tasks': {
      const result = await engine.getAdapter().runAsync(
        `DELETE FROM pending_tasks WHERE id IN (
          SELECT pt.id FROM pending_tasks pt
          LEFT JOIN knowledge_entries ke ON pt.entry_id = ke.id
          WHERE ke.id IS NULL
          LIMIT 10000
        )`,
      );
      return `Purged ${result.changes} orphaned tasks (batch, max 10000). Run again if more remain.`;
    }
    default: return `Admin: "${action}" via portal`;
  }
}

export async function handleGraph(engine: MemoryEngine, a: Args): Promise<string> {
  const action = (a.action as string) || 'neighbors';
  switch (action) {
    case 'neighbors': { const id = a.node_id as number; if (!id) return 'Error: node_id required'; const edges = await engine.getNeighbors(id); if (edges.length === 0) return `Node ${id}: no connections`; const ids = [...new Set(edges.flatMap(e => [e.source_id, e.target_id]).filter(x => x !== id))]; return `Node ${id} (${ids.length} connections):\n` + ids.slice(0, 20).map(n => `  → ${n}`).join('\n'); }
    case 'add_edge': { const s = a.source_id as number, t = a.target_id as number; if (!s || !t) return 'Error: source_id and target_id required'; const id = await engine.addEdge(s, t, (a.relation as string) ?? 'RELATES_TO'); return `Edge: ${s} → ${t} (id=${id})`; }
    case 'path': return 'Path query: use graph visualization';
    case 'ego': return 'Ego graph: use graph visualization';
    default: return `Unknown graph action: ${action}`;
  }
}

export async function handleConsolidate(engine: MemoryEngine, a: Args): Promise<string> {
  const action = (a.action as string) || 'consolidate';
  const dryRun = (a.dry_run as boolean) ?? false;
  const service = new TierConsolidationService(engine.getAdapter());

  switch (action) {
    case 'consolidate': {
      const targetTier = a.target_tier as string | undefined;
      const r = await service.runConsolidation(dryRun, targetTier);
      const prefix = dryRun ? '[DRY-RUN] Would promote: ' : 'Promoted: ';
      return `${prefix}${r.promoted}, Demoted: ${r.demoted}, Expired: ${r.expired}`;
    }
    case 'config': {
      if (dryRun) return JSON.stringify(service.getConfig(), null, 2);
      const updates = a.config as Partial<import('../consolidation/service.js').ConsolidationConfig> | undefined;
      if (updates) service.updateConfig(updates);
      return JSON.stringify(service.getConfig(), null, 2);
    }
    case 'stats': {
      const adapter = engine.getAdapter();
      const tiers = ['WORKING', 'EPISODIC', 'SEMANTIC'];
      const lines: string[] = [];
      for (const tier of tiers) {
        const row = await adapter.getAsync<{ cnt: number }>(
          'SELECT COUNT(*) as cnt FROM knowledge_entries WHERE tier = ? AND archived = 0', [tier],
        );
        lines.push(`${tier}: ${row?.cnt ?? 0}`);
      }
      return lines.join(' | ');
    }
    default: return `Unknown consolidate action: ${action}. Valid: consolidate, config, stats`;
  }
}

