/**
 * SA4E-122: ClusteringService — clusters related instincts into
 * skills/procedures over time. Groups instincts by tag similarity
 * and co-occurrence, then creates PROCEDURE entries for clusters
 * that exceed a size threshold.
 */

import type { MemoryEngine } from '../engine/core.js';
import type { ScopeContext, KnowledgeEntry } from '../models.js';

/** Minimum instincts in a cluster before procedure creation. */
const MIN_CLUSTER_SIZE = 3;

/** Minimum tag overlap ratio to consider two instincts related. */
const TAG_OVERLAP_THRESHOLD = 0.4;

/** Result of a clustering run. */
export interface ClusterResult {
  /** Number of clusters found. */
  clustersFound: number;
  /** Number of new procedures created. */
  proceduresCreated: number;
  /** Cluster summaries for reporting. */
  clusters: ClusterSummary[];
}

/** Summary of a single cluster. */
export interface ClusterSummary {
  /** Common tags in this cluster. */
  commonTags: string[];
  /** Number of instincts in cluster. */
  size: number;
  /** Whether a procedure was created for this cluster. */
  procedureCreated: boolean;
  /** Entry ID of created procedure (if any). */
  procedureId?: number;
}

export class ClusteringService {
  private readonly engine: MemoryEngine;

  constructor(engine: MemoryEngine) {
    this.engine = engine;
  }

  /**
   * Run clustering on all auto-learned instincts.
   * Groups by tag similarity, creates procedures for large clusters.
   * @param scopeCtx Scope context for isolation
   * @returns Clustering results summary
   */
  async cluster(scopeCtx?: ScopeContext): Promise<ClusterResult> {
    const instincts = await this.fetchAutoLearnedInstincts(scopeCtx);
    if (instincts.length < MIN_CLUSTER_SIZE) {
      return { clustersFound: 0, proceduresCreated: 0, clusters: [] };
    }

    const groups = this.groupByTagSimilarity(instincts);
    const clusters: ClusterSummary[] = [];
    let proceduresCreated = 0;

    for (const [tags, entries] of groups) {
      if (entries.length < MIN_CLUSTER_SIZE) continue;

      const commonTags = tags.split(',');
      const alreadyExists = await this.procedureExists(commonTags);

      if (alreadyExists) {
        clusters.push({ commonTags, size: entries.length, procedureCreated: false });
        continue;
      }

      const procId = await this.createProcedureFromCluster(commonTags, entries, scopeCtx);
      proceduresCreated++;
      clusters.push({ commonTags, size: entries.length, procedureCreated: true, procedureId: procId });
    }

    return { clustersFound: groups.size, proceduresCreated, clusters };
  }

  /** Fetch all instincts with 'auto-learned' tag. */
  private async fetchAutoLearnedInstincts(scopeCtx?: ScopeContext): Promise<KnowledgeEntry[]> {
    const adapter = this.engine.getAdapter();
    const rows = await adapter.allAsync<KnowledgeEntry>(
      `SELECT * FROM knowledge_entries
       WHERE type = 'INSTINCT' AND tags LIKE '%auto-learned%' AND archived = 0
       ORDER BY created_at DESC LIMIT 200`,
    );
    return rows;
  }

  /** Group instincts by common tags (excluding 'instinct' and 'auto-learned'). */
  private groupByTagSimilarity(entries: KnowledgeEntry[]): Map<string, KnowledgeEntry[]> {
    const groups = new Map<string, KnowledgeEntry[]>();

    for (const entry of entries) {
      const tags = this.getSignificantTags(entry.tags);
      const key = tags.sort().join(',');
      if (!key) continue;

      const group = groups.get(key) || [];
      group.push(entry);
      groups.set(key, group);
    }

    return groups;
  }

  /** Filter out generic tags, keep meaningful ones. */
  private getSignificantTags(tagStr: string): string[] {
    const ignore = new Set(['instinct', 'auto-learned', 'error-fix', 'correction']);
    return tagStr
      .split(',')
      .map(t => t.trim())
      .filter(t => t && !ignore.has(t));
  }

  /** Check if a procedure already exists for this tag set. */
  private async procedureExists(tags: string[]): Promise<boolean> {
    const adapter = this.engine.getAdapter();
    const tagPattern = tags[0] || 'auto-cluster';
    const row = await adapter.getAsync<{ cnt: number }>(
      `SELECT COUNT(*) as cnt FROM knowledge_entries
       WHERE type = 'PROCEDURE' AND tags LIKE ? AND archived = 0`,
      [`%${tagPattern}%`],
    );
    return (row?.cnt ?? 0) > 0;
  }

  /** Create a PROCEDURE entry summarizing the cluster. */
  private async createProcedureFromCluster(
    commonTags: string[],
    entries: KnowledgeEntry[],
    scopeCtx?: ScopeContext,
  ): Promise<number> {
    const name = `Cluster: ${commonTags.join(', ')}`;
    const content = this.buildProcedureContent(name, entries);
    const tags = ['procedure', 'auto-cluster', ...commonTags].join(',');

    return this.engine.insert({
      content,
      summary: `[Procedure] ${name}`,
      type: 'PROCEDURE',
      tier: 'SEMANTIC',
      scope: 'PROJECT',
      source: 'auto-learn/cluster',
      tags,
      user_id: scopeCtx?.userId ?? null,
      project_id: scopeCtx?.projectId ?? null,
      agent_name: 'auto-learner',
    });
  }

  /** Build procedure content from cluster entries. */
  private buildProcedureContent(name: string, entries: KnowledgeEntry[]): string {
    const steps = entries
      .slice(0, 10)
      .map((e, i) => `${i + 1}. ${e.content.slice(0, 150)}`)
      .join('\n');
    return `Procedure: ${name}\n\nAuto-clustered from ${entries.length} related instincts:\n\n${steps}`;
  }
}

/**
 * LLMInitializer — fire-and-forget LLM service setup for MemoryModule.
 * SRP fix: extracted from MemoryModule.initLLMInBackground() to keep
 * MemoryModule focused on lifecycle + tool routing, not LLM config details.
 *
 * Config priority (highest to lowest):
 *   1. Admin UI saved values (persisted in config_changes DB table)
 *   2. Environment variables
 *   3. Hardcoded defaults
 */

import type { Logger } from 'pino';
import { LLMService } from './LLMService.js';
import { TagAnalyzerService } from './analyzer.js';
import { ClassifyService } from './classify-service.js';
import { EmbeddingService } from '../../../engine/parsers/embedding/EmbeddingService.js';
import type { MemoryToolDispatcher } from '../dispatchers/index.js';
import type { TaskWorker } from '../task-queue/TaskWorker.js';
import { loadPersistedLLMConfig } from '../../../admin/db/config.js';

/** Build LLM config: DB overrides > env vars > auto-detect from LMStudio. */
async function buildLLMConfig() {
  const provider = process.env.LLM_PROVIDER || '';
  const model = process.env.LLM_MODEL || '';
  const baseUrl = process.env.LLM_BASE_URL || 'http://localhost:1234/v1';

  const envConfig = {
    provider: (provider || 'lmstudio') as any,
    model,
    baseUrl,
    apiKey: process.env.LLM_API_KEY || undefined,
    temperature: parseFloat(process.env.LLM_TEMPERATURE || '0.3'),
    maxTokens: parseInt(process.env.LLM_MAX_TOKENS || '800', 10),
  };

  // Merge DB overrides on top (Admin UI wins over env vars)
  try {
    const dbOverrides = await loadPersistedLLMConfig();
    const merged = {
      ...envConfig,
      ...(dbOverrides.provider && { provider: dbOverrides.provider as any }),
      ...(dbOverrides.model && { model: dbOverrides.model }),
      ...(dbOverrides.baseUrl && { baseUrl: dbOverrides.baseUrl }),
      ...(dbOverrides.apiKey && dbOverrides.apiKey !== '***' && { apiKey: dbOverrides.apiKey }),
      ...(dbOverrides.temperature !== undefined && { temperature: dbOverrides.temperature }),
      ...(dbOverrides.maxTokens !== undefined && { maxTokens: dbOverrides.maxTokens }),
    };
    if (merged.model) return merged;
    // Auto-detect: query LMStudio /v1/models and use first available
    merged.model = await autoDetectModel(merged.baseUrl);
    return merged;
  } catch (err: any) {
    if (err.message?.includes('LLM_MODEL')) throw err;
    // DB not ready — try env, then auto-detect
    if (envConfig.model) return envConfig;
    envConfig.model = await autoDetectModel(envConfig.baseUrl);
    return envConfig;
  }
}

/** Auto-detect model from LLM server's /v1/models endpoint. Throws if unavailable. */
async function autoDetectModel(baseUrl: string): Promise<string> {
  const modelsUrl = baseUrl.replace(/\/v1\/?$/, '') + '/v1/models';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const resp = await fetch(modelsUrl, { signal: controller.signal });
    clearTimeout(timeout);
    if (!resp.ok) throw new Error(`LLM server returned ${resp.status}`);
    const json = await resp.json() as { data?: Array<{ id: string }> };
    const models = json.data?.filter(m => !m.id.includes('embedding')) || [];
    if (models.length === 0) {
      throw new Error('LLM_MODEL not configured and no models found on LLM server. Set LLM_MODEL or load a model in LMStudio.');
    }
    return models[0].id;
  } catch (err: any) {
    clearTimeout(timeout);
    if (err.message?.includes('LLM_MODEL')) throw err;
    throw new Error(`LLM_MODEL not configured and cannot auto-detect from ${modelsUrl}: ${err.message}`);
  }
}

/**
 * Attempt LLM health check and wire TagAnalyzer + ClassifyService + EmbeddingService.
 * Fire-and-forget — never blocks module startup. Errors are silently logged.
 * If init fails, retries every 60s until LLM becomes available.
 *
 * @param dispatcher - MemoryToolDispatcher to wire services into
 * @param taskWorker - TaskWorker to wire TagAnalyzer + EmbeddingService into
 * @param logger - Module logger
 */
export function initLLMInBackground(
  dispatcher: MemoryToolDispatcher,
  taskWorker: TaskWorker | null,
  logger: Logger,
): void {
  /** Retry interval in ms (60s). */
  const RETRY_INTERVAL_MS = 60_000;
  let retryTimer: ReturnType<typeof setInterval> | null = null;

  const doInit = async (): Promise<boolean> => {
    try {
      const llmConfig = await buildLLMConfig();
      logger.info({ provider: llmConfig.provider, model: llmConfig.model }, '[LLMInitializer] Resolved LLM config');

      const healthUrl = llmConfig.baseUrl.replace(/\/v1\/?$/, '') + '/v1/models';
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 5000);
      const healthResp = await fetch(healthUrl, { signal: controller.signal });
      clearTimeout(timeout);

      if (!healthResp.ok) {
        logger.info({ provider: llmConfig.provider }, 'TagAnalyzer LLM not reachable — will retry in 60s');
        return false;
      }

      const llmService = new LLMService(llmConfig);

      taskWorker?.setLlmService(llmService);

      const tagAnalyzer = new TagAnalyzerService(llmService, logger);
      dispatcher.setTagAnalyzer(tagAnalyzer);
      taskWorker?.setTagAnalyzer(tagAnalyzer);
      logger.info({ provider: llmConfig.provider, model: llmConfig.model }, 'TagAnalyzerService initialized');

      const classifyService = new ClassifyService(llmService);
      dispatcher.setClassifyService(classifyService);
      logger.info('ClassifyService initialized — Smart KB Ingest enabled');

      // SA4E-107: Wire CodeEnrichmentHandler into TaskWorker for LLM enrichment of code symbols
      try {
        const { CodeEnrichmentHandler } = await import('../../../engine/enrichment/CodeEnrichmentHandler.js');
        const { getAdminAdapter } = await import('../../../admin/db/core.js');
        const adapter = getAdminAdapter();
        const enrichHandler = new CodeEnrichmentHandler(adapter, llmService, logger);
        taskWorker?.setCodeEnrichmentHandler(enrichHandler);
        logger.info('CodeEnrichmentHandler initialized — LLM code enrichment enabled');
      } catch (err) {
        logger.warn({ err }, '[LLMInitializer] CodeEnrichmentHandler init failed (non-fatal)');
      }

      try {
        const embSvc = EmbeddingService.getInstance();
        taskWorker?.setEmbeddingService(embSvc);
        dispatcher.setEmbeddingAvailable(true);
      } catch (err) { logger.debug({ err }, '[LLMInitializer] ONNX not available '); }

      return true;
    } catch (err) {
      logger.error({ err }, '[LLMInitializer] LLM initialization FAILED — will retry in 60s');
      return false;
    }
  };

  // First attempt
  doInit().then(success => {
    if (success) return;
    // Schedule periodic retry until LLM connects
    logger.info('[LLMInitializer] Scheduling periodic LLM health check (every 60s)');
    retryTimer = setInterval(async () => {
      logger.debug('[LLMInitializer] Retrying LLM connection...');
      const ok = await doInit();
      if (ok && retryTimer) {
        clearInterval(retryTimer);
        retryTimer = null;
        logger.info('[LLMInitializer] LLM connected after retry — periodic check stopped');
      }
    }, RETRY_INTERVAL_MS);
  });
}

/**
 * IT-08: TagAnalyzerService Integration Test — Chunking
 * Tests for automatic chunking when content exceeds context window.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { TagAnalyzerService } from '../analyzer.js';
import { LLMService } from '../LLMService.js';
import type { TaskWorkerConfig } from '../../task-queue/TaskWorkerConfig.js';

const chunkConfig: Partial<TaskWorkerConfig> = {
  llmChunkSize: 6000,
  llmChunkOverlap: 200,
};

describe('IT-08: Chunking integration', () => {
  let llm: LLMService;
  let svc: TagAnalyzerService;

  beforeEach(() => {
    llm = new LLMService({ provider: 'ollama', model: 'test', maxTokens: 2048 });
    svc = new TagAnalyzerService(llm, undefined, chunkConfig as any);
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('activates chunking for content exceeding context window', async () => {
    const spy = vi.spyOn(llm, 'complete')
      .mockResolvedValueOnce({
        content: JSON.stringify({ tags: [{ tag: 'chunk-one-tag', category: 'feature', confidence: 0.9, reason: 'first' }], summary: 'First chunk summary', business_entities: ['E1'], actors: ['A1'], business_rules: ['R1'] }),
        model: 'test', provider: 'ollama',
      })
      .mockResolvedValueOnce({
        content: JSON.stringify({ tags: [{ tag: 'chunk-two-tag', category: 'feature', confidence: 0.9, reason: 'second' }], summary: 'Second chunk summary', business_entities: ['E2'], actors: ['A2'], business_rules: ['R2'] }),
        model: 'test', provider: 'ollama',
      })
      .mockResolvedValueOnce({
        content: JSON.stringify({ tags: [{ tag: 'chunk-three-tag', category: 'feature', confidence: 0.9, reason: 'third' }], summary: 'Third chunk summary', business_entities: ['E3'], actors: ['A3'], business_rules: ['R3'] }),
        model: 'test', provider: 'ollama',
      });

    // 15000 chars will trigger chunking (chunkSize=6000)
    const content = 'X'.repeat(15000);
    const result = await svc.analyzeTags(content);

    // LLM should have been called 3 times (3 chunks)
    expect(spy).toHaveBeenCalledTimes(3);

    // Tags from all chunks should be present (merged)
    expect(result.appliedTags).toContain('chunk-one-tag');
    expect(result.appliedTags).toContain('chunk-two-tag');
    expect(result.appliedTags).toContain('chunk-three-tag');

    // Summary from first chunk only
    expect(result.summary).toBe('First chunk summary');

    // Entities from all chunks (union, deduplicated)
    expect(result.business_entities.length).toBeGreaterThanOrEqual(3);
  });

  it('does not chunk content within context window', async () => {
    const spy = vi.spyOn(llm, 'complete').mockResolvedValueOnce({
      content: JSON.stringify({ tags: [{ tag: 'single-tag', category: 'feature', confidence: 0.9, reason: 'single' }] }),
      model: 'test', provider: 'ollama',
    });

    // 3000 chars is well within context window (estimatedTokens=1000 < maxTokens=2048)
    const result = await svc.analyzeTags('Y'.repeat(3000));
    expect(spy).toHaveBeenCalledTimes(1);
    expect(result.appliedTags).toContain('single-tag');
  });

  it('handles empty content gracefully (no LLM call)', async () => {
    const spy = vi.spyOn(llm, 'complete');
    const result = await svc.analyzeTags('');
    expect(spy).not.toHaveBeenCalled();
    expect(result.appliedTags).toEqual([]);
    expect(result.fallbackUsed).toBe(false);
  });
});

