/**
 * PBT-02: safeParseStructuredMap — Correctness Properties
 * Property-based tests verifying robustness for null, invalid, and valid JSON inputs.
 */
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import { safeParseStructuredMap } from '../types.js';

describe('PBT-02: safeParseStructuredMap correctness properties', () => {
  // P1: Never throws
  it('never throws for any input', () => {
    fc.assert(
      fc.property(fc.constantFrom(null, undefined, '', '{}', '[]', 'invalid json', 'null', 'true', '42'), (input) => {
        expect(() => safeParseStructuredMap(input as any)).not.toThrow();
      }),
    );
    // Random string inputs
    fc.assert(
      fc.property(fc.string(), (input) => {
        expect(() => safeParseStructuredMap(input)).not.toThrow();
      }),
    );
  });

  // P2: Always returns object
  it('always returns an object (never array/primitive)', () => {
    fc.assert(
      fc.property(fc.string({ minLength: 0, maxLength: 500 }), (input) => {
        const result = safeParseStructuredMap(input);
        expect(result).toBeTruthy();
        expect(typeof result).toBe('object');
        expect(Array.isArray(result)).toBe(false);
      }),
    );
  });

  // P3-P5: Null, empty string, '{}' preservation
  it('returns empty object for null, empty string, and empty JSON', () => {
    expect(safeParseStructuredMap(null)).toEqual({});
    expect(safeParseStructuredMap(undefined)).toEqual({});
    expect(safeParseStructuredMap('')).toEqual({});
    expect(safeParseStructuredMap('{}')).toEqual({});
  });

  // P6: Valid JSON passthrough
  it('preserves all fields from valid JSON objects', () => {
    const input = '{"tags":["auth"],"summary":"test","business_entities":["User"],"extraction_meta":{"model":"qwen","fallback_used":false}}';
    const result = safeParseStructuredMap(input);
    expect(result.tags).toEqual(['auth']);
    expect(result.summary).toBe('test');
    expect(result.business_entities).toEqual(['User']);
    expect(result.extraction_meta?.model).toBe('qwen');
    expect(result.extraction_meta?.fallback_used).toBe(false);
  });

  // P7: Invalid JSON safety
  it('returns empty object for unparseable strings', () => {
    fc.assert(
      fc.property(fc.string({ minLength: 1, maxLength: 200 }), (input) => {
        // Skip inputs that happen to be valid JSON objects
        if (input === '{}' || input.startsWith('{') && input.endsWith('}')) return;
        const result = safeParseStructuredMap(input);
        expect(typeof result).toBe('object');
        expect(Array.isArray(result)).toBe(false);
      }),
    );
  });

  // P8: Array rejection
  it('returns empty object for JSON arrays', () => {
    expect(safeParseStructuredMap('[]')).toEqual({});
    expect(safeParseStructuredMap('["a","b"]')).toEqual({});
    expect(safeParseStructuredMap('[{"tag":"test"}]')).toEqual({});
  });

  // Edge: primitive JSON values
  it('returns empty object for JSON primitives', () => {
    expect(safeParseStructuredMap('null')).toEqual({});
    expect(safeParseStructuredMap('"string"')).toEqual({});
    expect(safeParseStructuredMap('42')).toEqual({});
    expect(safeParseStructuredMap('true')).toEqual({});
  });
});

/**
 * TagAnalyzerService — SA4E-47
 * LLM-based automatic tag assignment + expanded extraction for KB entries.
 * Supports context chain, chunking, and enhanced JSON parsing.
 */

import type { LLMMessage, ContextChainInput } from './types.js';
import { safeParseStructuredMap } from './types.js';
import { LLMService } from './LLMService.js';
import type { Logger } from 'pino';
import { SYSTEM_PROMPT, DEFAULT_TAXONOMY, KNOWN_KEYWORDS } from './prompts.js';
import type { TaskWorkerConfig } from '../task-queue/TaskWorkerConfig.js';

export interface TagSuggestion {
  tag: string;
  category: string;
  confidence: number;
  reason: string;
}

export interface TagAnalysisResult {
  appliedTags: string[];
  suggestedTags: TagSuggestion[];
  fallbackUsed: boolean;
  /** SA4E-155: Error message when fallback was triggered by LLM failure */
  fallbackReason?: string;
  /** SA4E-47: 1-3 sentence summary (max 500 chars) */
  summary: string;
  /** SA4E-47: Extracted business entities (max 5) */
  business_entities: string[];
  /** SA4E-47: Extracted actors/roles (max 5) */
  actors: string[];
  /** SA4E-47: Extracted business rules (max 10) */
  business_rules: string[];
}

export interface TagAnalyzeOptions {
  taxonomyCategories?: string[];
  threshold?: number;
  autoApply?: boolean;
}

export class TagAnalyzerService {
  private llmService: LLMService;
  private taxonomy: Record<string, string[]>;
  private allValidTags: Set<string>;
  private logger?: Logger;
  private workerConfig?: TaskWorkerConfig;

  constructor(llmService: LLMService, logger?: Logger, workerConfig?: TaskWorkerConfig) {
    this.llmService = llmService;
    this.taxonomy = DEFAULT_TAXONOMY;
    this.allValidTags = new Set(Object.values(this.taxonomy).flat());
    this.logger = logger;
    this.workerConfig = workerConfig;
  }

  // ── Public API ──

  async analyzeTags(
    content: string,
    options?: TagAnalyzeOptions,
    context?: ContextChainInput | null,
  ): Promise<TagAnalysisResult> {
    if (!content || content.trim().length < 10) {
      return { appliedTags: [], suggestedTags: [], fallbackUsed: false,
        summary: '', business_entities: [], actors: [], business_rules: [] };
    }
    const threshold = options?.threshold ?? 0.7;
    const autoApply = options?.autoApply ?? true;
    try {
      const maxTokens = this.llmService.getConfig().maxTokens ?? 2048;
      const estimatedTokens = Math.ceil(content.length / 3);
      const chunkSize = this.workerConfig?.llmChunkSize ?? 6000;
      if (estimatedTokens > maxTokens && content.length > chunkSize) {
        return this.analyzeWithChunking(content, context ?? null,
          this.workerConfig?.llmChunkSize ?? 6000,
          this.workerConfig?.llmChunkOverlap ?? 200);
      }
      const llmResult = await this.analyzeWithLLM(content, options, context ?? null);
      const normalized = this.normalizeTags(llmResult.suggestions);
      return this.applyThresholdWithExtended(normalized, threshold, autoApply, llmResult);
    } catch (err) {
      this.logger?.warn({ err, component: 'TagAnalyzerService' }, 'LLM analysis failed, using fallback');
      const fallback = this.fallbackWithExtended(content, threshold);
      fallback.fallbackReason = err instanceof Error ? err.message : String(err);
      return fallback;
    }
  }

  // ── LLM Communication ──

  private async analyzeWithLLM(
    content: string,
    options?: TagAnalyzeOptions,
    context?: ContextChainInput | null,
  ): Promise<{ suggestions: TagSuggestion[]; summary: string; business_entities: string[]; actors: string[]; business_rules: string[] }> {
    const userPrompt = this.buildContextPrompt(context, content);
    const messages: LLMMessage[] = [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: userPrompt },
    ];
    const timeoutMs = this.workerConfig?.llmTimeout ?? 30000;
    this.logger?.info({ contentLen: content.length, timeoutMs, model: this.llmService.getConfig().model },
      '[TagAnalyzer] Calling LLM...');
    const response = await Promise.race([
      this.llmService.complete(messages),
      this.timeout(timeoutMs),
    ]);
    this.logger?.info({ responseLen: response.content.length }, '[TagAnalyzer] LLM responded');
    return this.parseEnhancedResponse(response.content);
  }

  // ── Context Prompt Builder ──

  buildContextPrompt(context?: ContextChainInput | null, content?: string): string {
    if (!context) return `/no_think\n\n${content}`;
    const contextBlock = `[Previous section context]\nSummary: ${context.summary || ''}`
      + (context.business_entities?.length ? `\nBusiness entities: ${context.business_entities.join(', ')}` : '')
      + (context.actors?.length ? `\nActors: ${context.actors.join(', ')}` : '')
      + (context.business_rules?.length ? `\nBusiness rules: ${context.business_rules.slice(0, 3).join('; ')}` : '');
    return `/no_think\n\n${contextBlock}\n\n---\n\n${content}`;
  }

  // ── Response Parsing ──

  parseEnhancedResponse(llmOutput: string): {
    suggestions: TagSuggestion[];
    summary: string;
    business_entities: string[];
    actors: string[];
    business_rules: string[];
  } {
    const defaults = { suggestions: [] as TagSuggestion[], summary: '',
      business_entities: [] as string[], actors: [] as string[], business_rules: [] as string[] };
    if (!llmOutput || llmOutput.trim().length === 0) return defaults;

    const jsonMatch = llmOutput.match(/\{[\s\S]*"tags"[\s\S]*\}/);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[0]);
        const suggestions = (parsed.tags || parsed.suggestions || [])
          .filter((t: any) => t.tag && t.confidence !== undefined)
          .map((t: any) => ({
            tag: String(t.tag).toLowerCase().trim().replace(/\s+/g, '-'),
            category: String(t.category || 'feature'),
            confidence: Number(t.confidence),
            reason: String(t.reason || ''),
          }))
          .filter((t: TagSuggestion) => t.tag.length >= 3 && t.tag.length <= 50);
        return {
          suggestions,
          summary: String(parsed.summary || '').slice(0, 500),
          business_entities: (parsed.business_entities || [])
            .filter((e: any) => typeof e === 'string' && e.length <= 100).slice(0, 5),
          actors: (parsed.actors || [])
            .filter((a: any) => typeof a === 'string' && a.length <= 100).slice(0, 5),
          business_rules: (parsed.business_rules || [])
            .filter((r: any) => typeof r === 'string' && r.length <= 300).slice(0, 10),
        };
      } catch (err) { this.logger?.debug({ err }, '[analyzer] LLM parse failed, falling through to regex'); }
    }

    const tagPattern = /["']([a-z][a-z0-9-]{4,40}[a-z0-9])["']/g;
    const found: string[] = [];
    let m;
    while ((m = tagPattern.exec(llmOutput)) !== null) {
      const tag = m[1];
      if (tag.includes('-') && !['let-me', 'wait-the', 'so-maybe', 'that-s'].includes(tag)) {
        found.push(tag);
      }
    }
    return { ...defaults, suggestions: [...new Set(found)].slice(-3).map(tag => ({
      tag, category: 'feature', confidence: 0.85, reason: 'extracted from reasoning',
    })) };
  }

  // ── Tag Normalization (map LLM tags to taxonomy) ──

  private normalizeTags(suggestions: TagSuggestion[]): TagSuggestion[] {
    return suggestions.map(s => {
      if (this.allValidTags.has(s.tag)) return s;
      const keywordMatch = KNOWN_KEYWORDS[s.tag] ?? KNOWN_KEYWORDS[s.tag.replace(/-/g, ' ')];
      if (keywordMatch) return { ...s, tag: keywordMatch };
      // Fuzzy match: only consider valid tags ≥5 chars to avoid false positives
      // from short taxonomy entries (e.g. 'low' matching 'auth-flow-login')
      for (const validTag of this.allValidTags) {
        if (validTag.length < 5) continue;
        if (s.tag.includes(validTag) || validTag.includes(s.tag)) {
          return { ...s, tag: validTag, confidence: Math.min(s.confidence, 0.7) };
        }
      }
      // Unknown tags retain original confidence — LLM-assigned confidence is authoritative
      return s;
    });
  }

  // ── Threshold & Fallback ──

  private applyThresholdWithExtended(
    suggestions: TagSuggestion[],
    threshold: number,
    autoApply: boolean,
    extended?: { summary: string; business_entities: string[]; actors: string[]; business_rules: string[] },
  ): TagAnalysisResult {
    const applied = autoApply ? suggestions.filter(t => t.confidence >= threshold) : [];
    const suggested = suggestions.filter(t => t.confidence < threshold);
    return {
      appliedTags: applied.map(t => t.tag).slice(0, 6),
      suggestedTags: suggested,
      fallbackUsed: false,
      summary: extended?.summary ?? '',
      business_entities: extended?.business_entities ?? [],
      actors: extended?.actors ?? [],
      business_rules: extended?.business_rules ?? [],
    };
  }

  private fallbackWithExtended(content: string, _threshold: number): TagAnalysisResult {
    const base = this.fallbackKeywordExtraction(content, _threshold);
    return { ...base, summary: '', business_entities: [], actors: [], business_rules: [] };
  }

  // ── Chunking ──

  chunkContent(
    content: string,
    chunkSize = 6000,
    overlap = 200,
  ): { chunks: string[]; totalChunks: number } {
    if (content.length <= chunkSize) {
      return { chunks: [content], totalChunks: 1 };
    }
    // Clamp overlap to prevent excessive/infinite loops when overlap >= chunkSize
    // Minimum step of 20% chunkSize ensures reasonable chunk count
    const maxOverlap = Math.max(Math.floor(chunkSize * 0.8), 1);
    const safeOverlap = Math.min(overlap, maxOverlap);
    const chunks: string[] = [];
    let start = 0;
    while (start < content.length) {
      const end = Math.min(start + chunkSize, content.length);
      chunks.push(content.slice(start, end));
      start = end - safeOverlap;
      if (start >= content.length - safeOverlap) break;
    }
    return { chunks, totalChunks: chunks.length };
  }

  async analyzeWithChunking(
    content: string,
    context?: ContextChainInput | null,
    chunkSize?: number,
    overlap?: number,
  ): Promise<TagAnalysisResult> {
    const { chunks } = this.chunkContent(content, chunkSize, overlap);
    this.logger?.info({ totalChunks: chunks.length, chunkSize, component: 'TagAnalyzerService' },
      'Chunking activated');
    const results: TagAnalysisResult[] = [];
    for (const chunk of chunks) {
      try {
        const ctx = results.length === 0 ? context : null;
        const llmResult = await this.analyzeWithLLM(chunk, undefined, ctx);
        const normalized = this.normalizeTags(llmResult.suggestions);
        results.push(this.applyThresholdWithExtended(normalized, 0.7, true, llmResult));
      } catch (err) {
        this.logger?.warn({ err, chunkIdx: results.length, component: 'TagAnalyzerService' }, 'Chunk LLM failed, using fallback');
        results.push({ ...this.fallbackKeywordExtraction(chunk, 0.7), summary: '', business_entities: [], actors: [], business_rules: [] });
      }
    }
    return {
      appliedTags: [...new Set(results.flatMap(r => r.appliedTags))].slice(0, 6),
      suggestedTags: results[0]?.suggestedTags ?? [],
      fallbackUsed: results.some(r => r.fallbackUsed),
      summary: results[0]?.summary ?? '',
      business_entities: [...new Set(results.flatMap(r => r.business_entities))].slice(0, 5),
      actors: [...new Set(results.flatMap(r => r.actors))].slice(0, 5),
      business_rules: [...new Set(results.flatMap(r => r.business_rules))].slice(0, 10),
    };
  }

  // ── Helpers ──

  private fallbackKeywordExtraction(content: string, _threshold: number): TagAnalysisResult {
    const lower = content.toLowerCase();
    const found: string[] = [];
    for (const [keyword, tag] of Object.entries(KNOWN_KEYWORDS)) {
      if (lower.includes(keyword) && !found.includes(tag)) found.push(tag);
    }
    if (lower.startsWith('decision:') || lower.includes('we decided')) {
      if (!found.includes('decision')) found.push('decision');
    }
    if (lower.includes('error') || lower.includes('bug') || lower.includes('fix')) {
      if (!found.includes('error-pattern')) found.push('error-pattern');
    }
    return { appliedTags: found.slice(0, 6), suggestedTags: [],
      fallbackUsed: true, summary: '', business_entities: [], actors: [], business_rules: [] };
  }

  private filterTaxonomy(categories?: string[]): Record<string, string[]> {
    if (!categories || categories.length === 0) return this.taxonomy;
    const filtered: Record<string, string[]> = {};
    for (const cat of categories) {
      if (this.taxonomy[cat]) filtered[cat] = this.taxonomy[cat];
    }
    return Object.keys(filtered).length > 0 ? filtered : this.taxonomy;
  }

  private timeout(ms: number): Promise<never> {
    return new Promise((_, reject) =>
      setTimeout(() => reject(new Error('LLM timeout')), ms));
  }
}

export { safeParseStructuredMap };

/**
 * Ollama LLM adapter — local inference via REST API.
 * Handles qwen3 "thinking" mode: appends /no_think and falls back to thinking field.
 */

import type { LLMAdapter, LLMConfig, LLMMessage, LLMResponse } from './types.js';

export class OllamaAdapter implements LLMAdapter {
  async complete(messages: LLMMessage[], config: LLMConfig): Promise<LLMResponse> {
    const url = `${config.baseUrl}/api/chat`;

    // For qwen3 models: disable thinking mode by appending /no_think
    const isQwen3 = config.model.includes('qwen3');
    const processedMessages = messages.map(m => {
      if (isQwen3 && m.role === 'system') {
        return { role: m.role, content: m.content + ' /no_think' };
      }
      return { role: m.role, content: m.content };
    });
    if (isQwen3 && !messages.some(m => m.role === 'system')) {
      processedMessages.unshift({ role: 'system', content: 'Be concise. /no_think' });
    }

    const body = {
      model: config.model,
      messages: processedMessages,
      stream: false,
      options: {
        temperature: config.temperature ?? 0.3,
        num_predict: config.maxTokens ?? 200,
      },
    };

    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

    if (!res.ok) throw new Error(`Ollama error: ${res.status} ${await res.text()}`);
    const data = await res.json() as any;

    // qwen3 puts response in "thinking" when content is empty
    const content = data.message?.content || data.message?.thinking || '';

    return {
      content,
      model: config.model,
      provider: 'ollama',
      tokensUsed: data.eval_count,
    };
  }

  async isAvailable(config: LLMConfig): Promise<boolean> {
    try {
      const res = await fetch(`${config.baseUrl}/api/tags`, { signal: AbortSignal.timeout(3000) });
      return res.ok;
    } catch { return false; }
  }
}

/**
 * OpenAI-compatible adapter — works for OpenAI, Azure, vLLM, LM Studio, etc.
 */

import type { LLMAdapter, LLMConfig, LLMMessage, LLMResponse } from './types.js';

export class OpenAIAdapter implements LLMAdapter {
  async complete(messages: LLMMessage[], config: LLMConfig): Promise<LLMResponse> {
    const url = `${config.baseUrl}/chat/completions`;
    const body: Record<string, any> = {
      model: config.model,
      messages,
      temperature: config.temperature ?? 0.3,
      max_tokens: config.maxTokens ?? 500,
      chat_template_kwargs: { enable_thinking: false },
    };

    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (config.apiKey) headers['Authorization'] = `Bearer ${config.apiKey}`;

    const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
    if (!res.ok) throw new Error(`OpenAI error: ${res.status} ${await res.text()}`);
    const data = await res.json() as any;

    const msg = data.choices?.[0]?.message;
    const content = msg?.content || msg?.reasoning_content || '';

    return {
      content,
      model: config.model,
      provider: config.provider,
      tokensUsed: data.usage?.total_tokens,
    };
  }

  async isAvailable(config: LLMConfig): Promise<boolean> {
    try {
      const headers: Record<string, string> = {};
      if (config.apiKey) headers['Authorization'] = `Bearer ${config.apiKey}`;
      const res = await fetch(`${config.baseUrl}/models`, { headers, signal: AbortSignal.timeout(3000) });
      return res.ok;
    } catch { return false; }
  }
}

import { KnowledgeEntry } from '../models.js';
import { PiiDetector } from './detectors/PiiDetector.js';
import { CredentialDetector } from './detectors/CredentialDetector.js';
import { ContentMasker } from './maskers/ContentMasker.js';
import { AllowlistService } from './services/AllowlistService.js';
import { AuditService } from './services/AuditService.js';
import { ConfigCacheService } from './services/ConfigCacheService.js';
import {
  DetectionResult, MaskedEntry, MaskingOptions,
  SensitivityLevel,
} from './models/MaskingTypes.js';

const ROLE_ACCESS: Record<string, SensitivityLevel[]> = {
  ADMIN: ['PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED'],
  DEVELOPER: ['PUBLIC'],
  USER: ['PUBLIC'],
  EXTERNAL: ['PUBLIC'],
};

/**
 * Main orchestrator for the masking pipeline.
 */
export class MaskingMiddleware {
  private piiDetector: PiiDetector;
  private credDetector: CredentialDetector;
  private masker: ContentMasker;
  private allowlist: AllowlistService;
  private audit: AuditService;
  private configCache: ConfigCacheService;

  constructor(
    configCache: ConfigCacheService,
    allowlist: AllowlistService,
    audit: AuditService
  ) {
    this.configCache = configCache;
    this.allowlist = allowlist;
    this.audit = audit;
    this.masker = new ContentMasker();
    this.piiDetector = new PiiDetector();
    this.credDetector = new CredentialDetector();
  }

  applyMasking(
    entries: KnowledgeEntry[],
    requesterRole: string,
    requesterId: string,
    options?: MaskingOptions
  ): MaskedEntry[] {
    const reveal = options?.reveal ?? false;
    const results: MaskedEntry[] = [];
    for (const entry of entries) {
      const masked = this.processEntry(entry, requesterRole, requesterId, reveal);
      if (!masked.hidden) results.push(masked);
    }
    return results;
  }

  private processEntry(
    entry: KnowledgeEntry, role: string, requesterId: string, reveal: boolean
  ): MaskedEntry {
    if (this.allowlist.isAllowlisted(entry)) {
      this.audit.logEvent({
        entry_id: entry.id, requester_id: requesterId, requester_role: role,
        action: 'skip_allowlist', patterns_matched: '', sensitivity_level: 'PUBLIC',
      });
      return this.toMaskedEntry(entry, 'PUBLIC', false, []);
    }

    const level = this.classifyEntry(entry);

    if (!this.canAccess(role, level)) {
      this.audit.logEvent({
        entry_id: entry.id, requester_id: requesterId, requester_role: role,
        action: 'hide', patterns_matched: '', sensitivity_level: level,
      });
      return { id: entry.id, content: '', summary: '', masking_applied: true,
        sensitivity_level: level, masked_patterns: [], hidden: true };
    }

    const pii = this.detectSafe(() => this.piiDetector.detect(entry.content));
    const creds = this.detectSafe(() => this.credDetector.detect(entry.content));
    const all = [...pii, ...creds];
    const patterns = [...new Set(all.map(d => d.type))];

    let content = entry.content;
    if (all.length > 0) {
      const toMask = all.filter(d => {
        if (d.category === 'credential') return !(reveal && role === 'ADMIN');
        if (d.category === 'pii') return role !== 'ADMIN';
        return true;
      });
      content = this.masker.applyMasking(content, toMask, role, level, reveal);
    }

    if (level === 'CONFIDENTIAL' && role !== 'ADMIN') {
      this.audit.logEvent({
        entry_id: entry.id, requester_id: requesterId, requester_role: role,
        action: 'summary_only', patterns_matched: patterns.join(','), sensitivity_level: level,
      });
      return this.toMaskedEntry(entry, level, true, patterns, entry.summary);
    }

    if (all.length > 0) {
      const action = reveal ? 'reveal' : creds.length > 0 ? 'mask_credential' : 'mask_pii';
      this.audit.logEvent({
        entry_id: entry.id, requester_id: requesterId, requester_role: role,
        action, patterns_matched: patterns.join(','), sensitivity_level: level,
      });
    }

    return this.toMaskedEntry(entry, level, all.length > 0, patterns, content);
  }

  private classifyEntry(entry: KnowledgeEntry): SensitivityLevel {
    const creds = this.credDetector.detect(entry.content);
    if (creds.length > 0) return 'RESTRICTED';
    const pii = this.piiDetector.detect(entry.content);
    if (pii.length > 0) return 'INTERNAL';
    return 'PUBLIC';
  }

  private canAccess(role: string, level: SensitivityLevel): boolean {
    if (role === 'ADMIN') return true;
    if (level === 'RESTRICTED') return false;
    return true;
  }

  private detectSafe(fn: () => DetectionResult[]): DetectionResult[] {
    try { return fn(); } catch { return []; }
  }

  private toMaskedEntry(
    e: KnowledgeEntry, level: SensitivityLevel,
    masked: boolean, patterns: string[], content?: string
  ): MaskedEntry {
    return {
      id: e.id, content: content ?? e.content, summary: e.summary,
      masking_applied: masked, sensitivity_level: level,
      masked_patterns: patterns, hidden: false,
    };
  }
}

/**
 * Migration 001: Add scope and user_id columns to knowledge_entries.
 * Cross-engine: uses information_schema for PostgreSQL, pragma_table_info for SQLite.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';

async function columnExists(db: DatabaseAdapter, table: string, column: string): Promise<boolean> {
  try {
    // PostgreSQL: information_schema
    const pg = await db.allAsync<{ column_name: string }>(
      `SELECT column_name FROM information_schema.columns WHERE table_name = $1 AND column_name = $2`,
      [table, column],
    );
    if (pg.length > 0) return true;
  } catch (err) {
    // SQLite fallback
    try {
      const lite = await db.allAsync<{ name: string }>(
        `SELECT name FROM pragma_table_info('${table}') WHERE name = ?`,
        [column],
      );
      return lite.length > 0;
    } catch (err) { return false; }
  }
  return false;
}

export async function migrate001AddScopeColumns(db: DatabaseAdapter): Promise<void> {
  if (await columnExists(db, 'knowledge_entries', 'scope')) return;

  await db.execAsync(`ALTER TABLE knowledge_entries ADD COLUMN scope TEXT NOT NULL DEFAULT 'USER'`);
  await db.execAsync(`ALTER TABLE knowledge_entries ADD COLUMN user_id TEXT DEFAULT NULL`);
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_scope ON knowledge_entries(scope)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_user_id ON knowledge_entries(user_id)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_scope_user ON knowledge_entries(scope, user_id)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
}

/**
 * Migration 002: Add evolution scoring columns and tables.
 * Cross-engine: PostgreSQL + SQLite compatible.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';

async function columnExists(db: DatabaseAdapter, table: string, column: string): Promise<boolean> {
  try {
    const pg = await db.allAsync<{ column_name: string }>(
      `SELECT column_name FROM information_schema.columns WHERE table_name = $1 AND column_name = $2`,
      [table, column],
    );
    if (pg.length > 0) return true;
  } catch (err) {
    try {
      const lite = await db.allAsync<{ name: string }>(
        `SELECT name FROM pragma_table_info('${table}') WHERE name = ?`,
        [column],
      );
      return lite.length > 0;
    } catch (err) { return false; }
  }
  return false;
}

async function tableExists(db: DatabaseAdapter, table: string): Promise<boolean> {
  try {
    // PostgreSQL
    const pg = await db.allAsync<{ table_name: string }>(
      `SELECT table_name FROM information_schema.tables WHERE table_name = $1`,
      [table],
    );
    if (pg.length > 0) return true;
  } catch (err) {
    try {
      const lite = await db.allAsync<{ name: string }>(
        `SELECT name FROM sqlite_master WHERE type='table' AND name=?`,
        [table],
      );
      return lite.length > 0;
    } catch (err) { return false; }
  }
  return false;
}

export async function migrate002AddEvolutionColumns(db: DatabaseAdapter): Promise<void> {
  if (!await columnExists(db, 'knowledge_entries', 'needs_verification')) {
    await db.execAsync(`ALTER TABLE knowledge_entries ADD COLUMN needs_verification INTEGER NOT NULL DEFAULT 0`);
  }
  if (!await columnExists(db, 'knowledge_entries', 'epoch_id')) {
    await db.execAsync(`ALTER TABLE knowledge_entries ADD COLUMN epoch_id TEXT DEFAULT NULL`);
  }
  if (!await columnExists(db, 'knowledge_entries', 'superseded_by')) {
    await db.execAsync(`ALTER TABLE knowledge_entries ADD COLUMN superseded_by INTEGER DEFAULT NULL`);
  }

  if (!await tableExists(db, 'entry_outcomes')) {
    await db.execAsync(`
      CREATE TABLE entry_outcomes (
        id SERIAL PRIMARY KEY,
        entry_id INTEGER NOT NULL,
        outcome TEXT NOT NULL CHECK (outcome IN ('success', 'fail', 'partial')),
        agent_name TEXT DEFAULT NULL,
        context TEXT DEFAULT NULL,
        created_at TEXT NOT NULL DEFAULT (current_timestamp),
        FOREIGN KEY (entry_id) REFERENCES knowledge_entries(id) ON DELETE CASCADE
      )
    `);
  }

  if (!await tableExists(db, 'decay_config')) {
    await db.execAsync(`
      CREATE TABLE decay_config (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_at TEXT NOT NULL DEFAULT (current_timestamp)
      )
    `);
  }

  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_expires_at ON knowledge_entries(expires_at)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_updated_at ON knowledge_entries(updated_at)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_ke_needs_verification ON knowledge_entries(needs_verification)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_entry_outcomes_entry_id ON entry_outcomes(entry_id)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_search_log_failed ON search_log(result_count)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }

  // INSERT OR IGNORE is SQLite; use ON CONFLICT for cross-engine
  await db.execAsync(`INSERT INTO decay_config (key, value) VALUES ('half_life_days', '30') ON CONFLICT (key) DO NOTHING`);
  await db.execAsync(`INSERT INTO decay_config (key, value) VALUES ('enable_predictive', 'false') ON CONFLICT (key) DO NOTHING`);
  await db.execAsync(`INSERT INTO decay_config (key, value) VALUES ('include_superseded', 'false') ON CONFLICT (key) DO NOTHING`);
}

/**
 * Migration 003: Create pending_tasks table.
 * Cross-engine: PostgreSQL + SQLite compatible.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';

export async function migrate003PendingTasks(db: DatabaseAdapter): Promise<void> {
  // Check table existence cross-engine
  let exists = false;
  try {
    const pg = await db.allAsync<{ table_name: string }>(
      `SELECT table_name FROM information_schema.tables WHERE table_name = $1`,
      ['pending_tasks'],
    );
    exists = pg.length > 0;
  } catch (err) {
    try {
      const lite = await db.allAsync<{ name: string }>(
        `SELECT name FROM sqlite_master WHERE type='table' AND name='pending_tasks'`,
      );
      exists = lite.length > 0;
    } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  }

  if (exists) return;

  await db.execAsync(`
    CREATE TABLE pending_tasks (
      id SERIAL PRIMARY KEY,
      task_type TEXT NOT NULL,
      entry_id INTEGER NOT NULL,
      status TEXT NOT NULL DEFAULT 'PENDING',
      payload TEXT NOT NULL,
      error TEXT,
      retry_count INTEGER NOT NULL DEFAULT 0,
      max_retries INTEGER NOT NULL DEFAULT 3,
      created_at TEXT NOT NULL DEFAULT current_timestamp,
      started_at TEXT,
      completed_at TEXT,
      FOREIGN KEY (entry_id) REFERENCES knowledge_entries(id)
    )
  `);
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_pending_tasks_status_created ON pending_tasks(status, created_at)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
  try { await db.execAsync(`CREATE INDEX IF NOT EXISTS idx_pending_tasks_entry_id ON pending_tasks(entry_id)`); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
}

/**
 * Migration 004: Reset PostgreSQL sequences to avoid duplicate key errors.
 * When data was previously inserted with explicit id values (e.g. migrated from SQLite),
 * the SERIAL sequences may be out of sync with actual max id values.
 * This migration resets all affected sequences to max(id) + 1.
 * Safe to run multiple times (idempotent). SQLite: no-op.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import pino from 'pino';

const logger = pino({ name: 'migration-004' });

/** Tables with SERIAL primary keys that may have sequence drift. */
const SERIAL_TABLES = [
  'memory_sessions',
  'memory_audit',
  'conversation_turns',
  'knowledge_entries',
  'knowledge_vectors',
  'knowledge_graph_edges',
  'consolidation_log',
  'citations',
  'search_log',
  'entry_outcomes',
  'pending_tasks',
] as const;

export async function migrate004ResetSequences(db: DatabaseAdapter): Promise<void> {
  // Only needed for PostgreSQL — detect by trying pg_get_serial_sequence
  let isPostgres = false;
  try {
    await db.allAsync(`SELECT 1 FROM information_schema.tables LIMIT 1`);
    isPostgres = true;
  } catch { return; } // SQLite — skip

  if (!isPostgres) return;

  for (const table of SERIAL_TABLES) {
    try {
      // Check table exists
      const exists = await db.allAsync<{ table_name: string }>(
        `SELECT table_name FROM information_schema.tables WHERE table_name = $1`,
        [table],
      );
      if (exists.length === 0) continue;

      // Get sequence name for the id column
      const seqRow = await db.getAsync<{ seq: string }>(
        `SELECT pg_get_serial_sequence($1, 'id') as seq`,
        [table],
      );
      if (!seqRow?.seq) continue;

      // Reset to max(id) + 1
      await db.execAsync(
        `SELECT setval('${seqRow.seq}', COALESCE((SELECT MAX(id) FROM ${table}), 0) + 1, false)`,
      );
      logger.info({ table, seq: seqRow.seq }, 'migration-004: sequence reset');
    } catch (err) {
      logger.warn({ table, err }, 'migration-004: could not reset sequence (non-fatal)');
    }
  }
}

/**
 * Migration 006: Add project_id column to pending_tasks.
 * SA4E-164: Eliminates expensive JOIN for per-project task stats.
 *
 * Cross-engine: PostgreSQL + SQLite compatible.
 * Backfills project_id from knowledge_entries for existing tasks.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';

export async function migrate006PendingTasksProjectId(db: DatabaseAdapter): Promise<void> {
  const engine = db.getEngine();

  // Step 1: Add project_id column (idempotent)
  if (engine === 'postgresql') {
    await db.execAsync(`
      ALTER TABLE pending_tasks
      ADD COLUMN IF NOT EXISTS project_id TEXT DEFAULT NULL
    `);
  } else {
    try {
      await db.execAsync(`ALTER TABLE pending_tasks ADD COLUMN project_id TEXT DEFAULT NULL`);
    } catch (err) {
      const msg = (err as Error).message || '';
      if (!msg.includes('duplicate column') && !msg.includes('already exists')) throw err;
    }
  }

  // Step 2: Backfill from knowledge_entries (non-blocking, best effort)
  try {
    await db.runAsync(`
      UPDATE pending_tasks SET project_id = (
        SELECT ke.project_id FROM knowledge_entries ke
        WHERE ke.id = pending_tasks.entry_id
      ) WHERE project_id IS NULL
    `, []);
  } catch (err) {
    // Non-fatal: backfill may fail if entries are deleted
    console.debug('[migration-006] Backfill partial:', (err as Error).message);
  }

  // Step 3: Create index for per-project status queries
  try {
    await db.execAsync(`
      CREATE INDEX IF NOT EXISTS idx_pending_tasks_project_status
      ON pending_tasks (project_id, status)
    `);
  } catch (err) {
    console.debug('[migration-006] Index creation:', (err as Error).message);
  }
}

/**
 * Promotion rules — criteria evaluation for KB entry scope promotion.
 * SA4E-53: migrated from raw better-sqlite3 to DatabaseAdapter async API.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import type { KBScope } from '../models.js';

export interface PromotionCandidate {
  entryId: number;
  currentScope: KBScope;
  targetScope: KBScope;
  reason: string;
  score: number;
}

export interface PromotionConfig {
  minCitations: number;
  minAccessCount: number;
  minQualityScore: number;
  minAgeHours: number;
  minCriteriaMet: number;
  autoApproveToProject: boolean;
}

export const DEFAULT_CONFIG: PromotionConfig = {
  minCitations: 2,
  minAccessCount: 5,
  minQualityScore: 70,
  minAgeHours: 24,
  minCriteriaMet: 2,
  autoApproveToProject: false,
};

/**
 * Evaluate promotion criteria for a candidate entry.
 * SA4E-53: async for PostgreSQL compatibility.
 */
export async function evaluateCriteria(
  adapter: DatabaseAdapter,
  entry: any,
  config: PromotionConfig,
): Promise<{ metCount: number; reasons: string[]; score: number }> {
  const reasons: string[] = [];
  let metCount = 0;
  let score = 0;

  const citationRow = await adapter.getAsync<{ cnt: number }>(
    'SELECT COUNT(*) as cnt FROM citations WHERE entry_id = ?',
    [entry.id],
  );
  const citationCount = citationRow?.cnt ?? 0;

  if (citationCount >= config.minCitations) {
    metCount++;
    reasons.push(`citations=${citationCount}`);
    score += 30;
  }

  if (entry.access_count >= config.minAccessCount) {
    metCount++;
    reasons.push(`access_count=${entry.access_count}`);
    score += 25;
  }

  if (entry.quality_score !== null && entry.quality_score >= config.minQualityScore) {
    metCount++;
    reasons.push(`quality=${entry.quality_score}`);
    score += 25;
  }

  const crossAgentRow = await adapter.getAsync<{ cnt: number }>(
    'SELECT COUNT(DISTINCT cited_by) as cnt FROM citations WHERE entry_id = ?',
    [entry.id],
  );
  const crossAgentCites = crossAgentRow?.cnt ?? 0;

  if (crossAgentCites >= 2) {
    metCount++;
    reasons.push(`cross_agent_cites=${crossAgentCites}`);
    score += 20;
  }

  return { metCount, reasons, score };
}

/**
 * ScopePromotionService — manages KB entry promotion pipeline.
 * SA4E-53: migrated from raw better-sqlite3 to DatabaseAdapter async API for PostgreSQL compatibility.
 */
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import { DialectHelper } from '../../../database/dialect/DialectHelper.js';
import type { Logger } from 'pino';
import {
  type PromotionCandidate, type PromotionConfig, DEFAULT_CONFIG, evaluateCriteria,
} from './rules.js';

export class ScopePromotionService {
  private readonly adapter: DatabaseAdapter;
  private readonly dialect: DialectHelper;
  private readonly logger: Logger;
  private readonly config: PromotionConfig;

  constructor(adapter: DatabaseAdapter, logger: Logger, config?: Partial<PromotionConfig>) {
    this.adapter = adapter;
    this.dialect = new DialectHelper(adapter.getEngine());
    this.logger = logger.child({ service: 'scope-promotion' });
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Ensure promotion queue table exists — must be awaited before use. SA4E-53: async. */
  async ensurePromotionQueueTable(): Promise<void> {
    // DDL default uses engine-specific now expression
    const nowDefault = this.adapter.getEngine() === 'sqlite'
      ? "(datetime('now'))" : 'NOW()';
    await this.adapter.execAsync(`
      CREATE TABLE IF NOT EXISTS kb_promotion_queue (
        promotion_id TEXT PRIMARY KEY,
        entry_id INTEGER NOT NULL,
        source_tier TEXT NOT NULL,
        target_tier TEXT NOT NULL,
        reason TEXT NOT NULL,
        score REAL NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'PENDING',
        review_comment TEXT,
        reviewed_by TEXT,
        reviewed_at TEXT,
        cooldown_until TEXT,
        created_at TEXT NOT NULL DEFAULT ${nowDefault},
        FOREIGN KEY (entry_id) REFERENCES knowledge_entries(id) ON DELETE CASCADE
      )
    `);
    await this.adapter.execAsync(`
      CREATE INDEX IF NOT EXISTS idx_kpq_status ON kb_promotion_queue(status)
    `);
    await this.adapter.execAsync(`
      CREATE INDEX IF NOT EXISTS idx_kpq_entry ON kb_promotion_queue(entry_id)
    `);
  }

  async scanForPromotionCandidates(limit = 50): Promise<PromotionCandidate[]> {
    const candidates: PromotionCandidate[] = [];
    const minAge = new Date(Date.now() - this.config.minAgeHours * 3600_000).toISOString();

    const entries = await this.adapter.allAsync<any>(`
      SELECT ke.id, ke.summary, ke.type, ke.access_count, ke.quality_score, ke.created_at
      FROM knowledge_entries ke
      WHERE ke.scope = 'USER'
        AND ke.archived = 0
        AND ke.created_at <= ?
        AND ke.id NOT IN (
          SELECT entry_id FROM kb_promotion_queue
          WHERE status IN ('PENDING', 'APPROVED')
        )
      ORDER BY ke.access_count DESC
      LIMIT ?
    `, [minAge, limit]);

    for (const entry of entries) {
      const criteria = await evaluateCriteria(this.adapter, entry, this.config);
      if (criteria.metCount >= this.config.minCriteriaMet) {
        candidates.push({
          entryId: entry.id,
          currentScope: 'USER',
          targetScope: 'PROJECT',
          reason: criteria.reasons.join('; '),
          score: criteria.score,
        });
      }
    }

    this.logger.info({ scanned: entries.length, candidates: candidates.length }, 'Promotion scan complete');
    return candidates;
  }

  async queueCandidates(candidates: PromotionCandidate[]): Promise<{ queued: number; autoApproved: number }> {
    let queued = 0;
    let autoApproved = 0;

    // SA4E-53: use transactionAsync for atomic batch operations
    await this.adapter.transactionAsync(async () => {
      for (const c of candidates) {
        const promotionId = `promo-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

        if (this.config.autoApproveToProject && c.targetScope === 'PROJECT') {
          await this.adapter.runAsync(
            `UPDATE knowledge_entries SET scope = ?, updated_at = ${this.dialect.now()} WHERE id = ?`,
            [c.targetScope, c.entryId],
          );
          await this.adapter.runAsync(
            `INSERT INTO kb_promotion_queue
             (promotion_id, entry_id, source_tier, target_tier, reason, score, status)
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT (promotion_id) DO NOTHING`,
            [promotionId, c.entryId, c.currentScope, c.targetScope, c.reason, c.score, 'APPROVED'],
          );
          autoApproved++;
        } else {
          await this.adapter.runAsync(
            `INSERT INTO kb_promotion_queue
             (promotion_id, entry_id, source_tier, target_tier, reason, score, status)
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT (promotion_id) DO NOTHING`,
            [promotionId, c.entryId, c.currentScope, c.targetScope, c.reason, c.score, 'PENDING'],
          );
          queued++;
        }
      }
    });

    this.logger.info({ queued, autoApproved }, 'Promotion candidates processed');
    return { queued, autoApproved };
  }

  async runPromotionCycle(): Promise<string> {
    const candidates = await this.scanForPromotionCandidates();
    if (candidates.length === 0) {
      return 'No promotion candidates found.';
    }
    const { queued, autoApproved } = await this.queueCandidates(candidates);
    return `Promotion cycle: ${candidates.length} candidates found. Queued: ${queued}, Auto-approved: ${autoApproved}.`;
  }

  async listPending(limit = 20): Promise<any[]> {
    return this.adapter.allAsync<any>(`
      SELECT pq.*, ke.summary, ke.type, ke.tier, ke.scope
      FROM kb_promotion_queue pq
      JOIN knowledge_entries ke ON ke.id = pq.entry_id
      WHERE pq.status = 'PENDING'
      ORDER BY pq.score DESC, pq.created_at ASC
      LIMIT ?
    `, [limit]);
  }

  async approve(entryId: number, reviewerId: string, comment: string): Promise<boolean> {
    const promo = await this.adapter.getAsync<any>(
      'SELECT * FROM kb_promotion_queue WHERE entry_id = ? AND status = ?',
      [entryId, 'PENDING'],
    );
    if (!promo) return false;

    await this.adapter.runAsync(`
      UPDATE kb_promotion_queue
      SET status = 'APPROVED', reviewed_by = ?, review_comment = ?, reviewed_at = ${this.dialect.now()}
      WHERE promotion_id = ?
    `, [reviewerId, comment, promo.promotion_id]);

    await this.adapter.runAsync(
      `UPDATE knowledge_entries SET scope = ?, updated_at = ${this.dialect.now()} WHERE id = ?`,
      [promo.target_tier, entryId],
    );

    this.logger.info({ entryId, target: promo.target_tier, reviewer: reviewerId }, 'Promotion approved');
    return true;
  }

  async reject(entryId: number, reviewerId: string, comment: string): Promise<boolean> {
    const promo = await this.adapter.getAsync<any>(
      'SELECT * FROM kb_promotion_queue WHERE entry_id = ? AND status = ?',
      [entryId, 'PENDING'],
    );
    if (!promo) return false;

    await this.adapter.runAsync(`
      UPDATE kb_promotion_queue
      SET status = 'REJECTED', reviewed_by = ?, review_comment = ?, reviewed_at = ${this.dialect.now()}
      WHERE promotion_id = ?
    `, [reviewerId, comment, promo.promotion_id]);

    this.logger.info({ entryId, reviewer: reviewerId }, 'Promotion rejected (no cooldown)');
    return true;
  }

  async requestSharedPromotion(entryId: number, reason: string): Promise<boolean> {
    const entry = await this.adapter.getAsync<any>(
      'SELECT * FROM knowledge_entries WHERE id = ? AND scope = ?',
      [entryId, 'PROJECT'],
    );
    if (!entry) return false;

    const existing = await this.adapter.getAsync<any>(
      "SELECT 1 FROM kb_promotion_queue WHERE entry_id = ? AND target_tier = 'SHARED' AND status = 'PENDING'",
      [entryId],
    );
    if (existing) return false;

    const promotionId = `promo-shared-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    await this.adapter.runAsync(`
      INSERT INTO kb_promotion_queue (promotion_id, entry_id, source_tier, target_tier, reason, score, status)
      VALUES (?, ?, 'PROJECT', 'SHARED', ?, 0, 'PENDING')
    `, [promotionId, entryId, reason]);

    this.logger.info({ entryId, reason }, 'SHARED promotion requested');
    return true;
  }

  async promoteOnMerge(ticketKey: string): Promise<{ promoted: number; skipped: number }> {
    const entries = await this.adapter.allAsync<any>(`
      SELECT id, scope FROM knowledge_entries
      WHERE scope = 'USER'
        AND archived = 0
        AND (
          tags LIKE ? OR source LIKE ? OR summary LIKE ?
        )
    `, [`%${ticketKey}%`, `%${ticketKey}%`, `%${ticketKey}%`]);

    let promoted = 0;
    let skipped = 0;

    await this.adapter.transactionAsync(async () => {
      for (const entry of entries) {
        if (entry.scope !== 'USER') { skipped++; continue; }
        await this.adapter.runAsync(
          `UPDATE knowledge_entries SET scope = 'PROJECT', updated_at = ${this.dialect.now()} WHERE id = ?`,
          [entry.id],
        );
        await this.adapter.runAsync(
          `INSERT INTO consolidation_log (entry_id, from_tier, to_tier, reason) VALUES (?, 'USER', 'PROJECT', ?)`,
          [entry.id, `Auto-promoted on merge/release: ${ticketKey}`],
        );
        promoted++;
      }
    });

    this.logger.info({ ticketKey, promoted, skipped, total: entries.length }, 'promoteOnMerge completed');
    return { promoted, skipped };
  }
}

/**
 * Migration 007 — SA4E-79: Add enrichment tracking columns.
 * Non-destructive ALTER TABLE — existing entries default to 'done' (BR-03).
 * Adds enrichment_status, enriched_by, enriched_at + partial index for pending entries.
 * PostgreSQL-compatible: uses ADD COLUMN IF NOT EXISTS.
 */

import type { DatabaseAdapter } from '../../../../database/adapters/DatabaseAdapter.js';

/**
 * Execute migration 007 — adds enrichment status tracking.
 * Idempotent: safe to run multiple times (IF NOT EXISTS for PG, try/catch for SQLite).
 * @param adapter - Database adapter for executing SQL
 */
export async function migrate007Up(adapter: DatabaseAdapter): Promise<void> {
  const engine = adapter.getEngine();

  if (engine === 'postgresql') {
    await adapter.runAsync(
      `ALTER TABLE knowledge_entries ADD COLUMN IF NOT EXISTS enrichment_status TEXT NOT NULL DEFAULT 'done'`, [],
    );
    await adapter.runAsync(
      `ALTER TABLE knowledge_entries ADD COLUMN IF NOT EXISTS enriched_by TEXT DEFAULT NULL`, [],
    );
    await adapter.runAsync(
      `ALTER TABLE knowledge_entries ADD COLUMN IF NOT EXISTS enriched_at TEXT DEFAULT NULL`, [],
    );
  } else {
    // SQLite doesn't support IF NOT EXISTS for ADD COLUMN — use try/catch
    for (const col of [
      `ALTER TABLE knowledge_entries ADD COLUMN enrichment_status TEXT NOT NULL DEFAULT 'done'`,
      `ALTER TABLE knowledge_entries ADD COLUMN enriched_by TEXT DEFAULT NULL`,
      `ALTER TABLE knowledge_entries ADD COLUMN enriched_at TEXT DEFAULT NULL`,
    ]) {
      try { await adapter.runAsync(col, []); } catch (err) { console.debug('[migration] DDL statement failed (expected if already applied):', (err as Error).message); }
    }
  }

  // Partial index — idempotent via IF NOT EXISTS
  await adapter.runAsync(
    `CREATE INDEX IF NOT EXISTS idx_ke_enrichment_pending
     ON knowledge_entries(enrichment_status)
     WHERE enrichment_status = 'pending'`, [],
  );
}

/**
 * TaskWorker — SA4E-44 / SA4E-47
 * Background polling worker for pending tasks.
 * Non-blocking start, exponential backoff, graceful shutdown.
 * Supports context chain + structured_map persistence.
 */

import type { Logger } from 'pino';
import type { DatabaseAdapter } from '../../../database/adapters/DatabaseAdapter.js';
import type { TagAnalyzerService, TagAnalysisResult } from '../llm/analyzer.js';
import type { EmbeddingService } from '../../../engine/parsers/embedding/EmbeddingService.js';
import { PendingTaskRepository } from './PendingTaskRepository.js';
import { TaskType } from './models.js';
import type { PendingTask } from './models.js';
import type { TaskWorkerConfig } from './TaskWorkerConfig.js';
import { DEFAULT_TASK_WORKER_CONFIG } from './TaskWorkerConfig.js';
import type { MemoryEngine } from '../engine/index.js';
import type { ContextChainInput, StructuredMapData } from '../llm/types.js';
import { safeParseStructuredMap } from '../llm/types.js';
import type { CodeEnrichmentHandler } from '../../../engine/enrichment/CodeEnrichmentHandler.js';

export interface TaskWorkerStats {
  pending: number;
  processing: number;
  completed: number;
  failed: number;
  isRunning: boolean;
  lastPollAt: string | null;
}

export class TaskWorker {
  private readonly repo: PendingTaskRepository;
  private readonly config: TaskWorkerConfig;
  private readonly logger: Logger;
  private readonly engine: MemoryEngine;
  private tagAnalyzer?: TagAnalyzerService;
  private embeddingService?: EmbeddingService;
  private llmService?: { getConfig(): { model: string } };
  private running = false;
  private pollTimer: ReturnType<typeof setTimeout> | null = null;
  private consecutiveEmpty = 0;
  private lastPollAt: string | null = null;
  private processing = false;
  private shutdownResolve: (() => void) | null = null;
  /** SA4E-101: Track current processing task for status bar progress. */
  private currentTaskInfo: { file: string; type: string; current: number; total: number } | null = null;
  /** SA4E-155: Adaptive concurrency — reduces on LLM errors, recovers on success. */
  private activeConcurrency: number = 0;
  private consecutiveErrors = 0;

  constructor(
    db: DatabaseAdapter,
    engine: MemoryEngine,
    logger: Logger,
    config?: Partial<TaskWorkerConfig>,
  ) {
    this.repo = new PendingTaskRepository(db);
    this.engine = engine;
    this.logger = logger.child({ component: 'TaskWorker' });
    this.config = { ...DEFAULT_TASK_WORKER_CONFIG, ...config };
  }

  setTagAnalyzer(analyzer: TagAnalyzerService): void { this.tagAnalyzer = analyzer; }
  setEmbeddingService(service: EmbeddingService): void { this.embeddingService = service; }
  setLlmService(service: { getConfig(): { model: string } }): void { this.llmService = service; }
  /** SA4E-107: Inject code enrichment handler for CODE_ENRICHMENT tasks. */
  private codeEnrichmentHandler?: CodeEnrichmentHandler;
  setCodeEnrichmentHandler(handler: CodeEnrichmentHandler): void { this.codeEnrichmentHandler = handler; }

  /**
   * Update mutable config fields at runtime — no restart needed.
   * Called when admin changes taskWorker config via Admin UI.
   * Supported keys: concurrency (1-8), baseInterval, maxInterval.
   */
  updateConfig(patch: Partial<Pick<TaskWorkerConfig, 'concurrency' | 'baseInterval' | 'maxInterval'>>): void {
    if (patch.concurrency !== undefined) {
      (this.config as any).concurrency = Math.max(1, patch.concurrency);
    }
    if (patch.baseInterval !== undefined) (this.config as any).baseInterval = patch.baseInterval;
    if (patch.maxInterval !== undefined) (this.config as any).maxInterval = patch.maxInterval;
    this.logger.info(
      { concurrency: this.config.concurrency, baseInterval: this.config.baseInterval },
      '[TaskWorker] Config updated live',
    );
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.logger.info('TaskWorker started');
    // On startup: reset any PROCESSING tasks from previous run (crash/restart recovery)
    this.resetProcessingOnStartup().catch(err =>
      this.logger.warn({ err }, 'TaskWorker: startup reset failed (non-fatal)'),
    );
    // Delay first poll by 6s to allow LLM health check + tagAnalyzer init to complete.
    // LLMInitializer is fire-and-forget async (5s timeout) — 6s ensures it's ready.
    this.schedulePoll(6000);
  }

  stop(): Promise<void> {
    if (!this.running) return Promise.resolve();
    this.running = false;
    if (this.pollTimer) { clearTimeout(this.pollTimer); this.pollTimer = null; }
    if (!this.processing) { this.logger.info('TaskWorker stopped'); return Promise.resolve(); }
    return new Promise<void>(resolve => { this.shutdownResolve = resolve; });
  }

  /**
   * Reset ALL tasks stuck in PROCESSING to PENDING on startup.
   * Called once at start() — handles server restart/crash recovery immediately,
   * no need to wait for staleThreshold timeout.
   */
  async resetProcessingOnStartup(): Promise<number> {
    const result = await this.repo.resetAllProcessing();
    if (result > 0) this.logger.info({ reset: result }, 'TaskWorker: reset stuck PROCESSING tasks on startup');
    return result;
  }

  async recoverStaleTasks(): Promise<number> {
    const recovered = await this.repo.recoverStaleTasks(this.config.staleThreshold);
    if (recovered > 0) this.logger.info({ recovered }, 'Recovered stale tasks');
    return recovered;
  }

  async getStats(): Promise<TaskWorkerStats> {
    const dbStats = await this.repo.getStats();
    return { ...dbStats, isRunning: this.running, lastPollAt: this.lastPollAt };
  }

  /** SA4E-101: Get current task progress for status bar display. */
  async getProgress(): Promise<{ phase: string; file: string; current: number; total: number; percent: number } | null> {
    if (!this.processing || !this.currentTaskInfo) return null;
    const stats = await this.repo.getStats();
    const total = stats.pending + stats.processing + stats.completed;
    const current = stats.completed;
    const percent = total > 0 ? Math.round((current / total) * 100) : 0;
    return {
      phase: this.currentTaskInfo.type,
      file: this.currentTaskInfo.file,
      current,
      total,
      percent,
    };
  }

  getRepository(): PendingTaskRepository { return this.repo; }

  /** SA4E-169: Expose config for dashboard (concurrency max). */
  getConfig(): TaskWorkerConfig { return this.config; }

  /** SA4E-169: Expose current active concurrency level. */
  getActiveConcurrency(): number { return this.activeConcurrency; }

  // ── Private ──

  private schedulePoll(delayMs: number): void {
    if (!this.running) return;
    this.pollTimer = setTimeout(() => this.poll(), delayMs);
  }

  private async poll(): Promise<void> {
    if (!this.running) { this.finishShutdown(); return; }
    this.lastPollAt = new Date().toISOString();
    try {
      // SA4E-155: Adaptive concurrency — use activeConcurrency (adjusted by LLM error rate)
      const maxConcurrency = this.config.concurrency ?? 1;
      if (this.activeConcurrency === 0) this.activeConcurrency = maxConcurrency;
      const claimCount = this.activeConcurrency;
      const tasks = await this.repo.claimBatch(claimCount);
      if (tasks.length === 0) {
        this.consecutiveEmpty++;
        if (this.consecutiveEmpty <= 3 || this.consecutiveEmpty % 10 === 0) {
          this.logger.info({ consecutiveEmpty: this.consecutiveEmpty, claimCount },
            '[TaskWorker] poll: no tasks claimed');
        }
        const delay = Math.min(
          this.config.baseInterval * Math.pow(2, this.consecutiveEmpty),
          this.config.maxInterval);
        this.schedulePoll(delay);
        return;
      }
      this.logger.info({ claimed: tasks.length, taskIds: tasks.map(t => t.id).slice(0, 3) },
        '[TaskWorker] poll: claimed tasks');
      this.consecutiveEmpty = 0;
      this.processing = true;
      // Run all claimed tasks concurrently
      const errorsBefore = this.consecutiveErrors;
      await Promise.allSettled(tasks.map(task => this.processTask(task)));
      // SA4E-155: processTask catches errors internally (marks task FAILED).
      // Detect failures by checking if consecutiveErrors was incremented during processing.
      const errorsThisCycle = this.consecutiveErrors - errorsBefore;
      if (errorsThisCycle > 0) {
        // Halve concurrency on errors, minimum 1
        this.activeConcurrency = Math.max(1, Math.floor(this.activeConcurrency / 2));
        this.logger.warn({ failures: errorsThisCycle, activeConcurrency: this.activeConcurrency, component: 'TaskWorker' },
          'LLM errors detected — reducing concurrency');
      } else {
        this.consecutiveErrors = 0;
        // Recover: increment towards max (slow ramp-up)
        if (this.activeConcurrency < maxConcurrency) {
          this.activeConcurrency = Math.min(maxConcurrency, this.activeConcurrency + 1);
        }
      }
      this.processing = false;
      if (!this.running) { this.finishShutdown(); return; }
      // Backoff delay if errors persist
      const delay = this.consecutiveErrors >= 3
        ? this.config.baseInterval * 3
        : this.config.baseInterval;
      this.schedulePoll(delay);
    } catch (err) {
      this.processing = false;
      this.logger.error({ err }, 'Poll cycle error');
      this.activeConcurrency = 1;
      this.schedulePoll(this.config.baseInterval * 2);
    }
  }

  private finishShutdown(): void {
    this.logger.info('TaskWorker stopped');
    this.shutdownResolve?.();
    this.shutdownResolve = null;
  }

  private async processTask(task: PendingTask): Promise<void> {
    try {
      // SA4E-107: CODE_ENRICHMENT uses symbols table, not knowledge_entries
      if (task.task_type === TaskType.CODE_ENRICHMENT) {
        this.currentTaskInfo = { file: `symbol-${task.entry_id}`, type: task.task_type, current: 0, total: 0 };
        await this.processCodeEnrichment(task);
        return;
      }
      const entry = await this.engine.findById(task.entry_id);
      if (!entry) { await this.repo.markFailed(task.id, 'entry_not_found'); return; }
      let payload: any;
      try { payload = JSON.parse(task.payload); }
      catch { this.repo.markFailed(task.id, 'invalid_json_payload'); return; }
      // SA4E-101: Track current task for progress reporting
      const file = (entry as any).source || `entry-${task.entry_id}`;
      this.currentTaskInfo = { file, type: task.task_type, current: 0, total: 0 };
      switch (task.task_type) {
        case TaskType.TAG_ENRICHMENT:
          await this.processTagEnrichment(task, payload);
          break;
        case TaskType.VECTOR_EMBEDDING:
          await this.processVectorEmbedding(task, payload);
          break;
        default:
          await this.repo.markFailed(task.id, `unknown_task_type: ${task.task_type}`);
      }
    } catch (err: any) { await this.handleTaskError(task, err); }
  }

  // ── SA4E-47: Enhanced Tag Enrichment ──

  private async processTagEnrichment(task: PendingTask, payload: any): Promise<void> {
    if (!this.tagAnalyzer) { this.repo.resetForRetry(task.id); return; }

    // SA4E-79: Check if already enriched by client (BR-12, BR-13)
    const entry = await this.engine.findById(task.entry_id);
    if (!entry) { await this.repo.markFailed(task.id, 'entry_not_found'); return; }
    if ((entry as any).enrichment_status === 'done') {
      this.logger.info({ entry_id: task.entry_id }, 'Skipping TAG_ENRICHMENT — already enriched');
      await this.repo.markCompleted(task.id);
      return;
    }

    const context = this.config.enableContextChain
      ? await this.loadPreviousContext(task.entry_id, payload.source)
      : null;

    if (context) {
      this.logger.debug({ entry_id: task.entry_id, prev_section_id: context.previous_section_id,
        component: 'TaskWorker' }, 'Context chain applied');
    }

    const result = await this.tagAnalyzer.analyzeTags(payload.content, payload.options, context);

    // SA4E-155: Quality gate — if LLM failed (fallback used), ALWAYS mark failed.
    // LLM must succeed for enrichment to be considered done.
    if (result.fallbackUsed) {
      this.consecutiveErrors++;
      const reason = result.fallbackReason || 'unknown';
      const errorMsg = `llm_enrichment_failed: ${reason}`;
      this.logger.warn({ entry_id: task.entry_id, task_id: task.id, reason, component: 'TaskWorker' },
        'LLM enrichment failed — marking task FAILED (not done)');
      await this.repo.markFailed(task.id, errorMsg);
      // Write error details into structured_map so it's queryable/visible in Admin UI
      const errorMap = JSON.stringify({
        error: errorMsg,
        error_at: new Date().toISOString(),
        task_id: task.id,
        retry_count: task.retry_count,
        fallback_used: true,
        extraction_meta: {
          model: this.llmService?.getConfig()?.model || 'unknown',
          timestamp: new Date().toISOString(),
          fallback_used: true,
          error: reason,
        },
      });
      await this.engine.getAdapter().runAsync(
        `UPDATE knowledge_entries SET enrichment_status = 'failed', structured_map = ? WHERE id = ? AND enrichment_status = 'pending'`,
        [errorMap, task.entry_id],
      );
      return;
    }

    // TA-08: Re-check status after LLM call — client may have enriched during processing
    const currentEntry = await this.engine.findById(task.entry_id);
    if (!currentEntry || (currentEntry as any).enrichment_status === 'done') {
      this.logger.info({ entry_id: task.entry_id }, 'Client enriched during LLM processing — discarding result');
      await this.repo.markCompleted(task.id);
      return;
    }

    if (result.appliedTags.length > 0) {
      const existing = payload.existing_tags
        ? payload.existing_tags.split(',').map((t: string) => t.trim()).filter(Boolean)
        : [];
      const merged = [...new Set([...existing, ...result.appliedTags])];
      // NEW-03: Conditional update — only apply if still pending (race guard)
      await this.engine.getAdapter().runAsync(
        `UPDATE knowledge_entries SET tags = ? WHERE id = ? AND enrichment_status = 'pending'`,
        [merged.join(','), task.entry_id],
      );
    }

    // NEW-03: Conditional structured_map update — only if still pending
    await this.updateEntryStructuredMapConditional(task.entry_id, result, context);

    // SA4E-79: Mark entry as enriched by backend LLM (atomic — changes=0 if client won)
    const now = new Date().toISOString();
    const updateResult = await this.engine.getAdapter().runAsync(
      `UPDATE knowledge_entries
       SET enrichment_status = 'done', enriched_by = 'backend_llm', enriched_at = ?
       WHERE id = ? AND enrichment_status = 'pending'`,
      [now, task.entry_id],
    );

    if (updateResult.changes === 0) {
      this.logger.info({ entry_id: task.entry_id }, 'Client enriched during tag/map update — discarding');
    }

    // SA4E-165: Always mark task completed — entry sync is best-effort above
    await this.repo.markCompleted(task.id);
  }

  private async loadPreviousContext(
    entryId: number,
    source: string | null,
  ): Promise<ContextChainInput | null> {
    if (!source) return null;
    try {
      const prevEntry = await this.engine.getAdapter().getAsync<{ id: number; structured_map: string | null }>(
        'SELECT id, structured_map FROM knowledge_entries WHERE source = ? AND id < ? ORDER BY id DESC LIMIT 1',
        [source, entryId],
      );
      if (!prevEntry) {
        this.logger.debug({ entry_id: entryId, component: 'TaskWorker' },
          'No previous section found');
        return null;
      }
      const map = safeParseStructuredMap(prevEntry.structured_map);
      if (!map.summary && (!map.business_entities || map.business_entities.length === 0)) {
        this.logger.debug({ entry_id: entryId, component: 'TaskWorker' },
          'Previous section has no extractable data');
        return null;
      }
      return {
        previous_section_id: prevEntry.id,
        summary: (map.summary || '').slice(0, this.config.contextChainMaxLength),
        business_entities: (map.business_entities || []).slice(0, 5),
        actors: (map.actors || []).slice(0, 5),
        business_rules: (map.business_rules || []).slice(0, 10),
      };
    } catch (err) {
      this.logger.warn({ entry_id: entryId, err, component: 'TaskWorker' },
        'Failed to load previous context');
      return null;
    }
  }

  private async updateEntryStructuredMap(
    entryId: number,
    result: TagAnalysisResult,
    context?: ContextChainInput | null,
  ): Promise<void> {
    try {
      const entry = await this.engine.findById(entryId);
      if (!entry) return;
      const existing = safeParseStructuredMap(entry.structured_map);
      const structuredMap: StructuredMapData = {
        tags: result.appliedTags,
        summary: result.summary || existing.summary || '',
        business_entities: result.business_entities || [],
        actors: result.actors || [],
        business_rules: result.business_rules || [],
        fileCreatedAt: existing.fileCreatedAt,
        fileAuthor: existing.fileAuthor,
        fileVersion: existing.fileVersion,
        context_chain: context ? {
          previous_section_id: context.previous_section_id,
          previous_summary: context.summary,
        } : undefined,
        extraction_meta: {
          model: this.llmService?.getConfig()?.model || 'unknown',
          timestamp: new Date().toISOString(),
          fallback_used: result.fallbackUsed,
          context_chain_enabled: this.config.enableContextChain,
        },
      };
      let jsonStr = JSON.stringify(structuredMap);
      if (jsonStr.length > (this.config.structuredMapMaxSize ?? 102400)) {
        structuredMap.business_rules = (structuredMap.business_rules || []).slice(0, 5);
        structuredMap.actors = (structuredMap.actors || []).slice(0, 3);
        this.logger.warn({ entry_id: entryId, size: jsonStr.length, component: 'TaskWorker' },
          'structured_map truncated due to size limit');
        jsonStr = JSON.stringify(structuredMap);
      }
      await this.engine.updateStructuredMap(entryId, jsonStr);
    } catch (err) {
      this.logger.warn({ entry_id: entryId, err, component: 'TaskWorker' },
        'structured_map update failed');
    }
  }

  /** NEW-03: Conditional structured_map update — only applies if entry still pending. */
  private async updateEntryStructuredMapConditional(
    entryId: number,
    result: TagAnalysisResult,
    context?: ContextChainInput | null,
  ): Promise<void> {
    try {
      const entry = await this.engine.findById(entryId);
      if (!entry) return;
      if ((entry as any).enrichment_status === 'done') return;
      const existing = safeParseStructuredMap(entry.structured_map);
      const structuredMap: StructuredMapData = {
        tags: result.appliedTags,
        summary: result.summary || existing.summary || '',
        business_entities: result.business_entities || [],
        actors: result.actors || [],
        business_rules: result.business_rules || [],
        fileCreatedAt: existing.fileCreatedAt,
        fileAuthor: existing.fileAuthor,
        fileVersion: existing.fileVersion,
        context_chain: context ? {
          previous_section_id: context.previous_section_id,
          previous_summary: context.summary,
        } : undefined,
        extraction_meta: {
          model: this.llmService?.getConfig()?.model || 'unknown',
          timestamp: new Date().toISOString(),
          fallback_used: result.fallbackUsed,
          context_chain_enabled: this.config.enableContextChain,
        },
      };
      let jsonStr = JSON.stringify(structuredMap);
      if (jsonStr.length > (this.config.structuredMapMaxSize ?? 102400)) {
        structuredMap.business_rules = (structuredMap.business_rules || []).slice(0, 5);
        structuredMap.actors = (structuredMap.actors || []).slice(0, 3);
        jsonStr = JSON.stringify(structuredMap);
      }
      await this.engine.getAdapter().runAsync(
        `UPDATE knowledge_entries SET structured_map = ? WHERE id = ? AND enrichment_status = 'pending'`,
        [jsonStr, entryId],
      );
      // SA4E-169: Update summary column (separate from structured_map) for FTS indexing + KB UI display
      if (structuredMap.summary) {
        await this.engine.getAdapter().runAsync(
          `UPDATE knowledge_entries SET summary = ? WHERE id = ? AND enrichment_status = 'pending'`,
          [structuredMap.summary, entryId],
        );
      }
    } catch (err) {
      this.logger.warn({ entry_id: entryId, err, component: 'TaskWorker' },
        'structured_map conditional update failed');
    }
  }

  /** SA4E-107: Process CODE_ENRICHMENT task via injected handler. */
  private async processCodeEnrichment(task: PendingTask): Promise<void> {
    if (!this.codeEnrichmentHandler) { this.repo.resetForRetry(task.id); return; }
    await this.codeEnrichmentHandler.enrichSymbol(task);
    await this.repo.markCompleted(task.id);
  }

  private async processVectorEmbedding(task: PendingTask, payload: any): Promise<void> {
    if (!this.embeddingService) { this.repo.resetForRetry(task.id); return; }
    const vector = await this.embeddingService.generateEmbedding(payload.text);
    const buf = Buffer.from(new Float32Array(vector).buffer);
    await this.engine.getAdapter().runAsync(
      'UPDATE knowledge_entries SET vector = ? WHERE id = ?',
      [buf, task.entry_id],
    );
    await this.repo.markCompleted(task.id);
  }

  private async handleTaskError(task: PendingTask, err: Error): Promise<void> {
    this.consecutiveErrors++;
    // SA4E-106: Non-retryable patterns include CODE_ENRICHMENT-specific errors
    const nonRetryable = err.message.includes('invalid_json')
      || err.message.includes('entry_not_found')
      || err.message.includes('invalid_payload')
      || err.message.includes('symbol_not_found');
    if (nonRetryable || task.retry_count + 1 >= task.max_retries) {
      await this.repo.markFailed(task.id, err.message);
    } else {
      await this.repo.markFailed(task.id, err.message);
      await this.repo.resetForRetry(task.id);
    }
  }
}

/**
 * IT-01 to IT-07: TaskWorker Integration Tests
 * Full pipeline integration with in-memory SQLite and mocked LLM.
