  constructor(logger: Logger) {
    this.logger = logger.child({ component: 'McpClientManager' });
    this.healthConfig = { ...PRODUCTION_HEALTH_CONFIG };
    this.stateTracker = new ConnectionStateTracker(logger);
    this.healthMonitor = new HealthMonitor(logger, {
      getConnectedServers: () => this.getConnectedClients(),
      onPingSuccess: (name) => this.stateTracker.recordPingSuccess(name),
      onPingFailed: (name, error) => this.handlePingFailed(name, error),
    }, this.healthConfig);
    this.reconnectManager = new ReconnectManager(logger, this.healthConfig, {
      onReconnectSuccess: (name, client) => this.handleReconnectSuccess(name, client),
      onReconnectFailed: (name, attempt, err) => this.handleReconnectFailed(name, attempt, err),
      onMaxRetriesExhausted: (name) => this.handleMaxRetriesExhausted(name),
    });
  }

  async initializeAll(): Promise<void> {
    const workspace = process.env.CODE_INTEL_WORKSPACE || process.cwd();
    const dataDir = process.env.CODE_INTEL_DATA_DIR || '.code-intel';
    const configPath = path.resolve(workspace, dataDir, 'orchestration.json');

    if (!fs.existsSync(configPath)) {
      this.logger.info({ configPath }, 'No orchestration.json found, skipping child servers');
      return;
    }

    let config: { mcpServers: Record<string, ServerConfig> };
    try {
      const raw = fs.readFileSync(configPath, 'utf-8');
      config = JSON.parse(raw);
    } catch (err) {
      this.logger.error({ err, configPath }, 'Failed to read orchestration.json');
      return;
    }

    const servers = Object.entries(config.mcpServers || {});
    this.logger.info({ count: servers.length }, 'Connecting child MCP servers');

    for (const [name, serverConfig] of servers) {
      try {
        await this.connectServer(name, serverConfig);
      } catch (err) {
        this.logger.error({ err, server: name }, 'Failed to connect child server (will retry via health monitor)');
        // Register so health monitor can attempt reconnect later
        if (!this.stateTracker.getState(name)) this.stateTracker.register(name);
        this.serverConfigs.set(name, serverConfig);
      }
    }
  }

  getProxiedTools(): ToolDefinition[] { return this.proxiedTools; }

  getServersStatus(): ServerStatusEntry[] {
    return this.stateTracker.getAllStatuses((name) => this.getServerToolCount(name));
  }

  ownsTool(toolName: string): boolean { return this.toolsToServer.has(toolName); }

  async executeTool(toolName: string, args: unknown): Promise<any> {
    const serverName = this.toolsToServer.get(toolName);
    if (!serverName) throw new Error(`Tool ${toolName} is not managed by any child server`);

    const state = this.stateTracker.getState(serverName);
    if (state !== 'connected') throw new Error(this.getErrorMsg(serverName, state));

    const client = this.clients.get(serverName);
    if (!client) throw new Error(`Client for server ${serverName} is disconnected`);

    this.logger.info({ toolName, serverName }, 'Proxying tool execution to child server');
    const result = await client.callTool({ name: toolName, arguments: args as Record<string, unknown> });
    return { content: result.content, isError: result.isError };
  }

  async connectServer(name: string, config: ServerConfig): Promise<void> {
    if (config.disabled || name === 'code-intelligence') return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const transport = createTransport(name, config) as any;
    const client = new Client({ name: 'code-intel-orchestrator', version: '1.0.0' }, { capabilities: {} });
    await Promise.race([
      client.connect(transport),
      new Promise((_, rej) => setTimeout(() => rej(new Error('Connection timeout')), 10_000)),
    ]);
    this.clients.set(name, client);
    this.serverConfigs.set(name, config);
    if (!this.stateTracker.getState(name)) this.stateTracker.register(name);
    this.stateTracker.transition(name, 'connected');
    await this.registerServerTools(name, client);
    this.logger.info({ name, tools: this.getServerToolCount(name) }, 'Server connected');
  }

  async disconnectServer(name: string): Promise<void> {
    this.reconnectManager.cancelReconnect(name);
    const client = this.clients.get(name);
    if (client) {
      try { await client.close(); } catch (err) {
        this.logger.warn({ err, name }, 'Failed to close MCP client connection');
      }
      this.clients.delete(name);
    }
    this.clearServerTools(name);
    this.stateTracker.transition(name, 'disconnected');
    this.serverConfigs.delete(name);
  }

  async shutdownAll(): Promise<void> {
    this.stopHealthMonitor();
    for (const [name, client] of this.clients.entries()) {
      try { await client.close(); } catch (e) {
        this.logger.error({ err: e, serverName: name }, 'Error closing client');
      }
    }
  }

  startHealthMonitor(): void { this.healthMonitor.start(); }
  stopHealthMonitor(): void { this.healthMonitor.stop(); }

  async reconnectServer(name: string): Promise<void> {
    const state = this.stateTracker.getState(name);
    if (state === undefined) throw new Error(`Unknown server: ${name}`);
    if (state === 'disconnected') throw new Error('Cannot reconnect manually disconnected server');
    if (state === 'connected' || state === 'reconnecting') return;
    this.stateTracker.resetReconnectState(name);
    this.stateTracker.transition(name, 'reconnecting');
    const config = this.serverConfigs.get(name);
    if (!config) throw new Error(`Server config not found for '${name}'`);
    this.reconnectManager.scheduleReconnect(name, config, 1);
  }

  onServerStateChange(cb: ServerStateChangeCallback): Unsubscribe {
    return this.stateTracker.onStateChange(cb);
  }

  setHealthCheckConfig(config: Partial<HealthCheckConfig>): void {
    this.healthConfig = { ...this.healthConfig, ...config };
    this.healthMonitor.updateConfig(this.healthConfig);
    this.reconnectManager.updateConfig(this.healthConfig);
  }

  isServerConnected(name: string): boolean {
    return this.clients.has(name) && this.stateTracker.getState(name) === 'connected';
  }

  getServerToolCount(name: string): number {
    let count = 0;
    for (const [, sn] of this.toolsToServer.entries()) { if (sn === name) count++; }
    return count;
  }

  // --- Private ---

  private getConnectedClients(): Map<string, Client> {
    const connected = new Map<string, Client>();
    for (const [name, client] of this.clients.entries()) {
      if (this.stateTracker.getState(name) === 'connected') connected.set(name, client);
    }
    return connected;
  }

  private handlePingFailed(name: string, error: string): void {
    this.stateTracker.recordPingFailure(name, error);
    if (!this.stateTracker.isThresholdBreached(name, this.healthConfig.failureThreshold)) return;
    this.stateTracker.transition(name, 'unhealthy', error);
    this.stateTracker.transition(name, 'reconnecting');
    const config = this.serverConfigs.get(name);
    if (!config) return;
    const entry = this.stateTracker.getEntry(name);
    if (!entry) return;
    entry.reconnectAttempts = 1;
    const next = this.reconnectManager.scheduleReconnect(name, config, 1);
    if (next) entry.nextRetryAt = next;
  }

  private handleReconnectSuccess(name: string, client: Client): void {
    this.clients.set(name, client);
    this.clearServerTools(name);
    void this.registerServerTools(name, client).then(() => {
      this.stateTracker.resetReconnectState(name);
      this.stateTracker.transition(name, 'connected');
      this.logger.info({ server: name }, 'Reconnected successfully');
    });
  }

  private handleReconnectFailed(name: string, attempt: number, error: string): void {
    const entry = this.stateTracker.getEntry(name);
    if (!entry) return;
    entry.reconnectAttempts = attempt + 1;
    entry.lastError = error;
    const config = this.serverConfigs.get(name);
    if (!config) return;
    const next = this.reconnectManager.scheduleReconnect(name, config, attempt + 1);
    if (next) entry.nextRetryAt = next;
  }

  private handleMaxRetriesExhausted(name: string): void {
    this.stateTracker.transition(name, 'failed');
    this.logger.error({ server: name, attempts: this.healthConfig.maxRetries }, 'Max retries exhausted');
  }

  private async registerServerTools(name: string, client: Client): Promise<void> {
    const toolsResult = await client.listTools();
    for (const tool of toolsResult.tools ?? []) {
      this.toolsToServer.set(tool.name, name);
      this.proxiedTools.push({
        name: tool.name, description: tool.description ?? '',
        category: name as ToolDefinition['category'], inputSchema: tool.inputSchema as unknown as Record<string, unknown>,
      });
    }
  }

  private clearServerTools(name: string): void {
    const names: string[] = [];
    for (const [tn, sn] of this.toolsToServer.entries()) { if (sn === name) names.push(tn); }
    for (const tn of names) this.toolsToServer.delete(tn);
    this.proxiedTools = this.proxiedTools.filter((t) => !names.includes(t.name));
  }

  private getErrorMsg(name: string, state: string | undefined): string {
    const max = this.healthConfig.maxRetries;
    if (state === 'reconnecting') {
      const a = this.stateTracker.getEntry(name)?.reconnectAttempts ?? 0;
      return `Server '${name}' is currently reconnecting (attempt ${a}/${max}). Tool call rejected.`;
    }
    if (state === 'failed') return `Server '${name}' has failed after ${max} reconnect attempts. Manual reconnection required.`;
    if (state === 'unhealthy') return `Server '${name}' is unhealthy. Reconnection will be attempted shortly.`;
    return `Server '${name}' is not connected (state: ${state}).`;
  }
}

/**
 * McpConfigRoutes — REST API for MCP server config management.
 * Endpoints: GET/POST/PUT/DELETE /api/mcp-servers
 */

import { Hono } from 'hono';
import type { ContentfulStatusCode } from 'hono/utils/http-status';
import { McpConfigService, ConfigError } from './McpConfigService.js';
import type { McpClientManager } from './McpClientManager.js';
import type { Logger } from 'pino';

export function createMcpConfigRoutes(
  configService: McpConfigService,
  clientManager: McpClientManager,
  logger?: Logger
): Hono {
  const app = new Hono();

  app.get('/api/mcp-servers', (c) => {
    const servers = configService.listServers();
    const withStatus = servers.map(srv => ({
      name: srv.name,
      url: srv.url,
      command: srv.command,
      type: srv.type || srv.transportType,
      disabled: srv.disabled ?? false,
      status: clientManager.isServerConnected(srv.name!) ? 'connected' : 'disconnected',
      tools: clientManager.getServerToolCount(srv.name!),
    }));
    return c.json({ servers: withStatus });
  });

  app.get('/api/mcp-servers/:name', (c) => {
    const name = c.req.param('name');
    const server = configService.getServer(name);
    if (!server) return c.json({ error: `Server "${name}" not found` }, 404);
    return c.json({
      ...server,
      status: clientManager.isServerConnected(name) ? 'connected' : 'disconnected',
      tools: clientManager.getServerToolCount(name),
    });
  });

  app.post('/api/mcp-servers', async (c) => {
    const body = await c.req.json();
    const { name, ...config } = body;
    if (!name) return c.json({ error: 'name is required' }, 400);

    try {
      configService.addServer(name, config);
    } catch (e) {
      if (e instanceof ConfigError) {
        return c.json({ error: e.message, details: e.validationErrors }, e.statusCode as ContentfulStatusCode);
      }
      throw e;
    }

    let status = 'disconnected';
    let tools = 0;
    if (!config.disabled) {
      try {
        await clientManager.connectServer(name, config);
        status = 'connected';
        tools = clientManager.getServerToolCount(name);
      } catch (err) {
        logger?.warn({ name, err }, 'Connect failed after add');
      }
    }
    return c.json({ name, status, tools, transport: config.type }, 201);
  });

  app.put('/api/mcp-servers/:name', async (c) => {
    const name = c.req.param('name');
    const config = await c.req.json();

    try {
      configService.updateServer(name, config);
    } catch (e) {
      if (e instanceof ConfigError) {
        return c.json({ error: e.message, details: e.validationErrors }, e.statusCode as ContentfulStatusCode);
      }
      throw e;
    }

    let status = 'disconnected';
    let tools = 0;
    try {
      await clientManager.disconnectServer(name);
      if (!config.disabled) {
        const full = configService.getServer(name)!;
        await clientManager.connectServer(name, full);
        status = 'connected';
        tools = clientManager.getServerToolCount(name);
      }
    } catch (err) {
      logger?.warn({ name, err }, 'Reconnect failed after update');
    }
    return c.json({ name, status, tools });
  });

  app.delete('/api/mcp-servers/:name', async (c) => {
    const name = c.req.param('name');
    const toolsBefore = clientManager.getServerToolCount(name);

    try {
      configService.removeServer(name);
    } catch (e) {
      if (e instanceof ConfigError) {
        return c.json({ error: e.message }, e.statusCode as ContentfulStatusCode);
      }
      throw e;
    }

    try { await clientManager.disconnectServer(name); } catch (err) { logger?.debug({ err }, '[McpConfigRoutes] Disconnect during removal failed (non-fatal)'); }
    return c.json({ removed: name, tools_removed: toolsBefore });
  });

  app.post('/api/mcp-servers/:name/reconnect', async (c) => {
    const name = c.req.param('name');
    const server = configService.getServer(name);
    if (!server) return c.json({ error: `Server "${name}" not found` }, 404);

    try {
      await clientManager.disconnectServer(name);
      await clientManager.connectServer(name, server);
      return c.json({ name, status: 'connected', tools: clientManager.getServerToolCount(name) });
    } catch (err: any) {
      return c.json({ name, status: 'failed', error: err.message });
    }
  });

  return app;
}

/**
 * McpConfigService — CRUD operations for child MCP server configs.
 * Persists to .code-intel/orchestration.json with atomic writes.
 * NOT an MCP tool — exposed via REST API only.
 */

import * as fs from 'fs';
import * as path from 'path';
import type { Logger } from 'pino';

export interface ServerConfig {
  name?: string;
  url?: string;
  type?: string;
  transportType?: string;
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  disabled?: boolean;
  autoApprove?: string[];
}

export interface ServerInfo {
  name: string;
  status: 'connected' | 'disconnected' | 'disabled';
  tools: number;
  transport: string;
  url?: string;
  command?: string;
}

interface OrchestrationConfig {
  mcpServers: Record<string, ServerConfig>;
}

export interface ValidationError {
  field: string;
  message: string;
}

const RESERVED_NAME = 'code-intelligence';

export class McpConfigService {
  private configPath: string;
  private logger?: Logger;

  constructor(
    private workspace: string,
    private dataDir: string,
    logger?: Logger
  ) {
    this.configPath = path.resolve(workspace, dataDir, 'orchestration.json');
    this.logger = logger;
  }

  listServers(): ServerConfig[] {
    const config = this.readConfig();
    return Object.entries(config.mcpServers).map(([name, cfg]) => ({
      ...cfg, name,
    }));
  }

  getServer(name: string): ServerConfig | null {
    const config = this.readConfig();
    const server = config.mcpServers[name];
    return server ? { ...server, name } : null;
  }

  addServer(name: string, serverConfig: ServerConfig): void {
    if (name === RESERVED_NAME) {
      throw new ConfigError(403, 'Cannot modify reserved server: code-intelligence');
    }
    const config = this.readConfig();
    if (config.mcpServers[name]) {
      throw new ConfigError(409, `Server "${name}" already exists`);
    }
    const errors = this.validateConfig(serverConfig);
    if (errors.length > 0) {
      throw new ConfigError(400, 'Validation failed', errors);
    }
    config.mcpServers[name] = this.cleanConfig(serverConfig);
    this.writeConfig(config);
    this.logger?.info({ name }, 'MCP server config added');
  }

  updateServer(name: string, serverConfig: Partial<ServerConfig>): void {
    if (name === RESERVED_NAME) {
      throw new ConfigError(403, 'Cannot modify reserved server: code-intelligence');
    }
    const config = this.readConfig();
    if (!config.mcpServers[name]) {
      throw new ConfigError(404, `Server "${name}" not found`);
    }
    const merged = { ...config.mcpServers[name], ...serverConfig };
    const errors = this.validateConfig(merged);
    if (errors.length > 0) {
      throw new ConfigError(400, 'Validation failed', errors);
    }
    config.mcpServers[name] = this.cleanConfig(merged);
    this.writeConfig(config);
    this.logger?.info({ name }, 'MCP server config updated');
  }

  removeServer(name: string): void {
    if (name === RESERVED_NAME) {
      throw new ConfigError(403, 'Cannot modify reserved server: code-intelligence');
    }
    const config = this.readConfig();
    if (!config.mcpServers[name]) {
      throw new ConfigError(404, `Server "${name}" not found`);
    }
    delete config.mcpServers[name];
    this.writeConfig(config);
    this.logger?.info({ name }, 'MCP server config removed');
  }

  private readConfig(): OrchestrationConfig {
    if (!fs.existsSync(this.configPath)) {
      return { mcpServers: {} };
    }
    const raw = fs.readFileSync(this.configPath, 'utf-8');
    return JSON.parse(raw) as OrchestrationConfig;
  }

  private writeConfig(config: OrchestrationConfig): void {
    const dir = path.dirname(this.configPath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const json = JSON.stringify(config, null, 2);
    const tmpPath = this.configPath + '.tmp';
    fs.writeFileSync(tmpPath, json, 'utf-8');
    fs.renameSync(tmpPath, this.configPath);
  }

  private validateConfig(config: ServerConfig): ValidationError[] {
    const errors: ValidationError[] = [];
    if (!config.url && !config.command) {
      errors.push({ field: 'url/command', message: 'Either url or command is required' });
    }
    // type is optional — inferred: command present = stdio, url present = httpStream
    return errors;
  }

  private cleanConfig(config: ServerConfig): ServerConfig {
    const { name: _, ...rest } = config;
    return rest;
  }
}

export class ConfigError extends Error {
  constructor(
    public readonly statusCode: number,
    message: string,
    public readonly validationErrors?: ValidationError[]
  ) {
    super(message);
    this.name = 'ConfigError';
  }
}

/**
 * Orchestration Module — manages child MCP servers and tool discovery.
 * DIP fix: find_tools handler depends on ToolSearchService interface,
 * not on MemoryModule internals (getEngine().getDb()). Service is injected
 * after modules are initialized via setToolSearchService().
 */

import type { IModule, ModuleStatus } from '../../types/module.js';
import type { ToolHandler, ToolDefinition } from '../../types/tool.js';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../ModuleRegistry.js';
import { McpClientManager } from './McpClientManager.js';
import { trackToolUsage } from '../../server/toolUsageTracker.js';
import { createReindexSubscriber } from './reindex/ReindexSubscriberFactory.js';
import type { ReindexSubscriber } from './reindex/ReindexSubscriber.js';
import type { ToolSearchService } from './ToolSearchService.js';

export class OrchestrationModule implements IModule {
  readonly name = 'orchestration';
  private _status: ModuleStatus = 'initializing';
  private logger: Logger;
  private registry?: ModuleRegistry;
  private clientManager: McpClientManager;
  private reindexSubscriber?: ReindexSubscriber;
  /** Injected after module init — depends on abstraction, not MemoryModule concrete. */
  private toolSearchService?: ToolSearchService;

  constructor(logger: Logger, registry?: ModuleRegistry) {
    this.logger = logger.child({ module: this.name });
    this.registry = registry;
    this.clientManager = new McpClientManager(logger);
  }

  getClientManager(): McpClientManager { return this.clientManager; }
  get status(): ModuleStatus { return this._status; }

  /**
   * DIP: called from index.ts after MemoryModule is ready.
   * Injects a ToolSearchService backed by the memory DB without coupling this module to MemoryModule.
   */
  setToolSearchService(svc: ToolSearchService): void {
    this.toolSearchService = svc;
  }

  async initialize(): Promise<void> {
    this.logger.info('Initializing orchestration module');
    await this.clientManager.initializeAll();
    this.clientManager.startHealthMonitor();
    this.reindexSubscriber = createReindexSubscriber(this.clientManager, this.logger, this.registry);
    this.reindexSubscriber.start();
    this._status = 'ready';
  }

  async shutdown(): Promise<void> {
    this.reindexSubscriber?.stop();
    this.reindexSubscriber = undefined;
    this.clientManager.stopHealthMonitor();
    await this.clientManager.shutdownAll();
    this._status = 'stopped';
  }

  getToolHandlers(): Map<string, ToolHandler> {
    const handlers = new Map<string, ToolHandler>();

    handlers.set('orchestration_status', async () => {
      const servers = this.clientManager.getServersStatus();
      const totalProxiedTools = servers.reduce((sum, s) => sum + s.toolCount, 0);
      return {
        content: [{ type: 'text', text: JSON.stringify({ servers, serverCount: servers.length, totalProxiedTools, status: 'ready' }) }],
        isError: false,
      };
    });

    handlers.set('find_tools', async (args: any) => {
      const query = args.query as string;
      const limit = (args.top_k as number) || 5;

      if (!this.toolSearchService) {
        this.logger.warn('find_tools called but ToolSearchService not yet injected');
        return { content: [{ type: 'text', text: JSON.stringify({ tools: [], query }) }], isError: false };
      }

      const tools = await this.toolSearchService.search(query, limit);
      return { content: [{ type: 'text', text: JSON.stringify({ tools, query }) }], isError: false };
    });

    handlers.set('execute_dynamic_tool', async (args: any) => {
      const toolName = args.toolName || args.tool_name;
      const toolArgs = args.arguments || {};

      // Proxy to child MCP server if it owns this tool
      if (this.clientManager.ownsTool(toolName)) {
        try {
          const result = await this.clientManager.executeTool(toolName, toolArgs);
          if (this.registry && !result.isError) {
            trackToolUsage(this.registry, this.logger, toolName);
          }
          return result;
        } catch (err: any) {
          return { content: [{ type: 'text', text: `Error proxying tool ${toolName}: ${err.message || err}` }], isError: true };
        }
      }

      if (!this.registry) {
        return { content: [{ type: 'text', text: 'Registry not available' }], isError: true };
      }

      const handler = this.registry.getToolHandlers().get(toolName);
      if (!handler) {
        return { content: [{ type: 'text', text: `Tool ${toolName} not found` }], isError: true };
      }

      try {
        const result = await handler(toolArgs);
        if (!result.isError) trackToolUsage(this.registry, this.logger, toolName);
        return result;
      } catch (err: any) {
        this.logger.error({ err, toolName }, 'Failed to execute dynamic tool');
        return { content: [{ type: 'text', text: `Error executing tool ${toolName}: ${err.message || err}` }], isError: true };
      }
    });

    handlers.set('toggle_tool', async (args: any) => ({
      content: [{ type: 'text', text: `Tool ${args.toolName} enabled=${args.enabled}` }],
      isError: false,
    }));

    return handlers;
  }

  getToolDefinitions(): ToolDefinition[] {
    return [
      { name: 'orchestration_status', description: 'Get status of all child MCP servers', inputSchema: { type: 'object', properties: {} }, category: 'orchestration' },
      { name: 'find_tools', description: 'Search available tools by semantic query', inputSchema: { type: 'object', properties: { query: { type: 'string' }, threshold: { type: 'number' }, top_k: { type: 'number' } }, required: ['query'] }, category: 'orchestration' },
      { name: 'execute_dynamic_tool', description: 'Execute a dynamically discovered tool', inputSchema: { type: 'object', properties: { toolName: { type: 'string' }, arguments: { type: 'object' } }, required: ['toolName', 'arguments'] }, category: 'orchestration' },
      { name: 'toggle_tool', description: 'Enable or disable a tool', inputSchema: { type: 'object', properties: { tool_name: { type: 'string' }, enabled: { type: 'boolean' } }, required: ['tool_name'] }, category: 'orchestration' },
    ];
  }
}

/**
 * Unit tests for ConnectionStateTracker — SA4E-37
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { ConnectionStateTracker } from '../ConnectionStateTracker.js';
import type { ServerStateChangeEvent } from '../../types/health.js';

function createMockLogger() {
  return {
    child: () => createMockLogger(),
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  } as any;
}

describe('ConnectionStateTracker', () => {
  let tracker: ConnectionStateTracker;
  let logger: any;

  beforeEach(() => {
    logger = createMockLogger();
    tracker = new ConnectionStateTracker(logger);
  });

  describe('register / unregister', () => {
    it('should register a server with disconnected state', () => {
      tracker.register('server-a');
      expect(tracker.getState('server-a')).toBe('disconnected');
    });

    it('should unregister a server and remove its state', () => {
      tracker.register('server-a');
      tracker.unregister('server-a');
      expect(tracker.getState('server-a')).toBeUndefined();
    });

    it('should clear reconnect timer on unregister', () => {
      tracker.register('server-a');
      const entry = tracker.getEntry('server-a')!;
      const timerId = setTimeout(() => {}, 10000);
      entry.reconnectTimerId = timerId;
      tracker.unregister('server-a');
      clearTimeout(timerId);
    });
  });

  describe('valid state transitions', () => {
    it('should transition disconnected → connected', () => {
      tracker.register('s1');
      const result = tracker.transition('s1', 'connected');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('connected');
    });

    it('should transition connected → unhealthy', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const result = tracker.transition('s1', 'unhealthy');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('unhealthy');
    });

    it('should transition unhealthy → reconnecting', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.transition('s1', 'unhealthy');
      const result = tracker.transition('s1', 'reconnecting');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('reconnecting');
    });

    it('should transition reconnecting → failed', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.transition('s1', 'unhealthy');
      tracker.transition('s1', 'reconnecting');
      const result = tracker.transition('s1', 'failed');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('failed');
    });

    it('should transition reconnecting → connected', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.transition('s1', 'unhealthy');
      tracker.transition('s1', 'reconnecting');
      const result = tracker.transition('s1', 'connected');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('connected');
    });

    it('should transition failed → reconnecting', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.transition('s1', 'unhealthy');
      tracker.transition('s1', 'reconnecting');
      tracker.transition('s1', 'failed');
      const result = tracker.transition('s1', 'reconnecting');
      expect(result).toBe(true);
      expect(tracker.getState('s1')).toBe('reconnecting');
    });
  });

  describe('invalid state transitions', () => {
    it('should reject disconnected → unhealthy', () => {
      tracker.register('s1');
      const result = tracker.transition('s1', 'unhealthy');
      expect(result).toBe(false);
      expect(tracker.getState('s1')).toBe('disconnected');
    });

    it('should reject connected → failed', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const result = tracker.transition('s1', 'failed');
      expect(result).toBe(false);
      expect(tracker.getState('s1')).toBe('connected');
    });

    it('should reject connected → reconnecting', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const result = tracker.transition('s1', 'reconnecting');
      expect(result).toBe(false);
      expect(tracker.getState('s1')).toBe('connected');
    });

    it('should return false for unknown server', () => {
      const result = tracker.transition('unknown', 'connected');
      expect(result).toBe(false);
    });
  });

  describe('ping success / failure recording', () => {
    it('should reset consecutiveFailures on ping success', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const entry = tracker.getEntry('s1')!;
      entry.consecutiveFailures = 3;
      tracker.recordPingSuccess('s1');
      expect(tracker.getEntry('s1')!.consecutiveFailures).toBe(0);
      expect(tracker.getEntry('s1')!.lastHealthCheck).not.toBeNull();
    });

    it('should increment consecutiveFailures on ping failure', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.recordPingFailure('s1', 'timeout');
      tracker.recordPingFailure('s1', 'timeout');
      expect(tracker.getEntry('s1')!.consecutiveFailures).toBe(2);
      expect(tracker.getEntry('s1')!.lastError).toBe('timeout');
    });

    it('should set failureStartedAt on first failure only', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.recordPingFailure('s1', 'err');
      const first = tracker.getEntry('s1')!.failureStartedAt;
      expect(first).not.toBeNull();
      tracker.recordPingFailure('s1', 'err2');
      expect(tracker.getEntry('s1')!.failureStartedAt).toBe(first);
    });

    it('should do nothing for unknown server on recordPingSuccess', () => {
      tracker.recordPingSuccess('unknown');
    });
  });

  describe('threshold breach detection', () => {
    it('should detect threshold breach when failures >= threshold', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.recordPingFailure('s1', 'err');
      tracker.recordPingFailure('s1', 'err');
      expect(tracker.isThresholdBreached('s1', 2)).toBe(true);
    });

    it('should not detect breach when failures < threshold', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      tracker.recordPingFailure('s1', 'err');
      expect(tracker.isThresholdBreached('s1', 2)).toBe(false);
    });

    it('should return false for unknown server', () => {
      expect(tracker.isThresholdBreached('unknown', 2)).toBe(false);
    });
  });

  describe('event emission to listeners', () => {
    it('should emit event on valid transition', () => {
      tracker.register('s1');
      const events: ServerStateChangeEvent[] = [];
      tracker.onStateChange((e) => events.push(e));
      tracker.transition('s1', 'connected');
      expect(events).toHaveLength(1);
      expect(events[0].serverName).toBe('s1');
      expect(events[0].previousState).toBe('disconnected');
      expect(events[0].newState).toBe('connected');
      expect(events[0].timestamp).toBeTruthy();
    });

    it('should not emit event on invalid transition', () => {
      tracker.register('s1');
      const events: ServerStateChangeEvent[] = [];
      tracker.onStateChange((e) => events.push(e));
      tracker.transition('s1', 'failed');
      expect(events).toHaveLength(0);
    });

    it('should include error in event when provided', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const events: ServerStateChangeEvent[] = [];
      tracker.onStateChange((e) => events.push(e));
      tracker.transition('s1', 'unhealthy', 'ping timeout');
      expect(events[0].error).toBe('ping timeout');
    });
  });

  describe('listener error isolation', () => {
    it('should still call other listeners if one throws', () => {
      tracker.register('s1');
      const called: string[] = [];
      tracker.onStateChange(() => { throw new Error('listener error'); });
      tracker.onStateChange((e) => { called.push(e.serverName); });
      tracker.transition('s1', 'connected');
      expect(called).toEqual(['s1']);
    });
  });

  describe('unsubscribe', () => {
    it('should stop receiving events after unsubscribe', () => {
      tracker.register('s1');
      const events: ServerStateChangeEvent[] = [];
      const unsub = tracker.onStateChange((e) => events.push(e));
      tracker.transition('s1', 'connected');
      expect(events).toHaveLength(1);
      unsub();
      tracker.transition('s1', 'unhealthy');
      expect(events).toHaveLength(1);
    });

    it('should throw TypeError for non-function callback', () => {
      expect(() => tracker.onStateChange('not a function' as any)).toThrow(TypeError);
    });
  });

  describe('resetReconnectState', () => {
    it('should reset all reconnect-related fields', () => {
      tracker.register('s1');
      tracker.transition('s1', 'connected');
      const entry = tracker.getEntry('s1')!;
      entry.reconnectAttempts = 5;
      entry.consecutiveFailures = 3;
      entry.lastError = 'timeout';
      entry.failureStartedAt = new Date().toISOString();
      entry.nextRetryAt = new Date().toISOString();
      tracker.resetReconnectState('s1');
      const reset = tracker.getEntry('s1')!;
      expect(reset.reconnectAttempts).toBe(0);
      expect(reset.consecutiveFailures).toBe(0);
      expect(reset.lastError).toBeNull();
      expect(reset.failureStartedAt).toBeNull();
      expect(reset.nextRetryAt).toBeNull();
    });
  });

  describe('getAllStatuses', () => {
    it('should return status entries for all registered servers', () => {
      tracker.register('s1');
      tracker.register('s2');
      tracker.transition('s1', 'connected');
      const statuses = tracker.getAllStatuses(() => 3);
      expect(statuses).toHaveLength(2);
      const s1 = statuses.find((s) => s.name === 's1')!;
      expect(s1.state).toBe('connected');
      expect(s1.connected).toBe(true);
      expect(s1.toolCount).toBe(3);
      const s2 = statuses.find((s) => s.name === 's2')!;
      expect(s2.state).toBe('disconnected');
      expect(s2.connected).toBe(false);
    });
  });
});

/**
 * Unit tests for HealthMonitor — SA4E-37
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { HealthMonitor } from '../HealthMonitor.js';
import type { HealthMonitorDeps } from '../HealthMonitor.js';
import { DEFAULT_HEALTH_CONFIG } from '../../types/health.js';

function createMockLogger() {
  return {
    child: () => createMockLogger(),
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  } as any;
}

function createMockClient(shouldReject = false) {
  return {
    ping: vi.fn(() => {
      if (shouldReject) return Promise.reject(new Error('connection lost'));
      return Promise.resolve({});
    }),
    listTools: vi.fn(() => {
      if (shouldReject) return Promise.reject(new Error('connection lost'));
      return Promise.resolve({ tools: [] });
    }),
  } as any;
}

describe('HealthMonitor', () => {
  let monitor: HealthMonitor;
  let deps: HealthMonitorDeps;
  let logger: any;

  beforeEach(() => {
    vi.useFakeTimers();
    logger = createMockLogger();
    deps = {
      getConnectedServers: vi.fn(() => new Map()),
      onPingSuccess: vi.fn(),
      onPingFailed: vi.fn(),
    };
    monitor = new HealthMonitor(logger, deps, { ...DEFAULT_HEALTH_CONFIG });
  });

  afterEach(() => {
    monitor.stop();
    vi.useRealTimers();
  });

  describe('start / stop lifecycle', () => {
    it('should start and set interval', () => {
      expect(monitor.isRunning()).toBe(false);
      monitor.start();
      expect(monitor.isRunning()).toBe(true);
    });

    it('should stop and clear interval', () => {
      monitor.start();
      monitor.stop();
      expect(monitor.isRunning()).toBe(false);
    });

    it('should not create duplicate intervals if start called twice', () => {
      monitor.start();
      monitor.start();
      expect(monitor.isRunning()).toBe(true);
      monitor.stop();
      expect(monitor.isRunning()).toBe(false);
    });

    it('should invoke runCycle on interval tick', async () => {
      const client = createMockClient();
      (deps.getConnectedServers as any).mockReturnValue(new Map([['s1', client]]));
      monitor.start();
      await vi.advanceTimersByTimeAsync(DEFAULT_HEALTH_CONFIG.interval);
      expect(deps.onPingSuccess).toHaveBeenCalledWith('s1');
    });
  });

  describe('parallel pings via mock clients', () => {
    it('should ping all connected servers in parallel', async () => {
      const client1 = createMockClient();
      const client2 = createMockClient();
      (deps.getConnectedServers as any).mockReturnValue(
        new Map([['s1', client1], ['s2', client2]])
      );
      await monitor.runCycle();
      expect(deps.onPingSuccess).toHaveBeenCalledWith('s1');
      expect(deps.onPingSuccess).toHaveBeenCalledWith('s2');
      expect(client1.ping).toHaveBeenCalled();
      expect(client2.ping).toHaveBeenCalled();
    });

    it('should call onPingFailed when client.listTools rejects', async () => {
      const client = createMockClient(true);
      (deps.getConnectedServers as any).mockReturnValue(new Map([['s1', client]]));
      await monitor.runCycle();
      expect(deps.onPingFailed).toHaveBeenCalledWith('s1', 'connection lost');
    });
  });

  describe('ping timeout triggers onPingFailed', () => {
    it('should fail with timeout when client takes too long', async () => {
      const config = { ...DEFAULT_HEALTH_CONFIG, pingTimeout: 100 };
      monitor = new HealthMonitor(logger, deps, config);

      const slowClient = {
        ping: vi.fn(() => new Promise(() => {})),
      } as any;

      (deps.getConnectedServers as any).mockReturnValue(new Map([['s1', slowClient]]));

      const cyclePromise = monitor.runCycle();
      await vi.advanceTimersByTimeAsync(200);
      await cyclePromise;

      expect(deps.onPingFailed).toHaveBeenCalledWith('s1', expect.stringContaining('timeout'));
    });
  });

  describe('empty server list', () => {
    it('should skip cycle when no servers connected', async () => {
      (deps.getConnectedServers as any).mockReturnValue(new Map());
      await monitor.runCycle();
      expect(deps.onPingSuccess).not.toHaveBeenCalled();
      expect(deps.onPingFailed).not.toHaveBeenCalled();
    });
  });

  describe('multiple servers pinged concurrently', () => {
    it('should handle mixed success and failure', async () => {
      const okClient = createMockClient(false);
      const failClient = createMockClient(true);
      (deps.getConnectedServers as any).mockReturnValue(
        new Map([['ok', okClient], ['fail', failClient]])
      );
      await monitor.runCycle();
      expect(deps.onPingSuccess).toHaveBeenCalledWith('ok');
      expect(deps.onPingFailed).toHaveBeenCalledWith('fail', 'connection lost');
    });
  });

  describe('updateConfig', () => {
    it('should restart with new config if running', () => {
      monitor.start();
      expect(monitor.isRunning()).toBe(true);
      const newConfig = { ...DEFAULT_HEALTH_CONFIG, interval: 5000 };
      monitor.updateConfig(newConfig);
      expect(monitor.isRunning()).toBe(true);
    });
  });
});

/**
 * Unit tests for ReconnectManager — SA4E-37
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { ReconnectManager } from '../ReconnectManager.js';
import type { ReconnectCallbacks } from '../ReconnectManager.js';
import { DEFAULT_HEALTH_CONFIG } from '../../types/health.js';
import type { HealthCheckConfig } from '../../types/health.js';
import type { ServerConfig } from '../../McpConfigService.js';

vi.mock('@modelcontextprotocol/sdk/client/index.js', () => {
  const MockClient = vi.fn(function (this: any) {
    this.connect = vi.fn().mockResolvedValue(undefined);
    this.listTools = vi.fn().mockResolvedValue({ tools: [] });
    this.close = vi.fn().mockResolvedValue(undefined);
  });
  return { Client: MockClient };
});

vi.mock('../TransportFactory.js', () => ({
  createTransport: vi.fn().mockReturnValue({}),
}));

function createMockLogger() {
  return {
    child: () => createMockLogger(),
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  } as any;
}

describe('ReconnectManager', () => {
  let manager: ReconnectManager;
  let callbacks: ReconnectCallbacks;
  let config: HealthCheckConfig;
  let logger: any;

  const serverConfig: ServerConfig = {
    command: 'node',
    args: ['server.js'],
  };

  beforeEach(() => {
    vi.useFakeTimers();
    logger = createMockLogger();
    callbacks = {
      onReconnectSuccess: vi.fn(),
      onReconnectFailed: vi.fn(),
      onMaxRetriesExhausted: vi.fn(),
    };
    config = { ...DEFAULT_HEALTH_CONFIG, jitterEnabled: false };
    manager = new ReconnectManager(logger, config, callbacks);
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  describe('backoff delay calculation', () => {
    it('should calculate 1s for attempt 1', () => {
      const delay = manager.calculateDelay(1);
      expect(delay).toBe(1000);
    });

    it('should calculate 2s for attempt 2', () => {
      const delay = manager.calculateDelay(2);
      expect(delay).toBe(2000);
    });

    it('should calculate 4s for attempt 3', () => {
      const delay = manager.calculateDelay(3);
      expect(delay).toBe(4000);
    });

    it('should calculate 8s for attempt 4', () => {
      const delay = manager.calculateDelay(4);
      expect(delay).toBe(8000);
    });

    it('should calculate 16s for attempt 5', () => {
      const delay = manager.calculateDelay(5);
      expect(delay).toBe(16000);
    });

    it('should cap at 30s (maxDelay)', () => {
      const delay = manager.calculateDelay(6);
      expect(delay).toBe(30000);
    });

    it('should cap at 30s for very high attempt numbers', () => {
      const delay = manager.calculateDelay(20);
      expect(delay).toBe(30000);
    });
  });

  describe('jitter within +/-20% range', () => {
    it('should apply jitter when enabled', () => {
      const jitterConfig = { ...config, jitterEnabled: true, jitterRange: 0.2 };
      manager = new ReconnectManager(logger, jitterConfig, callbacks);

      const delays = new Set<number>();
      for (let i = 0; i < 100; i++) {
        delays.add(manager.calculateDelay(1));
      }
      // With jitter, base=1000, jitter=+/-200, range=[800,1200]
      for (const d of delays) {
        expect(d).toBeGreaterThanOrEqual(800);
        expect(d).toBeLessThanOrEqual(1200);
      }
      // With 100 samples, we should get more than 1 unique value
      expect(delays.size).toBeGreaterThan(1);
    });
  });

  describe('schedule / cancel reconnect', () => {
    it('should schedule a reconnect and return nextRetryAt', () => {
      const result = manager.scheduleReconnect('s1', serverConfig, 1);
      expect(result).not.toBeNull();
      expect(result).toMatch(/^\d{4}-\d{2}-\d{2}T/);
    });

    it('should cancel a scheduled reconnect', () => {
      manager.scheduleReconnect('s1', serverConfig, 1);
      manager.cancelReconnect('s1');
      // Advancing time should not trigger callback
      vi.advanceTimersByTime(2000);
      expect(callbacks.onReconnectSuccess).not.toHaveBeenCalled();
      expect(callbacks.onReconnectFailed).not.toHaveBeenCalled();
    });

    it('should not throw when canceling non-existent reconnect', () => {
      expect(() => manager.cancelReconnect('non-existent')).not.toThrow();
    });
  });

  describe('max retries triggers onMaxRetriesExhausted', () => {
    it('should call onMaxRetriesExhausted when attempt > maxRetries', () => {
      const result = manager.scheduleReconnect('s1', serverConfig, 11);
      expect(result).toBeNull();
      expect(callbacks.onMaxRetriesExhausted).toHaveBeenCalledWith('s1');
    });

    it('should not schedule when maxRetries exceeded', () => {
      manager.scheduleReconnect('s1', serverConfig, 11);
      vi.advanceTimersByTime(60000);
      expect(callbacks.onReconnectSuccess).not.toHaveBeenCalled();
      expect(callbacks.onReconnectFailed).not.toHaveBeenCalled();
    });
  });

  describe('successful reconnect calls onReconnectSuccess', () => {
    it('should call onReconnectSuccess after timer fires', async () => {
      manager.scheduleReconnect('s1', serverConfig, 1);

      // Advance past the 1s delay + flush microtasks for async attemptReconnect
      await vi.advanceTimersByTimeAsync(1500);

      expect(callbacks.onReconnectSuccess).toHaveBeenCalledWith('s1', expect.any(Object));
    });
  });

  describe('failed reconnect calls onReconnectFailed', () => {
    it('should call onReconnectFailed when connection throws', async () => {
      const { Client } = await import('@modelcontextprotocol/sdk/client/index.js');
      (Client as any).mockImplementation(function (this: any) {
        this.connect = vi.fn().mockRejectedValue(new Error('ECONNREFUSED'));
        this.listTools = vi.fn().mockResolvedValue({ tools: [] });
        this.close = vi.fn();
      });

      manager.scheduleReconnect('s1', serverConfig, 1);
      await vi.advanceTimersByTimeAsync(1100);

      expect(callbacks.onReconnectFailed).toHaveBeenCalledWith('s1', 1, 'ECONNREFUSED');
    });
  });

  describe('updateConfig', () => {
    it('should update internal config', () => {
      const newConfig = { ...config, maxDelay: 60000 };
      manager.updateConfig(newConfig);
      // After update, delay calculation should use new maxDelay
      const delay = manager.calculateDelay(10);
      expect(delay).toBeLessThanOrEqual(60000);
    });
  });
});

/**
 * SA4E-42 UT-11..19 — McpToolsRepository scoped SQL over a real better-sqlite3 DB.
 * Covers upsert idempotency, scoped prune/delete, empty-set guard, F-01 collision,
 * F-04 large-set fallback, and F-06 parameterized prune.
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import pino from 'pino';
import type Database from 'better-sqlite3';
import { makeTempDb, type TempDb } from '../../../../__tests__/sa4e-testkit.js';
import { McpToolsRepository } from '../McpToolsRepository.js';
import { SqliteDbAdapter } from '../../../memory/task-queue/SqliteDbAdapter.js';
import type { PreparedTool } from '../models/PreparedTool.js';

const silent = pino({ level: 'silent' });

function prepared(name: string, server: string, description = `${name} d`): PreparedTool {
  return {
    name,
    description,
    schemaJson: JSON.stringify({ type: 'object' }),
    category: server,
    server,
    vector: Buffer.from(new Float32Array([1, 2, 3, 4]).buffer),
  };
}

function names(db: Database.Database, server: string): string[] {
  return (db.prepare('SELECT name FROM mcp_tools WHERE server = ? ORDER BY name').all(server) as { name: string }[])
    .map((r) => r.name);
}

describe('McpToolsRepository', () => {
  let tmp: TempDb;
  let db: Database.Database;
  let repo: McpToolsRepository;

  beforeEach(() => {
    tmp = makeTempDb();
    db = tmp.dbManager.getDb();
    repo = new McpToolsRepository(new SqliteDbAdapter(db), silent);
  });
  afterEach(() => tmp.close());

  it('UT-11: upsertScoped inserts rows with server/category/vector', async () => {
    const count = await repo.upsertScoped([prepared('t1', 'S'), prepared('t2', 'S')], 'S');
    expect(count).toBe(2);
    const row = db.prepare('SELECT * FROM mcp_tools WHERE name = ?').get('t1') as any;
    expect(row.server).toBe('S');
    expect(row.category).toBe('S');
    expect(row.vector).toBeInstanceOf(Buffer);
  });

  it('UT-12: repeated upsert updates in place (no duplicate)', async () => {
    await repo.upsertScoped([prepared('t1', 'S', 'old')], 'S');
    await repo.upsertScoped([prepared('t1', 'S', 'new')], 'S');
    const rows = db.prepare('SELECT * FROM mcp_tools WHERE name = ?').all('t1') as any[];
    expect(rows).toHaveLength(1);
    expect(rows[0].description).toBe('new');
  });

  it('UT-13: pruneRemoved deletes rows not in the current set', async () => {
    await repo.upsertScoped([prepared('t1', 'S'), prepared('t2', 'S'), prepared('t3', 'S')], 'S');
    const removed = await repo.pruneRemoved('S', ['t1', 't2']);
    expect(removed).toBe(1);
    expect(names(db, 'S')).toEqual(['t1', 't2']);
  });

  it('UT-14: pruneRemoved with empty set is skipped (no wipe) + warns', async () => {
    const warn = vi.fn();
    const r = new McpToolsRepository(new SqliteDbAdapter(db), { warn } as any);
    await r.upsertScoped([prepared('t1', 'S'), prepared('t2', 'S')], 'S');
    const removed = await r.pruneRemoved('S', []);
    expect(removed).toBe(0);
    expect(names(db, 'S')).toEqual(['t1', 't2']);
    expect(warn).toHaveBeenCalled();
  });

  it('UT-15: deleteByServer removes only that server (core + others untouched)', async () => {
    await repo.upsertScoped([prepared('s1', 'S')], 'S');
    await repo.upsertScoped([prepared('t1', 'T')], 'T');
    db.prepare('INSERT INTO mcp_tools (name, description, schema_json, category, server, vector) VALUES (?,?,?,?,?,?)')
      .run('core', 'core', '{}', 'memory', null, null);
    await repo.deleteByServer('S');
    expect(names(db, 'S')).toEqual([]);
    expect(names(db, 'T')).toEqual(['t1']);
    const core = db.prepare('SELECT COUNT(*) c FROM mcp_tools WHERE server IS NULL').get() as any;
    expect(core.c).toBe(1);
  });

  it('UT-16: deleteByServer for unknown server returns 0 (no error)', async () => {
    expect(await repo.deleteByServer('nope')).toBe(0);
  });

  it('UT-17: prune with >900 tools uses temp-table fallback (no bound-var error)', async () => {
