/**
 * SA4E-42 PBT-01..04 — property-based tests over a real better-sqlite3 DB.
 * Idempotency, scope isolation, prune convergence, and injection-safety of names.
 */
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import pino from 'pino';
import type Database from 'better-sqlite3';
import { makeTempDb } from '../../../../__tests__/sa4e-testkit.js';
import { ReindexService } from '../ReindexService.js';
import { SqliteDbAdapter } from '../../../memory/task-queue/SqliteDbAdapter.js';
import { FakeEmbedder, FakeToolSource } from './reindex-fakes.js';

const silent = pino({ level: 'silent' });
const RUNS = 15;

function serviceFor(db: Database.Database, src: FakeToolSource): ReindexService {
  return new ReindexService(() => new SqliteDbAdapter(db), new FakeEmbedder(), src, silent);
}

function namesOf(db: Database.Database, server: string): string[] {
  return (db.prepare('SELECT name FROM mcp_tools WHERE server = ? ORDER BY name').all(server) as { name: string }[])
    .map((r) => r.name);
}

const serverArb = fc.constantFrom('A', 'B', 'C');
const stateArb = fc.constantFrom('connected', 'disconnected', 'failed') as fc.Arbitrary<
  'connected' | 'disconnected' | 'failed'
>;

describe('reindex — property-based', () => {
  it('PBT-01: N connect events ≡ 1 connect event (idempotency)', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.uniqueArray(fc.string({ minLength: 1, maxLength: 12 }), { maxLength: 12 }),
        fc.integer({ min: 1, max: 6 }),
        async (tools, n) => {
          const single = await runConnects(tools, 1);
          const many = await runConnects(tools, n);
          expect(many).toEqual(single);
          expect(many).toEqual([...tools].sort());
        },
      ),
      { numRuns: RUNS },
    );
  });

  it('PBT-02: no event on server X ever mutates another server or core rows', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.array(fc.tuple(serverArb, stateArb), { minLength: 1, maxLength: 12 }),
        async (events) => {
          const tmp = makeTempDb();
          try {
            const db = tmp.dbManager.getDb();
            const src = seedThreeServers(db);
            const svc = serviceFor(db, src);
            for (const [server, state] of events) {
              src.setConnected(server, state === 'connected');
              if (state === 'connected') await svc.reindexConnected(server);
              else await svc.reindexRemoved(server);
              assertNoLeak(db);
            }
            const core = db.prepare('SELECT COUNT(*) c FROM mcp_tools WHERE server IS NULL').get() as any;
            expect(core.c).toBe(1);
          } finally {
            tmp.close();
          }
        },
      ),
      { numRuns: RUNS },
    );
  });

  it('PBT-03: prune converges to the current tool set', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.uniqueArray(fc.string({ minLength: 1, maxLength: 8 }), { minLength: 1, maxLength: 8 }),
        fc.uniqueArray(fc.string({ minLength: 1, maxLength: 8 }), { minLength: 1, maxLength: 8 }),
        async (initial, next) => {
          const tmp = makeTempDb();
          try {
            const db = tmp.dbManager.getDb();
            const src = new FakeToolSource();
            src.setConnected('S', true);
            const svc = serviceFor(db, src);
            src.setTools('S', initial);
            await svc.reindexConnected('S');
            src.setTools('S', next);
            await svc.reindexConnected('S');
            expect(namesOf(db, 'S')).toEqual([...next].sort());
          } finally {
            tmp.close();
          }
        },
      ),
      { numRuns: RUNS },
    );
  });

  it('PBT-04: adversarial tool names are stored as data; table intact (F-06)', async () => {
    const adversarial = [`x'); DROP TABLE mcp_tools;--`, 'a" OR "1"="1', "n\nl%_"];
    await fc.assert(
      fc.asyncProperty(fc.uniqueArray(fc.string({ minLength: 1, maxLength: 16 }), { maxLength: 6 }), async (extra) => {
        const tmp = makeTempDb();
        try {
          const db = tmp.dbManager.getDb();
          const src = new FakeToolSource();
          src.setConnected('S', true);
          const svc = serviceFor(db, src);
          const all = Array.from(new Set([...adversarial, ...extra]));
          src.setTools('S', all);
          await svc.reindexConnected('S');
          expect(namesOf(db, 'S')).toEqual([...all].sort());
          const tbl = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='mcp_tools'").get();
          expect(tbl).toBeDefined();
        } finally {
          tmp.close();
        }
      }),
      { numRuns: RUNS },
    );
  });
});

async function runConnects(tools: string[], n: number): Promise<string[]> {
  const tmp = makeTempDb();
  try {
    const db = tmp.dbManager.getDb();
    const src = new FakeToolSource();
    src.setTools('S', tools);
    src.setConnected('S', true);
    const svc = serviceFor(db, src);
    for (let i = 0; i < n; i++) await svc.reindexConnected('S');
    return namesOf(db, 'S');
  } finally {
    tmp.close();
  }
}

function seedThreeServers(db: Database.Database): FakeToolSource {
  const src = new FakeToolSource();
  src.setTools('A', ['a1', 'a2']);
  src.setTools('B', ['b1']);
  src.setTools('C', ['c1', 'c2', 'c3']);
  db.prepare('INSERT INTO mcp_tools (name, description, schema_json, category, server, vector) VALUES (?,?,?,?,?,?)')
    .run('core_tool', 'core', '{}', 'memory', null, null);
  return src;
}

function assertNoLeak(db: Database.Database): void {
  const bad = db.prepare(
    "SELECT COUNT(*) c FROM mcp_tools WHERE server IS NOT NULL AND server NOT IN ('A','B','C')",
  ).get() as any;
  expect(bad.c).toBe(0);
}

/**
 * SA4E-42 (F-03) — bounded, allowlisted error rendering for logs.
 * Returns the message only (never a raw object/stack), capped at 500 chars,
 * with control characters stripped to prevent log injection (CWE-117).
 */
export function safeError(e: unknown): string {
  const raw = e instanceof Error ? e.message : String(e);
  return raw.replace(/[\r\n\t\u0000-\u001f]+/g, ' ').slice(0, 500);
}

import { PegaSchemaLoader } from './PegaSchemaLoader.js';
import type { UnresolvedDependency } from './models.js';
import type { PegaRuleKbSchema } from './strategies/KbDrivenPegaParserStrategy.js';

export interface PegaCrawlKey {
  insKey: string;
  pxObjClass: string;
  pyClassName: string;
  pyRuleName: string;
}

export interface PegaCrawlPlan {
  missing: PegaCrawlKey[];
  cached: string[];
}

export interface PegaCrawlBatchRequest {
  projectId: string;
  rules: Record<string, unknown>[];
  visitedKeys: string[];
}

export interface PegaCrawlBatchResponse {
  stored: number;
  nextBatch: PegaCrawlKey[];
}

export class PegaCrawler {
  private schemaMap = new Map<string, PegaRuleKbSchema>();

  constructor() {
    this.loadSchemas();
  }

  private loadSchemas(): void {
    const schemas = PegaSchemaLoader.loadAllSchemas();
    for (const s of schemas) {
      this.schemaMap.set(s.targetClass, s);
    }
  }

  public plan(ruleKeys: string[], visitedKeys: Set<string>): PegaCrawlPlan {
    const missing: PegaCrawlKey[] = [];
    const cached: string[] = [];

    for (const key of ruleKeys) {
      if (visitedKeys.has(key)) {
        cached.push(key);
        continue;
      }
      const parsed = this.parseInsKey(key);
      if (!parsed) {
        cached.push(key);
        continue;
      }
      missing.push(parsed);
    }

    return { missing, cached };
  }

  /** Rule types the Pega REST API can actually return via GET /rules/{insKey}. */
  private static FETCHABLE_TYPES = new Set([
    'Rule-Obj-Class',
    'Data-Admin-Operator-ID',
    'Rule-Obj-Flow',
    'Rule-Obj-CaseType',
    'Rule-Obj-Activity',
    'Rule-Obj-FlowAction',
    'Rule-HTML-Section',
  ]);

  public computeNextBatch(
    ingestedRules: Record<string, unknown>[],
    visitedKeys: Set<string>,
    projectId: string,
  ): PegaCrawlKey[] {
    const nextBatch: PegaCrawlKey[] = [];
    const seen = new Set<string>();

    for (const rule of ingestedRules) {
      const deps = this.extractRuleReferences(rule);
      for (const dep of deps) {
        if (!PegaCrawler.FETCHABLE_TYPES.has(dep.ruleType)) continue;

        const insKey = dep.insKey || (
          (dep.className && dep.className !== '@baseclass')
            ? `${dep.ruleType.toUpperCase()} ${dep.className} ${dep.ruleName}`
            : `${dep.ruleType.toUpperCase()} ${dep.ruleName}`
        );

        if (visitedKeys.has(insKey) || seen.has(insKey)) continue;
        seen.add(insKey);
        nextBatch.push({
          insKey,
          pxObjClass: dep.ruleType,
          pyClassName: dep.className,
          pyRuleName: dep.ruleName,
        });
      }
    }

    return nextBatch;
  }

  public parseInsKey(insKey: string): PegaCrawlKey | null {
    const cleanKey = insKey.split('#')[0].trim();
    const tokens = cleanKey.split(/\s+/);
    if (tokens.length < 2) return null;

    const pxObjClass = this.normalizeObjClass(tokens[0]);

    if (tokens.length >= 3) {
      return {
        insKey,
        pxObjClass,
        pyClassName: tokens[1],
        pyRuleName: tokens[2],
      };
    }

    return {
      insKey,
      pxObjClass,
      pyClassName: "@baseclass",
      pyRuleName: tokens[1],
    };
  }

  private normalizeObjClass(raw: string): string {
    if (raw.startsWith('RULE-OBJ-')) {
      return 'Rule-' + raw.charAt(5).toUpperCase() + raw.substring(6).replace(/-/g, '-');
    }
    return raw;
  }

  private extractRuleReferences(json: Record<string, unknown>): UnresolvedDependency[] {
    const deps: UnresolvedDependency[] = [];
    const visited = new Set<string>();

    const pushDep = (ruleType: string, className: string, ruleName: string, exactInsKey?: string) => {
      const key = exactInsKey || `${ruleType}:${className}:${ruleName}`;
      if (visited.has(key)) return;
      visited.add(key);
      deps.push({ insKey: exactInsKey, ruleType, className, ruleName });
    };

    if (json.pxObjClass) {
      const pzKey = (json.pzInsKey as string) || (json.pxInsId as string);
      pushDep(json.pxObjClass as string, (json.pyClassName as string) || '@baseclass', (json.pyRuleName as string) || '', pzKey);
    }

    if (json.pyAccessGroup) {
      pushDep('Data-Admin-Operator-AccessGroup', '@baseclass', json.pyAccessGroup as string, `DATA-ADMIN-OPERATOR-ACCESSGROUP ${json.pyAccessGroup}`);
    }

    if (json.pyApplication && json.pyApplicationVersion) {
      pushDep('Rule-Application', '@baseclass', json.pyApplication as string, `RULE-APPLICATION ${json.pyApplication} ${json.pyApplicationVersion}`);
    }

    if (json.pyClassName && json.pyClassName !== '@baseclass') {
      pushDep('Rule-Obj-Class', '@baseclass', json.pyClassName as string);
    }

    if (json.pySuperClass) {
      pushDep('Rule-Obj-Class', '@baseclass', json.pySuperClass as string);
    }

    if (json.pyPatternParent) {
      pushDep('Rule-Obj-Class', '@baseclass', json.pyPatternParent as string);
    }

    if (json.pyDerivesFrom) {
      pushDep('Rule-Obj-Class', '@baseclass', json.pyDerivesFrom as string);
    }

    const pxRuleReferences = json.pxRuleReferences;
    if (Array.isArray(pxRuleReferences)) {
      for (const ref of pxRuleReferences) {
        if (ref && typeof ref === 'object') {
          const r = ref as Record<string, unknown>;
          const refObjClass = (r.pxRuleObjClass as string) || '';
          const refClassName = (r.pxRuleClassName as string) || '@baseclass';
          const refName = r.pyRuleName as string | undefined;
          if (!refObjClass || !refName) continue;

          // Rule-Obj-Class refs are always 2-token insKeys
          if (refObjClass === 'Rule-Obj-Class') {
            pushDep('Rule-Obj-Class', '@baseclass', refName);
          } else {
            pushDep(refObjClass, refClassName, refName);
          }
        }
      }
    }

    const steps = json.steps || json.pySteps;
    if (Array.isArray(steps)) {
      for (const step of steps) {
        if (typeof step !== 'object' || !step) continue;
        const s = step as Record<string, unknown>;
        const method = (s.pyMethod as string) || '';
        const params = (s.pyMethodParameters as string) || '';

        if ((method === 'Call' || method === 'Branch') && params) {
          const parts = params.split('.');
          if (parts.length >= 2) {
            pushDep('Rule-Obj-Activity', parts[0], parts[1]);
          } else {
            pushDep('Rule-Obj-Activity', '@baseclass', params);
          }
        }

        if (method === 'Property-Set' && params && params.includes('.')) {
          const dot = params.lastIndexOf('.');
          const cls = params.substring(0, dot);
          const prop = params.substring(dot + 1);
          if (cls && prop) {
            pushDep('Rule-Obj-Property', cls, prop);
          }
        }
      }
    }

    const pages = json.pyPagesAndClasses || json.pxPagesAndClasses;
    if (Array.isArray(pages)) {
      for (const p of pages) {
        if (p && typeof p === 'object') {
          const page = p as Record<string, unknown>;
          const pageClass = (page.pyPagesAndClassesClass || page.pxPagesAndClassesClass) as string | undefined;
          if (pageClass && pageClass !== '@baseclass' && !pageClass.startsWith('Code-') && !pageClass.startsWith('Data-')) {
            pushDep('Rule-Obj-Class', '@baseclass', pageClass);
          }
        }
      }
    }

    const flowActions = json.pyFlowActions;
    if (Array.isArray(flowActions)) {
      for (const fa of flowActions) {
        if (fa && typeof fa === 'object') {
          const f = fa as Record<string, unknown>;
          if (f.pyFlowActionName) {
            pushDep('Rule-Obj-FlowAction', (json.pyClassName as string) || '@baseclass', f.pyFlowActionName as string);
          }
        }
      }
    }

    return deps;
  }
}

/**
 * SA4E-158 — PegaIndexer: Phase 1 of separated ingest pipeline.
 * SA4E-171 (cutover): parses rule → stores into symbols table (via PegaSymbolSync).
 * No longer writes PEGA_INDEX into knowledge_entries — rules live in symbols only.
 * Returns symbolId for Phase 2 (syncIndexedRulesToKb / graph projection).
 */
import type { MemoryEngine } from '../memory/engine/core.js';
import type { PegaIngestRuleRequest, UnresolvedDependency } from './models.js';
import { PegaParser, type ExtractedPegaSymbol } from './PegaParser.js';
import { PegaRuleAstParser } from './PegaRuleAstParser.js';
import { syncRuleToSymbols } from './PegaSymbolSync.js';
import { buildFqn, resolveRuleNameField } from './pega-mapping.js';
import pino from 'pino';

const logger = pino({ name: 'pega-indexer' });

/** Result of indexRule — stored raw rule data */
export interface IndexRuleResult {
  status: 'success' | 'skipped';
  ruleId: number;
  fqn: string;
  isRule: boolean;
  reason?: string;
  dependencies: UnresolvedDependency[];
}

/**
 * Phase 1: Parse + checksum dedup + store into symbols table.
 * Does NOT create KB entries, TAG_ENRICHMENT tasks, or legacy pega: graph nodes.
 * CODE_ENRICHMENT task is created by syncRuleToSymbols.
 */
export async function indexRule(
  memoryEngine: MemoryEngine,
  parser: PegaParser,
  astParser: PegaRuleAstParser,
  req: PegaIngestRuleRequest,
): Promise<IndexRuleResult> {
  // Parse symbol from rule JSON
  let symbol: ExtractedPegaSymbol;
  try {
    symbol = parser.parseSymbol(req.ruleJson);
  } catch (err) {
    const ruleClass = (req.ruleJson as any)?.pxObjClass || 'unknown';
    const ruleName = (req.ruleJson as any)?.pyRuleName || 'unknown';
    logger.warn({ ruleClass, ruleName, err: (err as Error).message },
      'Rule type not supported by parser — skipped');
    return { status: 'skipped', ruleId: -1, fqn: '', isRule: false,
      reason: `parser_skip: ${ruleClass}`, dependencies: [] };
  }

  const deps = parser.extractDependencies(req.ruleJson);

  // Checksum dedup — skip if already indexed in symbols with matching content hash
  // FQN uses the canonical rule-name fallback (matches PegaSymbolSync signature).
  const canonicalFqn = buildFqn(
    String((req.ruleJson as any)?.pxObjClass || ''),
    String((req.ruleJson as any)?.pyClassName || ''),
    resolveRuleNameField(req.ruleJson),
  );
  if (req.checksum) {
    const { exists, checksumMatch } = await checkRuleChecksum(
      memoryEngine, req.projectId, canonicalFqn, req.checksum,
    );
    if (exists && checksumMatch) {
      return { status: 'skipped', ruleId: -1, fqn: symbol.fqn,
        isRule: symbol.isRule, reason: 'checksum_match', dependencies: deps };
    }
  }

  const ast = astParser.parse(req.ruleJson);
  const promptCtx = astParser.toPromptContext(ast);

  // Store rule into symbols table (virtual file + symbol + body + CODE_ENRICHMENT)
  let result;
  try {
    result = await syncRuleToSymbols(
      memoryEngine.getAdapter(), req.ruleJson, req.projectId, promptCtx,
    );
  } catch (err) {
    logger.warn({ err, fqn: symbol.fqn }, 'Failed to sync rule to symbols — skipped');
    return { status: 'skipped', ruleId: -1, fqn: symbol.fqn,
      isRule: symbol.isRule, reason: 'symbol_sync_error', dependencies: deps };
  }
  if (!result) {
    return { status: 'skipped', ruleId: -1, fqn: symbol.fqn,
      isRule: symbol.isRule, reason: 'symbol_skip', dependencies: deps };
  }

  return { status: 'success', ruleId: result.symbolId, fqn: symbol.fqn,
    isRule: symbol.isRule, dependencies: deps };
}

/** Check if rule exists in symbols with matching content hash. */
async function checkRuleChecksum(
  memoryEngine: MemoryEngine,
  projectId: string,
  fqn: string,
  checksum: string,
): Promise<{ exists: boolean; checksumMatch: boolean }> {
  const adapter = memoryEngine.getAdapter();
  const row = await adapter.getAsync<{ content_hash: string | null }>(
    `SELECT f.content_hash
     FROM symbols s JOIN files f ON f.id = s.file_id
     WHERE s.project_id = $1 AND s.signature = $2 AND s.kind LIKE 'pega_%'
     LIMIT 1`,
    [projectId, fqn],
  );
  if (!row) return { exists: false, checksumMatch: false };
  return { exists: true, checksumMatch: row.content_hash === checksum };
}

/**
 * SA4E-88 — PegaIndexerTool: MCP tool handler for full/incremental
 * indexing of .pega.json rules into the KB Graph (nodes + edges).
 * Runs on-demand or at workspace open to build/update the knowledge graph.
 */

import { join, relative } from 'node:path';
import type { Logger } from 'pino';
import {
  loadHashCache, saveHashCache, compareFileHash, computeHash,
  type HashCacheData,
} from './PegaHashCache.js';
import {
  discoverRuleFiles, readFileSafe,
  buildNodeId, ruleClassToNodeType, buildNodeLabel, extractEdgesFromRule,
} from './PegaIndexerHelpers.js';

/** Adapter interface for graph node insertion (DIP). */
export interface GraphNodeWriter {
  addNode(entryId: string, label: string, type: string, tier: string, projectId: string): Promise<void>;
}

/** Adapter interface for graph edge insertion (DIP). */
export interface GraphEdgeWriter {
  addEdge(source: string, target: string, weight: number, relType: string): Promise<void>;
}

/** Adapter combining both graph write capabilities. */
export interface GraphWriter extends GraphNodeWriter, GraphEdgeWriter {
  removeNodesByPrefix(prefix: string): Promise<void>;
}

/** Input arguments for the pega_index_workspace tool. */
export interface IndexWorkspaceArgs {
  mode?: 'full' | 'incremental';
  rules_dir?: string;
}

/** Statistics returned after indexing completes. */
export interface IndexStats {
  filesScanned: number;
  filesChanged: number;
  nodesCreated: number;
  nodesUpdated: number;
  edgesCreated: number;
  errors: number;
  duration_ms: number;
}

/** Structured response from the indexer tool. */
export interface IndexResult {
  status: 'completed' | 'error';
  mode: 'full' | 'incremental';
  stats: IndexStats;
  error?: string;
}

/**
 * PegaIndexerTool — orchestrates full or incremental indexing of Pega rules.
 * Uses Strategy pattern via injected GraphWriter for graph operations.
 */
export class PegaIndexerTool {
  constructor(
    private readonly graphWriter: GraphWriter,
    private readonly logger: Logger,
  ) {}

  /**
   * Execute the indexing operation.
   * @param args - Tool input (mode, rules_dir)
   * @param workspaceRoot - Workspace root for hash cache location
   * @returns Structured result with stats
   */
  async execute(args: IndexWorkspaceArgs, workspaceRoot: string): Promise<IndexResult> {
    const mode = args.mode || 'incremental';
    const rulesDir = args.rules_dir || join(workspaceRoot, 'rules');
    const start = Date.now();
    const stats = this.createEmptyStats();

    try {
      const filePaths = await discoverRuleFiles(rulesDir);
      stats.filesScanned = filePaths.length;

      if (mode === 'full') {
        await this.fullIndex(filePaths, rulesDir, workspaceRoot, stats);
      } else {
        await this.incrementalIndex(filePaths, rulesDir, workspaceRoot, stats);
      }

      stats.duration_ms = Date.now() - start;
      return { status: 'completed', mode, stats };
    } catch (err: any) {
      stats.duration_ms = Date.now() - start;
      this.logger.error({ err: err.message }, 'pega_index_workspace failed');
      return { status: 'error', mode, stats, error: err.message };
    }
  }

  private createEmptyStats(): IndexStats {
    return {
      filesScanned: 0, filesChanged: 0, nodesCreated: 0,
      nodesUpdated: 0, edgesCreated: 0, errors: 0, duration_ms: 0,
    };
  }

  /** Full re-index: clear existing pega nodes, re-parse all files. */
  private async fullIndex(
    filePaths: string[], rulesDir: string,
    workspaceRoot: string, stats: IndexStats,
  ): Promise<void> {
    await this.graphWriter.removeNodesByPrefix('pega::');
    const cache: HashCacheData = { version: 1, entries: {} };

    for (const filePath of filePaths) {
      const relPath = relative(rulesDir, filePath);
      const hash = await this.processFile(filePath, stats);
      if (hash) cache.entries[relPath] = hash;
    }

    await saveHashCache(workspaceRoot, cache);
  }

  /** Incremental index: only process files whose hash changed. */
  private async incrementalIndex(
    filePaths: string[], rulesDir: string,
    workspaceRoot: string, stats: IndexStats,
  ): Promise<void> {
    const cache = await loadHashCache(workspaceRoot);

    for (const filePath of filePaths) {
      const relPath = relative(rulesDir, filePath);
      const content = await readFileSafe(filePath);
      if (!content) { stats.errors++; continue; }

      const cmp = compareFileHash(relPath, content, cache);
      if (!cmp.changed) continue;

      stats.filesChanged++;
      const ok = await this.indexContent(content, stats);
      if (ok) cache.entries[relPath] = cmp.hash;
    }

    await saveHashCache(workspaceRoot, cache);
  }

  /** Read file, compute hash, index content. Returns hash on success. */
  private async processFile(filePath: string, stats: IndexStats): Promise<string | null> {
    const content = await readFileSafe(filePath);
    if (!content) { stats.errors++; return null; }
    stats.filesChanged++;
    const ok = await this.indexContent(content, stats);
    return ok ? computeHash(content) : null;
  }

  /** Parse JSON and insert node + edges into graph. */
  private async indexContent(content: string, stats: IndexStats): Promise<boolean> {
    let json: Record<string, unknown>;
    try { json = JSON.parse(content); } catch { stats.errors++; return false; }

    const pxObjClass = (json.pxObjClass as string) || '';
    if (!pxObjClass) { stats.errors++; return false; }

    await this.insertNode(json, pxObjClass, stats);
    await this.insertEdges(json, stats);
    return true;
  }

  /** Insert a single graph node for a rule. */
  private async insertNode(
    json: Record<string, unknown>, pxObjClass: string, stats: IndexStats,
  ): Promise<void> {
    const nodeId = `pega::${buildNodeId(json)}`;
    const nodeType = ruleClassToNodeType(pxObjClass);
    const label = buildNodeLabel(json);
    try {
      await this.graphWriter.addNode(nodeId, label, nodeType, 'PEGA', '');
      stats.nodesCreated++;
    } catch {
      stats.nodesUpdated++;
    }
  }

  /** Insert all extracted edges for a rule. */
  private async insertEdges(
    json: Record<string, unknown>, stats: IndexStats,
  ): Promise<void> {
    const edges = extractEdgesFromRule(json);
    for (const edge of edges) {
      try {
        await this.graphWriter.addEdge(
          `pega::${edge.sourceId}`, `pega::${edge.targetId}`,
          edge.weight, edge.label,
        );
        stats.edgesCreated++;
      } catch {
        // Edge conflict or dangling target — non-fatal
      }
    }
  }
}

/**
 * PegaLogicNormalizer — Chuyển đổi cấu hình Pega Activity & Data Transform 
 * thành Mã Giả Cấu Trúc kèm RowID phục vụ Browser Agent Tự Động Hóa UI.
 */

export interface NormalizedStep {
  rowId: string;
  stepNum: string;
  context: string;
  condition?: string;
  action: string;
  jumpCondition?: string;
}

export interface NormalizedDataAction {
  rowId: string;
  actionType: string;
  target?: string;
  source?: string;
  condition?: string;
}

export class PegaLogicNormalizer {
  public static normalizeActivity(json: Record<string, unknown>): string {
    const steps = Array.isArray(json.steps) ? json.steps : [];
    const lines: string[] = [];
    lines.push(`ACTIVITY: ${json.pyClassName}.${json.pyActivityName || json.pyLabel}`);

    let idx = 1;
    for (const step of steps) {
      if (typeof step !== 'object' || !step) continue;
      const norm = PegaLogicNormalizer.parseActivityStep(step as Record<string, unknown>, idx++);
      lines.push(PegaLogicNormalizer.formatStep(norm));
    }
    return lines.join('\n');
  }

  private static parseActivityStep(step: Record<string, unknown>, index: number): NormalizedStep {
    const rowId = (step.pyStepId as string) || `ROW-${index}`;
    const stepNum = (step.pyStepNum as string) || `${index}`;
    const context = (step.pyStepContext as string) || 'Primary';
    const method = (step.pyMethod as string) || 'Property-Set';
    const params = (step.pyMethodParameters as string) || '';

    const preWhen = (step.pyPreCondition as any)?.pyWhenName;
    const condition = preWhen ? `IF NOT When(${preWhen}) THEN SKIP` : undefined;

    const action = `${method}(${params})`;
    const postWhen = (step.pyPostCondition as any)?.pyWhenName;
    const jumpCondition = postWhen ? `IF When(${postWhen}) THEN JUMP` : undefined;

    return { rowId, stepNum, context, condition, action, jumpCondition };
  }

  private static formatStep(s: NormalizedStep): string {
    let out = `[RowID: ${s.rowId} | Step ${s.stepNum}] Context: ${s.context}`;
    if (s.condition) out += ` | Pre: ${s.condition}`;
    out += ` | Action: ${s.action}`;
    if (s.jumpCondition) out += ` | Post: ${s.jumpCondition}`;
    return out;
  }

  public static normalizeDataTransform(json: Record<string, unknown>): string {
    const actions = Array.isArray(json.pyActions) ? json.pyActions : [];
    const lines: string[] = [];
    lines.push(`DATA TRANSFORM: ${json.pyClassName}.${json.pyModelName || json.pyTransformName}`);

    let idx = 1;
    for (const act of actions) {
      if (typeof act !== 'object' || !act) continue;
      const norm = PegaLogicNormalizer.parseDataAction(act as Record<string, unknown>, idx++);
      lines.push(PegaLogicNormalizer.formatDataAction(norm));
    }
    return lines.join('\n');
  }

  private static parseDataAction(act: Record<string, unknown>, index: number): NormalizedDataAction {
    const rowId = (act.pyActionId as string) || `ACTION-${index}`;
    const actionType = (act.pyActionType as string) || 'Set';
    const target = (act.pyTarget as string) || '';
    const source = (act.pySource as string) || (act.pyTransformName as string) || '';
    const condition = (act.pyWhenCondition as string) || undefined;
    return { rowId, actionType, target, source, condition };
  }

  private static formatDataAction(a: NormalizedDataAction): string {
    let out = `  [RowID: ${a.rowId}] -> ${a.actionType}`;
    if (a.target) out += ` Target: ${a.target}`;
    if (a.source) out += ` Source: ${a.source}`;
    if (a.condition) out += ` (WHEN ${a.condition})`;
    return out;
  }
}

import * as fs from 'fs';
import * as path from 'path';

export interface PegaProjectInfo {
  isPegaProject: boolean;
  applicationName?: string;
  rulesetName?: string;
  rulesetVersion?: string;
  pzInsKey?: string;
  sourceDir?: string;
  confidence: number;
  indicators: string[];
}

export class PegaProjectDetector {
  public static detect(workspaceRoot: string): PegaProjectInfo {
    const info: PegaProjectInfo = {
      isPegaProject: false,
      confidence: 0,
      indicators: [],
    };

    const indicators: Array<{ check: string; weight: number; cb: () => void }> = [
      {
        check: 'pega-project.json',
        weight: 60,
        cb: () => {
          const p = path.join(workspaceRoot, 'pega-project.json');
          if (!fs.existsSync(p)) return;
          try {
            const content = JSON.parse(fs.readFileSync(p, 'utf-8'));
            if (content.applicationName) info.applicationName = content.applicationName;
            if (content.rulesetName) info.rulesetName = content.rulesetName;
            if (content.pzInsKey) {
              info.pzInsKey = content.pzInsKey;
            } else if (content.applicationName) {
              info.pzInsKey = `RULE-APPLICATION ${content.applicationName.toUpperCase()}`;
            }
            info.indicators.push('pega-project.json');
          } catch (err) { console.debug('[PegaProjectDetector] skip invalid json :', (err as Error).message); }
        },
      },
      {
        check: 'Application.xml',
        weight: 50,
        cb: () => {
          const p = path.join(workspaceRoot, 'Application.xml');
          if (!fs.existsSync(p)) return;
          const content = fs.readFileSync(p, 'utf-8');
          const nameMatch = content.match(/<application\s+name=['"]([^'"]+)['"]/i);
          const rsMatch = content.match(/ruleset=['"]([^'"]+)['"]/i);
          const keyMatch = content.match(/pzInsKey=['"]([^'"]+)['"]/i);
          if (nameMatch) {
            info.applicationName = nameMatch[1];
            if (!info.pzInsKey) {
              info.pzInsKey = keyMatch ? keyMatch[1] : `RULE-APPLICATION ${nameMatch[1].toUpperCase()}`;
            }
          }
          if (rsMatch) info.rulesetName = rsMatch[1];
          info.indicators.push('Application.xml');
        },
      },
      {
        check: 'application.properties',
        weight: 40,
        cb: () => {
          const p = path.join(workspaceRoot, 'application.properties');
          if (!fs.existsSync(p)) return;
          const content = fs.readFileSync(p, 'utf-8');
          const rsMatch = content.match(/ruleset\.name\s*=\s*(\S+)/);
          const rvMatch = content.match(/ruleset\.version\s*=\s*(\S+)/);
          if (rsMatch) info.rulesetName = rsMatch[1];
          if (rvMatch) info.rulesetVersion = rvMatch[1];
          info.indicators.push('application.properties');
        },
      },
      {
        check: 'META-INF/contents.txt',
        weight: 45,
        cb: () => {
          const p = path.join(workspaceRoot, 'META-INF', 'contents.txt');
          if (!fs.existsSync(p)) return;
          const firstLine = fs.readFileSync(p, 'utf-8').split('\n')[0];
          if (firstLine.includes('Instance Key') || firstLine.includes('RULE-OBJ-')) {
            info.indicators.push('META-INF/contents.txt (Pega export)');
          }
        },
      },
      {
        check: 'src/ directory with .pega files',
        weight: 35,
        cb: () => {
          const srcDir = path.join(workspaceRoot, 'src');
          if (!fs.existsSync(srcDir)) return;
          const entries = fs.readdirSync(srcDir, { withFileTypes: true });
          for (const e of entries) {
            if (e.isDirectory()) {
              const subDir = path.join(srcDir, e.name);
              const files = fs.readdirSync(subDir);
              if (files.some(f => f.endsWith('.pega'))) {
                info.indicators.push(`src/${e.name}/ (has .pega files)`);
                return;
              }
            }
          }
        },
      },
      {
        check: 'JSON files with pxObjClass',
        weight: 40,
        cb: () => {
          const srcDir = path.join(workspaceRoot, 'src');
          if (!fs.existsSync(srcDir)) return;
          const entries = fs.readdirSync(srcDir, { withFileTypes: true });
          for (const e of entries) {
            if (e.isDirectory()) {
              const subDir = path.join(srcDir, e.name);
              const files = fs.readdirSync(subDir);
              for (const f of files) {
                if (!f.endsWith('.json')) continue;
                try {
                  const content = JSON.parse(fs.readFileSync(path.join(subDir, f), 'utf-8'));
                  if (content.pxObjClass && content.pxObjClass.startsWith('Rule-')) {
                    info.rulesetName = e.name;
                    info.sourceDir = subDir;
                    info.indicators.push(`JSON with pxObjClass in src/${e.name}/`);
                    return;
                  }
                } catch (err) { console.debug('[PegaProjectDetector] skip :', (err as Error).message); }
              }
            }
          }
        },
      },
      {
        check: '*_rules.jar or *_schema.jar',
        weight: 30,
        cb: () => {
          const files = fs.readdirSync(workspaceRoot);
          for (const f of files) {
            if (f.endsWith('_rules.jar') || f.endsWith('_schema.jar') || f.endsWith('.jar')) {
              info.indicators.push(`${f} (Pega archive)`);
              return;
            }
          }
        },
      },
      {
        check: 'prconfig.xml',
        weight: 25,
        cb: () => {
          const p = path.join(workspaceRoot, 'prconfig.xml');
          if (fs.existsSync(p)) {
            info.indicators.push('prconfig.xml');
          }
        },
      },
      {
        check: 'prpc.properties',
        weight: 20,
        cb: () => {
          const p = path.join(workspaceRoot, 'prpc.properties');
          if (fs.existsSync(p)) {
            info.indicators.push('prpc.properties');
          }
        },
      },
    ];

    for (const indicator of indicators) {
      try {
        indicator.cb();
        info.confidence += indicator.weight;
      } catch (err) { console.debug('[PegaProjectDetector] skip :', (err as Error).message); }
    }

    info.confidence = Math.min(info.confidence, 100);
    info.isPegaProject = info.confidence >= 25;

    return info;
  }
}

import type { PegaRuleAst, AstNode, AstReference } from './PegaRuleAst.js';
import { SYSTEM_FIELD_PREFIXES, SYSTEM_FIELDS } from './PegaRuleAst.js';

const REFERENCE_FIELDS = new Set([
  'pyClassName', 'pySuperClass', 'pyPatternParent', 'pyDerivesFrom',
  'pyRuleName', 'pyModelName', 'pyActivityName', 'pyTransformName',
  'pyWhenCondition', 'pyOnChangeTrigger',
]);

export class PegaRuleAstParser {
  public parse(json: Record<string, unknown>): PegaRuleAst {
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Obj-Activity';
    const name = this.extractName(pxObjClass, json);
    const className = (json.pyClassName as string) || '';
    const ruleset = (json.pyRuleset as string) || undefined;
    const version = (json.pyRuleSetVersion as string) || undefined;
    const label = (json.pyLabel as string) || undefined;

    const builder = this.getBuilder(pxObjClass);
    const { properties, children } = builder(json);

    const references = this.extractReferences(json, className, pxObjClass);

    return {
      astVersion: '1.0',
      ruleType: pxObjClass,
      name,
      className,
      ruleset,
      rulesetVersion: version,
      label,
      properties,
      children,
      references,
    };
  }

  private extractName(pxObjClass: string, json: Record<string, unknown>): string {
    return (json.pyRuleName as string)
      || (json.pyActivityName as string)
      || (json.pyModelName as string)
      || (json.pyFlowName as string)
      || (json.pyLabel as string)
      || (json.pyClassName as string)
      || '';
  }

  private extractReferences(
    json: Record<string, unknown>,
    defaultClass: string,
    ruleType: string,
  ): AstReference[] {
    const refs: AstReference[] = [];
    const visited = new Set<string>();

    const addRef = (rt: string, cls: string, name: string, role: string) => {
      const key = `${rt}:${cls}:${name}`;
      if (visited.has(key)) return;
      visited.add(key);
      refs.push({ ruleType: rt, className: cls, ruleName: name, role });
    };

    for (const [key, val] of Object.entries(json)) {
      if (!key.startsWith('py') && !key.startsWith('px')) continue;
      if (SYSTEM_FIELDS.has(key)) continue;
      if (typeof val !== 'string' || !val) continue;

      if (REFERENCE_FIELDS.has(key)) {
        const cls = key === 'pyClassName' ? '@baseclass' : (json.pyClassName as string) || defaultClass;
        const rt = key === 'pySuperClass' || key === 'pyPatternParent' || key === 'pyDerivesFrom' || key === 'pyClassName'
          ? 'Rule-Obj-Class' : ruleType;
        addRef(rt, cls, val, key);
        continue;
      }

      if (key === 'pyMethodParameters' && val.includes('.')) {
        const dot = val.lastIndexOf('.');
        addRef('Rule-Obj-Activity', val.substring(0, dot), val.substring(dot + 1), 'call');
        continue;
      }
      if (key === 'pyMethodParameters') {
        addRef('Rule-Obj-Activity', defaultClass, val, 'call');
      }
    }

    const steps = json.steps || json.pySteps;
    if (Array.isArray(steps)) {
      for (const s of steps) {
        if (typeof s !== 'object' || !s) continue;
        const step = s as Record<string, unknown>;
        const method = step.pyMethod as string || '';
        const params = step.pyMethodParameters as string || '';
        if ((method === 'Call' || method === 'Branch') && params) {
          const dot = params.lastIndexOf('.');
          addRef('Rule-Obj-Activity', dot >= 0 ? params.substring(0, dot) : defaultClass, dot >= 0 ? params.substring(dot + 1) : params, 'calls');
        }
        if (step.pyWhenCondition) {
          addRef('Rule-Obj-When', defaultClass, step.pyWhenCondition as string, 'guards');
        }
        if (step.pyFlowActionName) {
          addRef('Rule-Obj-FlowAction', defaultClass, step.pyFlowActionName as string, 'flow-action');
        }
      }
    }

    const actions = json.pyActions;
    if (Array.isArray(actions)) {
      for (const a of actions) {
        if (typeof a !== 'object' || !a) continue;
        const act = a as Record<string, unknown>;
        if (act.pyTransformName) addRef('Rule-Obj-Model', defaultClass, act.pyTransformName as string, 'applies-transform');
        if (act.pyWhenCondition) addRef('Rule-Obj-When', defaultClass, act.pyWhenCondition as string, 'guards');
        if (act.pyTarget && (act.pyActionType as string || '').includes('Transform')) {
          addRef('Rule-Obj-Model', defaultClass, act.pyTarget as string, 'applies-transform');
        }
      }
    }

    const pxRuleReferences = json.pxRuleReferences;
    if (Array.isArray(pxRuleReferences)) {
      for (const ref of pxRuleReferences) {
        if (typeof ref !== 'object' || !ref) continue;
        const r = ref as Record<string, unknown>;
        const refType = (r.pxRuleObjClass || r.pxRuleClassName) as string;
        const refName = r.pyRuleName as string;
        const refClass = r.pxRuleClassName as string || defaultClass;
        if (refType && refName) addRef(refType, refClass || defaultClass, refName, 'references');
      }
    }

    const shapes = json.pyShapes || json.shapes;
    if (Array.isArray(shapes)) {
      for (const sh of shapes) {
        if (typeof sh !== 'object' || !sh) continue;
        const shape = sh as Record<string, unknown>;
        if (shape.pyFlowActionName) {
          addRef('Rule-Obj-FlowAction', defaultClass, shape.pyFlowActionName as string, 'flow-action');
        }
        if (shape.pyWhenCondition) {
          addRef('Rule-Obj-When', defaultClass, shape.pyWhenCondition as string, 'guards');
        }
        if (shape.pyClassName && shape.pyClassName !== defaultClass) {
          addRef('Rule-Obj-Class', '@baseclass', shape.pyClassName as string, 'references');
        }
      }
    }

    return refs;
  }

  private getBuilder(
    pxObjClass: string,
  ): (json: Record<string, unknown>) => { properties: Record<string, unknown>; children: AstNode[] } {
    if (pxObjClass === 'Rule-Obj-Activity') return this.buildActivity.bind(this);
    if (pxObjClass === 'Rule-Obj-Model') return this.buildDataTransform.bind(this);
    if (pxObjClass === 'Rule-Obj-Flow') return this.buildFlow.bind(this);
    if (pxObjClass === 'Rule-Obj-FlowAction') return this.buildFlowAction.bind(this);
    if (pxObjClass === 'Rule-Obj-Class') return this.buildClass.bind(this);
    if (pxObjClass === 'Rule-Obj-Property') return this.buildProperty.bind(this);
    if (pxObjClass === 'Rule-Obj-When') return this.buildWhen.bind(this);
    if (pxObjClass === 'Rule-Declare-DecisionTable' || pxObjClass === 'Rule-Declare-DecisionTree') return this.buildDecision.bind(this);
    if (pxObjClass.startsWith('Rule-Declare-')) return this.buildDeclare.bind(this);
    if (pxObjClass.startsWith('Rule-Decision-')) return this.buildDecision.bind(this);
    if (pxObjClass.startsWith('Rule-Connect-')) return this.buildConnector.bind(this);
    if (pxObjClass.startsWith('Rule-Service-')) return this.buildService.bind(this);
    if (pxObjClass.startsWith('Rule-HTML-') || pxObjClass.startsWith('Rule-UI-')) return this.buildUi.bind(this);
    if (pxObjClass.startsWith('Rule-Parse-') || pxObjClass === 'Rule-Map-Structured') return this.buildParse.bind(this);
    if (pxObjClass.startsWith('Rule-Access-')) return this.buildAccess.bind(this);
    if (pxObjClass.startsWith('Rule-Async-') || pxObjClass.startsWith('Rule-Agent-')) return this.buildAsync.bind(this);
    if (pxObjClass.startsWith('Rule-Test-')) return this.buildTest.bind(this);
    if (pxObjClass.startsWith('Rule-File-')) return this.buildFile.bind(this);
    if (pxObjClass.startsWith('Rule-Admin-') || pxObjClass.startsWith('Rule-Security')) return this.buildAdmin.bind(this);
    if (pxObjClass.startsWith('Rule-Utility-') || pxObjClass.startsWith('Rule-Alias-')) return this.buildUtility.bind(this);
    if (pxObjClass.startsWith('Rule-Edit-')) return this.buildEdit.bind(this);
    if (pxObjClass.startsWith('Rule-Corr-')) return this.buildCorrespondence.bind(this);
    if (pxObjClass.startsWith('Rule-PegaQ-')) return this.buildSurvey.bind(this);
    return this.buildGeneric.bind(this);
  }

  private stripSystemFields(json: Record<string, unknown>): Record<string, unknown> {
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(json)) {
      if (SYSTEM_FIELDS.has(key)) continue;
      if (SYSTEM_FIELD_PREFIXES.some(p => key.startsWith(p))) continue;
      if (key.startsWith('px') && key !== 'pxObjClass') continue;
      if (key.startsWith('pz')) continue;
      if (typeof val === 'function') continue;
      if (Array.isArray(val) && val.length === 0 && key.endsWith('List')) continue;
      if (val === '' || val === null || val === undefined) continue;
      if (key === 'pyLinks' || key === 'pyLockDefList' || key === 'pyOtherJavaGenerators') continue;
      if (key === 'pyValidRuleSets' || key === 'pxClassSQL' || key === 'pxInternalClassSQL') continue;
      result[key] = val;
    }
    return result;
  }

  private buildActivity(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    delete props.steps;
    const steps = Array.isArray(json.steps) ? json.steps : [];
    const children: AstNode[] = steps.map((s: unknown, i: number) => {
      const step = s as Record<string, unknown>;
      return {
        type: 'Step',
        properties: this.stripSystemFields(step),
        children: [],
      };
    });
    return { properties: props, children };
  }

  private buildDataTransform(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    delete props.pyActions;
    const actions = Array.isArray(json.pyActions) ? json.pyActions : [];
    const children: AstNode[] = actions.map((a: unknown) => {
      const act = a as Record<string, unknown>;
      return {
        type: 'Action',
        properties: this.stripSystemFields(act),
        children: [],
      };
    });
    return { properties: props, children };
  }

  private buildFlow(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    delete props.pyShapes; delete props.shapes;
    const shapes = Array.isArray(json.pyShapes) ? json.pyShapes : Array.isArray(json.shapes) ? json.shapes : [];
    const children: AstNode[] = shapes.map((s: unknown) => {
      const shape = s as Record<string, unknown>;
      return {
        type: (shape.pyShapeType as string) || 'Shape',
        properties: this.stripSystemFields(shape),
        children: [],
      };
    });
    return { properties: props, children };
  }

  private buildFlowAction(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    return { properties: props, children: [] };
  }

  private buildClass(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    delete props.pxRuleReferences;
    const refs = Array.isArray(json.pxRuleReferences) ? json.pxRuleReferences : [];
    const children: AstNode[] = refs.map((r: unknown) => ({
      type: 'RuleReference',
      properties: this.stripSystemFields(r as Record<string, unknown>),
      children: [],
    }));
    return { properties: props, children };
  }

  private buildProperty(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    return { properties: this.stripSystemFields(json), children: [] };
  }

  private buildWhen(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    return { properties: this.stripSystemFields(json), children: [] };
  }

  private buildDeclare(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];

    if (json.pxResults) {
      const results = Array.isArray(json.pxResults) ? json.pxResults : [];
      for (const r of results) {
        children.push({ type: 'Result', properties: this.stripSystemFields(r as Record<string, unknown>), children: [] });
      }
    }
    if (json.pyPages) {
      const pages = Array.isArray(json.pyPages) ? json.pyPages : [];
      for (const p of pages) {
        children.push({ type: 'Page', properties: this.stripSystemFields(p as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildDecision(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];

    const rows = json.pyDecisionTableRows || json.pyRows;
    if (Array.isArray(rows)) {
      for (const r of rows) {
        children.push({ type: 'DecisionRow', properties: this.stripSystemFields(r as Record<string, unknown>), children: [] });
      }
    }

    const strategies = json.pyStrategyComponents || json.pyComponents;
    if (Array.isArray(strategies)) {
      for (const s of strategies) {
        children.push({ type: 'StrategyComponent', properties: this.stripSystemFields(s as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildConnector(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    delete props.pyHeaders;
    if (Array.isArray(json.pyHeaders)) {
      const hdrs: AstNode[] = (json.pyHeaders as any[]).map(h => ({
        type: 'Header', properties: this.stripSystemFields(h), children: [],
      }));
      return { properties: props, children: hdrs };
    }
    return { properties: props, children: [] };
  }

  private buildService(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    return { properties: props, children: [] };
  }

  private buildUi(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const layouts = json.pyLayouts || json.pxLayouts;
    if (Array.isArray(layouts)) {
      for (const l of layouts) {
        children.push({ type: 'Layout', properties: this.stripSystemFields(l as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildParse(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const parts = json.pyParseRules || json.pyParts;
    if (Array.isArray(parts)) {
      for (const p of parts) {
        children.push({ type: 'ParsePart', properties: this.stripSystemFields(p as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildAccess(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const ops = json.pyOperations || json.pyAccessPrivileges;
    if (Array.isArray(ops)) {
      for (const o of ops) {
        children.push({ type: 'Permission', properties: this.stripSystemFields(o as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildAsync(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    return { properties: props, children: [] };
  }

  private buildTest(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const cases = json.pyExpectations || json.pyAsserts || json.pyTestCases;
    if (Array.isArray(cases)) {
      for (const c of cases) {
        children.push({ type: 'Assertion', properties: this.stripSystemFields(c as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildFile(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    return { properties: props, children: [] };
  }

  private buildAdmin(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    return { properties: this.stripSystemFields(json), children: [] };
  }

  private buildUtility(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const params = json.pyParameters || json.pyInputParams;
    if (Array.isArray(params)) {
      for (const p of params) {
        children.push({ type: 'Parameter', properties: this.stripSystemFields(p as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildEdit(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    return { properties: this.stripSystemFields(json), children: [] };
  }

  private buildCorrespondence(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    return { properties: this.stripSystemFields(json), children: [] };
  }

  private buildSurvey(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    const questions = json.pyQuestions || json.pyQuestionItems;
    if (Array.isArray(questions)) {
      for (const q of questions) {
        children.push({ type: 'Question', properties: this.stripSystemFields(q as Record<string, unknown>), children: [] });
      }
    }
    return { properties: props, children };
  }

  private buildGeneric(json: Record<string, unknown>): { properties: Record<string, unknown>; children: AstNode[] } {
    const props = this.stripSystemFields(json);
    const children: AstNode[] = [];
    for (const [key, val] of Object.entries(json)) {
      if (SYSTEM_FIELDS.has(key)) continue;
      if (key.startsWith('px') || key.startsWith('pz')) continue;
      if (Array.isArray(val) && val.length > 0 && typeof val[0] === 'object') {
        const items = val as Record<string, unknown>[];
        children.push({
          type: key,
          properties: {},
          children: items.map(v => ({ type: 'Item', properties: this.stripSystemFields(v), children: [] })),
        });
      }
    }
    return { properties: props, children };
  }

  public toPromptContext(ast: PegaRuleAst, maxDepth?: number): string {
    const lines: string[] = [];
    lines.push(`Rule: ${ast.ruleType} — ${ast.name}`);
    lines.push(`Applies to: ${ast.className}`);
    if (ast.ruleset) lines.push(`Ruleset: ${ast.ruleset} ${ast.rulesetVersion || ''}`);
    if (ast.label) lines.push(`Label: ${ast.label}`);
    lines.push('');

    const semanticProps = this.getSemanticProperties(ast.properties, ast.ruleType);
    if (Object.keys(semanticProps).length > 0) {
      lines.push('Properties:');
      for (const [k, v] of Object.entries(semanticProps)) {
        lines.push(`  ${k}: ${typeof v === 'object' ? JSON.stringify(v) : String(v)}`);
      }
      lines.push('');
    }

    if (ast.children.length > 0) {
      lines.push('Structure:');
      this.formatNodes(ast.children, lines, '  ', maxDepth ?? 10);
      lines.push('');
    }

    if (ast.references.length > 0) {
      lines.push('References to other rules:');
      const grouped = new Map<string, AstReference[]>();
      for (const ref of ast.references) {
        const key = `${ref.role}`;
        if (!grouped.has(key)) grouped.set(key, []);
        grouped.get(key)!.push(ref);
      }
      for (const [role, refs] of grouped) {
        for (const ref of refs) {
          lines.push(`  [${role}] ${ref.ruleType}:${ref.className}:${ref.ruleName}`);
        }
      }
    }

    return lines.join('\n');
  }

  private getSemanticProperties(props: Record<string, unknown>, ruleType: string): Record<string, unknown> {
    const skip = new Set([
      'pyFormType', 'pyApplet', 'pyAppletHarness', 'pyClassGroupIndicator',
      'pyClassType', 'pyClassAllowState', 'pyClassInheritance',
      'pyPatternInheritance',
    ]);
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(props)) {
      if (skip.has(k)) continue;
      if (k.startsWith('py') || k.startsWith('px')) {
        if (typeof v === 'object' || typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
          result[k] = v;
        }
      }
    }
    return result;
  }

  private formatNodes(nodes: AstNode[], lines: string[], indent: string, depth: number): void {
    if (depth <= 0) { lines.push(`${indent}...`); return; }
    for (const node of nodes) {
      lines.push(`${indent}[${node.type}]`);
      for (const [k, v] of Object.entries(node.properties)) {
        if (k.startsWith('px') && k !== 'pxObjClass') continue;
        if (k.startsWith('pz')) continue;
        lines.push(`${indent}  ${k}: ${typeof v === 'object' ? JSON.stringify(v) : String(v)}`);
      }
      if (node.children.length > 0) {
        this.formatNodes(node.children, lines, indent + '  ', depth - 1);
      }
    }
  }
}

/**
 * PegaRuleFetcherService — fetches full Pega Rule Instances from Pega Server.
 * Supports Pega REST APIs, Data Pages, and PRServlet Activities.
 */
// @ts-ignore
import { parseStringPromise } from 'xml2js';

export interface FetchRuleRequest {
  pxObjClass: string;
  pyRuleName: string;
  pyClassName?: string; // Applies To class (e.g. TGB-HRApps-Work-Candidate)
  insKey?: string;
  pegaEndpoint: string;
  authHeader?: string;
  username?: string;
  password?: string;
}

export interface FetchRuleResponse {
  ruleJson: Record<string, unknown>;
  isFullContent: boolean;
  format: 'JSON' | 'XML_CONVERTED';
}

export class PegaRuleFetcherService {
  private sessionCookies: string | null = null;
  private sessionExpiry: number = 0;

  /**
   * Main entry point to fetch a full Pega Rule Instance.
   */
  public async fetchRule(req: FetchRuleRequest): Promise<FetchRuleResponse> {
    const { pxObjClass, pyRuleName, pegaEndpoint, authHeader } = req;
    const base = pegaEndpoint.replace(/\/$/, '');

    // 1. Try Custom Service REST Endpoint: GET /api/HRAppsV2Service/V1/rules/{insKey}
    if (req.insKey) {
      try {
        const url = `${base}/api/HRAppsV2Service/V1/rules/${encodeURIComponent(req.insKey)}`;
        const headers: Record<string, string> = { Accept: 'application/json' };
        if (authHeader) headers['Authorization'] = authHeader;

        const res = await fetch(url, { headers });
        if (res.ok) {
          const json = (await res.json()) as Record<string, unknown>;
          if (json && (json.pxObjClass || json.pzInsKey || json.pyRuleName) && !json.error && json.pyHTTPResponseCode !== '404' && json.pyHTTPResponseCode !== 404) {
            return { ruleJson: json, isFullContent: true, format: 'JSON' };
          }
        }
      } catch (err) { console.debug('[PegaRuleFetcherService] try next strategy :', (err as Error).message); }
    }

    // 2. Try Custom Service REST Endpoint: POST /api/HRAppsV2Service/V1/rules/query
    if (pxObjClass && pyRuleName) {
      try {
        const url = `${base}/api/HRAppsV2Service/V1/rules/query`;
        const headers: Record<string, string> = { 'Content-Type': 'application/json', Accept: 'application/json' };
        if (authHeader) headers['Authorization'] = authHeader;

        const res = await fetch(url, {
          method: 'POST',
          headers,
          body: JSON.stringify({
            ruleJson: JSON.stringify({
              RequestClass: pxObjClass,
              RequestAppliesTo: req.pyClassName || '',
              RequestRuleName: pyRuleName,
            })
          })
        });
        if (res.ok) {
          const json = (await res.json()) as Record<string, unknown>;
          if (json && (json.pxObjClass || json.pzInsKey) && !json.error && json.pyHTTPResponseCode !== '404' && json.pyHTTPResponseCode !== 404) {
            return { ruleJson: json, isFullContent: true, format: 'JSON' };
          }
        }
      } catch (err) { console.debug('[PegaRuleFetcherService] try next strategy :', (err as Error).message); }
    }

    // 3. Fallback: Try Pega PRServlet Activity via Session Authentication (pzGetRuleXML)
    if (req.username && req.password) {
      try {
        const candidateKeys = [
          req.insKey,
          req.pyClassName && req.pyClassName !== '@baseclass' ? `${pxObjClass} ${req.pyClassName} ${pyRuleName}` : null,
          `${pxObjClass} ${pyRuleName}`,
        ].filter(Boolean) as string[];

        for (const targetKey of candidateKeys) {
          const xmlRule = await this.fetchRuleXmlViaSession(base, req.username, req.password, targetKey);
          if (xmlRule) {
            const jsonFromXml = await this.convertXmlToJson(xmlRule, pxObjClass, pyRuleName);
            return { ruleJson: jsonFromXml, isFullContent: true, format: 'XML_CONVERTED' };
          }
        }
      } catch (err) { console.debug('[PegaRuleFetcherService] try next strategy :', (err as Error).message); }
    }

    // 4. Fallback: Return complete structured Pega Rule specification object
    return {
      ruleJson: this.buildRichRuleSpec(pxObjClass, pyRuleName, req.insKey),
      isFullContent: false,
      format: 'JSON',
    };
  }

  /**
   * Authenticates against Pega PRServlet and fetches rule XML via pzGetRuleXML activity.
   */
  private async fetchRuleXmlViaSession(base: string, user: string, pass: string, insKey: string): Promise<string | null> {
    const now = Date.now();
    if (!this.sessionCookies || now > this.sessionExpiry) {
      const loginBody = new URLSearchParams({
        UserIdentifier: user,
        Password: pass,
        pyActivity: 'Code-Security.Login',
      });

      const resLogin = await fetch(`${base}/PRServlet`, {
        method: 'POST',
        body: loginBody.toString(),
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        redirect: 'manual',
      });

      const cookies = resLogin.headers.getSetCookie ? resLogin.headers.getSetCookie() : [];
      const cookieHeader = cookies.map(c => c.split(';')[0]).join('; ');
      if (!cookieHeader) return null;

      this.sessionCookies = cookieHeader;
      this.sessionExpiry = now + 15 * 60 * 1000; // 15 min session
    }

    const ruleUrl = `${base}/PRServlet?pyActivity=pzGetRuleXML&pzInsKey=${encodeURIComponent(insKey)}`;
    const resRule = await fetch(ruleUrl, {
      headers: { Cookie: this.sessionCookies },
    });

    if (resRule.ok) {
      const xml = await resRule.text();
      if (xml && xml.includes('pagedata')) return xml;
    }
    return null;
  }

  /**
   * Converts Pega XML rule string to clean JSON object.
   */
  private async convertXmlToJson(xmlStr: string, pxObjClass: string, pyRuleName: string): Promise<Record<string, unknown>> {
    try {
      const parsed = await parseStringPromise(xmlStr, { explicitArray: false, mergeAttrs: true });
      const pagedata = parsed?.pagedata || parsed;
      return {
        pxObjClass,
        pyRuleName,
        ...pagedata,
      };
    } catch (err) {
      console.debug('[PegaRuleFetcherService] XML parse failed, returning raw content:', (err as Error).message);
      return {
        pxObjClass,
        pyRuleName,
        rawXmlContent: xmlStr,
      };
    }
  }

  /**
   * Builds rich complete specification object for Pega rule fallback.
   */
  private buildRichRuleSpec(pxObjClass: string, pyRuleName: string, insKey?: string): Record<string, unknown> {
    const pyClassName = pyRuleName.includes('-') ? pyRuleName.split('-').slice(0, -1).join('-') : '@baseclass';
    return {
      pxObjClass: pxObjClass || 'Rule-OBJ-CLASS',
      pyClassName,
      pyRuleName,
      pzInsKey: insKey || `${pxObjClass} ${pyRuleName}`,
      pyApplication: 'HRAppsV2',
      pyRuleSet: 'HRAppsV2',
      pyRuleSetVersion: '01-01-01',
      pyStatus: 'Available',
      pyDescription: `${pxObjClass || 'Pega Rule'} specification for ${pyRuleName}`,
      pxCreateDateTime: new Date().toISOString(),
      pxUpdateDateTime: new Date().toISOString(),
      pySteps: [
        { pxObjClass: 'Embed-Step', pyStepName: 'Initialize', pyStepType: 'Activity', pyDisabled: false },
      ],
      pyPagesAndClasses: [
        { pxObjClass: 'Embed-PagesAndClasses', pyPageName: 'primary', pyClassName },
      ],
      pyRuleReferences: [
        { pxObjClass: 'Embed-RuleRef', pyRefName: pyRuleName, pyRefType: pxObjClass || 'Rule' },
      ],
    };
  }
}

/**
 * PegaSchemaLoader — Tự động quét đệ quy và nạp tất cả các file JSON Schema mô đun hóa 
 * từ các thư mục con trong backend/src/modules/pega/schemas/.
 */

import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import type { PegaRuleKbSchema } from './strategies/KbDrivenPegaParserStrategy.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export class PegaSchemaLoader {
  public static loadAllSchemas(): PegaRuleKbSchema[] {
    const schemasDir = path.resolve(__dirname, './schemas');
    const results: PegaRuleKbSchema[] = [];
    if (!fs.existsSync(schemasDir)) return results;

    PegaSchemaLoader.scanDirectory(schemasDir, results);
    return results;
  }

  private static scanDirectory(dir: string, results: PegaRuleKbSchema[]): void {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        PegaSchemaLoader.scanDirectory(fullPath, results);
      } else if (entry.isFile() && entry.name.endsWith('.json')) {
        PegaSchemaLoader.loadSingleFile(fullPath, results);
      }
    }
  }

  private static loadSingleFile(filePath: string, results: PegaRuleKbSchema[]): void {
    try {
      const raw = fs.readFileSync(filePath, 'utf-8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed.schemas)) {
        for (const item of parsed.schemas) {
          if (item && item.targetClass) results.push(item);
        }
      } else if (parsed && parsed.targetClass) {
        results.push(parsed as PegaRuleKbSchema);
      }
    } catch (err) { console.debug('[PegaSchemaLoader] ignore invalid JSON files :', (err as Error).message); }
  }
}

/**
 * PegaService — Logic nghiệp vụ cho Pega Rule & Data Indexing & Schema Storage.
 * SA4E-171 (cutover): rules are indexed into symbols (via PegaIndexer/PegaSymbolSync);
 * syncIndexedRulesToKb only projects code graph nodes. No knowledge_entries PEGA_* rows.
 */
import type { MemoryEngine } from '../memory/engine/core.js';
import type {
  PegaCheckRuleRequest,
  PegaCheckRuleResponse,
  PegaIngestRuleRequest,
  PegaIngestRuleResponse,
} from './models.js';
import { PegaParser } from './PegaParser.js';
import { PegaSchemaLoader } from './PegaSchemaLoader.js';
import type { PegaRuleKbSchema } from './strategies/KbDrivenPegaParserStrategy.js';
import { PegaDeclarativeEngine } from './PegaDeclarativeEngine.js';
import { PegaRuleAstParser } from './PegaRuleAstParser.js';
import { indexRule, type IndexRuleResult } from './PegaIndexer.js';
import { syncAllIndexedRules, type SyncBatchResult } from './PegaKbSync.js';
import pino from 'pino';

const logger = pino({ name: 'pega-service' });

export class PegaService {
  private parser: PegaParser;
  private declarativeEngine: PegaDeclarativeEngine;
  private astParser: PegaRuleAstParser;

  constructor(private memoryEngine: MemoryEngine) {
    this.parser = new PegaParser();
    this.declarativeEngine = new PegaDeclarativeEngine();
    this.astParser = new PegaRuleAstParser();
    this.initSchemasInDb().catch((err) => { logger.debug({ err }, '[PegaService] Schema init failed (non-fatal)'); });
  }

  public getDeclarativeEngine(): PegaDeclarativeEngine { return this.declarativeEngine; }

  private async initSchemasInDb(): Promise<void> {
    const schemas = await this.getSchemasFromDb();
    if (schemas.length > 0) return;
    try {
      const allSchemas = PegaSchemaLoader.loadAllSchemas();
      for (const item of allSchemas) {
        await this.upsertSchemaInDb(item);
      }
    } catch (err) { logger.debug({ err }, '[PegaService] Failed to load schemas into DB (non-fatal)'); }
  }

  public async getSchemasFromDb(): Promise<PegaRuleKbSchema[]> {
    const adapter = this.memoryEngine.getAdapter();
    const rows = await adapter.allAsync<{ content: string }>(
      "SELECT content FROM knowledge_entries WHERE type = 'PEGA_SCHEMA'",
      [],
    );
    return rows.map((r) => {
      try { return JSON.parse(r.content) as PegaRuleKbSchema; }
      catch (err) { logger.debug({ err }, '[PegaService] Failed to parse PEGA_SCHEMA entry'); return null; }
    }).filter((s): s is PegaRuleKbSchema => s !== null);
  }

  public async upsertSchemaInDb(schema: PegaRuleKbSchema): Promise<void> {
    const adapter = this.memoryEngine.getAdapter();
    const sourceKey = `pega-schema:${schema.targetClass}`;
    await adapter.runAsync("DELETE FROM knowledge_entries WHERE source = $1 AND type = 'PEGA_SCHEMA'", [sourceKey]);
    await this.memoryEngine.insert({
      content: JSON.stringify(schema),
      summary: `Pega Rule Schema: ${schema.targetClass}`,
      type: 'PEGA_SCHEMA',
      tier: 'SEMANTIC',
      scope: 'SHARED',
      project_id: 'SYSTEM',
      source: sourceKey,
      tags: 'pega,schema',
    });
  }

  public async checkRule(req: PegaCheckRuleRequest): Promise<PegaCheckRuleResponse> {
    const fqn = `${req.ruleType}:${req.className}:${req.ruleName}`;
    const adapter = this.memoryEngine.getAdapter();
    const row = await adapter.getAsync<{ id: number; name: string; signature: string; doc_comment: string | null }>(
      `SELECT s.id, s.name, s.signature, s.doc_comment
       FROM symbols s JOIN files f ON f.id = s.file_id
       WHERE s.signature = $1 AND s.project_id = $2 AND s.kind LIKE 'pega_%'
       LIMIT 1`,
      [fqn, req.projectId],
    );
    if (!row) return { cached: false };
    const storedClass = row.signature.split(':')[0] ?? '';
    return {
      cached: true,
      ruleId: row.id,
      content: {
        pyRuleName: row.name,
        pyActivityName: row.name,
        pyClassName: storedClass || req.className,
        pxObjClass: req.ruleType,
      } as Record<string, unknown>,
    };
  }

  public parseRuleToSymbol(ruleJson: Record<string, unknown>): { fqn: string; isRule: boolean } | null {
    try {
      return this.parser.parseSymbol(ruleJson);
    } catch {
      return null;
    }
  }

  public getAstParser(): PegaRuleAstParser { return this.astParser; }
  public parseRuleToAst(ruleJson: Record<string, unknown>) { return this.astParser.parse(ruleJson); }
  public ruleToPromptContext(ruleJson: Record<string, unknown>): string {
    const ast = this.parseRuleToAst(ruleJson);
    return this.astParser.toPromptContext(ast);
  }

  /**
   * SA4E-158 Phase 1: Index rule — parse + dedup + store into symbols table.
   * No knowledge_entries writes (PEGA_INDEX/PEGA_RULE/PEGA_DATA/PEGA_AST removed).
   */
  public async indexRuleOnly(req: PegaIngestRuleRequest): Promise<IndexRuleResult> {
    // Auto-register Declare Expressions into Declarative Engine (was Phase 2 duty)
    const deps = this.parser.extractDependencies(req.ruleJson);
    const pxObjClass = (req.ruleJson as any)?.pxObjClass || '';
    if (pxObjClass === 'Rule-Declare-Expressions') {
      const targetProp = (req.ruleJson as any)?.pyTargetProperty || (req.ruleJson as any)?.pyPropertyName || '';
      const formula = (req.ruleJson as any)?.pyExpression || '';
      const inputs = deps.map(d => d.ruleName);
      if (targetProp) {
        this.declarativeEngine.registerExpression(targetProp, formula, inputs);
      }
    }
    return indexRule(this.memoryEngine, this.parser, this.astParser, req);
  }

  /**
   * SA4E-158 Phase 2: Sync all indexed rules for a project.
   * SA4E-171: enriches symbols already written by Phase 1 and projects
   * Pega code graph nodes. No knowledge_entries writes.
   */
  public async syncIndexedRulesToKb(projectId: string): Promise<SyncBatchResult> {
    return syncAllIndexedRules(this.memoryEngine, this.parser, this.declarativeEngine, projectId);
  }

  /** SA4E-158: Expose parser for route-level access. */
  public getParser(): PegaParser { return this.parser; }

  /** SA4E-158: Expose memoryEngine for route-level access. */
  public getMemoryEngine(): MemoryEngine { return this.memoryEngine; }

  /**
   * Legacy ingestRule — backward compatible single-rule ingest.
   * Writes to symbols table only (no knowledge_entries PEGA_* rows).
   * @deprecated Use indexRuleOnly + syncIndexedRulesToKb for SRP separation.
   */
  public async ingestRule(req: PegaIngestRuleRequest): Promise<PegaIngestRuleResponse> {
    // Auto-register Declare Expressions into Declarative Engine
    const deps = this.parser.extractDependencies(req.ruleJson);
    const pxObjClass = (req.ruleJson as any)?.pxObjClass || '';
    if (pxObjClass === 'Rule-Declare-Expressions') {
      const targetProp = (req.ruleJson as any)?.pyTargetProperty || (req.ruleJson as any)?.pyPropertyName || '';
      const formula = (req.ruleJson as any)?.pyExpression || '';
      const inputs = deps.map(d => d.ruleName);
      if (targetProp) {
        this.declarativeEngine.registerExpression(targetProp, formula, inputs);
      }
    }

    const result = await indexRule(this.memoryEngine, this.parser, this.astParser, req);
    return {
      status: 'success',
      ruleId: result.ruleId,
      unresolvedDependencies: result.dependencies,
      reason: result.status === 'skipped' ? result.reason : undefined,
    };
  }
}

/**
 * SA4E-171 — PegaSymbolSync: Sync Pega rules into symbols table.
 * Creates: virtual file → symbol → body_embeddings → CODE_ENRICHMENT task.
 * Feature flag: PEGA_DUAL_WRITE (default true) controls dual-write.
 */

import { createHash } from 'crypto';
import type { DatabaseAdapter } from '../../database/adapters/DatabaseAdapter.js';
import { resolveSymbolKind, buildVirtualPath, buildFqn, resolveRuleNameField } from './pega-mapping.js';
import { extractRuleContent } from './PegaContentExtractor.js';
import { TaskType, TaskStatus } from '../memory/task-queue/models.js';
import pino from 'pino';

const logger = pino({ name: 'pega-symbol-sync' });

/** Max rule JSON size in bytes (SEC-06: skip oversized rules). */
const MAX_RULE_SIZE_BYTES = 5 * 1024 * 1024; // 5MB

/** Feature flag: write to symbols table (default true, SEC-03: case-insensitive). */
export const PEGA_DUAL_WRITE = parseDualWriteFlag(process.env.PEGA_DUAL_WRITE);

/** Parse PEGA_DUAL_WRITE env var with case-insensitive boolean handling. */
function parseDualWriteFlag(value: string | undefined): boolean {
  if (!value) return true; // Default true when not set
  return value.toLowerCase() !== 'false';
}

/** Result of syncing a rule to the symbols table. */
export interface SymbolSyncResult {
  symbolId: number;
  fileId: number;
}

/**
 * Sync a Pega rule into the symbols table (new path).
 * Creates: virtual file → symbol → body_embeddings → CODE_ENRICHMENT task.
 * @param adapter - Database adapter for SQL operations
 * @param ruleJson - Raw Pega rule JSON content
 * @param projectId - Tenant project identifier (SEC-04)
 * @param promptContext - Prompt context for doc_comment
 * @returns symbolId and fileId, or null if validation fails
 */
export async function syncRuleToSymbols(
  adapter: DatabaseAdapter,
  ruleJson: Record<string, unknown>,
  projectId: string,
  promptContext: string,
): Promise<SymbolSyncResult | null> {
  const fields = extractRequiredFields(ruleJson);
  if (!fields) return null;

  const { pxObjClass, pyClassName, pyRuleName } = fields;
  const kind = resolveSymbolKind(pxObjClass);
  const fqn = buildFqn(pxObjClass, pyClassName, pyRuleName);
  const virtualPath = buildVirtualPath(pyClassName, kind, pyRuleName);
  const ruleJsonStr = JSON.stringify(ruleJson);

  // SEC-06: skip oversized rules
  if (ruleJsonStr.length > MAX_RULE_SIZE_BYTES) {
    logger.warn({ fqn, size: ruleJsonStr.length }, 'Rule exceeds 5MB limit — skipped');
    return null;
  }

  const contentHash = createHash('sha256').update(ruleJsonStr).digest('hex');
  const docComment = (promptContext || `${kind}: ${fqn}`).slice(0, 500);

  const fileId = await upsertVirtualFile(adapter, projectId, virtualPath, pyClassName, contentHash, ruleJsonStr.length);
  const symbolId = await upsertSymbol(adapter, projectId, fileId, pyRuleName, kind, fqn, pyClassName, docComment);
  // SA4E-106: store extracted readable content (steps/params/Java) for LLM enrichment
  await storeBodyEmbedding(adapter, projectId, symbolId, extractRuleContent(ruleJson));
  await createEnrichmentTaskIfNeeded(
    adapter, symbolId, pyRuleName, kind, virtualPath, projectId, pyClassName, resolveRuleSet(ruleJson),
  );

  logger.debug({ fqn, symbolId, fileId, kind }, 'Rule synced to symbols');
  return { symbolId, fileId };
}

/** Re-store body + re-queue enrichment for an existing symbol (SA4E-106 backfill). */
export async function refreshRuleSymbolBody(
  adapter: DatabaseAdapter,
  ruleJson: Record<string, unknown>,
  symbolId: number,
  projectId: string,
): Promise<void> {
  await storeBodyEmbedding(adapter, projectId, symbolId, extractRuleContent(ruleJson));

  const fields = extractRequiredFields(ruleJson);
  if (!fields) return;
  const kind = resolveSymbolKind(fields.pxObjClass);
  const virtualPath = buildVirtualPath(fields.pyClassName, kind, fields.pyRuleName);

  // Clear prior enrichment so a fresh CODE_ENRICHMENT task is created
  await adapter.runAsync(
    `DELETE FROM pending_tasks WHERE task_type = 'CODE_ENRICHMENT' AND entry_id = ? AND status IN ('PENDING', 'PROCESSING')`,
    [symbolId],
  );
  await adapter.runAsync(
    `UPDATE symbols SET enrichment_status = NULL, summary = NULL, pseudo_code = NULL,
     llm_tags = NULL, enriched_at = NULL WHERE id = ? AND project_id = ?`,
    [symbolId, projectId],
  );
  await createEnrichmentTaskIfNeeded(
    adapter, symbolId, fields.pyRuleName, kind, virtualPath,
    projectId, fields.pyClassName, resolveRuleSet(ruleJson),
  );
}

/** Resolve "RuleSet Version" string from rule JSON. */
function resolveRuleSet(ruleJson: Record<string, unknown>): string {
  const rs = (ruleJson as any)?.pyRuleset as string | undefined;
  const version = (ruleJson as any)?.pyRulesetVersion as string | undefined;
  return rs ? (version ? `${rs} ${version}` : rs) : '';
}

/** Extract and validate required fields from rule JSON. */
function extractRequiredFields(ruleJson: Record<string, unknown>) {
  const pxObjClass = String((ruleJson as any)?.pxObjClass || '');
  const pyClassName = String((ruleJson as any)?.pyClassName || '');
  // Name via canonical fallback (pyRuleName → pyActivityName → pyModelName → pyFlowName → pyLabel)
  const pyRuleName = resolveRuleNameField(ruleJson);

  if (!pxObjClass || !pyClassName || !pyRuleName) {
    logger.warn({ pxObjClass, pyClassName, pyRuleName }, 'Missing required Pega fields');
    return null;
  }
  return { pxObjClass, pyClassName, pyRuleName };
}

/** UPSERT virtual file entry (BR-02, BR-05). */
async function upsertVirtualFile(
  adapter: DatabaseAdapter, projectId: string, virtualPath: string,
  module: string, contentHash: string, sizeBytes: number,
): Promise<number> {
  const engine = adapter.getEngine();
  if (engine === 'postgresql') {
    const row = await adapter.getAsync<{ id: number }>(
      `INSERT INTO files (project_id, path, relative_path, language, module, content_hash, size_bytes, line_count)
       VALUES ($1, $2, $3, 'pega', $4, $5, $6, 1)
       ON CONFLICT(project_id, path) DO UPDATE SET
         content_hash = EXCLUDED.content_hash, size_bytes = EXCLUDED.size_bytes
       RETURNING id`,
      [projectId, virtualPath, virtualPath, module, contentHash, sizeBytes],
    );
    return row!.id;
  }
  // SQLite path
  await adapter.runAsync(
    `INSERT INTO files (project_id, path, relative_path, language, module, content_hash, size_bytes, line_count)
     VALUES (?, ?, ?, 'pega', ?, ?, ?, 1)
     ON CONFLICT(project_id, path) DO UPDATE SET
       content_hash = excluded.content_hash, size_bytes = excluded.size_bytes`,
    [projectId, virtualPath, virtualPath, module, contentHash, sizeBytes],
  );
  const row = await adapter.getAsync<{ id: number }>(
    'SELECT id FROM files WHERE project_id = ? AND path = ?',
    [projectId, virtualPath],
  );
  return row!.id;
}

/** UPSERT symbol entry (BR-01, BR-03, BR-04). */
async function upsertSymbol(
  adapter: DatabaseAdapter, projectId: string, fileId: number,
  name: string, kind: string, signature: string,
  parentSymbol: string, docComment: string,
): Promise<number> {
  const engine = adapter.getEngine();
  // Delete existing symbol for this file (1:1 virtual file → symbol)
  await adapter.runAsync(
    'DELETE FROM symbols WHERE file_id = ? AND project_id = ?',
    [fileId, projectId],
  );
  if (engine === 'postgresql') {
    const row = await adapter.getAsync<{ id: number }>(
      `INSERT INTO symbols (project_id, file_id, name, kind, signature, start_line, end_line, parent_symbol, visibility, doc_comment)
       VALUES ($1, $2, $3, $4, $5, 1, 1, $6, 'public', $7)
       RETURNING id`,
      [projectId, fileId, name, kind, signature, parentSymbol, docComment],
    );
    return row!.id;
  }
  const result = await adapter.runAsync(
    `INSERT INTO symbols (project_id, file_id, name, kind, signature, start_line, end_line, parent_symbol, visibility, doc_comment)
     VALUES (?, ?, ?, ?, ?, 1, 1, ?, 'public', ?)`,
    [projectId, fileId, name, kind, signature, parentSymbol, docComment],
  );
  return result.lastInsertRowid as number;
}

/** Store rule JSON body in body_embeddings for loadBodyText() (OI-04). */
async function storeBodyEmbedding(
  adapter: DatabaseAdapter, projectId: string, symbolId: number, body: string,
): Promise<void> {
  const buf = Buffer.from(body, 'utf-8');
  const tokenCount = Math.ceil(body.length / 4); // Rough token estimate
  const engine = adapter.getEngine();
  if (engine === 'postgresql') {
    await adapter.runAsync(
      `INSERT INTO body_embeddings (project_id, symbol_id, chunk_index, embedding, token_count)
       VALUES ($1, $2, 0, $3, $4)
       ON CONFLICT(project_id, symbol_id, chunk_index) DO UPDATE SET
         embedding = EXCLUDED.embedding, token_count = EXCLUDED.token_count`,
      [projectId, symbolId, buf, tokenCount],
    );
  } else {
    await adapter.runAsync(
      `INSERT INTO body_embeddings (project_id, symbol_id, chunk_index, embedding, token_count)
       VALUES (?, ?, 0, ?, ?)
       ON CONFLICT(project_id, symbol_id, chunk_index) DO UPDATE SET
         embedding = excluded.embedding, token_count = excluded.token_count`,
      [projectId, symbolId, buf, tokenCount],
    );
  }
}

/** Create CODE_ENRICHMENT task if symbol not already fully enriched (BR-07 amended). */
async function createEnrichmentTaskIfNeeded(
  adapter: DatabaseAdapter, symbolId: number, symbolName: string,
  kind: string, filePath: string, projectId: string,
  pegaClass?: string, pegaRuleset?: string,
): Promise<void> {
  // Skip only if CODE_ENRICHMENT already produced summary (not just TAG_ENRICHMENT tags)
  const sym = await adapter.getAsync<{ enrichment_status: string | null; summary: string | null }>(
    'SELECT enrichment_status, summary FROM symbols WHERE id = ? AND project_id = ?',
    [symbolId, projectId],
  );
  if (sym?.enrichment_status === 'COMPLETED' && sym.summary) return;

  const payload = JSON.stringify({
    symbolId, symbolName, symbolKind: kind,
    projectId, filePath, workspaceType: 'pega',
    pegaClass, pegaRuleset,
  });

  const now = new Date().toISOString();
  await adapter.runAsync(
    `INSERT INTO pending_tasks (task_type, entry_id, status, payload, max_retries, project_id, created_at)
     VALUES (?, ?, ?, ?, 3, ?, ?)`,
    [TaskType.CODE_ENRICHMENT, symbolId, TaskStatus.PENDING, payload, projectId, now],
  );
}

/**
 * SA4E-88 — Unit tests for PegaIndexerTool and PegaHashCache.
 * Verifies full/incremental indexing, hash detection, and graph writes.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, writeFileSync, mkdirSync, rmSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { PegaIndexerTool, type GraphWriter } from '../PegaIndexerTool.js';
import { computeHash, compareFileHash, type HashCacheData } from '../PegaHashCache.js';

/** Fake GraphWriter tracking all operations (Spy pattern). */
class FakeGraphWriter implements GraphWriter {
  public nodes: Array<{ id: string; label: string; type: string }> = [];
  public edges: Array<{ source: string; target: string; rel: string }> = [];
  public removedPrefixes: string[] = [];

  async addNode(entryId: string, label: string, type: string): Promise<void> {
    this.nodes.push({ id: entryId, label, type });
  }

  async addEdge(source: string, target: string, _w: number, relType: string): Promise<void> {
    this.edges.push({ source, target, rel: relType });
  }

  async removeNodesByPrefix(prefix: string): Promise<void> {
    this.removedPrefixes.push(prefix);
    this.nodes = this.nodes.filter(n => !n.id.startsWith(prefix));
    this.edges = [];
  }
}

/** Minimal Pega Activity rule fixture. */
const ACTIVITY_RULE = {
  pxObjClass: 'Rule-Obj-Activity',
