      const rule = {
        pxObjClass: 'Rule-Obj-Activity',
        pyClassName: 'Work-HR',
        pyRuleName: 'ApproveLeave',
        steps: [{ pyStepNum: '1', pyMethod: 'Call', pyMethodParameters: 'Work-HR.Validate' }],
      };
      await syncRuleToSymbols(mockAdapter, rule, 'proj1', '');

