        pyPurpose: 'MyStrategy',
        pyComponents: [
          { pyName: 'Comp1', pyComponentType: 'Segment', pyRef: 'RefRule1' },
          { pyName: 'Comp2', pyComponentType: 'Filter', pyTreatment: 'RefRule2' },
