import { describe, it, expect } from 'vitest';
import { PegaExpressionParser } from '../../expression/PegaExpressionParser.js';
import { PegExpressionError } from '../../expression/PegaExpressionAst.js';

describe('PegaExpressionParser', () => {
  const parser = new PegaExpressionParser();

  it('parses property ref .Order.Total', () => {
    const ast = parser.parse('.Order.Total');
    expect(ast.nodeType).toBe('PropertyRef');
    expect((ast as any).parts).toEqual(['Order', 'Total']);
  });

  it('parses single property ref .Name', () => {
    const ast = parser.parse('.Name');
    expect((ast as any).parts).toEqual(['Name']);
  });

  it('parses string literal "Open"', () => {
    const ast = parser.parse('"Open"');
    expect(ast.nodeType).toBe('StringLiteral');
    expect((ast as any).value).toBe('Open');
  });

  it('parses number literal 100', () => {
    const ast = parser.parse('100');
    expect(ast.nodeType).toBe('NumberLiteral');
    expect((ast as any).value).toBe(100);
  });

  it('parses function call @round(.Amount, 2)', () => {
    const ast = parser.parse('@round(.Amount, 2)');
    expect(ast.nodeType).toBe('FunctionCall');
    expect((ast as any).name).toBe('@round');
    const args = (ast as any).args;
    expect(args.length).toBe(2);
    expect(args[0].nodeType).toBe('PropertyRef');
    expect(args[1].nodeType).toBe('NumberLiteral');
  });

  it('parses comparison .Status = "Open"', () => {
    const ast = parser.parse('.Status = "Open"');
    expect(ast.nodeType).toBe('BinaryOp');
    expect((ast as any).operator).toBe('EQ');
  });

  it('parses compound .Status = "Open" .AND. .Amount > 100', () => {
    const ast = parser.parse('.Status = "Open" .AND. .Amount > 100');
    expect(ast.nodeType).toBe('BinaryOp');
    expect((ast as any).operator).toBe('AND');
  });

  it('parses NOT .NOT. .Status = "Closed"', () => {
    const ast = parser.parse('.NOT. .Status = "Closed"');
    expect(ast.nodeType).toBe('UnaryOp');
    expect((ast as any).operator).toBe('NOT');
  });

  it('parses ISNULL .ISNULL .Amount', () => {
    const ast = parser.parse('.ISNULL .Amount');
    expect(ast.nodeType).toBe('UnaryOp');
    expect((ast as any).operator).toBe('ISNULL');
  });

  it('parses function @upper(.Name)', () => {
    const ast = parser.parse('@upper(.Name)');
    expect(ast.nodeType).toBe('FunctionCall');
    expect((ast as any).name).toBe('@upper');
  });

  it('parses @CurrentDate()', () => {
    const ast = parser.parse('@CurrentDate()');
    expect(ast.nodeType).toBe('FunctionCall');
    expect((ast as any).args.length).toBe(0);
  });

  it('parses @If with 3 args', () => {
    const ast = parser.parse('@If(.Type = "VIP", .Limit, 0)');
    expect(ast.nodeType).toBe('FunctionCall');
    expect((ast as any).args.length).toBe(3);
  });

  it('handles parentheses (.Amount > 100 .OR. .Priority = "High")', () => {
    const ast = parser.parse('(.Amount > 100 .OR. .Priority = "High")');
    expect(ast.nodeType).toBe('BinaryOp');
    expect((ast as any).operator).toBe('OR');
  });

  it('throws on parse error', () => {
    expect(() => parser.parse('.Status =')).toThrow(PegExpressionError);
  });
});

import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import { PegaExpressionLexer } from '../../expression/PegaExpressionLexer.js';
import { PegaExpressionParser } from '../../expression/PegaExpressionParser.js';
import { PegaExpressionEvaluator } from '../../expression/PegaExpressionEvaluator.js';
import { PegaClipboardContext } from '../../expression/PegaClipboardContext.js';
import {
  PropertyRefNode,
  NumberLiteralNode,
  StringLiteralNode,
  BooleanLiteralNode,
  NullLiteralNode,
  BinaryOpNode,
  UnaryOpNode,
  FunctionCallNode,
} from '../../expression/PegaExpressionAst.js';

const isSimpleString = (s: string): boolean =>
  !s.includes('"') && !s.includes("'") && !s.includes('\\') && !s.includes('\n') && !s.includes('\t');

const isValidIdentifier = (s: string): boolean => /^[a-zA-Z_]\w*$/.test(s);

const evaluator = new PegaExpressionEvaluator();
const parser = new PegaExpressionParser();

describe('Lexer properties', () => {

  it('produces NUMBER tokens for numeric input with consistent parseFloat values', () => {
    fc.assert(fc.property(
      fc.integer({ min: -999999, max: 999999 }).filter(n => n !== -0),
      (n) => {
        const lexer = new PegaExpressionLexer(String(n));
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('NUMBER');
        expect(parseFloat(tokens[0].value)).toBe(n);
        expect(tokens[tokens.length - 1].type).toBe('EOF');
        expect(tokens.length).toBe(2);
      }
    ));
  });

  it('produces NUMBER tokens for decimal input with consistent parseFloat values', () => {
    fc.assert(fc.property(
      fc.integer({ min: 0, max: 9999 }),
      fc.integer({ min: 0, max: 9999 }),
      (int, frac) => {
        const str = `${int}.${String(frac).padStart(1, '0')}`;
        const n = parseFloat(str);
        const lexer = new PegaExpressionLexer(str);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('NUMBER');
        expect(parseFloat(tokens[0].value)).toBeCloseTo(n, 5);
        expect(tokens[0].value).toBe(str);
      }
    ));
  });

  it('produces STRING tokens for string literals with preserved value', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 15 }).filter(isSimpleString),
      (s) => {
        const lexer = new PegaExpressionLexer(`"${s}"`);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('STRING');
        expect(tokens[0].value).toBe(s);
        expect(tokens[tokens.length - 1].type).toBe('EOF');
      }
    ));
  });

  it('produces DOT and IDENTIFIER tokens for property references with correct name', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 20 }).filter(isValidIdentifier),
      (name) => {
        const lexer = new PegaExpressionLexer(`.${name}`);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('DOT');
        expect(tokens[1].type).toBe('IDENTIFIER');
        expect(tokens[1].value).toBe(name);
        expect(tokens[tokens.length - 1].type).toBe('EOF');
      }
    ));
  });

  it('recognizes keyword tokens .AND. .OR. .NOT. .ISNULL with correct types', () => {
    const keywordPairs: [string, string][] = [
      ['.AND.', 'AND'],
      ['.OR.', 'OR'],
      ['.NOT.', 'NOT'],
      ['.ISNULL', 'ISNULL'],
    ];
    fc.assert(fc.property(
      fc.constantFrom(...keywordPairs),
      ([keyword, expectedType]) => {
        const lexer = new PegaExpressionLexer(keyword);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe(expectedType);
        expect(tokens[0].value).toBe(keyword);
        expect(tokens[tokens.length - 1].type).toBe('EOF');
      }
    ));
  });

  it('recognizes comparison operators = <> > < >= <= with correct types', () => {
    const operatorPairs: [string, string][] = [
      ['=', 'EQ'],
      ['<>', 'NEQ'],
      ['>', 'GT'],
      ['<', 'LT'],
      ['>=', 'GTE'],
      ['<=', 'LTE'],
    ];
    fc.assert(fc.property(
      fc.constantFrom(...operatorPairs),
      ([op, expectedType]) => {
        const lexer = new PegaExpressionLexer(`.a ${op} .b`);
        const tokens = lexer.tokenize();
        const opToken = tokens.find(t => t.type === expectedType);
        expect(opToken).toBeDefined();
        expect(opToken!.type).toBe(expectedType);
      }
    ));
  });

  it('recognizes true and false as IDENTIFIER tokens', () => {
    fc.assert(fc.property(
      fc.constantFrom('true', 'false'),
      (s) => {
        const lexer = new PegaExpressionLexer(s);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('IDENTIFIER');
        expect(tokens[0].value).toBe(s);
        expect(tokens[tokens.length - 1].type).toBe('EOF');
      }
    ));
  });

  it('tokenizes FUNCTION tokens with @ prefix preserved', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 15 }).filter(isValidIdentifier),
      (name) => {
        const lexer = new PegaExpressionLexer(`@${name}()`);
        const tokens = lexer.tokenize();
        expect(tokens[0].type).toBe('FUNCTION');
        expect(tokens[0].value).toBe(`@${name}`);
      }
    ));
  });
});

describe('Parser properties', () => {

  it('parses .identifier to PropertyRefNode with correct parts', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 15 }).filter(isValidIdentifier),
      (name) => {
        const ast = parser.parse(`.${name}`);
        expect(ast).toBeInstanceOf(PropertyRefNode);
        expect((ast as PropertyRefNode).parts).toEqual([name]);
      }
    ));
  });

  it('parses chained property ref .a.b.c to PropertyRefNode with all parts', () => {
    fc.assert(fc.property(
      fc.array(fc.string({ minLength: 1, maxLength: 8 }).filter(isValidIdentifier), { minLength: 2, maxLength: 5 }),
      (parts) => {
        const expr = '.' + parts.join('.');
        const ast = parser.parse(expr);
        expect(ast).toBeInstanceOf(PropertyRefNode);
        expect((ast as PropertyRefNode).parts).toEqual(parts);
      }
    ));
  });

  it('parses number literal to NumberLiteralNode with correct value', () => {
    fc.assert(fc.property(
      fc.nat({ max: 999999 }),
      (n) => {
        const ast = parser.parse(String(n));
        expect(ast).toBeInstanceOf(NumberLiteralNode);
        expect((ast as NumberLiteralNode).value).toBe(n);
      }
    ));
  });

  it('parses string literal to StringLiteralNode with correct value', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      (s) => {
        const ast = parser.parse(`"${s}"`);
        expect(ast).toBeInstanceOf(StringLiteralNode);
        expect((ast as StringLiteralNode).value).toBe(s);
      }
    ));
  });

  it('parses boolean literals true and false to BooleanLiteralNode', () => {
    fc.assert(fc.property(
      fc.boolean(),
      (b) => {
        const ast = parser.parse(String(b));
        expect(ast).toBeInstanceOf(BooleanLiteralNode);
        expect((ast as BooleanLiteralNode).value).toBe(b);
      }
    ));
  });

  it('parses comparison .a = .b to BinaryOpNode with EQ operator', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 10 }).filter(isValidIdentifier),
      fc.string({ minLength: 1, maxLength: 10 }).filter(isValidIdentifier),
      (left, right) => {
        const ast = parser.parse(`.${left} = .${right}`);
        expect(ast).toBeInstanceOf(BinaryOpNode);
        expect((ast as BinaryOpNode).operator).toBe('EQ');
        expect((ast as BinaryOpNode).left).toBeInstanceOf(PropertyRefNode);
        expect((ast as BinaryOpNode).right).toBeInstanceOf(PropertyRefNode);
      }
    ));
  });

  it('parses .NOT. .a > 5 with NOT binding around comparison', () => {
    const ast = parser.parse('.NOT. .Amount > 5');
    expect(ast).toBeInstanceOf(UnaryOpNode);
    const unary = ast as UnaryOpNode;
    expect(unary.operator).toBe('NOT');
    expect(unary.operand).toBeInstanceOf(BinaryOpNode);
    const binary = unary.operand as BinaryOpNode;
    expect(binary.operator).toBe('GT');
    expect(binary.left).toBeInstanceOf(PropertyRefNode);
    expect((binary.left as PropertyRefNode).parts).toEqual(['Amount']);
    expect(binary.right).toBeInstanceOf(NumberLiteralNode);
    expect((binary.right as NumberLiteralNode).value).toBe(5);
  });

  it('parses parenthesized expression maintaining structure', () => {
    const withoutParens = parser.parse('.Amount > 5 .AND. .Priority = "High"');
    const withParens = parser.parse('.Amount > 5 .AND. (.Priority = "High")');
    expect(withoutParens).toBeInstanceOf(BinaryOpNode);
    expect(withParens).toBeInstanceOf(BinaryOpNode);
    const b1 = withoutParens as BinaryOpNode;
    const b2 = withParens as BinaryOpNode;
    expect(b1.operator).toBe('AND');
    expect(b2.operator).toBe('AND');
    expect(b1.left).toBeInstanceOf(BinaryOpNode);
    expect(b2.left).toBeInstanceOf(BinaryOpNode);
    expect(b1.right).toBeInstanceOf(BinaryOpNode);
    expect(b2.right).toBeInstanceOf(BinaryOpNode);
  });

  it('parses function call @name(...) to FunctionCallNode with correct name', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 12 }).filter(isValidIdentifier),
      fc.array(fc.nat({ max: 99 }), { minLength: 0, maxLength: 4 }),
      (name, args) => {
        const argStr = args.length > 0 ? args.map(String).join(', ') : '';
        const expr = `@${name}(${argStr})`;
        const ast = parser.parse(expr);
        expect(ast).toBeInstanceOf(FunctionCallNode);
        expect((ast as FunctionCallNode).name).toBe(`@${name}`);
        expect((ast as FunctionCallNode).args.length).toBe(args.length);
      }
    ));
  });
});

describe('Evaluator properties', () => {

  it('evaluates property reference to the value stored in clipboard', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      fc.string({ minLength: 1, maxLength: 10 }).filter(isValidIdentifier),
      (propValue, propName) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            [propName]: { type: 'Text', value: propValue },
          },
        });
        const result = evaluator.evaluate(`.${propName}`, ctx);
        expect(result.value.text).toBe(propValue);
        expect(result.value.type).toBe('Text');
      }
    ));
  });

  it('evaluates @upper(@lower(x)) preserving length', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 20 }).filter(isSimpleString),
      (s) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            Name: { type: 'Text', value: s },
          },
        });
        const lowerResult = evaluator.evaluate('@lower(.Name)', ctx);
        const upperResult = evaluator.evaluate('@upper(.Name)', ctx);
        expect(lowerResult.value.text).toBe(s.toLowerCase());
        expect(upperResult.value.text).toBe(s.toUpperCase());

        const doubleUpper = evaluator.evaluate('@upper(@lower(.Name))', ctx);
        const doubleLower = evaluator.evaluate('@lower(@upper(.Name))', ctx);
        expect(doubleUpper.value.text.length).toBe(s.length);
        expect(doubleLower.value.text.length).toBe(s.length);
        expect(doubleUpper.value.text).toBe(s.toUpperCase());
        expect(doubleLower.value.text).toBe(s.toLowerCase());

        expect(doubleUpper.value.text).toBe(upperResult.value.text);
        expect(doubleLower.value.text).toBe(lowerResult.value.text);
      }
    ));
  });

  it('evaluates @If(trueCondition, valA, valB) to valA', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      (a, b) => {
        const ctx = new PegaClipboardContext({ pyWorkPage: {} });
        const result = evaluator.evaluate(`@If(true, "${a}", "${b}")`, ctx);
        expect(result.value.text).toBe(a);
      }
    ));
  });

  it('evaluates @If(falseCondition, valA, valB) to valB', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      (a, b) => {
        const ctx = new PegaClipboardContext({ pyWorkPage: {} });
        const result = evaluator.evaluate(`@If(false, "${a}", "${b}")`, ctx);
        expect(result.value.text).toBe(b);
      }
    ));
  });

  it('evaluates @Concat(a, b) to a + b', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 8 }).filter(isSimpleString),
      fc.string({ minLength: 0, maxLength: 8 }).filter(isSimpleString),
      (a, b) => {
        const ctx = new PegaClipboardContext({ pyWorkPage: {} });
        const result = evaluator.evaluate(`@Concat("${a}", "${b}")`, ctx);
        expect(result.value.text).toBe(a + b);
        expect(result.value.type).toBe('Text');
      }
    ));
  });

  it('evaluates .ISNULL correctly: null value returns true, non-null returns false', () => {
    fc.assert(fc.property(
      fc.boolean(),
      fc.string({ minLength: 0, maxLength: 8 }).filter(isSimpleString),
      (hasValue, propValue) => {
        const propData = hasValue
          ? { type: 'Text', value: propValue }
          : null;
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            TestProp: propData as any,
          },
        });
        const result = evaluator.evaluate('.ISNULL .TestProp', ctx);
        expect(result.value.boolean).toBe(!hasValue);
        expect(result.value.type).toBe('Boolean');
      }
    ));
  });

  it('evaluates @round preserving integer identity', () => {
    fc.assert(fc.property(
      fc.integer({ min: -9999, max: 9999 }),
      (n) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            Value: { type: 'Number', value: n },
          },
        });
        const result = evaluator.evaluate('@round(.Value)', ctx);
        expect(result.value.number).toBe(n);
        expect(result.value.type).toBe('Number');
      }
    ));
  });

  it('evaluates @Length matching string length', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 30 }).filter(isSimpleString),
      (s) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            TextVal: { type: 'Text', value: s },
          },
        });
        const result = evaluator.evaluate('@Length(.TextVal)', ctx);
        expect(result.value.number).toBe(s.length);
      }
    ));
  });

  it('evaluates numeric comparison operators correctly', () => {
    fc.assert(fc.property(
      fc.integer({ min: -100, max: 100 }),
      fc.integer({ min: -100, max: 100 }),
      (a, b) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            A: { type: 'Number', value: a },
            B: { type: 'Number', value: b },
          },
        });
        expect(evaluator.evaluate('.A = .B', ctx).value.boolean).toBe(a === b);
        expect(evaluator.evaluate('.A <> .B', ctx).value.boolean).toBe(a !== b);
        expect(evaluator.evaluate('.A > .B', ctx).value.boolean).toBe(a > b);
        expect(evaluator.evaluate('.A < .B', ctx).value.boolean).toBe(a < b);
        expect(evaluator.evaluate('.A >= .B', ctx).value.boolean).toBe(a >= b);
        expect(evaluator.evaluate('.A <= .B', ctx).value.boolean).toBe(a <= b);
      }
    ));
  });
});

describe('ClipboardContext properties', () => {

  it('resolves single-part property preserving value across all primitive types', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 10 }).filter(isSimpleString),
      fc.integer({ min: -999, max: 999 }),
      fc.boolean(),
      (textVal, numVal, boolVal) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            TextProp: textVal,
            NumProp: numVal,
            BoolProp: boolVal,
          },
        });
        expect(ctx.resolve(['TextProp']).text).toBe(textVal);
        expect(ctx.resolve(['TextProp']).type).toBe('Text');
        expect(ctx.resolve(['NumProp']).number).toBe(numVal);
        expect(ctx.resolve(['NumProp']).type).toBe('Number');
        expect(ctx.resolve(['BoolProp']).boolean).toBe(boolVal);
        expect(ctx.resolve(['BoolProp']).type).toBe('Boolean');
      }
    ));
  });

  it('resolves nested page property via chained paths', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 0, maxLength: 8 }).filter(isSimpleString),
      fc.string({ minLength: 0, maxLength: 8 }).filter(isSimpleString),
      fc.string({ minLength: 1, maxLength: 8 }).filter(isValidIdentifier),
      fc.string({ minLength: 1, maxLength: 8 }).filter(isValidIdentifier),
      (innerVal, outerVal, innerProp, outerProp) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            [outerProp]: {
              [innerProp]: { type: 'Text', value: innerVal },
            },
            Other: { type: 'Text', value: outerVal },
          },
        });
        const nested = ctx.resolve([outerProp, innerProp]);
        expect(nested.text).toBe(innerVal);
        expect(nested.type).toBe('Text');
        const top = ctx.resolve(['Other']);
        expect(top.text).toBe(outerVal);
      }
    ));
  });

  it('resolves absolute vs relative paths consistently', () => {
    fc.assert(fc.property(
      fc.string({ minLength: 1, maxLength: 8 }).filter(isSimpleString),
      fc.string({ minLength: 1, maxLength: 8 }).filter(isValidIdentifier),
      (propValue, propName) => {
        const ctx = new PegaClipboardContext({
          pyWorkPage: {
            [propName]: { type: 'Text', value: propValue },
          },
        });
        const relative = ctx.resolve([propName]);
        const absolute = ctx.resolve(['pyWorkPage', propName]);
        expect(relative.text).toBe(propValue);
        expect(absolute.text).toBe(propValue);
        expect(relative.text).toBe(absolute.text);
      }
    ));
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { PegaSchemaInferrer, PegaFieldDocumentor } from '../../inference/index.js';
import { PegaMetaModelRegistry, PegaMetaModelLoader, PegaMetaModelCompiler } from '../../metamodel/index.js';
import { MOCK_ACTIVITY_JSON, MOCK_DATA_TRANSFORM_JSON, MOCK_DECISION_TABLE_JSON, MOCK_OPERATOR_DATA_JSON } from '../fixtures/pega-samples.js';
import * as path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const schemasDir = path.resolve(__dirname, '../../schemas');

describe('PegaSchemaInferrer', () => {
  let inferrer: PegaSchemaInferrer;
  let registry: PegaMetaModelRegistry;

  beforeEach(async () => {
    inferrer = new PegaSchemaInferrer();
    registry = PegaMetaModelRegistry.getInstance();
    if (!registry.isKnownClass('@baseclass')) {
      await registry.initialize(schemasDir);
    }
  });

  describe('inferFromRule', () => {
    it('infers pxObjClass correctly from JSON', () => {
      const def = inferrer.inferFromRule('Rule-Obj-Activity', MOCK_ACTIVITY_JSON);
      expect(def.pxObjClass).toBe('Rule-Obj-Activity');
    });

    it('returns properties and children from sample JSON', () => {
      const def = inferrer.inferFromRule('Rule-Obj-Activity', MOCK_ACTIVITY_JSON);
      expect(def.properties.length).toBeGreaterThan(0);
      expect(def.children.length).toBeGreaterThanOrEqual(0);
    });
  });

  describe('inferBaseClass', () => {
    it('infers baseClass for Rule-Obj-Activity → Rule-Obj-', () => {
      const base = inferrer.inferBaseClass('Rule-Obj-Activity', registry);
      expect(base).toBe('Rule-Obj-');
    });

    it('infers baseClass for Rule-Obj-FooBar → Rule-Obj-', () => {
      const base = inferrer.inferBaseClass('Rule-Obj-FooBar', registry);
      expect(base).toBe('Rule-Obj-');
    });

    it('infers baseClass for Rule-Connect-REST → Rule-Connect-', () => {
      const base = inferrer.inferBaseClass('Rule-Connect-REST', registry);
      expect(base).toBe('Rule-Connect-');
    });

    it('infers baseClass for Rule-HTML-Section → Rule-HTML-', () => {
      const base = inferrer.inferBaseClass('Rule-HTML-Section', registry);
      expect(base).toBe('Rule-HTML-');
    });

    it('infers baseClass by walking up hierarchy when intermediate missing', () => {
      const base = inferrer.inferBaseClass('Rule-X-Y', registry);
      expect(base).toBe('Rule-');
    });

    it('infers baseClass for unknown → @baseclass', () => {
      const base = inferrer.inferBaseClass('Something-Completely-Unknown', registry);
      expect(base).toBe('@baseclass');
    });

    it('returns empty string for @baseclass itself', () => {
      const base = inferrer.inferBaseClass('@baseclass', registry);
      expect(base).toBe('');
    });
  });

  describe('inferProperties', () => {
    it('infers properties with correct types (string, number, boolean, ref)', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'My Label',
        pyCount: 42,
        pyActive: true,
        pyClassName: 'Work-Cover',
        pyActivityName: 'DoSomething',
      };
      const props = inferrer.inferProperties(json);
      const label = props.find(p => p.name === 'pyLabel');
      const count = props.find(p => p.name === 'pyCount');
      const active = props.find(p => p.name === 'pyActive');
      const className = props.find(p => p.name === 'pyClassName');
      const activityName = props.find(p => p.name === 'pyActivityName');

      expect(label?.type).toBe('string');
      expect(count?.type).toBe('number');
      expect(active?.type).toBe('boolean');
      expect(className).toBeUndefined();
      expect(activityName).toBeDefined();
      expect(activityName!.type).toBe('ref');
    });

    it('marks Name-ending fields as isReference', () => {
      const json: Record<string, unknown> = {
        pyTemplateName: 'MyTemplate',
        pySourceClass: 'Work-',
        pyLabel: 'Hello',
      };
      const props = inferrer.inferProperties(json);
      const templateName = props.find(p => p.name === 'pyTemplateName');
      const sourceClass = props.find(p => p.name === 'pySourceClass');
      const label = props.find(p => p.name === 'pyLabel');

      expect(templateName?.isReference).toBe(true);
      expect(templateName?.type).toBe('ref');
      expect(sourceClass?.isReference).toBe(true);
      expect(sourceClass?.type).toBe('ref');
      expect(label?.isReference).toBe(false);
    });

    it('marks Class-ending fields as isReference', () => {
      const json: Record<string, unknown> = {
        pyTargetClass: 'Work-Cover',
        pySourceClass: 'Data-Admin',
        pyDescription: 'some text',
      };
      const props = inferrer.inferProperties(json);
      const tc = props.find(p => p.name === 'pyTargetClass');
      const sc = props.find(p => p.name === 'pySourceClass');
      expect(tc?.isReference).toBe(true);
      expect(sc?.isReference).toBe(true);
    });

    it('marks Profile-ending fields as isReference', () => {
      const json: Record<string, unknown> = {
        pyAuthProfile: 'MyProfile',
        pyLabel: 'test',
      };
      const props = inferrer.inferProperties(json);
      const profile = props.find(p => p.name === 'pyAuthProfile');
      expect(profile?.isReference).toBe(true);
      expect(profile?.type).toBe('ref');
    });

    it('detects children from array fields', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'test',
        steps: [
          { pxObjClass: 'Embedded-Step', pyStepNum: '1', pyMethod: 'Call' },
          { pxObjClass: 'Embedded-Step', pyStepNum: '2', pyMethod: 'Call' },
        ],
      };
      const children = inferrer.inferChildren(json);
      const stepsChild = children.find(c => c.name === 'steps');
      expect(stepsChild).toBeDefined();
      expect(stepsChild!.childType).toBe('Embedded-Step');
      expect(stepsChild!.arrayType).toBe('array');
    });

    it('does not produce duplicate properties', () => {
      const json: Record<string, unknown> = { pyLabel: 'A' };
      Object.defineProperty(json, 'pyLabel', { value: 'B', enumerable: true, writable: true, configurable: true });
      const props = inferrer.inferProperties(json);
      const labels = props.filter(p => p.name === 'pyLabel');
      expect(labels.length).toBeLessThanOrEqual(1);
    });

    it('detects reference from dotted value like class.method', () => {
      const json: Record<string, unknown> = {
        pyMethodCall: 'Work-Cover.SomeActivity',
        pyLabel: 'Simple Label',
      };
      const props = inferrer.inferProperties(json);
      const methodCall = props.find(p => p.name === 'pyMethodCall');
      expect(methodCall).toBeDefined();
      expect(methodCall!.type).toBe('ref');
    });
  });

  describe('ensureSchema', () => {
    it('creates and registers when class unknown', () => {
      const freshRegistry = PegaMetaModelRegistry.getInstance();
      const json: Record<string, unknown> = {
        pyLabel: 'Test Rule',
        pyDescription: 'A test rule',
      };
      const def = inferrer.ensureSchema('Rule-Obj-TestUnknown', json, freshRegistry);
      expect(def.pxObjClass).toBe('Rule-Obj-TestUnknown');
      expect(freshRegistry.isKnownClass('Rule-Obj-TestUnknown')).toBe(true);
      const fetched = freshRegistry.getParser('Rule-Obj-TestUnknown');
      expect(fetched).toBeDefined();
      expect(fetched!.pxObjClass).toBe('Rule-Obj-TestUnknown');
    });

    it('returns existing when class known', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'Activity',
      };
      const first = inferrer.ensureSchema('Rule-Obj-TestKnown', json, registry);
      const second = inferrer.ensureSchema('Rule-Obj-TestKnown', json, registry);
      expect(second).toBe(first);
    });

    it('sets baseClass for newly inferred schemas', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'New Rule',
      };
      const def = inferrer.ensureSchema('Rule-Obj-NewThing', json, registry);
      expect(def.baseClass).toBeDefined();
      expect(def.baseClass!.startsWith('Rule-')).toBe(true);
    });

    it('returns pre-loaded schema for known class in registry', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'Extra Field Not In Schema',
      };
      const def = inferrer.ensureSchema('Rule-Obj-Activity', json, registry);
      expect(def.pxObjClass).toBe('Rule-Obj-Activity');
      expect(def.label).toBeDefined();
    });
  });

  describe('hasKnownSchema', () => {
    it('returns false for unknown type', () => {
      expect(inferrer.hasKnownSchema('Totally-Unregistered-Type', registry)).toBe(false);
    });

    it('returns true for known type after ensureSchema', () => {
      const json: Record<string, unknown> = { pyLabel: 'test' };
      inferrer.ensureSchema('Rule-Obj-CheckKnown', json, registry);
      expect(inferrer.hasKnownSchema('Rule-Obj-CheckKnown', registry)).toBe(true);
    });
  });

  describe('isReferenceField', () => {
    it('detects Name-suffix fields as reference', () => {
      expect(inferrer.isReferenceField('pyActivityName')).toBe(true);
      expect(inferrer.isReferenceField('pyModelName')).toBe(true);
      expect(inferrer.isReferenceField('pyRuleName')).toBe(true);
      expect(inferrer.isReferenceField('pyTransformName')).toBe(true);
    });

    it('detects Class-suffix fields as reference', () => {
      expect(inferrer.isReferenceField('pyClassName')).toBe(true);
      expect(inferrer.isReferenceField('pySuperClass')).toBe(true);
      expect(inferrer.isReferenceField('pyTargetClass')).toBe(true);
    });

    it('detects Profile-suffix fields as reference', () => {
      expect(inferrer.isReferenceField('pyAuthProfile')).toBe(true);
    });

    it('does not mark plain fields as reference', () => {
      expect(inferrer.isReferenceField('pyLabel')).toBe(false);
      expect(inferrer.isReferenceField('pyDescription')).toBe(false);
      expect(inferrer.isReferenceField('pyCount')).toBe(false);
    });
  });

  describe('handle edge cases', () => {
    it('handles empty JSON gracefully', () => {
      const def = inferrer.inferFromRule('Rule-Obj-Empty', {});
      expect(def.pxObjClass).toBe('Rule-Obj-Empty');
      expect(def.properties).toEqual([]);
      expect(def.children).toEqual([]);
    });

    it('handles malformed JSON (null values)', () => {
      const json: Record<string, unknown> = {
        pyLabel: null,
        pyCount: null,
        pyActive: null,
      };
      const props = inferrer.inferProperties(json);
      expect(props.length).toBeGreaterThanOrEqual(0);
    });

    it('handles deeply nested JSON (objects as values → skip)', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'test',
        nestedObject: { innerKey: 'value', deeper: { a: 1 } },
        anotherProp: 'keep me',
      };
      const props = inferrer.inferProperties(json);
      const nested = props.find(p => p.name === 'nestedObject');
      expect(nested).toBeUndefined();
      expect(props.find(p => p.name === 'anotherProp')).toBeDefined();
    });

    it('marks system fields with pxCreate* and pxUpdate* prefixes as isSystem', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'test',
        pxCreateDateTime: '2026-07-27T10:00:00Z',
        pxUpdateOperator: 'user@test.com',
      };
      const props = inferrer.inferProperties(json);
      const createTime = props.find(p => p.name === 'pxCreateDateTime');
      const updateOp = props.find(p => p.name === 'pxUpdateOperator');
      expect(createTime).toBeDefined();
      expect(createTime!.isSystem).toBe(true);
      expect(updateOp).toBeDefined();
      expect(updateOp!.isSystem).toBe(true);
      expect(props.find(p => p.name === 'pyLabel')).toBeDefined();
    });

    it('marks system fields with pz* prefix as isSystem', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'test',
        pzChecksum: 'abc123',
        pzIndex: '0',
      };
      const props = inferrer.inferProperties(json);
      const checksum = props.find(p => p.name === 'pzChecksum');
      const index = props.find(p => p.name === 'pzIndex');
      expect(checksum).toBeDefined();
      expect(checksum!.isSystem).toBe(true);
      expect(index).toBeDefined();
      expect(index!.isSystem).toBe(true);
    });

    it('skips pxObjClass, pyClassName, pyRuleName in properties', () => {
      const json: Record<string, unknown> = {
        pxObjClass: 'Rule-Obj-Test',
        pyClassName: 'Work-Test',
        pyRuleName: 'MyRule',
        pyLabel: 'visible',
      };
      const props = inferrer.inferProperties(json);
      expect(props.find(p => p.name === 'pxObjClass')).toBeUndefined();
      expect(props.find(p => p.name === 'pyClassName')).toBeUndefined();
      expect(props.find(p => p.name === 'pyRuleName')).toBeUndefined();
      expect(props.find(p => p.name === 'pyLabel')).toBeDefined();
    });

    it('skips skipped arrays pxAllChangeList, pxWarnings', () => {
      const json: Record<string, unknown> = {
        pyLabel: 'test',
        pxAllChangeList: [],
        pxWarnings: [],
      };
      const children = inferrer.inferChildren(json);
      expect(children.find(c => c.name === 'pxAllChangeList')).toBeUndefined();
      expect(children.find(c => c.name === 'pxWarnings')).toBeUndefined();
    });
  });
});

