  afterAll(async () => {
    await adapter.disconnect();
  });

  it('TC-01: Check-rule returns cache miss for un-indexed activity', async () => {
    const res = await app.request('/api/v1/pega/check-rule', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
