  });
});

describe('PegaWorkflowEngine', () => {
  it('simulates a simple linear flow Start -> Action -> End', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    shapes.set('action', { id: 'action', type: 'Action', properties: {} });
    shapes.set('end', { id: 'end', type: 'End', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'action', isDefault: true },
      { id: 'c2', fromShapeId: 'action', toShapeId: 'end', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(true);
    expect(result.currentNodeId).toBe('end');
    expect(result.history).toEqual(['start', 'action', 'end']);
    expect(result.log).toHaveLength(4);
    expect(result.log[0]).toContain('Start');
    expect(result.log[1]).toContain('Action');
    expect(result.log[2]).toContain('End');
    expect(result.log[3]).toContain('Reached END');
  });

  it('returns completed=true and stops at the first End shape reached', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    shapes.set('mid', { id: 'mid', type: 'Action', properties: {} });
    shapes.set('end1', { id: 'end1', type: 'End', properties: {} });
    shapes.set('end2', { id: 'end2', type: 'End', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'mid', isDefault: true },
      { id: 'c2', fromShapeId: 'mid', toShapeId: 'end1', isDefault: true },
      { id: 'c3', fromShapeId: 'end1', toShapeId: 'end2', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(true);
    expect(result.currentNodeId).toBe('end1');
    expect(result.history).toEqual(['start', 'mid', 'end1']);
  });

  it('returns completed=false when the graph has no Start shape', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('a1', { id: 'a1', type: 'Action', properties: {} });
    shapes.set('e1', { id: 'e1', type: 'End', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'a1', toShapeId: 'e1', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(false);
    expect(result.currentNodeId).toBe('');
  });

  it('stops and logs when a shape referenced by a connector is not in the graph', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'missing', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(false);
    expect(result.currentNodeId).toBe('missing');
    expect(result.log.some(l => l.includes('not found'))).toBe(true);
  });

  it('stops when a shape has no outgoing connectors (dead end without End type)', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    shapes.set('dead', { id: 'dead', type: 'Action', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'dead', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(false);
    expect(result.currentNodeId).toBe('dead');
  });

  it('starts from a specific shape when startShapeId is provided', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('s1', { id: 's1', type: 'Start', properties: {} });
    shapes.set('s2', { id: 's2', type: 'Action', properties: {} });
    shapes.set('s3', { id: 's3', type: 'End', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 's1', toShapeId: 's2', isDefault: true },
      { id: 'c2', fromShapeId: 's2', toShapeId: 's3', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context, 's2');
    expect(result.history[0]).toBe('s2');
    expect(result.history).toEqual(['s2', 's3']);
    expect(result.completed).toBe(true);
  });

  it('detects loops by exhausting the max step limit (50 steps)', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    shapes.set('loop', { id: 'loop', type: 'Action', properties: {} });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'loop', isDefault: true },
      { id: 'c2', fromShapeId: 'loop', toShapeId: 'loop', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(false);
    expect(result.history).toHaveLength(50);
  });

  it('handles flow where End shape is identified via pyShapeType property', () => {
    const shapes = new Map<string, ShapeNode>();
    shapes.set('start', { id: 'start', type: 'Start', properties: {} });
    shapes.set('end', { id: 'end', type: 'CustomEnd', properties: { pyShapeType: 'End' } });
    const connectors: Connector[] = [
      { id: 'c1', fromShapeId: 'start', toShapeId: 'end', isDefault: true },
    ];
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(true);
    expect(result.currentNodeId).toBe('end');
    expect(result.log.some(l => l.includes('END'))).toBe(true);
  });

  it('simulates flow with multiple sequential actions before reaching end', () => {
    const shapeIds = ['start', 'a1', 'a2', 'a3', 'end'];
    const shapes = new Map<string, ShapeNode>(
      shapeIds.map(id => [id, { id, type: id === 'start' ? 'Start' : id === 'end' ? 'End' : 'Action', properties: {} }]),
    );
    const connectors: Connector[] = [];
    for (let i = 0; i < shapeIds.length - 1; i++) {
      connectors.push({ id: `c${i}`, fromShapeId: shapeIds[i], toShapeId: shapeIds[i + 1], isDefault: true });
    }
    const graph = new PegaFlowGraph(shapes, connectors);
    const engine = new PegaWorkflowEngine();
    const context = new PegaClipboardContext({ pyWorkPage: {} });
    const result = engine.simulate(graph, context);
    expect(result.completed).toBe(true);
    expect(result.history).toEqual(shapeIds);
    expect(result.currentNodeId).toBe('end');
  });
});

import type { IPegaRuleParserStrategy, ParseResult } from '../strategies/IPegaRuleParserStrategy.js';
import type { UnresolvedDependency } from '../models.js';
import type { PegaConnectRule, PegaConnectHeader, PegaServiceRule, ConnectMethod, ConnectType, AuthType } from './PegaConnectTypes.js';

const CONNECT_CLASSES = new Set([
  'Rule-Connect-REST',
  'Rule-Connect-SOAP',
  'Rule-Connect-SQL',
  'Rule-Connect-File',
  'Rule-Connect-HTTP',
  'Rule-Connect-MQ',
  'Rule-Connect-JMS',
  'Rule-Connect-JCA',
  'Rule-Connect-Java',
  'Rule-Connect-EJB',
  'Rule-Connect-dotNet',
  'Rule-Connect-CMIS',
]);

export class PegaConnectParser implements IPegaRuleParserStrategy {
  public supports(pxObjClass: string): boolean {
    if (pxObjClass.startsWith('Rule-Service-')) return true;
    if (CONNECT_CLASSES.has(pxObjClass)) return true;
    if (pxObjClass.startsWith('Rule-Connect-')) return true;
    return false;
  }

  public parse(json: Record<string, unknown>): ParseResult {
    const pxObjClass = (json.pxObjClass as string) || '';
    const className = (json.pyClassName as string) || '@baseclass';
    const name = this.extractName(pxObjClass, json);
    const fqn = `${pxObjClass}:${className}:${name}`;

    const dependencies = this.extractDependencies(json);

    const logicSummary = this.buildLogicSummary(pxObjClass, json);

    const symbol = {
      fqn,
      name,
      className,
      ruleType: pxObjClass,
      isRule: true,
      ruleset: (json.pyRuleset as string) || undefined,
      version: (json.pyRulesetVersion as string) || undefined,
      logicSummary,
    };

    return { symbol, dependencies };
  }

  private extractName(pxObjClass: string, json: Record<string, unknown>): string {
    return (json.pyRuleName as string)
      || (json.pyServiceRuleName as string)
      || (json.pyServiceName as string)
      || (json.pyLabel as string)
      || '';
  }

  public parseConnectRest(json: Record<string, unknown>): PegaConnectRule {
    const headers = this.parseHeaders(json);
    return {
      pxObjClass: (json.pxObjClass as string) || 'Rule-Connect-REST',
      pyName: this.extractName('Rule-Connect-REST', json),
      pyLabel: (json.pyLabel as string) || undefined,
      connectType: 'REST',
      endpoint: this.resolveEndpoint(json),
      method: this.resolveMethod(json),
      authType: this.resolveAuthType(json),
      authRef: (json.pyAuthProfile as string) || undefined,
      headers,
      requestMapping: (json.pyRequestDataTransform as string) || undefined,
      responseMapping: (json.pyResponseDataTransform as string) || undefined,
    };
  }

  public parseConnectSoap(json: Record<string, unknown>): PegaConnectRule {
    const headers = this.parseHeaders(json);
    return {
      pxObjClass: (json.pxObjClass as string) || 'Rule-Connect-SOAP',
      pyName: this.extractName('Rule-Connect-SOAP', json),
      pyLabel: (json.pyLabel as string) || undefined,
      connectType: 'SOAP',
      endpoint: this.resolveEndpoint(json),
      method: this.resolveMethod(json),
      authType: this.resolveAuthType(json),
      authRef: (json.pyAuthProfile as string) || undefined,
      headers,
      wsdlUrl: (json.pyWSDLURL as string) || (json.pyWsdlUrl as string) || undefined,
      soapAction: (json.pySoapAction as string) || (json.pySOAPAction as string) || undefined,
      requestMapping: (json.pyRequestDataTransform as string) || undefined,
      responseMapping: (json.pyResponseDataTransform as string) || undefined,
    };
  }

  public parseConnectSql(json: Record<string, unknown>): PegaConnectRule {
    return {
      pxObjClass: (json.pxObjClass as string) || 'Rule-Connect-SQL',
      pyName: this.extractName('Rule-Connect-SQL', json),
      pyLabel: (json.pyLabel as string) || undefined,
      connectType: 'SQL',
      endpoint: (json.pyDataSource as string) || undefined,
      method: undefined,
      dataSource: (json.pyDataSource as string) || (json.pyRWAccess as string) || undefined,
      sqlStatement: (json.pySQLStatement as string) || (json.pyStatement as string) || undefined,
    };
  }

  public parseConnectFile(json: Record<string, unknown>): PegaConnectRule {
    return {
      pxObjClass: (json.pxObjClass as string) || 'Rule-Connect-File',
      pyName: this.extractName('Rule-Connect-File', json),
      pyLabel: (json.pyLabel as string) || undefined,
      connectType: 'File',
      filePath: (json.pyFilePath as string) || (json.pyFileName as string) || undefined,
      filePattern: (json.pyFilePattern as string) || undefined,
    };
  }

  public parseServiceRule(json: Record<string, unknown>): PegaServiceRule {
    const methodStr = (json.pyHttpMethod as string) || (json.pyHTTPMethod as string) || 'GET';
    return {
      pxObjClass: (json.pxObjClass as string) || 'Rule-Service-REST',
      pyName: this.extractName('Rule-Service-REST', json),
      serviceType: (json.pyServiceType as string) || this.inferServiceType(json),
      endpoint: this.resolveEndpoint(json) || '',
      allowedMethods: methodStr.split(',').map(m => m.trim() as ConnectMethod).filter(m => ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(m)),
    };
  }

  private resolveEndpoint(json: Record<string, unknown>): string | undefined {
    return (json.pyEndpointURL as string)
      || (json.pyBaseURL as string)
      || (json.pyResourcePath as string)
      || (json.pyUrl as string)
      || undefined;
  }

  private resolveMethod(json: Record<string, unknown>): ConnectMethod | undefined {
    const method = (json.pyHttpMethod as string) || (json.pyHTTPMethod as string) || (json.pyMethod as string);
    if (method && ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(method.toUpperCase())) {
      return method.toUpperCase() as ConnectMethod;
    }
    return undefined;
  }

  private resolveAuthType(json: Record<string, unknown>): AuthType | undefined {
    const auth = (json.pyAuthType as string) || '';
    if (!auth) return undefined;
    const lower = auth.toLowerCase();
    if (lower === 'basic') return 'basic';
    if (lower === 'oauth2') return 'oauth2';
    if (lower === 'apikey') return 'apiKey';
    if (lower === 'custom') return 'custom';
    if (lower === 'none') return 'none';
    if (lower.includes('oauth') || lower.includes('oauth2')) return 'oauth2';
    if (lower.includes('basic')) return 'basic';
    if (lower.includes('apikey') || lower.includes('api_key') || lower.includes('api key')) return 'apiKey';
    return 'custom';
  }

  private parseHeaders(json: Record<string, unknown>): PegaConnectHeader[] | undefined {
    const rawHeaders = json.pyHeaders as unknown[];
    if (!Array.isArray(rawHeaders) || rawHeaders.length === 0) return undefined;
    return rawHeaders.map(h => {
      const header = h as Record<string, unknown>;
      return {
        pyName: (header.pyHeaderName as string) || (header.pyName as string) || '',
        pyValue: (header.pyHeaderValue as string) || (header.pyValue as string) || '',
      };
    });
  }

  private inferServiceType(json: Record<string, unknown>): string {
    const cls = (json.pxObjClass as string) || '';
    if (cls.startsWith('Rule-Service-REST')) return 'REST';
    if (cls.startsWith('Rule-Service-SOAP')) return 'SOAP';
    if (cls.startsWith('Rule-Service-File')) return 'File';
    if (cls.startsWith('Rule-Service-')) return cls.substring('Rule-Service-'.length);
    return 'REST';
  }

  private extractDependencies(json: Record<string, unknown>): UnresolvedDependency[] {
    const deps: UnresolvedDependency[] = [];
    const className = (json.pyClassName as string) || '@baseclass';

    const authRef = (json.pyAuthProfile as string);
    if (authRef) {
      deps.push({ ruleType: 'Rule-Connect-AuthProfile', className: '@baseclass', ruleName: authRef });
    }
    const requestMapping = (json.pyRequestDataTransform as string);
    if (requestMapping) {
      deps.push({ ruleType: 'Rule-Obj-Model', className, ruleName: requestMapping });
    }
    const responseMapping = (json.pyResponseDataTransform as string);
    if (responseMapping) {
      deps.push({ ruleType: 'Rule-Obj-Model', className, ruleName: responseMapping });
    }

    return deps;
  }

  private buildLogicSummary(pxObjClass: string, json: Record<string, unknown>): string {
    const lines: string[] = [];
    lines.push(`${pxObjClass}: ${this.extractName(pxObjClass, json)}`);

    if (pxObjClass.startsWith('Rule-Connect-REST') || pxObjClass.startsWith('Rule-Connect-HTTP')) {
      lines.push(`  Endpoint: ${this.resolveEndpoint(json) || '(not set)'}`);
      lines.push(`  Method: ${this.resolveMethod(json) || 'GET'}`);
      const auth = (json.pyAuthProfile as string);
      if (auth) lines.push(`  Auth Profile: ${auth}`);
      const reqMap = (json.pyRequestDataTransform as string);
      if (reqMap) lines.push(`  Request Transform: ${reqMap}`);
      const resMap = (json.pyResponseDataTransform as string);
      if (resMap) lines.push(`  Response Transform: ${resMap}`);
    } else if (pxObjClass === 'Rule-Connect-SOAP') {
      lines.push(`  WSDL: ${(json.pyWSDLURL as string) || '(not set)'}`);
      lines.push(`  SOAP Action: ${(json.pySoapAction as string) || '(not set)'}`);
    } else if (pxObjClass === 'Rule-Connect-SQL') {
      lines.push(`  Data Source: ${(json.pyDataSource as string) || '(not set)'}`);
      const stmt = (json.pySQLStatement as string) || '';
      lines.push(`  Statement: ${stmt.substring(0, 80)}${stmt.length > 80 ? '...' : ''}`);
    } else if (pxObjClass === 'Rule-Connect-File') {
      lines.push(`  File Path: ${(json.pyFilePath as string) || '(not set)'}`);
      lines.push(`  Pattern: ${(json.pyFilePattern as string) || '(none)'}`);
    } else if (pxObjClass.startsWith('Rule-Service-')) {
      lines.push(`  Endpoint: ${this.resolveEndpoint(json) || '(not set)'}`);
      lines.push(`  Methods: ${(json.pyHttpMethod as string) || (json.pyHTTPMethod as string) || 'GET'}`);
    }

    return lines.join('\n');
  }
}

import type { PegValue } from '../expression/PegaExpressionAst.js';

export type DecisionOperator =
  | 'EQUALS'
  | 'NOT_EQUALS'
  | 'GREATER'
  | 'GREATER_EQUALS'
  | 'LESS'
  | 'LESS_EQUALS'
  | 'IN'
  | 'NOT_IN'
  | 'IS_NULL'
  | 'IS_BLANK'
  | 'CUSTOM';

export interface PegaDecisionCondition {
  field: string;
  operator: DecisionOperator;
  value: unknown;
}

export interface PegaDecisionTableRow {
  rowId: string;
  priority: number;
  conditions: PegaDecisionCondition[];
  result: unknown;
}

export interface DecisionTreeBranch {
  key: string;
  conditionResult: unknown;
  childNode: DecisionTreeNode | null;
}

export interface DecisionTreeNode {
  nodeId: string;
  condition: PegaDecisionCondition;
  branches: DecisionTreeBranch[];
  defaultResult?: unknown;
}

export interface PegaEvaluationResult {
  matchedRowId: string;
  outputValue: unknown;
  tracePath: string[];
  status: 'matched' | 'no_match' | 'error';
  error?: string;
}

/**
 * PegaDeclareParser — Strategy parser for all Rule-Declare-* rule types.
 * Integrates with the expression engine (WP1) for Declare Expression.
 *
 * Handles:
 *   - Rule-Declare-Expressions  → PegaDeclareExpression
 *   - Rule-Declare-OnChange     → PegaDeclareOnChange
 *   - Rule-Declare-Trigger      → PegaDeclareTrigger
 *   - Rule-Declare-Pages        → PegaDeclarePages
 *   - Rule-Declare-Constraints  → PegaDeclareConstraint
 *   - Rule-Declare-Index        → PegaDeclareIndex
 *   - Rule-Declare-DecisionTable → PegaDeclareDecisionTable
 *   - Rule-Declare-DecisionTree → PegaDeclareDecisionTree
 */

import type { IPegaRuleParserStrategy, ParseResult } from '../strategies/IPegaRuleParserStrategy.js';
import type { UnresolvedDependency } from '../models.js';
import { PegaExpressionParser } from '../expression/PegaExpressionParser.js';
import type {
  PegaDeclareExpression,
  PegaDeclareOnChange,
  PegaDeclareTrigger,
  PegaDeclarePages,
  PegaDeclareConstraint,
  PegaDeclareIndex,
  PegaDeclareDecisionTable,
  PegaDeclareDecisionTree,
  DeclareOnChangeAction,
  DeclarePageDefinition,
  DeclareDecisionRow,
} from './PegaDeclareTypes.js';

/**
 * Set of pxObjClass values handled by this strategy.
 * DecisionTable and DecisionTree are included even though they also
 * work via the original buildDecision path — this strategy provides
 * richer typed output.
 */
const DECLARE_RULE_CLASSES = new Set([
  'Rule-Declare-Expressions',
  'Rule-Declare-OnChange',
  'Rule-Declare-Trigger',
  'Rule-Declare-Pages',
  'Rule-Declare-Constraints',
  'Rule-Declare-Index',
  'Rule-Declare-DecisionTable',
  'Rule-Declare-DecisionTree',
]);

/** pxObjClass → DeclareType mapping */
const CLASS_TO_DECLARE_TYPE: Record<string, string> = {
  'Rule-Declare-Expressions': 'Declare-Expression',
  'Rule-Declare-OnChange': 'Declare-OnChange',
  'Rule-Declare-Trigger': 'Declare-Trigger',
  'Rule-Declare-Pages': 'Declare-Pages',
  'Rule-Declare-Constraints': 'Declare-Constraints',
  'Rule-Declare-Index': 'Declare-Index',
  'Rule-Declare-DecisionTable': 'Declare-DecisionTable',
  'Rule-Declare-DecisionTree': 'Declare-DecisionTree',
};

export class PegaDeclareParser implements IPegaRuleParserStrategy {
  private expressionParser = new PegaExpressionParser();

  public supports(pxObjClass: string): boolean {
    return DECLARE_RULE_CLASSES.has(pxObjClass);
  }

  public parse(json: Record<string, unknown>): ParseResult {
    const pxObjClass = (json.pxObjClass as string) || '';
    const className = (json.pyClassName as string) || '@baseclass';
    const name = (json.pyRuleName as string) || (json.pyLabel as string) || 'UnnamedDeclare';
    const fqn = `${pxObjClass}:${className}:${name}`;
    const declareType = (CLASS_TO_DECLARE_TYPE[pxObjClass] || pxObjClass) as any;

    const dependencies: UnresolvedDependency[] = [];

    // Build a logic summary for the symbol
    let logicSummary = '';

    switch (pxObjClass) {
      case 'Rule-Declare-Expressions': {
        const parsed = this.parseDeclareExpression(json);
        logicSummary = `Declare Expression: .${parsed.targetProperty} = ${parsed.expression}`;
        break;
      }
      case 'Rule-Declare-OnChange': {
        const parsed = this.parseDeclareOnChange(json);
        logicSummary = `Declare OnChange: .${parsed.targetProperty} → ${parsed.actions.length} action(s)`;
        for (const action of parsed.actions) {
          if (action.type !== 'setValue') {
            dependencies.push({ ruleType: this.actionRuleType(action.type), className, ruleName: action.target });
          }
        }
        if (parsed.whenCondition) {
          dependencies.push({ ruleType: 'Rule-Obj-When', className, ruleName: parsed.whenCondition });
        }
        break;
      }
      case 'Rule-Declare-Trigger': {
        const parsed = this.parseDeclareTrigger(json);
        logicSummary = `Declare Trigger: ${parsed.triggerType}-${parsed.operation} on ${parsed.targetClass}`;
        dependencies.push({ ruleType: parsed.actionType === 'Activity' ? 'Rule-Obj-Activity' : 'Rule-Obj-Model', className, ruleName: parsed.action });
        if (parsed.whenCondition) {
          dependencies.push({ ruleType: 'Rule-Obj-When', className, ruleName: parsed.whenCondition });
        }
        break;
      }
      case 'Rule-Declare-Pages': {
        const parsed = this.parseDeclarePages(json);
        logicSummary = `Declare Pages: ${parsed.pages.length} page(s)`;
        break;
      }
      case 'Rule-Declare-Constraints': {
        const parsed = this.parseDeclareConstraint(json);
        logicSummary = `Declare Constraint: .${parsed.property} ${parsed.constraintType}=${parsed.constraintValue}`;
        break;
      }
      case 'Rule-Declare-Index': {
        const parsed = this.parseDeclareIndex(json);
        logicSummary = `Declare Index: .${parsed.property}${parsed.indexType ? ' (' + parsed.indexType + ')' : ''}`;
        break;
      }
      case 'Rule-Declare-DecisionTable': {
        const parsed = this.parseDeclareDecisionTable(json);
        logicSummary = `Declare DecisionTable: ${parsed.rows.length} row(s)`;
        break;
      }
      case 'Rule-Declare-DecisionTree': {
        const parsed = this.parseDeclareDecisionTree(json);
        logicSummary = `Declare DecisionTree: ${parsed.rows.length} row(s)`;
        break;
      }
      default:
        logicSummary = `Declare (${pxObjClass})`;
    }

    const symbol = {
      fqn,
      name,
      className,
      ruleType: pxObjClass,
      isRule: true,
      ruleset: (json.pyRuleset as string) || undefined,
      version: (json.pyRulesetVersion as string) || undefined,
      logicSummary,
    };

    return { symbol, dependencies };
  }

  /**
   * Parse a Declare Expression rule.
   * Uses the PegaExpressionParser (WP1) to build an AST from the expression string.
   */
  public parseDeclareExpression(json: Record<string, unknown>): PegaDeclareExpression {
    const targetProperty = (json.pyProperty as string) || (json.pxResult as string) || '';
    const expression = (json.pyExpression as string) || '';

    let expressionAst = undefined;
    if (expression) {
      try {
        expressionAst = this.expressionParser.parse(expression);
      } catch {
        // If expression fails to parse, continue without AST
      }
    }

    return {
      pxObjClass: 'Rule-Declare-Expressions',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-Expression',
      targetProperty,
      expression,
      expressionAst,
    };
  }

  /**
   * Parse a Declare OnChange rule.
   */
  public parseDeclareOnChange(json: Record<string, unknown>): PegaDeclareOnChange {
    const targetProperty = (json.pyProperty as string) || '';
    const whenCondition = (json.pyWhenCondition as string) || undefined;

    const actions: DeclareOnChangeAction[] = [];
    const rawActions = Array.isArray(json.pyActions) ? json.pyActions : [];

    for (const raw of rawActions) {
      if (typeof raw !== 'object' || !raw) continue;
      const act = raw as Record<string, unknown>;
      const actionType = (act.pyActionType as string) || '';
      const target = (act.pyTarget as string) || (act.pyActivityName as string) || (act.pyTransformName as string) || '';

      let type: DeclareOnChangeAction['type'];
      if (actionType.includes('Activity')) type = 'runActivity';
      else if (actionType.includes('Transform')) type = 'runDataTransform';
      else if (actionType.includes('Report')) type = 'runReport';
      else if (actionType.includes('Set')) type = 'setValue';
      else type = 'runActivity';

      const params: Record<string, string> = {};
      if (act.pyParameters && typeof act.pyParameters === 'object') {
        for (const [k, v] of Object.entries(act.pyParameters as Record<string, unknown>)) {
          params[k] = String(v);
        }
      }

      actions.push({ type, target, params: Object.keys(params).length > 0 ? params : undefined });
    }

    return {
      pxObjClass: 'Rule-Declare-OnChange',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-OnChange',
      targetProperty,
      whenCondition,
      actions,
    };
  }

  /**
   * Parse a Declare Trigger rule.
   */
  public parseDeclareTrigger(json: Record<string, unknown>): PegaDeclareTrigger {
    const triggerType = ((json.pyTriggerType as string) || 'after') as 'before' | 'after' | 'instead';
    const operation = ((json.pyOperation as string) || 'save') as 'save' | 'delete' | 'open';
    const targetClass = (json.pyClassName as string) || '';
    const whenCondition = (json.pyWhenCondition as string) || undefined;
    const action = (json.pyActivityName as string) || (json.pyTransformName as string) || '';
    const actionTypeStr = (json.pyActionType as string) || 'Activity';
    const actionType = actionTypeStr === 'DataTransform' ? 'DataTransform' : 'Activity';

    return {
      pxObjClass: 'Rule-Declare-Trigger',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-Trigger',
      triggerType,
      operation,
      targetClass,
      whenCondition,
      action,
      actionType,
    };
  }

  /**
   * Parse a Declare Pages rule.
   */
  public parseDeclarePages(json: Record<string, unknown>): PegaDeclarePages {
    const pages: DeclarePageDefinition[] = [];
    const rawPages = Array.isArray(json.pyPages) ? json.pyPages : [];

    for (const raw of rawPages) {
      if (typeof raw !== 'object' || !raw) continue;
      const pg = raw as Record<string, unknown>;
      const name = (pg.pyPageName as string) || '';
      const sourceStr = (pg.pySource as string) || (pg.pyPageSource as string) || 'clipboard';
      const sourceRef = (pg.pySourceClass as string) || (pg.pyRuleName as string) || '';

      let source: DeclarePageDefinition['source'];
      if (sourceStr.includes('DataPage') || sourceStr.includes('dataPage')) source = 'dataPage';
      else if (sourceStr.includes('Transform') || sourceStr.includes('DataTransform')) source = 'dataTransform';
      else if (sourceStr.includes('class') || sourceStr.includes('Class')) source = 'class';
      else source = 'clipboard';

      const scopeStr = (pg.pyScope as string) || '';
      let scope: DeclarePageDefinition['scope'] | undefined;
      if (scopeStr === 'requestor' || scopeStr === 'thread' || scopeStr === 'node') {
        scope = scopeStr;
      }

      const parameters: Record<string, string> = {};
      if (pg.pyParameters && typeof pg.pyParameters === 'object') {
        for (const [k, v] of Object.entries(pg.pyParameters as Record<string, unknown>)) {
          parameters[k] = String(v);
        }
      }

      pages.push({
        name,
        source,
        sourceRef,
        parameters: Object.keys(parameters).length > 0 ? parameters : undefined,
        scope,
      });
    }

    return {
      pxObjClass: 'Rule-Declare-Pages',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-Pages',
      pages,
    };
  }

  /**
   * Parse a Declare Constraint rule.
   */
  public parseDeclareConstraint(json: Record<string, unknown>): PegaDeclareConstraint {
    const property = (json.pyProperty as string) || '';
    const constraintTypeStr = (json.pyConstraintType as string) || 'expression';
    const constraintValue = (json.pyConstraintValue as string) || (json.pyConstraintText as string) || '';
    const message = (json.pyMessage as string) || (json.pyConstraintMessage as string) || undefined;

    let constraintType: PegaDeclareConstraint['constraintType'] = 'expression';
    if (constraintTypeStr === 'min' || constraintTypeStr === 'Min') constraintType = 'min';
    else if (constraintTypeStr === 'max' || constraintTypeStr === 'Max') constraintType = 'max';
    else if (constraintTypeStr === 'pattern' || constraintTypeStr === 'Pattern' || constraintTypeStr === 'regex') constraintType = 'pattern';
    else if (constraintTypeStr === 'list' || constraintTypeStr === 'List') constraintType = 'list';

    return {
      pxObjClass: 'Rule-Declare-Constraints',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-Constraints',
      property,
      constraintType,
      constraintValue,
      message: message || undefined,
    };
  }

  /**
   * Parse a Declare Index rule.
   */
  public parseDeclareIndex(json: Record<string, unknown>): PegaDeclareIndex {
    const property = (json.pyProperty as string) || '';
    const indexTypeStr = (json.pyIndexType as string) || '';
    let indexType: PegaDeclareIndex['indexType'] | undefined;
    if (indexTypeStr === 'unique' || indexTypeStr === 'Unique') indexType = 'unique';
    else if (indexTypeStr === 'duplicate' || indexTypeStr === 'Duplicate') indexType = 'duplicate';
    else if (indexTypeStr === 'compound' || indexTypeStr === 'Compound') indexType = 'compound';

    const additionalProperties: string[] = [];
    const rawProps = Array.isArray(json.pyAdditionalProperties) ? json.pyAdditionalProperties : [];
    for (const raw of rawProps) {
      if (typeof raw === 'string') additionalProperties.push(raw);
    }

    return {
      pxObjClass: 'Rule-Declare-Index',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-Index',
      property,
      indexType,
      additionalProperties: additionalProperties.length > 0 ? additionalProperties : undefined,
    };
  }

  /**
   * Parse a Declare DecisionTable rule.
   */
  public parseDeclareDecisionTable(json: Record<string, unknown>): PegaDeclareDecisionTable {
    const propertyEvaluated = (json.pyPropertyEvaluated as string) || undefined;
    const rows: DeclareDecisionRow[] = [];
    const rawRows = Array.isArray(json.pyDecisionTableRows) ? json.pyDecisionTableRows : [];

    for (const raw of rawRows) {
      if (typeof raw !== 'object' || !raw) continue;
      const row = raw as Record<string, unknown>;
      rows.push({
        condition: (row.pyCondition as string) || '',
        result: (row.pyResult as string) || '',
      });
    }

    return {
      pxObjClass: 'Rule-Declare-DecisionTable',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-DecisionTable',
      propertyEvaluated,
      rows,
    };
  }

  /**
   * Parse a Declare DecisionTree rule.
   */
  public parseDeclareDecisionTree(json: Record<string, unknown>): PegaDeclareDecisionTree {
    const propertyEvaluated = (json.pyPropertyEvaluated as string) || undefined;
    const rows: DeclareDecisionRow[] = [];
    const rawRows = Array.isArray(json.pyDecisionTableRows) ? json.pyDecisionTableRows : [];

    for (const raw of rawRows) {
      if (typeof raw !== 'object' || !raw) continue;
      const row = raw as Record<string, unknown>;
      rows.push({
        condition: (row.pyCondition as string) || '',
        result: (row.pyResult as string) || '',
      });
    }

    return {
      pxObjClass: 'Rule-Declare-DecisionTree',
      pyName: (json.pyRuleName as string) || '',
      pyLabel: (json.pyLabel as string) || undefined,
      declareType: 'Declare-DecisionTree',
      propertyEvaluated,
      rows,
    };
  }

  /** Map DeclareOnChange action type to rule type for dependency tracking */
  private actionRuleType(type: DeclareOnChangeAction['type']): string {
    switch (type) {
      case 'runActivity': return 'Rule-Obj-Activity';
      case 'runDataTransform': return 'Rule-Obj-Model';
      case 'runReport': return 'Rule-Obj-Report';
      default: return 'Rule-Obj-Activity';
    }
  }
}

import { Worker } from 'worker_threads';
import * as path from 'path';
import * as url from 'url';

const __dirname = path.dirname(url.fileURLToPath(import.meta.url));

interface PoolWorker {
  worker: Worker;
  busy: boolean;
  id: number;
}

interface Task<T> {
  resolve: (value: T) => void;
  reject: (reason: unknown) => void;
  timeout: number;
  timer: NodeJS.Timeout | null;
}

export interface PoolStats {
  total: number;
  busy: number;
  idle: number;
  pendingTasks: number;
}

export class PegaWorkerPool {
  private workers: PoolWorker[] = [];
  private taskQueue: Array<{ data: unknown; task: Task<unknown> }> = [];
  private nextId = 0;

  constructor(size: number = 2) {
    for (let i = 0; i < size; i++) {
      this.addWorker();
    }
  }

  private addWorker(): void {
    const id = this.nextId++;
    const workerPath = path.join(__dirname, '..', 'security', 'worker-evaluator.js');
    try {
      const worker = new Worker(workerPath);
      const pw: PoolWorker = { worker, busy: false, id };

      worker.on('message', (msg) => {
        pw.busy = false;
        this.processQueue();
      });

      worker.on('error', (err) => {
        pw.busy = false;
        this.processQueue();
      });

      worker.on('exit', () => {
        pw.busy = false;
      });

      this.workers.push(pw);
    } catch {
      // Worker pool best-effort
    }
  }

  dispatch<T>(data: unknown, timeout: number = 5000): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const task: Task<T> = {
        resolve: resolve as (value: unknown) => void,
        reject,
        timeout,
        timer: null,
      };

      this.taskQueue.push({ data, task: task as Task<unknown> });
      this.processQueue();
    });
  }

  private processQueue(): void {
    if (this.taskQueue.length === 0) return;

    const worker = this.workers.find(w => !w.busy);
    if (!worker) return;

    const item = this.taskQueue.shift();
    if (!item) return;

    worker.busy = true;
    worker.worker.postMessage(item.data);
  }

  getStats(): PoolStats {
    return {
      total: this.workers.length,
      busy: this.workers.filter(w => w.busy).length,
      idle: this.workers.filter(w => !w.busy).length,
      pendingTasks: this.taskQueue.length,
    };
  }

  async terminate(): Promise<void> {
    for (const pw of this.workers) {
      await pw.worker.terminate();
    }
    this.workers = [];
    this.taskQueue = [];
  }
}

/**
 * PegaActivityRule — Đối tượng OOP chuyên biệt cho Rule-Obj-Activity.
