import { PegaRule } from './PegaRule.js';
import type { UnresolvedDependency } from '../models.js';
import type { UiStepAction } from '../PegaActionPlanGenerator.js';
import type { PegaRuleKbSchema } from '../strategies/KbDrivenPegaParserStrategy.js';

export class PegaGenericRule extends PegaRule {
  constructor(
    pxObjClass: string,
    pyClassName: string,
    pyRuleName: string,
    public readonly rawJson: Record<string, unknown>,
    public readonly schema?: PegaRuleKbSchema,
    pyRuleset?: string,
    pyRulesetVersion?: string,
  ) {
    super(pxObjClass, pyClassName, pyRuleName, pyRuleset, pyRulesetVersion);
  }

  public extractDependencies(): UnresolvedDependency[] {
    const deps: UnresolvedDependency[] = [];
    const paths = this.schema?.dependencyPaths || [];

    for (const pathStr of paths) {
      if (pathStr.includes('[].')) {
        const [arrayProp, targetProp] = pathStr.split('[].');
        const arr = Array.isArray(this.rawJson[arrayProp]) ? (this.rawJson[arrayProp] as any[]) : [];
        for (const item of arr) {
          if (item && typeof item === 'object' && typeof item[targetProp] === 'string' && item[targetProp].trim()) {
            deps.push({ ruleType: 'Unknown', className: this.pyClassName, ruleName: item[targetProp].trim() });
          }
        }
      } else if (typeof this.rawJson[pathStr] === 'string' && (this.rawJson[pathStr] as string).trim()) {
        deps.push({ ruleType: 'Unknown', className: this.pyClassName, ruleName: (this.rawJson[pathStr] as string).trim() });
      }
    }
    return deps;
  }

  public toStructuredPseudoCode(): string {
    return `${this.pxObjClass}: ${this.pyClassName}.${this.pyRuleName}`;
  }

  public generateUiAutomationPlan(): UiStepAction[] {
    return [];
  }
}

import { PegValue, PegExpressionError } from './PegaExpressionAst.js';

interface PageNode {
  name: string;
  properties: Map<string, PegValue>;
  pages: Map<string, PageNode>;
  parent?: PageNode;
}

export class PegaClipboardContext {
  private root: PageNode;

  constructor(
    private pages: Record<string, Record<string, unknown>> = {},
    private currentPageName: string = 'pyWorkPage',
  ) {
    this.root = { name: '__root__', properties: new Map(), pages: new Map() };
    this.loadPages();
  }

  private loadPages(): void {
    for (const [pageName, pageData] of Object.entries(this.pages)) {
      this.root.pages.set(pageName, this.buildPage(pageName, pageData, this.root));
    }
  }

  private buildPage(name: string, data: Record<string, unknown>, parent?: PageNode): PageNode {
    const properties = new Map<string, PegValue>();
    const childPages = new Map<string, PageNode>();

    for (const [key, val] of Object.entries(data)) {
      if (val && typeof val === 'object' && !Array.isArray(val) && !('type' in (val as any))) {
        const childPage = this.buildPage(key, val as Record<string, unknown>);
        childPage.parent = parent;
        childPages.set(key, childPage);
      } else if (val && typeof val === 'object' && 'type' in (val as any) && 'value' in (val as any)) {
        const tv = val as { type: string; value: unknown };
        properties.set(key, new PegValue(tv.type as any, tv.value));
      } else if (typeof val === 'string') {
        properties.set(key, PegValue.text(val));
      } else if (typeof val === 'number') {
        properties.set(key, PegValue.number(val));
      } else if (typeof val === 'boolean') {
        properties.set(key, PegValue.bool(val));
      } else if (val === null || val === undefined) {
        properties.set(key, PegValue.null());
      }
    }

    return { name, properties, pages: childPages, parent };
  }

  resolve(parts: string[]): PegValue {
    if (parts.length === 0) {
      throw new PegExpressionError('Empty property reference', 'PROPERTY_NOT_FOUND');
    }

    if (parts.length === 1) {
      return this.resolveRelative(parts[0]);
    }

    const pageName = parts[0];
    const page = this.findPage(pageName);
    if (!page) {
      throw new PegExpressionError(
        "Page '" + pageName + "' not found in clipboard context",
        'PROPERTY_NOT_FOUND',
      );
    }

    let current: PageNode = page;
    for (let i = 1; i < parts.length; i++) {
      const part = parts[i];
      if (i === parts.length - 1) {
        const prop = current.properties.get(part);
        if (prop) return prop;
        throw new PegExpressionError(
          "Property '" + parts.slice(0, i + 1).join('.') + "' not found in clipboard",
          'PROPERTY_NOT_FOUND',
        );
      }
      const childPage = current.pages.get(part);
      if (childPage) {
        current = childPage;
      } else {
        throw new PegExpressionError(
          "Page '" + parts.slice(0, i + 1).join('.') + "' not found in clipboard",
          'PROPERTY_NOT_FOUND',
        );
      }
    }

    return PegValue.page(current.name, this);
  }

  private resolveRelative(propName: string): PegValue {
    const currentPage = this.root.pages.get(this.currentPageName);
    if (!currentPage) {
      throw new PegExpressionError(
        "Current page '" + this.currentPageName + "' not found in clipboard",
        'PROPERTY_NOT_FOUND',
      );
    }

    const prop = currentPage.properties.get(propName);
    if (prop) return prop;

    const childPage = currentPage.pages.get(propName);
    if (childPage) return PegValue.page(childPage.name, this);

    throw new PegExpressionError(
      "Property '" + propName + "' not found in clipboard (current page: " + this.currentPageName + ")",
      'PROPERTY_NOT_FOUND',
    );
  }

  private findPage(name: string): PageNode | undefined {
    const page = this.root.pages.get(name);
    if (page) return page;
    for (const [, p] of this.root.pages) {
      const found = this.findPageInTree(p, name);
      if (found) return found;
    }
    return undefined;
  }

  private findPageInTree(node: PageNode, name: string): PageNode | undefined {
    if (node.name === name) return node;
    for (const [, child] of node.pages) {
      const found = this.findPageInTree(child, name);
      if (found) return found;
    }
    return undefined;
  }

  setCurrentPage(name: string): void {
    this.currentPageName = name;
  }

  getCurrentPageName(): string {
    return this.currentPageName;
  }
}

import { PegExpressionError } from './PegaExpressionAst.js';
import type { ExpressionAstNode, BinaryOperator } from './PegaExpressionAst.js';
import {
  PropertyRefNode,
  FunctionCallNode,
  StringLiteralNode,
  NumberLiteralNode,
  BooleanLiteralNode,
  NullLiteralNode,
  BinaryOpNode,
  UnaryOpNode,
} from './PegaExpressionAst.js';
import { PegaExpressionLexer } from './PegaExpressionLexer.js';
import type { Token, TokenType } from './PegaExpressionLexer.js';

const COMPARISON_OPS: Array<{ token: TokenType; op: BinaryOperator }> = [
  { token: 'EQ', op: 'EQ' },
  { token: 'NEQ', op: 'NEQ' },
  { token: 'GT', op: 'GT' },
  { token: 'LT', op: 'LT' },
  { token: 'GTE', op: 'GTE' },
  { token: 'LTE', op: 'LTE' },
];

export class PegaExpressionParser {
  private tokens: Token[] = [];
  private pos = 0;

  parse(input: string): ExpressionAstNode {
    const lexer = new PegaExpressionLexer(input);
    this.tokens = lexer.tokenize();
    this.pos = 0;
    const result = this.parseOr();
    if (this.peek().type !== 'EOF') {
      const t = this.peek();
      throw new PegExpressionError(
        'Expected end of expression at line ' + t.line + ', column ' + t.column,
        'PARSE_ERROR',
        t.line, t.column,
      );
    }
    return result;
  }

  private parseOr(): ExpressionAstNode {
    let left = this.parseAnd();
    while (this.match('OR')) {
      const right = this.parseAnd();
      left = new BinaryOpNode('OR', left, right);
    }
    return left;
  }

  private parseAnd(): ExpressionAstNode {
    let left = this.parseNot();
    while (this.match('AND')) {
      const right = this.parseNot();
      left = new BinaryOpNode('AND', left, right);
    }
    return left;
  }

  private parseNot(): ExpressionAstNode {
    if (this.match('NOT')) {
      const operand = this.parseNot();
      return new UnaryOpNode('NOT', operand);
    }
    if (this.match('ISNULL')) {
      const operand = this.parseComparison();
      return new UnaryOpNode('ISNULL', operand);
    }
    return this.parseComparison();
  }

  private parseComparison(): ExpressionAstNode {
    const left = this.parseValue();

    for (const ct of COMPARISON_OPS) {
      if (this.match(ct.token)) {
        const right = this.parseValue();
        return new BinaryOpNode(ct.op, left, right);
      }
    }

    return left;
  }

  private parseValue(): ExpressionAstNode {
    const token = this.peek();

    if (token.type === 'LPAREN') {
      this.advance();
      const expr = this.parseOr();
      this.expect('RPAREN');
      return expr;
    }

    if (token.type === 'STRING') {
      this.advance();
      return new StringLiteralNode(token.value);
    }

    if (token.type === 'NUMBER') {
      this.advance();
      return new NumberLiteralNode(parseFloat(token.value));
    }

    if (token.type === 'IDENTIFIER' && (token.value === 'true' || token.value === 'false')) {
      this.advance();
      return new BooleanLiteralNode(token.value === 'true');
    }

    if (token.type === 'FUNCTION') {
      return this.parseFunctionCall();
    }

    if (token.type === 'DOT') {
      return this.parsePropertyRef();
    }

    if (token.type === 'IDENTIFIER') {
      return this.parsePropertyRefFromIdent();
    }

    throw new PegExpressionError(
      'Expected expression at line ' + token.line + ', column ' + token.column + ", got '" + token.value + "'",
      'PARSE_ERROR',
      token.line, token.column,
    );
  }

  private parseFunctionCall(): ExpressionAstNode {
    const token = this.expect('FUNCTION');
    this.expect('LPAREN');
    const args: ExpressionAstNode[] = [];

    if (this.peek().type !== 'RPAREN') {
      args.push(this.parseOr());
      while (this.match('COMMA')) {
        args.push(this.parseOr());
      }
    }

    this.expect('RPAREN');
    return new FunctionCallNode(token.value, args);
  }

  private parsePropertyRef(): ExpressionAstNode {
    const parts: string[] = [];
    this.expect('DOT');
    const ident = this.expect('IDENTIFIER');
    parts.push(ident.value);

    while (this.peek().type === 'DOT') {
      this.advance();
      const next = this.expect('IDENTIFIER');
      parts.push(next.value);
    }

    return new PropertyRefNode(parts);
  }

  private parsePropertyRefFromIdent(): ExpressionAstNode {
    const parts: string[] = [];
    const ident = this.expect('IDENTIFIER');
    parts.push(ident.value);

    while (this.peek().type === 'DOT') {
      this.advance();
      const next = this.expect('IDENTIFIER');
      parts.push(next.value);
    }

    return new PropertyRefNode(parts);
  }

  private peek(): Token {
    return this.tokens[this.pos];
  }

  private advance(): Token {
    return this.tokens[this.pos++];
  }

  private match(type: TokenType): boolean {
    if (this.peek().type === type) {
      this.advance();
      return true;
    }
    return false;
  }

  private expect(type: TokenType): Token {
    const token = this.peek();
    if (token.type !== type) {
      throw new PegExpressionError(
        'Expected ' + type + ' at line ' + token.line + ', column ' + token.column + ", got '" + token.value + "'",
        'PARSE_ERROR',
        token.line, token.column,
      );
    }
    return this.advance();
  }
}

import { PegaExpressionParser } from './PegaExpressionParser.js';
import { PegaClipboardContext } from './PegaClipboardContext.js';
import { PegaExpressionEvaluator } from './PegaExpressionEvaluator.js';

export interface WhenConditionResult {
  passed: boolean;
  trace: string[];
}

export class PegaWhenEvaluator {
  private evaluator = new PegaExpressionEvaluator();
  private parser = new PegaExpressionParser();

  evaluateWhen(
    whenExpression: string,
    clipboard: PegaClipboardContext,
  ): WhenConditionResult {
    const trace: string[] = [];
    trace.push(`Evaluating When: ${whenExpression}`);

    try {
      const result = this.evaluator.evaluate(whenExpression, clipboard, true);
      const passed = result.value.boolean;
      trace.push(`→ ${passed ? 'PASS' : 'FAIL'}`);

      return { passed, trace };
    } catch (err) {
      trace.push(`→ ERROR: ${(err as Error).message}`);
      return { passed: false, trace };
    }
  }

  evaluateWhenFromConditionText(
    conditionText: string,
    clipboard: PegaClipboardContext,
  ): WhenConditionResult {
    const expression = this.convertConditionToExpression(conditionText);
    return this.evaluateWhen(expression, clipboard);
  }

  private convertConditionToExpression(conditionText: string): string {
    let expr = conditionText.trim();

    if (expr.includes('.AND.')) {
      const parts = expr.split('.AND.').map(p => p.trim());
      const converted = parts.map(p => this.convertConditionToExpression(p));
      return `(${converted.join(') .AND. (')})`;
    }

    if (expr.includes('.OR.')) {
      const parts = expr.split('.OR.').map(p => p.trim());
      const converted = parts.map(p => this.convertConditionToExpression(p));
      return `(${converted.join(') .OR. (')})`;
    }

    const operators = ['=', '<>', '>', '<', '>=', '<='];
    for (const op of operators) {
      const idx = expr.indexOf(op);
      if (idx > 0) {
        const left = expr.substring(0, idx).trim();
        const right = expr.substring(idx + op.length).trim();
        const formattedLeft = left.startsWith('.') ? left : `.${left}`;
        let formattedRight = right;
        if (!right.startsWith('"') && !right.startsWith("'") && !/^-?\d/.test(right) && !right.startsWith('@')) {
          formattedRight = `"${right}"`;
        }
        return `${formattedLeft} ${op} ${formattedRight}`;
      }
    }

    if (expr.includes('.')) {
      return expr.startsWith('.') ? expr : `.${expr}`;
    }

    return expr;
  }
}

/**
 * PegaMetaModelCompiler — Generates IPegaRuleParserStrategy instances
 * from PegaClassDefinition schemas at runtime (dynamic, not code-gen).
 *
 * Each compiled strategy knows its class definition, supports inheritance-based
 * matching, and extracts properties/children/dependencies automatically.
 */

import type { PegaClassDefinition, PegaPropertyDef, PegaChildDef } from './PegaClassDefinition.js';
import type { PegaMetaModelRegistry } from './PegaMetaModelRegistry.js';
import type { IPegaRuleParserStrategy, ParseResult } from '../strategies/IPegaRuleParserStrategy.js';
import type { UnresolvedDependency } from '../models.js';
import type { PegaParserRegistry } from '../strategies/PegaParserRegistry.js';

/**
 * Compiled strategy that wraps a PegaClassDefinition and uses the registry
 * for inheritance resolution.
 */
class CompiledPegaRuleParserStrategy implements IPegaRuleParserStrategy {
  constructor(
    private readonly classDef: PegaClassDefinition,
    private readonly compiler: PegaMetaModelCompiler,
    private readonly registry: PegaMetaModelRegistry,
  ) {}

  /**
   * Check whether this strategy supports the given pxObjClass.
   *
   * Matching rules:
   * 1. Exact match on pxObjClass
   * 2. @baseclass supports everything
   * 3. Classes ending with '-' (base categories) support any subclass by prefix
   * 4. Full inheritance check via the registry
   */
  public supports(pxObjClass: string): boolean {
    if (pxObjClass === this.classDef.pxObjClass) return true;
    if (this.classDef.pxObjClass === '@baseclass') return true;

    // Base-category classes ending with '-' support prefix match
    if (this.classDef.pxObjClass.endsWith('-')) {
      if (pxObjClass.startsWith(this.classDef.pxObjClass)) return true;
    }

    // Full inheritance chain check
    return this.compiler.isDerivedFrom(pxObjClass, this.classDef.pxObjClass);
  }

  /**
   * Parse a raw JSON object into a ParseResult.
   * Extracts the symbol (name, class, type), detects references as dependencies,
   * and records all properties per the class definition.
   */
  public parse(json: Record<string, unknown>): ParseResult {
    const pxObjClass = (json.pxObjClass as string) || this.classDef.pxObjClass;
    const className = (json.pyClassName as string) || (json.className as string) || '@baseclass';
    const name = this.extractName(json);
    const fqn = `${pxObjClass}:${className}:${name}`;

    const symbol = {
      fqn,
      name,
      className,
      ruleType: pxObjClass,
      isRule: pxObjClass.startsWith('Rule-'),
      ruleset: (json.pyRuleset as string) || undefined,
      version: (json.pyRulesetVersion as string) || undefined,
      logicSummary: this.buildLogicSummary(json),
    };

    const dependencies = this.extractDependencies(json, className);

    return { symbol, dependencies };
  }

  private extractName(json: Record<string, unknown>): string {
    const candidates = ['pyRuleName', 'pyActivityName', 'pyModelName', 'pyTransformName',
      'pyFlowName', 'pyServiceRuleName', 'pyServiceName', 'pyLabel', 'pyName'];
    for (const key of candidates) {
      const val = json[key];
      if (typeof val === 'string' && val.trim()) return val.trim();
    }
    return 'Unnamed';
  }

  private extractDependencies(json: Record<string, unknown>, className: string): UnresolvedDependency[] {
    const deps: UnresolvedDependency[] = [];
    const visited = new Set<string>();

    // 1. Extract from classDef properties marked as isReference
    for (const prop of this.classDef.properties) {
      if (!prop.isReference) continue;
      const val = json[prop.name];
      if (typeof val !== 'string' || !val.trim()) continue;
      const key = `${prop.name}:${val}`;
      if (visited.has(key)) continue;
      visited.add(key);
      const ruleType = this.inferRuleType(prop.name, val, json);
      deps.push({ ruleType, className, ruleName: val.trim() });
    }

    // 2. Detect additional reference fields by naming convention
    //    Fields ending in reference-like suffixes that aren't already captured
    const referenceSuffixes = ['Name', 'Class', 'Profile', 'Transform', 'Condition', 'From', 'Evaluated', 'Trigger', 'Action', 'Target', 'Source', 'Expression'];
    for (const [key, val] of Object.entries(json)) {
      if (typeof val !== 'string' || !val.trim()) continue;
      if (key === 'pxObjClass' || key === 'pyClassName' || key === 'pyRuleName') continue;
      if (key === 'pyRuleset' || key === 'pyRulesetVersion' || key === 'pyRuleSet' || key === 'pyRuleSetVersion') continue;

      const hasRefSuffix = referenceSuffixes.some(s => key.endsWith(s));
      if (!hasRefSuffix) continue;

      // Skip if already captured as isReference property
      if (this.classDef.properties.some(p => p.name === key && p.isReference)) continue;

      const depKey = `${key}:${val}`;
      if (visited.has(depKey)) continue;
      visited.add(depKey);

      const ruleType = this.inferRuleType(key, val, json);
      deps.push({ ruleType, className, ruleName: val.trim() });
    }

    return deps;
  }

  private inferRuleType(fieldName: string, fieldValue: string, _json?: Record<string, unknown>): string {
    // Map known reference fields to rule types
    if (fieldName === 'pyAuthProfile') return 'Rule-Connect-AuthProfile';
    if (fieldName === 'pyRequestDataTransform' || fieldName === 'pyResponseDataTransform') return 'Rule-Obj-Model';
    if (fieldName === 'pyWhenCondition') return 'Rule-Obj-When';
    if (fieldName === 'pyOnChangeTrigger') return 'Rule-Obj-When';
    if (fieldName === 'pyFlowActionName') return 'Rule-Obj-FlowAction';
    if (fieldName === 'pySuperClass' || fieldName === 'pyDerivesFrom' || fieldName === 'pyPatternParent') return 'Rule-Obj-Class';
    if (fieldName === 'pyTransformName') return 'Rule-Obj-Model';
    if (fieldName === 'pyActivityName') return 'Rule-Obj-Activity';
    if (fieldName === 'pyFlowName') return 'Rule-Obj-Flow';
    if (fieldName === 'pyPropertyName') return 'Rule-Obj-Property';
    if (fieldName === 'pyPropertyEvaluated') return 'Rule-Obj-Property';
    if (fieldName === 'pyMethodParameters') return 'Rule-Obj-Activity';

    // Generic detection from value pattern
    if (fieldValue.includes('.') && fieldName.includes('Method')) return 'Rule-Obj-Activity';
    if (fieldName.endsWith('Transform')) return 'Rule-Obj-Model';
    if (fieldName.endsWith('Class')) return 'Rule-Obj-Class';
    if (fieldName.endsWith('Profile')) return 'Rule-Connect-AuthProfile';
    if (fieldName.endsWith('Condition')) return 'Rule-Obj-When';
    if (fieldName.endsWith('From')) return 'Rule-Obj-Class';
    if (fieldName.endsWith('Evaluated')) return 'Rule-Obj-Property';
    if (fieldName.endsWith('Trigger')) return 'Rule-Obj-When';
    if (fieldName.endsWith('Action')) return 'Rule-Obj-FlowAction';
    if (fieldName.endsWith('Target')) return 'Rule-Obj-Model';
    if (fieldName.endsWith('Source')) return 'Rule-Obj-Class';
    if (fieldName.endsWith('Expression')) return 'Rule-Obj-Model';
    if (fieldName.endsWith('Name')) return 'Rule-Obj-Activity';

    return 'Rule-Obj-Activity';
  }

  private buildLogicSummary(json: Record<string, unknown>): string | undefined {
    const name = this.extractName(json);
    const cls = this.classDef;
    const lines: string[] = [];
    lines.push(`${cls.pxObjClass}: ${name}`);

    // Add key fields based on classDef meta
    for (const prop of cls.properties.slice(0, 6)) {
      const val = json[prop.name];
      if (val !== undefined && val !== null && val !== '') {
        lines.push(`  ${prop.name}: ${String(val)}`);
      }
    }

    // Count children
    let childCount = 0;
    for (const child of cls.children) {
      const arr = json[child.name];
      if (Array.isArray(arr)) childCount += arr.length;
    }

    if (childCount > 0) {
      lines.push(`  Children: ${childCount} item(s) across ${cls.children.length} array(s)`);
    }

    return lines.join('\n');
  }
}

export class PegaMetaModelCompiler {
  private registry: PegaMetaModelRegistry;
  private compiled: Map<string, CompiledPegaRuleParserStrategy> = new Map();
  private hierarchyCache: Map<string, Set<string>> = new Map();

  constructor(registry: PegaMetaModelRegistry) {
    this.registry = registry;
  }

  /**
   * Generate a strategy for a single class definition.
   * The strategy will match the exact class and any subclasses.
   */
  public compileStrategy(classDef: PegaClassDefinition): IPegaRuleParserStrategy {
    const existing = this.compiled.get(classDef.pxObjClass);
    if (existing) return existing;

    const strategy = new CompiledPegaRuleParserStrategy(classDef, this, this.registry);
    this.compiled.set(classDef.pxObjClass, strategy);
    return strategy;
  }

  /**
   * Compile ALL registered classes into strategies.
   * Returns strategies ordered from most concrete to most generic
   * so the most specific match is found first.
   */
  public compileAll(): IPegaRuleParserStrategy[] {
    // Build inheritance depth map for ordering
    const depthMap = new Map<string, number>();

    const computeDepth = (pxObjClass: string): number => {
      const cached = depthMap.get(pxObjClass);
      if (cached !== undefined) return cached;
      const def = this.registry.getParser(pxObjClass);
      if (!def || !def.baseClass) {
        depthMap.set(pxObjClass, 0);
        return 0;
      }
      const depth = computeDepth(def.baseClass) + 1;
      depthMap.set(pxObjClass, depth);
      return depth;
    };

    // Get all classes sorted by inheritance depth (deepest first = most specific first)
    const classes = this.registry.getKnownClasses();

    for (const cls of classes) {
      computeDepth(cls);
    }

    // Sort by depth descending so concrete classes compile first
    const sorted = [...classes].sort((a, b) => (depthMap.get(b) || 0) - (depthMap.get(a) || 0));

    const strategies: IPegaRuleParserStrategy[] = [];
    for (const cls of sorted) {
      const def = this.registry.getParser(cls);
      if (def) {
        strategies.push(this.compileStrategy(def));
      }
    }

    return strategies;
  }

  /**
   * Get a compiled strategy for a specific pxObjClass.
   */
  public getStrategy(pxObjClass: string): IPegaRuleParserStrategy | undefined {
    return this.compiled.get(pxObjClass);
  }

  /**
   * Register all compiled strategies into a PegaParserRegistry.
   * More specific strategies are registered before generic ones.
   */
  public registerAll(parserRegistry: PegaParserRegistry): void {
    // Get all compiled strategies sorted by specificity
    const all = this.compileAll();

    // Register generic base classes first (they'll end up last via unshift),
    // concrete classes last (they'll end up first, matching first)
    const sorted = this.sortByInheritanceDepth(all);

    for (const strategy of sorted) {
      parserRegistry.registerStrategy(strategy);
    }
  }

  /**
   * Check if a given pxObjClass derives from a potential base class.
   * Uses the registry for class definition lookup and follows the baseClass chain.
   */
  public isDerivedFrom(pxObjClass: string, potentialBaseClass: string): boolean {
    if (pxObjClass === potentialBaseClass) return true;
    if (potentialBaseClass === '@baseclass') return true;

    // Build cached ancestry for the class
    let ancestors = this.hierarchyCache.get(pxObjClass);
    if (!ancestors) {
      ancestors = this.buildAncestors(pxObjClass);
      this.hierarchyCache.set(pxObjClass, ancestors);
    }

    return ancestors.has(potentialBaseClass);
  }

  private buildAncestors(pxObjClass: string): Set<string> {
    const ancestors = new Set<string>();
    if (pxObjClass === '@baseclass') {
      ancestors.add('@baseclass');
      return ancestors;
    }

    let current = pxObjClass;
    for (let i = 0; i < 20; i++) {
      const def = this.registry.getParser(current);
      if (!def || !def.baseClass) break;
      ancestors.add(def.baseClass);
      current = def.baseClass;
    }

    // Add @baseclass implicitly
    if (pxObjClass !== '@baseclass') {
      ancestors.add('@baseclass');
    }

    return ancestors;
  }

  private sortByInheritanceDepth(strategies: IPegaRuleParserStrategy[]): CompiledPegaRuleParserStrategy[] {
    const compiled = strategies as CompiledPegaRuleParserStrategy[];

    const getDepth = (strategy: CompiledPegaRuleParserStrategy): number => {
      const def = (strategy as any).classDef as PegaClassDefinition;
      let depth = 0;
      let current = def.baseClass;
      while (current) {
        depth++;
        const parentDef = this.registry.getParser(current);
        if (!parentDef || !parentDef.baseClass) break;
        current = parentDef.baseClass;
      }
      return depth;
    };

    // Sort by depth ascending (generic first) so unshift puts specific first
    return [...compiled].sort((a, b) => getDepth(a) - getDepth(b));
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import type { PegaClassDefinition, PegaPropertyDef, PegaChildDef } from './PegaClassDefinition.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const SYSTEM_FIELD_PREFIXES = ['pxCreate', 'pxUpdate', 'pxInstance', 'pxHost', 'pxMove', 'pxSibling',
  'pxLimitedAccess', 'pzChecksum', 'pzIndex', 'pzReindex', 'pzOriginal',
  'pxAllChangeList', 'pxWarnings', 'pxNamedPageReferences', 'pxAPIMethodReferences'];

const SYSTEM_FIELDS = new Set(['pxObjClass', 'pyClassName', 'pyRuleName', 'pyRuleset', 'pyRulesetVersion',
  'pyInsKey', 'pzInsKey', 'pxInsId', 'pxInsName',
  'pyRuleAvailable', 'pyModelName', 'pyActivityName',
  'pyTransformName', 'pyUserIdentifier', 'pyAccessGroup',
  'pyRuleSet', 'pyRuleSetVersion']);

const REFERENCE_FIELD_NAMES = new Set([
  'pyClassName', 'pySuperClass', 'pyPatternParent', 'pyDerivesFrom',
  'pyRuleName', 'pyModelName', 'pyActivityName', 'pyTransformName',
  'pyWhenCondition', 'pyOnChangeTrigger', 'pyFlowActionName',
  'pyFlowName', 'pyBlockName', 'pyPropertyName', 'pyMethodParameters',
]);

export class PegaMetaModelLoader {
  private registry: Map<string, PegaClassDefinition>;

  constructor() {
    this.registry = new Map();
  }

  public async loadSchemaDirectory(schemaDir?: string): Promise<Map<string, PegaClassDefinition>> {
    const dir = schemaDir || path.resolve(__dirname, '../schemas');
    this.registry = new Map();
    await this.scanDirectory(dir);
    this.resolveInheritance();
    return this.registry;
  }

  public loadSchemaFile(filePath: string): PegaClassDefinition | null {
    try {
      const raw = fs.readFileSync(filePath, 'utf-8');
      const parsed = JSON.parse(raw);
      return this.parseClassDefinition(parsed, path.basename(filePath));
    } catch {
      return null;
    }
  }

  public resolveInheritance(): void {
    const resolved = new Set<string>();

    const resolve = (className: string): PegaClassDefinition | undefined => {
      if (resolved.has(className)) return this.registry.get(className);
      const def = this.registry.get(className);
      if (!def) return undefined;
      if (def.baseClass && def.baseClass.length > 0) {
        const parentDef = resolve(def.baseClass);
        if (parentDef) {
          const mergedProps = this.mergeProperties(parentDef.properties, def.properties);
          const mergedChildren = this.mergeChildren(parentDef.children, def.children);
          def.properties = mergedProps;
          def.children = mergedChildren;
        }
      }
      resolved.add(className);
      return def;
    };

    for (const className of this.registry.keys()) {
      resolve(className);
    }
  }

  public registerClass(def: PegaClassDefinition): void {
    this.registry.set(def.pxObjClass, def);
  }

  public getClass(pxObjClass: string): PegaClassDefinition | undefined {
    return this.registry.get(pxObjClass);
  }

  public getAllClasses(): PegaClassDefinition[] {
    return Array.from(this.registry.values());
  }

  private async scanDirectory(dir: string): Promise<void> {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await this.scanDirectory(fullPath);
      } else if (entry.isFile() && entry.name.endsWith('.json')) {
        const def = this.loadSchemaFile(fullPath);
        if (def) {
          const key = def.pxObjClass;
          if (!this.registry.has(key) || this.isRicherClassFile(entry.name)) {
            this.registry.set(key, def);
          }
        }
      }
    }
  }

  private isRicherClassFile(filename: string): boolean {
    return filename === '@baseclass.json' || filename.startsWith('Rule-') && filename.indexOf('.') === filename.lastIndexOf('.');
  }

  private parseClassDefinition(json: Record<string, unknown>, filename: string): PegaClassDefinition | null {
    if (!json || typeof json !== 'object') return null;

    let pxObjClass = '';
    let baseClass: string | undefined;
    let description: string | undefined;
    let label: string | undefined;

    if (json.pxObjClass === 'Rule-Obj-Class' && json.pyClassName) {
      pxObjClass = json.pyClassName as string;
      baseClass = (json.pyDerivesFrom as string) || (json.pySuperClass as string) || undefined;
      if (baseClass && baseClass.length === 0) baseClass = undefined;
      description = (json.pyDescription as string) || undefined;
      label = (json.pyLabel as string) || undefined;
    } else if (json.targetClass) {
      pxObjClass = json.targetClass as string;
      description = (json.description as string) || undefined;
    } else {
      return null;
    }

    const properties = this.extractProperties(json);
    const children = this.extractChildren(json);

    return { pxObjClass, baseClass, properties, children, description, label };
  }

  private extractProperties(json: Record<string, unknown>): PegaPropertyDef[] {
    const props: PegaPropertyDef[] = [];
    const visited = new Set<string>();

    for (const [key, val] of Object.entries(json)) {
      if (visited.has(key)) continue;
      visited.add(key);
      if (key === 'pxObjClass' || key === 'pyKeyDefList' || key === 'pxRuleReferences') continue;
      if (key === 'pxAllChangeList' || key === 'pxWarnings' || key === 'pxAPIMethodReferences' || key === 'pxNamedPageReferences') continue;

      const isSystem = SYSTEM_FIELD_PREFIXES.some(p => key.startsWith(p)) || key.startsWith('pz');
      const isReference = REFERENCE_FIELD_NAMES.has(key) || key.endsWith('Name') || key.endsWith('Class') || key === 'pxObjClass';
      const type = this.inferType(val, key);
      const required = key === 'pxObjClass' || key === 'pyClassName' || key === 'pyRuleName';

      if ((type as string) === 'object' || Array.isArray(val)) continue;

      props.push({ name: key, type, required, isSystem, isReference, description: undefined });
    }

    return props;
  }

  private extractChildren(json: Record<string, unknown>): PegaChildDef[] {
    const children: PegaChildDef[] = [];
    const skipArrays = new Set(['pxAllChangeList', 'pxWarnings', 'pxAPIMethodReferences', 'pxNamedPageReferences']);

    for (const [key, val] of Object.entries(json)) {
      if (skipArrays.has(key)) continue;
      if (key === 'pyKeyDefList' || key === 'pxRuleReferences') continue;
      if (!Array.isArray(val) || val.length === 0) continue;

      const firstItem = val[0];
      if (!firstItem || typeof firstItem !== 'object') continue;

      const itemType = (firstItem as Record<string, unknown>).pxObjClass as string || 'Embedded';
      children.push({
        name: key,
        childType: itemType,
        arrayType: 'array',
        description: undefined,
      });
    }

    const keyDefList = json.pyKeyDefList;
    if (Array.isArray(keyDefList) && keyDefList.length > 0) {
      children.push({
        name: 'pyKeyDefList',
        childType: 'Embed-ClassKeys',
        arrayType: 'array',
        description: 'Key definitions for the class',
      });
    }

    const pxRuleRefs = json.pxRuleReferences;
    if (Array.isArray(pxRuleRefs) && pxRuleRefs.length > 0) {
      children.push({
        name: 'pxRuleReferences',
        childType: 'Embed-Reference-Rule',
        arrayType: 'array',
        description: 'Rule references',
      });
    }

    return children;
  }

  private inferType(val: unknown, key: string): PegaPropertyDef['type'] {
    if (typeof val === 'number') return 'number';
    if (typeof val === 'boolean') return 'boolean';
    if (typeof val === 'string') {
      if (REFERENCE_FIELD_NAMES.has(key) || key.endsWith('Name') || key.endsWith('Class') || key === 'pxObjClass') {
        return 'ref';
      }
      return 'string';
    }
    return 'string';
  }

  private mergeProperties(parent: PegaPropertyDef[], child: PegaPropertyDef[]): PegaPropertyDef[] {
    const childNames = new Set(child.map(p => p.name));
    const merged = [...child];
    for (const prop of parent) {
      if (!childNames.has(prop.name)) {
        merged.push(prop);
      }
    }
    return merged;
  }

  private mergeChildren(parent: PegaChildDef[], child: PegaChildDef[]): PegaChildDef[] {
    const childNames = new Set(child.map(c => c.name));
    const merged = [...child];
    for (const c of parent) {
      if (!childNames.has(c.name)) {
        merged.push(c);
      }
    }
    return merged;
  }
}

import type { DependencyGraph, DependencyNode, DependencyEdge } from './PegaReferenceExtractor.js';
import { PegaReferenceExtractor } from './PegaReferenceExtractor.js';

export interface ImpactAnalysis {
  ruleName: string;
  ruleType: string;
  directDependents: string[];
  indirectDependents: string[];
  impactScope: 'local' | 'module' | 'crossModule' | 'system';
  risk: 'low' | 'medium' | 'high';
  suggestedTests: string[];
}

export class PegaImpactAnalyzer {
  private extractor: PegaReferenceExtractor;

  constructor(extractor: PegaReferenceExtractor) {
    this.extractor = extractor;
  }

  public analyzeChange(ruleName: string, graph: DependencyGraph): ImpactAnalysis {
    const targetNodes = graph.nodes.filter(n => n.name === ruleName);
    if (targetNodes.length === 0) {
      return {
        ruleName,
        ruleType: 'Unknown',
        directDependents: [],
        indirectDependents: [],
        impactScope: 'local',
        risk: 'low',
        suggestedTests: [],
      };
    }

    const directDependents: string[] = [];
    const allDependents: string[] = [];
    const visited = new Set<string>();

    // Collect direct dependents
    for (const target of targetNodes) {
      const direct = this.extractor.getDependents(target.name, graph);
      for (const d of direct) {
        if (!directDependents.includes(d)) {
          directDependents.push(d);
        }
      }

      // Collect all transitives
      const all = this.extractor.getAllDependents(target.fqn, graph);
      for (const a of all) {
        if (!allDependents.includes(a)) {
          allDependents.push(a);
        }
      }
    }

    const indirectDependents = allDependents.filter(d => !directDependents.includes(d));

    // Determine impact scope
    const impactScope = this.determineScope(targetNodes, graph, allDependents);

    // Determine risk level
    const risk = this.determineRisk(targetNodes, allDependents, impactScope);

    // Generate test suggestions
    const suggestedTests = this.suggestTests(
      {
        ruleName,
        ruleType: targetNodes[0].type,
        directDependents,
        indirectDependents,
        impactScope,
        risk,
        suggestedTests: [],
      },
      graph.nodes.map(n => n.name),
    );

    return {
      ruleName,
      ruleType: targetNodes[0].type,
      directDependents,
      indirectDependents,
      impactScope,
      risk,
      suggestedTests,
    };
  }

  public analyzeBatch(changes: string[], graph: DependencyGraph): Map<string, ImpactAnalysis> {
    const results = new Map<string, ImpactAnalysis>();
    for (const ruleName of changes) {
      results.set(ruleName, this.analyzeChange(ruleName, graph));
    }
    return results;
  }

  public suggestTests(analysis: ImpactAnalysis, allRules: string[]): string[] {
    const tests: string[] = [];

    if (analysis.risk === 'high') {
      tests.push(`Full regression for all rules affected by ${analysis.ruleName}`);
      tests.push(`Integration test: ${analysis.ruleName} interactions`);
    }

    if (analysis.directDependents.length > 0) {
      tests.push(`Unit test: ${analysis.ruleName} direct dependents (${analysis.directDependents.slice(0, 5).join(', ')})`);
    }

    if (analysis.indirectDependents.length > 0) {
      tests.push(`Integration test: ${analysis.ruleName} transitive paths`);
    }

    if (analysis.impactScope === 'crossModule' || analysis.impactScope === 'system') {
      tests.push(`E2E test: flows involving ${analysis.ruleName}`);
    }

    // Specific test patterns based on rule type
    const ruleType = analysis.ruleType;
    if (ruleType === 'Rule-Obj-Activity') {
      tests.push(`Activity test: ${analysis.ruleName} step execution`);
    } else if (ruleType === 'Rule-Obj-Model') {
      tests.push(`DataTransform test: ${analysis.ruleName} mapping results`);
    } else if (ruleType === 'Rule-Obj-When') {
      tests.push(`When condition test: ${analysis.ruleName} evaluates correctly`);
    } else if (ruleType.startsWith('Rule-Connect-')) {
      tests.push(`Connect test: ${analysis.ruleName} endpoint reachable`);
    } else if (ruleType.startsWith('Rule-Decision-')) {
      tests.push(`Decision test: ${analysis.ruleName} strategy outcomes`);
    }

    return tests;
  }

  public toDot(graph: DependencyGraph): string {
    const lines: string[] = [];
    lines.push('digraph PegaDependencies {');
    lines.push('  rankdir=LR;');
    lines.push('  node [shape=box, style=rounded, fontname="Courier New"];');
    lines.push('  edge [fontname="Courier New", fontsize=10];');
    lines.push('');

    // Node declarations with labels
    for (const node of graph.nodes) {
      const safeId = this.dotId(node.fqn);
      const label = `${node.name}\\n${node.type}`;
      lines.push(`  ${safeId} [label="${label}"];`);
    }

    lines.push('');

    // Edge declarations
    for (const edge of graph.edges) {
      const sourceId = this.dotId(edge.source);
      const targetId = this.dotId(edge.target);
      const style = edge.optional ? ' [style=dashed]' : '';
      const label = edge.relation !== 'references' ? ` [label="${edge.relation}"]` : '';
      lines.push(`  ${sourceId} -> ${targetId}${style || label ? ` ${(style + label).trim()}` : ''};`);
    }

    lines.push('}');
    return lines.join('\n');
  }

  private determineScope(
    targetNodes: DependencyNode[],
    graph: DependencyGraph,
    allDependents: string[],
  ): ImpactAnalysis['impactScope'] {
    if (allDependents.length === 0) return 'local';

    const targetTypes = new Set(targetNodes.map(n => n.type));
    const dependentTypes = new Set<string>();

    for (const depName of allDependents) {
      const depNodes = graph.nodes.filter(n => n.name === depName);
      for (const dn of depNodes) {
        dependentTypes.add(dn.type);
      }
    }

    // Check if dependent types span multiple major categories
    const categories = new Set<string>();
    const allTypes = new Set([...targetTypes, ...dependentTypes]);

    for (const t of allTypes) {
      const category = t.split('-').slice(0, 3).join('-');
      categories.add(category);
    }

    if (categories.size >= 4) return 'system';
    if (categories.size >= 2) return 'crossModule';
    if (allDependents.length > 5) return 'module';
    return 'local';
  }

  private determineRisk(
    targetNodes: DependencyNode[],
    allDependents: string[],
    scope: ImpactAnalysis['impactScope'],
  ): ImpactAnalysis['risk'] {
    // Base risk on scope + number of dependents
    if (scope === 'system') return 'high';
    if (scope === 'crossModule' && allDependents.length > 10) return 'high';
    if (scope === 'crossModule') return 'medium';
    if (scope === 'module' && allDependents.length > 20) return 'high';
    if (scope === 'module') return 'medium';

    // Check if any targets are base classes or fundamental rules
    for (const node of targetNodes) {
      if (node.type === 'Rule-Obj-Class' && node.name !== '@baseclass') return 'medium';
    }

    return 'low';
  }

  private dotId(fqn: string): string {
    return `"${fqn.replace(/[^a-zA-Z0-9_:@.-]/g, '_')}"`;
  }
}

import type { ExpressionAstNode } from '../expression/PegaExpressionAst.js';
import { PegaExpressionParser } from '../expression/PegaExpressionParser.js';
import { PegaFunctionWhitelist } from './PegaFunctionWhitelist.js';

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export interface ValidationError {
  code: string;
  message: string;
}

export class PegaExpressionValidator {
  private parser = new PegaExpressionParser();
  private whitelist = new PegaFunctionWhitelist();
  private maxDepth = 100;
  private maxExpressionLength = 100_000;

  validate(expression: string): ValidationResult {
    const errors: ValidationError[] = [];

    if (!expression || expression.trim().length === 0) {
      errors.push({ code: 'EMPTY_EXPRESSION', message: 'Expression cannot be empty' });
      return { valid: false, errors };
    }

    if (expression.length > this.maxExpressionLength) {
      errors.push({
        code: 'EXPRESSION_TOO_LONG',
        message: `Expression exceeds max length of ${this.maxExpressionLength} characters`,
      });
      return { valid: false, errors };
    }

    let ast: ExpressionAstNode;
    try {
      ast = this.parser.parse(expression);
    } catch (err) {
      errors.push({
        code: 'PARSE_ERROR',
        message: (err as Error).message,
      });
      return { valid: false, errors };
    }

    this.validateAstNode(ast, 0, errors);

    return { valid: errors.length === 0, errors };
  }

  private validateAstNode(
    node: ExpressionAstNode,
    depth: number,
    errors: ValidationError[],
  ): void {
    if (depth > this.maxDepth) {
      errors.push({
        code: 'MAX_DEPTH_EXCEEDED',
        message: `Expression exceeds max depth of ${this.maxDepth}`,
      });
      return;
    }

    if (node.nodeType === 'FunctionCall') {
      const fnNode = node as any;
      if (!this.whitelist.isAllowed(fnNode.name)) {
        errors.push({
          code: 'FUNCTION_NOT_ALLOWED',
          message: `Function '${fnNode.name}' is not in whitelist`,
        });
      }
      for (const arg of fnNode.args) {
        this.validateAstNode(arg, depth + 1, errors);
      }
      return;
    }

    if (node.nodeType === 'BinaryOp') {
      const binNode = node as any;
      this.validateAstNode(binNode.left, depth + 1, errors);
      this.validateAstNode(binNode.right, depth + 1, errors);
      return;
    }

    if (node.nodeType === 'UnaryOp') {
      const unNode = node as any;
      this.validateAstNode(unNode.operand, depth + 1, errors);
      return;
    }
  }
}

import { PegaExpressionEvaluator } from '../expression/PegaExpressionEvaluator.js';
import { PegaClipboardContext } from '../expression/PegaClipboardContext.js';
import { PegaWorkflowEngine } from '../workflow/PegaWorkflowEngine.js';
import { PegaFlowGraph, type ShapeNode, type Connector } from '../workflow/PegaFlowGraph.js';
import { PegaDecisionTableEvaluator } from '../decision/PegaDecisionTableEvaluator.js';
import { parseDecisionCondition } from '../decision/PegaDecisionConditionParser.js';
import type { PegaDecisionTableRow } from '../decision/PegaEvaluationResult.js';

export interface SimulationOptions {
  maxSteps?: number;
  collectTrace?: boolean;
  timeoutMs?: number;
}

export interface SimulationTrace {
  step: number;
  action: string;
  detail: string;
  timestamp: number;
}

export interface SimulationRequest {
  pxObjClass: string;
  json: Record<string, unknown>;
  inputClipboard?: Record<string, Record<string, unknown>>;
  options?: SimulationOptions;
}

export interface SimulationResult {
  success: boolean;
  outputClipboard?: Record<string, Record<string, unknown>>;
  trace: SimulationTrace[];
  errors: string[];
  executionTimeMs: number;
}

export class PegaRuleSimulator {
  private expressionEvaluator: PegaExpressionEvaluator;
  private workflowEngine: PegaWorkflowEngine;
  private decisionTableEvaluator: PegaDecisionTableEvaluator;

  constructor() {
    this.expressionEvaluator = new PegaExpressionEvaluator();
    this.workflowEngine = new PegaWorkflowEngine();
    this.decisionTableEvaluator = new PegaDecisionTableEvaluator();
  }

  async simulate(request: SimulationRequest): Promise<SimulationResult> {
    const startTime = Date.now();
    const { pxObjClass, json, inputClipboard, options } = request;
    const clipboard = new PegaClipboardContext(inputClipboard || {}, 'pyWorkPage');

    switch (true) {
      case pxObjClass === 'Rule-Obj-Activity':
        return this.simulateActivity(json, clipboard, options);
      case pxObjClass === 'Rule-Obj-Model':
        return this.simulateDataTransform(json, clipboard, options);
      case pxObjClass === 'Rule-Obj-Flow':
        return this.simulateFlow(json, clipboard, options);
      case pxObjClass === 'Rule-Declare-DecisionTable' || pxObjClass === 'Rule-Declare-DecisionTree':
        return this.simulateDecisionTable(json, clipboard, options);
      default:
        return {
          success: false,
          trace: [{ step: 0, action: 'unsupported', detail: `Simulation not available for rule type: ${pxObjClass}`, timestamp: Date.now() }],
          errors: [`Unsupported rule type: ${pxObjClass}`],
          executionTimeMs: Date.now() - startTime,
        };
    }
  }

  simulateActivity(
    json: Record<string, unknown>,
    context: PegaClipboardContext,
    options?: SimulationOptions,
  ): SimulationResult {
    const startTime = Date.now();
    const trace: SimulationTrace[] = [];
    const errors: string[] = [];
    let stepCount = 0;
    const maxSteps = options?.maxSteps ?? 100;

    const name = (json.pyActivityName as string) || (json.pyRuleName as string) || '';
    const steps = Array.isArray(json.steps) ? json.steps : [];

    trace.push({
      step: stepCount++,
      action: 'start',
      detail: `Beginning simulation of activity "${name}" with ${steps.length} step(s)`,
      timestamp: Date.now(),
    });

    for (const s of steps) {
      if (stepCount > maxSteps) {
        errors.push(`Simulation exceeded max steps (${maxSteps})`);
        break;
      }

      const step = s as Record<string, unknown>;
      const method = (step.pyMethod as string) || '';
      const params = (step.pyMethodParameters as string) || '';
      const stepLabel = (step.pyLabel as string) || '';

      const when = step.pyWhenCondition as string;
      if (when) {
        try {
          const whenResult = this.expressionEvaluator.evaluate(when, context, options?.collectTrace);
          if (!whenResult.value.boolean) {
            trace.push({
              step: stepCount++,
              action: 'skip',
              detail: `Step "${stepLabel || method}" skipped (when condition "${when}" evaluated to false)`,
              timestamp: Date.now(),
            });
            continue;
          }
        } catch (err) {
          errors.push(`When condition evaluation error: ${err}`);
          trace.push({
            step: stepCount++,
            action: 'error',
            detail: `When condition "${when}" evaluation failed: ${err}`,
            timestamp: Date.now(),
          });
          continue;
        }
      }

      if (method === 'Call' || method === 'Branch') {
        trace.push({
          step: stepCount++,
          action: 'call',
          detail: `Calling activity ${params} (${stepLabel || 'no label'})`,
          timestamp: Date.now(),
        });
      } else if (method === 'Property-Set' || method === 'Property-Copy') {
        const target = params.replace(/^\./, '');
        trace.push({
          step: stepCount++,
          action: 'set',
          detail: `Setting property "${target}"`,
          timestamp: Date.now(),
        });
      } else if (method === 'Obj-Save' || method === 'Save') {
        trace.push({
          step: stepCount++,
          action: 'db_write',
          detail: `Saving "${params}" to database`,
          timestamp: Date.now(),
        });
      } else if (method === 'Obj-Delete') {
        trace.push({
          step: stepCount++,
          action: 'db_write',
          detail: `Deleting "${params}" from database`,
          timestamp: Date.now(),
        });
      } else if (method === 'Page-New') {
        trace.push({
          step: stepCount++,
          action: 'page_new',
          detail: `Creating new page "${params}"`,
          timestamp: Date.now(),
        });
      } else if (method) {
        trace.push({
          step: stepCount++,
          action: 'execute',
          detail: `Executing step method="${method}" params="${params}"`,
          timestamp: Date.now(),
        });
      } else {
        trace.push({
          step: stepCount++,
          action: 'noop',
          detail: `Step with no method`,
          timestamp: Date.now(),
        });
      }
    }

    trace.push({
      step: stepCount++,
      action: 'complete',
      detail: `Activity "${name}" simulation complete (${steps.length} steps processed)`,
      timestamp: Date.now(),
    });

    return {
      success: errors.length === 0,
      trace,
      errors,
      executionTimeMs: Date.now() - startTime,
    };
  }

  simulateDataTransform(
    json: Record<string, unknown>,
    context: PegaClipboardContext,
    options?: SimulationOptions,
  ): SimulationResult {
    const startTime = Date.now();
    const trace: SimulationTrace[] = [];
    const errors: string[] = [];
    let stepCount = 0;

    const name = (json.pyModelName as string) || (json.pyRuleName as string) || '';
    const actions = Array.isArray(json.pyActions) ? json.pyActions : [];

    trace.push({
      step: stepCount++,
      action: 'start',
      detail: `Beginning simulation of data transform "${name}" with ${actions.length} action(s)`,
      timestamp: Date.now(),
    });

    for (const a of actions) {
      const act = a as Record<string, unknown>;
      const actionType = (act.pyActionType as string) || '';
      const target = (act.pyTarget as string) || '';

      const when = act.pyWhenCondition as string;
      if (when) {
        try {
          const whenResult = this.expressionEvaluator.evaluate(when, context, options?.collectTrace);
          if (!whenResult.value.boolean) {
            trace.push({
              step: stepCount++,
              action: 'skip',
              detail: `Action "${actionType}" skipped (when condition "${when}" evaluated to false)`,
              timestamp: Date.now(),
            });
            continue;
          }
        } catch (err) {
          errors.push(`When condition evaluation error in data transform: ${err}`);
          trace.push({
            step: stepCount++,
            action: 'error',
            detail: `When condition "${when}" evaluation failed: ${err}`,
            timestamp: Date.now(),
          });
          continue;
        }
      }

      if (actionType === 'Set') {
        const source = (act.pySource as string) || '';
        trace.push({
          step: stepCount++,
          action: 'set',
          detail: `Mapping "${source}" -> "${target}"`,
          timestamp: Date.now(),
        });
      } else if (actionType === 'Apply Data Transform' || actionType === 'Page-New-Transform') {
        trace.push({
          step: stepCount++,
          action: 'apply_transform',
          detail: `Applying sub-transform "${target}"`,
          timestamp: Date.now(),
        });
      } else {
        trace.push({
          step: stepCount++,
          action: 'execute',
          detail: `Executing action "${actionType}" on target "${target}"`,
          timestamp: Date.now(),
        });
      }
    }

    trace.push({
      step: stepCount++,
      action: 'complete',
      detail: `Data transform "${name}" simulation complete`,
      timestamp: Date.now(),
    });

    return {
      success: errors.length === 0,
      trace,
      errors,
      executionTimeMs: Date.now() - startTime,
    };
  }

  simulateFlow(
    json: Record<string, unknown>,
    context: PegaClipboardContext,
    options?: SimulationOptions,
  ): SimulationResult {
    const startTime = Date.now();
    const trace: SimulationTrace[] = [];
    const errors: string[] = [];
    let stepCount = 0;

    const name = (json.pyFlowName as string) || (json.pyRuleName as string) || '';
    const shapes = Array.isArray(json.pyShapes) ? json.pyShapes : Array.isArray(json.shapes) ? json.shapes : [];

    if (shapes.length === 0) {
      return {
        success: false,
        trace: [{ step: 0, action: 'error', detail: 'Flow has no shapes defined', timestamp: Date.now() }],
        errors: ['Flow has no shapes defined'],
        executionTimeMs: Date.now() - startTime,
      };
    }

    const shapeMap = new Map<string, ShapeNode>();
    const connectors: Connector[] = [];

    for (let i = 0; i < shapes.length; i++) {
      const sh = shapes[i] as Record<string, unknown>;
      const shapeId = (sh.pyName as string) || `shape_${i}`;
      const shapeType = (sh.pyShapeType as string) || 'Unknown';
      const shape: ShapeNode = { id: shapeId, type: shapeType, properties: sh as Record<string, unknown> };
      shapeMap.set(shapeId, shape);

      if (i < shapes.length - 1) {
        const nextShape = shapes[i + 1] as Record<string, unknown>;
        const nextId = (nextShape.pyName as string) || `shape_${i + 1}`;
        connectors.push({
          id: `conn_${i}`,
          fromShapeId: shapeId,
          toShapeId: nextId,
          isDefault: true,
        });
      }
    }

    const graph = new PegaFlowGraph(shapeMap, connectors);
    const wfResult = this.workflowEngine.simulate(graph, context);

    for (const log of wfResult.log) {
      trace.push({
        step: stepCount++,
        action: 'flow_step',
        detail: log,
        timestamp: Date.now(),
      });
    }

    trace.push({
      step: stepCount++,
      action: wfResult.completed ? 'complete' : 'incomplete',
      detail: wfResult.completed
        ? `Flow "${name}" reached END after ${wfResult.history.length} shape(s)`
        : `Flow "${name}" did not reach END (stopped at shape ${wfResult.currentNodeId})`,
      timestamp: Date.now(),
    });

    return {
      success: wfResult.completed,
      trace,
      errors,
      executionTimeMs: Date.now() - startTime,
    };
  }

  simulateDecisionTable(
    json: Record<string, unknown>,
    context: PegaClipboardContext,
    options?: SimulationOptions,
  ): SimulationResult {
    const startTime = Date.now();
    const trace: SimulationTrace[] = [];
    const errors: string[] = [];
    let stepCount = 0;

    const name = (json.pyLabel as string) || (json.pyRuleName as string) || '';
    const rows = Array.isArray(json.pyDecisionTableRows) ? json.pyDecisionTableRows : Array.isArray(json.pyRows) ? json.pyRows : [];

    const dtRows: PegaDecisionTableRow[] = rows.map((r: unknown, i: number) => {
      const row = r as Record<string, unknown>;
      const condText = (row.pyCondition as string) || '';

      const conditions = condText
        ? [this.parseConditionFromString(condText)]
        : [];

      return {
        rowId: `R${i + 1}`,
        priority: i + 1,
        conditions,
        result: row.pyResult ?? null,
      };
    });

    trace.push({
      step: stepCount++,
      action: 'start',
      detail: `Beginning decision table "${name}" evaluation with ${dtRows.length} row(s)`,
      timestamp: Date.now(),
    });

    try {
      const result = this.decisionTableEvaluator.evaluate(dtRows, context, this.expressionEvaluator);

      for (const t of result.tracePath) {
        trace.push({
          step: stepCount++,
          action: 'eval',
          detail: t,
          timestamp: Date.now(),
        });
      }

      trace.push({
        step: stepCount++,
        action: result.status === 'matched' ? 'matched' : 'no_match',
        detail: result.status === 'matched'
          ? `Matched row ${result.matchedRowId} with result: ${JSON.stringify(result.outputValue)}`
          : 'No matching row found',
        timestamp: Date.now(),
      });

      return {
        success: result.status === 'matched' || result.status === 'no_match',
        trace,
        errors,
        executionTimeMs: Date.now() - startTime,
      };
    } catch (err) {
      errors.push(`Decision table evaluation error: ${err}`);
      trace.push({
        step: stepCount++,
        action: 'error',
        detail: `Decision table evaluation failed: ${err}`,
        timestamp: Date.now(),
      });
      return {
        success: false,
        trace,
        errors,
        executionTimeMs: Date.now() - startTime,
      };
    }
  }

  private parseConditionFromString(condText: string): { field: string; operator: 'EQUALS' | 'NOT_EQUALS' | 'GREATER' | 'GREATER_EQUALS' | 'LESS' | 'LESS_EQUALS'; value: unknown } {
    const parts = condText.trim().split(/\s+/);
    if (parts.length >= 3) {
      const field = parts[0];
      const opSymbol = parts[1];
      const value = parts.slice(2).join(' ');

      let operator: 'EQUALS' | 'NOT_EQUALS' | 'GREATER' | 'GREATER_EQUALS' | 'LESS' | 'LESS_EQUALS' = 'EQUALS';
      switch (opSymbol) {
        case '>': operator = 'GREATER'; break;
        case '<': operator = 'LESS'; break;
        case '>=': operator = 'GREATER_EQUALS'; break;
        case '<=': operator = 'LESS_EQUALS'; break;
        case '!=': case '<>': operator = 'NOT_EQUALS'; break;
        case '=': operator = 'EQUALS'; break;
        default: {
          if (opSymbol.toLowerCase() === 'equals') operator = 'EQUALS';
          break;
        }
      }

      const numericValue = Number(value);
      return { field, operator, value: isNaN(numericValue) ? value : numericValue };
    }

    if (parts.length === 1 && condText.includes(' ')) {
      return { field: condText, operator: 'EQUALS', value: true };
    }

    return { field: condText, operator: 'EQUALS', value: condText };
  }

  evaluateExpression(expression: string, context: PegaClipboardContext): unknown {
    const result = this.expressionEvaluator.evaluate(expression, context);
    return result.value.value;
  }
}

import type { PegaRuleAst, AstNode } from '../PegaRuleAst.js';
import type { PegaClassDefinition } from '../metamodel/PegaClassDefinition.js';
import type { SemanticAnalysis, SideEffect, SemanticDep, ConditionSummary, DataFlowEntry } from './types.js';

const SIDE_EFFECT_API_CALL = new Set([
  'Call', 'Connect-REST', 'Connect-SOAP', 'Connect-SQL', 'Connect-File',
  'Rule-Connect-REST', 'Rule-Connect-SOAP', 'Rule-Connect-SQL',
]);

const SIDE_EFFECT_DB_WRITE = new Set([
  'Property-Set', 'Obj-Save', 'Obj-Delete', 'Commit', 'Save',
  'Obj-Open-And-Update',
]);

const SIDE_EFFECT_PAGE_UPDATE = new Set([
  'Property-Set', 'Property-Copy', 'Page-New', 'Page-Copy',
  'Obj-Open', 'Obj-Open-By-Handle',
]);

export class PegaSemanticAnalyzer {
  analyze(json: Record<string, unknown>): SemanticAnalysis {
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Obj-Activity';
    const name = this.extractName(json);

    switch (true) {
      case pxObjClass === 'Rule-Obj-Activity':
        return this.analyzeActivity(json);
      case pxObjClass === 'Rule-Obj-Model':
        return this.analyzeDataTransform(json);
      case pxObjClass === 'Rule-Obj-Flow':
        return this.analyzeFlow(json);
      case pxObjClass === 'Rule-Obj-Section' || pxObjClass.startsWith('Rule-HTML-') || pxObjClass.startsWith('Rule-UI-'):
        return this.analyzeSection(json);
      case pxObjClass === 'Rule-Declare-DecisionTable' || pxObjClass === 'Rule-Declare-DecisionTree' || pxObjClass.startsWith('Rule-Decision-'):
        return this.analyzeDecision(json);
      case pxObjClass.startsWith('Rule-Connect-') || pxObjClass.startsWith('Rule-Service-'):
        return this.analyzeConnect(json);
      case pxObjClass.startsWith('Rule-Declare-'):
        return this.analyzeDeclare(json);
      default: {
        const analysis: SemanticAnalysis = {
          ruleType: pxObjClass,
          name,
          summary: `This is a ${pxObjClass} rule named "${name}"`,
          intent: `Define a ${pxObjClass} configuration`,
          sideEffects: [],
          dependencies: [],
          conditions: [],
          dataFlow: [],
        };
        return analysis;
      }
    }
  }

  analyzeActivity(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const label = (json.pyLabel as string) || name;
    const steps = Array.isArray(json.steps) ? json.steps : [];
    const stepDescs: string[] = [];
    const sideEffects: SideEffect[] = [];
    const dependencies: SemanticDep[] = [];
    const conditions: ConditionSummary[] = [];
    const dataFlow: DataFlowEntry[] = [];
    const calledActivities: string[] = [];
    const setProperties: string[] = [];

    for (const s of steps) {
      const step = s as Record<string, unknown>;
      const method = (step.pyMethod as string) || '';
      const params = (step.pyMethodParameters as string) || '';
      const stepLabel = (step.pyLabel as string) || '';
      const stepDesc = stepLabel || `${method} ${params}`;

      if (method === 'Call' || method === 'Branch') {
        const dotIdx = params.lastIndexOf('.');
        const calledClass = dotIdx >= 0 ? params.substring(0, dotIdx) : className;
        const calledName = dotIdx >= 0 ? params.substring(dotIdx + 1) : params;
        calledActivities.push(calledName);
        dependencies.push({
          type: 'activity',
          target: calledName,
          targetClass: calledClass,
          context: `Step calls ${calledName}`,
        });
        sideEffects.push({
          type: 'api_call',
          target: `${calledClass}.${calledName}`,
          detail: `Calls activity ${calledName}`,
        });
        stepDescs.push(`calls activity "${calledName}"`);
      } else if (method === 'Property-Set' || method === 'Property-Copy') {
        const target = params.replace(/^\./, '');
        if (target) {
          setProperties.push(target);
          sideEffects.push({
            type: 'page_update',
            target,
            detail: `Sets property ${target}`,
          });
          dataFlow.push({
            input: '',
            transform: `${method} -> ${target}`,
            output: target,
          });
          stepDescs.push(`sets property "${target}"`);
        }
      } else if (method === 'Obj-Save' || method === 'Save') {
        sideEffects.push({
          type: 'db_write',
          target: className || params,
          detail: `Saves object to database`,
        });
        stepDescs.push(`saves "${params}" to database`);
      } else if (method === 'Obj-Delete') {
        sideEffects.push({
          type: 'db_write',
          target: params,
          detail: `Deletes object from database`,
        });
        stepDescs.push(`deletes "${params}" from database`);
      } else if (method === 'Page-New') {
        sideEffects.push({
          type: 'page_update',
          target: params,
          detail: `Creates new page "${params}"`,
        });
        stepDescs.push(`creates new page "${params}"`);
      } else {
        stepDescs.push(stepDesc || `step ${steps.indexOf(s) + 1}`);
      }

      const when = step.pyWhenCondition as string;
      if (when) {
        conditions.push({
          field: when,
          operator: 'WHEN',
          value: true,
          description: `Guarded by when condition "${when}"`,
        });
      }
    }

    const summary = `This activity "${label}" ${steps.length === 0 ? 'has 0 step(s)' : `executes ${steps.length} step(s): ${stepDescs.join('; ')}`}.`;
    const intentParts: string[] = [];
    if (calledActivities.length > 0) intentParts.push(`calls ${calledActivities.length} sub-activity(ies)`);
    if (setProperties.length > 0) intentParts.push(`sets ${setProperties.length} property(ies)`);
    const intent = intentParts.length > 0 ? intentParts.join(' and ') : 'performs configured operations';

    return {
      ruleType: 'Rule-Obj-Activity',
      name,
      className,
      summary,
      intent,
      sideEffects,
      dependencies,
      conditions,
      dataFlow,
      steps: steps.length,
      calledActivities,
      setProperties,
    };
  }

  analyzeDataTransform(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const label = (json.pyLabel as string) || name;
    const actions = Array.isArray(json.pyActions) ? json.pyActions : [];
    const mappings: { from: string; to: string; condition?: string }[] = [];
    const dependencies: SemanticDep[] = [];
    const conditions: ConditionSummary[] = [];
    const sideEffects: SideEffect[] = [];
    const dataFlow: DataFlowEntry[] = [];

    for (const a of actions) {
      const act = a as Record<string, unknown>;
      const actionType = (act.pyActionType as string) || '';
      const target = (act.pyTarget as string) || '';
      const source = (act.pySource as string) || '';

      if (actionType === 'Set' && target && source) {
        const from = source.replace(/^\./, '');
        const to = target.replace(/^\./, '');
        mappings.push({ from, to });
        dataFlow.push({ input: from, transform: `Set ${from} -> ${to}`, output: to });
      }

      if ((actionType === 'Apply Data Transform' || actionType === 'Page-New-Transform') && target) {
        dependencies.push({
          type: 'data_transform',
          target,
          targetClass: className,
          context: `Applies data transform "${target}"`,
        });
        sideEffects.push({
          type: 'page_update',
          target: target,
          detail: `Applies data transform "${target}"`,
        });
      }

      const when = act.pyWhenCondition as string;
      if (when) {
        conditions.push({
          field: when,
          operator: 'WHEN',
          value: true,
          description: `Conditionally applied when "${when}"`,
        });
      }
    }

    const mappingDesc = mappings.map(m => `maps "${m.from}" to "${m.to}"`).join('; ');
    const summary = mappingDesc
      ? `This data transform "${label}" applies ${actions.length} action(s): ${mappingDesc}.`
      : `This data transform "${label}" applies ${actions.length} action(s).`;

    return {
      ruleType: 'Rule-Obj-Model',
      name,
      className,
      summary,
      intent: `Transform data by applying ${actions.length} action(s)`,
      sideEffects,
      dependencies,
      conditions,
      dataFlow,
      propertyMappings: mappings,
    };
  }

  analyzeFlow(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const label = (json.pyLabel as string) || name;
    const shapes = Array.isArray(json.pyShapes) ? json.pyShapes : Array.isArray(json.shapes) ? json.shapes : [];
    const shapeTypes: string[] = [];
    const dependencies: SemanticDep[] = [];
    const conditions: ConditionSummary[] = [];
    const sideEffects: SideEffect[] = [];
    const dataFlow: DataFlowEntry[] = [];

    for (const s of shapes) {
      const shape = s as Record<string, unknown>;
      const shapeType = (shape.pyShapeType as string) || 'Unknown';
      shapeTypes.push(shapeType);

      if (shape.pyFlowActionName) {
        dependencies.push({
          type: 'flow_action',
          target: shape.pyFlowActionName as string,
          targetClass: className,
          context: `Flow action "${shape.pyFlowActionName}"`,
        });
      }

      if (shape.pyWhenCondition) {
        conditions.push({
          field: shape.pyWhenCondition as string,
          operator: 'WHEN',
          value: true,
          description: `Branches on "${shape.pyWhenCondition}"`,
        });
      }

      if (shape.pyClassName && shape.pyClassName !== className) {
        dataFlow.push({
          input: '',
          transform: `References class ${shape.pyClassName}`,
          output: shape.pyClassName as string,
        });
      }
    }

    const startIdx = shapeTypes.indexOf('Start');
    const endIdx = shapeTypes.lastIndexOf('End');
    const route = startIdx >= 0 && endIdx >= 0 && endIdx > startIdx
      ? `starts at "${shapes[startIdx] && (shapes[startIdx] as Record<string, unknown>).pyName || 'Start'}", routes through ${shapeTypes.length - 2} shape(s), ends at "${shapes[endIdx] && (shapes[endIdx] as Record<string, unknown>).pyName || 'End'}"`
      : `contains ${shapeTypes.length} shape(s)`;

    const summary = `This flow "${label}" ${route}.`;
    return {
      ruleType: 'Rule-Obj-Flow',
      name,
      className,
      summary,
      intent: `Orchestrate ${shapeTypes.length} step(s) through a business process`,
      sideEffects,
      dependencies,
      conditions,
      dataFlow,
      shapeTypes,
    };
  }

  analyzeDecision(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Declare-DecisionTable';
    const label = (json.pyLabel as string) || name;
    const rows = Array.isArray(json.pyDecisionTableRows) ? json.pyDecisionTableRows : Array.isArray(json.pyRows) ? json.pyRows : [];
    const conditions: ConditionSummary[] = [];
    const dependencies: SemanticDep[] = [];
    const dataFlow: DataFlowEntry[] = [];
    const propertyEvaluated = (json.pyPropertyEvaluated as string) || '';

    for (const r of rows) {
      const row = r as Record<string, unknown>;
      const condText = (row.pyCondition as string) || '';
      const resultText = (row.pyResult as string) || '';

      if (condText) {
        const parts = condText.split(/\s+/);
        conditions.push({
          field: parts[0] || condText,
          operator: parts[1] || '?',
          value: parts.slice(2).join(' ') || '',
          description: condText,
        });
      }

      if (propertyEvaluated) {
        dataFlow.push({
          input: propertyEvaluated,
          transform: `Decision evaluates "${condText}"`,
          output: resultText,
        });
      }
    }

    const returnActions = json.pyReturnActions;
    if (Array.isArray(returnActions)) {
      for (const ra of returnActions) {
        const ract = ra as Record<string, unknown>;
        if (ract.pyTransformName) {
          dependencies.push({
            type: 'data_transform',
            target: ract.pyTransformName as string,
            targetClass: className,
            context: `Decision triggers transform "${ract.pyTransformName}"`,
          });
        }
      }
    }

    const summary = conditions.length > 0
      ? `This ${pxObjClass} "${label}" evaluates ${propertyEvaluated || 'properties'} across ${rows.length} row(s) and returns a matched result.`
      : `This ${pxObjClass} "${label}" has ${rows.length} row(s).`;

    return {
      ruleType: pxObjClass,
      name,
      className,
      summary,
      intent: `Evaluate ${rows.length} condition row(s) to determine output value`,
      sideEffects: [],
      dependencies,
      conditions,
      dataFlow,
      decisionRows: rows.length,
      propertyEvaluated,
    };
  }

  analyzeSection(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const label = (json.pyLabel as string) || name;
    const fields: string[] = [];
    const layouts: string[] = [];
    const dependencies: SemanticDep[] = [];

    const seenFields = new Set<string>();
    const extractFields = (obj: Record<string, unknown>, prefix: string): void => {
      for (const [key, val] of Object.entries(obj)) {
        if (key === 'pyPropertyName' && typeof val === 'string' && val && !seenFields.has(val)) {
          seenFields.add(val);
          fields.push(val);
        }
        if (key === 'pyLayoutType' && typeof val === 'string' && val) {
          layouts.push(val);
        }
        if (Array.isArray(val)) {
          for (const item of val) {
            if (typeof item === 'object' && item !== null) {
              extractFields(item as Record<string, unknown>, prefix);
            }
          }
        }
      }
    };

    extractFields(json, '');

    const layoutTypes = layouts.length > 0 ? [...new Set(layouts)] : ['dynamic'];
    const summary = fields.length > 0
      ? `This section "${label}" renders ${fields.length} field(s) (${fields.join(', ')}) in ${layoutTypes.join(', ')} layout(s).`
      : `This section "${label}" renders content in ${layoutTypes.join(', ')} layout(s).`;

    return {
      ruleType: 'Rule-Obj-Section',
      name,
      className,
      summary,
      intent: `Render ${fields.length} field(s) in ${layoutTypes.join(', ')} layout(s)`,
      sideEffects: [],
      dependencies,
      conditions: [],
      dataFlow: [],
      renderedFields: fields,
      layoutTypes,
    };
  }

  analyzeConnect(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Connect-REST';
    const label = (json.pyLabel as string) || name;
    const baseUrl = (json.pyBaseURL as string) || '';
    const resourcePath = (json.pyResourcePath as string) || '';
    const httpMethod = (json.pyHTTPMethod as string) || 'GET';
    const reqClass = (json.pyRequestClass as string) || '';
    const respClass = (json.pyResponseClass as string) || '';
    const authType = (json.pyAuthenticationType as string) || '';
    const sideEffects: SideEffect[] = [];
    const dependencies: SemanticDep[] = [];
    const dataFlow: DataFlowEntry[] = [];

    const url = (baseUrl || '') + (resourcePath || '');
    sideEffects.push({
      type: 'api_call',
      target: url || `${pxObjClass}:${name}`,
      detail: `Calls ${httpMethod} ${url || pxObjClass}`,
    });

    if (reqClass) {
      dataFlow.push({ input: reqClass, transform: `Serialized to ${httpMethod} request`, output: url || 'endpoint' });
    }
    if (respClass) {
      dataFlow.push({ input: url || 'endpoint', transform: `Deserialized from ${httpMethod} response`, output: respClass });
    }

    if (authType) {
      dependencies.push({
        type: 'auth',
        target: authType,
        targetClass: className,
        context: `Uses ${authType} authentication`,
      });
    }

    const summary = url
      ? `This ${pxObjClass} "${label}" calls ${httpMethod} ${url} with ${authType || 'no'} authentication.`
      : `This ${pxObjClass} "${label}" defines a connector endpoint.`;

    return {
      ruleType: pxObjClass,
      name,
      className,
      summary,
      intent: `Call ${httpMethod} ${url || 'external endpoint'} via ${pxObjClass}`,
      sideEffects,
      dependencies,
      conditions: [],
      dataFlow,
      endpointUrl: url,
      httpMethod,
      authType,
    };
  }

  analyzeDeclare(json: Record<string, unknown>): SemanticAnalysis {
    const name = this.extractName(json);
    const className = (json.pyClassName as string) || '';
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Declare-Expressions';
    const label = (json.pyLabel as string) || name;
    const targetProp = (json.pyTargetProperty as string) || (json.pyPropertyName as string) || '';
    const expression = (json.pyExpression as string) || '';
    const dependencies: SemanticDep[] = [];
    const dataFlow: DataFlowEntry[] = [];
    const conditions: ConditionSummary[] = [];
    const sideEffects: SideEffect[] = [];

    if (expression) {
      const inputs = this.extractPropertyRefs(expression);
      for (const input of inputs) {
        dataFlow.push({ input, transform: expression, output: targetProp || name });
      }
      dataFlow.push({ input: inputs.join(', ') || 'unknown', transform: expression, output: targetProp || name });
    }

    const when = json.pyWhenCondition as string;
    if (when) {
      conditions.push({
        field: when,
        operator: 'WHEN',
        value: true,
        description: `Applies when "${when}"`,
      });
    }

    const summary = targetProp && expression
      ? `This ${pxObjClass} "${label}" recalculates "${targetProp}" when dependencies change using expression: "${expression}".`
      : `This ${pxObjClass} "${label}" defines a declarative rule.`;

    return {
      ruleType: pxObjClass,
      name,
      className,
      summary,
      intent: targetProp ? `Recalculate ${targetProp} from ${expression || 'expression'}` : `Define declarative rule`,
      sideEffects,
      dependencies,
      conditions,
      dataFlow,
      targetProperty: targetProp,
      expression,
    };
  }

  analyzeGeneric(json: Record<string, unknown>, classDef: PegaClassDefinition): SemanticAnalysis {
    const name = this.extractName(json);
    const pxObjClass = classDef.pxObjClass || (json.pxObjClass as string) || 'Unknown';
    const description = classDef.description || '';
    const props: string[] = Object.keys(json).filter(k => k.startsWith('py') || k.startsWith('px'));
    const sideEffects: SideEffect[] = [];
    const dependencies: SemanticDep[] = [];
    const dataFlow: DataFlowEntry[] = [];

    for (const prop of classDef.properties) {
      if (prop.isReference && json[prop.name]) {
        dependencies.push({
          type: 'reference',
          target: String(json[prop.name]),
          targetClass: '',
          context: `References "${String(json[prop.name])}" via ${prop.name}`,
        });
      }
    }

    const summary = description
      ? `This ${pxObjClass} "${name}": ${description}. Has ${props.length} relevant propert(ies).`
      : `This ${pxObjClass} "${name}" has ${props.length} relevant propert(ies).`;

    return {
      ruleType: pxObjClass,
      name,
      summary,
      intent: `Configure a ${pxObjClass} with ${props.length} propert(ies)`,
      sideEffects,
      dependencies,
      conditions: [],
      dataFlow,
    };
  }

  private extractName(json: Record<string, unknown>): string {
    return (json.pyRuleName as string)
      || (json.pyActivityName as string)
      || (json.pyModelName as string)
      || (json.pyFlowName as string)
      || (json.pyLabel as string)
      || '';
  }

  private extractPropertyRefs(expr: string): string[] {
    const refs: string[] = [];
    const regex = /\.(\w+)/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(expr)) !== null) {
      const prop = match[1];
      if (!prop.startsWith('py') && !prop.startsWith('px') && !refs.includes(prop)) {
        refs.push(prop);
      }
    }
    return refs;
  }
}

/**
 * KbDrivenPegaParserStrategy — Phân tích Pega Rule/Data dựa trên tri thức Schema phong phú từ KB.
 * Hỗ trợ bóc tách đệ quy linh hoạt qua JSONPath mà không ảo giác.
 */

import type { IPegaRuleParserStrategy, ParseResult } from './IPegaRuleParserStrategy.js';
import type { UnresolvedDependency } from '../models.js';

export interface PegaRuleKbSchema {
  targetClass: string;
  displayName?: string;
  description?: string;
  nameProperty?: string;
  keyFields?: string[];
  contextFields?: string[];
  dependencyPaths: string[];
  semantics?: Record<string, unknown>;
}

export class KbDrivenPegaParserStrategy implements IPegaRuleParserStrategy {
  private schemaMap = new Map<string, PegaRuleKbSchema>();

  public addSchema(schema: PegaRuleKbSchema): void {
    this.schemaMap.set(schema.targetClass, schema);
  }

  public supports(pxObjClass: string): boolean {
    return this.schemaMap.has(pxObjClass);
  }

  public parse(json: Record<string, unknown>): ParseResult {
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Obj-Activity';
    const schema = this.schemaMap.get(pxObjClass);
    const className = (json.pyClassName as string) || (json.className as string) || '@baseclass';
    const nameProp = schema?.nameProperty || 'pyLabel';
    const name = (json[nameProp] as string) || (json.pyRuleName as string) || (json.pyLabel as string) || 'Unnamed';
    const fqn = `${pxObjClass}:${className}:${name}`;

    const symbol = {
      fqn,
      name,
      className,
      ruleType: pxObjClass,
      isRule: pxObjClass.startsWith('Rule-'),
      ruleset: (json.pyRuleset as string) || undefined,
      version: (json.pyRulesetVersion as string) || undefined,
    };

    const dependencies = this.extractDependenciesBySchema(json, schema?.dependencyPaths || []);
    return { symbol, dependencies };
  }

  private extractDependenciesBySchema(json: Record<string, unknown>, paths: string[]): UnresolvedDependency[] {
    const deps: UnresolvedDependency[] = [];
    for (const pathStr of paths) {
      this.extractByPath(json, pathStr, deps);
    }
    return deps;
  }

  private extractByPath(json: Record<string, unknown>, pathStr: string, deps: UnresolvedDependency[]): void {
    if (pathStr.includes('[].')) {
      const [arrayProp, targetProp] = pathStr.split('[].');
      const arr = Array.isArray(json[arrayProp]) ? (json[arrayProp] as any[]) : [];
      for (const item of arr) {
        if (item && typeof item === 'object' && typeof item[targetProp] === 'string' && item[targetProp].trim()) {
          deps.push({ ruleType: 'Unknown', className: '@baseclass', ruleName: item[targetProp].trim() });
        }
      }
    } else if (typeof json[pathStr] === 'string' && (json[pathStr] as string).trim()) {
      deps.push({ ruleType: 'Unknown', className: '@baseclass', ruleName: (json[pathStr] as string).trim() });
    }
  }
}

import type { PegaSection } from './PegaUITypes.js';
import type { PegaClipboardContext } from '../expression/PegaClipboardContext.js';
import { PegaSectionRenderer } from './PegaSectionRenderer.js';
import { PegaHtmlSanitizer } from '../security/PegaHtmlSanitizer.js';

export interface HarnessSections {
  header?: PegaSection;
  content?: PegaSection;
  footer?: PegaSection;
}

export class PegaHarnessAssembler {
  private sectionRenderer = new PegaSectionRenderer();

  assemble(sections: HarnessSections, context: PegaClipboardContext): string {
    const headerHtml = sections.header
      ? `<header class="pega-header">${this.sectionRenderer.renderSection(sections.header, context)}</header>`
      : '';

    const contentHtml = sections.content
      ? `<main class="pega-content">${this.sectionRenderer.renderSection(sections.content, context)}</main>`
      : '';

    const footerHtml = sections.footer
      ? `<footer class="pega-footer">${this.sectionRenderer.renderSection(sections.footer, context)}</footer>`
      : '';

    return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Pega Harness Preview</title><style>${this.getCssStyles()}</style></head><body>${headerHtml}${contentHtml}${footerHtml}</body></html>`;
  }

  private getCssStyles(): string {
