import type { PegaSection, PegaLayout, PegaField } from './PegaUITypes.js';
import type { LayoutType } from './PegaUITypes.js';
import type { PegaClipboardContext } from '../expression/PegaClipboardContext.js';
import { PegaLayoutRenderer } from './layouts/PegaLayoutRenderer.js';
import type { LayoutRenderFunction } from './layouts/PegaLayoutRenderer.js';
import { PegaDynamicLayoutRenderer } from './layouts/PegaDynamicLayoutRenderer.js';
import { PegaTabLayoutRenderer } from './layouts/PegaTabLayoutRenderer.js';
import { PegaRepeatingLayoutRenderer } from './layouts/PegaRepeatingLayoutRenderer.js';
import { PegaTableLayoutRenderer } from './layouts/PegaTableLayoutRenderer.js';
import { PegaFieldRenderer } from './PegaFieldRenderer.js';
import { PegaVisibilityEvaluator } from './PegaVisibilityEvaluator.js';

export class PegaSectionRenderer {
  private renderers = new Map<LayoutType, PegaLayoutRenderer>();
  private fieldRenderer = new PegaFieldRenderer();
  private visibilityEvaluator = new PegaVisibilityEvaluator();

  constructor() {
    this.renderers.set('dynamic', new PegaDynamicLayoutRenderer());
    this.renderers.set('tab', new PegaTabLayoutRenderer());
    this.renderers.set('repeating', new PegaRepeatingLayoutRenderer());
    this.renderers.set('table', new PegaTableLayoutRenderer());
  }

  renderSection(section: PegaSection, context: PegaClipboardContext): string {
    const layouts = section.layouts ?? [];
    const fields = section.fields ?? [];
    const parts: string[] = [];

    for (const layout of layouts) {
      if (!this.isVisible(layout, context)) continue;
      parts.push(this.renderLayout(layout, context));
    }

    for (const field of fields) {
      if (!this.isVisible(field, context)) continue;
      parts.push(this.fieldRenderer.renderField(field, context));
    }

    return `<div class="pega-section">${parts.join('')}</div>`;
  }

  private renderLayout(layout: PegaLayout, context: PegaClipboardContext): string {
    const renderer = layout.type ? this.renderers.get(layout.type) : this.renderers.get('dynamic');
    if (!renderer) {
      return `<div class="pega-unknown-layout">${layout.type ?? 'unknown'}</div>`;
    }
    return renderer.render(layout, context, this.fieldRenderer, this.renderLayout.bind(this));
  }

  private isVisible(element: PegaLayout | PegaField, context: PegaClipboardContext): boolean {
    return this.visibilityEvaluator.evaluate({
      visible: element.visible,
      when: element.when,
    }, context);
  }
}

import { PegaSchemaInferrer } from '../inference/PegaSchemaInferrer.js';
import { PegaFieldDocumentor } from '../inference/PegaFieldDocumentor.js';
import { PegaSemanticAnalyzer } from '../semantic/PegaSemanticAnalyzer.js';
import { PegaRuleSimulator } from '../semantic/PegaRuleSimulator.js';
import { PegaReferenceExtractor } from '../references/PegaReferenceExtractor.js';
import { PegaMetaModelRegistry } from '../metamodel/PegaMetaModelRegistry.js';
import { PegaMetaModelCompiler } from '../metamodel/PegaMetaModelCompiler.js';
import type { PegaClassDefinition } from '../metamodel/PegaClassDefinition.js';
import type { SideEffect, DataFlowEntry, ConditionSummary } from '../semantic/types.js';
import type { ResolvedDependency } from '../references/PegaReferenceExtractor.js';
import type { SimulationResult, SimulationTrace } from '../semantic/PegaRuleSimulator.js';

export interface PegaRuleUnderstanding {
  pxObjClass: string;
  name: string;
  className: string;
  fqn: string;

  schema: {
    classDefinition: PegaClassDefinition;
    fieldDocs: string;
    inferred: boolean;
  };

  semantics: {
    summary: string;
    intent: string;
    sideEffects: SideEffect[];
    dataFlow: DataFlowEntry[];
    conditions: ConditionSummary[];
  };

  dependencies: ResolvedDependency[];
  dependencyGraph: string;

  simulation: {
    input: Record<string, Record<string, unknown>> | null;
    result: SimulationResult | null;
    trace: SimulationTrace[];
  } | null;

  promptContext: string;
}

export class PegaRuleUnderstandingService {
  constructor(
    private inferrer: PegaSchemaInferrer,
    private documentor: PegaFieldDocumentor,
    private analyzer: PegaSemanticAnalyzer,
    private simulator: PegaRuleSimulator,
    private extractor: PegaReferenceExtractor,
    private registry: PegaMetaModelRegistry,
    private compiler: PegaMetaModelCompiler,
  ) {}

  async understand(json: Record<string, unknown>, options?: {
    simulate?: boolean;
    simulateInput?: Record<string, Record<string, unknown>>;
  }): Promise<PegaRuleUnderstanding> {
    const pxObjClass = (json.pxObjClass as string) || 'Rule-Obj-Activity';
    const className = (json.pyClassName as string) || '@baseclass';
    const name = this.extractRuleName(json);
    const fqn = `${pxObjClass}:${className}:${name}`;

    const wasKnown = this.registry.isKnownClass(pxObjClass);
    const classDef = this.inferrer.ensureSchema(pxObjClass, json, this.registry);
    const inferred = !wasKnown;

    const fieldDocs = this.documentor.generatePromptContext(pxObjClass, json, this.registry);
    const analysis = this.analyzer.analyze(json);
    const deps = this.extractor.extractFromRule(json);
    const dependencyGraph = this.buildDependencyGraphText(deps);

    let simulation: PegaRuleUnderstanding['simulation'] = null;
    if (options?.simulate) {
      const simInput = options.simulateInput || null;
      let simResult: SimulationResult | null = null;
      let simTrace: SimulationTrace[] = [];

      try {
        simResult = await this.simulator.simulate({
          pxObjClass,
          json,
          inputClipboard: options.simulateInput,
          options: { collectTrace: true },
        });
        simTrace = simResult.trace;
      } catch {
        simResult = null;
        simTrace = [];
      }

      simulation = {
        input: simInput,
        result: simResult,
        trace: simTrace,
      };
    }

    const understanding: PegaRuleUnderstanding = {
      pxObjClass,
      name,
      className,
      fqn,
      schema: {
        classDefinition: classDef,
        fieldDocs,
        inferred,
      },
      semantics: {
        summary: analysis.summary,
        intent: analysis.intent,
        sideEffects: analysis.sideEffects,
        dataFlow: analysis.dataFlow,
        conditions: analysis.conditions,
      },
      dependencies: deps,
      dependencyGraph,
      simulation,
      promptContext: '',
    };

    understanding.promptContext = this.toPromptContext(understanding);

    return understanding;
  }

  toPromptContext(understanding: PegaRuleUnderstanding): string {
    const lines: string[] = [];
    const W = 55;

    const topBorder = `╔${'═'.repeat(W)}╗`;
    const bottomBorder = `╚${'═'.repeat(W)}╝`;

    lines.push(topBorder);
    lines.push(`║  Rule Understanding: ${understanding.name.padEnd(W - 26)}║`);
    lines.push(`║  Type: ${understanding.pxObjClass.padEnd(W - 12)}║`);
    lines.push(`║  Class: ${understanding.className.padEnd(W - 13)}║`);
    lines.push(bottomBorder);
    lines.push('');

    lines.push(`── Schema ${'─'.repeat(W - 10)}──`);
    lines.push(`  Inferred: ${understanding.schema.inferred ? 'yes — detected from JSON' : 'no — loaded from known schema'}`);
    const docLines = understanding.schema.fieldDocs.split('\n');
    for (let i = 0; i < docLines.length; i++) {
      lines.push(`  ${docLines[i]}`);
    }
    lines.push('');

    lines.push(`── Semantic Analysis ${'─'.repeat(W - 22)}──`);
    lines.push(`  Summary: ${understanding.semantics.summary}`);
    lines.push(`  Intent: ${understanding.semantics.intent}`);

    if (understanding.semantics.sideEffects.length > 0) {
      lines.push('  Side Effects:');
      for (const se of understanding.semantics.sideEffects) {
        lines.push(`    • ${se.type}: ${se.detail}`);
      }
    }

    if (understanding.semantics.dataFlow.length > 0) {
      lines.push('  Data Flow:');
      for (const df of understanding.semantics.dataFlow) {
        if (df.input) {
          lines.push(`    ${df.input} > ${df.transform} > ${df.output}`);
        } else {
          lines.push(`    ${df.transform} > ${df.output}`);
        }
      }
    }

    if (understanding.semantics.conditions.length > 0) {
      lines.push('  Conditions:');
      for (const cond of understanding.semantics.conditions) {
        lines.push(`    WHEN ${cond.field} ${cond.operator} ${cond.value} — ${cond.description}`);
      }
    }
    lines.push('');

    lines.push(`── Dependencies ${'─'.repeat(W - 16)}──`);
    if (understanding.dependencies.length === 0) {
      lines.push('  (none)');
    } else {
      for (const dep of understanding.dependencies) {
        const opt = dep.optional ? ' (optional)' : '';
        lines.push(`  → ${dep.type}: ${dep.name} (${dep.relation})${opt}`);
      }
    }
    if (understanding.dependencyGraph) {
      lines.push(`  Graph: ${understanding.dependencyGraph}`);
    }
    lines.push('');

    if (understanding.simulation) {
      lines.push(`── Simulation ${'─'.repeat(W - 14)}──`);
      if (understanding.simulation.input) {
        lines.push(`  Input: ${JSON.stringify(understanding.simulation.input)}`);
      }
      if (understanding.simulation.result) {
        const r = understanding.simulation.result;
        lines.push(`  Result: ${r.success ? '✓ Success' : '✗ Failed'} (${r.executionTimeMs}ms)`);
        if (r.errors.length > 0) {
          for (const err of r.errors) {
            lines.push(`    Error: ${err}`);
          }
        }
      }
      if (understanding.simulation.trace.length > 0) {
        lines.push('  Trace:');
        for (const t of understanding.simulation.trace) {
          lines.push(`    Step ${t.step}: ${t.action} — ${t.detail}`);
        }
      }
      lines.push('');
    }

    return lines.join('\n');
  }

  private extractRuleName(json: Record<string, unknown>): string {
    return (json.pyRuleName as string)
      || (json.pyActivityName as string)
      || (json.pyModelName as string)
      || (json.pyTransformName as string)
      || (json.pyFlowName as string)
      || (json.pyLabel as string)
      || 'Unnamed';
  }

  private buildDependencyGraphText(deps: ResolvedDependency[]): string {
    if (deps.length === 0) return '';
    const entries = deps.map(d => `${d.type}:${d.name}`);
    return entries.join('; ');
  }
}

/**
 * SA4E-132 — GateGuardService: business logic for command evaluation + denylist management.
 * Chain of Responsibility: patterns checked sequentially, first match wins.
 * Facade: hides regex compilation, caching, and audit from consumers.
 *
 * Performance: Pre-compiled RegExp cached in memory; evaluation < 50ms.
 * SEC-05: ReDoS-prone patterns rejected before adding to denylist.
 */

import { createHash } from 'crypto';
import type { Logger } from 'pino';
import type { GateGuardRepository } from './GateGuardRepository.js';
import type { DenyPattern, EvalResult, AuditEntry, GateGuardAction } from './models.js';

/** BR-1201: Default destructive command patterns */
const DEFAULT_PATTERNS: DenyPattern[] = [
  { id: 'default-force-push', regex: 'git push --force.*', description: 'Force push', isDefault: true },
  { id: 'default-force-push-f', regex: 'git push -f.*', description: 'Force push short flag', isDefault: true },
  { id: 'default-rm-rf', regex: 'rm -rf\\s+(/|~|\\.\\.)', description: 'Recursive delete of root/home/parent', isDefault: true },
  { id: 'default-drop-table', regex: 'DROP\\s+TABLE', description: 'SQL DROP TABLE', isDefault: true },
  { id: 'default-drop-db', regex: 'DROP\\s+DATABASE', description: 'SQL DROP DATABASE', isDefault: true },
  { id: 'default-delete-no-where', regex: 'DELETE\\s+FROM\\s+\\w+\\s*;?\\s*$', description: 'DELETE without WHERE clause', isDefault: true },
  { id: 'default-git-reset-hard', regex: 'git reset --hard', description: 'Hard reset', isDefault: true },
  { id: 'default-kubectl-delete-ns', regex: 'kubectl delete namespace', description: 'Delete k8s namespace', isDefault: true },
  { id: 'default-docker-prune', regex: 'docker system prune -a', description: 'Docker full prune', isDefault: true },
];

/** SEC-05: Input that forces catastrophic backtracking for naive pattern detection. */
const REDOS_TEST_INPUT = 'a'.repeat(25) + 'x';
const REDOS_TIMEOUT_MS = 100;

export class GateGuardService {
  private compiledPatterns: Array<{ pattern: DenyPattern; regex: RegExp }> = [];
  private cacheValid = false;
  private customPatternSeq = 0;

  constructor(
    private readonly repository: GateGuardRepository,
    private readonly logger: Logger,
  ) {}

  /** Initialize cache with default + custom patterns */
  loadPatterns(projectId?: string): void {
    const customPatterns = this.repository.getPatterns(projectId);
    const allPatterns = [...DEFAULT_PATTERNS, ...customPatterns];
    this.compiledPatterns = allPatterns
      .map(p => this.compilePattern(p))
      .filter((p): p is { pattern: DenyPattern; regex: RegExp } => p !== null);
    this.cacheValid = true;
  }

  /** BR-1201/BR-1203: Evaluate a command against the denylist. < 50ms target. */
  evaluate(command: string, agent?: string, projectId?: string): EvalResult {
    const start = performance.now();
    if (!this.cacheValid) this.loadPatterns(projectId);

    for (const { pattern, regex } of this.compiledPatterns) {
      if (regex.test(command)) {
        const hash = this.generateOverrideHash(command);
        const latencyMs = Math.round(performance.now() - start);
        this.logAudit(command, agent, pattern.regex, 'blocked', projectId);
        return {
          action: 'blocked',
          patternMatched: pattern.regex,
          explanation: `Destructive command blocked by GateGuard: ${command.slice(0, 100)}`,
          overrideHash: hash,
          latencyMs,
        };
      }
    }

    const latencyMs = Math.round(performance.now() - start);
    return { action: 'allowed', latencyMs };
  }

  /** BR-1202: Process override — requires admin role (SEC-01) */
  processOverride(hash: string, user: string, role?: string): boolean {
    if (role !== 'gateguard_admin') {
      this.logger.warn({ user, role }, 'Override rejected: missing gateguard_admin role');
      return false;
    }
    this.logger.info({ user, hash }, 'GateGuard override approved');
    return true;
  }

  /** BR-1205: Add custom denylist pattern with ReDoS validation (SEC-05) */
  addPattern(regex: string, description: string, projectId?: string): DenyPattern {
    this.validateNotReDoS(regex);
    const id = `custom-${++this.customPatternSeq}`;
    const pattern: DenyPattern = { id, regex, description, isDefault: false, projectId };
    this.repository.addPattern(pattern);
    this.invalidateCache();
    return pattern;
  }

  /** Remove a custom pattern — defaults cannot be removed */
  removePattern(patternId: string): boolean {
    const removed = this.repository.removePattern(patternId);
    if (removed) this.invalidateCache();
    return removed;
  }

  /** List all patterns (default + custom) */
  listPatterns(projectId?: string): DenyPattern[] {
    const custom = this.repository.getPatterns(projectId);
    return [...DEFAULT_PATTERNS, ...custom];
  }

  /** Query audit log */
  getAuditLog(projectId?: string, limit?: number, actionFilter?: GateGuardAction): AuditEntry[] {
    return this.repository.queryAudit(projectId, limit, actionFilter);
  }

  /** Invalidate compiled regex cache — forces reload on next evaluate */
  invalidateCache(): void {
    this.cacheValid = false;
    this.compiledPatterns = [];
  }

  /** SEC-05: Reject ReDoS-prone regex patterns before adding */
  private validateNotReDoS(regex: string): void {
    try {
      const re = new RegExp(regex, 'i');
      const start = performance.now();
      re.test(REDOS_TEST_INPUT);
const elapsed = performance.now() - start;
      if (elapsed > REDOS_TIMEOUT_MS) {
        throw new Error(`Invalid regex: pattern appears ReDoS-prone (took ${elapsed.toFixed(1)}ms on test input)`);
      }
    } catch (err) {
      if ((err as Error).message.includes('ReDoS-prone')) throw err;
      throw new Error(`Invalid regex pattern: ${(err as Error).message}`);
    }
  }

  private compilePattern(p: DenyPattern): { pattern: DenyPattern; regex: RegExp } | null {
    try {
      return { pattern: p, regex: new RegExp(p.regex, 'i') };
    } catch {
      this.logger.warn({ patternId: p.id, regex: p.regex }, 'Failed to compile denylist regex');
      return null;
    }
  }

  private generateOverrideHash(command: string): string {
    return createHash('sha256').update(command).digest('hex').slice(0, 12);
  }

  private logAudit(
    command: string, agent: string | undefined,
    patternMatched: string, action: GateGuardAction, projectId?: string,
  ): void {
    try {
      this.repository.insertAudit({ command, agent, patternMatched, action, projectId });
    } catch (err) {
      this.logger.error({ err }, 'Failed to write GateGuard audit entry');
    }
  }
}

/**
 * Hono HTTP server setup with all routes and middleware.
 * DIP fix: ToolRouter and McpConfigService can be injected via HttpServerOptions.
 * Production defaults create them internally; tests can inject mocks.
 * Implements: UC-2, UC-7, BR-35, BR-37
 */

import { Hono } from 'hono';
import { serve } from '@hono/node-server';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../modules/ModuleRegistry.js';
import { ToolRouter } from '../tool-router/ToolRouter.js';
import { createHealthRoute } from './routes/health.js';
import { createToolsRoute } from './routes/tools.js';
import { createApiRoute } from './routes/api.js';
import { createProjectTypeRoutes } from './routes/project-type-routes.js';
import { createEnrichmentStatusRoutes } from './routes/enrichment-status-routes.js';
import { createAdminRoute } from './routes/admin.js';
import { createMcpConfigRoutes } from '../modules/orchestration/McpConfigRoutes.js';
import { McpConfigService } from '../modules/orchestration/McpConfigService.js';
import { createRequestLogger } from './middleware/request-logger.js';
import { createErrorHandler } from './middleware/error-handler.js';
import { rateLimiter } from './middleware/rate-limiter.js';
import { securityHeaders } from './middleware/security-headers.js';
import { apiKeyAuth } from './middleware/api-key-auth.js';
import { validateJwtConfig, jwtAuth } from './middleware/jwt-auth.js';
import { createKbApiRoutes, createToolsApiRoutes } from './routes/kb-api.js';
import { createPegaApiRoutes } from './routes/pega-api.js';
import { createPegaStreamRoutes } from './routes/pega-stream.js';
import { createIngestRuleRoute } from './routes/pega-ingest-rule.js';
import { createPegaSchemaRoutes } from './routes/pega-schema-routes.js';
import { createPegaSyncToKbRoutes } from './routes/pega-sync-to-kb.js';
import { createKnowledgeApiRoutes } from '../knowledge/routes.js';
import { bodyLimit } from 'hono/body-limit';
import { getMcpServer, registerTransport } from './mcpServer.js';
import { WebStandardStreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js';

export interface HttpServerOptions {
  port: number;
  host: string;
  logger: Logger;
  registry: ModuleRegistry;
  version: string;
  /** DIP: optionally inject a pre-built ToolRouter (useful for testing). Defaults to new ToolRouter(registry). */
  toolRouter?: ToolRouter;
  /** DIP: optionally inject a pre-built McpConfigService. Defaults to new McpConfigService(workspace, dataDir). */
  mcpConfigService?: McpConfigService;
}

export class HttpServer {
  private app: Hono;
  private server: ReturnType<typeof serve> | null = null;
  private logger: Logger;
  private port: number;
  private host: string;
  private _isRunning = false;

  constructor(private options: HttpServerOptions) {
    this.logger = options.logger;
    this.port = options.port;
    this.host = options.host;
    this.app = this.createApp();
  }

  private createApp(): Hono {
    const app = new Hono();
    // DIP: use injected ToolRouter or create default
    const toolRouter = this.options.toolRouter ?? new ToolRouter(this.options.registry, this.logger);

    app.use('*', securityHeaders);
    // Exempt streaming ingest from body limit — it uses ReadableStream getReader() directly
    app.use('*', async (c, next) => {
      if (c.req.path === '/api/v1/pega/ingest-stream') return next();
      return bodyLimit({ maxSize: 100 * 1024 * 1024 })(c, next);
    });
    app.use('*', createRequestLogger(this.logger));
    app.use('/api/admin/*', rateLimiter);
    app.use('/api/admin/auth/login', rateLimiter);
    app.use('/api/index/*', jwtAuth);
    app.use('/api/tags/*', apiKeyAuth);
    app.use('/mcp/*', apiKeyAuth);
    app.onError(createErrorHandler(this.logger));

    app.route('/', createHealthRoute(this.options.registry, this.options.version));
    app.route('/', createToolsRoute(toolRouter, this.logger));
    app.route('/', createApiRoute(this.options.registry, this.logger));
    app.route('/', createAdminRoute(this.logger, this.options.registry));

    this.registerMcpConfigRoutes(app);

    const kbApiRoutes = createKbApiRoutes(this.options.registry, this.logger);
    app.route('/api/v1', kbApiRoutes);

    const pegaApiRoutes = createPegaApiRoutes(this.options.registry, this.logger);
    app.route('/api/v1', pegaApiRoutes);

    // SA4E-92: NDJSON streaming ingest — constant memory regardless of batch size
    const pegaStreamRoutes = createPegaStreamRoutes(this.options.registry, this.logger);
    app.route('/api/v1', pegaStreamRoutes);

    // SA4E-158: Sync indexed Pega rules to KB (Phase 2)
    const pegaSyncRoutes = createPegaSyncToKbRoutes(this.options.registry, this.logger);
    app.route('/api/v1', pegaSyncRoutes);

    // SA4E-156: Per-rule ingestion with relative extraction (BFS-compatible)
    const ingestRuleRoute = createIngestRuleRoute(this.options.registry, this.logger);
    app.route('/api/v1/pega/ingest-rule', ingestRuleRoute);

    // SA4E-95: Schema generation from harness JSON (backend analysis, no Pega API calls)
    const pegaSchemaRoutes = createPegaSchemaRoutes(this.logger);
    app.route('/api/v1', pegaSchemaRoutes);

    // SA4E-85 Phase 0: Backend-Driven Knowledge REST API (threads/messages/checkpoint/events/artifacts/agents)
    const knowledgeModule = this.options.registry.getModule('knowledge') as any;
    if (knowledgeModule?.getService) {
      const knowledgeRoutes = createKnowledgeApiRoutes(knowledgeModule.getService(), this.logger);
      app.route('/api/v1', knowledgeRoutes);
    }

    const toolsApiRoutes = createToolsApiRoutes(this.options.registry, this.logger);
    app.route('/api/tools', toolsApiRoutes);

    // SA4E-108: Project type configs endpoint (extension fetches KB type definitions)
    const projectTypeRoutes = createProjectTypeRoutes(this.options.registry, this.logger);
    app.route('/api/v1', projectTypeRoutes);

    // SA4E-157: Enrichment status polling endpoint (JWT auth, no admin check)
    const enrichmentStatusRoutes = createEnrichmentStatusRoutes(this.options.registry, this.logger);
    app.route('/api/v1', enrichmentStatusRoutes);

    app.all('/mcp', async (c) => {
      const transport = new WebStandardStreamableHTTPServerTransport();
      registerTransport(transport);
      // Extract project context from HTTP headers for multi-tenant scope isolation
      const projectId = c.req.header('X-Project-Id') || '';
      const projectContext = projectId ? { projectId, userId: 'mcp-client' } : undefined;
      const server = getMcpServer(this.options.registry, this.logger, projectContext);
      await server.connect(transport);
      return transport.handleRequest(c.req.raw);
    });

    return app;
  }

  async start(): Promise<void> {
    return new Promise((resolve) => {
      this.server = serve({
        fetch: this.app.fetch,
        port: this.port,
        hostname: this.host,
      }, (info) => {
        this._isRunning = true;
        this.logger.info({ port: info.port, host: this.host }, 'Backend server started');
        resolve();
      });
    });
  }

  async stop(): Promise<void> {
    if (this.server) {
      this.server.close();
      this._isRunning = false;
      this.logger.info('Backend server stopped');
    }
  }

  get isRunning(): boolean { return this._isRunning; }
  get honoApp(): Hono { return this.app; }

  private registerMcpConfigRoutes(app: Hono): void {
    const orchestration = this.options.registry.getModule('orchestration') as any;
    if (!orchestration) {
      this.logger.warn('OrchestrationModule not found, skipping MCP config routes');
      return;
    }
    const clientManager = orchestration.getClientManager?.();
    if (!clientManager) {
      this.logger.warn('McpClientManager not available, skipping MCP config routes');
      return;
    }
    // DIP: use injected McpConfigService or create default
    const configService = this.options.mcpConfigService ?? new McpConfigService(
      process.env.CODE_INTEL_WORKSPACE || process.cwd(),
      process.env.CODE_INTEL_DATA_DIR || '.code-intel',
      this.logger,
    );
    const mcpConfigApp = createMcpConfigRoutes(configService, clientManager, this.logger);
    app.route('/', mcpConfigApp);
    this.logger.info('MCP Config REST API registered at /api/mcp-servers');
  }
}

