/**
 * Unit tests — url-validator (SSRF protection, SA4E Finding #11).
 * Verifies scheme allow-listing, localhost/private-IP blocking (IPv4 + IPv6),
 * and acceptance of public URLs.
 */

import { describe, it, expect } from 'vitest';
import { validateExternalUrl } from '../url-validator.js';

describe('validateExternalUrl', () => {
  it('accepts a public https URL', () => {
    expect(validateExternalUrl('https://example.com/path')).toEqual({ valid: true });
  });

  it('accepts a public http URL', () => {
    expect(validateExternalUrl('http://example.com')).toEqual({ valid: true });
  });

  it('accepts public IP hostnames', () => {
    expect(validateExternalUrl('http://8.8.8.8/')).toEqual({ valid: true });
  });

  it('rejects empty and non-string inputs', () => {
    expect(validateExternalUrl('')).toEqual({ valid: false, error: 'URL is required' });
    expect(validateExternalUrl(undefined as any)).toEqual({ valid: false, error: 'URL is required' });
    expect(validateExternalUrl(42 as any)).toEqual({ valid: false, error: 'URL is required' });
  });

  it('rejects malformed URLs', () => {
    const result = validateExternalUrl('not a url');
    expect(result.valid).toBe(false);
    expect(result.error).toBe('Invalid URL format');
  });

  it('rejects non-http/https schemes', () => {
    let result = validateExternalUrl('ftp://example.com');
    expect(result.valid).toBe(false);
    expect(result.error).toContain("Scheme 'ftp:' not allowed");
    result = validateExternalUrl('file:///etc/passwd');
    expect(result.valid).toBe(false);
    result = validateExternalUrl('javascript:alert(1)');
    expect(result.valid).toBe(false);
  });

  it('rejects localhost hostnames', () => {
    expect(validateExternalUrl('http://localhost/').valid).toBe(false);
    expect(validateExternalUrl('http://localhost.localdomain/').valid).toBe(false);
  });

  it('rejects loopback and private IPv4 ranges', () => {
    expect(validateExternalUrl('http://127.0.0.1:8080/').valid).toBe(false);
    expect(validateExternalUrl('http://10.0.0.1/').valid).toBe(false);
    expect(validateExternalUrl('http://192.168.1.1/').valid).toBe(false);
    expect(validateExternalUrl('http://169.254.169.254/latest/meta-data/').valid).toBe(false);
    expect(validateExternalUrl('http://0.0.0.0/').valid).toBe(false);
  });

  it('rejects 172.16.x.x through 172.31.x.x private range', () => {
    expect(validateExternalUrl('http://172.16.0.1/').valid).toBe(false);
    expect(validateExternalUrl('http://172.31.255.255/').valid).toBe(false);
  });

  it('accepts 172.15.x.x and 172.32.x.x which are outside the private range', () => {
    expect(validateExternalUrl('http://172.15.0.1/').valid).toBe(true);
    expect(validateExternalUrl('http://172.32.0.1/').valid).toBe(true);
  });

  it('rejects IPv6 loopback [::1]', () => {
    expect(validateExternalUrl('http://[::1]/').valid).toBe(false);
  });

  it('does not treat bracketed fc/fd IPv6 hostnames as private (no match)', () => {
    expect(validateExternalUrl('http://[fd00::1]/').valid).toBe(true);
    expect(validateExternalUrl('http://[fc00::1]/').valid).toBe(true);
  });

  it('blocks cloud metadata service IPs', () => {
    expect(validateExternalUrl('http://169.254.169.254/latest/meta-data/iam/security-credentials/').valid).toBe(false);
  });
});

/**
 * JWT Authentication Middleware for multi-tenant KB isolation.
 * SA4E-30: Replaces API-key-only auth with full JWT identity injection.
 * SA4E-50: validateSession is now async — safeValidateSession awaits it.
 *
 * Behavior:
 * - If CODE_INTEL_REQUIRE_AUTH=true -> JWT required on all /api/v1/* requests
 * - If CODE_INTEL_REQUIRE_AUTH is not set -> anonymous mode (backward compat)
 * - JWT claims: sub (userId), wid (workspaceId), pid (projectId)
 */

import type { MiddlewareHandler } from 'hono';
import { createProjectContext } from '../../modules/memory/ProjectContext.js';
import { validateSession } from '../../admin/admin-db.js';

const REQUIRE_AUTH = process.env.CODE_INTEL_REQUIRE_AUTH === 'true';
const TOKEN_SECRET = process.env.KB_TOKEN_SECRET || '';

/** Validate startup config. */
export function validateJwtConfig(): void {
  if (REQUIRE_AUTH && !TOKEN_SECRET) {
    throw new Error('KB_TOKEN_SECRET must be set when authentication is required');
  }
}

export function isJwtAuthRequired(): boolean {
  return REQUIRE_AUTH;
}

function decodeJwtPayload(token: string): Record<string, any> | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const payload = Buffer.from(parts[1], 'base64url').toString('utf8');
    return JSON.parse(payload);
  } catch {
    return null;
  }
}

async function verifyHs256(token: string, secret: string): Promise<boolean> {
  const [header, payload, signature] = token.split('.');
  const { createHmac } = await import('crypto');
  const expected = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');
  return signature === expected;
}

function isExpired(payload: Record<string, any>): boolean {
  if (!payload.exp) return false;
  return Date.now() >= payload.exp * 1000;
}

/**
 * Create a JWT auth middleware.
 * @param alwaysRequire When true, a valid token is ALWAYS required regardless of
 *   the global CODE_INTEL_REQUIRE_AUTH setting. Anonymous access is never allowed.
 *   Used for sensitive endpoints like indexing (no default/anonymous action).
 */
function createJwtAuth(alwaysRequire = false): MiddlewareHandler {
  return async (c, next) => {
    // X-Project-Id header is the mandatory source of project identity
    const projectId = c.req.header('X-Project-Id') || '';
    const authHeader = c.req.header('Authorization');
    const mustAuth = REQUIRE_AUTH || alwaysRequire;

    const anonymous = () => {
      const ctx = createProjectContext(projectId, 'anonymous');
      c.set('projectContext', ctx);
      return next();
    };

    const unauthorized = (code: string, message: string) =>
      c.json({ data: null, error: { code, message } }, 401);

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      if (mustAuth) return unauthorized('AUTH_REQUIRED', 'Authentication required');
      return anonymous();
    }

    const token = authHeader.slice(7);

    if (token.trim().length === 0) {
      if (mustAuth) return unauthorized('AUTH_REQUIRED', 'Authentication required');
      return anonymous();
    }

    // Two supported formats:
    //  1. JWT (header.payload.signature) — signed with KB_TOKEN_SECRET
    //  2. Admin session token — opaque hex, validated against sessions table
    const looksLikeJwt = token.split('.').length === 3;

    if (looksLikeJwt) {
      if (TOKEN_SECRET) {
        const valid = await verifyHs256(token, TOKEN_SECRET);
        if (!valid) {
          if (!mustAuth) return anonymous();
          return unauthorized('TOKEN_INVALID', 'Invalid or expired token');
        }
      }
      const payload = decodeJwtPayload(token);
      if (!payload || isExpired(payload)) {
        if (!mustAuth) return anonymous();
        return unauthorized('TOKEN_INVALID', 'Invalid or expired token');
      }
      const ctx = createProjectContext(
        projectId || payload.pid || '',
        payload.sub || 'anonymous',
        undefined,
        payload.wid || undefined,
      );
      c.set('projectContext', ctx);
      return next();
    }

    // SA4E-50: validateSession is now async — await it
    const session = await safeValidateSession(token);
    if (!session) {
      if (!mustAuth) return anonymous();
      return unauthorized('TOKEN_INVALID', 'Invalid or expired token');
    }
    const ctx = createProjectContext(projectId, session.userId);
    c.set('projectContext', ctx);
    return next();
  };
}

/** validateSession wrapped so a DB error never crashes auth (fails closed). */
async function safeValidateSession(
  token: string,
): Promise<{ userId: string; username: string; accessGroupId: string } | null> {
  try {
    return await validateSession(token);
  } catch {
    return null;
  }
}

export interface JwtVerification {
  /** True only for a well-formed, signature-valid, non-expired JWT. */
  valid: boolean;
  payload: Record<string, any> | null;
}

/**
 * Verify a bearer credential as a JWT.
 * SA4E-41 SEC-03: shared by the tools route to bind X-Project-Id to identity.
 * SA4E-55 SR-01: If KB_TOKEN_SECRET is not configured, JWT is rejected — never
 *   accept an unverified JWT payload as trusted identity.
 */
export async function verifyJwtToken(token: string): Promise<JwtVerification> {
  const looksLikeJwt = token.split('.').length === 3;
  if (!looksLikeJwt) return { valid: false, payload: null };
  // SR-01 fix: reject JWT when secret not configured — prevents forged identity
  if (!TOKEN_SECRET) return { valid: false, payload: null };
  const ok = await verifyHs256(token, TOKEN_SECRET);
  if (!ok) return { valid: false, payload: null };
  const payload = decodeJwtPayload(token);
  if (!payload || isExpired(payload)) return { valid: false, payload: null };
  return { valid: true, payload };
}

/** Extract the set of project ids a principal is granted from JWT claims. */
export function allowedProjectsFromClaims(payload: Record<string, any>): string[] {
  const out: string[] = [];
  if (typeof payload.pid === 'string' && payload.pid) out.push(payload.pid);
  if (Array.isArray(payload.pids)) {
    out.push(...payload.pids.filter((p: unknown): p is string => typeof p === 'string' && p.length > 0));
  }
  return out;
}

/** Standard JWT auth — anonymous allowed unless CODE_INTEL_REQUIRE_AUTH=true. */
export const jwtAuth: MiddlewareHandler = createJwtAuth(false);

/** Strict JWT auth — always requires a valid token, never anonymous. */
export const jwtAuthStrict: MiddlewareHandler = createJwtAuth(true);

/**
 * Integration tests for Admin Portal routes (Hono)
 * Tests: /admin SPA serving + /api/admin/* API endpoints
 * 
 * Uses real SQLite DB (admin.db) and real auth flow.
 * Default user: admin/admin (seeded on init).
 */

import { describe, it, expect, beforeAll } from 'vitest';
import { Hono } from 'hono';
import { createAdminRoute } from '../admin.js';
import pino from 'pino';

// Admin credentials from env (set by tests/vitest.setup.ts) — no hardcoded
// default (vuln-0001). Kept inline to avoid importing across the src rootDir.
const TEST_ADMIN_USERNAME = 'admin';
const TEST_ADMIN_PASSWORD = process.env.ADMIN_INITIAL_PASSWORD || 'test-admin-pw-01';

const logger = pino({ level: 'silent' });

let app: Hono;
let authToken: string;

beforeAll(async () => {
  app = new Hono();
  const adminRoute = createAdminRoute(logger);
  app.route('/', adminRoute);

  // Login to get real token
  const res = await app.request('/api/admin/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username: TEST_ADMIN_USERNAME, password: TEST_ADMIN_PASSWORD }),
  });
  const data = await res.json() as any;
  authToken = data.token;
});

function authHeaders() {
  return { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' };
}

describe('Admin Routes — /admin (SPA)', () => {
  it('GET /admin returns HTML or 404 when SPA file missing', async () => {
    const res = await app.request('/admin');
    expect([200, 404]).toContain(res.status);
    if (res.status === 200) {
      expect(res.headers.get('content-type')).toContain('text/html');
    }
  });

  it('GET /admin/dashboard returns SPA HTML (client-side routing)', async () => {
    const res = await app.request('/admin/dashboard');
    expect([200, 404]).toContain(res.status);
  });
});

describe('Admin Routes — /api/admin/auth', () => {
  it('POST /api/admin/auth/login with valid credentials returns token', async () => {
    const res = await app.request('/api/admin/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: TEST_ADMIN_USERNAME, password: TEST_ADMIN_PASSWORD }),
    });
    expect(res.status).toBe(200);
    const body = await res.json() as any;
    expect(body).toHaveProperty('token');
    expect(body).toHaveProperty('user');
    expect(body.user.username).toBe('admin');
    expect(body).toHaveProperty('expiresAt');
  });

  it('POST /api/admin/auth/login with invalid password returns 401', async () => {
    const res = await app.request('/api/admin/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: 'admin', password: 'wrong' }),
    });
    expect(res.status).toBe(401);
    const body = await res.json() as any;
    expect(body.error).toBe('Invalid credentials');
  });

  it('POST /api/admin/auth/login with unknown user returns 401', async () => {
    const res = await app.request('/api/admin/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: 'nobody', password: 'test' }),
    });
    expect(res.status).toBe(401);
  });

  it('GET /api/admin/auth/me returns current user info', async () => {
    const res = await app.request('/api/admin/auth/me', { headers: authHeaders() });
    expect(res.status).toBe(200);
    const body = await res.json() as any;
    expect(body.username).toBe('admin');
    expect(body.permissions).toContain('DASHBOARD_VIEW');
  });

  it('POST /api/admin/auth/logout invalidates session', async () => {
    // Login to get a new token
    const loginRes = await app.request('/api/admin/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: TEST_ADMIN_USERNAME, password: TEST_ADMIN_PASSWORD }),
    });
    const loginData = await loginRes.json() as any;
    const tempToken = loginData.token;

    // Logout
    const res = await app.request('/api/admin/auth/logout', {
      method: 'POST',
      headers: { Authorization: `Bearer ${tempToken}` },
    });
    expect(res.status).toBe(200);

    // Token should now be invalid
    const meRes = await app.request('/api/admin/auth/me', {
      headers: { Authorization: `Bearer ${tempToken}` },
    });
    expect(meRes.status).toBe(401);
  });
});

