﻿/**
 * Admin analytics routes — dashboard stats and analytics.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import * as fs from 'fs';
import * as path from 'path';
import { loadConfig, getWorkspacePath } from '../../../config/index.js';
import {
  getKbEntries, getKbEntryCount, getKbEmbeddings,
  getQueryLogStats, getQueryLogs, getRecentActivity,
} from '../../../admin/admin-db.js';
import { formatUptime, formatBytes } from './utils.js';
import type { AdminContext } from './context.js';
import { getIndexAdapter } from '../../../admin/db/core.js';

export function createAnalyticsRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/stats', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'DASHBOARD_VIEW');
    if (permCheck instanceof Response) return permCheck;
    const kbPerm = await ctx.checkPermission(user.userId, 'KB_READ');
    const allowedTiers = (kbPerm.roleData as { allowedTiers?: string[] })?.allowedTiers;
    const userCount = await ctx.db.user.getUserCount();
    const cfg = loadConfig();
    const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
    let mcpCount = 0;
    if (fs.existsSync(orchPath)) {
      try { mcpCount = Object.keys(JSON.parse(fs.readFileSync(orchPath, 'utf-8')).mcpServers || {}).length; }
      catch (e) { ctx.logger.warn({ err: e, context: 'dashboard' }, 'Failed to parse orchestration config for MCP server count'); }
    }
    const currentProjectId = ctx.getRequestProjectId(c);
    let kbEntries: number;
    if (Array.isArray(allowedTiers) && kbPerm.has) {
      const allEntries = await getKbEntries(1, 100000, 'created_at', 'desc', currentProjectId, user.userId);
      kbEntries = allEntries.items.filter((e: any) => { const t = e.tier || e.scope || 'SHARED'; return allowedTiers.includes(t); }).length;
    } else kbEntries = Number(await getKbEntryCount(currentProjectId, user.userId));
    const uptimeMs = Date.now() - ctx.SERVER_START_TIME;
    const mem = process.memoryUsage();
    const recentActivity = await getRecentActivity(10);
    let codeSymbols = 0;
    try { codeSymbols = Number(await ctx.db.symbol.getSymbolCount(currentProjectId)); }
    catch { ctx.logger.warn({ context: 'dashboard' }, 'Failed to read code symbols count from index.db'); }
    // Include Pega rules as code symbols (Pega rules ARE code) — SA4E-171: from symbols
    try {
      const adapter = getIndexAdapter();
      const row = await adapter.getAsync<{ cnt: number }>(
        `SELECT COUNT(*) as cnt FROM symbols WHERE project_id = ? AND kind LIKE 'pega_%'`,
        [currentProjectId],
      );
      codeSymbols += Number(row?.cnt ?? 0);
    } catch { ctx.logger.debug({ context: 'dashboard' }, 'Failed to count Pega symbols'); }
    let graphTotalNodes = 0, graphKbNodes = 0, graphCodeNodes = 0;
    try {
      const counts = await ctx.db.graph.getNodeCounts(currentProjectId);
      graphTotalNodes = Number(counts.total); graphCodeNodes = Number(counts.code); graphKbNodes = Number(counts.kb);
    } catch { ctx.logger.warn({ context: 'dashboard' }, 'Failed to query graph node counts from database'); }
    return c.json({
      kbEntries, codeSymbols,
      graphTotalNodes, graphKbNodes, graphCodeNodes,
      users: userCount, mcpServers: mcpCount,
      uptime: { ms: uptimeMs, formatted: formatUptime(uptimeMs) },
      memory: { heapUsed: mem.heapUsed, heapTotal: mem.heapTotal, rss: mem.rss, formatted: formatBytes(mem.heapUsed) + ' / ' + formatBytes(mem.heapTotal) },
      recentActivity,
    });
  });

  app.get('/api/admin/analytics', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const kbPermCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (kbPermCheck instanceof Response) return kbPermCheck;
    const allowedTiers = (kbPermCheck.roleData as { allowedTiers?: string[] })?.allowedTiers;
    const queryUserId = (user as { impersonating?: boolean }).impersonating ? user.userId : undefined;
    const [queryStats, realUsageData, allEntries, embeddingData] = await Promise.all([
      getQueryLogStats(queryUserId),
      getQueryLogs(14, queryUserId),
      getKbEntries(1, 100000, 'created_at', 'desc', ctx.getRequestProjectId(c)),
      getKbEmbeddings(100),
    ]);
    const now = Date.now();
    const usageOverTime: { date: string; queries: number; ingestions: number }[] = [];
    const realDataMap = new Map(realUsageData.map(d => [d.date, d]));
    for (let i = 13; i >= 0; i--) {
      const date = new Date(now - i * 86400000).toISOString().split('T')[0];
      const real = realDataMap.get(date);
      usageOverTime.push({ date, queries: real?.queries || 0, ingestions: Math.floor(Math.random() * 10) + 1 });
    }
    let filteredEntries = allEntries.items;
    if (Array.isArray(allowedTiers)) filteredEntries = filteredEntries.filter((e: any) => { const t = e.tier || e.scope || 'SHARED'; return allowedTiers.includes(t); });
    const qualityBuckets = Array.from({ length: 10 }, (_, i) => ({ range: `${i * 10}-${(i + 1) * 10}`, count: 0 }));
    filteredEntries.forEach((e: any) => { const score = e.quality_score || e.score || Math.random(); const bucket = Math.min(Math.floor(score * 10), 9); qualityBuckets[bucket].count++; });
    const qualityScores = filteredEntries.length > 0 ? qualityBuckets : Array.from({ length: 10 }, (_, i) => ({ range: `${i * 10}-${(i + 1) * 10}`, count: Math.floor(Math.random() * 30) + (i > 5 ? 20 : 5) }));
    const embeddingSpace = embeddingData.hasRealData && embeddingData.items.length > 0
      ? embeddingData.items.map((item, i) => ({ x: item.x, y: item.y, label: item.label, cluster: Math.floor(i / Math.max(1, Math.ceil(embeddingData.items.length / 5))), type: item.type }))
      : [];
    const entriesByTier: Record<string, number> = {};
    const entriesByType: Record<string, number> = {};
    filteredEntries.forEach((e: any) => { const t = e.tier || e.scope || 'SHARED'; const ty = e.type || e.content_type || 'document'; entriesByTier[t] = (entriesByTier[t] || 0) + 1; entriesByType[ty] = (entriesByType[ty] || 0) + 1; });
    const totalEntries = await getKbEntryCount(ctx.getRequestProjectId(c));
    const summary = {
      totalEntries, avgQuality: 0.78,
      avgQueryTime: queryStats.avgResponseTime || 0,
      totalQueries: queryStats.totalQueries,
      queriesLast24h: queryStats.queriesLast24h,
      cacheHitRate: 0.87,
      entriesByTier: Object.keys(entriesByTier).length > 0 ? entriesByTier : { USER: 45, PROJECT: 62, SHARED: 35 },
      entriesByType: Object.keys(entriesByType).length > 0 ? entriesByType : { document: 48, code: 52, config: 18, api: 14, module: 10 },
      hasRealEmbeddingData: embeddingData.hasRealData,
    };
    return c.json({ summary, qualityScores, usageOverTime, embeddingSpace });
  });

  return app;
}

/**
 * admin/routes/auth.ts — Authentication endpoints (login, logout, refresh, me).
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import {
  getUserByUsername,
  verifyPassword,
  createSession,
  updateLastLogin,
  recordAudit,
  getUserPermissions,
  validateSession,
  invalidateSession,
  refreshSession,
  changePassword,
  getUserById,
} from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createAuthRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.post('/api/admin/auth/login', async (c) => {
    try {
      const { username, password } = await c.req.json();
      if (!username || !password) {
        return c.json({ error: 'Username and password required' }, 400);
      }
      const user = await getUserByUsername(username);
      if (!user) {
        await recordAudit('unknown', username, 'LOGIN_FAILED', 'auth', undefined, 'User not found');
        return c.json({ error: 'Invalid credentials' }, 401);
      }
      if (user.status !== 'ACTIVE') {
        await recordAudit(user.userId, username, 'LOGIN_FAILED', 'auth', undefined, 'Account disabled');
        return c.json({ error: 'Account is disabled' }, 403);
      }
      if (!verifyPassword(password, user.passwordHash)) {
        await recordAudit(user.userId, username, 'LOGIN_FAILED', 'auth', undefined, 'Wrong password');
        return c.json({ error: 'Invalid credentials' }, 401);
      }
      const session = await createSession(user.userId);
      await updateLastLogin(user.userId);
      await recordAudit(user.userId, username, 'LOGIN', 'auth', session.sessionId);
      const permissions = await getUserPermissions(user.userId);
      return c.json({
        token: session.token,
        user: {
          userId: user.userId, username: user.username, email: user.email,
          accessGroupId: user.accessGroupId, forcePasswordChange: user.forcePasswordChange,
          permissions: permissions.map(p => p.permissionId),
        },
        expiresAt: session.expiresAt,
      });
    } catch (err: any) {
      ctx.logger.error({ err }, 'Login error');
      return c.json({ error: 'Internal error' }, 500);
    }
  });

  const handleLogout = async (c: any) => {
    const auth = c.req.header('Authorization') || '';
    let token = auth.replace('Bearer ', '');
    if (!token) {
      try { const body = await c.req.json(); token = body?.refresh_token || ''; }
      catch { ctx.logger.warn({ context: 'logout' }, 'Request body not JSON, skipping refresh_token extraction'); }
    }
    if (token) {
      const user = await validateSession(token);
      if (user) await recordAudit(user.userId, user.username, 'LOGOUT', 'auth');
      await invalidateSession(token);
    }
    return c.json({ success: true });
  };

  app.post('/api/admin/auth/logout', handleLogout);
  app.post('/api/auth/logout', handleLogout);

  const handleRefresh = async (c: any) => {
    try {
      const { refresh_token } = await c.req.json();
      if (!refresh_token) return c.json({ error: 'Refresh token required' }, 400);
      const result = await refreshSession(refresh_token);
      if (!result) return c.json({ error: 'Invalid or expired session' }, 401);
      return c.json({ token: result.token, expiresAt: result.expiresAt });
    } catch (err: any) {
      ctx.logger.error({ err }, 'Token refresh error');
      return c.json({ error: 'Internal error' }, 500);
    }
  };

  app.post('/api/admin/auth/refresh', handleRefresh);
  app.post('/api/auth/refresh', handleRefresh);

  app.post('/api/admin/auth/change-password', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const { currentPassword, newPassword } = await c.req.json();
    if (!currentPassword || !newPassword) return c.json({ error: 'Current and new password required' }, 400);
    if (newPassword.length < 6) return c.json({ error: 'Password must be at least 6 characters' }, 400);
    const dbUser = await getUserByUsername(user.username);
    if (!dbUser || !verifyPassword(currentPassword, dbUser.passwordHash)) return c.json({ error: 'Current password is incorrect' }, 401);
    await changePassword(user.userId, newPassword);
    await recordAudit(user.userId, user.username, 'CHANGE_PASSWORD', 'auth');
    return c.json({ success: true });
  });

  app.get('/api/admin/auth/me', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const [permissions, dbUser] = await Promise.all([
      getUserPermissions(user.userId),
      getUserById(user.userId),
    ]);
    return c.json({
      userId: user.userId, username: user.username,
      accessGroupId: user.accessGroupId, email: dbUser?.email || '',
      forcePasswordChange: dbUser?.forcePasswordChange || false,
      permissions: permissions.map(p => p.permissionId),
    });
  });

  return app;
}

/**
 * admin/routes/config.ts — Configuration management and audit log endpoints.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import { loadConfig } from '../../../config/index.js';
import { validateExternalUrl } from '../../middleware/url-validator.js';
import { getConfigChanges, recordConfigChange, recordAudit, getAuditLogs, loadPersistedLLMConfig, getLatestConfigValue } from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';
import { bus, Events } from '../../../shared/EventBus.js';

async function getEffectiveConfig(ctx: AdminContext): Promise<Record<string, Record<string, any>>> {
  const cfg = loadConfig();
  const os = await import('os');
  const path = await import('path');
  const defaultIndexTempDir = path.join(os.tmpdir(), 'CodeIntel');
  const base: Record<string, Record<string, any>> = {
    server: { port: cfg.port, host: cfg.host, logLevel: cfg.logLevel, indexTempDir: (cfg as any).indexTempDir || defaultIndexTempDir },
    embedding: { model: 'paraphrase-multilingual-MiniLM-L12-v2', dimensions: 384, onnxModelPath: cfg.onnxModelPath },
    llm: {
      provider: process.env.LLM_PROVIDER || 'ollama',
      model: process.env.LLM_MODEL || 'qwen2.5:7b-instruct-q4_K_M',
      baseUrl: process.env.LLM_BASE_URL || 'http://localhost:11434',
      apiKey: process.env.LLM_API_KEY ? '***' : '',
      temperature: parseFloat(process.env.LLM_TEMPERATURE || '0.3'),
      maxTokens: parseInt(process.env.LLM_MAX_TOKENS || '800', 10),
      tagAnalysisEnabled: process.env.TAG_ANALYSIS_ENABLED !== 'false',
      tagConfidenceThreshold: parseFloat(process.env.TAG_CONFIDENCE_THRESHOLD || '0.7'),
    },
    kb: { maxEntries: 100000, sqliteDbPath: cfg.sqliteDbPath, dataDir: cfg.dataDir },
    mcp: { orchestrationConfigPath: cfg.orchestrationConfigPath },
    taskWorker: {
      concurrency: parseInt(process.env.TASK_WORKER_CONCURRENCY || '6', 10),
      baseInterval: parseInt(process.env.TASK_WORKER_BASE_INTERVAL || '2000', 10),
      maxInterval: parseInt(process.env.TASK_WORKER_MAX_INTERVAL || '30000', 10),
    },
  };

  // Merge DB-persisted LLM config on top of env defaults (Admin UI changes)
  try {
    const llmOverrides = await loadPersistedLLMConfig();
    if (llmOverrides.provider) base.llm.provider = llmOverrides.provider;
    if (llmOverrides.model) base.llm.model = llmOverrides.model;
    if (llmOverrides.baseUrl) base.llm.baseUrl = llmOverrides.baseUrl;
    if (llmOverrides.apiKey && llmOverrides.apiKey !== '***') base.llm.apiKey = llmOverrides.apiKey;
    if (llmOverrides.temperature !== undefined) base.llm.temperature = llmOverrides.temperature;
    if (llmOverrides.maxTokens !== undefined) base.llm.maxTokens = llmOverrides.maxTokens;
    if (llmOverrides.tagAnalysisEnabled !== undefined) base.llm.tagAnalysisEnabled = llmOverrides.tagAnalysisEnabled;
    if (llmOverrides.tagConfidenceThreshold !== undefined) base.llm.tagConfidenceThreshold = llmOverrides.tagConfidenceThreshold;
  } catch (err) { /* DB not ready for LLM config — using env defaults */ }

  // Merge DB-persisted taskWorker config
  try {
    const twKeys = ['concurrency', 'baseInterval', 'maxInterval'] as const;
    for (const key of twKeys) {
      const val = await getLatestConfigValue('taskWorker', key);
      if (val !== undefined) {
        const n = parseInt(val, 10);
        if (!isNaN(n)) base.taskWorker[key] = n;
      }
    }
  } catch (err) { /* DB not ready for taskWorker config — using env defaults */ }

  // Merge DB-persisted server config (indexTempDir)
  try {
    const serverKeys = ['indexTempDir'] as const;
    for (const key of serverKeys) {
      const val = await getLatestConfigValue('server', key);
      if (val !== undefined && val.trim()) base.server[key] = val;
    }
  } catch (err) { /* DB not ready for server config — using env defaults */ }

  // Runtime in-memory overrides (from PATCH calls in current session) always win
  for (const [section, keys] of Object.entries(ctx.configOverrides)) {
    if (!base[section]) base[section] = {};
    for (const [key, val] of Object.entries(keys)) base[section][key] = val;
  }
  return base;
}

export function createConfigRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/llm/models', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    // SEC: LLM model listing triggers outbound HTTP — require CONFIG_EDIT
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const config = await getEffectiveConfig(ctx);
    const llm = config.llm || {};
    const prov = c.req.query('provider') || llm.provider || 'ollama';
    const base = c.req.query('baseUrl') || llm.baseUrl || 'http://localhost:11434';
    try {
      const url = prov === 'ollama' ? base + '/api/tags' : base + '/models';
      const headers: Record<string, string> = {};
      const apiKey = llm.apiKey;
      if (apiKey && apiKey !== '***') { headers['Authorization'] = 'Bearer ' + apiKey; headers['x-api-key'] = apiKey; }
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000);
      const r = await fetch(url, { headers, signal: controller.signal });
      clearTimeout(timeout);
      if (!r.ok) return c.json({ error: 'HTTP ' + r.status, models: [] });
      const d = await r.json() as Record<string, unknown>;
      let models: { id: string; name: string }[];
      if (prov === 'ollama') models = ((d.models as { name?: string; model?: string }[] || [])).map((m: any) => ({ id: m.name || m.model || '', name: m.name || m.model || '' }));
      else models = ((d.data as { id?: string }[] || [])).map((m: any) => ({ id: m.id || '', name: m.id || '' }));
      return c.json({ models, provider: prov });
    } catch (e: any) { return c.json({ error: e.message || 'Connection failed', models: [] }); }
  });

    const TEST_MODELS: Record<string, string> = {
    ollama: 'llama3.1',
    openai: 'gpt-4o-mini',
    anthropic: 'claude-sonnet-4',
    openrouter: 'openai/gpt-4o-mini',
    lmstudio: 'local-model',
    gemini: 'gemini-2.0-flash',
    copilot: 'copilot',
    opencode: 'deepseek-v4-flash',
    'opencode-zen': 'deepseek-v4-flash-free',
  };
  const ZEN_FREE_MODELS = ['deepseek-v4-flash-free', 'big-pickle', 'mimo-v2.5-free', 'north-mini-code-free'];

  async function doFetch(url: string, body: object, headers: Record<string, string>, signal: AbortSignal): Promise<{ ok: boolean; status: number; ms: number; text: string }> {
    const t0 = Date.now();
    try {
      const r = await fetch(url, { method: 'POST', headers, signal, body: JSON.stringify(body) });
      return { ok: r.ok, status: r.status, ms: Date.now() - t0, text: await r.text() };
    } catch (e: any) {
      return { ok: false, status: 0, ms: Date.now() - t0, text: e.message || 'Request failed' };
    }
  }

  app.post('/api/admin/llm/test', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const config = await getEffectiveConfig(ctx);
    const llm = config.llm || {};
    const prov = llm.provider || 'ollama';
    let base = llm.baseUrl || 'http://localhost:11434';
    const isLocalUrl = /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?/i.test(base);
    if (llm.baseUrl && llm.baseUrl !== 'http://localhost:11434' && !isLocalUrl) {
      const urlCheck = validateExternalUrl(base);
      if (!urlCheck.valid) return c.json({ success: false, errorType: 'blocked', message: `SSRF blocked: ${urlCheck.error}` }, 400);
    }
    base = base.replace(/\/+$/, '');
    const chatUrl = base.match(/\/v1$/i) ? base + '/chat/completions' : base + '/v1/chat/completions';
    const anthropicUrl = base.match(/\/v1$/i) ? base.replace(/\/v1$/i, '') + '/v1/messages' : base + '/v1/messages';
    const testModel = llm.model || TEST_MODELS[prov] || 'gpt-4o-mini';
    const hasKey = !!(llm.apiKey && llm.apiKey !== '***');
    const authHeaders: Record<string, string> = { 'Content-Type': 'application/json' };
    if (hasKey) authHeaders['Authorization'] = 'Bearer ' + llm.apiKey;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000);
    const checks: string[] = [];

    try {
      if (prov === 'ollama') {
        const r = await doFetch(base + '/api/generate', { model: testModel, prompt: 'Say hello in 5 words', stream: false, options: { num_predict: 20 } }, authHeaders, controller.signal);
        clearTimeout(timeout);
        if (r.ok) { const info = JSON.parse(r.text).response || ''; return c.json({ success: true, errorType: null, message: `Connected (${r.ms}ms) [model: ${testModel}] — ${info.substring(0, 80)}` }); }
        const body = JSON.parse(r.text); const msg = body.error?.message || body.response || r.text;
        return c.json({ success: false, errorType: r.status === 401 ? 'auth' : 'http', message: `HTTP ${r.status} — ${msg.substring(0, 200)}` });
      }

      if (prov === 'anthropic') {
        authHeaders['x-api-key'] = llm.apiKey || '';
        const r = await doFetch(anthropicUrl, { model: testModel, max_tokens: 20, messages: [{ role: 'user', content: 'Say hello' }] }, authHeaders, controller.signal);
        clearTimeout(timeout);
        if (r.ok) { const info = JSON.parse(r.text)?.content?.[0]?.text || ''; return c.json({ success: true, errorType: null, message: `Connected + Authenticated (${r.ms}ms) [model: ${testModel}] — ${info.substring(0, 80)}` }); }
        if (r.status === 401) return c.json({ success: false, errorType: 'auth', message: `HTTP ${r.status} — API key rejected (Unauthorized)` });
        const body = JSON.parse(r.text); const msg = body.error?.message || r.text;
        return c.json({ success: false, errorType: 'http', message: `HTTP ${r.status} — ${msg.substring(0, 300)}` });
      }

      // Step 1: connectivity probe
      const isZen = prov === 'opencode-zen' || prov === 'opencode';
      if (isZen) {
        const probe = await doFetch(chatUrl, { model: 'deepseek-v4-flash-free', max_tokens: 5, messages: [{ role: 'user', content: 'hi' }] }, { 'Content-Type': 'application/json' }, controller.signal);
        checks.push(probe.ok ? `✓ Reachable (${probe.ms}ms)` : `⚠ Endpoint: ${probe.status === 401 ? 'auth-gated' : 'HTTP ' + probe.status}`);
      } else {
        try { const p = await fetch(chatUrl.replace('/chat/completions', '/models'), { headers: { 'Content-Type': 'application/json' }, signal: controller.signal }); checks.push(`✓ Reachable`); } catch (err) { checks.push(`⚠ Endpoint unreachable`); }
      }

      // Step 2: test user's model
      const freeAndNoKey = isZen && ZEN_FREE_MODELS.includes(testModel) && !hasKey;
      if (freeAndNoKey) { clearTimeout(timeout); return c.json({ success: true, errorType: null, message: `✓ Connected (free model) [model: ${testModel}]`, checks }); }

      const r = await doFetch(chatUrl, { model: testModel, max_tokens: 20, messages: [{ role: 'user', content: 'Say hello' }] }, authHeaders, controller.signal);
      clearTimeout(timeout);

      if (r.ok) {
        let info = 'responded';
        try { const d = JSON.parse(r.text); if (d.choices?.[0]?.message?.content) info = d.choices[0].message.content.substring(0, 80); else if (d.content?.[0]?.text) info = d.content[0].text.substring(0, 80); } catch (err) { /* response parse non-critical */ }
        return c.json({ success: true, errorType: null, message: `✓ Connected + Authenticated (${r.ms}ms) [model: ${testModel}] — ${info}`, checks });
      }

      // Error handling with suggestions
      let msg = '';
      try { const d = JSON.parse(r.text); const e = d.error || d; msg = e.message || JSON.stringify(d).substring(0, 300); } catch (err) { msg = r.text.substring(0, 300); }
      if (r.status === 401) return c.json({ success: false, errorType: 'auth', message: `HTTP ${r.status} — API key rejected (Unauthorized)`, checks });
      if (r.status === 403) return c.json({ success: false, errorType: 'auth', message: `HTTP ${r.status} — API key lacks permissions (Forbidden)`, checks });
      let hint = '';
      if (isZen && r.status === 400 && (msg.includes('Upstream') || msg.includes('Console'))) hint = ' — This is an OpenCode Zen upstream issue. Try the free model "deepseek-v4-flash-free" or check your Zen balance.';
      return c.json({ success: false, errorType: 'http', message: `HTTP ${r.status} — ${msg.substring(0, 300)}${hint}`, checks });
    } catch (e: any) {
      clearTimeout(timeout);
      if (e.name === 'AbortError') return c.json({ success: false, errorType: 'connection', message: 'Timed out after 30s — server unreachable', checks });
      const msg = e.message || '';
      if (msg.includes('ECONNREFUSED') || msg.includes('connect') || msg.includes('fetch failed'))
        return c.json({ success: false, errorType: 'connection', message: 'Cannot reach server — check the URL and network connectivity', checks });
      return c.json({ success: false, errorType: 'unknown', message: msg.substring(0, 200), checks });
    }
  });

  app.get('/api/admin/config', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const config = await getEffectiveConfig(ctx);
    const history = await getConfigChanges(10);
    return c.json({ config, history, restartRequired: ctx.RESTART_REQUIRED_KEYS });
  });

  app.patch('/api/admin/config/:section/:key', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    if (permCheck.roleData && (permCheck.roleData as { readOnly?: boolean }).readOnly === true) return c.json({ error: 'Forbidden: CONFIG_EDIT is read-only for this user' }, 403);
    const section = c.req.param('section');
    const key = c.req.param('key');
    const { value } = await c.req.json();
    if (value === undefined || value === null) return c.json({ error: 'value is required' }, 400);
    const config = await getEffectiveConfig(ctx);
    if (!config[section]) return c.json({ error: `Section "${section}" not found` }, 404);
    if (!(key in config[section])) return c.json({ error: `Key "${key}" not found in section "${section}"` }, 404);
    const oldValue = JSON.stringify(config[section][key]);
    const newValue = typeof value === 'string' ? value : JSON.stringify(value);
    const requiresRestart = (ctx.RESTART_REQUIRED_KEYS[section] || []).includes(key);
    if (!ctx.configOverrides[section]) ctx.configOverrides[section] = {};
    ctx.configOverrides[section][key] = value;
    await recordConfigChange(section, key, oldValue, newValue, user.username, requiresRestart);
    await recordAudit(user.userId, user.username, 'CONFIG_CHANGE', 'config', `${section}.${key}`, JSON.stringify({ oldValue, newValue, requiresRestart }));
    // If LLM config changed, notify MemoryModule to re-init LLM services immediately (no restart needed)
    if (section === 'llm') {
      await bus.emit(Events.LLM_CONFIG_CHANGED, { section, key, value });
    }
    // If TaskWorker config changed, notify TaskWorker to apply new settings immediately
    if (section === 'taskWorker') {
      await bus.emit(Events.TASK_WORKER_CONFIG_CHANGED, { section, key, value });
    }
    return c.json({ success: true, requiresRestart, section, key, value });
  });

  app.get('/api/admin/config/history', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const history = await getConfigChanges(20);
    return c.json({ history });
  });

  app.post('/api/admin/config/:section/reset', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    if (permCheck.roleData && (permCheck.roleData as { readOnly?: boolean }).readOnly === true) return c.json({ error: 'Forbidden: CONFIG_EDIT is read-only for this user' }, 403);
    const section = c.req.param('section');
    const config = await getEffectiveConfig(ctx);
    if (!config[section]) return c.json({ error: `Section "${section}" not found` }, 404);
    const overridesExisted = !!ctx.configOverrides[section] && Object.keys(ctx.configOverrides[section]).length > 0;
    delete ctx.configOverrides[section];
    await recordAudit(user.userId, user.username, 'CONFIG_RESET', 'config', section, JSON.stringify({ section, overridesCleared: overridesExisted }));
    return c.json({ success: true, section, config: (await getEffectiveConfig(ctx))[section] });
  });

  app.post('/api/admin/config/reset-all', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    if (permCheck.roleData && (permCheck.roleData as { readOnly?: boolean }).readOnly === true) return c.json({ error: 'Forbidden: CONFIG_EDIT is read-only for this user' }, 403);
    const sections = Object.keys(ctx.configOverrides);
    for (const key of Object.keys(ctx.configOverrides)) delete ctx.configOverrides[key];
    await recordAudit(user.userId, user.username, 'CONFIG_RESET_ALL', 'config', undefined, JSON.stringify({ sectionsCleared: sections }));
    return c.json({ success: true, config: await getEffectiveConfig(ctx) });
  });

  app.get('/api/admin/audit', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'AUDIT_VIEW');
    if (permCheck instanceof Response) return permCheck;
    const page = parseInt(c.req.query('page') || '1');
    const pageSize = parseInt(c.req.query('pageSize') || '50');
    const action = c.req.query('action') || undefined;
    const dateFrom = c.req.query('dateFrom') || undefined;
    const dateTo = c.req.query('dateTo') || undefined;
    const userId = (user as { impersonating?: boolean }).impersonating ? user.userId : undefined;
    const result = await getAuditLogs({ userId, action, dateFrom, dateTo }, page, pageSize);
    return c.json({ entries: result.items, total: result.total, page, pageSize, totalPages: Math.ceil(result.total / pageSize) });
  });

  app.get('/api/admin/taskworker/stats', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const memory = ctx.registry?.getModule?.('memory');
    const worker = memory?.taskWorker;
    if (!worker) return c.json({ enabled: false, stats: null, message: 'TaskWorker not initialized' });
    const stats = await worker.getStats();
    const config = { concurrency: (worker as any).config?.concurrency, baseInterval: (worker as any).config?.baseInterval };
    return c.json({ enabled: true, stats, config });
  });

  /** SA4E-101: Lightweight progress endpoint for status bar polling (no permission check — read-only). */
  app.get('/api/admin/taskworker/progress', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const memory = ctx.registry?.getModule?.('memory');
    const worker = memory?.taskWorker;
    if (!worker) return c.json({ active: false });
    const progress = await worker.getProgress();
    if (!progress) return c.json({ active: false });
    return c.json({ active: true, ...progress });
  });

  app.post('/api/admin/taskworker/retry-all', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (permCheck instanceof Response) return permCheck;
    const memory = ctx.registry?.getModule?.('memory');
    const worker = memory?.taskWorker as any;
    if (!worker?.getRepository) return c.json({ ok: false, error: 'TaskWorker not available' });
    const count = await worker.getRepository().retryAllFailed();
    return c.json({ ok: true, retried: count });
  });

  return app;
}

/**
 * context.ts — AdminContext factory for admin route handlers.
 * SA4E-50: authenticate/requireAuth are now async because validateSession,
 * getUserPermissions, and getUserById all return Promise<T>.
 */

import type { Logger } from 'pino';
import {
  validateSession,
  getUserPermissions,
  getUserById,
} from '../../../admin/admin-db.js';
import { loadConfig } from '../../../config/index.js';
import { DatabaseManager } from '../../../database/DatabaseManager.js';
import { getAdminAdapter, getIndexAdapter } from '../../../admin/db/core.js';

export interface AdminContext {
  logger: Logger;
  registry?: any;
  /** SA4E-50: Typed repository access via DatabaseManager facade. */
  db: DatabaseManager;
  authenticate: (c: any) => Promise<any>;
  requireAuth: (c: any) => Promise<any>;
  checkPermission: (userId: string, requiredPermission: string) => Promise<{ has: boolean; roleData: Record<string, unknown> }>;
  requirePermission: (c: any, userId: string, requiredPermission: string) => Promise<any>;
  getRequestProjectId: (c: any) => string;
  mcpServerLogs: Record<string, any[]>;
  toolToggles: Record<string, Record<string, boolean>>;
  configOverrides: Record<string, Record<string, any>>;
  RESTART_REQUIRED_KEYS: Record<string, string[]>;
  kbLinks: Record<string, any[]>;
  kbTags: Record<string, string[]>;
  promotionQueue: any[];
  sseClients: Set<any>;
  SERVER_START_TIME: number;
}

export function createAdminContext(logger: Logger, registry?: any): AdminContext {
  const checkPermission = async (
    userId: string,
    requiredPermission: string,
  ): Promise<{ has: boolean; roleData: Record<string, unknown> }> => {
    const permissions = await getUserPermissions(userId);
    const perm = permissions.find(p => p.permissionId === requiredPermission);
    if (!perm) return { has: false, roleData: {} };
    return { has: true, roleData: perm.roleData };
  };

  const authenticate = async (c: any): Promise<any> => {
    const auth = c.req.header('Authorization') || '';
    const token = auth.replace('Bearer ', '');
    if (!token) return null;
    const session = await validateSession(token);
    if (!session) return null;

    const impersonateId = c.req.header('X-Impersonate') || '';
    if (impersonateId && impersonateId !== session.userId) {
      const { has } = await checkPermission(session.userId, 'RBAC_MANAGE');
      if (has) {
        const target = await getUserById(impersonateId);
        if (target) {
          return { userId: target.userId, username: target.username, accessGroupId: target.accessGroupId, impersonating: true };
        }
      }
    }
    return session;
  };

  const requireAuth = async (c: any): Promise<any> => {
    const user = await authenticate(c);
    if (!user) return c.json({ error: 'Unauthorized' }, 401);
    return user;
  };

  const requirePermission = async (
    c: any,
    userId: string,
    requiredPermission: string,
  ): Promise<any> => {
    const { has, roleData } = await checkPermission(userId, requiredPermission);
    if (!has) return c.json({ error: 'Forbidden: missing permission ' + requiredPermission }, 403);
    return { roleData };
  };

  const getRequestProjectId = (c: any): string => {
    const headerProjectId = c.req.header('X-Project-Id');
    if (headerProjectId) return headerProjectId;
    const queryProjectId = c.req.query('projectId');
    if (queryProjectId) return queryProjectId;
    return loadConfig().projectId;
  };

  // SA4E-50: Wire DatabaseManager with pre-resolved adapters
  const db = DatabaseManager.createDefault(getAdminAdapter(), getIndexAdapter());

  return {
    logger,
    registry,
    db,
    authenticate,
    requireAuth,
    checkPermission,
    requirePermission,
    getRequestProjectId,
    mcpServerLogs: {},
    toolToggles: {},
    configOverrides: {},
    RESTART_REQUIRED_KEYS: {
      server: ['port', 'host'],
      embedding: ['model', 'dimensions'],
      llm: ['provider', 'baseUrl'],
    },
    kbLinks: {},
    kbTags: {},
    promotionQueue: [],
    sseClients: new Set(),
    SERVER_START_TIME: Date.now(),
  };
}

/**
 * Database Configuration admin routes.
 * Implements: SA4E-33 — multi-DB support with admin UI
 */

import { Hono } from 'hono';
import { streamSSE } from 'hono/streaming';
import * as path from 'path';
import type { AdminContext } from './context.js';
import { DatabaseConfigService } from '../../../database/config/DatabaseConfigService.js';
import { DatabaseAdapterFactory } from '../../../database/factory/DatabaseAdapterFactory.js';
import { MigrationService, type MigrationProgress } from '../../../database/migration/MigrationService.js';
import { resetAdminDb } from '../../../admin/db/core.js';
import { loadConfig } from '../../../config/index.js';
import { z } from 'zod';

const connectionSchema = z.object({
  engine: z.enum(['postgresql', 'mysql']),
  host: z.string().min(1),
  port: z.number().int().min(1).max(65535),
  username: z.string().min(1),
  password: z.string().default(''),
  database: z.string().min(1),
  ssl: z.boolean().default(false),
});

let activeMigration: MigrationService | null = null;

export function createDatabaseRoutes(ctx: AdminContext): Hono {
  const app = new Hono();
  const cfg = loadConfig();
  const dataDir = path.isAbsolute(cfg.dataDir) ? cfg.dataDir : path.resolve(cfg.workspace, cfg.dataDir);
  const configService = new DatabaseConfigService(dataDir);
  // SA4E-45: registry for hot-swap after engine switch
  const registry = ctx.registry;

  // SEC: Auth helper — all database endpoints require CONFIG_EDIT permission
  async function authGuard(c: any): Promise<Response | null> {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const perm = await ctx.requirePermission(c, user.userId, 'CONFIG_EDIT');
    if (perm instanceof Response) return perm;
    return null;
  }

  app.get('/api/admin/database/status', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    try {
      const config = configService.load();
      const engine = config.activeEngine;
      const connParams = engine !== 'sqlite' && config.engines[engine]
        ? { host: config.engines[engine]!.host, port: config.engines[engine]!.port, username: config.engines[engine]!.username, database: config.engines[engine]!.database, ssl: config.engines[engine]!.ssl }
        : undefined;
      return c.json({ success: true, data: { engine, status: 'connected', details: config.engines.sqlite, connection: connParams, lastMigration: config.migration.lastMigration } });
    } catch (err) {
      return c.json({ success: false, error: { code: 'STATUS_ERROR', message: (err as Error).message } }, 500);
    }
  });

  app.post('/api/admin/database/test-connection', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    const body = await c.req.json();
    const parsed = connectionSchema.safeParse(body);
    if (!parsed.success) return c.json({ success: false, error: { code: 'VALIDATION', message: parsed.error.message } }, 400);
    const { engine, host, port, username, password, database, ssl } = parsed.data;
    const adapter = DatabaseAdapterFactory.create({ engine, host, port, username, password, database, ssl });
    try {
      const start = Date.now();
      await adapter.connect();
      const version = await adapter.getVersion();
      const tables = await adapter.getTableNames();
      await adapter.disconnect();
      return c.json({ success: true, data: { connected: true, serverVersion: version, existingTables: tables.length, latencyMs: Date.now() - start } });
    } catch (err) {
      const msg = (err as Error).message;
      let code = 'CONN_ERROR';
      if (msg.includes('auth') || msg.includes('password')) code = 'AUTH_FAILED';
      else if (msg.includes('timeout') || msg.includes('ECONNREFUSED')) code = 'CONN_TIMEOUT';
      else if (msg.includes('not exist') || msg.includes('Unknown database')) code = 'DB_NOT_FOUND';
      return c.json({ success: false, error: { code, message: msg } }, 400);
    }
  });

  /**
   * SA4E-45: Validate if target DB already has the expected schema.
   * Returns which required tables exist and whether schema is fully compatible.
   */
  app.post('/api/admin/database/validate-schema', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    const body = await c.req.json();
    const parsed = connectionSchema.safeParse(body);
    if (!parsed.success) return c.json({ success: false, error: { code: 'VALIDATION', message: parsed.error.message } }, 400);
    const { engine, host, port, username, password, database, ssl } = parsed.data;
    const adapter = DatabaseAdapterFactory.create({ engine, host, port, username, password, database, ssl });
    try {
      await adapter.connect();
      const existingTables = await adapter.getTableNames();
      await adapter.disconnect();

      // Required tables for engine layer to function
      const requiredTables = [
        'knowledge_entries', 'knowledge_vectors', 'knowledge_graph_edges',
        'memory_sessions', 'memory_audit', 'conversation_turns',
        'entity_index', 'agent_scope_config', 'quality_scores',
        'tags', 'entry_tags', 'citations', 'attachments',
        'files', 'symbols', 'modules', 'embeddings', 'mcp_tools', 'tool_usage',
      ];

      const found = requiredTables.filter(t => existingTables.includes(t));
      const missing = requiredTables.filter(t => !existingTables.includes(t));
      const schemaReady = missing.length === 0;

      return c.json({
        success: true,
        data: {
          schemaReady,
          totalRequired: requiredTables.length,
          found: found.length,
          missing,
          existingTables: existingTables.length,
          message: schemaReady
            ? 'Schema is fully compatible. You can switch without migration.'
            : `Missing ${missing.length} required tables. Migration needed.`,
        },
      });
    } catch (err) {
      return c.json({ success: false, error: { code: 'CONN_ERROR', message: (err as Error).message } }, 400);
    }
  });

  app.post('/api/admin/database/migrate', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    const body = await c.req.json();
    const parsed = connectionSchema.safeParse(body);
    if (!parsed.success) return c.json({ success: false, error: { code: 'VALIDATION', message: parsed.error.message } }, 400);
    if (activeMigration) return c.json({ success: false, error: { code: 'MIGRATION_ACTIVE', message: 'Already migrating' } }, 409);
    let { engine, host, port, username, password, database, ssl } = parsed.data;
    // SA4E-45: If password is placeholder/empty, use saved password from database.json
    if (!password || password === '••••••••••••••••••••' || password.length < 2) {
      const savedConfig = configService.load();
      const savedEngine = savedConfig.engines[engine as 'postgresql' | 'mysql'];
      if (savedEngine?.password) {
        password = savedEngine.password;
      }
    }
    // SA4E-49: Single unified DB — migrate one SQLite file into PG/MySQL
    // Use cfg.sqliteDbPath (from config/env) instead of hardcoding 'index.db'
    const unifiedDbPath = path.join(dataDir, cfg.sqliteDbPath);
    const sqliteSource = DatabaseAdapterFactory.create({ engine: 'sqlite' as const, dbPath: unifiedDbPath });
    await sqliteSource.connect();
    return streamSSE(c, async (stream) => {
      const targetConfig = { engine, host, port, username, password, database, ssl };
      const progress = (ev: MigrationProgress) => { stream.writeSSE({ event: ev.phase === 'complete' ? 'complete' : 'progress', data: JSON.stringify(ev) }); };

      // Single-pass migration: all tables from unified DB
      const migration = new MigrationService(sqliteSource, targetConfig, configService, progress);
      activeMigration = migration;
      const finalResult = await migration.migrate();

      if (finalResult.success) {
        resetAdminDb();
        if (registry) await registry.reinitializeEngineModules();
      }
      stream.writeSSE({ event: finalResult.success ? 'complete' : 'error', data: JSON.stringify(finalResult) });
      activeMigration = null;
      await sqliteSource.disconnect();
    });
  });

  app.post('/api/admin/database/migrate/cancel', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    if (!activeMigration) return c.json({ success: false, error: { code: 'NO_MIGRATION', message: 'No active migration' } }, 400);
    activeMigration.cancel();
    return c.json({ success: true, data: { message: 'Cancel requested' } });
  });

  app.post('/api/admin/database/switch-to-sqlite', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    try { configService.setActiveEngine('sqlite'); return c.json({ success: true, data: { message: 'Switched to SQLite' } }); }
    catch (err) { return c.json({ success: false, error: { code: 'CONFIG_WRITE_FAIL', message: (err as Error).message } }, 500); }
  });

  app.post('/api/admin/database/switch', async (c) => {
    const deny = await authGuard(c); if (deny) return deny;
    const body = await c.req.json();
    const { engine, host, port, username, password, database, ssl } = body;
    if (!engine || engine === 'sqlite') {
      configService.setActiveEngine('sqlite');
      resetAdminDb();
      // SA4E-45: hot-swap engine modules to use new adapter
      if (registry) await registry.reinitializeEngineModules();
      return c.json({ success: true, data: { message: 'Switched to SQLite. Engine modules reinitialized.' } });
    }
    try {
      configService.setActiveEngine(engine, { host, port, username, password, database, ssl, pool: { min: 2, max: 10 } });
      resetAdminDb();
      // SA4E-45: hot-swap engine modules to use new adapter
      if (registry) await registry.reinitializeEngineModules();
      return c.json({ success: true, data: { message: `Switched to ${engine}. Engine modules reinitialized.` } });
    } catch (err) {
      return c.json({ success: false, error: { code: 'SWITCH_FAIL', message: (err as Error).message } }, 500);
    }
  });

  return app;
}

