/** GET /api/admin/projects — list registered workspaces from project_registry. */
function createProjectsRoutes(ctx: AdminContext): Hono {
  const app = new Hono();
  app.get('/api/admin/projects', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    try {
      const adapter = getAdminAdapter();
      // RBAC_MANAGE (admins) see all workspaces; others only see their own
      const rbacCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
      const isAdmin = !(rbacCheck instanceof Response);
      const rows = isAdmin
        ? await adapter.allAsync<{ project_id: string; display_name: string; workspace_path: string; last_seen: string }>(
            'SELECT project_id, display_name, workspace_path, last_seen FROM project_registry ORDER BY last_seen DESC LIMIT 100'
          )
        : await adapter.allAsync<{ project_id: string; display_name: string; workspace_path: string; last_seen: string }>(
            'SELECT project_id, display_name, workspace_path, last_seen FROM project_registry WHERE created_by = ? OR created_by = ? ORDER BY last_seen DESC LIMIT 100',
            [user.userId, user.username ?? '']
          );
      return c.json({ projects: rows });
    } catch {
      return c.json({ projects: [] });
    }
  });
  return app;
}

export function createAdminRoute(logger: Logger, registry?: any): Hono {
  const ctx = createAdminContext(logger, registry);
  // getAdminDb() removed — only called when engine is sqlite (lazy init)

  const app = new Hono();

  app.route('/', createStaticRoutes(ctx));
  app.route('/', createAuthRoutes(ctx));
  app.route('/', createUsersRoutes(ctx));
  app.route('/', createRbacRoutes(ctx));
  app.route('/', createMcpRoutes(ctx));
  app.route('/', createMcpCrudRoutes(ctx));
  app.route('/', createConfigRoutes(ctx));
  app.route('/', createKbEntriesRoutes(ctx));
  app.route('/', createKbGraphRoutes(ctx));
  app.route('/', createKbGraphSpatialRoutes(ctx));
  app.route('/', createKbTagsRoutes(ctx));
  app.route('/', createKbOperationsRoutes(ctx));
  app.route('/', createKbQualityRoutes(ctx));
  app.route('/', createAnalyticsRoutes(ctx));
  app.route('/', createSseRoutes(ctx));
  app.route('/', createDatabaseRoutes(ctx));
  app.route('/', createProjectsRoutes(ctx));

  logger.info('Admin portal routes registered: /admin + /api/admin/* (with auth, SSE)');
  return app;
}

/**
 * KB entries routes — search, list, and detail for KB entries.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import {
  getKbEntries, getKbEntryCount, getKbEntryById,
  searchKbEntries, recordQueryLog,
} from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createKbEntriesRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.post('/api/admin/search', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'SEARCH_EXPLORE');
    if (permCheck instanceof Response) return permCheck;
    const maxResults = (permCheck.roleData as any)?.maxResults;
    const { query, debug } = await c.req.json();
    if (!query) return c.json({ results: [] });
    const startTime = Date.now();
    const realResults = await searchKbEntries(query, ctx.getRequestProjectId(c));
    if (realResults.items.length > 0) {
      const responseTimeMs = Date.now() - startTime;
      await recordQueryLog(query, responseTimeMs, realResults.items.length, user.userId);
      const resultLimit = (typeof maxResults === 'number' && maxResults > 0) ? Math.min(maxResults, 20) : 20;
      const results = realResults.items.slice(0, resultLimit).map((item: any) => ({
        id: item.id || item.entry_id || 'unknown',
        source: item.source || item.summary || 'unknown',
        content: (item.content || '').substring(0, 300),
        tier: item.tier || 'SHARED',
        score: item.score || 0.5,
        scores: item.scores || { similarity: +(item.score || 0.5).toFixed(3), keyword: 0, recency: 0, quality: 0 },
      }));
      return c.json({ results, debug: debug ? { queryTokens: query.split(/\s+/), totalCandidates: realResults.total, searchTimeMs: responseTimeMs } : undefined });
    }
    const mockResults = [
      { id: 'e1', source: 'project-structure', content: 'Code Intelligence indexes the project for semantic search and navigation...', tier: 'SHARED', score: 0.92, scores: { similarity: 0.85, keyword: 0.95, recency: 0.90, quality: 0.98 } },
      { id: 'e2', source: 'admin-portal', content: 'Admin portal provides web-based management of KB entries, users, and MCP servers...', tier: 'PROJECT', score: 0.87, scores: { similarity: 0.82, keyword: 0.88, recency: 0.85, quality: 0.93 } },
      { id: 'e3', source: 'mcp-integration', content: 'MCP servers are orchestrated through orchestration.json configuration...', tier: 'SHARED', score: 0.79, scores: { similarity: 0.75, keyword: 0.72, recency: 0.95, quality: 0.74 } },
    ];
    const filtered = mockResults.filter(r => r.source.toLowerCase().includes(query.toLowerCase()) || r.content.toLowerCase().includes(query.toLowerCase()));
    const responseTimeMs = Date.now() - startTime;
    let finalResults = filtered.length > 0 ? filtered : mockResults.slice(0, 2);
    if (typeof maxResults === 'number' && maxResults > 0) finalResults = finalResults.slice(0, maxResults);
    await recordQueryLog(query, responseTimeMs, finalResults.length, user.userId);
    return c.json({ results: finalResults, debug: debug ? { queryTokens: query.split(/\s+/), totalCandidates: 42, searchTimeMs: responseTimeMs } : undefined });
  });

  app.get('/api/admin/kb/entries', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const page = parseInt(c.req.query('page') || '1');
    const pageSize = parseInt(c.req.query('pageSize') || '20');
    const sortBy = c.req.query('sortBy') || 'created_at';
    const sortDir = (c.req.query('sortDir') || 'desc') as 'asc' | 'desc';
    const result = await getKbEntries(page, pageSize, sortBy, sortDir, ctx.getRequestProjectId(c));
    const allowedTiers = (permCheck.roleData as any)?.allowedTiers;
    let entries = result.items;
    if (Array.isArray(allowedTiers)) entries = entries.filter((e: any) => { const t = e.tier || e.scope || 'SHARED'; return allowedTiers.includes(t); });
    return c.json({ entries, total: Array.isArray(allowedTiers) ? entries.length : result.total, page, pageSize, totalPages: Math.ceil((Array.isArray(allowedTiers) ? entries.length : result.total) / pageSize) });
  });

  app.get('/api/admin/kb/entries/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    let entryId = c.req.param('id');

    // SA4E-171: legacy "pega:FQN" graph node ids → resolve to Pega symbol (code:{symbolId})
    if (entryId.startsWith('pega:')) {
      const resolved = await resolvePegaSymbolId(ctx, entryId.replace('pega:', ''));
      if (!resolved) return c.json({ error: 'Pega rule not found' }, 404);
      entryId = `code:${resolved}`;
    }

    if (entryId.startsWith('code:') || entryId.startsWith('sym-')) {
      const symbolId = entryId.startsWith('code:') ? entryId.replace('code:', '') : entryId.replace('sym-', '');
      const detail = await getCodeSymbolDetail(symbolId, ctx);
      if (detail) return c.json(detail);
      return c.json({ error: 'Code symbol not found' }, 404);
    }

    const lookupId = entryId.startsWith('doc-') ? entryId.replace('doc-', '') : entryId;
    const entry = await getKbEntryById(lookupId);
    if (!entry) return c.json({ error: 'Entry not found' }, 404);
    const allowedTiers = (permCheck.roleData as any)?.allowedTiers;
    if (Array.isArray(allowedTiers)) {
      const entryTier = entry.tier || entry.scope || 'SHARED';
      if (!allowedTiers.includes(entryTier)) return c.json({ error: 'Forbidden: entry tier not in allowedTiers' }, 403);
    }
    const tags = ctx.kbTags[entryId] || [];
    const links = ctx.kbLinks[entryId] || [];
    return c.json({
      id: entry.id || entry.entry_id || entryId,
      title: entry.title || entry.source || 'Untitled',
      content: entry.content || '',
      tier: entry.tier || entry.scope || 'SHARED',
      type: entry.content_type || entry.type || 'document',
      source: entry.source || '',
      tags, links,
      qualityScore: entry.quality_score || entry.score || null,
      createdAt: entry.created_at || null,
      updatedAt: entry.updated_at || null,
    });
  });

  /** On-demand enrichment: trigger LLM enrichment for a single unenriched entry. */
  app.post('/api/admin/kb/entries/:id/enrich', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    let entryId = c.req.param('id');

    const { getIndexAdapter } = await import('../../../admin/db/core.js');
    const indexAdapter = getIndexAdapter();
    const projectId = ctx.getRequestProjectId(c);

    // SA4E-171: legacy "pega:FQN" graph node ids → resolve to Pega symbol, enrich via CODE_ENRICHMENT
    if (entryId.startsWith('pega:')) {
      const resolved = await resolvePegaSymbolId(ctx, entryId.replace('pega:', ''));
      if (!resolved) return c.json({ error: 'Pega rule not found' }, 404);
      entryId = `code:${resolved}`;
    }

    // Branch: KB entries (non-symbol) — enrich via TAG_ENRICHMENT flow
    if (entryId.startsWith('kb-entry:')) {
      const numericId = parseInt(entryId.replace('kb-entry:', ''), 10);
      const entry = await indexAdapter.getAsync<{ id: number; content: string; summary: string | null; enrichment_status: string | null; structured_map: string | null }>(
        'SELECT id, content, summary, enrichment_status, structured_map FROM knowledge_entries WHERE id = ?', [numericId]);
      if (!entry) return c.json({ error: 'Entry not found' }, 404);
      if (entry.enrichment_status === 'done') {
        const map = entry.structured_map ? JSON.parse(entry.structured_map) : {};
        return c.json({ status: 'already_enriched', enrichment: { summary: map.summary || entry.summary, pseudoCode: null, llmTags: map.tags || null, status: 'COMPLETED' } });
      }
      try {
        const { PendingTaskRepository } = await import('../../../modules/memory/task-queue/PendingTaskRepository.js');
        const { TaskType } = await import('../../../modules/memory/task-queue/models.js');
        const taskRepo = new PendingTaskRepository(indexAdapter);
        await taskRepo.create({
          task_type: TaskType.TAG_ENRICHMENT,
          entry_id: entry.id,
          payload: { entry_id: entry.id, content: (entry.summary || entry.content || '').slice(0, 2000), existing_tags: '', options: { threshold: 0.6, autoApply: true } },
        });
        return c.json({ status: 'queued', message: 'Enrichment task created. Will be processed by background worker.' });
      } catch (err: any) {
        return c.json({ status: 'error', message: err.message }, 500);
      }
    }

    // Branch: Code symbols (original flow)
    if (!entryId.startsWith('code:') && !entryId.startsWith('sym-')) {
      return c.json({ error: 'Unsupported entry type for on-demand enrichment' }, 400);
    }
    const symbolId = entryId.startsWith('code:') ? entryId.replace('code:', '') : entryId.replace('sym-', '');
    const numId = parseInt(symbolId, 10);
    if (isNaN(numId)) return c.json({ error: 'Invalid symbol ID' }, 400);

    // Check if already enriched
    const sym = await indexAdapter.getAsync<{ enrichment_status: string | null; kind: string; name: string; file_id: number }>(
      'SELECT enrichment_status, kind, name, file_id FROM symbols WHERE id = ?', [numId],
    );
    if (!sym) return c.json({ error: 'Symbol not found' }, 404);
    if (sym.enrichment_status === 'COMPLETED') {
      return c.json({ status: 'already_enriched', message: 'Symbol already has enrichment data' });
    }

    // Get file path for the payload
    const fileRow = await indexAdapter.getAsync<{ relative_path: string }>(
      'SELECT relative_path FROM files WHERE id = ?', [sym.file_id],
    );
    const filePath = fileRow?.relative_path || '';

    // Try to enrich via backend LLM
    try {
      const { CodeEnrichmentHandler } = await import('../../../engine/enrichment/CodeEnrichmentHandler.js');
      const { LLMService } = await import('../../../modules/memory/llm/LLMService.js');
      const { loadPersistedLLMConfig } = await import('../../../admin/admin-db.js');

      // Build LLM config from env + DB overrides
      const envConfig = {
        provider: (process.env.LLM_PROVIDER || 'lmstudio') as any,
        model: process.env.LLM_MODEL || 'qwen2.5-vl-7b-instruct',
        baseUrl: process.env.LLM_BASE_URL || 'http://localhost:1234/v1',
        apiKey: process.env.LLM_API_KEY || undefined,
        temperature: parseFloat(process.env.LLM_TEMPERATURE || '0.3'),
        maxTokens: parseInt(process.env.LLM_MAX_TOKENS || '800', 10),
      };
      let llmConfig = envConfig;
      try {
        const dbOverrides = await loadPersistedLLMConfig();
        llmConfig = {
          ...envConfig,
          ...(dbOverrides.provider && { provider: dbOverrides.provider as any }),
          ...(dbOverrides.model && { model: dbOverrides.model }),
          ...(dbOverrides.baseUrl && { baseUrl: dbOverrides.baseUrl }),
          ...(dbOverrides.apiKey && dbOverrides.apiKey !== '***' && { apiKey: dbOverrides.apiKey }),
          ...(dbOverrides.temperature !== undefined && { temperature: dbOverrides.temperature }),
          ...(dbOverrides.maxTokens !== undefined && { maxTokens: dbOverrides.maxTokens }),
        };
      } catch { /* DB not ready — use env config */ }

      const llmService = new LLMService(llmConfig);
      const enrichHandler = new CodeEnrichmentHandler(indexAdapter, llmService, ctx.logger);

      // Build a proper PendingTask payload matching CodeEnrichmentPayloadSchema
      const fakeTask = {
        id: 0,
        payload: JSON.stringify({
          symbolId: numId,
          symbolName: sym.name,
          symbolKind: sym.kind,
          projectId: projectId,
          filePath: filePath,
          workspaceType: sym.kind.startsWith('pega_') ? 'pega' : 'standard',
        }),
        task_type: 'CODE_ENRICHMENT',
        status: 'PENDING',
        created_at: new Date().toISOString(),
      };
      await enrichHandler.enrichSymbol(fakeTask as any);

      // Re-fetch updated data
      const updated = await indexAdapter.getAsync<{ summary: string | null; pseudo_code: string | null; llm_tags: string | null }>(
        'SELECT summary, pseudo_code, llm_tags FROM symbols WHERE id = ?', [numId],
      );
      return c.json({
        status: 'enriched',
        enrichment: {
          summary: updated?.summary || null,
          pseudoCode: updated?.pseudo_code || null,
          llmTags: updated?.llm_tags ? JSON.parse(updated.llm_tags) : null,
          status: 'COMPLETED',
        },
      });
    } catch (err: any) {
      ctx.logger.warn({ symbolId, err: err.message }, '[on-demand-enrich] Backend LLM enrichment failed');
      return c.json({
        status: 'llm_unavailable',
        message: 'Backend LLM not available. Extension-side enrichment may be used as fallback.',
        error: err.message,
      }, 503);
    }
  });

  /** Save enrichment data from extension-side LLM (fallback path). */
  app.post('/api/admin/kb/entries/:id/enrich-save', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const entryId = c.req.param('id');

    if (!entryId.startsWith('code:') && !entryId.startsWith('sym-')) {
      return c.json({ error: 'Only code symbols support enrichment save' }, 400);
    }
    const symbolId = entryId.startsWith('code:') ? entryId.replace('code:', '') : entryId.replace('sym-', '');
    const numId = parseInt(symbolId, 10);
    if (isNaN(numId)) return c.json({ error: 'Invalid symbol ID' }, 400);

    const { summary, pseudoCode } = await c.req.json();
    if (!summary && !pseudoCode) return c.json({ error: 'At least summary or pseudoCode required' }, 400);

    const { getIndexAdapter } = await import('../../../admin/db/core.js');
    const indexAdapter = getIndexAdapter();
    const now = new Date().toISOString();
    await indexAdapter.runAsync(
      `UPDATE symbols SET summary = COALESCE(?, summary), pseudo_code = COALESCE(?, pseudo_code),
       enrichment_status = 'COMPLETED', enriched_at = ? WHERE id = ?`,
      [summary || null, pseudoCode || null, now, numId],
    );
    return c.json({ status: 'saved' });
  });

  return app;
}

/** SA4E-171: Resolve a Pega rule FQN to its symbol id (rules live in symbols). */
async function resolvePegaSymbolId(ctx: AdminContext, fqn: string): Promise<string | null> {
  try {
    const { getIndexAdapter } = await import('../../../admin/db/core.js');
    const adapter = getIndexAdapter();
    const sym = await adapter.getAsync<{ id: number }>(
      `SELECT s.id FROM symbols s JOIN files f ON f.id = s.file_id
       WHERE s.signature = ? AND s.kind LIKE 'pega_%' LIMIT 1`,
      [fqn],
    );
    return sym ? String(sym.id) : null;
  } catch {
    return null;
  }
}

/** Fetch code symbol detail via SymbolRepository for KB Graph node click. */
async function getCodeSymbolDetail(symbolId: string, ctx: AdminContext): Promise<Record<string, unknown> | null> {
  try {
    const detail = await ctx.db.symbol.getSymbolDetail(symbolId);
    if (!detail) return null;
    const lines = detail.startLine && detail.endLine ? `Lines ${detail.startLine}\u2013${detail.endLine}` : '';
    // SA4E-104: Fetch body/pseudo code from body_embeddings if available
    let bodyCode = '';
    try {
      const numId = parseInt(symbolId, 10);
      if (!isNaN(numId)) {
        const { getIndexAdapter } = await import('../../../admin/db/core.js');
        const indexAdapter = getIndexAdapter();
        const bodyRow = await indexAdapter.getAsync<{ embedding: Buffer | Uint8Array }>(
          'SELECT embedding FROM body_embeddings WHERE symbol_id = ? AND chunk_index = 0', [numId],
        );
        if (bodyRow && bodyRow.embedding) {
          bodyCode = Buffer.from(bodyRow.embedding).toString('utf-8');
        }
      }
    } catch (err) { /* body_embeddings table may not exist */ }
    const isPega = Boolean(detail.language && detail.language.toLowerCase() === 'pega');
    const codeLabel = isPega ? '**Rule Content:**' : '**Code:**';
    const codeFence = isPega ? 'text' : (detail.language?.toLowerCase() || 'typescript');
    const contentParts = [
      detail.signature ? `**Signature:** \`${detail.signature}\`` : '',
      detail.docComment ? `**Doc:** ${detail.docComment}` : '',
      `**Kind:** ${detail.kind}`, `**File:** ${detail.relativePath}`,
      lines ? `**Location:** ${lines}` : '',
      detail.module ? `**Module:** ${detail.module}` : '',
      detail.visibility ? `**Visibility:** ${detail.visibility}` : '',
      detail.parentSymbol ? `**Parent:** ${detail.parentSymbol}` : '',
      bodyCode ? `\n${codeLabel}\n\`\`\`${codeFence}\n${bodyCode.substring(0, 2000)}\n\`\`\`` : '',
    ].filter(Boolean).join('\n');
    return {
      id: `code:${detail.id}`,
      title: `${detail.name} (${detail.kind})`,
      content: contentParts, tier: 'CODE', type: 'CODE_ENTITY',
      source: detail.relativePath || '',
      tags: [detail.kind, detail.language, detail.module].filter(Boolean),
      links: [], qualityScore: null, createdAt: null, updatedAt: null,
      enrichment: {
        summary: detail.summary || null,
        pseudoCode: detail.pseudoCode || null,
        llmTags: detail.llmTags ? JSON.parse(detail.llmTags) : null,
        status: detail.enrichmentStatus || null,
      },
    };
  } catch (err) {
    ctx.logger.warn({ symbolId }, 'Failed to fetch code symbol detail');
    return null;
  }
}

/**
 * KB Graph Spatial routes — 3D spatial queries for graph visualization.
 * SA4E-45: Uses getIndexAdapter() for multi-DB support.
 * SA4E-49: Counts use graph_nodes table (authoritative) instead of knowledge_entries/symbols.
 */

import { Hono } from 'hono';
import { getKbEntries, getKbEntryCount } from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createKbGraphSpatialRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/kb/graph/positions', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const kbPermCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (kbPermCheck instanceof Response) return kbPermCheck;
    const allowedTiers = (kbPermCheck.roleData as { allowedTiers?: string[] })?.allowedTiers;
    let kbCount = 0;
    let codeCount = 0;
    // SA4E-49/50: Use repository for graph_nodes counts (authoritative source).
    let isPega = false;
    try {
      const pid = ctx.getRequestProjectId(c);
      const counts = await ctx.db.graph.getNodeCounts(pid);
      codeCount = counts.code;
      kbCount = counts.kb;
      isPega = await ctx.db.graph.isPegaProject(pid);
    } catch { ctx.logger.warn({ context: 'kb-graph' }, 'Failed to count graph nodes'); }
    const graphService = (globalThis as Record<string, unknown>).__sqliteGraphService as { ready?: boolean; getAllPositions?: (projectId?: string) => any } | undefined;
    if (graphService && graphService.ready) {
      try {
        const result = await graphService.getAllPositions!(ctx.getRequestProjectId(c));
        if (Array.isArray(allowedTiers)) result.nodes = result.nodes.filter((n: any) => n.tier === 'CODE' || allowedTiers.includes(n.tier));
        result.kbCount = kbCount; result.codeCount = codeCount; result.isPega = isPega;
        return c.json(result);
      } catch (err: any) { ctx.logger.warn({ error: err.message }, 'getAllPositions failed'); }
    }
    const allEntries = await getKbEntries(1, 100000, 'created_at', 'desc', ctx.getRequestProjectId(c));
    const items = allEntries.items;
    const golden = (1 + Math.sqrt(5)) / 2;
    const groups = new Map<string, number>();
    let groupCounter = 0;
    const nodes = items.map((e: any, i: number) => {
      const type = (e.type || e.content_type || 'DOCUMENT').toUpperCase();
      const tier = e.tier || e.scope || 'SHARED';
      if (!groups.has(type)) groups.set(type, groupCounter++);
      const groupId = groups.get(type)!;
      const level = ({ ARCHITECTURE: 0, REQUIREMENT: 0, DECISION: 0, PROCEDURE: 1, CONTEXT: 1, CODE_ENTITY: 1 } as Record<string, number>)[type] ?? 2;
      const theta = 2 * Math.PI * i / golden;
      const phi = Math.acos(1 - 2 * (i + 0.5) / Math.max(items.length, 1));
      const baseRadius = 300 + level * 200;
      const groupAngle = (groupId / Math.max(groupCounter, 1)) * 2 * Math.PI;
      return {
        id: e.id || e.entry_id || `node-${i}`,
        x: Math.round((baseRadius * Math.sin(phi) * Math.cos(theta) + 150 * Math.cos(groupAngle)) * 100) / 100,
        y: Math.round((baseRadius * Math.sin(phi) * Math.sin(theta) + 150 * Math.sin(groupAngle)) * 100) / 100,
        z: Math.round((baseRadius * Math.cos(phi)) * 100) / 100,
        type, tier,
        label: ((e.summary || e.tags || '').substring(0, 50)) || (e.source || '').split('/').pop() || `Entry ${i + 1}`,
      };
    });
    return c.json({ nodes, total: nodes.length, isPega });
  });

  app.get('/api/admin/kb/graph/spatial', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const kbPermCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (kbPermCheck instanceof Response) return kbPermCheck;
    const camX = parseFloat(c.req.query('x') || '0');
    const camY = parseFloat(c.req.query('y') || '0');
    const camZ = parseFloat(c.req.query('z') || '0');
    const zoom = parseFloat(c.req.query('zoom') || '500');
    const graphService = (globalThis as Record<string, unknown>).__sqliteGraphService as { ready?: boolean; spatialQuery?: Function } | undefined;
    if (graphService && graphService.ready) {
      try { return c.json(await graphService.spatialQuery!({ camX, camY, camZ, zoom }, ctx.getRequestProjectId(c))); }
      catch (err: any) { ctx.logger.warn({ error: err.message }, 'SQLite graph spatial query failed, using inline fallback'); }
    }
    const graphPermCheck = await ctx.checkPermission(user.userId, 'GRAPH_VIEW');
    const maxNodes = (graphPermCheck.roleData as { maxNodes?: number })?.maxNodes || 500;
    const allowedTiers = (kbPermCheck.roleData as { allowedTiers?: string[] })?.allowedTiers;
    const allEntries = await getKbEntries(1, maxNodes, 'created_at', 'desc', ctx.getRequestProjectId(c));
    let items = allEntries.items;
    if (Array.isArray(allowedTiers)) items = items.filter((e: any) => allowedTiers.includes(e.tier || e.scope || 'SHARED'));
    items = items.slice(0, maxNodes);
    const levelMap: Record<string, number> = { ARCHITECTURE: 0, REQUIREMENT: 0, DECISION: 0, PROCEDURE: 1, CONTEXT: 1, CODE_ENTITY: 1, LESSON_LEARNED: 2, ERROR_PATTERN: 2, DOCUMENT: 2 };
    const groups = new Map<string, number>();
    let groupCounter = 0;
    const golden = (1 + Math.sqrt(5)) / 2;
    const nodes = items.map((e: any, i: number) => {
      const type = (e.type || e.content_type || 'DOCUMENT').toUpperCase();
      const tier = e.tier || e.scope || 'SHARED';
      if (!groups.has(type)) groups.set(type, groupCounter++);
      const groupId = groups.get(type)!;
      const level = levelMap[type] ?? 2;
      const theta = 2 * Math.PI * i / golden;
      const phi = Math.acos(1 - 2 * (i + 0.5) / items.length);
      const baseRadius = 100 + level * 80;
      const groupAngle = (groupId / Math.max(groupCounter, 1)) * 2 * Math.PI;
      return {
        id: e.id || e.entry_id || `node-${i}`,
        label: ((e.summary || e.tags || '').substring(0, 50)) || (e.source || '').split('/').pop() || `Entry ${i + 1}`,
        type, tier, x: Math.round((baseRadius * Math.sin(phi) * Math.cos(theta) + 50 * Math.cos(groupAngle)) * 100) / 100,
        y: Math.round((baseRadius * Math.sin(phi) * Math.sin(theta) + 50 * Math.sin(groupAngle)) * 100) / 100,
        z: Math.round((baseRadius * Math.cos(phi)) * 100) / 100,
        level, clusterId: `cluster-${groupId}`,
      };
    });
    let filteredNodes = nodes;
    if (zoom <= 500) {
      const r = Math.max(200, zoom * 0.5);
      filteredNodes = nodes.filter((nd: any) => nd.x >= camX - r && nd.x <= camX + r && nd.y >= camY - r && nd.y <= camY + r && nd.z >= camZ - r && nd.z <= camZ + r);
    }
    const edges: any[] = [];
    const clusterMap = new Map<string, any[]>();
    for (const nd of filteredNodes) {
      const cid = nd.clusterId || 'default';
      if (!clusterMap.has(cid)) clusterMap.set(cid, []);
      clusterMap.get(cid)!.push(nd);
    }
    for (const [, members] of clusterMap) {
      const hub = members[0];
      for (let i = 1; i < Math.min(members.length, 11); i++) edges.push({ source: hub.id, target: members[i].id, weight: 0.8 });
      for (let i = 1; i < members.length; i += 3) edges.push({ source: members[i - 1].id, target: members[i].id, weight: 0.5 });
    }
    const level = zoom > 500 ? 'macro' : zoom > 200 ? 'mid' : 'micro';
    return c.json({ nodes: filteredNodes, edges, stats: { totalNodes: filteredNodes.length, totalEdges: edges.length, queryTimeMs: 0, level, source: 'sqlite-fallback', totalEntries: await getKbEntryCount(ctx.getRequestProjectId(c)) } });
  });

  return app;
}

﻿/**
 * KB graph routes — node/edge data for graph visualization.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import { getKbEntries, getKbEntryCount } from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createKbGraphRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/kb/graph', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const kbPermCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (kbPermCheck instanceof Response) return kbPermCheck;
    const allowedTiers = (kbPermCheck.roleData as any)?.allowedTiers;
    const graphPermCheck = await ctx.checkPermission(user.userId, 'GRAPH_VIEW');
    const maxNodes = (graphPermCheck.roleData as any)?.maxNodes || 500;
    const result = await getKbEntries(1, 500, 'created_at', 'desc', ctx.getRequestProjectId(c));
    let nodes: any[] = [], edges: any[] = [];
    if (result.items.length > 0) {
      let items = result.items;
      if (Array.isArray(allowedTiers)) items = items.filter((e: any) => { const t = e.tier || e.scope || 'SHARED'; return allowedTiers.includes(t); });
      items = items.slice(0, maxNodes);
      nodes = items.map((e: any, i: number) => ({
        id: e.id || e.entry_id || `node-${i}`,
        label: ((e.summary || e.tags || '').substring(0, 50)) || (e.source || '').split('/').pop() || 'Entry ' + (i + 1),
        type: e.type || e.content_type || 'document', tier: e.tier || e.scope || 'SHARED', group: Math.floor(i / 5),
      }));
      for (let i = 0; i < nodes.length; i++) {
        const groupSize = 5;
        const groupStart = Math.floor(i / groupSize) * groupSize;
        if (i > groupStart && i < groupStart + groupSize) edges.push({ source: nodes[groupStart].id, target: nodes[i].id, weight: +(0.6 + Math.random() * 0.4).toFixed(2) });
        if (i > 0 && i % 7 === 0) {
          const target = Math.floor(Math.random() * i);
          if (nodes[i].type === nodes[target].type || nodes[i].tier === nodes[target].tier) edges.push({ source: nodes[i].id, target: nodes[target].id, weight: +(0.3 + Math.random() * 0.4).toFixed(2) });
        }
      }
    }
    if (nodes.length === 0) {
      const labels = ['project-structure', 'admin-db', 'mcp-server', 'embedding', 'config', 'routes', 'auth', 'rbac', 'audit', 'kb-index', 'tools', 'types', 'modules', 'search', 'graph'];
      let mockNodes = labels.map((label, i) => ({ id: `n${i}`, label, type: ['module', 'code', 'config', 'api', 'document'][i % 5], tier: ['SHARED', 'PROJECT', 'USER'][i % 3], group: Math.floor(i / 4) }));
      if (Array.isArray(allowedTiers)) mockNodes = mockNodes.filter(n => allowedTiers.includes(n.tier));
      mockNodes = mockNodes.slice(0, maxNodes);
      nodes = mockNodes;
      const nodeIds = new Set(nodes.map(n => n.id));
      edges = [{ source: 'n0', target: 'n1', weight: 0.9 }, { source: 'n0', target: 'n5', weight: 0.8 }, { source: 'n1', target: 'n6', weight: 0.7 }, { source: 'n2', target: 'n10', weight: 0.85 }, { source: 'n3', target: 'n9', weight: 0.6 }, { source: 'n4', target: 'n5', weight: 0.75 }, { source: 'n5', target: 'n6', weight: 0.9 }, { source: 'n6', target: 'n7', weight: 0.8 }, { source: 'n7', target: 'n8', weight: 0.7 }, { source: 'n8', target: 'n0', weight: 0.5 }, { source: 'n9', target: 'n13', weight: 0.85 }, { source: 'n10', target: 'n11', weight: 0.6 }, { source: 'n11', target: 'n12', weight: 0.7 }, { source: 'n12', target: 'n13', weight: 0.55 }, { source: 'n13', target: 'n14', weight: 0.8 }, { source: 'n14', target: 'n0', weight: 0.65 }].filter(e => nodeIds.has(e.source) && nodeIds.has(e.target));
    }
    const totalEntries = await getKbEntryCount(ctx.getRequestProjectId(c));
    return c.json({ nodes, edges, stats: { totalNodes: nodes.length, totalEdges: edges.length, maxNodes, totalEntries } });
  });

  app.get('/api/admin/kb/graph/cluster/:clusterId', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const kbPermCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (kbPermCheck instanceof Response) return kbPermCheck;
    const clusterId = c.req.param('clusterId');
    const match = clusterId.match(/cluster-(\d+)/);
    if (!match) return c.json({ error: 'Invalid cluster ID' }, 400);
    const clusterIndex = parseInt(match[1], 10);
    const pageSize = 30;
    const offset = clusterIndex * pageSize;
    const result = await getKbEntries(1, 5000, 'created_at', 'desc', ctx.getRequestProjectId(c));
    const items = result.items.slice(offset, offset + pageSize);
    const nodes = items.map((e: any, i: number) => ({
      id: e.id || e.entry_id || `child-${offset + i}`,
      label: ((e.summary || e.tags || '').substring(0, 50)) || (e.source || '').split('/').pop() || `Entry ${offset + i + 1}`,
      type: e.type || e.content_type || 'document',
      tier: e.tier || e.scope || 'SHARED',
    }));
    const edges: any[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < Math.min(nodes.length, i + 3); j++) {
        if (nodes[i].type === nodes[j].type || nodes[i].tier === nodes[j].tier) edges.push({ source: nodes[i].id, target: nodes[j].id, weight: +(0.3 + Math.random() * 0.7).toFixed(2) });
      }
    }
    return c.json({ clusterId, nodes, edges });
  });

  app.post('/api/admin/kb/graph/sync', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    // SEC: graph sync resets the entire graph — requires RBAC_MANAGE (admin-only), not user KB_WRITE
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const graphService = (globalThis as any).__sqliteGraphService;
    if (!graphService) return c.json({ error: 'Graph service not initialized' }, 503);
    setImmediate(async () => {
      try { await ctx.db.graph.resetGraph(); await graphService.fullSync(); }
      catch (err: any) { ctx.logger.error({ error: err.message }, 'Graph sync failed'); }
    });
    return c.json({ status: 'sync_started', message: 'Graph sync triggered in background.' });
  });

  return app;
}

/**
 * admin/routes/kb-operations.ts — KB links, promotions, import/export.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import {
  getKbEntries, getKbEntryById, recordAudit,
  checkPromotionCooldown, setPromotionCooldown,
} from '../../../admin/admin-db.js';
import { containsHtml, sanitizeKbEntry } from '../../../admin/sanitize.js';
import type { AdminContext } from './context.js';

export function createKbOperationsRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.post('/api/admin/kb/entries/:id/link', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const entryId = c.req.param('id');
    const { targetId, linkType } = await c.req.json();
    if (!targetId) return c.json({ error: 'targetId is required' }, 400);
    if (!ctx.kbLinks[entryId]) ctx.kbLinks[entryId] = [];
    ctx.kbLinks[entryId].push({ targetId, linkType: linkType || 'related', createdAt: new Date().toISOString() });
    await recordAudit(user.userId, user.username, 'LINK_ENTRY', 'kb', entryId, JSON.stringify({ targetId, linkType }));
    return c.json({ success: true, links: ctx.kbLinks[entryId] });
  });

  app.get('/api/admin/kb/entries/:id/links', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    return c.json({ entryId: c.req.param('id'), links: ctx.kbLinks[c.req.param('id')] || [] });
  });

  app.get('/api/admin/kb/promotions', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_PROMOTE');
    if (permCheck instanceof Response) return permCheck;
    const status = c.req.query('status') || undefined;
    let filtered = [...ctx.promotionQueue];
    if (status) filtered = filtered.filter(p => p.status === status);
    return c.json({ promotions: filtered, total: filtered.length });
  });

  app.post('/api/admin/kb/promotions', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_PROMOTE');
    if (permCheck instanceof Response) return permCheck;
    const { entryId, fromTier, toTier, reason } = await c.req.json();
    if (!entryId || !toTier) return c.json({ error: 'entryId and toTier required' }, 400);
    const cooldownStatus = await checkPromotionCooldown(entryId);
    if (cooldownStatus.onCooldown) return c.json({ error: 'Entry is on promotion cooldown after a recent rejection', cooldownUntil: cooldownStatus.cooldownUntil }, 400);
    const promotion = { id: 'promo-' + Date.now().toString(36), entryId, fromTier: fromTier || 'USER', toTier, reason: reason || '', requestedBy: user.username, requestedAt: new Date().toISOString(), status: 'pending' };
    ctx.promotionQueue.push(promotion);
    await recordAudit(user.userId, user.username, 'REQUEST_PROMOTION', 'kb', entryId, JSON.stringify({ fromTier, toTier }));
    return c.json({ success: true, promotion }, 201);
  });

  app.post('/api/admin/kb/promotions/:id/review', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_PROMOTE');
    if (permCheck instanceof Response) return permCheck;
    const promoId = c.req.param('id');
    const { action } = await c.req.json();
    if (!action || !['approve', 'reject'].includes(action)) return c.json({ error: 'action must be approve or reject' }, 400);
    const promo = ctx.promotionQueue.find(p => p.id === promoId);
    if (!promo) return c.json({ error: 'Promotion not found' }, 404);
    promo.status = action === 'approve' ? 'approved' : 'rejected';
    promo.reviewedBy = user.username;
    promo.reviewedAt = new Date().toISOString();
    if (action === 'reject') await setPromotionCooldown(promo.entryId, user.username);
    await recordAudit(user.userId, user.username, action === 'approve' ? 'APPROVE_PROMOTION' : 'REJECT_PROMOTION', 'kb', promo.entryId);
    return c.json({ success: true, promotion: promo });
  });

  app.get('/api/admin/kb/export', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_IMPORT_EXPORT');
    if (permCheck instanceof Response) return permCheck;
    const result = await getKbEntries(1, 100000, 'created_at', 'desc', ctx.getRequestProjectId(c));
    const allowedTiers = (permCheck.roleData as any)?.allowedTiers;
    let entries = result.items;
    if (Array.isArray(allowedTiers)) entries = entries.filter((e: any) => { const t = e.tier || e.scope || 'SHARED'; return allowedTiers.includes(t); });
    await recordAudit(user.userId, user.username, 'KB_EXPORT', 'kb', undefined, JSON.stringify({ count: entries.length }));
    return c.json({ entries, exportedAt: new Date().toISOString(), count: entries.length });
  });

  app.post('/api/admin/kb/import', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_IMPORT_EXPORT');
    if (permCheck instanceof Response) return permCheck;
    try {
      const { entries: rawEntries, conflictMode } = await c.req.json();
      if (!Array.isArray(rawEntries)) return c.json({ error: 'entries must be an array' }, 400);
      for (const entry of rawEntries) {
        for (const field of ['source', 'content', 'summary', 'title']) {
          if (containsHtml((entry as any)?.[field])) return c.json({ error: `Entry field "${field}" contains disallowed HTML/script content` }, 400);
        }
      }
      const entries = rawEntries.map((e: any) => sanitizeKbEntry(e));
      const mode = conflictMode || 'skip';
      if (!['skip', 'overwrite', 'merge'].includes(mode)) return c.json({ error: 'conflictMode must be skip, overwrite, or merge' }, 400);
      const existingEntries = await getKbEntries(1, 100000, 'created_at', 'desc', ctx.getRequestProjectId(c));
      const existingIds = new Set(existingEntries.items.map((e: any) => e.id || e.entry_id));
      const conflicts: any[] = [], newEntries: any[] = [];
      for (const entry of entries) {
        const entryId = entry.id || entry.entry_id;
        if (entryId && existingIds.has(entryId)) conflicts.push({ id: entryId, existing: existingEntries.items.find((e: any) => (e.id || e.entry_id) === entryId), incoming: entry });
        else newEntries.push(entry);
      }
      let imported = newEntries.length;
      let skipped = 0, overwritten = 0, merged = 0;
      if (conflicts.length > 0) {
        switch (mode) {
          case 'skip': skipped = conflicts.length; break;
          case 'overwrite': overwritten = conflicts.length; imported += conflicts.length; break;
          case 'merge': merged = conflicts.length; imported += conflicts.length; break;
        }
      }
      await recordAudit(user.userId, user.username, 'KB_IMPORT', 'kb', undefined, JSON.stringify({ count: entries.length, conflictMode: mode, imported, skipped, overwritten, merged }));
      return c.json({ success: true, imported, skipped, overwritten, merged, conflicts: conflicts.map(cf => ({ id: cf.id, existingSource: cf.existing?.source || cf.existing?.title || 'unknown', incomingSource: cf.incoming?.source || cf.incoming?.title || 'unknown' })), message: `${imported} entries imported (${skipped} skipped, ${overwritten} overwritten, ${merged} merged)` });
    } catch { return c.json({ error: 'Invalid JSON body' }, 400); }
  });

  /** DELETE /api/admin/kb/entries/all — wipe all KB entries + graph nodes (admin only). */
  app.delete('/api/admin/kb/entries/all', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    try {
      const { getIndexAdapter } = await import('../../../admin/db/core.js');
      const adapter = getIndexAdapter();
      const result = await adapter.runAsync('DELETE FROM knowledge_entries');
      // resetGraph uses sync transaction — use async variant for PG compatibility
      const { getAdminAdapter } = await import('../../../admin/db/core.js');
      const adminAdapter = getAdminAdapter();
      await adminAdapter.transactionAsync(async () => {
        await adminAdapter.execAsync('DELETE FROM graph_nodes');
        await adminAdapter.execAsync('DELETE FROM graph_edges');
      });
      await recordAudit(user.userId, user.username, 'KB_DELETE_ALL', 'kb', undefined, `Deleted ${result.changes} entries`);
      return c.json({ success: true, deleted: result.changes });
    } catch (err: any) {
      ctx.logger.error({ err }, 'Failed to delete all KB entries');
      return c.json({ error: err.message || 'Failed' }, 500);
    }
  });

  return app;
}

/**
 * KB quality routes — quality scoring and distribution for KB entries.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import { getKbEntries } from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createKbQualityRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/kb/quality', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const allowedTiers = (permCheck.roleData as any)?.allowedTiers;
    const page = parseInt(c.req.query('page') || '1');
    const pageSize = parseInt(c.req.query('pageSize') || '20');
    const tierFilter = c.req.query('tier') || undefined;
    const sortBy = c.req.query('sortBy') || 'quality_score';
    const sortDir = (c.req.query('sortDir') || 'desc') as 'asc' | 'desc';
    const result = await getKbEntries(1, 100000, 'created_at', 'desc', ctx.getRequestProjectId(c));
    let entries = result.items.map((e: any) => ({
      id: e.id || e.entry_id,
      source: e.source || e.title || 'Untitled',
      tier: e.tier || e.scope || 'SHARED',
      type: e.type || e.content_type || 'document',
      qualityScore: e.quality_score || e.score || +(Math.random() * 0.4 + 0.5).toFixed(3),
      status: (e.quality_score || e.score || 0.7) >= 0.7 ? 'good' : (e.quality_score || e.score || 0.7) >= 0.4 ? 'fair' : 'poor',
      createdAt: e.created_at || null,
    }));
    if (Array.isArray(allowedTiers)) entries = entries.filter(e => allowedTiers.includes(e.tier));
    if (tierFilter) entries = entries.filter(e => e.tier === tierFilter);
    entries.sort((a, b) => {
      const aVal = sortBy === 'quality_score' ? a.qualityScore : (a as any)[sortBy] || '';
      const bVal = sortBy === 'quality_score' ? b.qualityScore : (b as any)[sortBy] || '';
      if (sortDir === 'asc') return aVal > bVal ? 1 : -1;
      return aVal < bVal ? 1 : -1;
    });
    const distribution = Array.from({ length: 10 }, (_, i) => ({ range: `${i * 10}-${(i + 1) * 10}`, count: 0 }));
    entries.forEach(e => { const bucket = Math.min(Math.floor(e.qualityScore * 10), 9); distribution[bucket].count++; });
    const total = entries.length;
    const paged = entries.slice((page - 1) * pageSize, page * pageSize);
    return c.json({
      entries: paged, total, page, pageSize, totalPages: Math.ceil(total / pageSize),
      distribution,
      summary: {
        total,
        good: entries.filter(e => e.status === 'good').length,
        fair: entries.filter(e => e.status === 'fair').length,
        poor: entries.filter(e => e.status === 'poor').length,
        avgScore: entries.length > 0 ? +(entries.reduce((s, e) => s + e.qualityScore, 0) / entries.length).toFixed(3) : 0,
      },
    });
  });

  return app;
}

/**
 * admin/routes/kb-tags.ts — KB tag management endpoints.
 * SA4E-50: All admin-db calls are awaited since they are now async.
 */

import { Hono } from 'hono';
import {
  getKbEntryById, updateKbEntryTags, getAllKbTags,
  renameKbTag, deleteKbTag, mergeKbTags, getKbEntriesByTag, recordAudit,
} from '../../../admin/admin-db.js';
import { findInvalidTag } from '../../../admin/sanitize.js';
import type { AdminContext } from './context.js';

export function createKbTagsRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.post('/api/admin/kb/entries/:id/tags', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const entryId = c.req.param('id');
    const { tags } = await c.req.json();
    if (!Array.isArray(tags)) return c.json({ error: 'tags must be an array' }, 400);
    const badTag = findInvalidTag(tags);
    if (badTag !== null) return c.json({ error: 'Invalid tag. Tags may only contain letters, numbers, spaces, hyphens, and underscores (max 64 chars).', invalidTag: badTag }, 400);
    ctx.kbTags[entryId] = tags;
    await updateKbEntryTags(entryId, tags);
    await recordAudit(user.userId, user.username, 'TAG_ENTRY', 'kb', entryId, JSON.stringify({ tags }));
    return c.json({ success: true, entryId, tags: ctx.kbTags[entryId] });
  });

  app.get('/api/admin/kb/entries/:id/tags', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const entryId = c.req.param('id');
    let tags = ctx.kbTags[entryId] || [];
    if (tags.length === 0) {
      const entry = await getKbEntryById(entryId);
      if (entry && entry.tags) {
        tags = entry.tags.split(',').map((t: string) => t.trim()).filter((t: string) => t.length > 0);
        ctx.kbTags[entryId] = tags;
      }
    }
    return c.json({ entryId, tags });
  });

  app.get('/api/admin/kb/tags', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const tagCounts = await getAllKbTags(ctx.getRequestProjectId(c));
    if (ctx.kbTags['__tag_registry__']) {
      for (const tag of ctx.kbTags['__tag_registry__']) {
        if (!tagCounts[tag]) tagCounts[tag] = { count: 0, lastUsed: new Date().toISOString() };
      }
    }
    const tagList = Object.entries(tagCounts).map(([name, data]) => ({ name, entryCount: (data as any).count, lastUsed: (data as any).lastUsed })).sort((a, b) => b.entryCount - a.entryCount);
    return c.json({ tags: tagList, total: tagList.length });
  });

  app.post('/api/admin/kb/tags', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const { name } = await c.req.json();
    if (!name || typeof name !== 'string' || name.trim().length === 0) return c.json({ error: 'Tag name is required' }, 400);
    if (!ctx.kbTags['__tag_registry__']) ctx.kbTags['__tag_registry__'] = [];
    if (ctx.kbTags['__tag_registry__'].includes(name.trim())) return c.json({ error: 'Tag already exists' }, 409);
    ctx.kbTags['__tag_registry__'].push(name.trim());
    await recordAudit(user.userId, user.username, 'CREATE_TAG', 'kb', undefined, JSON.stringify({ tag: name.trim() }));
    return c.json({ success: true, tag: { name: name.trim(), entryCount: 0 } }, 201);
  });

  app.put('/api/admin/kb/tags/:name', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const oldName = decodeURIComponent(c.req.param('name'));
    const { name: newName } = await c.req.json();
    if (!newName || typeof newName !== 'string' || newName.trim().length === 0) return c.json({ error: 'New tag name is required' }, 400);
    let renamed = 0;
    for (const [, tags] of Object.entries(ctx.kbTags)) {
      const idx = tags.indexOf(oldName);
      if (idx !== -1) { tags[idx] = newName.trim(); renamed++; }
    }
    const dbRenamed = await renameKbTag(oldName, newName.trim());
    await recordAudit(user.userId, user.username, 'RENAME_TAG', 'kb', undefined, JSON.stringify({ oldName, newName: newName.trim(), entriesAffected: renamed + dbRenamed }));
    return c.json({ success: true, oldName, newName: newName.trim(), entriesAffected: renamed + dbRenamed });
  });

  app.delete('/api/admin/kb/tags/:name', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const tagName = decodeURIComponent(c.req.param('name'));
    let removed = 0;
    for (const [, tags] of Object.entries(ctx.kbTags)) {
      const idx = tags.indexOf(tagName);
      if (idx !== -1) { tags.splice(idx, 1); removed++; }
    }
    const dbRemoved = await deleteKbTag(tagName);
    await recordAudit(user.userId, user.username, 'DELETE_TAG', 'kb', undefined, JSON.stringify({ tag: tagName, entriesAffected: removed + dbRemoved }));
    return c.json({ success: true, tag: tagName, entriesAffected: removed + dbRemoved });
  });

  app.post('/api/admin/kb/tags/merge', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_WRITE');
    if (permCheck instanceof Response) return permCheck;
    const { sourceTag, targetTag } = await c.req.json();
    if (!sourceTag || !targetTag) return c.json({ error: 'sourceTag and targetTag are required' }, 400);
    if (sourceTag === targetTag) return c.json({ error: 'sourceTag and targetTag must be different' }, 400);
    let merged = 0;
    for (const [, tags] of Object.entries(ctx.kbTags)) {
      const idx = tags.indexOf(sourceTag);
      if (idx !== -1) { tags.splice(idx, 1); if (!tags.includes(targetTag)) tags.push(targetTag); merged++; }
    }
    const dbMerged = await mergeKbTags(sourceTag, targetTag);
    await recordAudit(user.userId, user.username, 'MERGE_TAGS', 'kb', undefined, JSON.stringify({ sourceTag, targetTag, entriesAffected: merged + dbMerged }));
    return c.json({ success: true, sourceTag, targetTag, entriesAffected: merged + dbMerged });
  });

  app.get('/api/admin/kb/tags/:name/entries', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'KB_READ');
    if (permCheck instanceof Response) return permCheck;
    const allowedTiers = (permCheck.roleData as any)?.allowedTiers;
    const tagName = decodeURIComponent(c.req.param('name'));
    const memEntryIds = Object.entries(ctx.kbTags).filter(([id, tags]) => id !== '__tag_registry__' && tags.includes(tagName)).map(([entryId]) => entryId);
    const memEntries = (await Promise.all(memEntryIds.map(async id => {
      const entry = await getKbEntryById(id);
      if (!entry) return null;
      return { id: entry.id || entry.entry_id || id, source: entry.source || entry.title || 'Untitled', tier: entry.tier || entry.scope || 'SHARED', type: entry.content_type || entry.type || 'document', createdAt: entry.created_at || null };
    }))).filter(Boolean);
    const dbRows = await getKbEntriesByTag(tagName, ctx.getRequestProjectId(c));
    const dbEntries = dbRows.map((entry: any) => ({ id: entry.id || entry.entry_id, source: entry.source || entry.title || 'Untitled', tier: entry.tier || entry.scope || 'SHARED', type: entry.content_type || entry.type || 'document', createdAt: entry.created_at || null }));
    const allEntries = [...memEntries, ...dbEntries];
    const uniqueMap = new Map();
    allEntries.forEach((e: any) => { if (e && !uniqueMap.has(e.id)) uniqueMap.set(e.id, e); });
    let entries = Array.from(uniqueMap.values());
    if (Array.isArray(allowedTiers)) entries = entries.filter((e: any) => allowedTiers.includes(e.tier));
    return c.json({ tag: tagName, entries, total: entries.length });
  });

  return app;
}

import { Hono } from 'hono';
import * as fs from 'fs';
import * as path from 'path';
import { loadConfig, getWorkspacePath } from '../../../config/index.js';
import { recordAudit } from '../../../admin/admin-db.js';
import { addMcpLog } from './mcp.js';
import type { AdminContext } from './context.js';

export function createMcpCrudRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.post('/api/admin/mcp/servers', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    if ((permCheck.roleData as { allowAdd?: boolean })?.allowAdd === false) return c.json({ error: 'Forbidden: not allowed to add servers' }, 403);
    const body = await c.req.json();
    const { name, url, type, command, args, env, disabled, autoApprove } = body;
    if (!name) return c.json({ error: 'name is required' }, 400);
    if (!url && !command) return c.json({ error: 'url or command is required' }, 400);
    const cfg = loadConfig();
    const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
    let orch: any = { mcpServers: {} };
    if (fs.existsSync(orchPath)) { try { orch = JSON.parse(fs.readFileSync(orchPath, 'utf-8')); } catch (e) { ctx.logger.warn({ err: e, context: 'mcp-add' }, 'Failed to parse orch config for add'); } }
    if (!orch.mcpServers) orch.mcpServers = {};
    if (orch.mcpServers[name]) return c.json({ error: `Server "${name}" already exists` }, 409);
    const serverConfig: any = {};
    if (url) serverConfig.url = url;
    if (type) { serverConfig.type = type; serverConfig.transportType = type; } else { serverConfig.type = 'stdio'; serverConfig.transportType = 'stdio'; }
    if (command) serverConfig.command = command;
    if (args) serverConfig.args = args;
    if (env) serverConfig.env = env;
    if (disabled !== undefined) serverConfig.disabled = disabled;
    if (autoApprove) serverConfig.autoApprove = autoApprove;
    if (body.tools) serverConfig.tools = body.tools;
    orch.mcpServers[name] = serverConfig;
    const tmpPath = orchPath + '.tmp';
    fs.writeFileSync(tmpPath, JSON.stringify(orch, null, 2), 'utf-8');
    fs.renameSync(tmpPath, orchPath);
    addMcpLog(ctx, name, 'INFO', `Server added by ${user.username}`);
    await recordAudit(user.userId, user.username, 'ADD_SERVER', 'mcp', name);
    let status = disabled ? 'stopped' : 'disconnected';
    let toolCount = 0;
    const orchestration = ctx.registry?.getModule?.('orchestration');
    const clientManager = orchestration?.getClientManager?.();
    if (clientManager && !disabled) {
      try { await clientManager.connectServer(name, serverConfig); status = 'connected'; toolCount = clientManager.getServerToolCount(name); }
      catch (err: any) { addMcpLog(ctx, name, 'ERROR', `Connect failed: ${err.message}`); status = 'disconnected'; }
    }
    return c.json({ success: true, name, status, tools: toolCount }, 201);
  });

  app.delete('/api/admin/mcp/servers/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    if ((permCheck.roleData as { allowRemove?: boolean })?.allowRemove === false) return c.json({ error: 'Forbidden: not allowed to remove servers' }, 403);
    const serverId = c.req.param('id');
    const allowedServers = (permCheck.roleData as any)?.allowedServers;
    if (Array.isArray(allowedServers) && !allowedServers.includes('*') && !allowedServers.includes(serverId)) return c.json({ error: 'Forbidden: server not in allowedServers' }, 403);
    const cfg = loadConfig();
    const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
    let orch: any = { mcpServers: {} };
    if (fs.existsSync(orchPath)) { try { orch = JSON.parse(fs.readFileSync(orchPath, 'utf-8')); } catch (e) { ctx.logger.warn({ err: e, context: 'mcp-delete' }, 'Failed to parse orch config for delete'); } }
    if (!orch.mcpServers?.[serverId]) return c.json({ error: `Server "${serverId}" not found` }, 404);
    delete orch.mcpServers[serverId];
    const tmpPath = orchPath + '.tmp';
    fs.writeFileSync(tmpPath, JSON.stringify(orch, null, 2), 'utf-8');
    fs.renameSync(tmpPath, orchPath);
    addMcpLog(ctx, serverId, 'INFO', `Server removed by ${user.username}`);
    await recordAudit(user.userId, user.username, 'REMOVE_SERVER', 'mcp', serverId);
    return c.json({ success: true, removed: serverId });
  });

  app.put('/api/admin/mcp/servers/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    if ((permCheck.roleData as { allowEdit?: boolean })?.allowEdit === false) return c.json({ error: 'Forbidden: not allowed to edit server config' }, 403);
    const serverId = c.req.param('id');
    const allowedServers = (permCheck.roleData as any)?.allowedServers;
    if (Array.isArray(allowedServers) && !allowedServers.includes('*') && !allowedServers.includes(serverId)) return c.json({ error: 'Forbidden: server not in allowedServers' }, 403);
    const body = await c.req.json();
    const cfg = loadConfig();
    const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
    let orch: any = { mcpServers: {} };
    if (fs.existsSync(orchPath)) { try { orch = JSON.parse(fs.readFileSync(orchPath, 'utf-8')); } catch (e) { ctx.logger.warn({ err: e, context: 'mcp-update' }, 'Failed to parse orch config for update'); } }
    if (!orch.mcpServers?.[serverId]) return c.json({ error: `Server "${serverId}" not found` }, 404);
    const existing = orch.mcpServers[serverId];
    if (body.url !== undefined) existing.url = body.url;
    if (body.type !== undefined) { existing.type = body.type; existing.transportType = body.type; }
    if (body.command !== undefined) existing.command = body.command;
    if (body.args !== undefined) existing.args = body.args;
    if (body.env !== undefined) existing.env = body.env;
    if (body.disabled !== undefined) existing.disabled = body.disabled;
    if (body.autoApprove !== undefined) existing.autoApprove = body.autoApprove;
    const tmpPath = orchPath + '.tmp';
    fs.writeFileSync(tmpPath, JSON.stringify(orch, null, 2), 'utf-8');
    fs.renameSync(tmpPath, orchPath);
    addMcpLog(ctx, serverId, 'INFO', `Config updated by ${user.username}`);
    await recordAudit(user.userId, user.username, 'UPDATE_SERVER', 'mcp', serverId);
    const orchestration = ctx.registry?.getModule?.('orchestration');
    const clientManager = orchestration?.getClientManager?.();
    if (clientManager && !existing.disabled) {
      try { await clientManager.disconnectServer(serverId); await clientManager.connectServer(serverId, existing); }
      catch (err: any) { addMcpLog(ctx, serverId, 'ERROR', `Reconnect failed: ${err.message}`); }
    }
    return c.json({ success: true, name: serverId });
  });

  return app;
}

import { Hono } from 'hono';
import * as fs from 'fs';
import * as path from 'path';
import { loadConfig, getWorkspacePath } from '../../../config/index.js';
import { recordAudit } from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function addMcpLog(ctx: AdminContext, serverId: string, level: string, message: string) {
  if (!ctx.mcpServerLogs[serverId]) ctx.mcpServerLogs[serverId] = [];
  ctx.mcpServerLogs[serverId].push({ timestamp: new Date().toISOString(), level, message });
  if (ctx.mcpServerLogs[serverId].length > 100) ctx.mcpServerLogs[serverId].shift();
}

export function createMcpRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/mcp/servers', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_ACCESS');
    if (permCheck instanceof Response) return permCheck;
    const cfg = loadConfig();
    const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
    let servers: any[] = [];
    const orchestration = ctx.registry?.getModule?.('orchestration');
    const clientManager = orchestration?.getClientManager?.();
    if (fs.existsSync(orchPath)) {
      try {
        const orch = JSON.parse(fs.readFileSync(orchPath, 'utf-8'));
        servers = Object.entries(orch.mcpServers || {}).map(([name, cfg]: [string, any]) => {
          const serverToggles = ctx.toolToggles[name] || {};
          const isConnected = clientManager?.isServerConnected?.(name) ?? false;
          const actualToolCount = clientManager?.getServerToolCount?.(name) ?? 0;
          const configTools = cfg.tools || cfg.autoApprove || [];
          let tools: any[];
          if (isConnected && actualToolCount > 0) {
            const proxied = (clientManager?.getProxiedTools?.() || []).filter((t: any) => t.category === name);
            tools = proxied.map((t: any) => ({ name: t.name, description: t.description || '', enabled: serverToggles[t.name] !== false }));
          } else tools = configTools.map((t: string) => ({ name: t, description: '', enabled: serverToggles[t] !== false }));
          return {
            id: name, name, url: cfg.url || '', type: cfg.type || cfg.transportType || 'stdio',
            transportType: cfg.transportType || cfg.type || 'stdio',
            command: cfg.command || '', args: cfg.args || [], env: cfg.env || {},
            disabled: cfg.disabled || false,
            status: cfg.disabled ? 'stopped' : (isConnected ? 'running' : 'disconnected'), tools,
          };
        });
      } catch (err) { ctx.logger.warn({ err, context: 'mcp-list' }, 'Failed to list MCP servers'); }
    }
    const allHandlers = ctx.registry?.getToolHandlers?.();
    if (allHandlers) {
      const allDefs = ctx.registry?.getAllToolDefinitions?.() || [];
      const defMap = new Map(allDefs.map((d: any) => [d.name, d.description || '']));
      const internalTools = Array.from(allHandlers.keys());
      servers.push({
        id: 'code-intel', name: 'code-intel', url: 'internal', type: 'internal',
        transportType: 'internal', command: '', args: [], env: {}, disabled: false,
        status: 'running', tools: internalTools.map((t: unknown) => ({ name: t as string, description: defMap.get(t as string) || '', enabled: true })),
      });
    }
    const allowedServers = (permCheck.roleData as { allowedServers?: string[] })?.allowedServers;
    if (Array.isArray(allowedServers)) servers = servers.filter(s => allowedServers.includes(s.id));
    return c.json({ servers });
  });

  app.post('/api/admin/mcp/servers/:id/restart', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    if ((permCheck.roleData as { allowRestart?: boolean })?.allowRestart === false) return c.json({ error: 'Forbidden: not allowed to restart servers' }, 403);
    const serverId = c.req.param('id');
    const allowedServers = (permCheck.roleData as any)?.allowedServers;
    if (Array.isArray(allowedServers) && !allowedServers.includes('*') && !allowedServers.includes(serverId)) return c.json({ error: 'Forbidden: server not in allowedServers' }, 403);
    addMcpLog(ctx, serverId, 'INFO', `Server restart requested by ${user.username}`);
    await recordAudit(user.userId, user.username, 'RESTART_SERVER', 'mcp', serverId);
    const orchestration = ctx.registry?.getModule?.('orchestration');
    const clientManager = orchestration?.getClientManager?.();
    if (clientManager) {
      try {
        await clientManager.disconnectServer(serverId);
        const cfg = loadConfig();
        const orchPath = path.resolve(getWorkspacePath(), cfg.dataDir, cfg.orchestrationConfigPath);
        if (fs.existsSync(orchPath)) {
          const orch = JSON.parse(fs.readFileSync(orchPath, 'utf-8'));
          const serverCfg = orch.mcpServers?.[serverId];
          if (serverCfg && !serverCfg.disabled) {
            await clientManager.connectServer(serverId, serverCfg);
            const toolCount = clientManager.getServerToolCount(serverId);
            addMcpLog(ctx, serverId, 'INFO', `Reconnected. ${toolCount} tools loaded.`);
            return c.json({ success: true, status: 'connected', tools: toolCount });
          }
        }
      } catch (err: any) { addMcpLog(ctx, serverId, 'ERROR', `Restart failed: ${err.message}`); return c.json({ success: false, error: err.message, status: 'disconnected' }); }
    }
    return c.json({ success: true, message: 'Restart signal sent' });
  });

  app.post('/api/admin/mcp/servers/:id/tools/:toolName/toggle', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const serverId = c.req.param('id');
    const allowedServers = (permCheck.roleData as any)?.allowedServers;
    if (Array.isArray(allowedServers) && !allowedServers.includes(serverId)) return c.json({ error: 'Forbidden: server not in allowedServers' }, 403);
    const toolName = c.req.param('toolName');
    const { enabled } = await c.req.json();
    if (!ctx.toolToggles[serverId]) ctx.toolToggles[serverId] = {};
    ctx.toolToggles[serverId][toolName] = enabled !== false;
    addMcpLog(ctx, serverId, 'INFO', `Tool "${toolName}" ${enabled !== false ? 'enabled' : 'disabled'} by ${user.username}`);
    await recordAudit(user.userId, user.username, 'TOGGLE_TOOL', 'mcp', `${serverId}/${toolName}`, JSON.stringify({ enabled }));
    return c.json({ success: true, serverId, toolName, enabled: enabled !== false });
  });

  app.get('/api/admin/mcp/servers/:id/logs', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'MCP_ACCESS');
    if (permCheck instanceof Response) return permCheck;
    const serverId = c.req.param('id');
    const allowedServers = (permCheck.roleData as any)?.allowedServers;
    if (Array.isArray(allowedServers) && !allowedServers.includes(serverId)) return c.json({ error: 'Forbidden: server not in allowedServers' }, 403);
    const logs = ctx.mcpServerLogs[serverId] || [];
    if (logs.length === 0) {
      const now = Date.now();
      const mockLogs = [
        { offset: -300000, level: 'INFO', message: `Server "${serverId}" started successfully` },
        { offset: -240000, level: 'INFO', message: 'Connected to transport layer' },
        { offset: -180000, level: 'INFO', message: 'Tools registered and ready' },
        { offset: -60000, level: 'DEBUG', message: 'Health check passed' },
        { offset: 0, level: 'INFO', message: 'Accepting tool calls' },
      ];
      mockLogs.forEach(m => {
        if (!ctx.mcpServerLogs[serverId]) ctx.mcpServerLogs[serverId] = [];
        ctx.mcpServerLogs[serverId].push({ timestamp: new Date(now + m.offset).toISOString(), level: m.level, message: m.message });
      });
    }
    return c.json({ serverId, logs: ctx.mcpServerLogs[serverId] || [] });
  });

  return app;
}

/**
 * admin/routes/rbac.ts — RBAC group management endpoints.
 * SA4E-50: All admin-db calls are awaited; route handlers are async.
 */

import { Hono } from 'hono';
import {
  getGroups, getGroupById, createGroup, updateGroup, deleteGroup, recordAudit,
} from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createRbacRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/rbac/groups', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const groups = await getGroups();
    const result = await Promise.all(groups.map(async g => ({
      ...g, id: g.accessGroupId, name: g.accessGroupName, isSystem: g.isSystemGroup,
      userCount: await ctx.db.user.getUserCountByGroup(g.accessGroupId),
      permissions: g.permissions.map(p => ({ name: p.permissionId, roleData: p.roleData })),
    })));
    return c.json({ groups: result });
  });

  app.get('/api/admin/rbac/groups/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const group = await getGroupById(c.req.param('id'));
    if (!group) return c.json({ error: 'Group not found' }, 404);
    return c.json(group);
  });

  app.post('/api/admin/rbac/groups', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    try {
      const body = await c.req.json();
      const name = body.name || body.accessGroupName;
      if (!name) return c.json({ error: 'Group name required' }, 400);
      const permissions = (body.permissions || []).map((p: any) => ({
        permissionId: p.name || p.permissionId, roleData: p.roleData || {},
      }));
      const group = await createGroup(name, permissions);
      await recordAudit(user.userId, user.username, 'CREATE_GROUP', 'rbac', group.accessGroupId, JSON.stringify({ name }));
      return c.json({ success: true, group: { ...group, id: group.accessGroupId, name: group.accessGroupName, isSystem: false } }, 201);
    } catch (err: any) {
      if (err.message?.includes('UNIQUE')) return c.json({ error: 'Group name already exists' }, 409);
      return c.json({ error: err.message || 'Internal error' }, 500);
    }
  });

  app.put('/api/admin/rbac/groups/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    try {
      const groupId = c.req.param('id');
      const body = await c.req.json();
      const name = body.name || body.accessGroupName;
      const permissions = (body.permissions || []).map((p: any) => ({
        permissionId: p.name || p.permissionId, roleData: p.roleData || {},
      }));
      const group = await updateGroup(groupId, name, permissions);
      await recordAudit(user.userId, user.username, 'UPDATE_GROUP', 'rbac', groupId, JSON.stringify({ name, permCount: permissions.length }));
      return c.json({ success: true, group });
    } catch (err: any) { return c.json({ error: err.message || 'Internal error' }, 400); }
  });

  app.delete('/api/admin/rbac/groups/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    try {
      const groupId = c.req.param('id');
      await deleteGroup(groupId);
      await recordAudit(user.userId, user.username, 'DELETE_GROUP', 'rbac', groupId);
      return c.json({ success: true });
    } catch (err: any) { return c.json({ error: err.message }, 400); }
  });

  app.get('/api/admin/rbac/permissions', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    return c.json({
      permissions: [
        'DASHBOARD_VIEW', 'KB_READ', 'KB_WRITE', 'KB_PROMOTE', 'KB_IMPORT_EXPORT',
        'MCP_ACCESS', 'MCP_MANAGE', 'USER_MANAGE', 'RBAC_MANAGE', 'CONFIG_EDIT',
        'SEARCH_EXPLORE', 'AUDIT_VIEW', 'GRAPH_VIEW', 'ANALYTICS_VIEW',
      ],
    });
  });

  return app;
}

/**
 * admin/routes/sse.ts — Server-Sent Events for real-time dashboard stats.
 * SA4E-50: getKbEntryCount is now async; handler uses async wrapper.
 */

import { Hono } from 'hono';
import { getKbEntryCount } from '../../../admin/admin-db.js';
import { formatUptime, formatBytes } from './utils.js';
import type { AdminContext } from './context.js';

export function createSseRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/sse', async (c) => {
    const user = await ctx.authenticate(c);
    if (!user) return c.json({ error: 'Unauthorized' }, 401);

    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter();
    ctx.sseClients.add(writer);
    const encoder = new TextEncoder();

    writer.write(encoder.encode(
      `event: connected\ndata: ${JSON.stringify({ userId: user.userId, timestamp: new Date().toISOString() })}\n\n`,
    ));

    const buildStats = async () => {
      const uptimeMs = Date.now() - ctx.SERVER_START_TIME;
      const mem = process.memoryUsage();
      const userCount = await ctx.db.user.getUserCount();
      const kbCount = await getKbEntryCount(ctx.getRequestProjectId(c));
      return JSON.stringify({
        kbEntries: kbCount, users: userCount,
        uptime: { ms: uptimeMs, formatted: formatUptime(uptimeMs) },
        memory: {
          heapUsed: mem.heapUsed, heapTotal: mem.heapTotal, rss: mem.rss,
          formatted: `${formatBytes(mem.heapUsed)} / ${formatBytes(mem.heapTotal)}`,
        },
        timestamp: new Date().toISOString(),
      });
    };

    writer.write(encoder.encode(`event: stats\ndata: ${await buildStats()}\n\n`));

    const interval = setInterval(async () => {
      try { writer.write(encoder.encode(`event: stats\ndata: ${await buildStats()}\n\n`)); }
      catch { clearInterval(interval); ctx.sseClients.delete(writer); }
    }, 30000);

    c.req.raw.signal.addEventListener('abort', () => {
      clearInterval(interval);
      ctx.sseClients.delete(writer);
      writer.close().catch(() => {});
    });

    return new Response(readable, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no',
      },
    });
  });

  return app;
}

import { Hono } from 'hono';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import type { AdminContext } from './context.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export function createStaticRoutes(ctx: AdminContext): Hono {
  const app = new Hono();
  const spaPath = path.resolve(__dirname, '../../../viewer/admin/index.html');

  app.get('/admin', (c) => {
    if (fs.existsSync(spaPath)) {
      let html = fs.readFileSync(spaPath, 'utf-8');
      const token = c.req.query('token');
      const page = c.req.query('page') || '';
      const embed = c.req.query('embed');
      if (embed) {
        html = html.replace('</head>', '<style>.sidebar{display:none!important}.main{padding:0!important;height:100vh!important;width:100%!important}</style></head>');
        html = html.replace('<body>', '<body data-embed="true">');
      }
      if (token) {
        // SEC: sanitize token — only allow alphanumeric, dash, dot, underscore to prevent XSS
        const safeToken = token.replace(/[^A-Za-z0-9\-_.]/g, '');
        if (safeToken.length > 0) {
          const injectScript = '<script>localStorage.setItem("admin_token","' + safeToken + '");</script>';
          html = html.replace('</head>', injectScript + '</head>');
        }
      }
      if (page) {
        // SEC SR-07: sanitize page param — prevents reflected XSS via crafted URL
        const safePage = page.replace(/[^A-Za-z0-9\-_]/g, '');
        if (safePage) {
          html = html.replace("useState('dashboard')", "useState('" + safePage + "')");
        }
      }
      return new Response(html, { headers: { 'Content-Type': 'text/html', 'Cache-Control': 'no-store, no-cache, must-revalidate', 'Pragma': 'no-cache' } });
    }
    return c.text('Admin Portal not found', 404);
  });

  const jsFiles = ['kb-graph-renderer.js', 'gesture-fsm.js', 'camera-physics.js', 'zoom-animator.js', 'map-controls.js', 'lod-clustering.js', 'lod-manager.js', 'lod-animation.js'];
  for (const file of jsFiles) {
    app.get('/admin/' + file, (c) => {
      const fp = path.resolve(__dirname, '../../../viewer/admin/' + file);
      if (fs.existsSync(fp)) return new Response(fs.readFileSync(fp, 'utf-8'), { headers: { 'Content-Type': 'application/javascript' } });
      return c.text('Not found', 404);
    });
  }

  app.get('/admin/*', (c) => {
    if (fs.existsSync(spaPath)) {
      const html = fs.readFileSync(spaPath, 'utf-8');
      return c.html(html);
    }
    return c.text('Admin Portal not found', 404);
  });

  return app;
}

/**
 * admin/routes/users.ts — User management endpoints.
 * SA4E-50: All admin-db calls are awaited; route handlers are async.
 */

import { Hono } from 'hono';
import {
  getUserById, getUserPermissions, getUsers, createUser,
  updateUserStatus, deleteUser, resetUserPassword, changePassword,
  invalidateUserSessions, getUserSessions, recordAudit,
  getGroupById, getGroupPermissionIds,
  updateUserEmail, getAdminAdapter,
} from '../../../admin/admin-db.js';
import type { AdminContext } from './context.js';

export function createUsersRoutes(ctx: AdminContext): Hono {
  const app = new Hono();

  app.get('/api/admin/impersonate/:userId', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'RBAC_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('userId');
    const [target, targetPerms] = await Promise.all([
      getUserById(targetId),
      getUserPermissions(targetId),
    ]);
    if (!target) return c.json({ error: 'User not found' }, 404);
    return c.json({
      userId: target.userId, username: target.username,
      accessGroupId: target.accessGroupId,
      permissions: targetPerms.map(p => p.permissionId),
      roleData: targetPerms.reduce((acc, p) => { acc[p.permissionId] = p.roleData; return acc; }, {} as any),
    });
  });

  app.get('/api/admin/profile', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const requestedId = c.req.query('userId');
    let targetId = user.userId;
    if (requestedId && requestedId !== user.userId) {
      const { has } = await ctx.checkPermission(user.userId, 'USER_MANAGE');
      if (!has) {
        await recordAudit(user.userId, user.username, 'PROFILE_ACCESS_DENIED', 'users', requestedId, 'IDOR attempt');
        return c.json({ error: 'Forbidden: cannot access another user profile' }, 403);
      }
      targetId = requestedId;
    }
    const [dbUser, permissions] = await Promise.all([
      getUserById(targetId),
      getUserPermissions(targetId),
    ]);
    if (!dbUser) return c.json({ error: 'User not found' }, 404);
    return c.json({
      userId: dbUser.userId, username: dbUser.username, email: dbUser.email || '',
      group: dbUser.accessGroupId, permissions: permissions.map(p => p.permissionId),
      lastLogin: dbUser.lastLogin || new Date().toISOString(),
      forcePasswordChange: dbUser.forcePasswordChange || false,
    });
  });

  app.post('/api/admin/profile', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const { email } = await c.req.json();
    if (email !== undefined) {
      await ctx.db.user.updateEmail(user.userId, email);
      await recordAudit(user.userId, user.username, 'UPDATE_PROFILE', 'users', user.userId, JSON.stringify({ email }));
    }
    const dbUser = await getUserById(user.userId);
    return c.json({ success: true, user: { userId: dbUser?.userId, username: dbUser?.username, email: dbUser?.email } });
  });

  app.get('/api/admin/users', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const page = parseInt(c.req.query('page') || '1');
    const pageSize = parseInt(c.req.query('pageSize') || '50');
    const status = c.req.query('status') || undefined;
    const search = c.req.query('search') || undefined;
    const accessGroupId = c.req.query('accessGroupId') || undefined;
    const result = await getUsers({ status, search, accessGroupId }, page, pageSize);
    return c.json({ users: result.items, total: result.total, page, pageSize, totalPages: Math.ceil(result.total / pageSize) });
  });

  app.get('/api/admin/users/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const [targetUser, sessions] = await Promise.all([
      getUserById(c.req.param('id')),
      getUserSessions(c.req.param('id')),
    ]);
    if (!targetUser) return c.json({ error: 'User not found' }, 404);
    return c.json({ ...targetUser, sessions });
  });

  app.post('/api/admin/users', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    try {
      const { username, email, password, accessGroupId } = await c.req.json();
      if (!username || !password || !accessGroupId) return c.json({ error: 'username, password, and accessGroupId are required' }, 400);
      if (username.length < 3) return c.json({ error: 'Username must be at least 3 characters' }, 400);
      if (password.length < 6) return c.json({ error: 'Password must be at least 6 characters' }, 400);
      const [group, creatorPerms] = await Promise.all([
        getGroupById(accessGroupId),
        getUserPermissions(user.userId),
      ]);
      if (!group) return c.json({ error: 'Access group not found' }, 400);
      const creatorPermSet = new Set(creatorPerms.map(p => p.permissionId));
      const targetPerms = await getGroupPermissionIds(accessGroupId);
      const escalated = targetPerms.filter(p => !creatorPermSet.has(p));
      if (escalated.length > 0) {
        await recordAudit(user.userId, user.username, 'CREATE_USER_DENIED', 'users', undefined, JSON.stringify({ username, accessGroupId, escalatedPermissions: escalated }));
        return c.json({ error: 'Cannot assign an access group with privileges higher than your own', escalatedPermissions: escalated }, 403);
      }
      const newUser = await createUser(username, email || '', password, accessGroupId);
      await recordAudit(user.userId, user.username, 'CREATE_USER', 'users', newUser.userId, JSON.stringify({ username, accessGroupId }));
      return c.json({ success: true, user: newUser }, 201);
    } catch (err: any) {
      if (err.message?.includes('UNIQUE constraint')) return c.json({ error: 'Username already exists' }, 409);
      ctx.logger.error({ err }, 'Create user error');
      return c.json({ error: err.message || 'Internal error' }, 500);
    }
  });

  app.put('/api/admin/users/:id/status', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    const { status } = await c.req.json();
    if (!status || !['ACTIVE', 'DISABLED'].includes(status)) return c.json({ error: 'Invalid status. Must be ACTIVE or DISABLED' }, 400);
    const target = await getUserById(targetId);
    if (!target) return c.json({ error: 'User not found' }, 404);
    if (target.username === 'admin' && status === 'DISABLED') return c.json({ error: 'Cannot disable system admin' }, 403);
    const sessionsTerminated = await updateUserStatus(targetId, status);
    await recordAudit(user.userId, user.username, 'UPDATE_USER_STATUS', 'users', targetId, JSON.stringify({ status, sessionsTerminated }));
    return c.json({ success: true, sessionsTerminated });
  });

  app.put('/api/admin/users/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    try {
      const { username, email, accessGroupId } = await c.req.json();
      const target = await getUserById(targetId);
      if (!target) return c.json({ error: 'User not found' }, 404);
      if (target.username === 'admin' && username && username !== 'admin') return c.json({ error: 'Cannot rename system admin' }, 403);
      
      // Validate email if provided
      if (email !== undefined && email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return c.json({ error: 'Invalid email format' }, 400);
      }
      
      // If accessGroupId provided, validate it exists and no privilege escalation
      if (accessGroupId !== undefined) {
        const [group, creatorPerms] = await Promise.all([
          getGroupById(accessGroupId),
          getUserPermissions(user.userId),
        ]);
        if (!group) return c.json({ error: 'Access group not found' }, 400);
        const creatorPermSet = new Set(creatorPerms.map(p => p.permissionId));
        const targetPerms = await getGroupPermissionIds(accessGroupId);
        const escalated = targetPerms.filter(p => !creatorPermSet.has(p));
        if (escalated.length > 0) {
          await recordAudit(user.userId, user.username, 'UPDATE_USER_DENIED', 'users', targetId, JSON.stringify({ accessGroupId, escalatedPermissions: escalated }));
          return c.json({ error: 'Cannot assign an access group with privileges higher than your own', escalatedPermissions: escalated }, 403);
        }
      }
      
      // Update user - we'll update fields that were provided
      if (username !== undefined && username !== target.username) {
        const adapter = getAdminAdapter();
        await adapter.runAsync('UPDATE users SET username = ? WHERE user_id = ?', [username, targetId]);
      }
      if (email !== undefined && email !== target.email) {
        await updateUserEmail(targetId, email);
      }
      if (accessGroupId !== undefined && accessGroupId !== target.accessGroupId) {
        const adapter = getAdminAdapter();
        await adapter.runAsync('UPDATE users SET access_group_id = ? WHERE user_id = ?', [accessGroupId, targetId]);
      }
      
      const updated = await getUserById(targetId);
      await recordAudit(user.userId, user.username, 'UPDATE_USER', 'users', targetId, JSON.stringify({ username, email, accessGroupId }));
      return c.json({ success: true, user: updated });
    } catch (err: any) {
      if (err.message?.includes('UNIQUE constraint')) return c.json({ error: 'Username already exists' }, 409);
      ctx.logger.error({ err }, 'Update user error');
      return c.json({ error: err.message || 'Internal error' }, 500);
    }
  });

  app.delete('/api/admin/users/:id', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    try {
      const target = await getUserById(targetId);
      if (!target) return c.json({ error: 'User not found' }, 404);
      await deleteUser(targetId);
      await recordAudit(user.userId, user.username, 'DELETE_USER', 'users', targetId, JSON.stringify({ username: target.username }));
      return c.json({ success: true });
    } catch (err: any) { return c.json({ error: err.message }, 400); }
  });

  app.post('/api/admin/users/:id/force-logout', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    const target = await getUserById(targetId);
    if (!target) return c.json({ error: 'User not found' }, 404);
    const terminated = await invalidateUserSessions(targetId);
    await recordAudit(user.userId, user.username, 'FORCE_LOGOUT', 'users', targetId, JSON.stringify({ terminated }));
    return c.json({ success: true, terminated });
  });

  app.post('/api/admin/users/:id/reset-password', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    const target = await getUserById(targetId);
    if (!target) return c.json({ error: 'User not found' }, 404);
    const temporaryPassword = await resetUserPassword(targetId);
    await invalidateUserSessions(targetId);
    await recordAudit(user.userId, user.username, 'RESET_PASSWORD', 'users', targetId);
    return c.json({ success: true, temporaryPassword });
  });

  app.post('/api/admin/users/:id/change-password', async (c) => {
    const user = await ctx.requireAuth(c);
    if (user instanceof Response) return user;
    const permCheck = await ctx.requirePermission(c, user.userId, 'USER_MANAGE');
    if (permCheck instanceof Response) return permCheck;
    const targetId = c.req.param('id');
    const target = await getUserById(targetId);
    if (!target) return c.json({ error: 'User not found' }, 404);
    const { newPassword } = await c.req.json();
    if (!newPassword || newPassword.length < 6) return c.json({ error: 'Password must be at least 6 characters' }, 400);
    await changePassword(targetId, newPassword);
    await recordAudit(user.userId, user.username, 'CHANGE_PASSWORD_ADMIN', 'users', targetId);
    return c.json({ success: true });
  });

  return app;
}

/**
 * SA4E-78 — Decoupled indexer endpoints (SRP: separated from legacy api-index).
 * POST /api/index/full — trigger async full index (202 Accepted)
 * POST /api/index/file-events — push file change events from Extension
 * POST /api/index/cancel — cancel running index via AbortController
 * GET  /api/index/progress — poll current progress
 */

import type { Context } from 'hono';
import type { Logger } from 'pino';
import * as fs from 'fs';
import * as path from 'path';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import type { CodeIntelModule } from '../../modules/code-intel/CodeIntelModule.js';
import { IndexOperationManager } from '../../engine/indexer/index-operation-manager.js';
import { loadConfig } from '../../config/index.js';
import { requireProjectId } from '../../engine/query/code-intel-isolation.js';
import { resolveWithinWorkspace } from '../../shared/path-safety.js';
import type { FileEvent, FileEventsResult } from '../../engine/indexer/types.js';

/** Max events per request to prevent abuse. */
const MAX_EVENTS_PER_REQUEST = 100;

/** Singleton manager map — one per CodeIntelModule lifetime. */
const managerCache = new WeakMap<object, IndexOperationManager>();

/** Get or create IndexOperationManager for the codeIntel module. */
function getManager(registry: ModuleRegistry): IndexOperationManager | null {
  const codeIntel = registry.getModule('codeIntel') as CodeIntelModule | undefined;
  if (!codeIntel || codeIntel.status !== 'ready') return null;
  const indexer = codeIntel.getIndexer();
  if (!indexer) return null;

  let manager = managerCache.get(codeIntel);
  if (!manager) {
    manager = new IndexOperationManager(indexer);
    managerCache.set(codeIntel, manager);
  }
  return manager;
}

/** Resolve project scope from request headers. */
function resolveScope(c: Context, sessionUserId?: string) {
  const config = loadConfig();
  const projectId = requireProjectId(c.req.header('X-Project-Id') || config.projectId);
  const userId = sessionUserId || 'default';
  // indexTempDir/{userId}/{projectId} for source file writes
  const workspace = path.join(config.indexTempDir, userId, projectId);
  if (!fs.existsSync(workspace)) fs.mkdirSync(workspace, { recursive: true });
  return { projectId, workspace };
}

/**
 * POST /api/index/full — Trigger async full index.
 * @returns 202 with operationId, or 409 if already running.
 */
export async function handleFullIndex(c: Context, registry: ModuleRegistry, logger: Logger) {
  try {
    const scope = resolveScope(c);
    const manager = getManager(registry);
    if (!manager) return c.json({ error: 'Code intelligence not ready' }, 503);

    const op = manager.startOperation(scope.projectId, scope);
    if (!op) {
      // Already running — return 409
      const progress = manager.getProgress(scope.projectId);
      return c.json({
        error: 'Index already running',
        operationId: progress.operationId,
        projectId: scope.projectId,
      }, 409);
    }

    logger.info({ operationId: op.operationId, projectId: scope.projectId }, '[index] Full index started');
    return c.json({
      operationId: op.operationId,
      projectId: scope.projectId,
      status: 'started',
      message: 'Full index started',
    }, 202);
  } catch (err: unknown) {
    return handleError(c, err, logger, 'Error starting full index');
  }
}

/**
 * POST /api/index/file-events — Receive file change events from Extension.
 * Processes sequentially to avoid DB contention.
 */
export async function handleFileEvents(c: Context, registry: ModuleRegistry, logger: Logger) {
  try {
    const scope = resolveScope(c);
    const body = await c.req.json() as { events: FileEvent[] };
    const { events } = body;

    if (!events || !Array.isArray(events)) {
      return c.json({ error: 'events array required' }, 400);
    }
    if (events.length > MAX_EVENTS_PER_REQUEST) {
      return c.json({ error: `Max ${MAX_EVENTS_PER_REQUEST} events per request` }, 413);
    }

    const codeIntel = registry.getModule('codeIntel') as CodeIntelModule | undefined;
    const indexer = codeIntel?.getIndexer() as any;
    if (!indexer) return c.json({ error: 'Code intelligence not ready' }, 503);

    const result: FileEventsResult = {
      indexed: 0, updated: 0, removed: 0,
      skipped: 0, rejected: [], projectId: scope.projectId,
    };

    for (const event of events) {
      const processed = await processFileEvent(
        event, scope, indexer, logger,
      );
      if (processed === 'rejected') result.rejected.push(event.path);
      else if (processed === 'indexed') result.indexed++;
      else if (processed === 'updated') result.updated++;
      else if (processed === 'removed') result.removed++;
      else result.skipped++;
    }

    return c.json(result);
  } catch (err: unknown) {
    return handleError(c, err, logger, 'Error processing file events');
  }
}

/** Process a single file event — returns outcome category. */
async function processFileEvent(
  event: FileEvent,
  scope: { projectId: string; workspace: string },
  indexer: any,
  logger: Logger,
): Promise<'indexed' | 'updated' | 'removed' | 'skipped' | 'rejected'> {
  const safePath = resolveWithinWorkspace(scope.workspace, event.path);
  if (!safePath) return 'rejected';

  if (event.type === 'delete') {
    indexer.removeFile(event.path);
    return 'removed';
  }

  // For add/change: write content if provided, then index
  if (event.content) {
    fs.mkdirSync(path.dirname(safePath), { recursive: true });
    fs.writeFileSync(safePath, event.content, 'utf-8');
  }

  try {
    await indexer.indexSingleFile(event.path, scope.projectId);
    return event.type === 'add' ? 'indexed' : 'updated';
  } catch (err) {
    logger.warn({ err, file: event.path }, '[index] file-event index failed');
    return 'skipped';
  }
}

/**
 * POST /api/index/cancel — Cancel running index operation.
 * @returns 200 with cancelled status, or 404 if no active operation.
 */
export async function handleCancel(c: Context, registry: ModuleRegistry, logger: Logger) {
  try {
    const scope = resolveScope(c);
    const manager = getManager(registry);
    if (!manager) return c.json({ error: 'Code intelligence not ready' }, 503);

    const op = manager.cancelOperation(scope.projectId);
    if (!op) {
      return c.json({ error: 'No active index operation', projectId: scope.projectId }, 404);
    }

    logger.info({ operationId: op.operationId }, '[index] Cancel signal sent');
    return c.json({
      operationId: op.operationId,
      status: 'cancelling',
      message: 'Cancellation signal sent',
    });
  } catch (err: unknown) {
    return handleError(c, err, logger, 'Error cancelling index');
  }
}

/**
 * GET /api/index/progress — Poll current indexing progress.
 * @returns Current progress snapshot (idle if no operation).
 */
export async function handleProgress(c: Context, registry: ModuleRegistry, _logger: Logger) {
  const scope = resolveScope(c);
  const manager = getManager(registry);
  if (!manager) return c.json({ error: 'Code intelligence not ready' }, 503);

  const progress = manager.getProgress(scope.projectId);
  return c.json(progress);
}

/** Shared error handler for decoupled endpoints. */
function handleError(c: Context, err: unknown, logger: Logger, context: string) {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg.startsWith('PROJECT_REQUIRED')) {
    return c.json({ error: 'X-Project-Id required' }, 400);
  }
  logger.error({ err }, context);
  return c.json({ error: 'Internal error' }, 500);
}

﻿/**
 * Source/document indexing endpoints — POST /api/index/source|document|documents.
 * SA4E-41: every write is path-safe (SEC-04/05) and tenant-scoped (requireProjectId).
 */

import { Hono } from 'hono';
import type { Context } from 'hono';
import type { Logger } from 'pino';
import * as fs from 'fs';
import * as path from 'path';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import type { CodeIntelModule } from '../../modules/code-intel/CodeIntelModule.js';
import { loadConfig } from '../../config/index.js';
import { getAdminAdapter } from '../../admin/db/core.js';
import { GraphRepository } from '../../database/repositories/GraphRepository.js';
import { requireProjectId } from '../../engine/query/code-intel-isolation.js';
import { resolveWithinWorkspace } from '../../shared/path-safety.js';
import { validateSession } from '../../admin/db/sessions.js';
import type { FileDependency } from '../../engine/parsers/types.js';
import {
  handleFullIndex, handleFileEvents, handleCancel, handleProgress,
} from './api-index-decoupled.js';

interface SourceFile {
  path: string;
  content: string;
  gitHash?: string;
  checksum?: string;
}
interface IndexScope { projectId: string; workspace: string }

/** Resolve request scope — uses authenticated userId from session for tenant isolation. */
function resolveRequestScope(c: Context, sessionUserId?: string): IndexScope {
  const config = loadConfig();
  const projectId = requireProjectId(c.req.header('X-Project-Id') || config.projectId);
  const userId = sessionUserId || 'default';
  // indexTempDir/{userId}/{projectId} for source file writes
  const workspace = path.join(config.indexTempDir, userId, projectId);
  if (!fs.existsSync(workspace)) fs.mkdirSync(workspace, { recursive: true });
  return { projectId, workspace };
}

/** Extract userId from Bearer token (non-fatal — returns '' if unauthenticated). */
// NOTE: resolveUserId kept for backward compatibility but auth is now enforced at route level

/** Phase: write files to disk under the workspace, rejecting unsafe paths. */
function writeFilesPhase(workspace: string, files: SourceFile[]): { written: number; rejected: string[] } {
  const rejected: string[] = [];
  let written = 0;
  for (const file of files) {
    const targetPath = resolveWithinWorkspace(workspace, file.path);
    if (!targetPath) { rejected.push(file.path); continue; }
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.writeFileSync(targetPath, file.content, 'utf-8');
    written++;
  }
  return { written, rejected };
}

/** Phase: register/update the project in the admin registry (non-fatal). */
async function registerProjectPhase(projectId: string, workspace: string, logger: Logger, createdBy = '', realWorkspaceRoot?: string): Promise<void> {
  try {
    const graphRepo = new GraphRepository(getAdminAdapter());
    const displayName = await deriveDisplayName(realWorkspaceRoot || workspace);
    const displayPath = realWorkspaceRoot || workspace;
    await graphRepo.registerProject(projectId, displayName, displayPath, createdBy);
  } catch (err) {
    logger.warn({ err, projectId }, '[index] project registry upsert skipped (non-fatal)');
  }
}

/** Derive human-readable project name: git repo name > folder name. Pega handled separately. */
async function deriveDisplayName(workspaceRoot: string): Promise<string> {
  // 1. Try git repo name from remote URL
  try {
    const { execSync } = await import('child_process');
    const remote = execSync('git remote get-url origin', { cwd: workspaceRoot, encoding: 'utf-8', timeout: 3000 }).trim();
    if (remote) {
      // Parse: https://github.com/org/repo-name.git → repo-name
      // Parse: git@github.com:org/repo-name.git → repo-name
      const match = remote.match(/\/([^/]+?)(?:\.git)?$/);
      if (match) return match[1];
    }
  } catch { /* no git or no remote — fallback */ }
  // 2. Fallback: folder name
  return path.basename(workspaceRoot) || 'Untitled Project';
}

/** Phase: trigger a scoped background full re-index. Returns whether an indexer ran. */
function triggerIndexPhase(registry: ModuleRegistry, scope: IndexScope, logger: Logger): boolean {
  const codeIntel = registry.getModule('codeIntel') as CodeIntelModule | undefined;
  const indexer = codeIntel?.getIndexer();
  if (!indexer) return false;
  indexer.runFullIndex({ projectId: scope.projectId, workspace: scope.workspace })
    .catch((err: unknown) => logger.error({ err }, 'Background full re-index failed'));
  return true;
}

/** Phase: ensure a KB metadata entry + graph node exist for the project (non-fatal). */
/** Phase: ensure a KB metadata entry + graph node exist for the project (non-fatal). */
async function ensureProjectKbEntry(registry: ModuleRegistry, scope: IndexScope, written: number, logger: Logger): Promise<void> {
  try {
    const mem = registry.getModule('memory') as any;
    if (mem?.status !== 'ready') return;
    const engine = mem.getEngine();
    const displayName = path.basename(scope.workspace);
    // Use async insert — engine.insert() is now async for PostgreSQL compatibility
    const entryId = await engine.insert({
      content: `Project "${displayName}" indexed. Workspace: ${scope.workspace}. Files: ${written}.`,
      summary: `Project metadata for ${displayName}`,
      type: 'CONTEXT', tier: 'SEMANTIC', scope: 'PROJECT',
      project_id: scope.projectId, source: 'project-metadata', tags: 'project,metadata,indexed',
    });
    await upsertProjectGraphNode(String(entryId), displayName, scope.projectId, logger);
  } catch (err) {
    logger.warn({ err }, '[index] project KB entry skipped (non-fatal)');
  }
}

/** Upsert the project-metadata graph node (INSERT OR REPLACE to fix stale/missing rows). */
async function upsertProjectGraphNode(entryId: string, displayName: string, projectId: string, logger: Logger): Promise<void> {
  try {
    const graphRepo = new GraphRepository(getAdminAdapter());
    await graphRepo.upsertNode({
      entryId, label: `Project: ${displayName}`, type: 'CONTEXT',
      tier: 'SEMANTIC', projectId, x: 0, y: 0, z: 0, level: 'macro', clusterId: '0',
    });
  } catch (err) {
    logger.warn({ err }, '[index] graph node upsert skipped (non-fatal)');
  }
}

/** Require valid session — returns 401 if not authenticated. */
async function requireAuth(c: Context): Promise<{ userId: string } | null> {
  const auth = c.req.header('Authorization') || '';
  const token = auth.replace('Bearer ', '').trim();
  if (!token) return null;
  const session = await validateSession(token);
  return session ?? null;
}

/** Register the /api/index/* routes on the given app. */
export function registerIndexRoutes(app: Hono, registry: ModuleRegistry, logger: Logger): void {
  app.post('/api/index/source', async (c) => {
    const session = await requireAuth(c);
    if (!session) return c.json({ error: 'Unauthorized' }, 401);
    return handleIndexSource(c, registry, logger, session.userId);
  });
  app.post('/api/index/document', async (c) => {
    const session = await requireAuth(c);
    if (!session) return c.json({ error: 'Unauthorized' }, 401);
    return handleIndexDocument(c, logger, session.userId);
  });
  app.post('/api/index/documents', async (c) => {
    const session = await requireAuth(c);
    if (!session) return c.json({ error: 'Unauthorized' }, 401);
