async function handleIndexSource(c: Context, registry: ModuleRegistry, logger: Logger, userId = '') {
  try {
    const body = await c.req.json() as { files: SourceFile[] };
    const { files } = body;
    if (!files || !Array.isArray(files)) return c.json({ error: 'files array required' }, 400);
    const scope = resolveRequestScope(c, userId);
    const realWorkspaceRoot = c.req.header('X-Workspace-Root') || '';
    await registerProjectPhase(scope.projectId, scope.workspace, logger, userId, realWorkspaceRoot || undefined);

    const codeIntel = registry.getModule('codeIntel') as CodeIntelModule | undefined;
    const indexer = codeIntel?.getIndexer() as any;

    const written: string[] = [];
    const indexed: string[] = [];
    const indexFailed: string[] = [];
    const skipped: string[] = [];
    const rejected: string[] = [];
    const allDeps: FileDependency[] = [];

    for (const file of files) {
      const targetPath = resolveWithinWorkspace(scope.workspace, file.path);
      if (!targetPath) { rejected.push(file.path); continue; }

      const fileHash = file.gitHash || file.checksum || '';

      if (indexer && fileHash) {
        try {
          const existing = await indexer.adapter.getAsync(
            'SELECT content_hash FROM files WHERE relative_path = ? AND project_id = ?',
            [file.path, scope.projectId],
          ) as { content_hash: string } | undefined;
          if (existing && existing.content_hash === fileHash.slice(0, 16)) {
            skipped.push(file.path);
            continue;
          }
        } catch {
          // Table may not exist yet — proceed with indexing
        }
      }

      fs.mkdirSync(path.dirname(targetPath), { recursive: true });
      fs.writeFileSync(targetPath, file.content, 'utf-8');
      written.push(file.path);

      // Index single file and collect deps
      if (indexer) {
        try {
          const result = await indexer.indexSingleFile(file.path, scope.projectId);
          if (result && result.symbolCount > 0) {
            indexed.push(file.path);
            if (result.dependencies) {
              for (const dep of result.dependencies) {
                if (!allDeps.some(d => d.path === dep.path)) {
                  allDeps.push(dep);
                }
              }
            }
          } else {
            indexFailed.push(file.path);
          }
        } catch (err) {
          indexFailed.push(file.path);
          logger.warn({ err, file: file.path }, '[index] single-file index failed');
        }
      }
    }

    if (rejected.length > 0) logger.warn({ rejected, projectId: scope.projectId }, '[index] rejected unsafe paths');
    if (indexFailed.length > 0) logger.warn({ count: indexFailed.length, projectId: scope.projectId }, '[index] files written but DB index failed');
    await ensureProjectKbEntry(registry, scope, indexed.length, logger);

    // SA4E-107: Create LLM enrichment tasks for newly indexed symbols (async, non-blocking)
    if (indexer && indexed.length > 0) {
      try {
        const { CodeEnrichmentTaskCreator } = await import('../../engine/enrichment/CodeEnrichmentTaskCreator.js');
        const creator = new CodeEnrichmentTaskCreator(indexer.adapter, logger);
        const created = await creator.createTasksForProject(scope.projectId);
        if (created > 0) logger.info({ created, projectId: scope.projectId }, '[index] Enrichment tasks queued');
      } catch (err) {
        logger.warn({ err }, '[index] Enrichment task creation skipped (non-fatal)');
      }
    }

    return c.json({ written: written.length, indexed: indexed.length, indexFailed: indexFailed.length, skipped: skipped.length, rejected, deps: allDeps, projectId: scope.projectId });
  } catch (err: any) {
    return indexError(c, err, logger, 'Error writing source batch');
  }
}

async function handleIndexDocument(c: Context, logger: Logger, userId = '') {
  try {
    const body = await c.req.json() as { path: string; content: string };
    const { path: relPath, content } = body;
    if (!relPath || !content) return c.json({ error: 'path and content required' }, 400);
    const scope = resolveRequestScope(c, userId);
    const targetPath = resolveWithinWorkspace(scope.workspace, relPath);
    if (!targetPath) return c.json({ error: 'Invalid path' }, 400);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.writeFileSync(targetPath, content, 'utf-8');
    return c.json({ success: true });
  } catch (err: any) {
    return indexError(c, err, logger, 'Error writing document');
  }
}

async function handleIndexDocuments(c: Context, logger: Logger, userId = '') {
  try {
    const body = await c.req.json() as { files: SourceFile[] };
    const { files } = body;
    if (!files || !Array.isArray(files)) return c.json({ error: 'files array required' }, 400);
    const scope = resolveRequestScope(c, userId);
    const { written, rejected } = writeFilesPhase(scope.workspace, files);
    if (rejected.length > 0) logger.warn({ rejected, projectId: scope.projectId }, '[index] rejected unsafe paths');
    return c.json({ indexed: written, rejected });
  } catch (err: any) {
    return indexError(c, err, logger, 'Error writing documents batch');
  }
}

/** Map errors to responses — PROJECT_REQUIRED → 400, everything else → 500. */
function indexError(c: Context, err: any, logger: Logger, context: string) {
  if (String(err?.message).startsWith('PROJECT_REQUIRED')) {
    return c.json({ error: 'X-Project-Id required for indexing' }, 400);
  }
  logger.error({ err }, context);
  return c.json({ error: 'Internal error' }, 500);
}

/**
 * Database Configuration API routes.
 * Implements: SA4E-33, UC-1 through UC-6
 * SEC: All endpoints require authentication + CONFIG_EDIT permission.
 */

import { Hono } from 'hono';
import { streamSSE } from 'hono/streaming';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import { DatabaseConfigService } from '../../database/config/DatabaseConfigService.js';
import { DatabaseAdapterFactory } from '../../database/factory/DatabaseAdapterFactory.js';
import { MigrationService, type MigrationProgress } from '../../database/migration/MigrationService.js';
import { validateSession } from '../../admin/db/sessions.js';
import type { Context } from 'hono';
import { z } from 'zod';

const connectionSchema = z.object({
  engine: z.enum(['postgresql', 'mysql']),
  host: z.string().min(1),
  port: z.number().int().min(1).max(65535),
  username: z.string().min(1),
  password: z.string().min(1),
  database: z.string().min(1),
  ssl: z.boolean().default(false),
});

let activeMigration: MigrationService | null = null;

/** Require valid admin session. Returns null → caller must return 401. */
async function requireDatabaseAuth(c: Context): Promise<{ userId: string } | null> {
  const auth = c.req.header('Authorization') || '';
  const token = auth.replace('Bearer ', '').trim();
  if (!token) return null;
  return await validateSession(token) ?? null;
}

export function createDatabaseRoute(registry: ModuleRegistry, logger: Logger, dataDir: string): Hono {
  const app = new Hono();
  const configService = new DatabaseConfigService(dataDir);

  app.get('/api/admin/database/status', async (c) => {
    if (!await requireDatabaseAuth(c)) return c.json({ error: 'Unauthorized' }, 401);
    try {
      const config = configService.load();
      return c.json({ success: true, data: { engine: config.activeEngine, status: 'connected', lastMigration: config.migration.lastMigration } });
    } catch (err) {
      return c.json({ success: false, error: { code: 'STATUS_ERROR', message: (err as Error).message } }, 500);
    }
  });

  app.post('/api/admin/database/test-connection', async (c) => {
    if (!await requireDatabaseAuth(c)) return c.json({ error: 'Unauthorized' }, 401);
    const body = await c.req.json();
    const parsed = connectionSchema.safeParse(body);
    if (!parsed.success) return c.json({ success: false, error: { code: 'VALIDATION', message: parsed.error.message } }, 400);
    const { engine, host, port, username, password, database, ssl } = parsed.data;
    const adapter = DatabaseAdapterFactory.create({ engine, host, port, username, password, database, ssl });
    try {
      const start = Date.now();
      await adapter.connect();
      const version = await adapter.getVersion();
      const tables = await adapter.getTableNames();
      await adapter.disconnect();
      return c.json({ success: true, data: { connected: true, serverVersion: version, existingTables: tables.length, latencyMs: Date.now() - start } });
    } catch (err) {
      const msg = (err as Error).message;
      let code = 'CONN_ERROR';
      if (msg.includes('auth') || msg.includes('password')) code = 'AUTH_FAILED';
      else if (msg.includes('timeout') || msg.includes('ECONNREFUSED')) code = 'CONN_TIMEOUT';
      else if (msg.includes('not exist') || msg.includes('Unknown database')) code = 'DB_NOT_FOUND';
      return c.json({ success: false, error: { code, message: msg } }, 400);
    }
  });

  app.post('/api/admin/database/migrate', async (c) => {
    if (!await requireDatabaseAuth(c)) return c.json({ error: 'Unauthorized' }, 401);
    const body = await c.req.json();
    const parsed = connectionSchema.safeParse(body);
    if (!parsed.success) return c.json({ success: false, error: { code: 'VALIDATION', message: parsed.error.message } }, 400);
    if (activeMigration) return c.json({ success: false, error: { code: 'MIGRATION_ACTIVE', message: 'Already migrating' } }, 409);
    const { engine, host, port, username, password, database, ssl } = parsed.data;
    const sourceConfig = configService.getActiveConfig();
    const source = DatabaseAdapterFactory.create(sourceConfig);
    await source.connect();
    return streamSSE(c, async (stream) => {
      const migration = new MigrationService(source, { engine, host, port, username, password, database, ssl }, configService,
        (ev: MigrationProgress) => { stream.writeSSE({ event: ev.phase === 'complete' ? 'complete' : 'progress', data: JSON.stringify(ev) }); }
      );
      activeMigration = migration;
      try {
        const result = await migration.migrate();
        stream.writeSSE({ event: result.success ? 'complete' : 'error', data: JSON.stringify(result) });
      } finally { activeMigration = null; await source.disconnect(); }
    });
  });

  app.post('/api/admin/database/migrate/cancel', async (c) => {
    if (!await requireDatabaseAuth(c)) return c.json({ error: 'Unauthorized' }, 401);
    if (!activeMigration) return c.json({ success: false, error: { code: 'NO_MIGRATION', message: 'No active migration' } }, 400);
    activeMigration.cancel();
    return c.json({ success: true, data: { message: 'Cancel requested' } });
  });

  app.post('/api/admin/database/switch-to-sqlite', async (c) => {
    if (!await requireDatabaseAuth(c)) return c.json({ error: 'Unauthorized' }, 401);
    try { configService.setActiveEngine('sqlite'); return c.json({ success: true, data: { message: 'Switched to SQLite' } }); }
    catch (err) { return c.json({ success: false, error: { code: 'CONFIG_WRITE_FAIL', message: (err as Error).message } }, 500); }
  });

  return app;
}

/**
 * SA4E-157 — Enrichment Status Route.
 * GET /api/v1/enrichment/status — returns current LLM enrichment progress.
 * JWT auth required, no admin permission check (read-only status data).
 */

import { Hono } from 'hono';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import { jwtAuth } from '../middleware/jwt-auth.js';
import { deriveEnrichmentState } from '../../shared/schemas/EnrichmentStatusSchema.js';
import type { EnrichmentStatusResponse } from '../../shared/schemas/EnrichmentStatusSchema.js';
import type { TaskWorker } from '../../modules/memory/task-queue/TaskWorker.js';

/**
 * Create enrichment status route group.
 * @param registry Module registry for accessing TaskWorker
 * @param logger Pino logger instance
 * @returns Hono app with enrichment status routes
 */
export function createEnrichmentStatusRoutes(registry: ModuleRegistry, logger: Logger): Hono {
  const app = new Hono();
  app.use('*', jwtAuth);

  app.get('/enrichment/status', async (c) => {
    try {
      const taskWorker = getTaskWorker(registry);
      if (!taskWorker) {
        return c.json({ error: 'Enrichment service unavailable', details: 'TaskWorker not initialized' }, 503);
      }

      // Filter by project_id from request context (X-Project-Id header or JWT)
      const projectId = c.req.header('X-Project-Id') || '';

      const response = await buildStatusResponse(taskWorker, projectId);
      return c.json(response, 200);
    } catch (err: any) {
      logger.error({ err }, '[EnrichmentStatus] Failed to retrieve status');
      return c.json({ error: 'Failed to retrieve enrichment status', details: err.message }, 500);
    }
  });

  /** POST /api/v1/enrichment/retry-failed — reset all failed tasks to pending for re-processing. */
  app.post('/enrichment/retry-failed', async (c) => {
    try {
      const taskWorker = getTaskWorker(registry);
      if (!taskWorker) {
        return c.json({ error: 'Enrichment service unavailable', details: 'TaskWorker not initialized' }, 503);
      }
      const repo = taskWorker.getRepository();
      const resetCount = await repo.retryAllFailed();
      logger.info({ resetCount }, '[EnrichmentStatus] Retry failed tasks');
      return c.json({ data: { resetCount, message: `${resetCount} failed tasks reset to pending` }, error: null });
    } catch (err: any) {
      logger.error({ err }, '[EnrichmentStatus] Retry failed tasks error');
      return c.json({ error: 'Failed to retry tasks', details: err.message }, 500);
    }
  });

  return app;
}

/** Extract TaskWorker from registry via memory module (same pattern as admin routes). */
function getTaskWorker(registry: ModuleRegistry): TaskWorker | null {
  const memory = registry.getModule('memory') as any;
  return memory?.taskWorker ?? null;
}

/** Build the full enrichment status response from TaskWorker data, scoped to project. */
async function buildStatusResponse(taskWorker: TaskWorker, projectId: string): Promise<EnrichmentStatusResponse & { activeTasks: Array<{ source: string }>; recentFailures: Array<{ symbolName: string; error: string; taskId: number }> }> {
  const repo = taskWorker.getRepository();
  const progress = await taskWorker.getProgress();

  // Project-scoped stats: JOIN pending_tasks with knowledge_entries to filter by project_id
  const rawStats = projectId
    ? await repo.getStatsByProject(projectId)
    : await taskWorker.getStats();
  const startedAt = await repo.getEarliestActiveTimestamp();

  // PostgreSQL COUNT returns bigint as string — ensure numbers
  const stats = {
    pending: Number(rawStats.pending) || 0,
    processing: Number(rawStats.processing) || 0,
    completed: Number(rawStats.completed) || 0,
    failed: Number(rawStats.failed) || 0,
    isRunning: (rawStats as any).isRunning ?? (Number(rawStats.processing) > 0 || Number(rawStats.pending) > 0),
    lastPollAt: (rawStats as any).lastPollAt ?? null,
  };

  const state = deriveEnrichmentState(stats);
  const total = stats.pending + stats.processing + stats.completed + stats.failed;
  // BR-02: percent = completed / total * 100
  const percent = total > 0 ? Math.round((stats.completed / total) * 100) : 0;
  const estimatedCompletion = computeEstimatedCompletion(stats.completed, total, startedAt);

  return {
    state,
    projectId: projectId || null,
    totalRules: total,
    completedRules: stats.completed,
    failedRules: stats.failed,
    pendingRules: stats.pending,
    processingRules: stats.processing,
    percent,
    isRunning: stats.isRunning,
    startedAt,
    estimatedCompletion,
    currentFile: progress?.file ?? null,
    lastPollAt: stats.lastPollAt,
    activeTasks: await getActiveTasks(repo, projectId),
    recentFailures: await getRecentFailures(repo),
  };
}

/**
 * Compute estimated completion time (BR-08).
 * Only meaningful when completedRules >= 10 (avoids wild extrapolation).
 */
function computeEstimatedCompletion(
  completed: number, total: number, startedAt: string | null,
): string | null {
  if (!startedAt || completed < 10 || total === 0) return null;
  const start = new Date(startedAt).getTime();
  if (isNaN(start)) return null;
  const now = Date.now();
  const elapsed = now - start;
  if (elapsed <= 0) return null;
  const msPerTask = elapsed / completed;
  const remaining = total - completed;
  const etaMs = now + msPerTask * remaining;
  if (!isFinite(etaMs)) return null;
  return new Date(etaMs).toISOString();
}

/** Get currently processing tasks for tooltip display, scoped by project. */
async function getActiveTasks(
  repo: InstanceType<typeof import('../../modules/memory/task-queue/PendingTaskRepository.js').PendingTaskRepository>,
  projectId?: string,
): Promise<Array<{ source: string }>> {
  try {
    const tasks = await repo.listProcessing(5, projectId);
    return tasks.map((t) => ({ source: t.source }));
  } catch {
    return [];
  }
}

/** Get recent failed tasks with error messages for dashboard display. */
async function getRecentFailures(
  repo: InstanceType<typeof import('../../modules/memory/task-queue/PendingTaskRepository.js').PendingTaskRepository>,
): Promise<Array<{ symbolName: string; error: string; taskId: number }>> {
  try {
    const tasks = await repo.listFailed(10);
    return tasks.map((t) => {
      const payload = typeof t.payload === 'string' ? JSON.parse(t.payload) : t.payload;
      return {
        taskId: t.id,
        symbolName: payload?.symbolName || payload?.filePath || `entry-${t.entry_id}`,
        error: (t as any).error || 'Unknown error',
      };
    });
  } catch {
    return [];
  }
}

