/**
 * Hono route for POST /api/v1/pega/ingest-rule — Single-rule ingestion with relative extraction.
 * SA4E-156: Per-rule BFS-compatible endpoint returning discovered dependencies.
 * Pattern: Factory — createIngestRuleRoute() follows existing Hono route factory conventions.
 */

import { Hono } from 'hono';
import { bodyLimit } from 'hono/body-limit';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import { PegaService } from '../../modules/pega/PegaService.js';
import { IngestRuleRequestSchema } from '../../modules/pega/schemas/ingest-rule.schema.js';
import { RelativeExtractor } from '../../modules/pega/services/RelativeExtractor.js';
import { PegaSchemaLoader } from '../../modules/pega/PegaSchemaLoader.js';
import type { PegaRuleKbSchema } from '../../modules/pega/strategies/KbDrivenPegaParserStrategy.js';

/** Build schemaMap from pega-core-schemas.json (cached singleton) */
let cachedSchemaMap: Map<string, PegaRuleKbSchema> | null = null;

function getSchemaMap(): Map<string, PegaRuleKbSchema> {
  if (!cachedSchemaMap) {
    const schemas = PegaSchemaLoader.loadAllSchemas();
    cachedSchemaMap = new Map(schemas.map((s) => [s.targetClass, s]));
  }
  return cachedSchemaMap;
}

/**
 * Create Hono route for single-rule ingestion + relative extraction.
 * @param registry - Module registry for accessing memory/PegaService
 * @param logger - Pino logger instance
 */
export function createIngestRuleRoute(registry: ModuleRegistry, logger: Logger): Hono {
  const app = new Hono();

  // 10MB body limit per rule JSON
  app.use('*', bodyLimit({ maxSize: 10 * 1024 * 1024 }));

  app.post('/', async (c) => {
    // 1. Resolve PegaService from memory module
    const service = resolvePegaService(registry);
    if (!service) {
      return c.json({
        data: null,
        error: { code: 'NOT_READY', message: 'Memory module not ready' },
      }, 503);
    }

    // 2. Parse and validate request body
    const body = await c.req.json().catch(() => null);
    if (!body) {
      return c.json({
        data: null,
        error: { code: 'VALIDATION_ERROR', message: 'Invalid JSON body' },
      }, 400);
    }

    const parsed = IngestRuleRequestSchema.safeParse(body);
    if (!parsed.success) {
      const msg = parsed.error.errors[0]?.message || 'Invalid request';
      return c.json({
        data: null,
        error: { code: 'VALIDATION_ERROR', message: msg },
      }, 400);
    }

    // 3. Ingest rule via PegaService
    const { projectId, ruleJson, checksum, version } = parsed.data;
    const ingestResult = await ingestSafely(service, projectId, ruleJson, checksum, version, logger);
    if (ingestResult.error) {
      return c.json({
        data: null,
        error: { code: 'INTERNAL_ERROR', message: ingestResult.error },
      }, 500);
    }

    // 4. Extract relatives via RelativeExtractor
    const schemaMap = getSchemaMap();
    const extractor = new RelativeExtractor(schemaMap);
    const relatives = extractor.extract(ruleJson as Record<string, unknown>);

    // 5. Return combined response
    const status = ingestResult.ruleId === -1 ? 200 : 201;
    return c.json({
      data: {
        status: ingestResult.status,
        ruleId: ingestResult.ruleId,
        unresolvedDependencies: relatives,
        reason: ingestResult.reason,
      },
      error: null,
    }, status);
  });

  return app;
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/** Lazily resolve PegaService from memory module */
function resolvePegaService(registry: ModuleRegistry): PegaService | null {
  const memModule = registry.getModule('memory') as any;
  if (!memModule || memModule.status !== 'ready') return null;
  return new PegaService(memModule.getEngine());
}

/** Wrap ingestRule in try/catch to prevent unhandled exceptions */
async function ingestSafely(
  service: PegaService,
  projectId: string,
  ruleJson: Record<string, unknown>,
  checksum: string | undefined,
  version: string | undefined,
  logger: Logger,
): Promise<{ status: string; ruleId?: number; reason?: string; error?: string }> {
  try {
    const result = await service.ingestRule({ projectId, ruleJson, checksum, version });
    return { status: result.status, ruleId: result.ruleId, reason: result.reason };
  } catch (err: any) {
    logger.error({ err: err.message, stack: err.stack }, '[pega-ingest-rule] Ingestion failed');
    return { status: 'error', error: 'Ingestion failed. Check server logs for details.' };
  }
}

/**
 * SA4E-95 — Pega Schema Generation Routes.
 * POST /pega/schema/generate — Backend parses harness JSON + section JSONs → returns JSON Schema.
 * Architecture: Extension fetches from Pega, backend only does analysis.
 */

import { Hono } from 'hono';
import type { Logger } from 'pino';
import { HarnessParser } from '../../modules/pega/harness-schema/parser/HarnessParser.js';
import { SchemaBuilder } from '../../modules/pega/harness-schema/generator/SchemaBuilder.js';
import { FormatTypeMapper } from '../../modules/pega/harness-schema/generator/FormatTypeMapper.js';
import { PageContextResolver } from '../../modules/pega/harness-schema/resolver/PageContextResolver.js';
import { ClassHierarchyResolver } from '../../modules/pega/harness-schema/resolver/ClassHierarchyResolver.js';

/** Request body: extension sends raw harness + pre-fetched sections */
interface SchemaGenerateRequest {
  harnessJson: Record<string, unknown>;
  sectionJsons?: Record<string, Record<string, unknown>>;
  ruleType?: string;
}

/**
 * Create schema generation routes.
 * Backend does NOT talk to Pega — extension provides all raw JSON.
 */
export function createPegaSchemaRoutes(logger: Logger): Hono {
  const app = new Hono();
  const formatMapper = new FormatTypeMapper();
  const schemaBuilder = new SchemaBuilder(formatMapper);
  const contextResolver = new PageContextResolver();

  /**
   * POST /pega/schema/generate
   * Receives raw harness JSON + optional pre-fetched sections.
   * Returns generated JSON Schema.
   */
  app.post('/pega/schema/generate', async (c) => {
    const body = await c.req.json<SchemaGenerateRequest>();

    if (!body.harnessJson) {
      return c.json({ error: 'Missing harnessJson in request body' }, 400);
    }

    try {
      // Create a local hierarchy resolver that uses provided sections (no API calls)
      const localResolver = createLocalResolver(body.sectionJsons || {});
      const parser = new HarnessParser(
        createNoOpFetcher(),
        localResolver,
        contextResolver,
      );

      const parsedHarness = await parser.parse(body.harnessJson);
      const schema = schemaBuilder.build(parsedHarness);
      const coverage = schemaBuilder.calculateCoverage(parsedHarness);

      logger.info({
        ruleType: parsedHarness.ruleType,
        fieldCount: Object.keys(schema.properties).length,
        coverage,
      }, '[pega-schema] Schema generated');

      return c.json({
        schema,
        ruleType: parsedHarness.ruleType,
        coverage,
        templateSections: parsedHarness.templateMarkers.map(m => m.sectionName),
      });
    } catch (err: any) {
      logger.error({ err: err.message }, '[pega-schema] Generation failed');
      return c.json({
        error: 'Schema generation failed',
        details: err.message,
      }, 500);
    }
  });

  return app;
}

/** Create a resolver that looks up sections from provided map (no network calls) */
function createLocalResolver(
  sectionJsons: Record<string, Record<string, unknown>>,
): ClassHierarchyResolver {
  const resolver = Object.create(ClassHierarchyResolver.prototype) as ClassHierarchyResolver;
  (resolver as any).resolveSection = async (name: string, _targetClass: string) => {
    const json = sectionJsons[name];
    if (!json) return null;
    return { sectionJson: json, resolvedClass: (json.pyClassName as string) || '@baseclass' };
  };
  (resolver as any).getClassHierarchy = (_className: string) => ['@baseclass'];
  return resolver;
}

/** No-op fetcher since backend doesn't call Pega API */
function createNoOpFetcher(): any {
  return {
    fetchHarness: async () => null,
    fetchSection: async () => null,
  };
}

/**
 * Helper functions for pega-stream route — DB queries, project registration, line processing.
 * Extracted to keep route file ≤ 200 lines (SRP compliance).
 */

import type { Logger } from 'pino';
import type { PegaService } from '../../modules/pega/PegaService.js';

/** Metadata sent as the first NDJSON line */
export interface StreamMetadata {
  __meta: true;
  projectId: string;
  checksums: Record<string, string>;
  versions: Record<string, string>;
  visitedKeys: string[];
}

/** Result of processing a single NDJSON line */
export interface LineResult {
  isMeta: boolean;
  meta?: StreamMetadata;
  stored: boolean;
  rule?: Record<string, unknown>;
}

/** Process a single NDJSON line — either metadata or a rule to index (Phase 1 only) */
export async function processOneLine(
  line: string,
  meta: StreamMetadata | null,
  service: PegaService,
  logger: Logger,
): Promise<LineResult> {
  let obj: Record<string, unknown>;
  try {
    obj = JSON.parse(line);
  } catch {
    logger.debug({ line: line.substring(0, 80) }, '[pega-stream] Malformed JSON line — skipping');
    return { isMeta: false, stored: false };
  }

  if (obj.__meta) {
    return { isMeta: true, meta: obj as unknown as StreamMetadata, stored: false };
  }

  if (!meta) {
    logger.warn('[pega-stream] Rule received before metadata line — skipping');
    return { isMeta: false, stored: false };
  }

  try {
    const sym = service.parseRuleToSymbol(obj);
    const checksum = sym ? meta.checksums[sym.fqn] : undefined;
    const version = sym ? meta.versions[sym.fqn] : undefined;

    // SA4E-158: Use indexRuleOnly (Phase 1) — no KB/graph/enrichment
    const result = await service.indexRuleOnly({
      projectId: meta.projectId,
      ruleJson: obj,
      checksum,
      version,
    });

    const didStore = result.status === 'success' && result.ruleId !== -1;
    return { isMeta: false, stored: didStore, rule: didStore ? obj : undefined };
  } catch (err: any) {
    logger.debug({ err: err.message }, '[pega-stream] Single rule index failed — skipping');
    return { isMeta: false, stored: false };
  }
}

/** Aggregate totals from the knowledge database */
export interface PegaDbTotals {
  totalRulesInDb: number;
  totalKbEntriesInDb: number;
  totalGraphNodesInDb: number;
}

/** Query aggregate totals from the database for a given project */
export async function queryPegaTotals(service: PegaService, projectId: string): Promise<PegaDbTotals> {
  let totalRulesInDb = 0;
  let totalKbEntriesInDb = 0;
  let totalGraphNodesInDb = 0;

  try {
    const adapter = (service as any).memoryEngine.getAdapter();

    const rowRules = await adapter.getAsync(
      "SELECT COUNT(*) as cnt FROM symbols WHERE project_id = $1 AND kind LIKE 'pega_%'",
      [projectId],
    ) as { cnt?: number } | undefined;
    if (rowRules?.cnt) totalRulesInDb = Number(rowRules.cnt);

    const rowKb = await adapter.getAsync(
      "SELECT COUNT(*) as cnt FROM symbols WHERE project_id = $1",
      [projectId],
    ) as { cnt?: number } | undefined;
    if (rowKb?.cnt) totalKbEntriesInDb = Number(rowKb.cnt);

    const rowGraph = await adapter.getAsync(
      "SELECT COUNT(*) as cnt FROM graph_nodes WHERE project_id = $1",
      [projectId],
    ) as { cnt?: number } | undefined;
    if (rowGraph?.cnt) totalGraphNodesInDb = Number(rowGraph.cnt);
  } catch (err) { console.debug('[pega-stream] Failed to query DB totals (fallback to zeros):', (err as Error).message); }

  return { totalRulesInDb, totalKbEntriesInDb, totalGraphNodesInDb };
}

/** Register project in project_registry table (non-fatal on failure) */
export async function registerPegaProject(
  service: PegaService,
  projectId: string,
  ingestedRules: Record<string, unknown>[],
): Promise<void> {
  try {
    const adapter = (service as any).memoryEngine.getAdapter();
    const eng = adapter.getEngine();
    const ts = eng === 'sqlite' ? `datetime('now')` : 'current_timestamp';
    const appName = (ingestedRules[0] as any)?.pyApplication || projectId;
    await adapter.runAsync(
      `INSERT INTO project_registry (project_id, display_name, workspace_path, created_by, last_seen)
       VALUES ($1, $2, $3, $4, ${ts})
       ON CONFLICT (project_id) DO UPDATE SET last_seen = ${ts}`,
      [projectId, 'Pega: ' + appName, '', 'pega-crawler'],
    );
  } catch (err) { console.debug('[pega-stream] Failed to register project in project_registry (non-fatal):', (err as Error).message); }
}

/**
 * Async NDJSON ingest endpoint for Pega rules (SA4E-94).
 * POST /pega/ingest-stream — accepts NDJSON body, returns 202 + jobId immediately.
 * GET /pega/jobs/:id — poll job progress/status.
 * Background processing via setImmediate batches (50 rules/tick) to avoid blocking event loop.
 */

import { Hono } from 'hono';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import { PegaService } from '../../modules/pega/PegaService.js';
import { queryPegaTotals, registerPegaProject, processOneLine } from './pega-stream-helpers.js';
import type { StreamMetadata } from './pega-stream-helpers.js';
import { pegaJobStore } from './pega-job-store.js';
import type { JobResult } from './pega-job-store.js';

/** Number of rules processed per setImmediate tick */
const BATCH_SIZE = 50;

/**
 * Create Hono routes for async NDJSON ingest + job polling.
 * @param registry - Module registry for accessing memory/PegaService
 * @param logger - Pino logger instance
 */
export function createPegaStreamRoutes(registry: ModuleRegistry, logger: Logger): Hono {
  const app = new Hono();

  /** Lazily resolve PegaService from memory module */
  const resolvePegaService = (): PegaService | null => {
    const memModule = registry.getModule('memory') as any;
    if (!memModule || memModule.status !== 'ready') return null;
    return new PegaService(memModule.getEngine());
  };

  // POST /pega/ingest-stream — buffer body, return 202 + jobId, process in background
  app.post('/pega/ingest-stream', async (c) => {
    const service = resolvePegaService();
    if (!service) {
      return c.json({ data: null, error: { code: 'NOT_READY', message: 'Memory module not ready' } }, 503);
    }

    // Stream body line-by-line to avoid OOM on large payloads (39K+ rules)
    const reader = c.req.raw.body?.getReader();
    if (!reader) {
      return c.json({ data: null, error: { code: 'NO_BODY', message: 'Request body is empty' } }, 400);
    }

    // Read stream into lines incrementally (still buffers lines array, but not raw text)
    const lines: string[] = [];
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const parts = buffer.split('\n');
      buffer = parts.pop() || '';
      for (const p of parts) { if (p.trim()) lines.push(p); }
    }
    if (buffer.trim()) lines.push(buffer);

    if (lines.length === 0) {
      return c.json({ data: null, error: { code: 'NO_BODY', message: 'Request body is empty' } }, 400);
    }

    const jobId = pegaJobStore.createJob(lines.length);

    logger.info({ jobId, lineCount: lines.length }, '[pega-stream] Job created, processing in background');
    processInBackground(jobId, lines, service, logger);

    return c.json({ data: { jobId }, error: null }, 202);
  });

  // GET /pega/jobs/:id — return current job status + progress
  app.get('/pega/jobs/:id', (c) => {
    const id = c.req.param('id');
    const job = pegaJobStore.getJob(id);

    if (!job) {
      return c.json({ data: null, error: { code: 'NOT_FOUND', message: `Job ${id} not found or expired` } }, 404);
    }

    return c.json({
      data: { status: job.status, progress: job.progress, result: job.result, error: job.error },
      error: null,
    });
  });

  return app;
}

/**
 * Process NDJSON lines in background using setImmediate batches.
 * Processes BATCH_SIZE rules per tick to avoid blocking the event loop.
 */
function processInBackground(jobId: string, lines: string[], service: PegaService, logger: Logger): void {
  let meta: StreamMetadata | null = null;
  let stored = 0;
  let index = 0;
  const ingestedRules: Record<string, unknown>[] = [];

  const processNextBatch = (): void => {
    const end = Math.min(index + BATCH_SIZE, lines.length);

    const promises: Promise<void>[] = [];
    for (let i = index; i < end; i++) {
      promises.push(processOneLine(lines[i], meta, service, logger).then((result) => {
        if (result.isMeta) meta = result.meta!;
        if (result.stored) { stored++; ingestedRules.push(result.rule!); }
      }));
    }

    Promise.all(promises)
      .then(() => {
        index = end;
        pegaJobStore.updateProgress(jobId, index);

        if (index < lines.length) {
          setImmediate(processNextBatch);
        } else {
          return finalizeJob(jobId, meta, stored, ingestedRules, service, logger);
        }
      })
      .catch((err) => {
        logger.error({ err, jobId }, '[pega-stream] Background processing failed');
        pegaJobStore.fail(jobId, err.message || 'Unknown processing error');
      });
  };

  setImmediate(processNextBatch);
}

/** Compute totals + next batch after all lines processed, then mark job done */
async function finalizeJob(
  jobId: string,
  meta: StreamMetadata | null,
  stored: number,
  ingestedRules: Record<string, unknown>[],
  service: PegaService,
  logger: Logger,
): Promise<void> {
  let totals = { totalRulesInDb: 0, totalKbEntriesInDb: 0, totalGraphNodesInDb: 0 };
  let nextBatch: JobResult['nextBatch'] = [];

  try {
    totals = await queryPegaTotals(service, meta?.projectId || '');
  } catch (err: any) {
    logger.warn({ err: err.message }, '[pega-stream] queryPegaTotals failed — using zeros');
  }

  // SA4E-94: computeNextBatch removed — enumeration is handled by extension
  nextBatch = [];

  if (meta) await registerPegaProject(service, meta.projectId, ingestedRules);

  const result: JobResult = { stored, ...totals, nextBatch };
  pegaJobStore.complete(jobId, result);
  logger.info({ jobId, stored, total: totals.totalRulesInDb }, '[pega-stream] Job complete');
}

/**
 * SA4E-158 — POST /api/v1/pega/sync-to-kb
 * Triggers Phase 2: re-project Pega code graph nodes for a project.
 * SA4E-171: rules already live in symbols (indexed by Phase 1) — no KB writes.
 */
import { Hono } from 'hono';
import type { Logger } from 'pino';
import type { ModuleRegistry } from '../../modules/ModuleRegistry.js';
import { PegaService } from '../../modules/pega/PegaService.js';

/**
 * Create route for Pega KB sync endpoint.
 * @param registry - Module registry for accessing memory/PegaService
 * @param logger - Pino logger instance
 */
export function createPegaSyncToKbRoutes(registry: ModuleRegistry, logger: Logger): Hono {
  const app = new Hono();

  /** Lazily resolve PegaService from memory module */
  const resolvePegaService = (): PegaService | null => {
    const memModule = registry.getModule('memory') as any;
    if (!memModule || memModule.status !== 'ready') return null;
    return new PegaService(memModule.getEngine());
  };

  /** Check if LLM TagAnalyzer is available (TaskWorker has it set). */
  const isLlmAvailable = (): boolean => {
    const memModule = registry.getModule('memory') as any;
    if (!memModule) return false;
    const worker = memModule.taskWorker;
    return !!(worker as any)?.tagAnalyzer;
  };

  /**
   * POST /pega/sync-to-kb — Sync indexed rules to KB for a project.
   * Body: { projectId: string }
   * Returns: { synced, skipped, errors, llmStatus, details[] }
   */
  app.post('/pega/sync-to-kb', async (c) => {
    const service = resolvePegaService();
    if (!service) {
      return c.json({
        data: null,
        error: { code: 'NOT_READY', message: 'Memory module not ready' },
      }, 503);
    }

    try {
      const body = await c.req.json<{ projectId: string }>();
      if (!body.projectId) {
        return c.json({
          data: null,
          error: { code: 'INVALID_INPUT', message: 'projectId is required' },
        }, 400);
      }

      // Duplicate prevention: check if there are already pending enrichment tasks for this project
      const pendingCount = await checkPendingTaskCount(registry, body.projectId);
      if (pendingCount > 100) {
        logger.info({ projectId: body.projectId, pendingCount },
          '[pega-sync-to-kb] Skipped — enrichment already in progress');
        return c.json({
          data: { synced: 0, skipped: 0, errors: 0, details: [],
            llmStatus: `⚠️ Enrichment already in progress (${pendingCount} tasks pending). Wait for completion.`,
            llmReady: isLlmAvailable(), alreadyRunning: true, pendingCount },
          error: null,
        });
      }

      logger.info({ projectId: body.projectId }, '[pega-sync-to-kb] Starting graph sync');
      const result = await service.syncIndexedRulesToKb(body.projectId);

      logger.info({ projectId: body.projectId, synced: result.synced, errors: result.errors },
        '[pega-sync-to-kb] Graph sync complete');

      return c.json({ data: { ...result }, error: null });
    } catch (err: any) {
      logger.error({ err }, '[pega-sync-to-kb] Sync failed');
      return c.json({
        data: null,
        error: { code: 'INTERNAL_ERROR', message: err.message },
      }, 500);
    }
  });

  return app;
}

/** Check how many pending/processing tasks exist for TAG_ENRICHMENT. */
async function checkPendingTaskCount(registry: ModuleRegistry, _projectId: string): Promise<number> {
  try {
    const memModule = registry.getModule('memory') as any;
    if (!memModule?.taskWorker) return 0;
    const stats = await memModule.taskWorker.getStats();
    return (stats.pending || 0) + (stats.processing || 0);
  } catch { return 0; }
}

