/** Helper: create a mock Response object */
function createMockResponse(status: number, body: string): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    headers: new Headers(),
    text: () => Promise.resolve(body),
  } as unknown as Response;
}

/**
 * SA4E-110 — Unit tests for CredentialManager (UT-05, UT-14, UT-21)
 * IPC message handling, auth header generation, staleness check.
