﻿/**
 * SA4E-110 - Jira user tools (4 tools).
 * myself, search_users, watchers, add_watcher.
 */
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import type { JiraApiClient } from '../clients/jira-client.js';
import { UserSearchSchema, WatcherSchema, GetAttachmentsSchema } from '../models/jira-schemas.js';
import { createSuccessResult, createErrorResult } from '../models/error-schemas.js';
import { AtlassianErrorCode } from '../models/types.js';
import { AtlassianApiError } from '../clients/base-client.js';
import { z } from 'zod';

const IssueKeyOnly = z.object({ issue_key: z.string().min(1) });

/** Register Jira user and watcher tools */
export function registerJiraUserTools(server: McpServer, client: JiraApiClient): void {
  server.tool('jira_get_myself', 'Get current authenticated user info', async () => {
    try { return createSuccessResult((await client.getMyself()).data); }
    catch (e) { return handleError(e); }
  });

  server.registerTool('jira_search_users', { description: 'Search for Jira users', inputSchema: UserSearchSchema }, async (args, _extra) => {
    const parsed = UserSearchSchema.safeParse(args);
    if (!parsed.success) return createErrorResult(AtlassianErrorCode.VALIDATION_ERROR, parsed.error.message);
    try { return createSuccessResult((await client.searchUsers(parsed.data.query, parsed.data.startAt, parsed.data.maxResults)).data); }
    catch (e) { return handleError(e); }
  });

  server.registerTool('jira_get_watchers', { description: 'Get watchers on a Jira issue', inputSchema: IssueKeyOnly }, async (args, _extra) => {
    const parsed = IssueKeyOnly.safeParse(args);
    if (!parsed.success) return createErrorResult(AtlassianErrorCode.VALIDATION_ERROR, parsed.error.message);
    try { return createSuccessResult((await client.getWatchers(parsed.data.issue_key)).data); }
    catch (e) { return handleError(e); }
  });

  server.registerTool('jira_add_watcher', { description: 'Add a watcher to a Jira issue', inputSchema: WatcherSchema }, async (args, _extra) => {
    const parsed = WatcherSchema.safeParse(args);
    if (!parsed.success) return createErrorResult(AtlassianErrorCode.VALIDATION_ERROR, parsed.error.message);
    try {
      await client.addWatcher(parsed.data.issue_key, parsed.data.account_id);
      return createSuccessResult({ success: true });
    } catch (e) { return handleError(e); }
  });
}

function handleError(e: unknown) {
  if (e instanceof AtlassianApiError) return createErrorResult(e.code, e.message);
  return createErrorResult(AtlassianErrorCode.UNKNOWN, (e as Error).message);
}

/**
 * EventBus — typed publish/subscribe for module lifecycle and tool events.
 * Observer pattern: modules and services communicate via events without direct coupling.
 * Replaces index.ts post-init wiring (getModule() casts) with event-driven setup.
 */

export type EventCallback<T = unknown> = (payload: T) => void | Promise<void>;

export interface Unsubscribe {
  (): void;
}

type EventHandler = { callback: EventCallback; once: boolean };

export class EventBus {
  private handlers = new Map<string, Set<EventHandler>>();

  on<T>(event: string, callback: EventCallback<T>): Unsubscribe {
    return this.addHandler(event, callback, false);
  }

  once<T>(event: string, callback: EventCallback<T>): Unsubscribe {
    return this.addHandler(event, callback, true);
  }

  off<T>(event: string, callback: EventCallback<T>): void {
    const set = this.handlers.get(event);
    if (!set) return;
    for (const h of set) {
      if (h.callback === callback) { set.delete(h); break; }
    }
    if (set.size === 0) this.handlers.delete(event);
  }

  async emit<T>(event: string, payload: T): Promise<void> {
    const set = this.handlers.get(event);
    if (!set) return;
    const toRemove: EventHandler[] = [];
    for (const handler of set) {
      try {
        await handler.callback(payload);
      } catch (err) { /* subscriber errors never crash the bus */ console.debug('[EventBus] Subscriber error for event:', event, (err as Error).message); }
      if (handler.once) toRemove.push(handler);
    }
    for (const h of toRemove) set.delete(h);
    if (set.size === 0) this.handlers.delete(event);
  }

  clear(): void {
    this.handlers.clear();
  }

  private addHandler<T>(event: string, callback: EventCallback<T>, once: boolean): Unsubscribe {
    if (!this.handlers.has(event)) this.handlers.set(event, new Set());
    const handler: EventHandler = { callback: callback as EventCallback<unknown>, once };
    this.handlers.get(event)!.add(handler);
    return () => { const s = this.handlers.get(event); if (s) { s.delete(handler); if (s.size === 0) this.handlers.delete(event); } };
  }
}

export const bus = new EventBus();

export const Events = {
  MODULE_REGISTERED: 'module:registered',
  MODULE_READY: 'module:ready',
  MODULE_ERROR: 'module:error',
  MODULE_STOPPED: 'module:stopped',
  ALL_MODULES_READY: 'all:modules:ready',
  TOOLS_INGESTED: 'tools:ingested',
  TOOL_EXECUTED: 'tool:executed',
  /** Emitted when admin saves an LLM config change — payload: { section, key, value } */
  LLM_CONFIG_CHANGED: 'llm:config:changed',
  /** Emitted when admin saves a TaskWorker config change — payload: { section, key, value } */
  TASK_WORKER_CONFIG_CHANGED: 'taskworker:config:changed',
} as const;

/**
 * Unit tests — EventBus (typed pub/sub bus).
 * Verifies on/once/off subscriptions, unsubscribe functions, async emission
 * ordering, subscriber error isolation, clear(), and event constants.
 */

import { describe, it, expect, vi } from 'vitest';
import { EventBus, Events } from '../EventBus.js';

describe('EventBus', () => {
  it('delivers payloads to on() subscribers', async () => {
    const bus = new EventBus();
    const cb = vi.fn();
    bus.on('evt', cb);
    await bus.emit('evt', { a: 1 });
    expect(cb).toHaveBeenCalledWith({ a: 1 });
  });

  it('does not call subscribers for events without listeners', async () => {
    const bus = new EventBus();
    await expect(bus.emit('nothing', 1)).resolves.toBeUndefined();
  });

  it('supports multiple subscribers on the same event', async () => {
    const bus = new EventBus();
    const a = vi.fn();
    const b = vi.fn();
    bus.on('evt', a);
    bus.on('evt', b);
    await bus.emit('evt', 'x');
    expect(a).toHaveBeenCalledOnce();
    expect(b).toHaveBeenCalledOnce();
  });

  it('off() removes a specific handler only', async () => {
    const bus = new EventBus();
    const a = vi.fn();
    const b = vi.fn();
    bus.on('evt', a);
    bus.on('evt', b);
    bus.off('evt', a);
    await bus.emit('evt', 1);
    expect(a).not.toHaveBeenCalled();
    expect(b).toHaveBeenCalledTimes(1);
  });

  it('off() on an unknown event or non-registered handler is safe', async () => {
    const bus = new EventBus();
    const cb = vi.fn();
    expect(() => bus.off('missing', cb)).not.toThrow();
    bus.on('evt', cb);
    expect(() => bus.off('evt', vi.fn())).not.toThrow();
  });

  it('once() fires a single time then self-removes', async () => {
    const bus = new EventBus();
    const cb = vi.fn();
    bus.once('evt', cb);
    await bus.emit('evt', 1);
    await bus.emit('evt', 2);
    expect(cb).toHaveBeenCalledTimes(1);
    expect(cb).toHaveBeenCalledWith(1);
  });

  it('on() returns an unsubscribe function', async () => {
    const bus = new EventBus();
    const cb = vi.fn();
    const unsubscribe = bus.on('evt', cb);
    unsubscribe();
    await bus.emit('evt', 1);
    expect(cb).not.toHaveBeenCalled();
  });

  it('once() also returns a working unsubscribe function', async () => {
    const bus = new EventBus();
    const cb = vi.fn();
    const unsubscribe = bus.once('evt', cb);
    unsubscribe();
    await bus.emit('evt', 1);
    expect(cb).not.toHaveBeenCalled();
  });

  it('awaits async subscribers and preserves ordering', async () => {
    const bus = new EventBus();
    const order: string[] = [];
    bus.on('evt', async () => { await new Promise(r => setTimeout(r, 10)); order.push('slow'); });
    bus.on('evt', async () => { order.push('fast'); });
    await bus.emit('evt', null);
    expect(order).toEqual(['slow', 'fast']);
  });

  it('isolates subscriber errors so the bus never crashes', async () => {
    const bus = new EventBus();
    const debug = vi.spyOn(console, 'debug').mockImplementation(() => {});
    const bad = vi.fn(() => { throw new Error('boom'); });
    const good = vi.fn();
    bus.on('evt', bad as any);
    bus.on('evt', good);
    await expect(bus.emit('evt', 1)).resolves.toBeUndefined();
    expect(good).toHaveBeenCalledTimes(1);
    expect(debug).toHaveBeenCalled();
    debug.mockRestore();
  });

  it('clear() removes all handlers', async () => {
    const bus = new EventBus();
    const a = vi.fn();
    const b = vi.fn();
    bus.on('e1', a);
    bus.on('e2', b);
    bus.clear();
    await bus.emit('e1', 1);
    await bus.emit('e2', 2);
    expect(a).not.toHaveBeenCalled();
    expect(b).not.toHaveBeenCalled();
  });

  it('exposes the Events constants map', () => {
    expect(Events.MODULE_READY).toBe('module:ready');
    expect(Events.ALL_MODULES_READY).toBe('all:modules:ready');
    expect(Events.TOOLS_INGESTED).toBe('tools:ingested');
    expect(Events.LLM_CONFIG_CHANGED).toBe('llm:config:changed');
  });
});

/**
 * Unit tests — shared path-safety helpers (SA4E-41 SEC-04/05).
 * Verifies traversal/absolute/null-byte rejection, workspace containment
 * checks, and the resolveWithinWorkspace combiner.
 */

import * as path from 'path';
import { describe, it, expect } from 'vitest';
import { isPathSafe, isWithinRoot, resolveWithinWorkspace } from '../path-safety.js';

describe('isPathSafe', () => {
  it('accepts simple relative paths', () => {
    expect(isPathSafe('a/b/c.ts')).toBe(true);
    expect(isPathSafe('file.txt')).toBe(true);
  });

  it('rejects empty and non-string inputs', () => {
    expect(isPathSafe('')).toBe(false);
    expect(isPathSafe(undefined as any)).toBe(false);
    expect(isPathSafe(null as any)).toBe(false);
    expect(isPathSafe(123 as any)).toBe(false);
  });

  it('rejects null-byte inputs', () => {
    expect(isPathSafe('a\0b')).toBe(false);
  });

  it('rejects absolute paths', () => {
    expect(isPathSafe('/etc/passwd')).toBe(false);
    expect(isPathSafe('C:\\Windows\\System32')).toBe(false);
  });

  it("rejects pure and prefix '..' traversal", () => {
    expect(isPathSafe('..')).toBe(false);
    expect(isPathSafe('../x')).toBe(false);
    expect(isPathSafe('../../etc')).toBe(false);
  });

  it("rejects embedded '..' segments after normalization", () => {
    expect(isPathSafe('a/../../b')).toBe(false);
    expect(isPathSafe('a/../..')).toBe(false);
  });

  it('rejects backslash traversal on any platform', () => {
    expect(isPathSafe('..\\..\\etc\\passwd')).toBe(false);
    expect(isPathSafe('a\\..\\..\\b')).toBe(false);
  });
});

describe('isWithinRoot', () => {
  const root = path.resolve('/workspace/proj-a');

  it('is true when fullPath equals root', () => {
    expect(isWithinRoot(root, path.join(root))).toBe(true);
  });

  it('is true for descendants of root', () => {
    expect(isWithinRoot(root, path.join(root, 'src', 'index.ts'))).toBe(true);
  });

  it('is false for paths outside the root', () => {
    expect(isWithinRoot(root, path.resolve('/workspace/proj-b/secret.txt'))).toBe(false);
    expect(isWithinRoot(root, path.resolve('/etc/passwd'))).toBe(false);
  });

  it('is false for a sibling directory that merely shares a name prefix', () => {
    expect(isWithinRoot(root, path.resolve('/workspace/proj-a-2/x.ts'))).toBe(false);
  });
});

describe('resolveWithinWorkspace', () => {
  const ws = path.resolve('/data/workspace');

  it('resolves a safe relative path inside the workspace', () => {
    const resolved = resolveWithinWorkspace(ws, 'docs/plan.md');
    expect(resolved).toBe(path.join(ws, 'docs', 'plan.md'));
  });

  it('returns null for traversal attempts', () => {
    expect(resolveWithinWorkspace(ws, '../outside.md')).toBeNull();
    expect(resolveWithinWorkspace(ws, 'a/../../outside.md')).toBeNull();
  });

  it('returns null for absolute paths', () => {
    expect(resolveWithinWorkspace(ws, '/etc/passwd')).toBeNull();
    expect(resolveWithinWorkspace(ws, 'C:\\secret.txt')).toBeNull();
  });

  it('returns null for null-byte inputs', () => {
    expect(resolveWithinWorkspace(ws, 'a\0b')).toBeNull();
  });
});

/**
 * ToolHandlerDecorators — composable higher-order functions for tool handlers.
 * Decorator pattern: wrap base handlers with cross-cutting concerns.
 *
 * Usage:
 *   const handler = compose(
 *     withErrorHandling(logger),
 *     withScopeContext(dispatcher),
 *     withResultFormat,
 *   )(coreHandler);
 */

import type { Logger } from 'pino';
import type { ToolHandler, ToolResult } from '../types/tool.js';

type CoreHandler<T = unknown> = (args: Record<string, unknown>) => T | Promise<T>;

function isToolResult(v: unknown): v is ToolResult {
  return typeof v === 'object' && v !== null && 'content' in v && 'isError' in v;
}

function toResult(text: string): ToolResult {
  return { content: [{ type: 'text' as const, text }], isError: false };
}

function errorResult(text: string): ToolResult {
  return { content: [{ type: 'text' as const, text }], isError: true };
}

export function withErrorHandling(logger: Logger, toolName: string): (next: CoreHandler<ToolResult>) => ToolHandler {
  return (next) => async (args) => {
    try {
      return await next(args);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      logger.error({ tool: toolName, err }, 'Tool execution failed');
      return errorResult(`Error: ${message}`);
    }
  };
}

export function withScopeContext(dispatcher: { setScopeContext: (ctx: { userId: string; projectId?: string } | undefined) => void }): (next: ToolHandler) => ToolHandler {
  return (next) => async (args) => {
    const injectedCtx = (args as any)._projectContext;
    if (injectedCtx) {
      dispatcher.setScopeContext({ userId: injectedCtx.userId || '', projectId: injectedCtx.projectId || '' });
    } else {
      const userId = (args as any).__userId as string | undefined;
      // SA4E-103: Also read __projectId stamped by stampProjectScope (MCP tool call path)
      const projectId = (args as any).__projectId as string | undefined;
      dispatcher.setScopeContext(userId || projectId ? { userId: userId || '', projectId } : undefined);
    }
    return next(args);
  };
}

export function withProjectId(next: (args: Record<string, unknown>, projectId?: string) => Promise<string>): ToolHandler {
  return async (args) => {
    const projectId = (args as any).__projectId as string | undefined;
    const result = await next(args, projectId);
    return toResult(result);
  };
}

export function withResultFormat(next: CoreHandler<string | null>): ToolHandler {
  return async (args) => {
    const text = await next(args);
    if (text === null) return errorResult('Unknown tool');
    return toResult(text);
  };
}

export function withTextResult(next: CoreHandler<string>): ToolHandler {
  return async (args) => {
    const text = await next(args);
    return toResult(text);
  };
}

export function compose<T>(...fns: Array<(next: any) => any>): (base: T) => T {
  return (base: T) => fns.reduceRight((acc, fn) => fn(acc), base);
}

/**
 * Tool routing layer.
 * Routes tool_name to the appropriate module handler.
 * Wraps execution with a timeout boundary (default 60s) and structured error handling.
 */

import type { ToolHandler, ToolDefinition, ToolResult, ToolCallRequest } from '../types/tool.js';
import type { ModuleRegistry } from '../modules/ModuleRegistry.js';
import type { Logger } from 'pino';

/** Default per-tool execution timeout in milliseconds. */
const DEFAULT_TOOL_TIMEOUT_MS = 60_000;

/** Race a promise against a timeout, rejecting with a descriptive error on timeout. */
function withTimeout<T>(promise: Promise<T>, ms: number, toolName: string): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new Error(`Tool '${toolName}' timed out after ${ms}ms`)),
      ms,
    );
    promise.then(
      (v) => { clearTimeout(timer); resolve(v); },
      (e) => { clearTimeout(timer); reject(e); },
    );
  });
}

export class ToolRouter {
  private registry: ModuleRegistry;
  private logger: Logger;
  private readonly toolTimeoutMs: number;

  constructor(registry: ModuleRegistry, logger: Logger, toolTimeoutMs = DEFAULT_TOOL_TIMEOUT_MS) {
    this.registry = registry;
    this.logger = logger;
    this.toolTimeoutMs = toolTimeoutMs;
  }

  async route(request: ToolCallRequest): Promise<ToolResult> {
    const { tool_name, arguments: args } = request;
    const handlers = this.registry.getToolHandlers();
    const handler = handlers.get(tool_name);

    if (!handler) {
      this.logger.warn({ tool_name }, 'Tool not found');
      return {
        content: [{ type: 'text', text: `Tool '${tool_name}' not found` }],
        isError: true,
      };
    }

    const requestId = crypto.randomUUID();
    const start = Date.now();

    this.logger.debug({ tool_name, requestId }, 'Tool call start');

    try {
      const result = await withTimeout(handler(args), this.toolTimeoutMs, tool_name);
      const duration = Date.now() - start;
      this.logger.debug({ tool_name, requestId, duration_ms: duration }, 'Tool call complete');
      return result;
    } catch (err) {
      const duration = Date.now() - start;
      const message = err instanceof Error ? err.message : String(err);
      const isTimeout = message.includes('timed out');
      this.logger.error({ tool_name, requestId, duration_ms: duration, timeout: isTimeout, err }, 'Tool call error');
      return {
        content: [{ type: 'text', text: `Tool execution failed: ${message}` }],
        isError: true,
      };
    }
  }

  listTools(): ToolDefinition[] {
    return this.registry.getAllToolDefinitions();
  }

  hasTools(): boolean {
    return this.registry.getAllToolDefinitions().length > 0;
  }

  getToolCount(): number {
    return this.registry.getAllToolDefinitions().length;
  }
}

